import { z } from 'zod';
import { createEndpoint, RecruitmentRows, Tasks, BoardColumns, CellValues, Boards, CalendarEvents } from 'zite-integrations-backend-sdk';
import { resolveBoardId } from '../serverUtils/resolveBoardId';

const sleep = (ms: number) => new Promise(r => setTimeout(r, ms));

const isUUID = (s: string) => /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(s);

// Retry a single operation with exponential backoff on rate-limit errors
async function withRetry<T>(fn: () => Promise<T>, attempts = 4): Promise<T> {
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn();
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      const isRateLimit = msg.toLowerCase().includes('too many') || msg.toLowerCase().includes('rate');
      if (!isRateLimit || i === attempts - 1) throw err;
      await sleep(600 * Math.pow(2, i));
    }
  }
  throw new Error('Max retries exceeded');
}

// Smaller batch size (5) with longer pauses to avoid rate limits
async function softDeleteBatch(ids: string[], updater: (id: string) => Promise<unknown>) {
  for (let i = 0; i < ids.length; i += 5) {
    await Promise.all(ids.slice(i, i + 5).map(id => withRetry(() => updater(id))));
    if (i + 5 < ids.length) await sleep(400);
  }
}

export default createEndpoint({
  authenticated: true,
  description: 'Soft-delete a board (tasks, rows, columns, cells, and the board record itself). UUID-safe: when boardId is a UUID, operates exclusively by that UUID with no name-based fallback.',
  inputSchema: z.object({
    boardId: z.string(),
    boardName: z.string(),
    projectCode: z.string(),
    boardType: z.string().optional(),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    const now = new Date().toISOString();
    const u = context.user;
    const deletedBy = [u.firstName, u.lastName].filter(Boolean).join(' ') || u.email;

    // ════════════════════════════════════════════════════════════════════════
    // UUID PATH — operate exclusively by UUID, no name-based queries ever
    // ════════════════════════════════════════════════════════════════════════
    if (isUUID(input.boardId)) {
      const uuid = input.boardId;
      const boardIdVariants = [uuid, `${uuid}::groups`, `${uuid}::children`];

      // ── 1. Fetch entities by UUID ──────────────────────────────────────
      const [rowsResult, tasksResult] = await Promise.all([
        RecruitmentRows.findAll({ filters: { boardId: uuid } as any, fields: ['id'], limit: 2000 }),
        Tasks.findAll({ filters: { boardId: uuid } as any, fields: ['id'], limit: 2000 }),
      ]);

      const [colResults, cellResults] = await Promise.all([
        Promise.all(boardIdVariants.map(bid =>
          BoardColumns.findAll({ filters: { boardId: bid }, fields: ['id'], limit: 2000 })
        )),
        Promise.all(boardIdVariants.map(bid =>
          CellValues.findAll({ filters: { boardId: bid }, fields: ['id'], limit: 2000 })
        )),
      ]);

      const allColIds = colResults.flatMap(r => r.records.map(c => c.id));
      const allCellIds = cellResults.flatMap(r => r.records.map(c => c.id));

      // ── 2. Soft-delete recruitment rows ────────────────────────────────
      await softDeleteBatch(rowsResult.records.map(r => r.id), id =>
        RecruitmentRows.update({ id, record: { deletedAt: now } })
      );
      await sleep(300);

      // ── 3. Hard-delete tasks ───────────────────────────────────────────
      await softDeleteBatch(tasksResult.records.map(r => r.id), id =>
        Tasks.delete({ id })
      );
      await sleep(300);

      // ── 4. Hard-delete CalendarEvents by boardId UUID ──────────────────
      if (input.boardType === 'calendar' || input.boardId.startsWith('cal-')) {
        const { records: calEvents } = await CalendarEvents.findAll({
          filters: { boardId: uuid } as any,
          fields: ['id'],
          limit: 2000,
        });
        if (calEvents.length > 0) {
          await softDeleteBatch(calEvents.map(e => e.id), id =>
            CalendarEvents.delete({ id })
          );
          await sleep(300);
        }
      }

      // ── 5. Soft-delete columns ─────────────────────────────────────────
      if (allColIds.length > 0) {
        await softDeleteBatch(allColIds, id =>
          BoardColumns.update({ id, record: { deletedAt: now, deletedBy } })
        );
        await sleep(500);
      }

      // ── 6. Soft-delete cells ───────────────────────────────────────────
      if (allCellIds.length > 0) {
        await softDeleteBatch(allCellIds, id =>
          CellValues.update({ id, record: { deletedAt: now } })
        );
      }

      // ── 7. Soft-delete the board record itself — ONLY this UUID ────────
      await withRetry(() => Boards.update({ id: uuid, record: { deletedAt: now } }));

      return { success: true };
    }

    // ════════════════════════════════════════════════════════════════════════
    // LEGACY PATH — input.boardId is a composite like "pm-PROJECT-BOARD"
    // ════════════════════════════════════════════════════════════════════════

    // ── 1. Resolve board to get both UUID and legacy IDs ────────────────
    let resolved: { baseBoardId: string; legacyBaseId: string; boardId?: string; legacyCompositeId?: string };
    try {
      resolved = await resolveBoardId({
        boardIdOrKey: input.boardId,
        projectCode: input.projectCode,
        boardName: input.boardName,
        fallbackToLegacy: true,
      });
    } catch {
      resolved = { baseBoardId: input.boardId, legacyBaseId: input.boardId };
    }

    // ── 2. Build deduplicated set of all boardId variants to clean ───────
    const boardIdSet = new Set<string>([
      input.boardId,
      resolved.baseBoardId,
      resolved.legacyBaseId,
      `${resolved.baseBoardId}::groups`,
      `${resolved.baseBoardId}::children`,
      `${resolved.legacyBaseId}::groups`,
      `${resolved.legacyBaseId}::children`,
    ]);
    if (resolved.boardId) boardIdSet.add(resolved.boardId);
    if (resolved.legacyCompositeId) boardIdSet.add(resolved.legacyCompositeId);

    const boardIdsToClean = [...boardIdSet];

    // ── 3. Fetch all IDs to soft-delete ─────────────────────────────────
    const boardsFilter: Record<string, string> = {
      boardName: input.boardName,
      projectCode: input.projectCode,
    };
    if (input.boardType) boardsFilter.boardType = input.boardType;

    const [rowsResult, tasksResult, boardsResult] = await Promise.all([
      RecruitmentRows.findAll({
        filters: { boardName: input.boardName, projectCode: input.projectCode },
        fields: ['id'],
        limit: 2000,
      }),
      Tasks.findAll({
        filters: { boardName: input.boardName, projectCode: input.projectCode },
        fields: ['id'],
        limit: 2000,
      }),
      Boards.findAll({
        filters: boardsFilter as any,
        fields: ['id'],
        limit: 10,
      }),
    ]);

    const [colResults, cellResults] = await Promise.all([
      Promise.all(
        boardIdsToClean.map(bid =>
          BoardColumns.findAll({ filters: { boardId: bid }, fields: ['id'], limit: 2000 })
        )
      ),
      Promise.all(
        boardIdsToClean.map(bid =>
          CellValues.findAll({ filters: { boardId: bid }, fields: ['id'], limit: 2000 })
        )
      ),
    ]);

    const allColIds = colResults.flatMap(r => r.records.map(c => c.id));
    const allCellIds = cellResults.flatMap(r => r.records.map(c => c.id));

    // ── 4. Soft-delete recruitment rows ─────────────────────────────────
    await softDeleteBatch(rowsResult.records.map(r => r.id), id =>
      RecruitmentRows.update({ id, record: { deletedAt: now } })
    );
    await sleep(300);

    // ── 5. Hard-delete tasks ────────────────────────────────────────────
    await softDeleteBatch(tasksResult.records.map(r => r.id), id =>
      Tasks.delete({ id })
    );
    await sleep(300);

    // ── 6. If calendar board, hard-delete CalendarEvents (UUID-safe) ───
    if (input.boardType === 'calendar' || input.boardId.startsWith('cal-')) {
      // Find exactly which Board UUID matches this legacy deletion
      const activeBoardRecords = boardsResult.records.filter(b => !b.deletedAt);
      if (activeBoardRecords.length === 1) {
        // Unambiguous — safe to delete CalendarEvents by that board's UUID
        const matchedBoardUUID = activeBoardRecords[0].id;
        const { records: calEvents } = await CalendarEvents.findAll({
          filters: { boardId: matchedBoardUUID } as any,
          fields: ['id'],
          limit: 2000,
        });
        if (calEvents.length > 0) {
          await softDeleteBatch(calEvents.map(e => e.id), id =>
            CalendarEvents.delete({ id })
          );
          await sleep(300);
        }
      } else if (activeBoardRecords.length > 1) {
        console.warn(`[deleteBoard] Ambiguous: ${activeBoardRecords.length} active boards match name "${input.boardName}", skipping CalendarEvents deletion`);
      }
      // 0 matches → skip, nothing to delete
    }

    // ── 7. Soft-delete columns ──────────────────────────────────────────
    if (allColIds.length > 0) {
      await softDeleteBatch(allColIds, id =>
        BoardColumns.update({ id, record: { deletedAt: now, deletedBy } })
      );
      await sleep(500);
    }

    // ── 8. Soft-delete cells ────────────────────────────────────────────
    if (allCellIds.length > 0) {
      await softDeleteBatch(allCellIds, id =>
        CellValues.update({ id, record: { deletedAt: now } })
      );
    }

    // ── 9. Soft-delete the board record — only ONE if multiple match ────
    const activeBoardRecords = boardsResult.records.filter(b => !b.deletedAt);
    if (activeBoardRecords.length > 0) {
      // Only delete the first match, not all — prevents mass deletion of same-named boards
      await withRetry(() => Boards.update({ id: activeBoardRecords[0].id, record: { deletedAt: now } }));
    }

    return { success: true };
  },
});

src/api/fixCellData.ts.content:
import { z } from 'zod';
import { createEndpoint, RecruitmentRows, CellValues } from 'zite-integrations-backend-sdk';

/**
 * ONE-TIME REPAIR ENDPOINT
 * Re-denormalizes CellValues back into the cellData field of RecruitmentRows.
 * Run this after the rate-limit storm that corrupted/cleared cellData.
 *
 * Strategy:
 * 1. Page through all RecruitmentRows to find unique (projectCode, boardName) combos.
 * 2. For each unique boardId, fetch all CellValues in one paginated pass.
 * 3. Group CellValues by rowId → rebuild cellData JSON per row.
 * 4. Update each RecruitmentRow in serial batches of 20.
 */
export default createEndpoint({
  authenticated: true,
  description: 'One-time repair: rebuilds cellData on RecruitmentRows from CellValues table.',
  inputSchema: z.object({
    projectCode: z.string().optional(), // limit to one project for safety
    dryRun: z.boolean().optional(),     // if true, only count affected rows
  }),
  outputSchema: z.object({
    rowsScanned: z.number(),
    rowsUpdated: z.number(),
    rowsSkipped: z.number(),
    boardIds: z.array(z.string()),
    cellValuesLoaded: z.number(),
    dryRun: z.boolean(),
    errors: z.number(),
  }),
  execute: async ({ input, context }) => {
    // Only admins
    if (context.user!.role !== 'Owner' && context.user!.role !== 'Socio') {
      throw new Error('Solo administradores pueden ejecutar esta reparación');
    }

    const dryRun = input.dryRun ?? false;

    // ── Step 1: Fetch all RecruitmentRows (paginated) ─────────────────────
    const allRows: Array<{ id: string; projectCode?: string; boardName?: string; cellData?: string }> = [];
    let offset = 0;
    while (true) {
      const filters: Record<string, unknown> = {};
      if (input.projectCode) filters.projectCode = input.projectCode;
      const { records, hasMore } = await RecruitmentRows.findAll({
        filters,
        limit: 2000,
        offset,
        fields: ['id', 'projectCode', 'boardName', 'cellData', 'deletedAt'],
      });
      // Only active rows
      allRows.push(...records.filter(r => !(r as any).deletedAt));
      if (!hasMore) break;
      offset += records.length;
    }

    // ── Step 2: Collect unique boardIds ───────────────────────────────────
    const boardIdSet = new Set<string>();
    for (const r of allRows) {
      if (r.projectCode && r.boardName) {
        boardIdSet.add(`recruitment-${r.projectCode}-${r.boardName}`);
      }
    }
    const boardIds = [...boardIdSet];

    // ── Step 3: Load all CellValues for each boardId ──────────────────────
    // Map: rowId → { columnId → { textValue, numberValue, ... } }
    const cellsByRow = new Map<string, Record<string, Record<string, unknown>>>();
    let totalCellsLoaded = 0;

    for (const boardId of boardIds) {
      let cellOffset = 0;
      while (true) {
        const { records: cells, hasMore } = await CellValues.findAll({
          filters: { boardId },
          limit: 2000,
          offset: cellOffset,
        });
        totalCellsLoaded += cells.length;
        for (const cell of cells) {
          if (!cell.rowId || !cell.columnId) continue;
          if (!cellsByRow.has(cell.rowId)) cellsByRow.set(cell.rowId, {});
          const rowCells = cellsByRow.get(cell.rowId)!;
          // Only store defined non-empty values
          const val: Record<string, unknown> = {};
          if (cell.textValue    !== undefined && cell.textValue    !== null && cell.textValue    !== '') val.textValue    = cell.textValue;
          if (cell.numberValue  !== undefined && cell.numberValue  !== null) val.numberValue  = cell.numberValue;
          if (cell.dateValue    !== undefined && cell.dateValue    !== null && cell.dateValue    !== '') val.dateValue    = cell.dateValue;
          if (cell.booleanValue !== undefined && cell.booleanValue !== null) val.booleanValue = cell.booleanValue;
          if (cell.fileUrl      !== undefined && cell.fileUrl      !== null && cell.fileUrl      !== '') val.fileUrl      = cell.fileUrl;
          if (Object.keys(val).length > 0) {
            rowCells[cell.columnId] = val;
          }
        }
        if (!hasMore) break;
        cellOffset += cells.length;
        // Small pause between pages to avoid rate limits
        await new Promise(r => setTimeout(r, 100));
      }
    }

    // ── Step 4: Update each row with reconstructed cellData ───────────────
    let rowsUpdated = 0;
    let rowsSkipped = 0;
    let errors = 0;

    const BATCH_SIZE = 20;
    for (let i = 0; i < allRows.length; i += BATCH_SIZE) {
      const batch = allRows.slice(i, i + BATCH_SIZE);

      await Promise.all(batch.map(async (row) => {
        const cells = cellsByRow.get(row.id) ?? {};
        const newCellData = JSON.stringify(cells);

        // Skip if cellData is already correct (avoid unnecessary writes)
        if (row.cellData === newCellData) {
          rowsSkipped++;
          return;
        }
        // Skip rows with no cells and already empty cellData
        if (Object.keys(cells).length === 0 && (!row.cellData || row.cellData === '{}' || row.cellData === 'null')) {
          rowsSkipped++;
          return;
        }

        if (dryRun) {
          rowsUpdated++;
          return;
        }

        try {
          await RecruitmentRows.update({ id: row.id, record: { cellData: newCellData } });
          rowsUpdated++;
        } catch {
          errors++;
        }
      }));

      // Small pause between batches
      if (i + BATCH_SIZE < allRows.length) {
        await new Promise(r => setTimeout(r, 150));
      }
    }

    return {
      rowsScanned: allRows.length,
      rowsUpdated,
      rowsSkipped,
      boardIds,
      cellValuesLoaded: totalCellsLoaded,
      dryRun,
      errors,
    };
  },
});

