import { z } from 'zod';
import { createEndpoint, Expenses, ExpenseLineItems } from 'zite-integrations-backend-sdk';

const expenseOut = z.object({
  id: z.string(),
  expenseNumber: z.number().optional().nullable(),
  description: z.string().optional().nullable(),
  amount: z.number().optional().nullable(),
  category: z.string().optional().nullable(),
  paymentMethod: z.string().optional().nullable(),
  costCenter: z.string().optional().nullable(),
  projectCode: z.string().optional().nullable(),
  currency: z.string().optional().nullable(),
  expenseDate: z.string().optional().nullable(),
  status: z.string().optional().nullable(),
  receipt: z.array(z.object({ url: z.string() })).optional().nullable(),
  notes: z.string().optional().nullable(),
  createdBy: z.string().optional().nullable(),
  approvedBy: z.string().optional().nullable(),
  rejectionReason: z.string().optional().nullable(),
  pettyCashFundId: z.string().optional().nullable(),
  createdAt: z.string().optional().nullable(),
  lineItemCount: z.number(),
});

export default createEndpoint({
  authenticated: true,
  description: 'Get expenses with optional filters',
  inputSchema: z.object({
    status: z.string().optional(),
    category: z.string().optional(),
    paymentMethod: z.string().optional(),
    costCenter: z.string().optional(),
    dateFrom: z.string().optional(),
    dateTo: z.string().optional(),
  }),
  outputSchema: z.object({
    expenses: z.array(expenseOut),
    isFinanceUser: z.boolean(),
  }),
  execute: async ({ input, context }) => {
    const isFinance = ['Finanzas', 'Admin', 'Admin Financiero'].includes(context.user!.role ?? '');

    const filters: Record<string, unknown> = {};
    if (input.status) filters.status = input.status;
    if (input.category) filters.category = input.category;
    if (input.paymentMethod) filters.paymentMethod = input.paymentMethod;
    if (input.costCenter) filters.costCenter = input.costCenter;
    if (!isFinance) filters.createdBy = context.user!.email;

    const { records } = await Expenses.findAll({ filters: filters as never, limit: 500 });

    let expenses = records;
    if (input.dateFrom || input.dateTo) {
      expenses = records.filter(e => {
        if (!e.expenseDate) return true;
        if (input.dateFrom && e.expenseDate < input.dateFrom) return false;
        if (input.dateTo && e.expenseDate > input.dateTo) return false;
        return true;
      });
    }

    expenses.sort((a, b) => (b.createdAt ?? '').localeCompare(a.createdAt ?? ''));

    // Batch fetch line item counts
    const lineCountMap: Record<string, number> = {};
    try {
      const { records: liRecords } = await ExpenseLineItems.findAll({
        limit: 2000,
        fields: ['expense'],
      });
      for (const li of liRecords) {
        const expId = Array.isArray(li.expense) ? li.expense[0] : li.expense;
        if (expId && typeof expId === 'string') {
          lineCountMap[expId] = (lineCountMap[expId] ?? 0) + 1;
        }
      }
    } catch {
      // non-critical — fallback to 0 counts
    }

    return {
      expenses: expenses.map(e => {
        const fund = e.pettyCashFund;
        const fundId = Array.isArray(fund) ? (fund[0] ?? null) : (fund ? String(fund) : null);
        return {
          id: e.id,
          expenseNumber: typeof e.expenseNumber === 'number' ? e.expenseNumber : null,
          description: e.description ?? null,
          amount: e.amount ?? null,
          category: e.category ?? null,
          paymentMethod: e.paymentMethod ?? null,
          costCenter: e.costCenter ?? null,
          projectCode: e.projectCode ?? null,
          currency: e.currency ?? null,
          expenseDate: e.expenseDate ?? null,
          status: e.status ?? null,
          receipt: (e.receipt as { url: string }[] | undefined) ?? null,
          notes: e.notes ?? null,
          createdBy: e.createdBy ?? null,
          approvedBy: e.approvedBy ?? null,
          rejectionReason: e.rejectionReason ?? null,
          pettyCashFundId: fundId,
          createdAt: e.createdAt ?? null,
          lineItemCount: lineCountMap[e.id] ?? 0,
        };
      }),
      isFinanceUser: isFinance,
    };
  },
});

src/api/getMessages.ts.content:
import { z } from 'zod';
import { createEndpoint, Messages, ChatConversations } from 'zite-integrations-backend-sdk';
import { parseMembers } from '../lib/chatJson';

const sanitize = (r: Awaited<ReturnType<typeof Messages.findAll>>['records'][0]) => ({
  ...r,
  pinned: r.pinned ?? false,
  parentMessageId: r.parentMessageId ?? undefined,
  reactions: r.reactions ?? undefined,
  attachments: r.attachments ?? undefined,
});

export default createEndpoint({
  description: 'Get messages for a channel (including replies)',
  authenticated: true,
  inputSchema: z.object({
    channel: z.string(),
    limit: z.number().optional(),
    since: z.string().optional(),
  }),
  outputSchema: z.object({
    messages: z.array(z.object({
      id: z.string(),
      messageId: z.any().optional(),
      channel: z.string().optional(),
      senderName: z.string().optional(),
      senderEmail: z.string().optional(),
      content: z.string().optional(),
      sentAt: z.string().optional(),
      parentMessageId: z.string().optional(),
      reactions: z.string().optional(),
      pinned: z.boolean().optional(),
      attachments: z.string().optional(),
    })),
  }),
  execute: async ({ input, context }) => {
    // Check if this channel is a DM/group conversation (not "general" or a project code)
    if (input.channel !== 'general') {
      try {
        const conv = await ChatConversations.findOne({ id: input.channel });
        if (conv) {
          // It's a conversation record — verify the user is a member
          const members: string[] = parseMembers(conv.members);
          if (!members.includes(context.user!.email)) {
            return { messages: [] };
          }
        }
        // If conv is undefined → not found, treat as regular project channel, allow access
      } catch {
        // Error looking up → treat as regular project channel, allow access
      }
    }

    // Incremental fetch: only messages newer than `since`
    if (input.since) {
      const { records } = await Messages.findAll({
        filters: { channel: input.channel, sentAt: { gt: new Date(input.since) } },
      });
      return {
        messages: records
          .map(sanitize)
          .sort((a, b) =>
            new Date(a.sentAt ?? 0).getTime() - new Date(b.sentAt ?? 0).getTime()
          ),
      };
    }

    // Full fetch (initial load): get all messages, sort ascending, keep only the LAST N
    // This ensures we always show the most recent messages, not the oldest ones.
    const limit = input.limit ?? 60;
    const { records } = await Messages.findAll({
      filters: { channel: input.channel },
      limit: 2000,
    });

    const sorted = records
      .map(sanitize)
      .sort((a, b) =>
        new Date(a.sentAt ?? 0).getTime() - new Date(b.sentAt ?? 0).getTime()
      );

    // Slice to keep only the most recent `limit` messages
    const recent = sorted.length > limit ? sorted.slice(sorted.length - limit) : sorted;

    return { messages: recent };
  },
});

src/api/getPayments.ts.content:
import { z } from 'zod';
import { createEndpoint, Payments, PurchaseOrders, Suppliers, BillingEntities } from 'zite-integrations-backend-sdk';

const paymentSchema = z.object({
  id: z.string(),
  paymentId: z.any().optional(),
  poId: z.string().optional(),
  poNumber: z.string().optional(),
  projectCode: z.string().optional(),
  supplierName: z.string().optional(),
  supplierEmail: z.string().optional(),
  amount: z.number().optional(),
  currency: z.string().optional(),
  paymentDate: z.string().optional(),
  dueDate: z.string().optional(),
  method: z.string().optional(),
  reference: z.string().optional(),
  status: z.string().optional(),
  notes: z.string().optional(),
  supplierInvoiceNumber: z.string().optional(),
  destinationAccount: z.string().optional(),
  sourceCompany: z.string().optional(),
  sourceBank: z.string().optional(),
  sourceAccount: z.string().optional(),
  attachment: z.array(z.object({ url: z.string() })).optional(),
  poTotalAmount: z.number().optional(),
  poPendingAmount: z.number().optional(),
});

const poOptionSchema = z.object({
  id: z.string(),
  poNumber: z.string(),
  supplierName: z.string(),
  projectCode: z.string(),
  totalAmount: z.number(),
  pendingAmount: z.number(),
  billingEntity: z.string().optional(),
});

const billingEntityOptionSchema = z.object({
  id: z.string(),
  companyName: z.string(),
});

const delay = (ms: number) => new Promise(r => setTimeout(r, ms));

export default createEndpoint({
  authenticated: true,
  description: 'Get payments to suppliers with enriched PO data and billing entity options',
  inputSchema: z.object({
    status: z.string().optional(),
    supplierName: z.string().optional(),
    projectCode: z.string().optional(),
  }),
  outputSchema: z.object({
    payments: z.array(paymentSchema),
    poOptions: z.array(poOptionSchema),
    billingEntityOptions: z.array(billingEntityOptionSchema),
  }),
  execute: async ({ input }) => {
    // Step 1: Fetch payments
    const paymentsResult = await Payments.findAll({ filters: { type: 'Pago a proveedor' }, limit: 500 });

    // Small delay between DB calls to avoid rate limiting
    await delay(150);

    // Step 2: Fetch referenced POs (sequential batches with delays)
    const uniquePoIds = [...new Set(paymentsResult.records.map(p => p.poId).filter(Boolean))] as string[];
    let referencedPOs: Awaited<ReturnType<typeof PurchaseOrders.findAll>>['records'] = [];
    if (uniquePoIds.length > 0) {
      const BATCH = 100;
      for (let i = 0; i < uniquePoIds.length; i += BATCH) {
        if (i > 0) await delay(200);
        const batch = uniquePoIds.slice(i, i + BATCH);
        const result = await PurchaseOrders.findAll({
          filters: { id: { in: batch } },
          limit: BATCH,
        });
        referencedPOs = [...referencedPOs, ...result.records];
      }
    }

    await delay(150);

    // Step 3: Fetch suppliers
    const suppliersResult = await Suppliers.findAll({ limit: 500 });

    await delay(150);

    // Step 4: Fetch billing entities
    const billingEntitiesResult = await BillingEntities.findAll({ limit: 200 });

    await delay(150);

    // Step 5: Fetch approved POs for form options (reduced limit)
    const approvedPosResult = await PurchaseOrders.findAll({
      filters: { status: { in: ['Aprobada', 'Enviada a aprobación'] } },
      limit: 500,
    });

    // Build supplier email map
    const supplierEmailMap: Record<string, string> = {};
    suppliersResult.records.forEach(s => {
      if (s.supplierName && s.email) supplierEmailMap[s.supplierName] = s.email;
    });

    // Build PO lookup map
    const poMap: Record<string, { poNumber: string; supplierName: string; projectCode: string; totalAmount: number; billingEntity?: string }> = {};
    referencedPOs.forEach(po => {
      poMap[po.id] = {
        poNumber: String(po.poNumber ?? ''),
        supplierName: po.supplierName ?? '',
        projectCode: po.projectCode ?? '',
        totalAmount: po.totalAmount ?? 0,
        billingEntity: po.billingEntity ?? undefined,
      };
    });

    // Calculate paid amount per PO
    const paidPerPo: Record<string, number> = {};
    paymentsResult.records.forEach(p => {
      if (p.poId && p.status === 'Realizado') {
        paidPerPo[p.poId] = (paidPerPo[p.poId] ?? 0) + (p.amount ?? 0);
      }
    });

    // Enrich payments
    let payments = paymentsResult.records.map(p => {
      const po = p.poId ? poMap[p.poId] : undefined;
      const poTotal = po?.totalAmount ?? 0;
      const paid = p.poId ? (paidPerPo[p.poId] ?? 0) : 0;
      const resolvedSupplierName = p.supplierName ?? po?.supplierName;
      return {
        id: p.id,
        paymentId: p.paymentId,
        poId: p.poId,
        poNumber: po?.poNumber,
        projectCode: p.projectCode ?? po?.projectCode,
        supplierName: resolvedSupplierName,
        supplierEmail: resolvedSupplierName ? supplierEmailMap[resolvedSupplierName] : undefined,
        amount: p.amount,
        currency: p.currency,
        paymentDate: p.paymentDate,
        dueDate: p.dueDate,
        method: p.method,
        reference: p.reference,
        status: p.status,
        notes: p.notes,
        supplierInvoiceNumber: p.supplierInvoiceNumber,
        destinationAccount: p.destinationAccount,
        sourceCompany: p.sourceCompany ?? (p.poId ? poMap[p.poId]?.billingEntity : undefined),
        sourceBank: p.sourceBank,
        sourceAccount: p.sourceAccount,
        attachment: p.attachment,
        poTotalAmount: poTotal,
        poPendingAmount: Math.max(0, poTotal - paid),
      };
    });

    // Apply filters
    if (input.status) payments = payments.filter(p => p.status === input.status);
    if (input.supplierName) payments = payments.filter(p => p.supplierName?.toLowerCase().includes(input.supplierName!.toLowerCase()));
    if (input.projectCode) payments = payments.filter(p => p.projectCode === input.projectCode);

    // Build PO options
    const poOptions = approvedPosResult.records.map(po => ({
      id: po.id,
      poNumber: String(po.poNumber ?? ''),
      supplierName: po.supplierName ?? '',
      projectCode: po.projectCode ?? '',
      totalAmount: po.totalAmount ?? 0,
      pendingAmount: Math.max(0, (po.totalAmount ?? 0) - (paidPerPo[po.id] ?? 0)),
      billingEntity: po.billingEntity ?? undefined,
    }));

    // Build billing entity options
    const billingEntityOptions = billingEntitiesResult.records.map(b => ({
      id: b.id,
      companyName: b.companyName ?? '',
    })).filter(b => b.companyName);

    return { payments, poOptions, billingEntityOptions };
  },
});

src/api/getPresence.ts.content:
import { z } from 'zod';
import { createEndpoint, Users } from 'zite-integrations-backend-sdk';

const ACTIVE_WINDOW_MS = 5 * 60 * 1000;   // 5 min — for activeEmails compat
const PRESENCE_WINDOW_MS = 30 * 60 * 1000; // 30 min — for granular status

export default createEndpoint({
  authenticated: true,
  description: 'Returns presence data for users active in the last 30 minutes',
  inputSchema: z.object({}),
  outputSchema: z.object({
    activeEmails: z.array(z.string()),
    users: z.array(z.object({
      email: z.string(),
      firstName: z.string().optional(),
      lastName: z.string().optional(),
      profilePhoto: z.string().optional(),
      lastSeenAt: z.string().optional(),
      activeChannel: z.string().nullable().optional(),
    })),
  }),
  execute: async () => {
    const cutoff30 = new Date(Date.now() - PRESENCE_WINDOW_MS).toISOString();
    const cutoff5  = new Date(Date.now() - ACTIVE_WINDOW_MS).toISOString();

    const { records } = await Users.findAll({
      filters: { lastActiveAt: { gt: new Date(cutoff30) } },
      fields: ['email', 'lastActiveAt', 'activeChannel', 'firstName', 'lastName', 'profilePhoto'],
    });

    const r = records as Array<Record<string, unknown>>;

    const users = r
      .filter(rec => rec.email && rec.lastActiveAt)
      .map(rec => ({
        email: rec.email as string,
        firstName: rec.firstName as string | undefined,
        lastName: rec.lastName as string | undefined,
        profilePhoto: rec.profilePhoto as string | undefined,
        lastSeenAt: rec.lastActiveAt as string,
        activeChannel: rec.activeChannel as string | null ?? null,
      }));

    const activeEmails = users
      .filter(u => u.lastSeenAt > cutoff5)
      .map(u => u.email);

    return { activeEmails, users };
  },
});

src/api/getProjects.ts.content:
import { z } from 'zod';
import { createEndpoint, Projects, Tasks, CalendarEvents } from 'zite-integrations-backend-sdk';

const linkedField = z.union([z.string(), z.array(z.string())]).optional();

const projectSchema = z.object({
  id: z.string(),
  projectCode: z.string().optional(),
  fullName: z.string().optional(),
  status: z.string().optional(),
  client: z.string().optional(),
  tematica: z.string().optional(),
  startDate: z.string().optional(),
  endDate: z.string().optional(),
  description: z.string().optional(),
  timelineStatus: z.string().optional(),
  timelineUrl: z.string().optional(),
  timelineUpdatedAt: z.string().optional(),
  teamsChannelUrl: z.string().optional(),
  teamsChannelStatus: z.string().optional(),
  computedStartDate: z.string().optional(),
  computedEndDate: z.string().optional(),
  lider: linkedField,
  analistas: linkedField,
  moderadores: linkedField,
  asistentes: linkedField,
  muestra: z.string().optional(),
  muestraImagen: z.string().optional(),
});

export default createEndpoint({
  authenticated: true,
  description: 'Get all projects with auto-detected start/end dates from tasks and calendar events',
  inputSchema: z.object({ search: z.string().optional() }),
  outputSchema: z.object({ projects: z.array(projectSchema) }),
  execute: async ({ input }) => {
    // Fetch projects, tasks, and events in parallel — minimal fields on all three
    const [{ records: projects }, { records: tasks }, { records: events }] = await Promise.all([
      Projects.findAll({
        limit: 500,
        fields: [
          'projectCode', 'fullName', 'status', 'client', 'tematica',
          'startDate', 'endDate', 'description',
          'timelineStatus', 'timelineUrl', 'timelineUpdatedAt',
          'teamsChannelUrl', 'teamsChannelStatus',
          'lider', 'analistas', 'moderadores', 'asistentes', 'muestra', 'muestraImagen',
        ],
      }),
      Tasks.findAll({ limit: 1000, fields: ['projectCode', 'startDate', 'endDate'] }),
      CalendarEvents.findAll({ limit: 500, fields: ['projectCode', 'eventDate'] }),
    ]);

    // Build min/max date maps per projectCode from native task fields only
    const minMap = new Map<string, string>();
    const maxMap = new Map<string, string>();

    const updateMin = (code: string, d: string) => {
      const ex = minMap.get(code); if (!ex || d < ex) minMap.set(code, d);
    };
    const updateMax = (code: string, d: string) => {
      const ex = maxMap.get(code); if (!ex || d > ex) maxMap.set(code, d);
    };

    for (const t of tasks) {
      if (!t.projectCode) continue;
      const start = t.startDate?.split('T')[0];
      const end   = t.endDate?.split('T')[0];
      if (start) updateMin(t.projectCode, start);
      if (end)   updateMax(t.projectCode, end);
    }

    for (const ev of events) {
      if (!ev.projectCode || !ev.eventDate) continue;
      const d = ev.eventDate.split('T')[0];
      if (d) { updateMin(ev.projectCode, d); updateMax(ev.projectCode, d); }
    }

    const filtered = input.search
      ? projects.filter(r =>
          r.projectCode?.toLowerCase().includes(input.search!.toLowerCase()) ||
          r.fullName?.toLowerCase().includes(input.search!.toLowerCase()) ||
          r.client?.toLowerCase().includes(input.search!.toLowerCase())
        )
      : projects;

    return {
      projects: filtered.map(p => ({
        ...p,
        startDate: p.startDate?.split('T')[0],
        endDate:   p.endDate?.split('T')[0],
        computedStartDate: p.projectCode ? minMap.get(p.projectCode) : undefined,
        computedEndDate:   p.projectCode ? maxMap.get(p.projectCode) : undefined,
        lider: p.lider,
        analistas: p.analistas,
        moderadores: p.moderadores,
        asistentes: p.asistentes,
        muestra: (p as any).muestra,
        muestraImagen: (p as any).muestraImagen,
      })),
    };
  },
});

src/api/getTaskById.ts.content:
import { z } from 'zod';
import { createEndpoint, Tasks } from 'zite-integrations-backend-sdk';

const taskSchema = z.object({
  id: z.string(),
  taskName: z.string().optional(),
  projectCode: z.string().optional(),
  boardName: z.string().optional(),
  boardId: z.string().optional(),
  status: z.string().optional(),
  assignedTo: z.string().optional(),
  startDate: z.string().optional(),
  endDate: z.string().optional(),
  parentTaskId: z.string().optional(),
  order: z.number().optional(),
  notes: z.string().optional(),
});

export default createEndpoint({
  authenticated: true,
  description: 'Get a single task by ID for realtime surgical updates',
  inputSchema: z.object({
    id: z.string(),
  }),
  outputSchema: z.object({
    task: taskSchema.nullable(),
  }),
  execute: async ({ input }) => {
    const record = await Tasks.findOne({
      id: input.id,
      fields: ['taskName', 'projectCode', 'boardName', 'boardId', 'status', 'assignedTo', 'startDate', 'endDate', 'parentTaskId', 'order', 'notes'],
    });

    if (!record) {
      return { task: null };
    }

    return {
      task: {
        id: record.id,
        taskName: record.taskName,
        projectCode: record.projectCode,
        boardName: record.boardName,
        boardId: record.boardId,
        status: record.status,
        assignedTo: record.assignedTo,
        startDate: record.startDate,
        endDate: record.endDate,
        parentTaskId: record.parentTaskId,
        order: record.order,
        notes: record.notes,
      },
    };
  },
});

