const QUICK_EMOJIS = ['👍', '❤️', '😂', '🎉', '✅', '👀'];

const EMOJI_CATEGORIES: Record<string, string[]> = {
  'Caritas':  ['😀','😂','🥰','😎','🤩','😭','🥺','😤','🤯','🫡'],
  'Manos':    ['👍','👎','👏','🙌','💪','🤝','✌️','🫶','👋','🤙'],
