src/api/duplicateRows.ts.content:
import { z } from 'zod';
import { createEndpoint, RecruitmentRows, Tasks, CalendarEvents, CellValues } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Duplicate a list of rows (recruitment, task, or calendarEvent), copying all fields and dynamic column cell values',
  inputSchema: z.object({
    ids: z.array(z.string()),
    tableType: z.enum(['recruitment', 'task', 'calendarEvent']),
  }),
  outputSchema: z.object({
    createdIds: z.array(z.string()),
    count: z.number(),
  }),
  execute: async ({ input }) => {
    const { ids, tableType } = input;
    const createdIds: string[] = [];

    for (const id of ids) {
      if (tableType === 'recruitment') {
        const orig = await RecruitmentRows.findOne({ id });
        if (!orig) continue;
        const { id: _id, ...rest } = orig;
        const newRow = await RecruitmentRows.create({
          record: {
            ...rest,
            rowName: `${rest.rowName ?? 'Fila'} (copia)`,
            participantName: rest.participantName ? `${rest.participantName} (copia)` : rest.participantName,
          },
        });

        // Copy all dynamic cell values
        const { records: cells } = await CellValues.findAll({ filters: { rowId: id }, limit: 500 });
        for (let i = 0; i < cells.length; i += 50) {
          await CellValues.bulkCreate({
            records: cells.slice(i, i + 50).map(c => ({
              boardId: c.boardId,
              rowId: newRow.id,
              columnId: c.columnId,
              textValue: c.textValue,
              numberValue: c.numberValue,
              dateValue: c.dateValue,
              booleanValue: c.booleanValue,
              fileUrl: c.fileUrl,
            })),
          });
        }

        createdIds.push(newRow.id);
      } else if (tableType === 'calendarEvent') {
        const orig = await CalendarEvents.findOne({ id });
        if (!orig) continue;
        const { id: _id, ...rest } = orig;
        const newEvent = await CalendarEvents.create({
          record: {
            ...rest,
            eventName: `${rest.eventName ?? 'Evento'} (copia)`,
            // Strip Outlook-related fields
            outlookEventId: undefined,
            outlookEventLink: undefined,
            inviteBodyHtml: undefined,
            inviteStatus: undefined,
            inviteSent: undefined,
            inviteEmails: undefined,
          },
        });

        // Copy all dynamic cell values
        const { records: cells } = await CellValues.findAll({ filters: { rowId: id }, limit: 500 });
        for (let i = 0; i < cells.length; i += 50) {
          await CellValues.bulkCreate({
            records: cells.slice(i, i + 50).map(c => ({
              boardId: c.boardId,
              rowId: newEvent.id,
              columnId: c.columnId,
              textValue: c.textValue,
              numberValue: c.numberValue,
              dateValue: c.dateValue,
              booleanValue: c.booleanValue,
              fileUrl: c.fileUrl,
            })),
          });
        }

        createdIds.push(newEvent.id);
      } else {
        const orig = await Tasks.findOne({ id });
        if (!orig) continue;
        const { id: _id, ...rest } = orig;
        const newTask = await Tasks.create({
          record: { ...rest, taskName: `${rest.taskName ?? 'Tarea'} (copia)` },
        });

        // Copy all dynamic cell values
        const { records: cells } = await CellValues.findAll({ filters: { rowId: id }, limit: 500 });
        for (let i = 0; i < cells.length; i += 50) {
          await CellValues.bulkCreate({
            records: cells.slice(i, i + 50).map(c => ({
              boardId: c.boardId,
              rowId: newTask.id,
              columnId: c.columnId,
              textValue: c.textValue,
              numberValue: c.numberValue,
              dateValue: c.dateValue,
              booleanValue: c.booleanValue,
              fileUrl: c.fileUrl,
            })),
          });
        }

        createdIds.push(newTask.id);
      }
    }

    return { createdIds, count: createdIds.length };
  },
});

src/api/generatePoPdf.ts.content:
import { z } from 'zod';
import { createEndpoint, ZiteError, PurchaseOrders, PoLineItems, Suppliers, BillingEntities } from 'zite-integrations-backend-sdk';
import { publishEvent } from '../lib/ably';

export default createEndpoint({
  authenticated: true,
  description: 'Generate PDF for a purchase order via n8n webhook (Respond to Webhook)',
  inputSchema: z.object({ id: z.string() }),
  outputSchema: z.object({ success: z.boolean(), message: z.string(), pdfUrl: z.string().optional(), pdfBase64: z.string().optional() }),
  execute: async ({ input }) => {
    const webhookUrl = process.env.ZITE_N8N_ODC_WEBHOOK_URL;
    if (!webhookUrl) {
      throw new ZiteError({
        code: 'BAD_REQUEST',
        message: 'El webhook de PDF no está configurado. Agrega ZITE_N8N_ODC_WEBHOOK_URL en los secrets de la app.',
      });
    }

    const po = await PurchaseOrders.findOne({ id: input.id });
    if (!po) throw new ZiteError({ code: 'NOT_FOUND', message: 'OC no encontrada' });

    const [{ records: lineItems }, supplierResult, billingEntityResult] = await Promise.all([
      PoLineItems.findAll({ filters: { poId: input.id }, limit: 200 }),
      po.supplierName
        ? Suppliers.findOne({ filters: { supplierName: po.supplierName } })
        : Promise.resolve(undefined),
      po.billingEntity
        ? BillingEntities.findOne({ filters: { companyName: po.billingEntity } })
        : Promise.resolve(undefined),
    ]);

    const grandTotal = lineItems.reduce((sum, l) => sum + (l.total ?? 0), 0);

    const response = await fetch(webhookUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        po: {
          id: po.id,
          poNumber: String(po.poNumber ?? ''),
          projectCode: po.projectCode ?? '',
          supplierName: po.supplierName ?? '',
          issueDate: po.issueDate ?? '',
          totalAmount: po.totalAmount ?? 0,
          status: po.status ?? '',
          category: po.category ?? '',
          paymentTerms: po.paymentTerms ?? '',
          currency: po.currency ?? 'MXN',
          createdBy: po.createdBy ?? '',
          approvedBy: po.approvedBy ?? '',
          notes: po.notes ?? '',
          serviceDescription: po.serviceDescription ?? '',
          billingEntity: po.billingEntity ?? '',
        },
        supplier: {
          name: supplierResult?.supplierName ?? po.supplierName ?? '',
          rfc: supplierResult?.taxId ?? '',
          email: supplierResult?.email ?? '',
          phone: supplierResult?.phone ?? '',
          contactName: supplierResult?.contactName ?? '',
        },
        billingEntity: {
          companyName: billingEntityResult?.companyName ?? po.billingEntity ?? '',
          rfc: billingEntityResult?.rfc ?? '',
          address: billingEntityResult?.address ?? '',
          postalCode: billingEntityResult?.postalCode ?? '',
          city: billingEntityResult?.city ?? '',
          state: billingEntityResult?.state ?? '',
          fullAddress: [
            billingEntityResult?.address,
            billingEntityResult?.city,
            billingEntityResult?.state,
            billingEntityResult?.postalCode ? `CP. ${billingEntityResult.postalCode}` : '',
          ].filter(Boolean).join(', '),
        },
        lineItems: lineItems.map(l => ({
          description: l.description ?? '',
          quantity: l.quantity ?? 1,
          unitPrice: l.unitPrice ?? 0,
          total: l.total ?? 0,
          isNegative: (l.total ?? 0) < 0,
        })),
        grandTotal,
        grandTotalFormatted: new Intl.NumberFormat('es-MX', {
          style: 'currency',
          currency: po.currency === 'USD' ? 'USD' : 'MXN',
          maximumFractionDigits: 2,
        }).format(grandTotal),
      }),
    });

    let raw = await response.json() as unknown;
    const result = (Array.isArray(raw) ? raw[0] : raw) as Record<string, unknown>;

    if (result.success === false) {
      throw new ZiteError({
        code: 'INTERNAL_ERROR',
        message: (result.error as string) ?? 'n8n no pudo generar el PDF',
      });
    }

    const pdfUrl = (
      result.pdfUrl ?? result.pdf_url ?? result.url ?? result.fileUrl ?? result.webUrl ?? result.myField
    ) as string | undefined;

    const pdfBase64Check = result.pdfBase64 as string | undefined;

    if (!pdfUrl && !pdfBase64Check) {
      throw new ZiteError({
        code: 'INTERNAL_ERROR',
        message: `n8n respondió sin URL ni base64 de PDF. Campos recibidos: ${Object.keys(result).join(', ')}`,
      });
    }

    const pdfBase64 = result.pdfBase64 as string | undefined;

    if (pdfBase64) {
      console.log('pdfBase64 received from n8n, length:', pdfBase64.length);
    } else {
      console.log('No pdfBase64 in n8n response');
    }

    await PurchaseOrders.update({
      id: input.id,
      record: {
        ...(pdfUrl ? { pdfUrl } : {}),
        ...(pdfBase64 ? { pdfBase64 } : {}),
      },
    });

    try { await publishEvent('purchases:global', 'po.changed', { id: input.id, action: 'pdf_generated', timestamp: new Date().toISOString() }); } catch { /* silent */ }
    return { success: true, message: 'PDF generado correctamente', pdfUrl, pdfBase64: pdfBase64 ?? undefined };
  },
});

src/api/getCellValues.ts.content:
import { z } from 'zod';
import { createEndpoint, CellValues, Boards } from 'zite-integrations-backend-sdk';
import { resolveBoardId } from '../serverUtils/resolveBoardId';

const DEBUG =
  typeof process !== 'undefined' && process.env?.DEBUG_BOARD_RESOLUTION === 'true';

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const SUFFIXES_CV = ['::groups', '::children'] as const;

function extractSuffixCV(input: string): { base: string; suffix: string } {
  for (const s of SUFFIXES_CV) {
    if (input.endsWith(s)) return { base: input.slice(0, -s.length), suffix: s };
  }
  return { base: input, suffix: '' };
}

const cellSchema = z.object({
  id: z.string(),
  cellId: z.any().optional(),
  boardId: z.string().optional(),
  rowId: z.string().optional(),
  columnId: z.string().optional(),
  textValue: z.string().optional(),
  numberValue: z.number().optional(),
  dateValue: z.string().optional(),
  booleanValue: z.boolean().optional(),
  fileUrl: z.string().optional(),
});

export default createEndpoint({
  authenticated: true,
  description: 'Get cell values for a board — paginated so the first page returns immediately',
  inputSchema: z.object({
    boardId: z.string(),
    limit: z.number().optional(),
    offset: z.number().optional(),
  }),
  outputSchema: z.object({
    cells: z.array(cellSchema),
    hasMore: z.boolean(),
    nextOffset: z.number(),
  }),
  execute: async ({ input }) => {
    const limit  = input.limit  ?? 500;
    const offset = input.offset ?? 0;
    const originalBoardId = input.boardId;

    // ── Detect legacy composite board IDs ────────────────────────────────────
    // Legacy IDs (pm-X-Y, cal-X-Y, recruitment-X-Y, events-X-Y) may have been
    // migrated to UUID. The fast path would find straggler legacy cells and
    // return only those, missing the bulk of data under UUID. Skip it.
    const isLegacyComposite = /^(pm-|cal-|recruitment-|events-)/.test(
      originalBoardId.replace(/::groups$|::children$/, ''),
    );

    // ── NON-LEGACY PATH (UUID input) ──────────────────────────────────────────
    if (!isLegacyComposite) {
      const { base, suffix } = extractSuffixCV(originalBoardId);

      if (UUID_RE.test(base)) {
        const board = await Boards.findOne({ id: base });
        if (!board || board.deletedAt) {
          return { cells: [], hasMore: false, nextOffset: offset };
        }

        // ── MERGE-READ for recruitment and calendar boards ────────────────
        // These board types may have CellValues split across UUID and legacy
        // boardIds due to the migration. We read from both and deduplicate.
        const needsUuidMerge = board.boardType === 'recruitment' || board.boardType === 'calendar';

        if (needsUuidMerge) {
          const prefix = board.boardType === 'recruitment' ? 'recruitment-' : 'cal-';
          const legacyBase = `${prefix}${board.projectCode}-${board.boardName}`;
          const legacyId = suffix ? `${legacyBase}${suffix}` : legacyBase;
          const candidates = [originalBoardId];
          if (legacyId !== originalBoardId) candidates.push(legacyId);

          const seen = new Map<string, any>(); // key: rowId::columnId → cell record
          const seenIsUUID = new Map<string, boolean>(); // track source type

          for (const candidate of candidates) {
            const isUUIDCandidate = UUID_RE.test(candidate.replace(/::groups$|::children$/, ''));
            let cOffset = 0;
            let cMore = true;
            while (cMore) {
              const { records, hasMore: hm } = await CellValues.findAll({
                filters: { boardId: candidate },
                limit: 2000,
                offset: cOffset,
              });
              for (const r of records) {
                if (r.deletedAt) continue;
                const key = `${r.rowId}::${r.columnId}`;
                const existingIsUUID = seenIsUUID.get(key);
                if (existingIsUUID !== undefined) {
                  // Duplicate — prefer UUID version
                  if (!existingIsUUID && isUUIDCandidate) {
                    seen.set(key, r);
                    seenIsUUID.set(key, true);
                  }
                } else {
                  seen.set(key, r);
                  seenIsUUID.set(key, isUUIDCandidate);
                }
              }
              cMore = hm;
              cOffset += records.length;
            }
          }

          const merged = Array.from(seen.values());
          const page = merged.slice(offset, offset + limit);
          const hasMore = (offset + limit) < merged.length;

          if (DEBUG) {
            console.log(`[getCellValues] ${board.boardType} merge-read: ${merged.length} cell(s) from ${candidates.length} candidates`, candidates);
          }

          return { cells: page, hasMore, nextOffset: offset + page.length };
        }

        // ── NON-MERGE UUID: fast path (PM, etc.) ────────────────────────────
        const { records: fast, hasMore: fastMore } = await CellValues.findAll({
          filters: { boardId: originalBoardId },
          limit,
          offset,
        });
        const fastActive = fast.filter((r) => !r.deletedAt);
        if (fastActive.length > 0 || fastMore) {
          return { cells: fastActive, hasMore: fastMore, nextOffset: offset + fast.length };
        }
        return { cells: [], hasMore: false, nextOffset: offset };
      }

      // Non-UUID, non-legacy — unexpected format, return empty
      return { cells: [], hasMore: false, nextOffset: offset };
    }

    // ── SLOW PATH: resolve boardId & try candidates ───────────────────────────
    // For legacy IDs we always enter here; for UUID IDs we enter only if the
    // fast path found nothing.
    let candidates: string[] = [];

    try {
      const resolved = await resolveBoardId({
        boardIdOrKey: originalBoardId,
        fallbackToLegacy: true,
      });

      if (DEBUG) {
        console.log('[getCellValues] resolution:', {
          input: originalBoardId,
          resolvedBoardId: resolved.boardId,
          legacyCompositeId: resolved.legacyCompositeId,
          isLegacy: resolved.isLegacy,
          unresolvedLegacy: resolved.unresolvedLegacy ?? false,
        });
      }

      // Build deduplicated candidate list — UUID first (canonical), legacy as fallback
      // This ensures post-migration boards serve data from the UUID source.
      const uuidCandidate = resolved.boardId;
      const legacyCandidate = resolved.legacyCompositeId;

      // 1. UUID (resolved) — most data lives here after migration
      if (uuidCandidate && !candidates.includes(uuidCandidate)) {
        candidates.push(uuidCandidate);
      }
      // 2. Original input (if different from both resolved candidates)
      if (!candidates.includes(originalBoardId)) {
        candidates.push(originalBoardId);
      }
      // 3. Legacy composite — fallback for un-migrated boards
      if (
        legacyCandidate &&
        !candidates.includes(legacyCandidate)
      ) {
        candidates.push(legacyCandidate);
      }
    } catch (err) {
      if (DEBUG) {
        console.log('[getCellValues] resolver-error — using original boardId only:', err);
      }
      // candidates already = [originalBoardId], endpoint continues safely
    }

    if (DEBUG) {
      console.log('[getCellValues] candidates:', candidates, { offset, limit });
    }

    // ── MERGE MODE: when data may be split across legacy + UUID boardIds ─────
    // Applies to ::groups/::children AND legacy composite boards (pm-, cal-,
    // recruitment-) where columns/cells can be split after partial migration.
    const needsMerge = candidates.length > 1 && isLegacyComposite;

    if (needsMerge) {
      const seen = new Set<string>();
      const merged: typeof candidates extends string[] ? any[] : never = [];

      for (const candidate of candidates) {
        const { records } = await CellValues.findAll({
          filters: { boardId: candidate },
          limit: 2000,
          offset: 0,
        });

        for (const r of records) {
          if (r.deletedAt) continue;
          // Deduplicate by rowId+columnId (same cell under different boardIds)
          const key = `${r.rowId}::${r.columnId}`;
          if (!seen.has(key)) {
            seen.add(key);
            merged.push(r);
          }
        }
      }

      if (DEBUG) {
        console.log(`[getCellValues] MERGE mode for ${originalBoardId}: ${merged.length} cells from ${candidates.length} candidates`);
      }

      // Apply pagination to the merged set
      const page = merged.slice(offset, offset + limit);
      const hasMore = offset + limit < merged.length;
      return { cells: page, hasMore, nextOffset: offset + page.length };
    }

    // ── Dual-read: try each candidate in order, return on first hit ───────────
    // Rules:
    //   - Never mix results from different candidates
    //   - Return the first candidate that has active records OR hasMore
    //   - Same limit/offset applied to every candidate
    for (const candidate of candidates) {
      const { records, hasMore } = await CellValues.findAll({
        filters: { boardId: candidate },
        limit,
        offset,
      });

      const active = records.filter((r) => !r.deletedAt);

      if (active.length > 0 || hasMore) {
        if (DEBUG) {
          const source =
            candidate === originalBoardId
              ? 'original'
              : candidate === candidates[1]
                ? 'uuid'
                : 'legacy-composite';
          console.log(
            `[getCellValues] source="${source}" candidate="${candidate}"`,
            { cellsFound: active.length, hasMore, offset },
          );
        }
        return { cells: active, hasMore, nextOffset: offset + records.length };
      }
    }

    // ── Nothing found across all candidates ───────────────────────────────────
    if (DEBUG) {
      console.log('[getCellValues] source="empty" — no cells found for any candidate:', candidates);
    }

    return { cells: [], hasMore: false, nextOffset: offset };
  },
});

src/api/getPoAuditLog.ts.content:
import { z } from 'zod';
import { createEndpoint, PoAuditLog } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Get audit log entries for a purchase order',
  inputSchema: z.object({ poId: z.string() }),
  outputSchema: z.object({
    entries: z.array(z.object({
      id: z.string(),
      timestamp: z.string().optional(),
      action: z.string().optional(),
      userEmail: z.string().optional(),
      userName: z.string().optional(),
      comments: z.string().optional(),
    })),
  }),
  execute: async ({ input }) => {
    const { records } = await PoAuditLog.findAll({
      filters: { purchaseOrder: input.poId } as never,
      limit: 200,
    });

    const sorted = [...records].sort((a, b) => {
      const aTime = a.timestamp ? new Date(a.timestamp).getTime() : 0;
      const bTime = b.timestamp ? new Date(b.timestamp).getTime() : 0;
      return bTime - aTime;
    });

    return {
      entries: sorted.map(r => ({
        id: r.id,
        timestamp: r.timestamp,
        action: r.action,
        userEmail: r.userEmail,
        userName: r.userName,
        comments: r.comments,
      })),
    };
  },
});

src/api/getTrashItems.ts.content:
import { z } from 'zod';
import { createEndpoint, RecruitmentRows, BoardColumns, Boards } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Get soft-deleted boards and rows for a project (UUID-forward with legacy fallback)',
  inputSchema: z.object({ projectCode: z.string() }),
  outputSchema: z.object({
    boards: z.array(z.object({
      boardId: z.string(),
      boardName: z.string(),
      deletedAt: z.string(),
      deletedBy: z.string().optional(),
      rowCount: z.number(),
    })),
    rows: z.array(z.object({
      id: z.string(),
      participantName: z.string().optional(),
      email: z.string().optional(),
      boardName: z.string().optional(),
      deletedAt: z.string(),
    })),
  }),
  execute: async ({ input }) => {
    // ── 1. Fetch boards for this project from Boards table ──────────────
    const { records: projectBoards } = await Boards.findAll({
      filters: { projectCode: input.projectCode },
      limit: 200,
    });

    // Get all board UUIDs for this project (active + deleted)
    const allBoardUuids = projectBoards.map(b => b.id);
    const legacyPrefix = `recruitment-${input.projectCode}-`;

    // ── 2. Find deleted board columns (UUID + legacy) ──────────────────
    // Search by UUID boards
    const colResults: any[] = [];
    for (const uuid of allBoardUuids) {
      const { records } = await BoardColumns.findAll({
        filters: { boardId: uuid },
        fields: ['id', 'boardId', 'deletedAt', 'deletedBy'],
        limit: 200,
      });
      colResults.push(...records);
    }
    // Also search legacy prefix for boards that may not have been migrated
    const { records: legacyCols } = await BoardColumns.findAll({
      filters: { boardId: { contains: legacyPrefix } },
      fields: ['id', 'boardId', 'deletedAt', 'deletedBy'],
      limit: 500,
    });
    const seenColIds = new Set(colResults.map(c => c.id));
    for (const lc of legacyCols) {
      if (!seenColIds.has(lc.id)) colResults.push(lc);
    }

    // Group deleted columns by boardId
    const boardMap = new Map<string, { boardId: string; boardName: string; deletedAt: string; deletedBy?: string }>();
    const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    for (const col of colResults) {
      if (!col.deletedAt || !col.boardId) continue;
      const existing = boardMap.get(col.boardId);
      // Derive boardName from UUID lookup or legacy parse
      let boardName = '';
      if (UUID_RE.test(col.boardId)) {
        const board = projectBoards.find(b => b.id === col.boardId);
        boardName = board?.boardName ?? col.boardId;
      } else if (col.boardId.startsWith(legacyPrefix)) {
        boardName = col.boardId.slice(legacyPrefix.length);
      } else {
        continue;
      }
      if (!existing) {
        boardMap.set(col.boardId, {
          boardId: col.boardId,
          boardName,
          deletedAt: col.deletedAt,
          deletedBy: col.deletedBy ?? undefined,
        });
      } else if (!existing.deletedBy && col.deletedBy) {
        boardMap.set(col.boardId, { ...existing, deletedBy: col.deletedBy });
      }
    }

    // ── 3. Find deleted recruitment rows ─────────────────────────────────
    const { records: allRows } = await RecruitmentRows.findAll({
      filters: { projectCode: input.projectCode },
      fields: ['id', 'participantName', 'email', 'boardName', 'deletedAt', 'parentRowId'],
      limit: 2000,
    });

    const deletedRows = allRows.filter(r => !!r.deletedAt);
    const deletedBoardNames = new Set([...boardMap.values()].map(b => b.boardName));

    const individuallyDeleted = deletedRows
      .filter(r => !deletedBoardNames.has(r.boardName ?? '') && !r.parentRowId)
      .map(r => ({
        id: r.id,
        participantName: r.participantName,
        email: r.email,
        boardName: r.boardName,
        deletedAt: r.deletedAt!,
      }));

    const boards = [...boardMap.values()].map(b => ({
      ...b,
      rowCount: deletedRows.filter(r => r.boardName === b.boardName).length,
    }));

    return { boards, rows: individuallyDeleted };
  },
});

src/api/publishTyping.ts.content:
import { z } from 'zod';
import { createEndpoint } from 'zite-integrations-backend-sdk';
import { publishEvent } from '../lib/ably';

export default createEndpoint({
  description: 'Publish a typing indicator event via Ably (ephemeral, not stored)',
  authenticated: true,
  inputSchema: z.object({
    channel: z.string().min(1),
  }),
  outputSchema: z.object({ ok: z.boolean() }),
  execute: async ({ input, context }) => {
    const userName = `${context.user!.firstName ?? ''} ${context.user!.lastName ?? ''}`.trim() || context.user!.email.split('@')[0];
    try {
      await publishEvent(`chat:${input.channel}`, 'typing', {
        channel: input.channel,
        userEmail: context.user!.email,
        userName,
        sentAt: new Date().toISOString(),
      });
    } catch {
      // Best-effort — don't break the UI if Ably fails
    }
    return { ok: true };
  },
});

src/api/rejectExpense.ts.content:
import { z } from 'zod';
import { createEndpoint, Expenses, ExpenseAuditLog, ZiteError } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Reject an expense and return it to Rechazado status',
  inputSchema: z.object({ id: z.string(), rejectionReason: z.string() }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    const level = context.user!.purchaseLevel ?? 'Creador';
    if (level !== 'Aprobador' && level !== 'Finanzas' && level !== 'Socios') {
      throw new ZiteError({ code: 'FORBIDDEN', message: 'No tienes permisos para rechazar gastos' });
    }

    const expense = await Expenses.findOne({ id: input.id });
    if (!expense) throw new ZiteError({ code: 'NOT_FOUND', message: 'Gasto no encontrado' });
    if (expense.status !== 'Enviado a aprobación') {
      throw new ZiteError({ code: 'BAD_REQUEST', message: 'Solo se pueden rechazar gastos en estado "Enviado a aprobación"' });
    }

    await Expenses.update({
      id: input.id,
      record: {
        status: 'Rechazado',
        rejectionReason: input.rejectionReason,
        approvedBy: context.user!.email,
      },
    });

    const userName = [context.user!.firstName, context.user!.lastName].filter(Boolean).join(' ') || context.user!.email;
    await ExpenseAuditLog.create({
      record: {
        timestamp: new Date().toISOString(),
        expense: input.id,
        action: 'Rechazado',
        userEmail: context.user!.email,
        userName,
        comments: input.rejectionReason,
        expenseNumber: String(expense.expenseNumber ?? ''),
      },
    });

    return { success: true };
  },
});

src/api/saveCellValue.ts.content:
import { z } from 'zod';
import { createEndpoint, CellValues, BoardColumns, CalendarEvents, RecruitmentRows, Tasks, Users, Boards } from 'zite-integrations-backend-sdk';
import { publishEvent } from '../lib/ably';
import { resolveWriteBoardId, smartWriteCellValue } from '../serverUtils/smartWrite';
import { resolveBoardId } from '../serverUtils/resolveBoardId';

// ─────────────────────────────────────────────────────────────────────────────
// Calendar dynamic columns that mirror native CalendarEvents fields
// ─────────────────────────────────────────────────────────────────────────────
const CAL_SYNC_COLUMNS: Record<string, 'eventDate' | 'durationHours' | 'location' | 'attendees'> = {
  'Fecha y hora':        'eventDate',
  'Duración (hrs)':      'durationHours',
  'Ubicación (interna)': 'location',
  'Ubicación Interna':   'location',
  'Espacio':             'location',
  'Moderador':           'attendees',
  'Persona/Moderador':   'attendees',
};

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const LEGACY_WRITE_PREFIXES = ['recruitment-', 'cal-', 'pm-'] as const;
const SUFFIXES = ['::groups', '::children'] as const;

export default createEndpoint({
  authenticated: true,
  description: 'Upsert a single cell value. Uses resolveWriteBoardId + smartWriteCellValue for UUID migration. events- boards stay legacy permanently. Writes to CellValues, syncs CalendarEvents native fields, syncs Tasks.startDate/endDate for pm boards, and updates denormalized cellData on RecruitmentRows.',
  inputSchema: z.object({
    boardId:      z.string(),
    rowId:        z.string(),
    columnId:     z.string(),
    projectCode:  z.string().optional(),
    textValue:    z.string().optional(),
    numberValue:  z.number().optional(),
    dateValue:    z.string().optional(),
    booleanValue: z.boolean().optional(),
    fileUrl:      z.string().optional(),
  }),
  outputSchema: z.object({ success: z.boolean(), id: z.string(), inviteStatusChanged: z.boolean().optional() }),
  execute: async ({ input, context }) => {
    const { boardId, rowId, columnId, projectCode: inputProjectCode, ...values } = input;

    // ── Phase 1: Parse suffix + detect type ─────────────────────────────
    let suffix = '' as '' | '::groups' | '::children';
    for (const s of SUFFIXES) {
      if (boardId.endsWith(s)) { suffix = s; break; }
    }
    const originalBase = suffix ? boardId.slice(0, -suffix.length) : boardId;
    const originalBoardId = boardId;

    const isEventsBoard = originalBase.startsWith('events-');
    const isLegacyWritePrefix = LEGACY_WRITE_PREFIXES.some(p => originalBase.startsWith(p));
    const isUuid = UUID_RE.test(originalBase);

    // Board type resolved from prefix or UUID lookup — used for Phase 5/6 detection
    let resolvedBoardType: string | undefined =
      originalBase.startsWith('pm-')          ? 'pm' :
      originalBase.startsWith('cal-')         ? 'calendar' :
      originalBase.startsWith('recruitment-') ? 'recruitment' :
      originalBase.startsWith('events-')      ? 'events' : undefined;

    let entityType =
      originalBase.startsWith('pm-')          ? 'task' :
      originalBase.startsWith('cal-')         ? 'event' :
      originalBase.startsWith('recruitment-') ? 'recruitmentRow' : 'unknown';

    let resolvedProjectCode: string | undefined = inputProjectCode;

    // ── Phase 2: Resolve write target ───────────────────────────────────
    let writeBoardId: string;
    let legacyBoardId: string | undefined;

    if (isEventsBoard) {
      // events- → permanent legacy, no UUID resolution ever
      writeBoardId = boardId;
      legacyBoardId = undefined;
    } else if (isLegacyWritePrefix) {
      // pm-, cal-, recruitment- → resolve base to UUID
      const resolution = await resolveWriteBoardId(originalBase);
      writeBoardId = suffix ? `${resolution.writeBoardId}${suffix}` : resolution.writeBoardId;
      legacyBoardId = suffix ? `${originalBase}${suffix}` : originalBase;
      if (resolution.reason === 'legacy-fallback' || resolution.reason === 'input-passthrough') {
        console.warn(`[saveCellValue] Could not resolve ${originalBase} to UUID — fallback (reason=${resolution.reason})`);
      } else {
        console.log(`[saveCellValue] Resolved legacy ${originalBase} → ${resolution.writeBoardId}`);
      }
    } else if (isUuid) {
      // UUID → already correct target; find legacy equivalent for dual-read
      writeBoardId = boardId;
      try {
        const resolved = await resolveBoardId({ boardIdOrKey: originalBase, fallbackToLegacy: true });
        legacyBoardId = resolved.legacyBaseId
          ? (suffix ? `${resolved.legacyBaseId}${suffix}` : resolved.legacyBaseId)
          : undefined;
        resolvedProjectCode = resolvedProjectCode ?? resolved.projectCode ?? undefined;
        // Resolve boardType from the UUID lookup so Phase 5/6 work for UUID boards
        resolvedBoardType = resolved.boardType || resolvedBoardType;
        if (resolvedBoardType === 'calendar') entityType = 'event';
        else if (resolvedBoardType === 'pm') entityType = 'task';
        else if (resolvedBoardType === 'recruitment') entityType = 'recruitmentRow';

        // Fallback: if legacyBaseId is empty/missing for calendar boards, compute from CalendarEvents
        if (!legacyBoardId && resolvedBoardType === 'calendar' && resolvedProjectCode) {
          try {
            const probeEvent = await CalendarEvents.findOne({ id: rowId });
            if (probeEvent?.calendarName) {
              legacyBoardId = suffix
                ? `cal-${resolvedProjectCode}-${probeEvent.calendarName}${suffix}`
                : `cal-${resolvedProjectCode}-${probeEvent.calendarName}`;
              console.log(`[saveCellValue] Computed legacyBoardId from CalendarEvents probe: ${legacyBoardId}`);
            }
          } catch { /* skip */ }
        }
      } catch (resolveErr) {
        legacyBoardId = undefined;
        console.warn(`[saveCellValue] resolveBoardId failed for UUID ${originalBase}:`, resolveErr);
        // Fallback: try to infer boardType by probing CalendarEvents (lightweight — only runs on error path)
        if (!resolvedBoardType) {
          try {
            const probeEvent = await CalendarEvents.findOne({ id: rowId });
            if (probeEvent) {
              resolvedBoardType = 'calendar';
              entityType = 'event';
              resolvedProjectCode = resolvedProjectCode ?? probeEvent.projectCode ?? undefined;
              console.log(`[saveCellValue] Inferred boardType=calendar from CalendarEvents probe for rowId=${rowId}`);
            }
          } catch { /* probe failed — leave boardType unknown */ }
        }
      }

      // ── Post-resolve: ensure legacyBoardId is computed when possible ───
      if (!legacyBoardId && resolvedProjectCode) {
        if (resolvedBoardType === 'calendar') {
          try {
            const probeEvent = await CalendarEvents.findOne({ id: rowId });
            if (probeEvent?.calendarName && probeEvent?.projectCode) {
              legacyBoardId = suffix
                ? `cal-${probeEvent.projectCode}-${probeEvent.calendarName}${suffix}`
                : `cal-${probeEvent.projectCode}-${probeEvent.calendarName}`;
              console.log(`[saveCellValue] Fallback legacyBoardId from CalendarEvents: ${legacyBoardId}`);
            }
          } catch { /* skip */ }
        } else if (resolvedBoardType && resolvedBoardType !== 'events') {
          try {
            const board = await Boards.findOne({ id: originalBase });
            if (board?.boardName && board?.projectCode) {
              const prefix = resolvedBoardType === 'recruitment' ? 'recruitment-' : 'pm-';
              legacyBoardId = suffix
                ? `${prefix}${board.projectCode}-${board.boardName}${suffix}`
                : `${prefix}${board.projectCode}-${board.boardName}`;
              console.log(`[saveCellValue] Fallback legacyBoardId from Boards: ${legacyBoardId}`);
            }
          } catch { /* skip */ }
        }
      }
    } else {
      // Unknown format → passthrough
      writeBoardId = boardId;
      legacyBoardId = undefined;
      console.warn(`[saveCellValue] Unknown boardId format: ${boardId} — passthrough`);
    }

    // ── Realtime publish helper ─────────────────────────────────────────
    const tryPublish = async () => {
      try {
        if (!resolvedProjectCode) return;
        await publishEvent(`board:${resolvedProjectCode}`, 'board.field.updated', {
          projectCode: resolvedProjectCode,
          boardId: originalBoardId,
          entityType,
          fieldType: 'dynamic',
          rowId,
          columnId,
          value: {
            textValue:    values.textValue,
            numberValue:  values.numberValue,
            dateValue:    values.dateValue,
            booleanValue: values.booleanValue,
            fileUrl:      values.fileUrl,
          },
          senderEmail: context.user!.email,
          timestamp: new Date().toISOString(),
        });
      } catch { /* fire and forget */ }
    };

    const isEmpty =
      (!values.textValue  || values.textValue.trim()  === '') &&
      values.numberValue  === undefined &&
      (!values.dateValue  || values.dateValue.trim()  === '') &&
      values.booleanValue === undefined &&
      (!values.fileUrl    || values.fileUrl.trim()    === '');

    const clean = isEmpty ? {} : Object.fromEntries(
      Object.entries(values).filter(([, v]) => v !== undefined && v !== null && v !== '')
    );

    console.log(`[saveCellValue] original=${originalBoardId} writeBoardId=${writeBoardId} legacyBoardId=${legacyBoardId ?? 'none'} rowId=${rowId} colId=${columnId} isEmpty=${isEmpty}`);

    // ── Phase 3: Write cell value ───────────────────────────────────────
    let cellId: string;

    if (isEventsBoard) {
      // Direct legacy write for events- boards (no smartWrite)
      const existing = await CellValues.findOne({ filters: { boardId: writeBoardId, rowId, columnId } });
      if (isEmpty) {
        if (existing) {
          await CellValues.delete({ id: existing.id });
          cellId = existing.id;
          console.log(`[saveCellValue] [events] Deleted id=${existing.id}`);
        } else {
          cellId = '__noop__';
        }
      } else {
        if (existing) {
          await CellValues.update({ id: existing.id, record: clean });
          cellId = existing.id;
          console.log(`[saveCellValue] [events] Updated id=${existing.id}`);
        } else {
          const created = await CellValues.create({ record: { boardId: writeBoardId, rowId, columnId, ...clean } });
          cellId = created.id;
          console.log(`[saveCellValue] [events] Created id=${created.id}`);
        }
      }
    } else {
      // All other boards: smartWriteCellValue (handles UUID/legacy dual-read, move, dedup)
      const result = await smartWriteCellValue({
        uuidBoardId: writeBoardId,
        legacyBoardId,
        rowId,
        columnId,
        values,
        isEmpty,
      });
      cellId = result.id;
      console.log(`[saveCellValue] smartWrite: action=${result.action} boardIdUsed=${result.boardIdUsed}`);
    }

    // ── Phase 4: Sync RecruitmentRows.cellData (recruitment boards only) ─
    if (resolvedBoardType === 'recruitment' || originalBase.startsWith('recruitment-')) {
      try {
        const rowRecord = await RecruitmentRows.findOne({ id: rowId });
        if (rowRecord) {
          resolvedProjectCode = resolvedProjectCode ?? rowRecord.projectCode ?? undefined;
          let cellData: Record<string, unknown> = {};
          try { cellData = JSON.parse(rowRecord.cellData ?? '{}'); } catch { /**/ }
          if (isEmpty) {
            delete cellData[columnId];
          } else {
            cellData[columnId] = clean;
          }
          await RecruitmentRows.update({ id: rowId, record: { cellData: JSON.stringify(cellData) } });
        }
      } catch { /* Non-recruitment rows — ignore */ }
    }

    // ── Phase 5: Sync Tasks (pm boards) ─────────────────────────────────
    if ((originalBase.startsWith('pm-') || resolvedBoardType === 'pm') && !suffix) {
      try {
        const col = await BoardColumns.findOne({ id: columnId });
        if (col?.columnType === 'Fecha') {
          // Find all Fecha columns to determine start vs end — use the column's own boardId first
          const colBoardId = col.boardId || originalBase;
          let colsRes = await BoardColumns.findAll({ filters: { boardId: colBoardId }, limit: 200 });
          let fechaCols = colsRes.records
            .filter(c => !c.deletedAt && c.columnType === 'Fecha')
            .sort((a, b) => (a.columnOrder ?? 9999) - (b.columnOrder ?? 9999));

          // Fallback: if no Fecha cols found and writeBoardId base differs, try that
          const writeBase = writeBoardId.split('::')[0];
          if (fechaCols.length === 0 && writeBase !== colBoardId) {
            colsRes = await BoardColumns.findAll({ filters: { boardId: writeBase }, limit: 200 });
            fechaCols = colsRes.records
              .filter(c => !c.deletedAt && c.columnType === 'Fecha')
              .sort((a, b) => (a.columnOrder ?? 9999) - (b.columnOrder ?? 9999));
          }

          const isStartCol = fechaCols[0]?.id === columnId;
          const isEndCol   = fechaCols[1]?.id === columnId;
          if (isStartCol || isEndCol) {
            const field = isStartCol ? 'startDate' : 'endDate';
            const dateVal = isEmpty ? undefined : (values.dateValue?.split('T')[0] ?? undefined);
            await Tasks.update({ id: rowId, record: { [field]: dateVal } });
            console.log(`[saveCellValue] ✓ Synced Tasks.${field}=${dateVal} for task id=${rowId}`);
          }
        }
      } catch (e) {
        console.log(`[saveCellValue] pm date sync skipped for rowId=${rowId}:`, e);
      }
    }

    // pm: resolve projectCode from Task if still unknown
    if (!resolvedProjectCode && (originalBase.startsWith('pm-') || resolvedBoardType === 'pm')) {
      try {
        const task = await Tasks.findOne({ id: rowId });
        resolvedProjectCode = task?.projectCode ?? undefined;
      } catch { /* skip */ }
    }

    // ── Phase 6: Sync CalendarEvents (cal boards) ───────────────────────
    if ((originalBase.startsWith('cal-') || resolvedBoardType === 'calendar') && !suffix) {
      console.log(`[saveCellValue] Calendar board — checking column for native sync`);
      const calEvent = await CalendarEvents.findOne({ id: rowId });
      resolvedProjectCode = resolvedProjectCode ?? calEvent?.projectCode ?? undefined;

      if (!calEvent) {
        console.warn(`[saveCellValue] CalendarEvents NOT FOUND for rowId=${rowId} — sync skipped`);
      } else {
        try {
          const col = await BoardColumns.findOne({ id: columnId });
          if (col?.columnName) {
            const nativeField = CAL_SYNC_COLUMNS[col.columnName];
            if (nativeField) {
              const update: Partial<{ eventDate: string; durationHours: number; location: string; attendees: string }> = {};

              if (isEmpty) {
                if (nativeField === 'eventDate')     update.eventDate     = undefined;
                if (nativeField === 'durationHours') update.durationHours = undefined;
                if (nativeField === 'location')      update.location      = undefined;
                if (nativeField === 'attendees')     update.attendees     = undefined;
              } else {
                if (nativeField === 'eventDate'     && values.dateValue)                 update.eventDate     = values.dateValue;
                if (nativeField === 'durationHours' && values.numberValue !== undefined) update.durationHours = values.numberValue;
                if (nativeField === 'location'      && values.textValue)                 update.location      = values.textValue;
                if (nativeField === 'attendees'     && values.textValue) {
                  let attendeeName = values.textValue;
                  if (UUID_RE.test(values.textValue)) {
                    try {
                      const uRecord = await Users.findOne({ id: values.textValue });
                      if (uRecord) {
                        attendeeName = [uRecord.firstName, uRecord.lastName].filter(Boolean).join(' ') || uRecord.email || values.textValue;
                      }
                    } catch { /* not a valid user */ }
                  }
                  update.attendees = attendeeName;
                }
              }

              if (Object.keys(update).length > 0) {
                await CalendarEvents.update({ id: rowId, record: update });
                console.log(`[saveCellValue] ✓ CalendarEvents native sync for id=${rowId} field="${nativeField}"`);
              }
            }
          }
        } catch (e) {
          console.warn(`[saveCellValue] cal column sync skipped for columnId=${columnId}:`, e);
        }

        let inviteStatusChanged = false;
        if (
          calEvent.outlookEventId &&
          calEvent.inviteStatus !== 'Cancelado' &&
          calEvent.inviteStatus !== 'Por actualizar'
        ) {
          // Best-effort update with 1 retry — must never crash the endpoint
          try {
            await CalendarEvents.update({ id: rowId, record: { inviteStatus: 'Por actualizar' } });
            inviteStatusChanged = true;
          } catch (firstErr) {
            console.warn(`[saveCellValue] inviteStatus update failed (attempt 1), retrying in 1s:`, firstErr);
            try {
              await new Promise(r => setTimeout(r, 1000));
              await CalendarEvents.update({ id: rowId, record: { inviteStatus: 'Por actualizar' } });
              inviteStatusChanged = true;
            } catch (retryErr) {
              console.warn(`[saveCellValue] inviteStatus update failed (attempt 2), giving up. Cell was saved. Error:`, retryErr);
              inviteStatusChanged = false;
            }
          }
        }

        await tryPublish();
        return { success: true, id: cellId, inviteStatusChanged };
      }
    }

    // ── Phase 7: Publish realtime + return ──────────────────────────────
    await tryPublish();
    return { success: true, id: cellId };
  },
});

