src/api/duplicateBoard.ts.content:
import { z } from 'zod';
import { createEndpoint, Boards, BoardColumns, Tasks, CellValues } from 'zite-integrations-backend-sdk';

// ── Helpers ───────────────────────────────────────────────────────────────────

/** Try the primary key first; if no active records come back, try the fallback key. */
async function dualReadColumns(primaryId: string, fallbackId: string | undefined) {
  const { records: primary } = await BoardColumns.findAll({ filters: { boardId: primaryId }, limit: 500 });
  const active = primary.filter(c => !c.deletedAt);
  if (active.length > 0 || !fallbackId || fallbackId === primaryId) return active;

  const { records: fallback } = await BoardColumns.findAll({ filters: { boardId: fallbackId }, limit: 500 });
  return fallback.filter(c => !c.deletedAt);
}

async function dualReadCells(primaryId: string, fallbackId: string | undefined) {
  const { records: primary } = await CellValues.findAll({ filters: { boardId: primaryId }, limit: 2000 });
  const active = primary.filter(c => !c.deletedAt);
  if (active.length > 0 || !fallbackId || fallbackId === primaryId) return active;

  const { records: fallback } = await CellValues.findAll({ filters: { boardId: fallbackId }, limit: 2000 });
  return fallback.filter(c => !c.deletedAt);
}

// ── Endpoint ──────────────────────────────────────────────────────────────────

export default createEndpoint({
  authenticated: true,
  description: 'Duplicates a timeline board — columns, tasks (with parent mapping), cell values, and groups board.',
  inputSchema: z.object({
    projectCode: z.string(),
    boardName: z.string(),
    newBoardName: z.string(),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    newBoardName: z.string(),
    taskCount: z.number(),
    /** The real UUID of the new Board record */
    uuidBoardId: z.string(),
    /** Legacy composite ID (pm-/cal-/recruitment- prefix) — used by frontend for cache keys */
    legacyBoardId: z.string(),
    /** Alias for uuidBoardId — canonical ID to use in future writes */
    canonicalBoardId: z.string(),
    taskColumnsCreated: z.array(z.object({
      id: z.string(),
      boardId: z.string().optional(),
      columnName: z.string().optional(),
      columnType: z.string().optional(),
      columnOrder: z.number().optional(),
      optionsJson: z.string().optional(),
    })).optional(),
    groupColumnsCreated: z.array(z.object({
      id: z.string(),
      boardId: z.string().optional(),
      columnName: z.string().optional(),
      columnType: z.string().optional(),
      columnOrder: z.number().optional(),
      optionsJson: z.string().optional(),
    })).optional(),
    taskCellValuesCreated: z.array(z.object({
      id: z.string(),
      boardId: z.string().optional(),
      rowId: z.string().optional(),
      columnId: z.string().optional(),
      textValue: z.string().optional(),
      numberValue: z.number().optional(),
      dateValue: z.string().optional(),
      booleanValue: z.boolean().optional(),
      fileUrl: z.string().optional(),
    })).optional(),
    groupCellValuesCreated: z.array(z.object({
      id: z.string(),
      boardId: z.string().optional(),
      rowId: z.string().optional(),
      columnId: z.string().optional(),
      textValue: z.string().optional(),
      numberValue: z.number().optional(),
      dateValue: z.string().optional(),
      booleanValue: z.boolean().optional(),
      fileUrl: z.string().optional(),
    })).optional(),
  }),
  execute: async ({ input }) => {
    const { projectCode, boardName, newBoardName } = input;

    // ── 0. Find source Board record to get boardType + UUID ───────────────────
    const existingBoardsEarly = await Boards.findAll({ filters: { projectCode }, limit: 200 });
    const srcBoardEarly = existingBoardsEarly.records.find(b => b.boardName === boardName && !b.deletedAt);

    const boardTypePrefix =
      srcBoardEarly?.boardType === 'calendar'    ? 'cal-' :
      srcBoardEarly?.boardType === 'recruitment' ? 'recruitment-' :
      'pm-';

    // Legacy composite IDs (source)
    const srcBoardId      = `${boardTypePrefix}${projectCode}-${boardName}`;
    const srcGroupBoardId = `${srcBoardId}::groups`;

    // Source UUID (may be undefined for boards that pre-date the Boards table)
    const srcUuid      = srcBoardEarly?.id;
    const srcUuidGroup = srcUuid ? `${srcUuid}::groups` : undefined;

    // Legacy composite IDs (destination) — used only in response for frontend cache
    const destBoardId      = `${boardTypePrefix}${projectCode}-${newBoardName}`;
    const destGroupBoardId = `${destBoardId}::groups`;

    // ── 1. Fetch source data with dual-read (legacy first, UUID fallback) ─────
    const [
      activeCols,
      activeGroupCols,
      srcTasksRes,
      activeCells,
      activeGroupCells,
      existingBoards,
    ] = await Promise.all([
      dualReadColumns(srcBoardId, srcUuid),
      dualReadColumns(srcGroupBoardId, srcUuidGroup),
      Tasks.findAll({ filters: { projectCode, boardName }, limit: 2000 }),
      dualReadCells(srcBoardId, srcUuid),
      dualReadCells(srcGroupBoardId, srcUuidGroup),
      Boards.findAll({ filters: { projectCode }, limit: 200 }),
    ]);

    // ── 2. Create new Board record — capture UUID ─────────────────────────────
    const srcBoard  = existingBoards.records.find(b => b.boardName === boardName && !b.deletedAt);
    const maxOrder  = existingBoards.records.reduce((m, b) => Math.max(m, b.boardOrder ?? 0), 0);
    const createdBoard = await Boards.create({
      record: {
        boardName: newBoardName,
        projectCode,
        boardOrder: maxOrder + 1,
        boardType: srcBoard?.boardType ?? undefined,
      },
    });

    const uuidBoardId      = createdBoard.id;
    const uuidGroupBoardId = `${uuidBoardId}::groups`;

    // ── 3. Duplicate main board columns under UUID ────────────────────────────
    const colIdMap = new Map<string, string>(); // oldId → newId
    const allTaskColsCreated: Array<{ id: string; boardId?: string; columnName?: string; columnType?: string; columnOrder?: number; optionsJson?: string }> = [];

    if (activeCols.length > 0) {
      const chunks: typeof activeCols[] = [];
      for (let i = 0; i < activeCols.length; i += 50) chunks.push(activeCols.slice(i, i + 50));

      for (const chunk of chunks) {
        const res = await BoardColumns.bulkCreate({
          records: chunk.map(c => ({
            columnName:  c.columnName,
            boardId:     uuidBoardId,   // ← write under UUID
            columnType:  c.columnType,
            optionsJson: c.optionsJson,
            columnOrder: c.columnOrder,
          })),
        });
        res.records.forEach((newRec, idx) => {
          colIdMap.set(chunk[idx].id, newRec.id);
          // Return legacy boardId so preSeedBoardCache uses the right cache key
          allTaskColsCreated.push({
            id:          newRec.id,
            boardId:     destBoardId,   // ← legacy in response
            columnName:  newRec.fields.columnName  ?? undefined,
            columnType:  newRec.fields.columnType  ?? undefined,
            optionsJson: newRec.fields.optionsJson ?? undefined,
            columnOrder: newRec.fields.columnOrder ?? undefined,
          });
        });
      }
    }

    // ── 4. Duplicate group board columns under UUID::groups ───────────────────
    const groupColIdMap = new Map<string, string>(); // oldGroupColId → newGroupColId
    const allGroupColsCreated: Array<{ id: string; boardId?: string; columnName?: string; columnType?: string; columnOrder?: number; optionsJson?: string }> = [];

    if (activeGroupCols.length > 0) {
      const chunks: typeof activeGroupCols[] = [];
      for (let i = 0; i < activeGroupCols.length; i += 50) chunks.push(activeGroupCols.slice(i, i + 50));

      for (const chunk of chunks) {
        const res = await BoardColumns.bulkCreate({
          records: chunk.map(c => ({
            columnName:  c.columnName,
            boardId:     uuidGroupBoardId,   // ← write under UUID::groups
            columnType:  c.columnType,
            optionsJson: c.optionsJson,
            columnOrder: c.columnOrder,
          })),
        });
        res.records.forEach((newRec, idx) => {
          groupColIdMap.set(chunk[idx].id, newRec.id);
          allGroupColsCreated.push({
            id:          newRec.id,
            boardId:     destGroupBoardId,   // ← legacy::groups in response
            columnName:  newRec.fields.columnName  ?? undefined,
            columnType:  newRec.fields.columnType  ?? undefined,
            optionsJson: newRec.fields.optionsJson ?? undefined,
            columnOrder: newRec.fields.columnOrder ?? undefined,
          });
        });
      }
    }

    // ── 5. Duplicate tasks (two passes for parent-child mapping) ─────────────
    const allTasks = srcTasksRes.records;
    const topLevel = allTasks.filter(t => !t.parentTaskId);
    const children  = allTasks.filter(t => !!t.parentTaskId);
    const taskIdMap = new Map<string, string>(); // oldTaskId → newTaskId

    // Pass 1: top-level tasks
    for (let i = 0; i < topLevel.length; i += 50) {
      const chunk = topLevel.slice(i, i + 50);
      const res = await Tasks.bulkCreate({
        records: chunk.map(t => ({
          taskName:   t.taskName,
          projectCode,
          boardName:  newBoardName,
          boardId:    uuidBoardId,
          status:     t.status,
          assignedTo: t.assignedTo,
          startDate:  t.startDate,
          endDate:    t.endDate,
          order:      t.order,
          notes:      t.notes,
        })),
      });
      res.records.forEach((newRec, idx) => taskIdMap.set(chunk[idx].id, newRec.id));
    }

    // Pass 2: child tasks (parentTaskId remapped)
    for (let i = 0; i < children.length; i += 50) {
      const chunk = children.slice(i, i + 50);
      const res = await Tasks.bulkCreate({
        records: chunk.map(t => ({
          taskName:     t.taskName,
          projectCode,
          boardName:    newBoardName,
          boardId:      uuidBoardId,
          status:       t.status,
          assignedTo:   t.assignedTo,
          startDate:    t.startDate,
          endDate:      t.endDate,
          order:        t.order,
          notes:        t.notes,
          parentTaskId: taskIdMap.get(t.parentTaskId!) ?? undefined,
        })),
      });
      res.records.forEach((newRec, idx) => taskIdMap.set(chunk[idx].id, newRec.id));
    }

    // ── 6. Duplicate main board cell values under UUID ────────────────────────
    const mappableCells = activeCells.filter(
      c => c.rowId && taskIdMap.has(c.rowId) && c.columnId && colIdMap.has(c.columnId)
    );
    const allTaskCellsCreated: Array<{ id: string; boardId?: string; rowId?: string; columnId?: string; textValue?: string; numberValue?: number; dateValue?: string; booleanValue?: boolean; fileUrl?: string }> = [];

    for (let i = 0; i < mappableCells.length; i += 100) {
      const chunk = mappableCells.slice(i, i + 100);
      const res = await CellValues.bulkCreate({
        records: chunk.map(c => ({
          boardId:      uuidBoardId,                 // ← write under UUID
          rowId:        taskIdMap.get(c.rowId!)!,
          columnId:     colIdMap.get(c.columnId!)!,
          textValue:    c.textValue,
          numberValue:  c.numberValue,
          dateValue:    c.dateValue,
          booleanValue: c.booleanValue,
          fileUrl:      c.fileUrl,
        })),
      });
      res.records.forEach(r => allTaskCellsCreated.push({
        id:           r.id,
        boardId:      destBoardId,                   // ← legacy in response
        rowId:        r.fields.rowId       ?? undefined,
        columnId:     r.fields.columnId    ?? undefined,
        textValue:    r.fields.textValue   ?? undefined,
        numberValue:  r.fields.numberValue ?? undefined,
        dateValue:    r.fields.dateValue   ?? undefined,
        booleanValue: r.fields.booleanValue ?? undefined,
        fileUrl:      r.fields.fileUrl     ?? undefined,
      }));
    }

    // ── 7. Duplicate group board cell values under UUID::groups ───────────────
    const mappableGroupCells = activeGroupCells.filter(
      c => c.rowId && taskIdMap.has(c.rowId) && c.columnId && groupColIdMap.has(c.columnId)
    );
    const allGroupCellsCreated: Array<{ id: string; boardId?: string; rowId?: string; columnId?: string; textValue?: string; numberValue?: number; dateValue?: string; booleanValue?: boolean; fileUrl?: string }> = [];

    for (let i = 0; i < mappableGroupCells.length; i += 100) {
      const chunk = mappableGroupCells.slice(i, i + 100);
      const res = await CellValues.bulkCreate({
        records: chunk.map(c => ({
          boardId:      uuidGroupBoardId,                 // ← write under UUID::groups
          rowId:        taskIdMap.get(c.rowId!)!,
          columnId:     groupColIdMap.get(c.columnId!)!,
          textValue:    c.textValue,
          numberValue:  c.numberValue,
          dateValue:    c.dateValue,
          booleanValue: c.booleanValue,
          fileUrl:      c.fileUrl,
        })),
      });
      res.records.forEach(r => allGroupCellsCreated.push({
        id:           r.id,
        boardId:      destGroupBoardId,                   // ← legacy::groups in response
        rowId:        r.fields.rowId       ?? undefined,
        columnId:     r.fields.columnId    ?? undefined,
        textValue:    r.fields.textValue   ?? undefined,
        numberValue:  r.fields.numberValue ?? undefined,
        dateValue:    r.fields.dateValue   ?? undefined,
        booleanValue: r.fields.booleanValue ?? undefined,
        fileUrl:      r.fields.fileUrl     ?? undefined,
      }));
    }

    return {
      success: true,
      newBoardName,
      taskCount: allTasks.length,
      uuidBoardId,
      legacyBoardId:   destBoardId,
      canonicalBoardId: uuidBoardId,
      taskColumnsCreated:    allTaskColsCreated,
      groupColumnsCreated:   allGroupColsCreated,
      taskCellValuesCreated: allTaskCellsCreated,
      groupCellValuesCreated: allGroupCellsCreated,
    };
  },
});

src/api/duplicateGroup.ts.content:
import { z } from 'zod';
import { createEndpoint, BoardColumns, CellValues, RecruitmentRows, Tasks } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Duplicate a group column and all rows inside it',
  inputSchema: z.object({
    groupColumnId: z.string(),
    tableType: z.enum(['recruitment', 'task']),
  }),
  outputSchema: z.object({
    newGroupId: z.string(),
    duplicatedRows: z.number(),
  }),
  execute: async ({ input }) => {
    const { groupColumnId, tableType } = input;

    // 1. Find the original group column
    const origCol = await BoardColumns.findOne({ id: groupColumnId });
    if (!origCol) throw new Error('Grupo no encontrado');

    // 2. Create a new group column (same board, same color, name + " (copia)")
    const newCol = await BoardColumns.create({
      record: {
        boardId: origCol.boardId,
        columnName: `${origCol.columnName ?? 'Grupo'} (copia)`,
        columnType: origCol.columnType, // color id
        columnOrder: (origCol.columnOrder ?? 0) + 0.5,
      },
    });

    // 3. Find all rows belonging to the original group
    const { records: groupCells } = await CellValues.findAll({
      filters: { columnId: groupColumnId, textValue: '1' },
      limit: 500,
    });
    const rowIds = groupCells.map(c => c.rowId).filter(Boolean) as string[];

    // 4. Duplicate each row and assign to new group
    let duplicatedRows = 0;
    for (const rowId of rowIds) {
      if (tableType === 'recruitment') {
        const orig = await RecruitmentRows.findOne({ id: rowId });
        if (!orig) continue;
        const { id: _id, ...rest } = orig;
        const newRow = await RecruitmentRows.create({
          record: {
            ...rest,
            rowName: `${rest.rowName ?? 'Fila'} (copia)`,
            participantName: rest.participantName ? `${rest.participantName} (copia)` : rest.participantName,
          },
        });

        // Copy cell values excluding the old group assignment
        const { records: cells } = await CellValues.findAll({ filters: { rowId }, limit: 500 });
        const cellsToClone = cells.filter(c => c.columnId !== groupColumnId);
        for (let i = 0; i < cellsToClone.length; i += 50) {
          await CellValues.bulkCreate({
            records: cellsToClone.slice(i, i + 50).map(c => ({
              boardId: c.boardId,
              rowId: newRow.id,
              columnId: c.columnId,
              textValue: c.textValue,
              numberValue: c.numberValue,
              dateValue: c.dateValue,
              booleanValue: c.booleanValue,
              fileUrl: c.fileUrl,
            })),
          });
        }

        // Assign to the new group
        await CellValues.create({
          record: {
            boardId: origCol.boardId ?? '',
            rowId: newRow.id,
            columnId: newCol.id,
            textValue: '1',
          },
        });

        duplicatedRows++;
      } else {
        const orig = await Tasks.findOne({ id: rowId });
        if (!orig) continue;
        const { id: _id, ...rest } = orig;
        const newTask = await Tasks.create({
          record: { ...rest, taskName: `${rest.taskName ?? 'Tarea'} (copia)` },
        });

        // Copy cell values excluding the old group assignment
        const { records: cells } = await CellValues.findAll({ filters: { rowId }, limit: 500 });
        const cellsToClone = cells.filter(c => c.columnId !== groupColumnId);
        for (let i = 0; i < cellsToClone.length; i += 50) {
          await CellValues.bulkCreate({
            records: cellsToClone.slice(i, i + 50).map(c => ({
              boardId: c.boardId,
              rowId: newTask.id,
              columnId: c.columnId,
              textValue: c.textValue,
              numberValue: c.numberValue,
              dateValue: c.dateValue,
              booleanValue: c.booleanValue,
              fileUrl: c.fileUrl,
            })),
          });
        }

        // Assign to the new group
        await CellValues.create({
          record: {
            boardId: origCol.boardId ?? '',
            rowId: newTask.id,
            columnId: newCol.id,
            textValue: '1',
          },
        });

        duplicatedRows++;
      }
    }

    return { newGroupId: newCol.id, duplicatedRows };
  },
});

src/api/filloutWebhook.ts.content:
import { z } from 'zod';
import { createEndpoint, RecruitmentRows, Participants, BoardColumns, CellValues, Projects } from 'zite-integrations-backend-sdk';
import { resolveWriteBoardId } from '../serverUtils/smartWrite';
import { lookupBoardUUID } from '../serverUtils/resolveBoardId';

type ProjectDates = { startDate?: string; endDate?: string; client?: string };

// Maps Fillout/generic field types to the board's column type vocabulary
const toColumnType = (type?: string): string => {
  if (!type) return 'Texto';
  const t = type.toLowerCase();
  if (t.includes('number') || t.includes('num') || t.includes('rating')) return 'Número';
  if (t.includes('date') || t.includes('time')) return 'Fecha';
  if (t.includes('bool') || t.includes('check') || t.includes('yesno')) return 'Checkbox';
  if (t.includes('select') || t.includes('choice') || t.includes('dropdown')) return 'Select';
  if (t.includes('email')) return 'Email';
  if (t.includes('phone') || t.includes('tel')) return 'Teléfono';
  if (t.includes('file') || t.includes('upload')) return 'Archivo';
  return 'Texto';
};

const buildParticipationNote = (
  allRows: { id: string; projectCode?: string; boardName?: string; status?: string; group?: string }[],
  newRecordId: string,
  currentProjectCode: string,
  currentBoardName: string,
  projectDatesMap: Map<string, ProjectDates> = new Map(),
): string => {
  const otherRows = allRows.filter(r => r.id !== newRecordId);
  if (otherRows.length === 0) return '';

  const sixMonthsAgo = new Date();
  sixMonthsAgo.setMonth(sixMonthsAgo.getMonth() - 6);

  const normalizeStr = (s?: string) =>
    (s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
  const currentClientNorm = normalizeStr(projectDatesMap.get(currentProjectCode)?.client);

  // ── 🟠 Orange: same board ×N ─────────────────────────────────────────────
  const sameBoardRows = otherRows.filter(
    r => r.projectCode === currentProjectCode && r.boardName === currentBoardName,
  );

  // ── Other board/project rows → 🔴 RED or 🔵 BLUE ─────────────────────────
  const otherBoardRows = otherRows.filter(
    r => !(r.projectCode === currentProjectCode && r.boardName === currentBoardName),
  );

  const redProjects  = new Map<string, string>();
  const blueProjects = new Map<string, string>();

  for (const r of otherBoardRows) {
    if (!r.projectCode) continue;
    const label       = r.boardName ? `${r.projectCode} (${r.boardName})` : r.projectCode;
    const participated = r.status === 'Asistió' || (!!r.group && r.group.trim() !== '');
    const projData    = projectDatesMap.get(r.projectCode);
    const otherEnd    = projData?.endDate ? new Date(projData.endDate) : null;
    const otherClient = normalizeStr(projData?.client);
    // Same client → always red regardless of time or participation
    const isSameClient     = !!currentClientNorm && !!otherClient && otherClient === currentClientNorm;
    // Recent/active: project hasn't ended OR ended within last 6 months
    const isRecentOrActive = !otherEnd || otherEnd > sixMonthsAgo;
    const isRed = isSameClient || (participated && isRecentOrActive);
    if (isRed) {
      redProjects.set(r.projectCode, label);
    } else if (!redProjects.has(r.projectCode)) {
      blueProjects.set(r.projectCode, label);
    }
  }

  const parts: string[] = [];
  if (redProjects.size > 0) {
    parts.push(`🔴 ALERTA: ${[...redProjects.values()].join(', ')}.`);
  }
  const blueLabels = [...blueProjects.entries()]
    .filter(([k]) => !redProjects.has(k))
    .map(([, v]) => v);
  if (blueLabels.length > 0) {
    parts.push(`🔵 DUPLICADO EXTERNO: ${blueLabels.join(', ')}.`);
  }
  if (sameBoardRows.length > 0) {
    parts.push(`🟠 ×${sameBoardRows.length + 1} EN ESTE TABLERO`);
  }

  return parts.join(' ');
};

export default createEndpoint({
  description: 'Receive form submissions from Fillout and create recruitment rows. Supports arbitrary custom fields that auto-create dynamic columns. UUID-first writes.',
  inputSchema: z.object({
    projectCode: z.string().optional(),
    boardName: z.string().optional(),
    participantName: z.string().optional(),
    email: z.string().optional(),
    phone: z.string().optional(),
    idNumber: z.string().optional(),
    city: z.string().optional(),
    gender: z.string().optional(),
    age: z.number().optional(),
    sourceForm: z.string().optional(),
    customFields: z.array(z.object({
      fieldName: z.string(),
      value: z.string().optional(),
      type: z.string().optional(),
    })).optional(),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input }) => {
    // ── 1. Upsert participant in global registry ─────────────────────────────
    if (input.participantName || input.email) {
      await Participants.bulkCreate({
        records: [{
          fullName: input.participantName,
          email: input.email,
          phone: input.phone,
          idNumber: input.idNumber,
          city: input.city,
          gender: input.gender,
          age: input.age,
        }],
        matchOn: input.email ? ['email'] : undefined,
      });
    }

    const resolvedBoardName = input.boardName ?? 'Principal';

    // Dual-write: resolve boardId UUID before creating
    let boardIdUUID: string | undefined;
    if (input.projectCode && resolvedBoardName) {
      const lookup = await lookupBoardUUID(input.projectCode, resolvedBoardName, 'recruitment');
      if (lookup.found && lookup.uuid) {
        boardIdUUID = lookup.uuid;
      } else {
        console.warn('[filloutWebhook] boardId lookup failed, leaving empty', { projectCode: input.projectCode, boardName: resolvedBoardName, reason: lookup.reason });
      }
    }

    // ── 2. Create recruitment row ────────────────────────────────────────────
    const record = await RecruitmentRows.create({
      record: {
        rowName: input.participantName ?? input.email ?? 'Sin nombre',
        projectCode: input.projectCode,
        boardName: resolvedBoardName,
        boardId: boardIdUUID,
        participantName: input.participantName,
        email: input.email,
        phone: input.phone,
        idNumber: input.idNumber,
        status: 'Pendiente',
        sourceForm: input.sourceForm,
        level: 0,
        rowOrder: Math.floor(Date.now() / 1000),
      },
    });

    // ── 3. Handle custom fields → dynamic columns + cell values (UUID-first) ─
    if (input.customFields && input.customFields.length > 0) {
      const legacyBoardId = `recruitment-${input.projectCode ?? 'all'}-${resolvedBoardName}`;

      // Resolve to UUID when possible
      const resolution = await resolveWriteBoardId(legacyBoardId, {
        projectCode: input.projectCode ?? 'all',
        boardName: resolvedBoardName,
        boardType: 'recruitment',
      });
      const writeBoardId = resolution.writeBoardId;

      if (resolution.reason === 'legacy-fallback' || resolution.reason === 'input-passthrough') {
        console.warn('[filloutWebhook] legacy fallback for custom fields', {
          legacyBoardId,
          reason: resolution.reason,
        });
      }

      // Dual-read BoardColumns: UUID first, then legacy if different
      const { records: primaryCols } = await BoardColumns.findAll({
        filters: { boardId: writeBoardId },
        limit: 200,
      });

      let allCols = [...primaryCols];

      // If legacy differs from write, also fetch legacy cols to avoid duplicates
      if (resolution.legacyBoardId && resolution.legacyBoardId !== writeBoardId) {
        const { records: legacyCols } = await BoardColumns.findAll({
          filters: { boardId: resolution.legacyBoardId },
          limit: 200,
        });
        // Merge: add legacy cols not already present by name
        const existingNames = new Set(
          primaryCols.map(c => (c.columnName ?? '').toLowerCase()),
        );
        for (const lc of legacyCols) {
          if (lc.columnName && !existingNames.has(lc.columnName.toLowerCase())) {
            allCols.push(lc);
            existingNames.add(lc.columnName.toLowerCase());
          }
        }
      }

      const colByName = new Map<string, string>();
      for (const col of allCols) {
        if (col.columnName) colByName.set(col.columnName.toLowerCase(), col.id);
      }

      const cellRecords: Array<{
        boardId: string;
        rowId: string;
        columnId: string;
        textValue?: string;
      }> = [];

      for (const field of input.customFields) {
        if (!field.fieldName || field.value === undefined || field.value === '') continue;

        const key = field.fieldName.toLowerCase();
        let columnId = colByName.get(key);

        if (!columnId) {
          // Create new column under UUID boardId
          const newCol = await BoardColumns.create({
            record: {
              columnName: field.fieldName,
              boardId: writeBoardId,
              columnType: toColumnType(field.type),
              columnOrder: allCols.length + cellRecords.length,
            },
          });
          columnId = newCol.id;
          colByName.set(key, columnId);
        }

        // CellValues under UUID boardId
        cellRecords.push({ boardId: writeBoardId, rowId: record.id, columnId, textValue: field.value });
      }

      if (cellRecords.length > 0) {
        await CellValues.bulkCreate({ records: cellRecords });
        // cellData denormalization doesn't depend on boardId
        await RecruitmentRows.update({
          id: record.id,
          record: {
            cellData: JSON.stringify(
              Object.fromEntries(cellRecords.map(c => [c.columnId, { textValue: c.textValue }]))
            ),
          },
        });
      }
    }

    // ── 4. 4-level participation/duplicate detection ─────────────────────────
    // (No changes needed — searches by RecruitmentRows, not by boardId)
    const { records: allProjects } = await Projects.findAll({
      limit: 500,
      fields: ['projectCode', 'startDate', 'endDate', 'client'],
    });
    const projectDatesMap = new Map<string, ProjectDates>();
    for (const p of allProjects) {
      if (p.projectCode) projectDatesMap.set(p.projectCode, { startDate: p.startDate, endDate: p.endDate });
    }

    if (input.projectCode && (input.email || input.participantName || input.phone)) {
      try {
        const detectionFields: string[] = ['id', 'participantName', 'email', 'phone', 'projectCode', 'boardName', 'status', 'group', 'deletedAt'];
        const queries: Promise<{ records: any[] }>[] = [];
        if (input.email) {
          queries.push(RecruitmentRows.findAll({ filters: { email: input.email }, limit: 50, fields: detectionFields }));
        }
        if (input.participantName) {
          queries.push(RecruitmentRows.findAll({ filters: { participantName: { contains: input.participantName } }, limit: 50, fields: detectionFields }));
        }
        if (input.phone) {
          queries.push(RecruitmentRows.findAll({ filters: { phone: input.phone }, limit: 50, fields: detectionFields }));
        }
        const results = await Promise.all(queries);
        const seen = new Set<string>();
        const merged: any[] = [];
        for (const { records } of results) {
          for (const r of records) {
            if (!seen.has(r.id)) { seen.add(r.id); merged.push(r); }
          }
        }
        const activeExisting = merged.filter(r => !r.deletedAt);
        const note = buildParticipationNote(activeExisting, record.id, input.projectCode ?? '', resolvedBoardName, projectDatesMap);
        if (note) {
          await RecruitmentRows.update({ id: record.id, record: { notes: note } });
        }
      } catch { /* non-blocking */ }
    }

    return { success: true };
  },
});

