    included: z.boolean().optional(),
  }),
  outputSchema: z.object({ id: z.string() }),
  execute: async ({ input }) => {
    const { id, ...record } = input;
    if (id) {
      await Cotizaciones.update({ id, record });
      return { id };
    }
    const created = await Cotizaciones.create({ record });
    return { id: created.id };
  },
});

