}

// ── Profile popover content ───────────────────────────────────────────────────
function ProfilePopoverContent({ user, profilePhoto, onSave, onLogout }: {
  user: { firstName?: string; lastName?: string; email?: string; role?: string };
  profilePhoto?: string;
  onSave: (file: File) => Promise<void>;
  onLogout: () => void;
}) {
  const fullName = user.firstName ? `${user.firstName} ${user.lastName ?? ''}`.trim() : user.email ?? '';

  return (
    <div className="flex flex-col gap-3">
      {/* User info */}
      <div className="text-center pb-1 border-b border-border">
        <div className="text-sm font-semibold leading-tight">{fullName}</div>
        <div className="text-xs text-muted-foreground">{user.email}</div>
        <div className="text-[11px] text-muted-foreground/50 mt-0.5">{user.role ?? 'Usuario'}</div>
      </div>

      {/* Avatar crop editor */}
      <AvatarCropEditor currentPhotoUrl={profilePhoto} onSave={onSave} />

      {/* Logout */}
      <div className="border-t border-border pt-2">
        <button
          onClick={onLogout}
          className="w-full flex items-center justify-center gap-2 px-2 py-1.5 rounded-md text-sm text-destructive hover:bg-destructive/10 transition-colors"
        >
          <LogOut className="w-3.5 h-3.5" />
          Cerrar sesión
        </button>
      </div>
    </div>
  );
}

// ── Extracted project popover content ────────────────────────────────────────
function ProjectPopoverContent({
  search, setSearch, filtered, loadingProjects,
  selectedProject, setSelectedProject, setOpen, navigate, statusDot,
}: {
  search: string;
  setSearch: (v: string) => void;
  filtered: Project[];
  loadingProjects: boolean;
  selectedProject: string | null;
  setSelectedProject: (v: string | null) => void;
  setOpen: (v: boolean) => void;
  navigate: (to: string) => void;
  statusDot: Record<string, string>;
}) {
  return (
    <>
      <div className="flex items-center gap-1 mb-2">
        <Search className="w-4 h-4 text-muted-foreground" />
        <Input
          placeholder="Buscar proyecto..."
          value={search}
          onChange={e => setSearch(e.target.value)}
          className="h-7 text-sm border-0 focus-visible:ring-0 p-0"
          autoFocus
        />
      </div>
      {selectedProject && (
        <button
          className="w-full text-left px-2 py-1.5 text-xs text-muted-foreground hover:bg-muted rounded flex items-center gap-1 mb-1"
          onClick={() => { setSelectedProject(null); setOpen(false); }}
        >
          <X className="w-3 h-3" /> Limpiar selección
        </button>
      )}
      <ScrollArea className="max-h-48">
        {loadingProjects ? (
          <div className="space-y-1 px-1">
            {[1, 2, 3].map(i => <Skeleton key={i} className="h-8 w-full" />)}
          </div>
        ) : filtered.length === 0 ? (
          <div className="text-xs text-muted-foreground text-center py-4">Sin resultados</div>
        ) : (
          filtered.map(p => (
            <button
              key={p.id}
              className={`w-full text-left px-2 py-2 rounded text-sm hover:bg-muted flex items-center gap-2 transition-colors ${
                p.projectCode === selectedProject ? 'bg-accent text-accent-foreground font-semibold' : ''
              }`}
              onClick={() => { setSelectedProject(p.projectCode ?? null); setOpen(false); setSearch(''); navigate(`/operacion/proyectos/${p.projectCode}`); }}
            >
              <div className={`w-2 h-2 rounded-full flex-shrink-0 ${statusDot[p.status ?? ''] ?? 'bg-slate-300'}`} />
              <div>
                <div className="font-semibold text-xs">{p.projectCode}</div>
                <div className="text-xs text-muted-foreground truncate">{p.fullName}</div>
              </div>
            </button>
          ))
        )}
      </ScrollArea>
      <div className="border-t mt-2 pt-2">
        <button
          className="w-full text-left px-2 py-1.5 text-xs text-primary hover:bg-accent rounded flex items-center gap-1 transition-colors"
          onClick={() => { setOpen(false); navigate('/operacion/proyectos'); }}
        >
          <Plus className="w-3 h-3" /> Nuevo proyecto
        </button>
      </div>
    </>
  );
}

src/lib/ablyTokenCache.ts.content:
import { getAblyToken } from 'zite-endpoints-sdk';

type CachedToken = { token: string; expires: number };

const tokenCache = new Map<string, CachedToken>();
const inflightRequests = new Map<string, Promise<CachedToken | null>>();

/**
 * Get an Ably token for a channel, reusing cached tokens and deduplicating
 * in-flight requests. Two hooks subscribing to the same channel at the same
 * time will share a single getAblyToken call instead of firing two requests.
 */
export async function getCachedAblyToken(channel: string): Promise<CachedToken | null> {
  // Check cache — token is valid if it expires in more than 5 minutes
  const cached = tokenCache.get(channel);
  const now = Math.floor(Date.now() / 1000);
  if (cached && cached.expires - now > 300) {
    return cached;
  }

  // Deduplicate: if a request is already in-flight for this channel, reuse it
  const existing = inflightRequests.get(channel);
  if (existing) {
    return existing;
  }

  // Make the request and cache the result
  const promise = (async (): Promise<CachedToken | null> => {
    try {
      const res = await getAblyToken({ channels: [channel] });
      if (res.token && res.expires) {
        const result = { token: res.token, expires: res.expires };
        tokenCache.set(channel, result);
        return result;
      }
      return null;
    } catch {
      return null;
    } finally {
      inflightRequests.delete(channel);
    }
  })();

  inflightRequests.set(channel, promise);
  return promise;
}

/** Invalidate a cached token (e.g. after SSE error forces a reconnect) */
export function invalidateAblyToken(channel: string): void {
  tokenCache.delete(channel);
}

src/lib/pageVisibility.ts.content:
export interface PageDef {
  key: string;  // matches the exact label stored in the DB multiple_select field
  label: string;
  route: string;
}

export interface PageSectionDef {
  id: string;
  label: string;
  pages: PageDef[];
}

export const PAGE_SECTIONS_DEF: PageSectionDef[] = [
  {
    id: 'general',
    label: 'General',
    pages: [
      { key: 'Dashboard',  label: 'Dashboard', route: '/dashboard' },
      { key: 'Chat',       label: 'Chat',      route: '/chat' },
    ],
  },
  {
    id: 'comercial',
    label: 'Comercial',
    pages: [
      { key: 'CRM / Deals',          label: 'CRM / Deals',          route: '/comercial/crm' },
      { key: 'Dashboard comercial',  label: 'Dashboard comercial',  route: '/comercial/dashboard' },
      { key: 'Cotizaciones',         label: 'Cotizaciones',         route: '/comercial/cotizaciones' },
    ],
  },
  {
    id: 'operacion',
    label: 'Operación',
    pages: [
      { key: 'Proyectos', label: 'Proyectos', route: '/operacion/proyectos' },
    ],
  },
  {
    id: 'admin',
    label: 'Administración',
    pages: [
      { key: 'Órdenes de compra',       label: 'Órdenes de compra',       route: '/admin/ordenes' },
      { key: 'Proveedores',             label: 'Proveedores',             route: '/admin/proveedores' },
      { key: 'Pagos a proveedores',     label: 'Pagos a proveedores',     route: '/admin/pagos' },
      { key: 'Facturas de proveedores', label: 'Facturas de proveedores', route: '/admin/facturas-proveedores' },
      { key: 'Cobranza',                  label: 'Cobranza',                  route: '/admin/cobranza' },
      { key: 'Comprobación de gastos',   label: 'Comprobación de gastos',    route: '/admin/gastos' },
    ],
  },
  {
    id: 'finanzas',
    label: 'Finanzas',
    pages: [
      { key: 'Costos por proyecto',       label: 'Costos por proyecto',       route: '/finanzas/costos' },
      { key: 'Dashboard financiero',      label: 'Dashboard financiero',      route: '/finanzas/dashboard' },
    ],
  },
  {
    id: 'otros',
    label: 'Otros',
    pages: [
      { key: 'Tableros flexibles', label: 'Tableros flexibles', route: '/tableros' },
    ],
  },
];

// Maps route → DB label key (e.g. '/dashboard' → 'Dashboard')
export const ROUTE_TO_PAGE_KEY: Record<string, string> = Object.fromEntries(
  PAGE_SECTIONS_DEF.flatMap(s => s.pages.map(p => [p.route, p.key]))
);

// All valid DB label keys
export const ALL_PAGE_KEYS: string[] = PAGE_SECTIONS_DEF.flatMap(s => s.pages.map(p => p.key));

/**
 * Returns true if the given route should be visible.
 * Compares against DB-stored label values (e.g. "Dashboard", "CRM / Deals").
 * - userPages non-empty → use user's personal override
 * - userPages empty → use globalDefaultPages
 * - both empty → show everything (no restriction configured)
 */
export function isPageVisible(route: string, userPages: string[], defaultPages: string[]): boolean {
  const effective = (userPages?.length ?? 0) > 0 ? userPages : defaultPages;
  if (effective.length === 0) return true;
  const key = ROUTE_TO_PAGE_KEY[route];
  if (!key) return true;
  return effective.includes(key);
}

src/api/getBoardColumns.ts.content:
import { z } from 'zod';
import { createEndpoint, BoardColumns, Boards } from 'zite-integrations-backend-sdk';
import { resolveBoardId } from '../serverUtils/resolveBoardId';

const DEBUG =
  typeof process !== 'undefined' && process.env?.DEBUG_BOARD_RESOLUTION === 'true';

const LEGACY_PREFIX_RE = /^(pm-|cal-|recruitment-|events-)/;
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const SUFFIXES = ['::groups', '::children'] as const;

function extractSuffix(input: string): { base: string; suffix: string } {
  for (const s of SUFFIXES) {
    if (input.endsWith(s)) return { base: input.slice(0, -s.length), suffix: s };
  }
  return { base: input, suffix: '' };
}

export default createEndpoint({
  authenticated: true,
  description: 'Get dynamic columns for a board, sorted by order',
  inputSchema: z.object({ boardId: z.string() }),
  outputSchema: z.object({
    columns: z.array(
      z.object({
        id: z.string(),
        columnName: z.string().optional(),
        boardId: z.string().optional(),
        columnType: z.string().optional(),
        optionsJson: z.string().optional(),
        columnOrder: z.number().optional(),
      }),
    ),
  }),
  execute: async ({ input }) => {
    const originalBoardId = input.boardId;
    const isGroupsBoard = originalBoardId.endsWith('::groups');
    const isLegacyComposite = LEGACY_PREFIX_RE.test(
      originalBoardId.replace(/::groups$|::children$/, ''),
    );

    // ── NON-LEGACY PATH (UUID input) ──────────────────────────────────────────
    if (!isLegacyComposite) {
      const { base, suffix } = extractSuffix(originalBoardId);

      // If UUID, check if it's a recruitment board → merge-read UUID + legacy
      if (UUID_RE.test(base)) {
        const board = await Boards.findOne({ id: base });
        if (!board || board.deletedAt) return { columns: [] };

        if (board.boardType === 'recruitment') {
          // ── RECRUITMENT MERGE-READ: always read from UUID + legacy ─────────
          const legacyBase = `recruitment-${board.projectCode}-${board.boardName}`;
          const legacyId = suffix ? `${legacyBase}${suffix}` : legacyBase;
          const candidates = [originalBoardId];
          if (legacyId !== originalBoardId) candidates.push(legacyId);

          const seenIds = new Set<string>();
          const nameTypeKey = (name: string, type: string) =>
            `${(name || '').trim().toLowerCase()}::${(type || '').trim().toLowerCase()}`;
          const semanticMap = new Map<string, { col: any; isUUID: boolean }>();
          const allActive: any[] = [];

          for (const candidate of candidates) {
            const isUUIDCandidate = UUID_RE.test(candidate.replace(/::groups$|::children$/, ''));
            const { records } = await BoardColumns.findAll({
              filters: { boardId: candidate },
              limit: 500,
            });
            for (const r of records) {
              if (r.deletedAt) continue;
              // Layer 1: exact id dedupe
              if (seenIds.has(r.id)) continue;
              seenIds.add(r.id);
              // Layer 2: semantic dedupe by normalized name + type
              const ntk = nameTypeKey(r.columnName ?? '', r.columnType ?? '');
              const existing = semanticMap.get(ntk);
              if (existing) {
                if (existing.isUUID && !isUUIDCandidate) continue; // keep UUID version
                if (!existing.isUUID && isUUIDCandidate) {
                  // replace legacy with UUID version
                  const idx = allActive.indexOf(existing.col);
                  if (idx !== -1) allActive.splice(idx, 1);
                  semanticMap.set(ntk, { col: r, isUUID: isUUIDCandidate });
                  allActive.push(r);
                  continue;
                }
                // both same source type — keep both (different columns with same name)
              } else {
                semanticMap.set(ntk, { col: r, isUUID: isUUIDCandidate });
              }
              allActive.push(r);
            }
          }

          allActive.sort((a: any, b: any) => (a.columnOrder ?? 0) - (b.columnOrder ?? 0));

          if (DEBUG) {
            console.log(`[getBoardColumns] recruitment merge-read: ${allActive.length} column(s) from ${candidates.length} candidates`, candidates);
          }

          return { columns: allActive };
        }

        // ── NON-RECRUITMENT UUID: fast path (PM, Calendar, etc.) ─────────────
        const { records: fast } = await BoardColumns.findAll({
          filters: { boardId: originalBoardId },
          limit: 500,
        });
        const fastActive = fast.filter((r) => !r.deletedAt);
        const fastSorted = [...fastActive].sort((a, b) => (a.columnOrder ?? 0) - (b.columnOrder ?? 0));
        if (fastSorted.length > 0) {
          return { columns: fastSorted };
        }
        return { columns: [] };
      }

      // Non-UUID, non-legacy — unexpected format, return empty
      return { columns: [] };
    }

    // ── SLOW PATH: resolve boardId & try candidates ───────────────────────────
    // For legacy IDs we always enter here (columns may be split across legacy
    // and UUID boardIds after partial migration). For UUID IDs we enter only
    // if the fast path found nothing.
    const resolved = await resolveBoardId({
      boardIdOrKey: originalBoardId,
      fallbackToLegacy: true,
    });

    if (DEBUG) {
      console.log('[getBoardColumns] resolution:', {
        input: originalBoardId,
        resolvedBoardId: resolved.boardId,
        legacyBaseId: resolved.legacyBaseId,
        legacyCompositeId: resolved.legacyCompositeId,
        isLegacy: resolved.isLegacy,
        unresolvedLegacy: resolved.unresolvedLegacy ?? false,
        suffix: resolved.suffix,
      });
    }

    // ── Build deduplicated candidate list ─────────────────────────────────────
    const candidates: string[] = [originalBoardId];

    if (resolved.boardId && resolved.boardId !== originalBoardId) {
      candidates.push(resolved.boardId);
    }

    const legacyCandidate = resolved.legacyCompositeId;
    if (
      legacyCandidate &&
      legacyCandidate !== originalBoardId &&
      !candidates.includes(legacyCandidate)
    ) {
      candidates.push(legacyCandidate);
    }

    if (DEBUG) {
      console.log('[getBoardColumns] candidates:', candidates);
    }

    // ── MERGE-READ for ::groups OR legacy composites with multiple candidates ─
    // Columns may be split across legacy and UUID board IDs after partial
    // migration. Merge from ALL candidates and deduplicate by column id.
    if (candidates.length > 1 && (isGroupsBoard || isLegacyComposite)) {
      const seen = new Set<string>();
      const allActive: Array<typeof candidates extends any[] ? any : never> = [];

      for (const candidate of candidates) {
        const { records } = await BoardColumns.findAll({
          filters: { boardId: candidate },
          limit: 500,
        });
        for (const r of records) {
          if (r.deletedAt || seen.has(r.id)) continue;
          seen.add(r.id);
          allActive.push(r);
        }
      }

      allActive.sort((a: any, b: any) => (a.columnOrder ?? 0) - (b.columnOrder ?? 0));

      if (DEBUG) {
        console.log(`[getBoardColumns] merge-read: ${allActive.length} column(s) from ${candidates.length} candidates:`, candidates);
      }

      return { columns: allActive };
    }

    // ── FIRST-HIT: try each candidate in order (single candidate or UUID) ─────
    for (const candidate of candidates) {
      const { records } = await BoardColumns.findAll({
        filters: { boardId: candidate },
        limit: 500,
      });

      const active = records.filter((r) => !r.deletedAt);
      const sorted = [...active].sort(
        (a, b) => (a.columnOrder ?? 0) - (b.columnOrder ?? 0),
      );

      if (sorted.length > 0) {
        if (DEBUG) {
          const source =
            candidate === originalBoardId
              ? 'original'
              : candidate === resolved.boardId
                ? 'uuid'
                : 'legacy-composite';
          console.log(
            `[getBoardColumns] ${sorted.length} column(s) found via source="${source}" (candidate="${candidate}")`,
          );
        }
        return { columns: sorted };
      }
    }

    if (DEBUG) {
      console.log('[getBoardColumns] no columns found for any candidate:', candidates);
    }

    return { columns: [] };
  },
});

