import { z } from 'zod';
import { createEndpoint, Participants } from 'zite-integrations-backend-sdk';

const participantSchema = z.object({
  id: z.string(),
  fullName: z.string().optional(),
  email: z.string().optional(),
  phone: z.string().optional(),
  idNumber: z.string().optional(),
  city: z.string().optional(),
  gender: z.string().optional(),
  age: z.number().optional(),
  totalSessions: z.number().optional(),
  notes: z.string().optional(),
});

export default createEndpoint({
  authenticated: true,
  description: 'Search participants globally',
  inputSchema: z.object({ search: z.string().optional() }),
  outputSchema: z.object({ participants: z.array(participantSchema) }),
  execute: async ({ input }) => {
    const { records } = await Participants.findAll({ limit: 500 });
    const filtered = input.search
      ? records.filter(r =>
          r.fullName?.toLowerCase().includes(input.search!.toLowerCase()) ||
          r.email?.toLowerCase().includes(input.search!.toLowerCase()) ||
          r.idNumber?.toLowerCase().includes(input.search!.toLowerCase())
        )
      : records;
    return { participants: filtered };
  },
});

src/api/getTaskComments.ts.content:
import { z } from 'zod';
import { createEndpoint, TaskComments } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Get chat comments/mentions for a specific task',
  authenticated: true,
  inputSchema: z.object({
    taskId: z.string(),
  }),
  outputSchema: z.object({
    comments: z.array(z.object({
      id: z.string(),
      messageId: z.string().optional(),
      taskName: z.string().optional(),
      channel: z.string().optional(),
      senderName: z.string().optional(),
      senderEmail: z.string().optional(),
      content: z.string().optional(),
      sentAt: z.string().optional(),
      isThreadReply: z.boolean().optional(),
    })),
  }),
  execute: async ({ input }) => {
    const { records } = await TaskComments.findAll({
      filters: { taskId: input.taskId },
      limit: 100,
      fields: ['taskId', 'messageId', 'taskName', 'channel', 'senderName', 'senderEmail', 'content', 'sentAt', 'isThreadReply'],
    });

    // Sort by sentAt ascending
    const sorted = records
      .filter(r => r.sentAt)
      .sort((a, b) => (a.sentAt! < b.sentAt! ? -1 : 1));

    return {
      comments: sorted.map(r => ({
        id: r.id,
        messageId: r.messageId ?? undefined,
        taskName: r.taskName ?? undefined,
        channel: r.channel ?? undefined,
        senderName: r.senderName ?? undefined,
        senderEmail: r.senderEmail ?? undefined,
        content: r.content ?? undefined,
        sentAt: r.sentAt ?? undefined,
        isThreadReply: r.isThreadReply ?? undefined,
      })),
    };
  },
});

src/api/getUnreadCounts.ts.content:
import { z } from 'zod';
import { createEndpoint, Messages } from 'zite-integrations-backend-sdk';

function stripMarkdown(text: string): string {
  if (text.startsWith('{"type":"poll"')) return '📊 Encuesta';
  return text
    .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
    .replace(/[*_~`#]/g, '')
    .trim();
}

export default createEndpoint({
  authenticated: true,
  description: 'Get unread message counts per channel, detect mention channels, and return last message preview per channel',
  inputSchema: z.object({
    channels: z.array(z.string()),
    lastReadTimestamps: z.record(z.string(), z.string()),
    mentionName: z.string().optional(),
  }),
  outputSchema: z.object({
    counts: z.record(z.string(), z.number()),
    mentionChannels: z.array(z.string()),
    lastMessageAt: z.record(z.string(), z.string()),
    lastMessagePreview: z.record(z.string(), z.object({ content: z.string(), senderName: z.string() })),
  }),
  execute: async ({ input, context }) => {
    const channelSet = new Set(input.channels.slice(0, 500));
    if (channelSet.size === 0) return { counts: {}, mentionChannels: [], lastMessageAt: {}, lastMessagePreview: {} };

    // Always look back at least 7 days so lastMessagePreview is populated for
    // all channels with recent activity — even channels that have been fully read.
    const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
    const fallback = sevenDaysAgo;
    const timestamps = [...channelSet].map(ch => input.lastReadTimestamps[ch as string] ?? fallback);
    const minTimestamp = timestamps.reduce((min, t) => (t < min ? t : min), timestamps[0]);
    // Enforce a floor of 7 days so we never miss previews for read-but-old channels
    const effectiveMin = minTimestamp < sevenDaysAgo ? minTimestamp : sevenDaysAgo;

    const { records } = await Messages.findAll({
      filters: { sentAt: { gt: effectiveMin } } as any,
      limit: 2000,
      sort: [{ field: 'sentAt', direction: 'desc' }],
      fields: ['channel', 'senderEmail', 'senderName', 'parentMessageId', 'sentAt', 'content'],
    } as any);

    const counts: Record<string, number> = {};
    const lastMessageAt: Record<string, string> = {};
    const lastMessagePreview: Record<string, { content: string; senderName: string }> = {};
    for (const channel of channelSet) counts[channel as string] = 0;
    const mentionSet = new Set<string>();
    const nameLower = input.mentionName?.trim().toLowerCase();
    const myEmailLower = context.user!.email.toLowerCase();

    for (const m of records) {
      if (!m.channel || !channelSet.has(m.channel)) continue;
      if (m.parentMessageId) continue;
      if (!m.sentAt) continue;

      // Track latest message timestamp and preview for ALL messages (including own)
      if (!lastMessageAt[m.channel] || m.sentAt > lastMessageAt[m.channel]) {
        lastMessageAt[m.channel] = m.sentAt;
        const rawContent = m.content ?? '';
        const cleanContent = stripMarkdown(rawContent).slice(0, 80);
        lastMessagePreview[m.channel] = {
          content: cleanContent || '📎 Archivo',
          senderName: m.senderName ?? m.senderEmail?.split('@')[0] ?? 'Desconocido',
        };
      }

      // Never count the user's own messages as unread
      if (m.senderEmail && m.senderEmail.toLowerCase() === myEmailLower) continue;

      const lastRead = input.lastReadTimestamps[m.channel];
      const isUnread = !lastRead || new Date(m.sentAt) > new Date(lastRead);
      if (!isUnread) continue;

      counts[m.channel] = (counts[m.channel] ?? 0) + 1;

      if (nameLower && (m.content ?? '').toLowerCase().includes(`@${nameLower}`)) {
        mentionSet.add(m.channel);
      }
    }

    return { counts, mentionChannels: [...mentionSet], lastMessageAt, lastMessagePreview };
  },
});

src/api/importExcelData.ts.content:
import { z } from 'zod';
import { createEndpoint, RecruitmentRows, Boards, BoardColumns, CellValues, Projects } from 'zite-integrations-backend-sdk';
import { resolveWriteBoardId } from '../serverUtils/smartWrite';

const GROUP_COLOR_IDS = ['chart1', 'chart2', 'chart3', 'chart4', 'chart5', 'primary', 'destructive', 'muted'];

const colMappingSchema = z.object({
  excelIndex:        z.number(),
  target:            z.enum(['participantName', 'email', 'phone', 'idNumber', 'status', 'skip', 'dynamic']),
  dynamicColumnName: z.string().optional(),
  included:          z.boolean(),
});

const duplicateSchema = z.object({
  rowIndex:       z.number(),
  name:           z.string(),
  email:          z.string(),
  phone:          z.string(),
  level:          z.enum(['same_client', 'already_participated', 'external_duplicate', 'same_project', 'same_board']),
  matchedProject: z.string(),
  matchedBoard:   z.string(),
  matchedStatus:  z.string(),
  matchedBy:      z.enum(['email', 'name', 'phone']),
});

// ── Helpers ──────────────────────────────────────────────────────────────────
const normalize = (s: string) =>
  s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();

const LEVEL_RANK: Record<string, number> = {
  same_client:          5,
  already_participated: 4,
  external_duplicate:   3,
  same_project:         2,
  same_board:           1,
};

export default createEndpoint({
  description: 'Import parsed Excel/CSV rows into a recruitment board, with full 4-level duplicate detection.',
  authenticated: true,
  inputSchema: z.object({
    boardId:         z.string(),
    boardName:       z.string(),
    projectCode:     z.string(),
    currentClient:   z.string().optional(), // for same-client detection
    createNewBoard:  z.boolean().optional(),
    newBoardName:    z.string().optional(),
    columnMapping:   z.array(colMappingSchema),
    groups:          z.array(z.object({ name: z.string(), rowIndices: z.array(z.number()) })),
    groupDecisions:  z.array(z.object({ name: z.string(), action: z.enum(['create', 'skip']) })).optional(),
    rows:            z.array(z.array(z.string())),
    dryRun:          z.boolean().optional(),
    skipDuplicates:  z.boolean().optional(),
  }),
  outputSchema: z.object({
    imported:        z.number(),
    groupsCreated:   z.number(),
    columnsCreated:  z.number(),
    newBoardName:    z.string().optional(),
    duplicates:      z.array(duplicateSchema),
    newCount:        z.number(),
    duplicateCount:  z.number(),
  }),
  execute: async ({ input }) => {
    const effectiveCreateNewBoard = (input.createNewBoard ?? false) || !input.boardId;
    const targetBoardName = effectiveCreateNewBoard && input.newBoardName?.trim()
      ? input.newBoardName.trim()
      : input.boardName;
    const targetBoardId = input.boardId;

    // ── Helper: get mapped value from row ─────────────────────────────────
    const includedMappings = input.columnMapping.filter(m => m.included);
    const getVal = (row: string[], target: string) => {
      let val = '';
      for (const m of includedMappings) {
        if (m.target === target) {
          const v = (row[m.excelIndex] ?? '').trim();
          if (v) val = v;
        }
      }
      return val;
    };

    // ── Duplicate detection (mirrors recalculateDuplicateNotes logic) ─────
    const duplicates: z.infer<typeof duplicateSchema>[] = [];
    const duplicateRowIndices = new Set<number>();

    // Always run duplicate detection unless creating a brand-new board
    if (!effectiveCreateNewBoard) {
      // 1. Fetch ALL active rows across ALL projects
      type AnyRow = { id: string; participantName?: string; email?: string; phone?: string; projectCode?: string; boardName?: string; status?: string; group?: string; deletedAt?: string };
      const allRows: AnyRow[] = [];
      let offset = 0;
      while (true) {
        const { records, hasMore } = await RecruitmentRows.findAll({
          limit: 2000, offset,
          fields: ['id', 'participantName', 'email', 'phone', 'projectCode', 'boardName', 'status', 'group', 'deletedAt'],
        });
        allRows.push(...records.filter(r => !r.deletedAt));
        if (!hasMore) break;
        offset += records.length;
      }

      // 2. Fetch project dates
      const { records: allProjects } = await Projects.findAll({
        limit: 500,
        fields: ['projectCode', 'startDate', 'endDate', 'client'],
      });
      const projectDatesMap = new Map<string, { startDate?: string; endDate?: string; client?: string }>();
      for (const p of allProjects) {
        if (p.projectCode) projectDatesMap.set(p.projectCode, { startDate: p.startDate ?? undefined, endDate: p.endDate ?? undefined, client: p.client ?? undefined });
      }

      // 3. Build lookup maps
      const emailMap = new Map<string, AnyRow[]>();
      const nameMap  = new Map<string, AnyRow[]>();
      const phoneMap = new Map<string, AnyRow[]>();

      for (const r of allRows) {
        if (r.email) {
          const k = r.email.toLowerCase().trim();
          if (!emailMap.has(k)) emailMap.set(k, []);
          emailMap.get(k)!.push(r);
        }
        if (r.participantName) {
          const k = normalize(r.participantName);
          if (k.length > 2) {
            if (!nameMap.has(k)) nameMap.set(k, []);
            nameMap.get(k)!.push(r);
          }
        }
        if (r.phone) {
          const k = r.phone.replace(/[\s\-().+]/g, '');
          if (k.length >= 7) {
            if (!phoneMap.has(k)) phoneMap.set(k, []);
            phoneMap.get(k)!.push(r);
          }
        }
      }

      const currentDates = projectDatesMap.get(input.projectCode);
      const currentStart = currentDates?.startDate ? new Date(currentDates.startDate) : null;
      const sixMonthsAgo = new Date();
      sixMonthsAgo.setMonth(sixMonthsAgo.getMonth() - 6);

      // 4. For each Excel row, find matches and classify
      for (let idx = 0; idx < input.rows.length; idx++) {
        const row   = input.rows[idx];
        const email = getVal(row, 'email').toLowerCase().trim();
        const name  = normalize(getVal(row, 'participantName'));
        const phone = getVal(row, 'phone').replace(/[\s\-().+]/g, '');

        // Gather all matching existing rows with the field that matched
        const candidates: { row: AnyRow; matchedBy: 'email' | 'name' | 'phone' }[] = [];
        const seen = new Set<string>();

        const addCandidates = (rows: AnyRow[], by: 'email' | 'name' | 'phone') => {
          for (const r of rows) {
            if (!seen.has(r.id)) { seen.add(r.id); candidates.push({ row: r, matchedBy: by }); }
          }
        };

        if (email) addCandidates(emailMap.get(email) ?? [], 'email');
        if (name.length > 2) addCandidates(nameMap.get(name) ?? [], 'name');
        if (phone.length >= 7) addCandidates(phoneMap.get(phone) ?? [], 'phone');

        if (candidates.length === 0) continue;

        // 5. Classify each candidate — keep worst level
        let worstLevel: z.infer<typeof duplicateSchema>['level'] | null = null;
        let worstCandidate: { row: AnyRow; matchedBy: 'email' | 'name' | 'phone' } | null = null;

        for (const c of candidates) {
          const r = c.row;
          if (!r.projectCode) continue;

          let level: z.infer<typeof duplicateSchema>['level'];

          const sameProject = r.projectCode === input.projectCode;
          const sameBoard   = sameProject && r.boardName === targetBoardName;

          const normalizeStr = (s?: string) => (s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
          const otherClient = projectDatesMap.get(r.projectCode)?.client;
          const sameClient  = !sameProject && !!input.currentClient && !!otherClient &&
            normalizeStr(otherClient) === normalizeStr(input.currentClient);

          if (sameBoard) {
            level = 'same_board';
          } else if (sameProject) {
            level = 'same_project';
          } else {
            // Cross-project: classify as red (same_client / already_participated) or blue (external_duplicate)
            const participated = r.status === 'Asistió' || (!!r.group && r.group.trim() !== '');
            const otherDates   = projectDatesMap.get(r.projectCode);
            const otherEnd     = otherDates?.endDate ? new Date(otherDates.endDate) : null;
            // Active or recently ended (< 6 months)
            const isRecentOrActive = !otherEnd || otherEnd > sixMonthsAgo;
            if (sameClient && participated) {
              // Same client AND participated → red warning
              level = 'same_client';
            } else if (participated && isRecentOrActive) {
              // Participated recently or still active in another project → red
              level = 'already_participated';
            } else {
              // Old participation (> 6mo) or no participation → blue
              level = 'external_duplicate';
            }
          }

          if (!worstLevel || LEVEL_RANK[level] > LEVEL_RANK[worstLevel]) {
            worstLevel = level;
            worstCandidate = c;
          }
        }

        if (worstLevel && worstCandidate) {
          duplicates.push({
            rowIndex:       idx,
            name:           getVal(row, 'participantName') || `Fila ${idx + 1}`,
            email:          getVal(row, 'email'),
            phone:          getVal(row, 'phone'),
            level:          worstLevel,
            matchedProject: worstCandidate.row.projectCode ?? '',
            matchedBoard:   worstCandidate.row.boardName   ?? '',
            matchedStatus:  worstCandidate.row.status      ?? '',
            matchedBy:      worstCandidate.matchedBy,
          });
          duplicateRowIndices.add(idx);
        }
      }
    }

    const newCount       = input.rows.length - duplicateRowIndices.size;
    const duplicateCount = duplicates.length;

    // ── Dry run — just return analysis ────────────────────────────────────
    if (input.dryRun) {
      return { imported: 0, groupsCreated: 0, columnsCreated: 0, duplicates, newCount, duplicateCount };
    }

    // ── Resolve / create target board ─────────────────────────────────────
    let resolvedBoardId = targetBoardId;
    let legacyBoardId: string | undefined = targetBoardId;

    if (effectiveCreateNewBoard && input.newBoardName?.trim()) {
      const { records: existing } = await Boards.findAll({ filters: { projectCode: input.projectCode }, limit: 200 });
      const created = await Boards.create({ record: { boardName: input.newBoardName.trim(), projectCode: input.projectCode, boardOrder: existing.length } });
      resolvedBoardId = created.id;
      legacyBoardId = targetBoardId;
      console.log('[importExcelData] New board created with UUID', { resolvedBoardId, legacyBoardId });
    } else {
      // Existing board — resolve to UUID
      try {
        const res = await resolveWriteBoardId(targetBoardId);
        resolvedBoardId = res.writeBoardId;
        legacyBoardId = res.legacyBoardId ?? targetBoardId;
        if (res.reason === 'legacy-fallback' || res.reason === 'input-passthrough') {
          console.warn('[importExcelData] Board UUID not found, using legacy', { targetBoardId, reason: res.reason });
        }
      } catch (err) {
        console.warn('[importExcelData] resolveWriteBoardId failed', { targetBoardId, error: String(err) });
      }
    }

    // ── Resolve UUID for groups board ID ────────────────────────────────
    const groupsBoardId = `${resolvedBoardId}::groups`;

    // ── Build group decision lookup ───────────────────────────────────────
    const groupDecisionMap = new Map<string, 'create' | 'skip'>();
    if (input.groupDecisions) {
      for (const gd of input.groupDecisions) groupDecisionMap.set(gd.name, gd.action);
    }

    // ── Create group columns (only for groups with action 'create') ──────
    const groupColMap = new Map<string, string>();
    let groupsCreated = 0;
    for (let i = 0; i < input.groups.length; i++) {
      const g = input.groups[i];
      const action = groupDecisionMap.get(g.name) ?? 'create';
      if (action === 'skip') continue;
      const rec = await BoardColumns.create({
        record: { columnName: g.name, boardId: groupsBoardId, columnType: GROUP_COLOR_IDS[i % GROUP_COLOR_IDS.length], columnOrder: i },
      });
      groupColMap.set(g.name, rec.id);
      groupsCreated++;
    }

    // ── Create dynamic columns ─────────────────────────────────────────────
    const dynColMap    = new Map<string, string>();
    let columnsCreated = 0;
    const dynamicMappings = input.columnMapping.filter(m => m.included && m.target === 'dynamic' && m.dynamicColumnName);

    // Dual-read: UUID first, then legacy fallback
    const { records: existingColsUuid } = await BoardColumns.findAll({ filters: { boardId: resolvedBoardId }, limit: 200 });
    let existingCols = [...existingColsUuid];

    if (legacyBoardId && legacyBoardId !== resolvedBoardId) {
      const { records: existingColsLegacy } = await BoardColumns.findAll({ filters: { boardId: legacyBoardId }, limit: 200 });
      // Deduplicate by columnName — prefer UUID version
      const seenNames = new Set(existingCols.map(c => c.columnName?.toLowerCase() ?? ''));
      for (const lc of existingColsLegacy) {
        if (!seenNames.has(lc.columnName?.toLowerCase() ?? '')) {
          existingCols.push(lc);
          seenNames.add(lc.columnName?.toLowerCase() ?? '');
        }
      }
    }
    const existingByName = new Map(existingCols.map(c => [c.columnName?.toLowerCase() ?? '', c.id]));

    for (let i = 0; i < dynamicMappings.length; i++) {
      const name = dynamicMappings[i].dynamicColumnName!;
      const key  = name.toLowerCase();
      if (existingByName.has(key)) {
        dynColMap.set(name, existingByName.get(key)!);
      } else {
        const rec = await BoardColumns.create({
          record: { columnName: name, boardId: resolvedBoardId, columnType: 'Texto', columnOrder: existingCols.length + i },
        });
        dynColMap.set(name, rec.id);
        columnsCreated++;
      }
    }

    // ── Build row → group lookup ───────────────────────────────────────────
    const rowToGroup = new Map<number, string>();
    for (const g of input.groups) {
      for (const idx of g.rowIndices) rowToGroup.set(idx, g.name);
    }

    // ── Filter rows if skipDuplicates ──────────────────────────────────────
    const rowsToImport = input.skipDuplicates
      ? input.rows.map((r, i) => ({ row: r, excelIdx: i })).filter(({ excelIdx }) => !duplicateRowIndices.has(excelIdx))
      : input.rows.map((r, i) => ({ row: r, excelIdx: i }));

    // ── BulkCreate recruitment rows ────────────────────────────────────────
    const rowPayloads = rowsToImport.map(({ row, excelIdx }) => {
      const name = getVal(row, 'participantName') || `Participante ${excelIdx + 1}`;
      const explicitStatus = getVal(row, 'status');
      // Determine default status: if participant belongs to a group marked 'create', default to 'Asistió'
      let defaultStatus = 'Pendiente';
      const groupName = rowToGroup.get(excelIdx);
      if (groupName) {
        const action = groupDecisionMap.get(groupName) ?? 'create';
        if (action === 'create') defaultStatus = 'Asistió';
      }
      return {
        excelIdx,
        record: {
          rowName:         name,
          participantName: name,
          email:           getVal(row, 'email')    || undefined,
          phone:           getVal(row, 'phone')    || undefined,
          idNumber:        getVal(row, 'idNumber') || undefined,
          status:          explicitStatus || defaultStatus,
          projectCode:     input.projectCode,
          boardName:       targetBoardName,
          boardId:         resolvedBoardId,
          level:           0,
        },
      };
    });

    const createdIds: Array<{ id: string; excelIdx: number }> = [];
    for (let i = 0; i < rowPayloads.length; i += 100) {
      const batch = rowPayloads.slice(i, i + 100);
      const res   = await RecruitmentRows.bulkCreate({ records: batch.map(b => b.record) });
      res.records.forEach((r, j) => createdIds.push({ id: r.id, excelIdx: batch[j].excelIdx }));
    }

    // ── BulkCreate cell values ─────────────────────────────────────────────
    const cellsToCreate: Array<{ boardId: string; rowId: string; columnId: string; textValue: string }> = [];
    for (const { id, excelIdx } of createdIds) {
      const row = input.rows[excelIdx];
      const cellGroupName = rowToGroup.get(excelIdx);
      if (cellGroupName && groupColMap.has(cellGroupName)) {
        cellsToCreate.push({ boardId: groupsBoardId, rowId: id, columnId: groupColMap.get(cellGroupName)!, textValue: '1' });
      }
      for (const m of dynamicMappings) {
        const val = (row[m.excelIndex] ?? '').trim();
        if (val && m.dynamicColumnName && dynColMap.has(m.dynamicColumnName)) {
          cellsToCreate.push({ boardId: resolvedBoardId, rowId: id, columnId: dynColMap.get(m.dynamicColumnName)!, textValue: val });
        }
      }
    }
    for (let i = 0; i < cellsToCreate.length; i += 100) {
      await CellValues.bulkCreate({ records: cellsToCreate.slice(i, i + 100) });
    }

    return {
      imported:      createdIds.length,
      groupsCreated,
      columnsCreated,
      newBoardName:  effectiveCreateNewBoard ? targetBoardName : undefined,
      duplicates,
      newCount:      createdIds.length,
      duplicateCount,
    };
  },
});

src/api/importSuppliers.ts.content:
import { z } from 'zod';
import { createEndpoint, Suppliers } from 'zite-integrations-backend-sdk';

const supplierRowSchema = z.object({
  supplierName: z.string(),
  taxId: z.string().optional(),
  email: z.string().optional(),
  address: z.string().optional(),
  personType: z.string().optional(),
  taxRegime: z.string().optional(),
  country: z.string().optional(),
  phone: z.string().optional(),
  categories: z.array(z.string()).optional(),
});

export default createEndpoint({
  description: 'Bulk import suppliers from a parsed Monday.com CSV, upsert by supplierName',
  authenticated: true,
  inputSchema: z.object({
    suppliers: z.array(supplierRowSchema),
  }),
  outputSchema: z.object({
    created: z.number(),
    total: z.number(),
  }),
  execute: async ({ input, context }) => {
    if (context.user!.role !== 'Owner' && context.user!.role !== 'Socio') {
      throw new Error('Solo los administradores pueden importar proveedores.');
    }

    const { suppliers } = input;
    if (suppliers.length === 0) return { created: 0, total: 0 };

    let created = 0;
    for (let i = 0; i < suppliers.length; i += 100) {
      const batch = suppliers.slice(i, i + 100);
      const res = await Suppliers.bulkCreate({
        records: batch,
        matchOn: ['supplierName'],
      });
      created += res.records.length;
    }

    return { created, total: suppliers.length };
  },
});

src/api/linkFilloutForm.ts.content:
import { z } from 'zod';
import { createEndpoint, BoardColumns } from 'zite-integrations-backend-sdk';
import { lookupBoardUUID } from '../serverUtils/resolveBoardId';

const normalize = (str: string) =>
  str.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();

const toColType = (type: string): string => {
  const t = (type ?? '').toLowerCase();
  if (['numberinput', 'number', 'currency'].includes(t)) return 'Número';
  if (['dateinput', 'date'].includes(t)) return 'Fecha';
  if (['datetimeinput', 'datetime'].includes(t)) return 'Datetime';
  if (['checkbox'].includes(t)) return 'Checkbox';
  if (['linearscale'].includes(t)) return 'Select';
  if (['dropdown', 'multiselect', 'ranking'].includes(t)) return 'Texto';
  if (['emailinput', 'email'].includes(t)) return 'Email';
  if (['phoneinput', 'phonenumber', 'phone'].includes(t)) return 'Teléfono';
  if (['fileinput', 'fileupload', 'file'].includes(t)) return 'Archivo';
  return 'Texto';
};

const matchCore = (name: string): string | null => {
  const n = normalize(name);
  if (n.includes('nombre') || n.includes('name')) return 'participantName';
  if (n.includes('email') || n.includes('correo')) return 'email';
  if (n.includes('telefono') || n.includes('phone') || n.includes('celular')) return 'phone';
  if (n.includes('documento') || n.includes('cedula') || n.includes('id doc')) return 'idNumber';
  return null;
};

const CORE_ALIASES: Record<string, string[]> = {
  participantName: ['participante', 'nombre', 'name', 'candidato', 'candidate', 'persona'],
  email:          ['email', 'correo', 'e-mail', 'mail'],
  phone:          ['telefono', 'teléfono', 'phone', 'celular', 'tel'],
  idNumber:       ['documento', 'cedula', 'cédula', 'id', 'identificacion', 'identificación'],
};

const toText = (rawVal: unknown): string => {
  if (rawVal == null) return '';
  if (typeof rawVal === 'string') return rawVal.trim();
  if (typeof rawVal === 'number' || typeof rawVal === 'boolean') return String(rawVal);
  if (Array.isArray(rawVal)) {
    if (rawVal.length > 0 && typeof rawVal[0] === 'object' && rawVal[0] !== null && 'url' in rawVal[0]) {
      return rawVal.map((f: any) => f.url ?? f.filename ?? '').filter(Boolean).join(', ');
    }
    return rawVal.map(v => String(v)).filter(Boolean).join(', ');
  }
  if (typeof rawVal === 'object' && rawVal !== null) {
    if ('url' in rawVal) return (rawVal as any).url ?? '';
    return JSON.stringify(rawVal);
  }
  return '';
};

export default createEndpoint({
  authenticated: true,
  description: 'Link a Fillout form to a recruitment board: reads questions, bulk-creates missing dynamic columns, stores linkage metadata, and immediately imports existing submissions.',
  inputSchema: z.object({
    formId: z.string(),
    formName: z.string(),
    boardId: z.string(),
    projectCode: z.string().optional(),
    boardName: z.string(),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    columnsCreated: z.number(),
    webhookUrl: z.string(),
    webhookRegistered: z.boolean(),
    initialImported: z.number(),
  }),
  execute: async ({ input, context }) => {
    const u = context.user;
    const deletedBy = [u.firstName, u.lastName].filter(Boolean).join(' ') || u.email;
    const apiKey = process.env.ZITE_FILLOUT_API_KEY ?? '';
    if (!apiKey) throw new Error('Fillout API key not configured');

    // ── 0. Resolve boardId to UUID ─────────────────────────────────────────
    const lookup = await lookupBoardUUID(
      input.projectCode ?? '',
      input.boardName,
      'recruitment',
    );
    const effectiveBoardId = lookup.found && lookup.uuid ? lookup.uuid : input.boardId;
    const legacyBoardId = lookup.legacyId;
    const boardIdChanged = effectiveBoardId !== input.boardId;

    if (lookup.found) {
      console.log('[linkFilloutForm] Resolved boardId to UUID', {
        input: input.boardId, uuid: effectiveBoardId,
      });
    } else {
      console.warn('[linkFilloutForm] UUID not found, using input boardId as fallback', {
        input: input.boardId, reason: lookup.reason,
      });
    }

    // ── 1. Fetch form questions ────────────────────────────────────────────
    const res = await fetch(`https://api.fillout.com/v1/api/forms/${input.formId}`, {
      headers: { Authorization: `Bearer ${apiKey}` },
    });
    if (!res.ok) throw new Error(`Error al obtener el formulario: ${res.status}`);
    const formData = await res.json();
    const questions: { id: string; name: string; type: string }[] = formData.questions ?? [];

    // ── 2. Get existing columns for this board (dual-read: UUID + legacy) ─
    const { records: uuidCols } = await BoardColumns.findAll({
      filters: { boardId: effectiveBoardId },
      limit: 200,
    });
    let existingCols = uuidCols;

    // Also check under legacy boardId if different — merge without duplicates
    if (boardIdChanged) {
      const { records: legacyCols } = await BoardColumns.findAll({
        filters: { boardId: input.boardId },
        limit: 200,
      });
      const seenIds = new Set(uuidCols.map(c => c.id));
      for (const lc of legacyCols) {
        if (!seenIds.has(lc.id)) existingCols.push(lc);
      }
    }

    // ── Guard: delete ALL existing __fillout_link__ sentinels for this board ──
    // Prevents duplicate sentinels from accumulating.
    const oldLinks = existingCols.filter(c => c.columnType === '__fillout_link__');
    for (const oldLink of oldLinks) {
      try {
        await BoardColumns.update({
          id: oldLink.id,
          record: { deletedAt: new Date().toISOString(), deletedBy },
        });
      } catch { /* best-effort */ }
    }

    const visibleCols = existingCols.filter(c => c.columnType !== '__fillout_link__');
    const visibleColCount = visibleCols.length;

    const colByNorm = new Map<string, string>();
    const colNameSet = new Set<string>();
    for (const col of visibleCols) {
      if (col.columnName) {
        colByNorm.set(normalize(col.columnName), col.id);
        colNameSet.add(col.columnName.toLowerCase());
      }
    }

    // ── 3. First pass: decide which columns need to be created ─────────────
    type PendingCol = { filloutId: string; name: string; type: string; orderOffset: number };
    const toCreate: PendingCol[] = [];
    const seenNames = new Set<string>();

    for (const q of questions) {
      const name = (q.name ?? '').trim();
      if (!name) continue;
      const normName = normalize(name);
      const coreKey = matchCore(name);

      if (coreKey) {
        const aliases = CORE_ALIASES[coreKey] ?? [];
        const found = aliases.some(a => colByNorm.has(a)) || colByNorm.has(normName);
        if (!found && !seenNames.has(normName)) {
          toCreate.push({ filloutId: q.id, name, type: q.type, orderOffset: toCreate.length });
          seenNames.add(normName);
        }
      } else {
        if (!colByNorm.has(normName) && !colNameSet.has(name.toLowerCase()) && !seenNames.has(normName)) {
          toCreate.push({ filloutId: q.id, name, type: q.type, orderOffset: toCreate.length });
          seenNames.add(normName);
        }
      }
    }

    // ── 4. Bulk-create all missing columns ────────────────────────────────
    if (toCreate.length > 0) {
      const batchSize = 100;
      for (let i = 0; i < toCreate.length; i += batchSize) {
        const batch = toCreate.slice(i, i + batchSize);
        const created = await BoardColumns.bulkCreate({
          records: batch.map(c => ({
            columnName: c.name,
            boardId: effectiveBoardId,
            columnType: toColType(c.type),
            columnOrder: visibleColCount + c.orderOffset,
          })),
        });
        for (const r of created.records) {
          const nm = normalize(r.fields.columnName ?? '');
          if (nm) colByNorm.set(nm, r.id);
        }
      }
    }

    // ── 5. Second pass: build question → column mapping ────────────────────
    const questionMapping: { filloutId: string; columnId: string; questionName: string }[] = [];

    for (const q of questions) {
      const name = (q.name ?? '').trim();
      if (!name) continue;
      const normName = normalize(name);
      const coreKey = matchCore(name);

      let colId: string | undefined;
      if (coreKey) {
        const aliases = CORE_ALIASES[coreKey] ?? [];
        for (const alias of aliases) {
          if (colByNorm.has(alias)) { colId = colByNorm.get(alias); break; }
        }
        if (!colId) colId = colByNorm.get(normName);
      } else {
        colId = colByNorm.get(normName);
      }

      if (colId) questionMapping.push({ filloutId: q.id, columnId: colId, questionName: name });
    }

    // ── 6. Store linkage as a hidden sentinel column ───────────────────────
    //    boardId = UUID (primary destination for new submissions)
    //    legacyBoardId = legacy composite (reference only, not used for writes)
    await BoardColumns.create({
      record: {
        columnName: input.formName,
        boardId: effectiveBoardId,
        columnType: '__fillout_link__',
        columnOrder: 9999,
        optionsJson: JSON.stringify({
          formId: input.formId,
          formName: input.formName,
          boardId: effectiveBoardId,
          legacyBoardId: boardIdChanged ? legacyBoardId : undefined,
          projectCode: input.projectCode ?? '',
          boardName: input.boardName,
          linkedAt: new Date().toISOString(),
          questionMapping,
        }),
      },
    });

    // ── 7. (Webhook registration removed — not supported in this architecture) ─
    const webhookUrl = '';
    const webhookRegistered = false;

    // NOTE: Initial import of existing submissions is handled automatically
    // by checkNewSubmissions (lightweight polling) which fires 10s after linking.
    // Since lastSyncedAt is not set in the metadata above, the first poll will
    // fetch all submissions from the beginning.

    return { success: true, columnsCreated: toCreate.length, webhookUrl, webhookRegistered, initialImported: 0 };
  },
});

src/api/linkProjectDeal.ts.content:
import { z } from 'zod';
import { createEndpoint, Projects } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Link or unlink a deal from a project for P&L cost analysis',
  inputSchema: z.object({
    projectId: z.string(),
    dealId: z.string().optional(), // omit to unlink
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input }) => {
    await Projects.update({
      id: input.projectId,
      record: { dealVinculado: input.dealId ? [input.dealId] : [] },
    });
    return { success: true };
  },
});

src/api/publishDocEvent.ts.content:
import { z } from 'zod';
import { createEndpoint } from 'zite-integrations-backend-sdk';
import { publishEvent } from '../lib/ably';

export default createEndpoint({
  description: 'Publish ephemeral document lock events to Ably realtime channel',
  authenticated: true,
  inputSchema: z.object({
    docId: z.string(),
    eventType: z.enum(['block.lock', 'block.unlock', 'block.lock_heartbeat']),
    blockId: z.string(),
    lockId: z.string(),
    expiresAt: z.number().optional(),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    error: z.string().optional(),
  }),
  execute: async ({ input, context }) => {
    const { docId, eventType, blockId, lockId, expiresAt } = input;
    const userName =
      [context.user!.firstName, context.user!.lastName].filter(Boolean).join(' ') ||
      context.user!.email;

    const data = {
      docId,
      blockId,
      lockId,
      userId: context.user!.id,
      userEmail: context.user!.email,
      userName,
      expiresAt: expiresAt ?? Date.now() + 15000,
    };

    try {
      await publishEvent(`doc:${docId}`, eventType, data);
      return { success: true };
    } catch (err) {
      console.error('[publishDocEvent] failed:', (err as Error).message);
      return { success: false, error: 'publish failed' };
    }
  },
});

src/api/saveAppSettings.ts.content:
import { z } from 'zod';
import { createEndpoint, ZiteError, AppSettings } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Save global app settings (default visible pages). Requires admin access.',
  inputSchema: z.object({
    settingId: z.string().optional(),
    defaultVisiblePages: z.array(z.string()),
  }),
  outputSchema: z.object({ success: z.boolean(), id: z.string() }),
  execute: async ({ input, context }) => {
    const u = context.user!;
    const isAdmin =
      u.role === 'Owner' || u.role === 'Socio' ||
      u.accessComercial === 'Administrar' ||
      u.accessOperacion === 'Administrar' ||
      u.accessAdmin === 'Administrar' ||
      u.accessFinanzas === 'Administrar' ||
      u.accessOtros === 'Administrar';

    if (!isAdmin)
      throw new ZiteError({ code: 'FORBIDDEN', message: 'No tienes permisos para guardar configuración' });

    if (input.settingId) {
      await AppSettings.update({
        id: input.settingId,
        record: { defaultVisiblePages: input.defaultVisiblePages },
      });
      return { success: true, id: input.settingId };
    } else {
      const created = await AppSettings.create({
        record: { settingKey: 'default', defaultVisiblePages: input.defaultVisiblePages },
      });
      return { success: true, id: created.id };
    }
  },
});

src/api/saveBoardColumn.ts.content:
import { z } from 'zod';
import { createEndpoint, BoardColumns } from 'zite-integrations-backend-sdk';
import { resolveWriteBoardId } from '../serverUtils/smartWrite';

const SUFFIXES = ['::groups', '::children'] as const;

export default createEndpoint({
  authenticated: true,
  description: 'Create or update a board column definition. Uses resolveWriteBoardId for UUID migration. Dual-read anti-duplicate logic for create/upsert.',
  inputSchema: z.object({
    id: z.string().optional(),
    columnName: z.string(),
    boardId: z.string(),
    columnType: z.string().optional(),
    optionsJson: z.string().optional(),
    columnOrder: z.number().optional(),
  }),
  outputSchema: z.object({ success: z.boolean(), id: z.string() }),
  execute: async ({ input }) => {
    const { id, boardId: inputBoardId, columnName, columnType, optionsJson, columnOrder } = input;

    // ── Phase 1: Parse suffix ───────────────────────────────────────────
    let suffix = '' as '' | '::groups' | '::children';
    for (const s of SUFFIXES) {
      if (inputBoardId.endsWith(s)) { suffix = s; break; }
    }
    const originalBase = suffix ? inputBoardId.slice(0, -suffix.length) : inputBoardId;
    const isEventsBoard = originalBase.startsWith('events-');

    // ── Phase 2: Resolve write target ───────────────────────────────────
    let writeBoardId: string;
    let legacyBoardId: string | undefined;

    if (isEventsBoard) {
      writeBoardId = inputBoardId;
      legacyBoardId = undefined;
    } else {
      const resolution = await resolveWriteBoardId(originalBase);
      writeBoardId = suffix ? `${resolution.writeBoardId}${suffix}` : resolution.writeBoardId;

      if (resolution.legacyBoardId) {
        legacyBoardId = suffix ? `${resolution.legacyBoardId}${suffix}` : resolution.legacyBoardId;
      } else if (inputBoardId !== writeBoardId) {
        legacyBoardId = inputBoardId;
      } else {
        legacyBoardId = undefined;
      }

      if (resolution.reason === 'legacy-fallback' || resolution.reason === 'input-passthrough') {
        console.warn(`[saveBoardColumn] Could not resolve ${originalBase} to UUID — fallback (reason=${resolution.reason})`);
      }
    }

    // ── Phase 3a: UPDATE by id ──────────────────────────────────────────
    if (id) {
      const updateRecord: Record<string, unknown> = { boardId: writeBoardId, columnName };
      if (columnType !== undefined) updateRecord.columnType = columnType;
      if (optionsJson !== undefined) updateRecord.optionsJson = optionsJson;
      if (columnOrder !== undefined) updateRecord.columnOrder = columnOrder;

      await BoardColumns.update({ id, record: updateRecord });
      console.log(`[saveBoardColumn] action=updated id=${id} boardId=${writeBoardId} columnName=${columnName}`);
      return { success: true, id };
    }

    // ── Phase 3b: CREATE / UPSERT — dual-read anti-duplicate ────────────
    let existing: { id: string } | null = null;
    let foundUnder: 'uuid' | 'legacy' | null = null;

    // 1. Search under UUID boardId
    try {
      const { records } = await BoardColumns.findAll({
        filters: { boardId: writeBoardId, columnName },
        limit: 1,
      });
      const active = records.find(r => !r.deletedAt);
      if (active) { existing = active; foundUnder = 'uuid'; }
    } catch { /* no match */ }

    // 2. If not found, search under legacy boardId
    if (!existing && legacyBoardId && legacyBoardId !== writeBoardId) {
      try {
        const { records } = await BoardColumns.findAll({
          filters: { boardId: legacyBoardId, columnName },
          limit: 1,
        });
        const active = records.find(r => !r.deletedAt);
        if (active) { existing = active; foundUnder = 'legacy'; }
      } catch { /* no match */ }
    }

    // 3. Write
    if (existing && foundUnder === 'uuid') {
      // Already under UUID — update in place (only provided fields)
      const updateFields: Record<string, unknown> = {};
      if (columnType !== undefined) updateFields.columnType = columnType;
      if (optionsJson !== undefined) updateFields.optionsJson = optionsJson;
      if (columnOrder !== undefined) updateFields.columnOrder = columnOrder;

      if (Object.keys(updateFields).length > 0) {
        await BoardColumns.update({ id: existing.id, record: updateFields });
      }
      console.log(`[saveBoardColumn] action=updated boardId=${writeBoardId} columnName=${columnName}`);
      return { success: true, id: existing.id };
    }

    if (existing && foundUnder === 'legacy') {
      // Found under legacy — move to UUID + update all fields
      const moveRecord: Record<string, unknown> = { boardId: writeBoardId, columnName };
      if (columnType !== undefined) moveRecord.columnType = columnType;
      if (optionsJson !== undefined) moveRecord.optionsJson = optionsJson;
      if (columnOrder !== undefined) moveRecord.columnOrder = columnOrder;

      await BoardColumns.update({ id: existing.id, record: moveRecord });
      console.log(`[saveBoardColumn] action=moved from=${legacyBoardId} to=${writeBoardId} columnName=${columnName}`);
      return { success: true, id: existing.id };
    }

    // Not found — create under UUID
    const createRecord: Record<string, unknown> = { boardId: writeBoardId, columnName };
    if (columnType !== undefined) createRecord.columnType = columnType;
    if (optionsJson !== undefined) createRecord.optionsJson = optionsJson;
    if (columnOrder !== undefined) createRecord.columnOrder = columnOrder;

    const created = await BoardColumns.create({ record: createRecord });
    console.log(`[saveBoardColumn] action=created id=${created.id} boardId=${writeBoardId} columnName=${columnName}`);
    return { success: true, id: created.id };
  },
});

src/api/saveParticipant.ts.content:
import { z } from 'zod';
import { createEndpoint, Participants } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Create or update a participant',
  inputSchema: z.object({
    id: z.string().optional(),
    fullName: z.string().optional(),
    email: z.string().optional(),
    phone: z.string().optional(),
    idNumber: z.string().optional(),
    city: z.string().optional(),
    gender: z.string().optional(),
    age: z.number().optional(),
    totalSessions: z.number().optional(),
    notes: z.string().optional(),
  }),
  outputSchema: z.object({ success: z.boolean(), id: z.string() }),
  execute: async ({ input }) => {
    const { id, ...fields } = input;
    if (id) {
      await Participants.update({ id, record: fields });
      return { success: true, id };
    }
    const record = await Participants.create({ record: fields });
    return { success: true, id: record.id };
  },
});

src/pages/ExpensesPage.tsx.content:
import { useState, useEffect, useMemo, useCallback } from 'react';
import { useAuth } from 'zite-auth-sdk';
import {
  getExpenses, getPettyCashFunds, approveExpense, rejectExpense,
  submitExpense, deleteExpense, savePettyCashFund,
  GetExpensesOutputType, GetPettyCashFundsOutputType,
} from 'zite-endpoints-sdk';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Card, CardContent } from '@/components/ui/card';
import { Skeleton } from '@/components/ui/skeleton';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { ReceiptText, Plus, RefreshCw, Search, CheckCircle, XCircle, Trash2, Wallet, Clock, Pencil, Send, TrendingUp, DollarSign, ArrowUp } from 'lucide-react';
import { toast } from 'sonner';
import ExpenseFormSheet from '../components/expenses/ExpenseFormSheet';
import ExpenseDetailDialog from '../components/expenses/ExpenseDetailDialog';
import { COST_CENTERS } from '../lib/constants';

type Expense = GetExpensesOutputType['expenses'][0];
type Fund = GetPettyCashFundsOutputType['funds'][0];

const CATEGORIES = ['Viáticos', 'Transporte', 'Alimentación', 'Hospedaje', 'Compras menores', 'Papelería', 'Materiales', 'Otros'];
const PAYMENT_METHODS = ['Caja chica', 'Tarjeta corporativa', 'Reembolso empleado'];

const STATUSES = ['Borrador', 'Enviado a aprobación', 'Aprobado', 'Rechazado'];

const STATUS_STYLES: Record<string, string> = {
  'Borrador': 'bg-muted text-muted-foreground border-transparent',
  'Enviado a aprobación': 'border-amber-300 bg-amber-50 text-amber-800',
  'Aprobado': 'border-emerald-300 bg-emerald-50 text-emerald-800',
  'Rechazado': 'border-rose-300 bg-rose-50 text-rose-800',
};

function fmt(amount: number | null | undefined, currency = 'MXN') {
  if (amount == null) return '—';
  return new Intl.NumberFormat('es-MX', { style: 'currency', currency, minimumFractionDigits: 0, maximumFractionDigits: 2 }).format(amount);
}

function fmtDate(d: string | null | undefined) {
  if (!d) return '—';
  const [y, m, day] = d.split('-');
  return new Date(Number(y), Number(m) - 1, Number(day)).toLocaleDateString('es-MX', { day: '2-digit', month: 'short', year: 'numeric' });
}

function StatusBadge({ status }: { status: string | null | undefined }) {
  if (!status) return null;
  return (
    <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium border ${STATUS_STYLES[status] ?? 'bg-muted text-muted-foreground border-transparent'}`}>
      {status}
    </span>
  );
}

export default function ExpensesPage() {
  const { user } = useAuth();
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [loading, setLoading] = useState(true);
  const [funds, setFunds] = useState<Fund[]>([]);
  const [isFinance, setIsFinance] = useState(false);

  const [formOpen, setFormOpen] = useState(false);
  const [editExpense, setEditExpense] = useState<Expense | null>(null);
  const [pettyCashOpen, setPettyCashOpen] = useState(false);

  const [rejectOpen, setRejectOpen] = useState(false);
  const [rejectTarget, setRejectTarget] = useState<Expense | null>(null);
  const [rejectionReason, setRejectionReason] = useState('');
  const [rejecting, setRejecting] = useState(false);

  const [deleteTarget, setDeleteTarget] = useState<Expense | null>(null);
  const [deleting, setDeleting] = useState(false);
  const [approving, setApproving] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState<string | null>(null);

  const [filterStatus, setFilterStatus] = useState('');
  const [filterCategory, setFilterCategory] = useState('');
  const [filterMethod, setFilterMethod] = useState('');
  const [search, setSearch] = useState('');
  const [refresh, setRefresh] = useState(0);

  const [detailExpense, setDetailExpense] = useState<Expense | null>(null);
  const [detailOpen, setDetailOpen] = useState(false);

  const canApprove = ['Aprobador', 'Finanzas', 'Socios'].includes(user?.purchaseLevel ?? '');
  const isFinanceRole = ['Admin', 'Admin Financiero', 'Finanzas'].includes(user?.role ?? '');

  const loadExpenses = useCallback(async () => {
    setLoading(true);
    try {
      const r = await getExpenses({
        status: filterStatus || undefined,
        category: filterCategory || undefined,
        paymentMethod: filterMethod || undefined,
      });
      setExpenses(r.expenses);
      setIsFinance(r.isFinanceUser);
    } catch { toast.error('Error al cargar gastos'); }
    setLoading(false);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [filterStatus, filterCategory, filterMethod, refresh]);

  const loadFunds = useCallback(async () => {
    try { const r = await getPettyCashFunds({}); setFunds(r.funds); } catch { /* no permission */ }
  }, []);

  useEffect(() => { loadExpenses(); }, [loadExpenses]);
  useEffect(() => { loadFunds(); }, [loadFunds]);

  const filtered = useMemo(() => {
    if (!search.trim()) return expenses;
    const q = search.toLowerCase();
    return expenses.filter(e =>
      e.description?.toLowerCase().includes(q) ||
      e.category?.toLowerCase().includes(q) ||
      e.costCenter?.toLowerCase().includes(q) ||
      e.projectCode?.toLowerCase().includes(q)
    );
  }, [expenses, search]);

  const currentMonth = new Date().toISOString().slice(0, 7);
  const thisMonth = useMemo(() => expenses.filter(e => (e.expenseDate ?? '').startsWith(currentMonth)), [expenses, currentMonth]);
  const totalThisMonth = useMemo(() => thisMonth.reduce((s, e) => s + (e.amount ?? 0), 0), [thisMonth]);
  const pendingCount = useMemo(() => expenses.filter(e => e.status === 'Enviado a aprobación').length, [expenses]);
  const approvedCount = useMemo(() => thisMonth.filter(e => e.status === 'Aprobado').length, [thisMonth]);
  const cashBalance = useMemo(() => funds.filter(f => f.status === 'Activo').reduce((s, f) => s + (f.currentBalance ?? 0), 0), [funds]);

  const handleApprove = async (expense: Expense) => {
    setApproving(expense.id);
    try {
      await approveExpense({ id: expense.id });
      toast.success('Gasto aprobado');
      setRefresh(r => r + 1); loadFunds();
    } catch (e: unknown) { toast.error((e as { message?: string })?.message ?? 'Error al aprobar'); }
    setApproving(null);
  };

  const handleReject = async () => {
    if (!rejectTarget || !rejectionReason.trim()) return;
    setRejecting(true);
    try {
      await rejectExpense({ id: rejectTarget.id, rejectionReason: rejectionReason.trim() });
      toast.success('Gasto rechazado');
      setRefresh(r => r + 1);
      setRejectOpen(false); setRejectionReason(''); setRejectTarget(null);
    } catch (e: unknown) { toast.error((e as { message?: string })?.message ?? 'Error al rechazar'); }
    setRejecting(false);
  };

  const handleSubmitForApproval = async (expense: Expense) => {
    setSubmitting(expense.id);
    try {
      await submitExpense({ id: expense.id });
      toast.success('Enviado a aprobación');
      setRefresh(r => r + 1);
    } catch (e: unknown) { toast.error((e as { message?: string })?.message ?? 'Error al enviar'); }
    setSubmitting(null);
  };

  const handleDelete = async () => {
    if (!deleteTarget) return;
    setDeleting(true);
    try {
      await deleteExpense({ id: deleteTarget.id });
      toast.success('Gasto eliminado');
      setRefresh(r => r + 1); setDeleteTarget(null);
    } catch (e: unknown) { toast.error((e as { message?: string })?.message ?? 'Error al eliminar'); }
    setDeleting(false);
  };

  const handleUpdateExpense = useCallback((id: string, changes: Partial<Expense>) => {
    setExpenses(prev => prev.map(e => e.id === id ? { ...e, ...changes } : e));
    setDetailExpense(prev => prev?.id === id ? { ...prev, ...changes } : prev);
  }, []);

  const activeFunds = useMemo(() => funds.filter(f => f.status === 'Activo'), [funds]);

  return (
    <div className="p-6 space-y-5 max-w-7xl mx-auto">
      {/* Header */}
      <div className="flex items-center justify-between gap-4">
        <div className="flex items-center gap-2.5">
          <div className="w-8 h-8 rounded-lg bg-primary/10 flex items-center justify-center flex-shrink-0">
            <ReceiptText className="w-4 h-4 text-primary" />
          </div>
          <div>
            <h1 className="text-lg font-bold">Comprobación de Gastos</h1>
            <p className="text-xs text-muted-foreground">{isFinance ? 'Todos los gastos' : 'Mis gastos'}</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="outline" size="sm" onClick={() => setRefresh(r => r + 1)} className="gap-1.5">
            <RefreshCw className="w-3.5 h-3.5" /><span className="hidden sm:inline">Actualizar</span>
          </Button>
          <Button size="sm" onClick={() => { setEditExpense(null); setFormOpen(true); }} className="gap-1.5">
            <Plus className="w-3.5 h-3.5" /> Nuevo gasto
          </Button>
        </div>
      </div>

      {/* Summary cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        {[
          { icon: <DollarSign className="w-4 h-4 text-muted-foreground" />, label: 'Total este mes', value: fmt(totalThisMonth), sub: `${thisMonth.length} gasto${thisMonth.length !== 1 ? 's' : ''}` },
          { icon: <Clock className="w-4 h-4 text-amber-500" />, label: 'Pendientes', value: String(pendingCount), sub: 'Por aprobar' },
          { icon: <CheckCircle className="w-4 h-4 text-emerald-500" />, label: 'Aprobados', value: String(approvedCount), sub: 'Este mes' },
        ].map(c => (
          <Card key={c.label} className="border-border">
            <CardContent className="pt-4 pb-3 px-4">
              <div className="flex items-center gap-2 mb-2">{c.icon}<span className="text-xs text-muted-foreground">{c.label}</span></div>
              <div className="text-xl font-bold">{c.value}</div>
              <div className="text-[11px] text-muted-foreground mt-0.5">{c.sub}</div>
            </CardContent>
          </Card>
        ))}
        <Card className={`border-border transition-colors ${isFinanceRole ? 'cursor-pointer hover:border-primary/40 hover:bg-primary/5' : ''}`}
          onClick={() => isFinanceRole && setPettyCashOpen(true)}>
          <CardContent className="pt-4 pb-3 px-4">
            <div className="flex items-center gap-2 mb-2">
              <Wallet className="w-4 h-4 text-primary" />
              <span className="text-xs text-muted-foreground">Caja chica</span>
              {isFinanceRole && <span className="ml-auto text-[10px] text-primary font-semibold">Gestionar →</span>}
            </div>
            <div className="text-xl font-bold">{isFinanceRole ? fmt(cashBalance) : '—'}</div>
            <div className="text-[11px] text-muted-foreground mt-0.5">Saldo disponible</div>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <div className="flex flex-wrap items-center gap-2">
        <div className="relative flex-1 min-w-[180px] max-w-xs">
          <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground" />
          <Input placeholder="Buscar..." value={search} onChange={e => setSearch(e.target.value)} className="pl-8 h-8 text-sm" />
        </div>
        <Select value={filterStatus} onValueChange={setFilterStatus}>
          <SelectTrigger className="h-8 w-44 text-xs"><SelectValue placeholder="Todos los estatus" /></SelectTrigger>
          <SelectContent>{STATUSES.map(s => <SelectItem key={s} value={s} className="text-xs">{s}</SelectItem>)}</SelectContent>
        </Select>
        <Select value={filterCategory} onValueChange={setFilterCategory}>
          <SelectTrigger className="h-8 w-36 text-xs"><SelectValue placeholder="Categoría" /></SelectTrigger>
          <SelectContent>{CATEGORIES.map(c => <SelectItem key={c} value={c} className="text-xs">{c}</SelectItem>)}</SelectContent>
        </Select>
        <Select value={filterMethod} onValueChange={setFilterMethod}>
          <SelectTrigger className="h-8 w-40 text-xs"><SelectValue placeholder="Método de pago" /></SelectTrigger>
          <SelectContent>{PAYMENT_METHODS.map(m => <SelectItem key={m} value={m} className="text-xs">{m}</SelectItem>)}</SelectContent>
        </Select>
        {(filterStatus || filterCategory || filterMethod) && (
          <Button variant="ghost" size="sm" className="h-8 text-xs text-muted-foreground"
            onClick={() => { setFilterStatus(''); setFilterCategory(''); setFilterMethod(''); }}>
            Limpiar
          </Button>
        )}
      </div>

      {/* Table */}
      <div className="border border-border rounded-xl overflow-hidden bg-card">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-border bg-muted/40">
                {['#', 'Fecha', 'Descripción', 'Categoría', 'Método', 'Monto', 'Centro de costos', 'Estatus', 'Acciones'].map((h, i) => (
                  <th key={h} className={`px-4 py-2.5 text-xs font-semibold text-muted-foreground ${i >= 7 ? 'text-right' : 'text-left'} ${i === 3 ? 'hidden md:table-cell' : ''} ${i === 4 || i === 6 ? 'hidden lg:table-cell' : ''}`}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {loading ? (
                Array.from({ length: 5 }).map((_, i) => (
                  <tr key={i} className="border-b border-border/50">
                    {Array.from({ length: 9 }).map((_, j) => (
                      <td key={j} className="px-4 py-3"><Skeleton className="h-4 w-full" /></td>
                    ))}
                  </tr>
                ))
              ) : filtered.length === 0 ? (
                <tr>
                  <td colSpan={9} className="px-4 py-16 text-center">
                    <ReceiptText className="w-8 h-8 mx-auto mb-2 text-muted-foreground/40" />
                    <p className="text-sm text-muted-foreground">No hay gastos registrados</p>
                    <p className="text-xs text-muted-foreground/60 mt-0.5">Crea un nuevo gasto con el botón de arriba</p>
                  </td>
                </tr>
              ) : filtered.map(expense => (
                <tr key={expense.id} className="border-b border-border/50 hover:bg-muted/20 transition-colors cursor-pointer" onClick={() => { setDetailExpense(expense); setDetailOpen(true); }}>
                  <td className="px-4 py-3 text-xs text-muted-foreground font-mono">{expense.expenseNumber ?? '—'}</td>
                  <td className="px-4 py-3 text-xs text-muted-foreground whitespace-nowrap">{fmtDate(expense.expenseDate)}</td>
                  <td className="px-4 py-3">
                    <div className="font-medium text-sm truncate max-w-[200px]">{expense.description ?? '—'}</div>
                    <div className="flex items-center gap-2 flex-wrap mt-0.5">
                      {expense.projectCode && <span className="text-[11px] text-muted-foreground">{expense.projectCode}</span>}
                      {expense.lineItemCount > 0 && (
                        <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-primary/10 text-primary font-medium">
                          {expense.lineItemCount} partida{expense.lineItemCount !== 1 ? 's' : ''}
                        </span>
                      )}
                      {expense.lineItemCount === 0 && expense.receipt && expense.receipt.length > 0 && (
                        <a href={expense.receipt[0].url} target="_blank" rel="noopener noreferrer"
                          className="text-[11px] text-primary hover:underline">📎 comprobante</a>
                      )}
                    </div>
                  </td>
                  <td className="px-4 py-3 hidden md:table-cell text-xs text-muted-foreground">{expense.category ?? '—'}</td>
                  <td className="px-4 py-3 hidden lg:table-cell text-xs text-muted-foreground">{expense.paymentMethod ?? '—'}</td>
                  <td className="px-4 py-3 text-right font-semibold text-sm whitespace-nowrap">{fmt(expense.amount, expense.currency ?? 'MXN')}</td>
                  <td className="px-4 py-3 hidden lg:table-cell">
                    <span className="text-xs text-muted-foreground truncate block max-w-[130px]">{expense.costCenter ?? '—'}</span>
                  </td>
                  <td className="px-4 py-3">
                    <StatusBadge status={expense.status} />
                    {expense.status === 'Rechazado' && expense.rejectionReason && (
                      <p className="text-[11px] text-muted-foreground mt-0.5 truncate max-w-[120px]" title={expense.rejectionReason}>
                        {expense.rejectionReason}
                      </p>
                    )}
                  </td>
                  <td className="px-4 py-3" onClick={e => e.stopPropagation()}>
                    <div className="flex items-center justify-end gap-0.5">
                      {expense.status === 'Borrador' && (expense.createdBy === user?.email || isFinanceRole) && (
                        <Button variant="ghost" size="sm" className="h-7 w-7 p-0" title="Editar"
                          onClick={() => { setEditExpense(expense); setFormOpen(true); }}>
                          <Pencil className="w-3.5 h-3.5" />
                        </Button>
                      )}
                      {expense.status === 'Borrador' && expense.createdBy === user?.email && (
                        <Button variant="ghost" size="sm" className="h-7 w-7 p-0 text-primary" title="Enviar a aprobación"
                          disabled={submitting === expense.id} onClick={() => handleSubmitForApproval(expense)}>
                          <Send className="w-3.5 h-3.5" />
                        </Button>
                      )}
                      {expense.status === 'Enviado a aprobación' && canApprove && (
                        <Button variant="ghost" size="sm" className="h-7 w-7 p-0 text-emerald-600" title="Aprobar"
                          disabled={approving === expense.id} onClick={() => handleApprove(expense)}>
                          <CheckCircle className="w-3.5 h-3.5" />
                        </Button>
                      )}
                      {expense.status === 'Enviado a aprobación' && canApprove && (
                        <Button variant="ghost" size="sm" className="h-7 w-7 p-0 text-destructive" title="Rechazar"
                          onClick={() => { setRejectTarget(expense); setRejectOpen(true); }}>
                          <XCircle className="w-3.5 h-3.5" />
                        </Button>
                      )}
                      {expense.status === 'Borrador' && (expense.createdBy === user?.email || user?.role === 'Owner' || user?.role === 'Socio') && (
                        <Button variant="ghost" size="sm" className="h-7 w-7 p-0 text-destructive/50 hover:text-destructive" title="Eliminar"
                          onClick={() => setDeleteTarget(expense)}>
                          <Trash2 className="w-3.5 h-3.5" />
                        </Button>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        {!loading && filtered.length > 0 && (
          <div className="px-4 py-2 border-t border-border/50 text-xs text-muted-foreground text-right">
            {filtered.length} gasto{filtered.length !== 1 ? 's' : ''}
          </div>
        )}
      </div>

      {/* Expense form */}
      <ExpenseFormSheet
        open={formOpen}
        expense={editExpense}
        funds={activeFunds}
        canApprove={canApprove}
        userEmail={user?.email ?? ''}
        isFinanceRole={isFinanceRole}
        onSaved={() => setRefresh(r => r + 1)}
        onClose={() => { setFormOpen(false); setRefresh(r => r + 1); }}
      />

      {/* Reject dialog */}
      <Dialog open={rejectOpen} onOpenChange={v => { if (!v) { setRejectOpen(false); setRejectionReason(''); } }}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 text-base">
              <XCircle className="w-4 h-4 text-destructive" /> Rechazar gasto
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-3">
            <div className="bg-muted/50 rounded-lg px-3 py-2 text-sm">
              <span className="font-medium">{rejectTarget?.description}</span>
              <span className="text-muted-foreground"> — {fmt(rejectTarget?.amount, rejectTarget?.currency ?? 'MXN')}</span>
            </div>
            <div className="space-y-1.5">
              <Label className="text-xs font-medium">Motivo de rechazo *</Label>
              <Textarea value={rejectionReason} onChange={e => setRejectionReason(e.target.value)}
                placeholder="Explica el motivo..." className="text-sm min-h-[80px] resize-none" autoFocus />
            </div>
          </div>
          <DialogFooter className="gap-2">
            <Button variant="ghost" size="sm" onClick={() => setRejectOpen(false)} disabled={rejecting}>Cancelar</Button>
            <Button variant="destructive" size="sm" onClick={handleReject} disabled={rejecting || !rejectionReason.trim()}>
              {rejecting ? 'Rechazando...' : 'Rechazar'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Delete confirmation */}
      <AlertDialog open={!!deleteTarget} onOpenChange={v => { if (!v) setDeleteTarget(null); }}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>¿Eliminar este gasto?</AlertDialogTitle>
            <AlertDialogDescription>
              Se eliminará permanentemente "<strong>{deleteTarget?.description}</strong>". Esta acción no se puede deshacer.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleting}>Cancelar</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} disabled={deleting} className="bg-destructive hover:bg-destructive/90">
              {deleting ? 'Eliminando...' : 'Eliminar'}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Petty cash dialog */}
      {isFinanceRole && (
        <PettyCashDialog open={pettyCashOpen} onClose={() => setPettyCashOpen(false)}
          funds={funds} onRefresh={loadFunds} />
      )}

      {/* Expense detail dialog */}
      <ExpenseDetailDialog
        expense={detailExpense}
        open={detailOpen}
        onClose={() => setDetailOpen(false)}
        canApprove={canApprove}
        userEmail={user?.email ?? ''}
        isFinanceRole={isFinanceRole}
        onEdit={(exp) => { setDetailOpen(false); setEditExpense(exp); setFormOpen(true); }}
        onUpdate={handleUpdateExpense}
        onRefreshList={() => setRefresh(r => r + 1)}
      />
    </div>
  );
}

// ── Petty Cash Dialog ─────────────────────────────────────────────────────────
function PettyCashDialog({ open, onClose, funds, onRefresh }: {
  open: boolean; onClose: () => void; funds: Fund[]; onRefresh: () => void;
}) {
  const [newFundOpen, setNewFundOpen] = useState(false);
  const [replenishTarget, setReplenishTarget] = useState<Fund | null>(null);
  const [replenishAmount, setReplenishAmount] = useState('');
  const [saving, setSaving] = useState(false);
  const [newFund, setNewFund] = useState({ fundName: '', initialAmount: '', costCenter: '' });

  const handleReplenish = async () => {
    if (!replenishTarget || !replenishAmount) return;
    setSaving(true);
    try {
      await savePettyCashFund({ id: replenishTarget.id, action: 'replenish', replenishAmount: parseFloat(replenishAmount) });
      toast.success('Fondo repuesto correctamente');
      setReplenishTarget(null); setReplenishAmount(''); onRefresh();
    } catch (e: unknown) { toast.error((e as { message?: string })?.message ?? 'Error'); }
    setSaving(false);
  };

  const handleNewFund = async () => {
    if (!newFund.fundName || !newFund.initialAmount) return;
    setSaving(true);
    try {
      await savePettyCashFund({ action: 'save', fundName: newFund.fundName, initialAmount: parseFloat(newFund.initialAmount), costCenter: newFund.costCenter || undefined });
      toast.success('Fondo creado');
      setNewFundOpen(false); setNewFund({ fundName: '', initialAmount: '', costCenter: '' }); onRefresh();
    } catch (e: unknown) { toast.error((e as { message?: string })?.message ?? 'Error'); }
    setSaving(false);
  };

  return (
    <Dialog open={open} onOpenChange={v => { if (!v) onClose(); }}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-base">
            <Wallet className="w-4 h-4 text-primary" /> Fondos de Caja Chica
          </DialogTitle>
        </DialogHeader>
        <div className="max-h-[60vh] overflow-y-auto pr-1 space-y-3">
          <div className="space-y-3">
            {funds.length === 0 ? (
              <p className="text-sm text-muted-foreground text-center py-8">No hay fondos configurados</p>
            ) : funds.map(fund => (
              <div key={fund.id} className="border border-border rounded-xl p-4 space-y-3">
                <div className="flex items-start justify-between gap-2">
                  <div>
                    <div className="font-semibold text-sm">{fund.fundName ?? '—'}</div>
                    {fund.costCenter && <div className="text-xs text-muted-foreground">{fund.costCenter}</div>}
                  </div>
                  <span className={`text-xs px-2 py-0.5 rounded-full border ${fund.status === 'Activo' ? 'bg-emerald-50 text-emerald-700 border-emerald-200' : 'bg-muted text-muted-foreground border-transparent'}`}>
                    {fund.status}
                  </span>
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <div className="text-xs text-muted-foreground mb-0.5">Saldo actual</div>
                    <div className="text-lg font-bold">{fmt(fund.currentBalance)}</div>
                  </div>
                  <div>
                    <div className="text-xs text-muted-foreground mb-0.5">Fondo inicial</div>
                    <div className="text-sm font-medium text-muted-foreground">{fmt(fund.initialAmount)}</div>
                  </div>
                </div>
                {fund.lastReplenishmentDate && (
                  <p className="text-xs text-muted-foreground">Última reposición: {fmtDate(fund.lastReplenishmentDate)}</p>
                )}
                {fund.status === 'Activo' && (
                  replenishTarget?.id === fund.id ? (
                    <div className="flex items-center gap-2">
                      <Input type="number" placeholder="Monto a reponer" value={replenishAmount}
                        onChange={e => setReplenishAmount(e.target.value)} className="h-8 text-sm" autoFocus />
                      <Button size="sm" className="h-8 flex-shrink-0" onClick={handleReplenish} disabled={saving || !replenishAmount}>
                        {saving ? '...' : 'Reponer'}
                      </Button>
                      <Button variant="ghost" size="sm" className="h-8 w-8 p-0 flex-shrink-0"
                        onClick={() => { setReplenishTarget(null); setReplenishAmount(''); }}>×</Button>
                    </div>
                  ) : (
                    <Button variant="outline" size="sm" className="h-7 text-xs gap-1.5" onClick={() => setReplenishTarget(fund)}>
                      <ArrowUp className="w-3.5 h-3.5" /> Reponer fondo
                    </Button>
                  )
                )}
              </div>
            ))}
          </div>

          {!newFundOpen ? (
            <Button variant="outline" size="sm" className="gap-1.5 w-full" onClick={() => setNewFundOpen(true)}>
              <Plus className="w-3.5 h-3.5" /> Nuevo fondo
            </Button>
          ) : (
            <div className="border border-border rounded-xl p-4 space-y-3">
            <p className="text-sm font-semibold">Nuevo fondo de caja chica</p>
            <div className="space-y-1.5">
              <Label className="text-xs">Nombre *</Label>
              <Input value={newFund.fundName} onChange={e => setNewFund(p => ({ ...p, fundName: e.target.value }))} placeholder="Ej: Caja chica oficina" className="h-8 text-sm" />
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1.5">
                <Label className="text-xs">Monto inicial *</Label>
                <Input type="number" value={newFund.initialAmount} onChange={e => setNewFund(p => ({ ...p, initialAmount: e.target.value }))} placeholder="0.00" className="h-8 text-sm" />
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs">Centro de costos</Label>
                <Select value={newFund.costCenter} onValueChange={v => setNewFund(p => ({ ...p, costCenter: v }))}>
                  <SelectTrigger className="h-8 text-xs"><SelectValue placeholder="Seleccionar..." /></SelectTrigger>
                  <SelectContent>
                    {COST_CENTERS.map(cc => <SelectItem key={cc} value={cc} className="text-xs">{cc}</SelectItem>)}
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div className="flex justify-end gap-2">
              <Button variant="ghost" size="sm" onClick={() => setNewFundOpen(false)} disabled={saving}>Cancelar</Button>
              <Button size="sm" onClick={handleNewFund} disabled={saving || !newFund.fundName || !newFund.initialAmount}>
                {saving ? 'Creando...' : 'Crear fondo'}
              </Button>
            </div>
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

