import { z } from 'zod';
import { createEndpoint, Cotizaciones } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Delete a cotizacion',
  inputSchema: z.object({ id: z.string() }),
