src/api/getProjectBudget.ts.content:
import { z } from 'zod';
import { createEndpoint, Projects, Deals, Cotizaciones, CotizacionLineItems as CotizacionLineItemsSDK, Users } from 'zite-integrations-backend-sdk';

const RUBROS_ORDER = [
  'Reclutamiento e incentivos', 'Moderación', 'Management', 'Logística y operación', 'Back office',
];

export default createEndpoint({
  authenticated: true,
  description: 'Get project budget breakdown by rubro with permission-based filtering',
  inputSchema: z.object({ projectCode: z.string() }),
  outputSchema: z.object({
    canSeeAll: z.boolean(),
    rubros: z.array(z.object({
      rubroName: z.string(),
      lineItems: z.array(z.object({
        id: z.string(),
        subRubro: z.string(),
        cantidad: z.number(),
        componentes: z.number(),
        unitCost: z.number(),
        total: z.number(),
        cotizacionName: z.string(),
      })),
      assignedUsers: z.array(z.object({ id: z.string(), name: z.string() })),
      subtotalCotizado: z.number(),
    })),
    totals: z.object({ cotizado: z.number(), conMarkup: z.number() }),
    personas: z.array(z.object({ id: z.string(), name: z.string(), rubros: z.array(z.string()) })),
    currency: z.string(),
    dealName: z.string().optional(),
    projectCode: z.string().optional(),
  }),
  execute: async ({ input, context }) => {
    const user = context.user!;
    const canSeeAll =
      user.role === 'Owner' || user.role === 'Socio' ||
      user.accessFinanzas === 'Editar' || user.accessFinanzas === 'Administrar';
    const userRubros: string[] = (user as any).cotizacionRubros ?? [];

    // Find project by projectCode
    const project = await Projects.findOne({ filters: { projectCode: input.projectCode } });
    if (!project) return { canSeeAll, rubros: [], totals: { cotizado: 0, conMarkup: 0 }, personas: [], currency: 'MXN' };

    const dealId = Array.isArray(project.dealVinculado)
      ? project.dealVinculado[0]
      : (project.dealVinculado ?? undefined);

    let dealName: string | undefined;
    let currency = 'MXN';
    let allLineItems: import('zite-integrations-backend-sdk').CotizacionLineItemsRecordType[] = [];

    if (dealId) {
      const [dealRec, { records: cotizaciones }] = await Promise.all([
        Deals.findOne({ id: dealId }),
        Cotizaciones.findAll({ filters: { deal: { contains: dealId } } as never, limit: 200 }),
      ]);

      if (dealRec) {
        dealName = dealRec.dealName ?? undefined;
        currency = ((dealRec as any).currency ?? 'MXN').replace(/ 🇲🇽| 🇺🇸| 🇪🇺/g, '').trim();
      }

      const included = cotizaciones.filter(c => {
        const ids = Array.isArray(c.deal) ? c.deal : c.deal ? [c.deal] : [];
        return ids.includes(dealId) && (c as any).included === true;
      });

      if (included.length > 0) {
        const results = await Promise.all(
          included.map(c => CotizacionLineItemsSDK.findAll({ filters: { cotizacion: { contains: c.id } } as never, limit: 500 }))
        );
        allLineItems = results.flatMap((r, i) =>
          r.records.map(li => ({ ...li, _cotizacionName: included[i].cotizacionName ?? `Cotización ${i + 1}` }))
        ) as any;
      }
    }

    // Load users with cotizacionRubros for personas
    const { records: allUsers } = await Users.findAll({
      limit: 300,
      fields: ['id', 'email', 'firstName', 'lastName', 'cotizacionRubros'],
    });

    const personas = allUsers
      .filter(u => { const r = (u as any).cotizacionRubros as string[] | undefined; return r && r.length > 0; })
      .map(u => ({
        id: u.id,
        name: [u.firstName, u.lastName].filter(Boolean).join(' ') || u.email || u.id,
        rubros: (u as any).cotizacionRubros as string[],
      }));

    // rubro → assignedUsers map
    const rubroUsersMap = new Map<string, { id: string; name: string }[]>();
    for (const p of personas) {
      for (const rubro of p.rubros) {
        if (!rubroUsersMap.has(rubro)) rubroUsersMap.set(rubro, []);
        rubroUsersMap.get(rubro)!.push({ id: p.id, name: p.name });
      }
    }

    // Filter: only items included in budget with a non-zero total
    const budgetLineItems = allLineItems.filter(li => {
      if (!li.includedInBudget) return false;
      const total = Number(li.cantidad ?? 1) * Number(li.componentes ?? 1) * Number(li.unitCost ?? 0);
      return total > 0;
    });

    // Group line items by rubro
    const rubroItemsMap = new Map<string, import('zite-integrations-backend-sdk').CotizacionLineItemsRecordType[]>();
    for (const li of budgetLineItems) {
      const rubro = (li as any).rubro ?? 'Back office';
      if (!rubroItemsMap.has(rubro)) rubroItemsMap.set(rubro, []);
      rubroItemsMap.get(rubro)!.push(li);
    }

    const sortedRubroNames = [...rubroItemsMap.keys()].sort((a, b) => {
      const ai = RUBROS_ORDER.indexOf(a), bi = RUBROS_ORDER.indexOf(b);
      if (ai === -1 && bi === -1) return a.localeCompare(b);
      if (ai === -1) return 1; if (bi === -1) return -1;
      return ai - bi;
    });

    const visibleRubros = canSeeAll ? sortedRubroNames : sortedRubroNames.filter(r => userRubros.includes(r));

    const rubros = visibleRubros.map(rubroName => {
      const items = rubroItemsMap.get(rubroName) ?? [];
      const lineItems = items.map(li => {
        const cantidad = Number((li as any).cantidad ?? 1);
        const componentes = Number((li as any).componentes ?? 1);
        const unitCost = Number((li as any).unitCost ?? 0);
        return { id: li.id, subRubro: (li as any).subRubro ?? '', cantidad, componentes, unitCost, total: cantidad * componentes * unitCost, cotizacionName: (li as any)._cotizacionName ?? '' };
      });
      return {
        rubroName,
        lineItems,
        assignedUsers: rubroUsersMap.get(rubroName) ?? [],
        subtotalCotizado: lineItems.reduce((s, li) => s + li.total, 0),
      };
    });

    const totalCotizado = rubros.reduce((s, r) => s + r.subtotalCotizado, 0);
    const totalConMarkup = rubros.reduce((sum, r) => {
      const items = rubroItemsMap.get(r.rubroName) ?? [];
      return sum + items.reduce((s, li) => s + Number((li as any).finalPrice ?? 0), 0);
    }, 0);

    return {
      canSeeAll, rubros,
      totals: { cotizado: totalCotizado, conMarkup: totalConMarkup },
      personas, currency, dealName, projectCode: project.projectCode ?? input.projectCode,
    };
  },
});

src/api/getStreetViewUrl.ts.content:
import { z } from 'zod';
import { createEndpoint } from 'zite-integrations-backend-sdk';

// Module-level in-memory cache — persists across requests within the same worker instance
const cache = new Map<string, { embedUrl: string; mode: 'streetview' | 'place' }>();

function normalizeKey(address: string): string {
  return address.trim().toLowerCase().replace(/\s+/g, ' ');
}

function placeUrl(address: string): string {
  return `https://www.google.com/maps/embed/v1/place?key=${process.env.ZITE_GOOGLE_MAPS_API_KEY}&q=${encodeURIComponent(address)}`;
}

function streetViewUrl(lat: number, lng: number): string {
  return `https://www.google.com/maps/embed/v1/streetview?key=${process.env.ZITE_GOOGLE_MAPS_API_KEY}&location=${lat},${lng}&heading=210&pitch=10&fov=90`;
}

export default createEndpoint({
  description: 'Geocodes an address server-side and returns a Maps Embed API iframe URL (Street View or Place fallback)',
  inputSchema: z.object({
    address: z.string(),
  }),
  outputSchema: z.object({
    embedUrl: z.string(),
    mode: z.enum(['streetview', 'place']),
  }),
  execute: async ({ input }) => {
    const { address } = input;
    const key = normalizeKey(address);

    // Empty address — return place fallback with empty query
    if (!key) {
      return { embedUrl: placeUrl(''), mode: 'place' as const };
    }

    // Cache hit
    const cached = cache.get(key);
    if (cached) return cached;

    // Cache miss — call Geocoding API with the ORIGINAL address
    try {
      const geocodeRes = await fetch(
        `https://maps.googleapis.com/maps/api/geocode/json?address=${encodeURIComponent(address)}&key=${process.env.ZITE_GOOGLE_MAPS_API_KEY}`
      );
      const data = await geocodeRes.json() as {
        status: string;
        results: Array<{ geometry: { location: { lat: number; lng: number } } }>;
      };

      if (
        data.status === 'OK' &&
        data.results?.length > 0 &&
        data.results[0].geometry?.location
      ) {
        const { lat, lng } = data.results[0].geometry.location;
        const result = { embedUrl: streetViewUrl(lat, lng), mode: 'streetview' as const };
        cache.set(key, result);
        return result;
      }

      // Geocoding returned non-OK or no results — fall back to place
      const fallback = { embedUrl: placeUrl(address), mode: 'place' as const };
      cache.set(key, fallback);
      return fallback;

    } catch {
      // Network error or JSON parse failure — fall back to place
      const fallback = { embedUrl: placeUrl(address), mode: 'place' as const };
      cache.set(key, fallback);
      return fallback;
    }
  },
});

src/api/getTasksForGantt.ts.content:
import { z } from 'zod';
import { createEndpoint, Tasks, BoardColumns, CellValues, Boards, Projects } from 'zite-integrations-backend-sdk';

const taskSchema = z.object({
  id: z.string(),
  taskName: z.string().optional(),
  projectCode: z.string().optional(),
  boardName: z.string().optional(),
  status: z.string().optional(),
  assignedTo: z.string().optional(),
  startDate: z.string().optional(),
  endDate: z.string().optional(),
  parentTaskId: z.string().optional(),
  taskColor: z.string().optional(),
  colorColumnId: z.string().optional(),
  startColumnId: z.string().optional(),
  endColumnId: z.string().optional(),
  boardId: z.string().optional(),
  groupName: z.string().optional(),
  groupColorId: z.string().optional(),
});

// ── Pagination helper ─────────────────────────────────────────────────────────
const PAGE_SIZE = 2000;
const MAX_PAGES = 50;

async function fetchAll<T>(
  label: string,
  findAllFn: (params: { limit: number; offset: number; fields?: string[]; [key: string]: any }) => Promise<{ records: T[]; hasMore: boolean }>,
  opts: Record<string, any> = {}
): Promise<T[]> {
  const all: T[] = [];
  let offset = 0;
  const t0 = Date.now();
  for (let page = 0; page < MAX_PAGES; page++) {
    const res = await findAllFn({ ...opts, limit: PAGE_SIZE, offset });
    const records = res?.records ?? [];
    all.push(...records);
    console.log('[getTasksForGantt][fetchAll]', {
      label,
      page,
      offset,
      count: records.length,
      total: all.length,
      hasMore: res?.hasMore,
      ms: Date.now() - t0,
    });
    if (!res?.hasMore) return all;
    offset += PAGE_SIZE;
  }
  throw new Error(`Pagination safety stop: ${label} fetched ${all.length} records`);
}

export default createEndpoint({
  authenticated: true,
  description: 'Get all tasks with dates, group info, and colorColumnId for Gantt.',
  inputSchema: z.object({}),
  outputSchema: z.object({
    tasks: z.array(taskSchema),
    projectStatuses: z.record(z.string(), z.string()),
  }),
  execute: async () => {
    try {
      // ── Phase 1: Load everything except CellValues ──────────────────────────
      const [tasks, boards, projects, cols] = await Promise.all([
        fetchAll('Tasks',        (p) => Tasks.findAll(p)),
        fetchAll('Boards',       (p) => Boards.findAll(p)),
        fetchAll('Projects',     (p) => Projects.findAll(p), { fields: ['projectCode', 'status'] }),
        fetchAll('BoardColumns', (p) => BoardColumns.findAll(p)),
      ]);

      console.log('[getTasksForGantt] phase1 counts', {
        tasks: tasks.length,
        boards: boards.length,
        projects: projects.length,
        boardColumns: cols.length,
      });

      // ── Project status map ──────────────────────────────────────────────────
      const projectStatuses: Record<string, string> = {};
      for (const p of projects) {
        if (p.projectCode && p.status) projectStatuses[p.projectCode] = p.status;
      }

      // ── Active pm-type board keys ───────────────────────────────────────────
      const NON_PM_TYPES = new Set(['calendar']);
      const pmBoardKeys      = new Set<string>();
      const deletedBoardKeys = new Set<string>();
      for (const b of boards) {
        const key = `${b.projectCode}::${b.boardName}`;
        if (b.deletedAt) {
          deletedBoardKeys.add(key);
        } else if (!b.boardType || b.boardType === 'pm' || !NON_PM_TYPES.has(b.boardType)) {
          pmBoardKeys.add(key);
        }
      }

      // ── Build set of active (non-deleted) board UUIDs for direct validation ──
      const activeBoardUUIDs = new Set<string>();
      for (const b of boards) {
        if (!b.deletedAt && (!b.boardType || b.boardType === 'pm' || !NON_PM_TYPES.has(b.boardType))) {
          activeBoardUUIDs.add(b.id);
        }
      }

      // ── Filter tasks to active pm boards ───────────────────────────────────
      const validTasks = tasks.filter(t => {
        // UUID-first: if task has a boardId UUID, validate it directly
        if (t.boardId && activeBoardUUIDs.has(t.boardId)) return true;
        // Legacy fallback: validate via composite key
        return (
          t.boardName &&
          t.projectCode &&
          !deletedBoardKeys.has(`${t.projectCode}::${t.boardName}`) &&
          pmBoardKeys.has(`${t.projectCode}::${t.boardName}`)
        );
      });

      // Build the set of relevant boardIds from valid tasks (UUID-first)
      const relevantBoardIds = new Set<string>();
      for (const t of validTasks) {
        // Use task.boardId (UUID) when it exists and points to an active board
        const bid = (t.boardId && activeBoardUUIDs.has(t.boardId))
          ? t.boardId
          : `pm-${t.projectCode}-${t.boardName}`;
        relevantBoardIds.add(bid);
        relevantBoardIds.add(`${bid}::groups`);
      }

      console.log('[getTasksForGantt] relevantBoardIds', relevantBoardIds.size);

      // ── Phase 2: Fetch CellValues filtered to relevant boards only ──────────
      const relevantBoardIdArray = [...relevantBoardIds];
      const cells = relevantBoardIdArray.length > 0
        ? await fetchAll('CellValues', (p) => CellValues.findAll(p), {
            filters: { boardId: { in: relevantBoardIdArray } },
          })
        : [];

      console.log('[getTasksForGantt] cellValues fetched', cells.length);

      // ── Filter columns and cells to only relevant pm boards ─────────────────
      const activeCols = cols
        .filter(c => !c.deletedAt && c.boardId && relevantBoardIds.has(c.boardId))
        .sort((a, b) => (a.columnOrder ?? 9999) - (b.columnOrder ?? 9999));

      const activeCells = cells
        .filter(c => !c.deletedAt && c.boardId && relevantBoardIds.has(c.boardId));

      // ── Resolve date + color columns per boardId ────────────────────────────
      const START_NAMES = new Set(['inicio', 'start', 'fecha inicio', 'start date', 'fecha_inicio']);
      const END_NAMES   = new Set(['fin', 'end', 'fecha fin', 'end date', 'fecha_fin']);

      const boardFechaMap = new Map<string, typeof activeCols>();
      for (const col of activeCols) {
        if (!col.boardId || col.columnType !== 'Fecha') continue;
        if (!boardFechaMap.has(col.boardId)) boardFechaMap.set(col.boardId, []);
        boardFechaMap.get(col.boardId)!.push(col);
      }

      const boardDateCols = new Map<string, { startColId?: string; endColId?: string; colorColId?: string }>();

      for (const [boardId, fechaCols] of boardFechaMap) {
        const entry: { startColId?: string; endColId?: string; colorColId?: string } = {};

        const startByName = fechaCols.find(c => START_NAMES.has((c.columnName ?? '').toLowerCase().trim()));
        const endByName   = fechaCols.find(c => END_NAMES.has((c.columnName ?? '').toLowerCase().trim()));
        if (startByName) entry.startColId = startByName.id;
        if (endByName)   entry.endColId   = endByName.id;

        if (!entry.startColId && !entry.endColId) {
          if (fechaCols[0]) entry.startColId = fechaCols[0].id;
          if (fechaCols[1]) entry.endColId   = fechaCols[1].id;
        } else if (entry.startColId && !entry.endColId) {
          const fb = fechaCols.find(c => c.id !== entry.startColId);
          if (fb) entry.endColId = fb.id;
        } else if (!entry.startColId && entry.endColId) {
          const fb = fechaCols.find(c => c.id !== entry.endColId);
          if (fb) entry.startColId = fb.id;
        }

        boardDateCols.set(boardId, entry);
      }

      // Color columns
      for (const col of activeCols) {
        if (!col.boardId || col.columnType !== 'Color') continue;
        const entry = boardDateCols.get(col.boardId) ?? {};
        if (!entry.colorColId) { entry.colorColId = col.id; boardDateCols.set(col.boardId, entry); }
      }

      // ── Group column info from ::groups boards ──────────────────────────────
      const groupColInfo = new Map<string, { name: string; colorId: string }>();
      for (const col of activeCols) {
        if (!col.boardId?.endsWith('::groups')) continue;
        if (!col.id || !col.columnName) continue;
        groupColInfo.set(col.id, { name: col.columnName, colorId: col.columnType ?? '' });
      }

      // ── Build color + group map from cells ──────────────────────────────────
      const cellMap = new Map<string, { color?: string; groupColId?: string }>();

      for (const cell of activeCells) {
        if (!cell.rowId || !cell.columnId || !cell.boardId) continue;

        if (cell.boardId.endsWith('::groups')) {
          if (cell.textValue === '1' && groupColInfo.has(cell.columnId)) {
            const entry = cellMap.get(cell.rowId) ?? {};
            entry.groupColId = cell.columnId;
            cellMap.set(cell.rowId, entry);
          }
          continue;
        }

        const dateCols = boardDateCols.get(cell.boardId);
        if (!dateCols?.colorColId) continue;
        if (cell.columnId === dateCols.colorColId && cell.textValue) {
          const entry = cellMap.get(cell.rowId) ?? {};
          entry.color = cell.textValue;
          cellMap.set(cell.rowId, entry);
        }
      }

      // ── Map tasks to output ─────────────────────────────────────────────────
      const outputTasks = validTasks.map(t => {
        const cell      = cellMap.get(t.id);
        // UUID-first: use task.boardId when it points to an active board
        const boardId   = (t.boardId && activeBoardUUIDs.has(t.boardId))
          ? t.boardId
          : `pm-${t.projectCode}-${t.boardName}`;
        const dateCols  = boardDateCols.get(boardId);
        const groupInfo = cell?.groupColId ? groupColInfo.get(cell.groupColId) : undefined;

        return {
          id: t.id,
          taskName:      t.taskName      ?? undefined,
          projectCode:   t.projectCode   ?? undefined,
          boardName:     t.boardName     ?? undefined,
          status:        t.status        ?? undefined,
          assignedTo:    t.assignedTo    ?? undefined,
          parentTaskId:  t.parentTaskId  ?? undefined,
          startDate: t.startDate?.split('T')[0] ?? undefined,
          endDate:   t.endDate?.split('T')[0]   ?? undefined,
          taskColor: cell?.color ?? undefined,
          colorColumnId: dateCols?.colorColId ?? undefined,
          startColumnId: dateCols?.startColId ?? undefined,
          endColumnId:   dateCols?.endColId   ?? undefined,
          boardId,
          groupName:    groupInfo?.name    ?? undefined,
          groupColorId: groupInfo?.colorId ?? undefined,
        };
      });

      return { tasks: outputTasks, projectStatuses };

    } catch (error) {
      console.error('[getTasksForGantt] failed', {
        message: error instanceof Error ? error.message : String(error),
        stack: error instanceof Error ? error.stack : undefined,
      });
      throw error;
    }
  },
});

src/api/importOdcFromCsv.ts.content:
import { z } from 'zod';
import { createEndpoint, Projects, Suppliers, PurchaseOrders, PoLineItems } from 'zite-integrations-backend-sdk';

// ── CSV helpers ───────────────────────────────────────────────────────────────
function splitCSV(line: string): string[] {
  const out: string[] = [];
  let cur = '', inQ = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (c === '"') { if (inQ && line[i + 1] === '"') { cur += '"'; i++; } else inQ = !inQ; }
    else if (c === ',' && !inQ) { out.push(cur); cur = ''; }
    else cur += c;
  }
  out.push(cur);
  return out;
}

function pn(v: string | undefined): number {
  if (!v || v === 'nan') return 0;
  const x = parseFloat(v.replace(/[$,\s]/g, ''));
  return isNaN(x) ? 0 : x;
}

function pd(v: string | undefined): string | undefined {
  if (!v || v === 'nan') return undefined;
  const s = v.trim();
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
  const M: Record<string, string> = { Jan:'01',Feb:'02',Mar:'03',Apr:'04',May:'05',Jun:'06',Jul:'07',Aug:'08',Sep:'09',Oct:'10',Nov:'11',Dec:'12' };
  const m1 = s.match(/^(\d{1,2})-([A-Za-z]{3})-(\d{4})$/);
  if (m1) return `${m1[3]}-${M[m1[2]] ?? '01'}-${m1[1].padStart(2, '0')}`;
  const m2 = s.match(/\w{3} ([A-Za-z]{3}) (\d+) (\d{4})/);
  if (m2) return `${m2[3]}-${M[m2[1]] ?? '01'}-${m2[2].padStart(2, '0')}`;
  return undefined;
}

function mapRubro(r: string): string {
  const u = r.toUpperCase();
  if (u.includes('LOGÍST') || u.includes('LOGIST') || u.includes('VIÁTIC') || u.includes('VIATIC')) return 'Logística';
  if (u.includes('MODERAT') || u.includes('MODERAC')) return 'Moderaciones';
  if (u.includes('MANAGEMENT')) return 'Management';
  return 'Reclutamiento e Incentivos';
}

function normalizeName(s: string): string {
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim().replace(/\s+/g, ' ');
}

/** Map CSV send/pay statuses to system status */
function mapCsvStatus(sendStatus: string, payStatus: string): string {
  if (payStatus.toLowerCase().includes('pagada')) return 'Pagada';
  if (sendStatus.toLowerCase().includes('enviada')) return 'Factura recibida';
  return 'Aprobada';
}

/** Detect ODC type from item name */
function mapTipoDeOc(name: string): 'Anticipo' | 'Cierre' | 'Normal' {
  const lc = name.toLowerCase();
  if (lc.includes('anticipo')) return 'Anticipo';
  if (lc.includes('cierre') || lc.includes('finalización') || lc.includes('finalizacion')) return 'Cierre';
  return 'Normal';
}

interface ParsedODC {
  projectCode: string;
  poNumber: string;
  description: string;
  rubro: string;
  supplierRaw: string;
  supplierRfc: string;
  supplierEmail: string;
  currency: string;
  totalAmount: number;     // col 29: Total Sin IVA (después de restar anticipo)
  anticipoMxn: number;     // col 27: Anticipo (MXN$)
  sendStatus: string;
  payStatus: string;
  issueDate?: string;
  pdfUrl?: string;
  lineItems: { description: string; quantity: number; unitPrice: number; total: number }[];
}

function parseMondayCsv(text: string): ParsedODC[] {
  const lines = text.split(/\r?\n/);
  const odcs: ParsedODC[] = [];
  let currentProject = '';
  let projectCandidate = '';
  let lastOdc: ParsedODC | null = null;
  let inSubitems = false;
  let statusOdcCol = -1;
  let statusPagoCol = -1;

  for (const line of lines) {
    if (!line.trim()) { inSubitems = false; continue; }
    const cols = splitCSV(line);
    const c = (i: number) => cols[i]?.trim() ?? '';
    const c0 = c(0), c1 = c(1);

    if (c0 === 'Name' && c1 === 'Subitems') {
      currentProject = projectCandidate;
      inSubitems = false;
      // Detect status column positions from this header row
      for (let i = 0; i < cols.length; i++) {
        const h = cols[i]?.trim().toLowerCase() ?? '';
        if (h.includes('status odc') || h === 'estado odc' || h === 'status de la odc') statusOdcCol = i;
        if (h.includes('status de pago') || h.includes('status pago') || h === 'estado de pago' || h === 'estado pago') statusPagoCol = i;
      }
      continue;
    }
    if (c0 === 'Subitems' && c1 === 'Name') { inSubitems = true; continue; }
    if (c0 === '' && c1 && c1 !== 'Name' && inSubitems && lastOdc) {
      lastOdc.lineItems.push({ description: c1, quantity: pn(c(5)), unitPrice: pn(c(6)), total: pn(c(9)) });
      continue;
    }

    const c4 = c(4);
    if (/^[A-Za-z]+-\d/.test(c4)) {
      inSubitems = false;
      const emailCandidate = [c(10), c(11), c(12)].find(v => v.includes('@') && v.includes('.')) ?? '';
      const sendStatus = statusOdcCol >= 0 ? c(statusOdcCol) : '';
      const payStatus = statusPagoCol >= 0 ? c(statusPagoCol) : c(31);

      // col 27: Anticipo (MXN$)
      // col 29: Total Sin IVA = total bruto - anticipo (lo que realmente se debe pagar)
      // col 21: Total de actividades (MXN$) — fallback si col 29 está vacía
      const anticipoMxn = pn(c(27));
      const totalSinIva = pn(c(29));
      const totalBruto = pn(c(21)) || pn(c(20));
      // Use totalSinIva if available, otherwise totalBruto
      const totalAmount = totalSinIva !== 0 ? totalSinIva : totalBruto;

      const odc: ParsedODC = {
        projectCode: currentProject,
        poNumber: c4,
        description: c0 === 'Agregar pago' ? '' : c0,
        rubro: c(5),
        supplierRaw: c(8) || c(7),
        supplierRfc: c(9),
        supplierEmail: emailCandidate,
        currency: c(3).replace(' $', '').trim() || 'MXN',
        totalAmount,
        anticipoMxn,
        sendStatus,
        payStatus,
        issueDate: pd(c(40)),
        pdfUrl: c(43).startsWith('http') ? c(43) : undefined,
        lineItems: [],
      };
      odcs.push(odc);
      lastOdc = odc;
      continue;
    }

    if (c0 && c0 !== 'Agregar pago' && c0 !== 'Subitems' && !c4) {
      projectCandidate = c0;
      inSubitems = false;
    }
  }
  return odcs;
}

// ── Endpoint ─────────────────────────────────────────────────────────────────
const sleep = (ms: number) => new Promise(r => setTimeout(r, ms));

export default createEndpoint({
  authenticated: true,
  description: 'Import ODCs from a Monday.com CSV. Accepts project/supplier mappings for manual resolution. Call in batches until done=true.',
  inputSchema: z.object({
    csvUrl: z.string(),
    batchOffset: z.number(),
    batchSize: z.number().optional(),
    projectMappings: z.record(z.string(), z.string()).optional(),
    supplierMappings: z.record(z.string(), z.string()).optional(),
    skipExisting: z.boolean().optional(),
    amountsOnly: z.boolean().optional(), // Only update totalAmount, tipoDeOc and line items on existing ODCs
  }),
  outputSchema: z.object({
    created: z.number(),
    newCount: z.number(),
    updatedCount: z.number(),
    lineItemsCreated: z.number(),
    projectsCreated: z.number(),
    suppliersCreated: z.number(),
    batchOffset: z.number(),
    done: z.boolean(),
    totalOdcs: z.number(),
  }),
  execute: async ({ input, context }) => {
    const { csvUrl, batchOffset, batchSize = 50, projectMappings = {}, supplierMappings = {}, skipExisting = false, amountsOnly = false } = input;

    const resp = await fetch(csvUrl);
    if (!resp.ok) throw new Error(`No se pudo obtener el CSV: ${resp.status}`);
    const text = await resp.text();
    const odcs = parseMondayCsv(text);

    // ── AMOUNTS ONLY MODE ─────────────────────────────────────────────────────
    // Only update totalAmount, tipoDeOc, and line items on existing ODCs by poNumber.
    // No project/supplier resolution needed.
    if (amountsOnly) {
      const batch = odcs.slice(batchOffset, batchOffset + batchSize);
      if (batch.length === 0) {
        return { created: 0, newCount: 0, updatedCount: 0, lineItemsCreated: 0, projectsCreated: 0, suppliersCreated: 0, batchOffset, done: true, totalOdcs: odcs.length };
      }

      const poNumbers = batch.map(o => o.poNumber).filter(Boolean) as string[];
      const { records: existingPos } = await PurchaseOrders.findAll({
        filters: { poNumber: { in: poNumbers } },
        fields: ['poNumber'],
        limit: poNumbers.length,
      });

      const poIdByNumber: Record<string, string> = {};
      for (const p of existingPos) if (p.poNumber) poIdByNumber[p.poNumber] = p.id;

      // Update totalAmount + tipoDeOc on each existing PO
      let updatedCount = 0;
      for (const odc of batch) {
        const id = poIdByNumber[odc.poNumber];
        if (!id) continue;
        await PurchaseOrders.update({ id, record: { totalAmount: odc.totalAmount || undefined, tipoDeOc: mapTipoDeOc(odc.description) } });
        updatedCount++;
        if (updatedCount % 10 === 0) await sleep(100); // rate limit safety
      }

      // Refresh line items: delete old, create new
      const existingPoIds = Object.values(poIdByNumber).filter(Boolean);
      if (existingPoIds.length > 0) {
        const { records: oldItems } = await PoLineItems.findAll({ filters: { poId: { in: existingPoIds } }, limit: 2000, fields: [] });
        for (const item of oldItems) await PoLineItems.delete({ id: item.id });
        if (oldItems.length > 0) await sleep(150);
      }

      const lineItems: any[] = [];
      for (const odc of batch) {
        const poId = poIdByNumber[odc.poNumber];
        if (!poId) continue;
        for (const item of odc.lineItems) {
          lineItems.push({ description: item.description || '—', quantity: item.quantity || undefined, unitPrice: item.unitPrice || undefined, total: item.total || undefined, category: mapRubro(odc.rubro), poId });
        }
        if (odc.anticipoMxn > 0) {
          lineItems.push({ description: 'Anticipo', quantity: 1, unitPrice: -odc.anticipoMxn, total: -odc.anticipoMxn, category: mapRubro(odc.rubro), poId });
        }
      }

      let lineItemsCreated = 0;
      for (let i = 0; i < lineItems.length; i += 100) {
        const r = await PoLineItems.bulkCreate({ records: lineItems.slice(i, i + 100) });
        lineItemsCreated += r.records.length;
        if (i + 100 < lineItems.length) await sleep(150);
      }

      const done = batchOffset + batchSize >= odcs.length;
      return { created: 0, newCount: 0, updatedCount, lineItemsCreated, projectsCreated: 0, suppliersCreated: 0, batchOffset, done, totalOdcs: odcs.length };
    }
    // ── END AMOUNTS ONLY ──────────────────────────────────────────────────────

    const { records: suppliers } = await Suppliers.findAll({ fields: ['supplierName', 'taxId', 'email'], limit: 2000 });
    const rfcMap: Record<string, string> = {};
    const emailMap: Record<string, string> = {};
    const nameMap: Record<string, string> = {};
    for (const s of suppliers) {
      const name = s.supplierName ?? '';
      if (s.taxId) rfcMap[s.taxId.toUpperCase().trim()] = name;
      if (s.email) emailMap[s.email.toLowerCase().trim()] = name;
      if (name) nameMap[normalizeName(name)] = name;
    }

    let projectsCreated = 0;
    let suppliersCreated = 0;

    const { records: allExistingProjects } = await Projects.findAll({ fields: ['projectCode'], limit: 2000 });
    const existingProjectMap = new Map<string, string>();
    for (const p of allExistingProjects) if (p.projectCode) existingProjectMap.set(p.projectCode.toUpperCase().trim(), p.projectCode);

    if (batchOffset === 0) {
      const allCodes = [...new Set(odcs.map(o => o.projectCode).filter(Boolean))];
      const toCreate = allCodes.filter(code => {
        if (existingProjectMap.has(code.toUpperCase().trim())) return false;
        const mapped = projectMappings[code];
        if (mapped === 'skip') return false;
        return !mapped || mapped === 'create';
      });
      if (toCreate.length > 0) {
        const r = await Projects.bulkCreate({
          records: toCreate.map(code => ({ projectCode: code, status: 'En curso' })),
          matchOn: ['projectCode'],
        });
        projectsCreated = r.records.length;
      }

      const suppliersToCreate: Array<{ supplierName: string; taxId?: string }> = [];
      for (const [key, decision] of Object.entries(supplierMappings)) {
        if (decision === 'create') {
          const odc = odcs.find(o => (o.supplierRfc || o.supplierRaw || '') === key);
          if (odc && odc.supplierRaw) {
            suppliersToCreate.push({ supplierName: odc.supplierRaw, taxId: odc.supplierRfc || undefined });
          }
        }
      }
      if (suppliersToCreate.length > 0) {
        const r = await Suppliers.bulkCreate({ records: suppliersToCreate, matchOn: ['supplierName'] });
        suppliersCreated = r.records.length;
        for (const rec of r.records) {
          const name = (rec.fields as any)?.supplierName;
          if (name) nameMap[normalizeName(name)] = name;
        }
      }
    }

    const batch = odcs.slice(batchOffset, batchOffset + batchSize);
    if (batch.length === 0) {
      return { created: 0, newCount: 0, updatedCount: 0, lineItemsCreated: 0, projectsCreated, suppliersCreated, batchOffset, done: true, totalOdcs: odcs.length };
    }

    const poRecords = batch.map(odc => {
      const mappedProject = projectMappings[odc.projectCode];
      const effectiveProjectCode =
        mappedProject === 'skip' ? '' :
        (mappedProject && mappedProject !== 'create') ? mappedProject :
        existingProjectMap.get(odc.projectCode.toUpperCase().trim()) ?? odc.projectCode;

      let supplierName = odc.supplierRaw;
      let dbMatched = false;

      if (odc.supplierRfc) {
        const m = rfcMap[odc.supplierRfc.toUpperCase().trim()];
        if (m) { supplierName = m; dbMatched = true; }
      }
      if (!dbMatched && odc.supplierEmail) {
        const m = emailMap[odc.supplierEmail.toLowerCase().trim()];
        if (m) { supplierName = m; dbMatched = true; }
      }
      if (!dbMatched && odc.supplierRaw) {
        const m = nameMap[normalizeName(odc.supplierRaw)];
        if (m) { supplierName = m; dbMatched = true; }
      }

      if (!dbMatched) {
        const key = odc.supplierRfc || odc.supplierRaw || '';
        const decision = supplierMappings[key];
        if (decision && decision !== 'raw' && decision !== 'create') {
          supplierName = decision;
        }
      }

      const wasEnviada = odc.sendStatus.toLowerCase().includes('enviada');
      const tipoDeOc = mapTipoDeOc(odc.description);

      return {
        poNumber: odc.poNumber,
        projectCode: effectiveProjectCode,
        supplierName: supplierName || '(sin proveedor)',
        totalAmount: odc.totalAmount || undefined,
        status: mapCsvStatus(odc.sendStatus, odc.payStatus),
        notes: odc.description || undefined,
        category: mapRubro(odc.rubro),
        currency: odc.currency || 'MXN',
        issueDate: odc.issueDate,
        createdBy: context.user!.email,
        pdfUrl: odc.pdfUrl,
        origen: 'Migrada' as const,
        tipoDeOc,
        ...(wasEnviada ? { emailSentAt: odc.issueDate ? new Date(odc.issueDate).toISOString() : new Date().toISOString() } : {}),
      };
    });

    const batchPoNumbers = poRecords.map(r => r.poNumber).filter(Boolean) as string[];
    const { records: existingPos } = await PurchaseOrders.findAll({
      filters: { poNumber: { in: batchPoNumbers } },
      fields: ['poNumber'],
      limit: batchPoNumbers.length,
    });
    const existingPoNumbersSet = new Set(existingPos.map(p => p.poNumber).filter(Boolean));

    // When skipExisting, filter out records whose poNumber already exists
    const filteredPoRecords = skipExisting
      ? poRecords.filter(r => r.poNumber && !existingPoNumbersSet.has(r.poNumber))
      : poRecords;

    if (filteredPoRecords.length === 0) {
      const done = batchOffset + batchSize >= odcs.length;
      return { created: 0, newCount: 0, updatedCount: 0, lineItemsCreated: 0, projectsCreated, suppliersCreated, batchOffset, done, totalOdcs: odcs.length };
    }

    const poResult = await PurchaseOrders.bulkCreate({
      records: filteredPoRecords,
      matchOn: ['poNumber'],
    });

    const filteredPoNumbers = filteredPoRecords.map(r => r.poNumber).filter(Boolean) as string[];
    const newCount = filteredPoNumbers.filter(n => !existingPoNumbersSet.has(n)).length;
    const updatedCount = filteredPoNumbers.filter(n => existingPoNumbersSet.has(n)).length;

    const poIdMap: Record<string, string> = {};
    for (const r of poResult.records) {
      const num = (r.fields as any)?.poNumber;
      if (num) poIdMap[num] = r.id;
    }

    const existingPoIds = filteredPoNumbers
      .filter(n => existingPoNumbersSet.has(n))
      .map(n => poIdMap[n])
      .filter(Boolean) as string[];

    if (existingPoIds.length > 0) {
      const { records: oldLineItems } = await PoLineItems.findAll({
        filters: { poId: { in: existingPoIds } },
        limit: 2000,
        fields: [],
      });
      for (const item of oldLineItems) {
        await PoLineItems.delete({ id: item.id });
      }
      if (oldLineItems.length > 0) await sleep(100);
    }

    const filteredPoNumbersSet = new Set(filteredPoNumbers);
    const lineItems: any[] = [];
    for (const odc of batch) {
      if (!filteredPoNumbersSet.has(odc.poNumber)) continue;
      const poId = poIdMap[odc.poNumber];
      if (!poId) continue;

      // Regular subitems
      for (const item of odc.lineItems) {
        lineItems.push({
          description: item.description || '—',
          quantity: item.quantity || undefined,
          unitPrice: item.unitPrice || undefined,
          total: item.total || undefined,
          category: mapRubro(odc.rubro),
          poId,
        });
      }

      // Anticipo as a negative line item so sum reflects the real total
      if (odc.anticipoMxn > 0) {
        lineItems.push({
          description: 'Anticipo',
          quantity: 1,
          unitPrice: -odc.anticipoMxn,
          total: -odc.anticipoMxn,
          category: mapRubro(odc.rubro),
          poId,
        });
      }
    }

    let lineItemsCreated = 0;
    for (let i = 0; i < lineItems.length; i += 100) {
      const r = await PoLineItems.bulkCreate({ records: lineItems.slice(i, i + 100) });
      lineItemsCreated += r.records.length;
      if (i + 100 < lineItems.length) await sleep(150);
    }

    const done = batchOffset + batchSize >= odcs.length;
    return { created: poResult.records.length, newCount, updatedCount, lineItemsCreated, projectsCreated, suppliersCreated, batchOffset, done, totalOdcs: odcs.length };
  },
});

src/api/linkGroupToEvent.ts.content:
import { z } from 'zod';
import { createEndpoint, BoardColumns, CellValues } from 'zite-integrations-backend-sdk';
import { resolveWriteBoardId, smartWriteCellValue } from '../serverUtils/smartWrite';

const LINKED_GROUP_COLUMN_NAME = 'Grupo vinculado';

export default createEndpoint({
  authenticated: true,
  description: 'Link (or unlink) a recruitment group to a calendar event — bidirectional, idempotent',
  inputSchema: z.object({
    groupColumnId: z.string(),
    recruitmentBoardId: z.string(),
    calendarBoardId: z.string(),
    eventId: z.string(),
    unlink: z.boolean().optional(),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input }) => {
    const { groupColumnId, recruitmentBoardId, calendarBoardId, eventId, unlink } = input;

    // ── Resolve both boardIds to UUIDs ────────────────────────────────────
    let resolvedRecruitmentId = recruitmentBoardId;
    try {
      const res = await resolveWriteBoardId(recruitmentBoardId);
      resolvedRecruitmentId = res.writeBoardId;
    } catch { /* keep input */ }

    let resolvedCalendarId = calendarBoardId;
    let resolvedCalLegacyId: string | undefined = calendarBoardId;
    try {
      const res = await resolveWriteBoardId(calendarBoardId);
      resolvedCalendarId = res.writeBoardId;
      resolvedCalLegacyId = res.legacyBoardId ?? calendarBoardId;
      if (res.reason === 'legacy-fallback' || res.reason === 'input-passthrough') {
        console.warn('[linkGroupToEvent] Calendar UUID not found, using legacy', { calendarBoardId, reason: res.reason });
      }
    } catch (err) {
      console.warn('[linkGroupToEvent] resolveWriteBoardId failed for calendar', { calendarBoardId, error: String(err) });
    }

    // ── 1. Read the group's BoardColumn ────────────────────────────────────
    const groupCol = await BoardColumns.findOne({ id: groupColumnId });
    if (!groupCol) throw new Error(`Group column ${groupColumnId} not found`);

    let opts: Record<string, unknown> = {};
    try { opts = JSON.parse(groupCol.optionsJson ?? '{}'); } catch { /* keep empty */ }

    // ── 2. Clean up old inverse CellValue if there was a previous link ─────
    const prevLink = opts.linkedCalEvent as { calBoardId?: string; eventId?: string } | undefined;
    if (prevLink?.eventId && prevLink?.calBoardId) {
      const prevBoardId = prevLink.calBoardId;

      // Dual-read for the "Grupo vinculado" column
      let oldCalCol = (await BoardColumns.findAll({
        filters: { boardId: prevBoardId, columnName: LINKED_GROUP_COLUMN_NAME },
        limit: 1,
      })).records[0];

      if (!oldCalCol) {
        try {
          const prevResolution = await resolveWriteBoardId(prevBoardId);
          if (prevResolution.writeBoardId !== prevBoardId) {
            oldCalCol = (await BoardColumns.findAll({
              filters: { boardId: prevResolution.writeBoardId, columnName: LINKED_GROUP_COLUMN_NAME },
              limit: 1,
            })).records[0];
          }
          if (!oldCalCol && prevResolution.legacyBoardId && prevResolution.legacyBoardId !== prevBoardId && prevResolution.legacyBoardId !== prevResolution.writeBoardId) {
            oldCalCol = (await BoardColumns.findAll({
              filters: { boardId: prevResolution.legacyBoardId, columnName: LINKED_GROUP_COLUMN_NAME },
              limit: 1,
            })).records[0];
          }
        } catch { /* skip — best effort cleanup */ }
      }

      if (oldCalCol) {
        let oldCell = await CellValues.findOne({
          filters: { boardId: prevBoardId, rowId: prevLink.eventId, columnId: oldCalCol.id },
        });
        if (!oldCell) {
          const altBoardId = prevBoardId === resolvedCalendarId ? resolvedCalLegacyId : resolvedCalendarId;
          if (altBoardId && altBoardId !== prevBoardId) {
            oldCell = await CellValues.findOne({
              filters: { boardId: altBoardId, rowId: prevLink.eventId, columnId: oldCalCol.id },
            });
          }
        }
        if (oldCell) await CellValues.delete({ id: oldCell.id });
      }
    }

    // ── 3. Update the group's optionsJson ──────────────────────────────────
    if (unlink) {
      delete opts.linkedCalEvent;
    } else {
      opts.linkedCalEvent = { calBoardId: resolvedCalendarId, eventId };
    }
    await BoardColumns.update({ id: groupColumnId, record: { optionsJson: JSON.stringify(opts) } });

    // ── 4. Get or create the "Grupo vinculado" column on the cal board ─────
    // Search under UUID first
    let calCol = (await BoardColumns.findAll({
      filters: { boardId: resolvedCalendarId, columnName: LINKED_GROUP_COLUMN_NAME },
      limit: 1,
    })).records[0];

    // Fallback: search under legacy
    if (!calCol && resolvedCalLegacyId && resolvedCalLegacyId !== resolvedCalendarId) {
      calCol = (await BoardColumns.findAll({
        filters: { boardId: resolvedCalLegacyId, columnName: LINKED_GROUP_COLUMN_NAME },
        limit: 1,
      })).records[0];
    }

    // Create under UUID if not found anywhere
    if (!calCol) {
      calCol = await BoardColumns.create({
        record: {
          boardId: resolvedCalendarId,
          columnName: LINKED_GROUP_COLUMN_NAME,
          columnType: 'Texto',
          columnOrder: 9999,
        },
      });
    }

    // ── 5. Upsert / delete the inverse CellValue on the event ─────────────
    if (unlink) {
      await smartWriteCellValue({
        uuidBoardId: resolvedCalendarId,
        legacyBoardId: resolvedCalLegacyId,
        rowId: eventId,
        columnId: calCol.id,
        values: {},
        isEmpty: true,
      });
    } else {
      const textValue = `${resolvedRecruitmentId}::${groupColumnId}`;
      await smartWriteCellValue({
        uuidBoardId: resolvedCalendarId,
        legacyBoardId: resolvedCalLegacyId,
        rowId: eventId,
        columnId: calCol.id,
        values: { textValue },
        isEmpty: false,
      });
    }

    return { success: true };
  },
});

src/api/purgeDeletedRows.ts.content:
import { z } from 'zod';
import { createEndpoint, RecruitmentRows } from 'zite-integrations-backend-sdk';

// Endpoint to hard-delete one batch of soft-deleted rows.
// Call repeatedly from the frontend until done === true.
export default createEndpoint({
  authenticated: true,
  description: 'Hard-delete a batch of soft-deleted Recruitment Rows. Returns remaining count.',
  inputSchema: z.object({
    projectCode: z.string(),
    batchSize: z.number().optional(), // default 50
  }),
  outputSchema: z.object({
    deleted: z.number(),
    done: z.boolean(),
  }),
  execute: async ({ input }) => {
    const batchSize = input.batchSize ?? 50;

    // Fetch a batch of rows for this project (all, not just deleted, because we can't filter deletedAt)
    const { records } = await RecruitmentRows.findAll({
      filters: { projectCode: input.projectCode },
      limit: 500,
      offset: 0,
      fields: ['id', 'deletedAt'],
    });

    const toDelete = records.filter(r => r.deletedAt).slice(0, batchSize);

    // Delete one at a time to stay within rate limits
    for (const r of toDelete) {
      await RecruitmentRows.delete({ id: r.id });
    }

    // Check if there are still soft-deleted rows remaining
    const { records: check } = await RecruitmentRows.findAll({
      filters: { projectCode: input.projectCode },
      limit: 100,
      offset: 0,
      fields: ['id', 'deletedAt'],
    });
    const remaining = check.filter(r => r.deletedAt).length;

    return { deleted: toDelete.length, done: remaining === 0 };
  },
});

src/api/restoreFromTrash.ts.content:
import { z } from 'zod';
import { createEndpoint, RecruitmentRows, BoardColumns, CellValues } from 'zite-integrations-backend-sdk';

const sleep = (ms: number) => new Promise(r => setTimeout(r, ms));

async function restoreBatch(ids: string[], updater: (id: string) => Promise<unknown>) {
  for (let i = 0; i < ids.length; i += 10) {
    await Promise.all(ids.slice(i, i + 10).map(updater));
    if (i + 10 < ids.length) await sleep(250);
  }
}

export default createEndpoint({
  authenticated: true,
  description: 'Restore a board or individual row from trash',
  inputSchema: z.object({
    type: z.enum(['board', 'row']),
    boardId: z.string().optional(),
    boardName: z.string().optional(),
    projectCode: z.string().optional(),
    rowId: z.string().optional(),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input }) => {
    if (input.type === 'board') {
      if (!input.boardId || !input.boardName || !input.projectCode) return { success: false };

      // Restore columns
      const { records: cols } = await BoardColumns.findAll({
        filters: { boardId: input.boardId },
        fields: ['id'],
        limit: 500,
      });
      await restoreBatch(cols.map(c => c.id), id => BoardColumns.update({ id, record: { deletedAt: '' } }));

      await sleep(250);

      // Restore rows
      const { records: rows } = await RecruitmentRows.findAll({
        filters: { boardName: input.boardName, projectCode: input.projectCode },
        fields: ['id'],
        limit: 2000,
      });
      await restoreBatch(rows.map(r => r.id), id => RecruitmentRows.update({ id, record: { deletedAt: '' } }));

      await sleep(250);

      // Restore cells
      const { records: cells } = await CellValues.findAll({
        filters: { boardId: input.boardId },
        fields: ['id'],
        limit: 2000,
      });
      await restoreBatch(cells.map(c => c.id), id => CellValues.update({ id, record: { deletedAt: '' } }));

    } else {
      if (!input.rowId) return { success: false };

      // Find the row and its children
      const { records: children } = await RecruitmentRows.findAll({
        filters: { parentRowId: input.rowId },
        fields: ['id'],
        limit: 100,
      });
      const allIds = [input.rowId, ...children.map(c => c.id)];
      await restoreBatch(allIds, id => RecruitmentRows.update({ id, record: { deletedAt: '' } }));
    }

    return { success: true };
  },
});

