import { z } from 'zod';
import { createEndpoint, ApprovalLimits } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Creates or updates an approval limit record',
  inputSchema: z.object({
    id: z.string().optional(),
    costCenter: z.string(),
    approvalLevel: z.string(),
    maxAmount: z.number(),
  }),
  outputSchema: z.object({ success: z.boolean(), id: z.string() }),
  execute: async ({ input }) => {
    if (input.id) {
      const result = await ApprovalLimits.update({
        id: input.id,
        record: {
          costCenter: input.costCenter,
          approvalLevel: input.approvalLevel,
          maxAmount: input.maxAmount,
        },
      });
      return { success: true, id: result.id };
    } else {
      const result = await ApprovalLimits.create({
        record: {
          costCenter: input.costCenter,
          approvalLevel: input.approvalLevel,
          maxAmount: input.maxAmount,
        },
      });
      return { success: true, id: result.id };
    }
  },
});

src/api/saveCalendarEvent.ts.content:
import { z } from 'zod';
import { createEndpoint, CalendarEvents, BoardColumns, CellValues, CalendarAuditLog } from 'zite-integrations-backend-sdk';
import { publishEvent } from '../lib/ably';
import { resolveWriteBoardId, smartWriteCellValue } from '../serverUtils/smartWrite';
import { lookupBoardUUID } from '../serverUtils/resolveBoardId';

// Maps native CalendarEvents field → dynamic column name (try these names in order)
const NATIVE_COL_SYNC: Array<{
  inputKey: string;
  colNames: string[];
  valueType: 'date' | 'number' | 'text';
}> = [
  { inputKey: 'eventDate',    colNames: ['Fecha y hora'],                                        valueType: 'date' },
  { inputKey: 'durationHours', colNames: ['Duración (hrs)'],                                     valueType: 'number' },
  { inputKey: 'location',     colNames: ['Ubicación Interna', 'Ubicación (interna)', 'Espacio'], valueType: 'text' },
];

// Dynamic-only fields: stored ONLY as CellValues (not in CalendarEvents table)
const DYN_ONLY_FIELDS: Array<{
  inputKey: string;
  colName: string;
  excludeType?: string;
}> = [
  { inputKey: 'dinamica',             colName: 'Dinámica' },
  { inputKey: 'perfil',               colName: 'Perfil' },
  { inputKey: 'descripcion',          colName: 'Descripción' },
  { inputKey: 'detallesAdicionales',  colName: 'Detalles adicionales' },
  { inputKey: 'detallesAdicionales2', colName: 'Detalles adicionales 2' },
  { inputKey: 'direccion',            colName: 'Ubicación', excludeType: 'Select' },
  { inputKey: 'link',                 colName: 'Link' },
];

export default createEndpoint({
  authenticated: true,
  description: 'Create or update a calendar event, keeping dynamic column CellValues in sync',
  inputSchema: z.object({
    id: z.string().optional(),
    eventName: z.string().optional(),
    projectCode: z.string().optional(),
    calendarName: z.string().optional(),
    boardId: z.string().optional(),
    eventDate: z.string().optional(),
    durationHours: z.number().optional(),
    location: z.string().optional(),
    attendees: z.string().optional(),
    inviteEmails: z.string().optional(),
    inviteSent: z.boolean().optional(),
    notes: z.string().optional(),
    parentEventId: z.string().optional(),
    // Dynamic-only fields (saved as CellValues, not in CalendarEvents)
    dinamica: z.string().optional(),
    perfil: z.string().optional(),
    descripcion: z.string().optional(),
    detallesAdicionales: z.string().optional(),
    detallesAdicionales2: z.string().optional(),
    direccion: z.string().optional(),
    link: z.string().optional(),
    restringirReenvio: z.boolean().optional(),
  }),
  outputSchema: z.object({ success: z.boolean(), id: z.string(), inviteStatusChanged: z.boolean().optional() }),
  execute: async ({ input, context }) => {
    // Strip dynamic-only fields from native record update
    const {
      id,
      dinamica, perfil, descripcion, detallesAdicionales, detallesAdicionales2, direccion, link,
      restringirReenvio,
      ...fields
    } = input;

    let eventId: string;
    let projectCode: string | undefined;
    let calendarName: string | undefined;
    // Track the effective boardId UUID for this event (used for CellValue sync + Ably)
    let effectiveBoardId: string | undefined;
    let inviteStatusChanged = false;
    const isCreate = !id;

    if (id) {
      const ev = await CalendarEvents.findOne({ id });
      projectCode = ev?.projectCode ?? fields.projectCode;
      calendarName = ev?.calendarName ?? fields.calendarName;
      effectiveBoardId = ev?.boardId || input.boardId || undefined;

      const userInputFields = { ...fields };

      if (ev?.outlookEventId && ev?.inviteStatus !== 'Cancelado' && ev?.inviteStatus !== 'Por actualizar' && (fields as any).inviteStatus === undefined) {
        (fields as any).inviteStatus = 'Por actualizar';
        inviteStatusChanged = true;
      }

      await CalendarEvents.update({ id, record: { ...fields, ...(restringirReenvio !== undefined ? { permitirReenvio: restringirReenvio } : {}) } });
      eventId = id;

      // Ably publish — UUID-first for boardId
      try {
        if (projectCode) {
          const ablyBoardId = effectiveBoardId || (calendarName ? `cal-${projectCode}-${calendarName}` : undefined);
          if (ablyBoardId) {
            const updatedFields = Object.fromEntries(
              Object.entries(userInputFields as Record<string, unknown>).filter(
                ([k, v]) => v !== undefined && k !== 'id' && k !== 'projectCode' && k !== 'calendarName'
              )
            );
            if (Object.keys(updatedFields).length > 0) {
              await publishEvent(`board:${projectCode}`, 'board.field.updated', {
                projectCode,
                boardId: ablyBoardId,
                entityType: 'event',
                fieldType: 'fixed',
                rowId: id,
                fields: updatedFields,
                senderEmail: context.user!.email,
                timestamp: new Date().toISOString(),
              });
            }
          }
        }
      } catch { /* fire and forget */ }
    } else {
      // UUID-first: use input.boardId directly if provided, otherwise fallback to legacy lookup
      let boardIdUUID: string | undefined = input.boardId || undefined;
      if (!boardIdUUID && fields.projectCode && fields.calendarName) {
        const lookup = await lookupBoardUUID(fields.projectCode, fields.calendarName, 'calendar');
        if (lookup.found && lookup.uuid) {
          boardIdUUID = lookup.uuid;
        } else {
          console.warn('[saveCalendarEvent] boardId lookup failed, leaving empty', { projectCode: fields.projectCode, calendarName: fields.calendarName, reason: lookup.reason });
        }
      }
      // Strip boardId from fields to avoid passing it twice (it's set explicitly below)
      const { boardId: _stripBoardId, ...createFields } = fields;
      const record = await CalendarEvents.create({ record: { ...createFields, boardId: boardIdUUID, ...(restringirReenvio !== undefined ? { permitirReenvio: restringirReenvio } : {}) } });
      eventId = record.id;
      projectCode = fields.projectCode;
      calendarName = fields.calendarName;
      effectiveBoardId = boardIdUUID;
    }

    // ── Sync CellValues (native + dynamic-only fields) ───────────────────────
    const nativeFieldsToSync = NATIVE_COL_SYNC.filter(({ inputKey }) => (fields as any)[inputKey] !== undefined);
    const dynFieldsToSync = DYN_ONLY_FIELDS.filter(({ inputKey }) => (input as any)[inputKey] !== undefined);
    const needsSync = nativeFieldsToSync.length > 0 || dynFieldsToSync.length > 0;

    if (needsSync && (effectiveBoardId || (projectCode && calendarName))) {
      // ── Resolve boardId for CellValue/BoardColumn writes ───────────
      let resolvedBoardId: string;
      let resolvedLegacyId: string | undefined;

      if (effectiveBoardId) {
        // UUID available — use directly, but still compute legacy for dual-read in smartWrite
        resolvedBoardId = effectiveBoardId;
        resolvedLegacyId = (projectCode && calendarName) ? `cal-${projectCode}-${calendarName}` : undefined;
      } else {
        // Legacy path
        const legacyBoardId = `cal-${projectCode}-${calendarName}`;
        resolvedBoardId = legacyBoardId;
        resolvedLegacyId = legacyBoardId;
        try {
          const resolution = await resolveWriteBoardId(legacyBoardId, {
            projectCode: projectCode!,
            boardName: calendarName!,
            boardType: 'calendar',
          });
          resolvedBoardId = resolution.writeBoardId;
          resolvedLegacyId = resolution.legacyBoardId ?? legacyBoardId;
          if (resolution.reason === 'legacy-fallback' || resolution.reason === 'input-passthrough') {
            console.warn('[saveCalendarEvent] UUID not found, using legacy boardId', { legacyBoardId, reason: resolution.reason });
          }
        } catch (err) {
          console.warn('[saveCalendarEvent] resolveWriteBoardId failed, using legacy', { legacyBoardId, error: String(err) });
        }
      }

      // ── BoardColumns read: UUID-first, legacy fallback only when needed
      let cols = (await BoardColumns.findAll({ filters: { boardId: resolvedBoardId }, limit: 100 })).records;
      if (cols.length === 0 && resolvedLegacyId && resolvedLegacyId !== resolvedBoardId) {
        cols = (await BoardColumns.findAll({ filters: { boardId: resolvedLegacyId }, limit: 100 })).records;
      }

      // Extra legacy fallback: try cal-{projectCode}-{calendarName} if cols still empty
      if (cols.length === 0 && effectiveBoardId && projectCode && calendarName) {
        const legacyFallbackId = `cal-${projectCode}-${calendarName}`;
        if (legacyFallbackId !== resolvedBoardId) {
          cols = (await BoardColumns.findAll({ filters: { boardId: legacyFallbackId }, limit: 100 })).records;
          if (cols.length > 0) {
            console.warn('[saveCalendarEvent] CellValue columns found under legacy boardId fallback', { legacyFallbackId, effectiveBoardId, eventId });
          }
        }
      }

      // Diagnostic: warn if no columns found at all
      if (cols.length === 0) {
        console.warn('[saveCalendarEvent] CellValue sync skipped: no matching columns found', { eventId, resolvedBoardId, effectiveBoardId, projectCode, calendarName });
      }

      // Sync native fields (eventDate, durationHours, location) via smartWriteCellValue
      for (const { inputKey, colNames, valueType } of nativeFieldsToSync) {
        const col = cols.find(c => colNames.includes(c.columnName ?? ''));
        if (!col) continue;
        const nativeValue = (fields as Record<string, unknown>)[inputKey];
        const isEmpty = nativeValue === null || nativeValue === undefined || nativeValue === '';
        const values: Record<string, unknown> = {};
        if (!isEmpty) {
          if (valueType === 'date') values.dateValue = nativeValue as string;
          else if (valueType === 'number') values.numberValue = nativeValue as number;
          else values.textValue = String(nativeValue);
        }
        await smartWriteCellValue({
          uuidBoardId: resolvedBoardId,
          legacyBoardId: resolvedLegacyId,
          rowId: eventId,
          columnId: col.id,
          values: values as any,
          isEmpty,
        });
      }

      // Sync dynamic-only fields via smartWriteCellValue
      for (const { inputKey, colName, excludeType } of dynFieldsToSync) {
        const col = cols.find(c => c.columnName === colName && (!excludeType || c.columnType !== excludeType));
        if (!col) continue;
        const value = (input as any)[inputKey];
        const isEmpty = !value;
        await smartWriteCellValue({
          uuidBoardId: resolvedBoardId,
          legacyBoardId: resolvedLegacyId,
          rowId: eventId,
          columnId: col.id,
          values: isEmpty ? {} : { textValue: String(value) },
          isEmpty,
        });
      }
    }

    // ── Reverse sync on CREATE without eventDate ──────────────────────────────
    if (isCreate && fields.eventDate === undefined && (effectiveBoardId || (projectCode && calendarName))) {
      (async () => {
        try {
          let rsResolvedId: string;
          let rsLegacyId: string | undefined;

          if (effectiveBoardId) {
            // UUID available — use directly, but still compute legacy for dual-read
            rsResolvedId = effectiveBoardId;
            rsLegacyId = (projectCode && calendarName) ? `cal-${projectCode}-${calendarName}` : undefined;
          } else {
            const legacyBoardId = `cal-${projectCode}-${calendarName}`;
            rsResolvedId = legacyBoardId;
            rsLegacyId = legacyBoardId;
            try {
              const resolution = await resolveWriteBoardId(legacyBoardId, {
                projectCode: projectCode!,
                boardName: calendarName!,
                boardType: 'calendar',
              });
              rsResolvedId = resolution.writeBoardId;
              rsLegacyId = resolution.legacyBoardId ?? legacyBoardId;
            } catch { /* use legacy */ }
          }

          // Read BoardColumns
          let cols = (await BoardColumns.findAll({ filters: { boardId: rsResolvedId }, limit: 100 })).records;
          if (cols.length === 0 && rsLegacyId && rsLegacyId !== rsResolvedId) {
            cols = (await BoardColumns.findAll({ filters: { boardId: rsLegacyId }, limit: 100 })).records;
          }

          const backfill: Partial<{ eventDate: string; durationHours: number; location: string }> = {};

          const dateCol = cols.find(c => c.columnName === 'Fecha y hora');
          const durCol  = cols.find(c => c.columnName === 'Duración (hrs)');
          const locCol  = cols.find(c => ['Ubicación Interna', 'Ubicación (interna)', 'Espacio'].includes(c.columnName ?? ''));

          // Cell read helper
          const findCell = async (columnId: string) => {
            let cell = await CellValues.findOne({ filters: { boardId: rsResolvedId, rowId: eventId, columnId } });
            if (!cell && rsLegacyId && rsLegacyId !== rsResolvedId) {
              cell = await CellValues.findOne({ filters: { boardId: rsLegacyId, rowId: eventId, columnId } });
            }
            return cell;
          };

          if (dateCol) {
            const cell = await findCell(dateCol.id);
            if (cell?.dateValue) backfill.eventDate = cell.dateValue;
          }
          if (durCol) {
            const cell = await findCell(durCol.id);
            if (cell?.numberValue != null) backfill.durationHours = cell.numberValue;
          }
          if (locCol) {
            const cell = await findCell(locCol.id);
            if (cell?.textValue) backfill.location = cell.textValue;
          }
          if (Object.keys(backfill).length > 0) {
            await CalendarEvents.update({ id: eventId, record: backfill });
          }
        } catch (err) {
          console.error(`[saveCalendarEvent] Reverse sync failed for id=${eventId}:`, (err as Error)?.message ?? err);
        }
      })();
    }

    // Write audit log (fire-and-forget)
    const action = isCreate ? 'Evento creado' : 'Evento actualizado';
    CalendarAuditLog.create({
      record: {
        action,
        eventName: fields.eventName ?? (isCreate ? '(sin nombre)' : undefined),
        calendarName: calendarName ?? '',
        projectCode: projectCode ?? '',
        userEmail: context.user!.email,
        userName: [context.user!.firstName, context.user!.lastName].filter(Boolean).join(' ') || context.user!.email,
        timestamp: new Date().toISOString(),
        details: isCreate
          ? `Nuevo evento creado con ID: ${eventId}`
          : `Campos actualizados: ${Object.keys({ ...fields, ...(dinamica !== undefined ? { dinamica } : {}), ...(perfil !== undefined ? { perfil } : {}) }).join(', ')} | ID: ${eventId}`,
      },
    }).catch(err => console.error('[CalendarAuditLog] Failed to write save log:', err));

    return { success: true, id: eventId, inviteStatusChanged: inviteStatusChanged || undefined };
  },
});

src/api/savePettyCashFund.ts.content:
import { z } from 'zod';
import { createEndpoint, PettyCashFunds, ZiteError } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Create or update a petty cash fund, or replenish its balance',
  inputSchema: z.object({
    id: z.string().optional(),
    action: z.enum(['save', 'replenish']),
    fundName: z.string().optional(),
    initialAmount: z.number().optional(),
    costCenter: z.string().optional(),
    status: z.string().optional(),
    notes: z.string().optional(),
    replenishAmount: z.number().optional(),
  }),
  outputSchema: z.object({ id: z.string(), success: z.boolean() }),
  execute: async ({ input, context }) => {
    const role = context.user!.role ?? '';
    if (!['Admin', 'Admin Financiero', 'Finanzas'].includes(role)) {
      throw new ZiteError({ code: 'FORBIDDEN', message: 'No tienes permisos para gestionar fondos de caja chica' });
    }

    if (input.action === 'replenish') {
      if (!input.id) throw new ZiteError({ code: 'BAD_REQUEST', message: 'Se requiere el ID del fondo' });
      const fund = await PettyCashFunds.findOne({ id: input.id });
      if (!fund) throw new ZiteError({ code: 'NOT_FOUND', message: 'Fondo no encontrado' });
      await PettyCashFunds.update({
        id: input.id,
        record: {
          currentBalance: (fund.currentBalance ?? 0) + (input.replenishAmount ?? 0),
          lastReplenishmentDate: new Date().toISOString().split('T')[0],
        },
      });
      return { id: input.id, success: true };
    }

    if (input.id) {
      await PettyCashFunds.update({
        id: input.id,
        record: {
          fundName: input.fundName,
          costCenter: input.costCenter,
          status: input.status,
          notes: input.notes,
        },
      });
      return { id: input.id, success: true };
    }

    if (!input.fundName) throw new ZiteError({ code: 'BAD_REQUEST', message: 'El nombre del fondo es requerido' });
    const created = await PettyCashFunds.create({
      record: {
        fundName: input.fundName,
        initialAmount: input.initialAmount,
        currentBalance: input.initialAmount,
        costCenter: input.costCenter,
        status: 'Activo',
        notes: input.notes,
      },
    });
    return { id: created.id, success: true };
  },
});

src/api/savePurchaseOrder.ts.content:
import { z } from 'zod';
import { createEndpoint, PurchaseOrders, PoLineItems, PoAuditLog, ZiteError } from 'zite-integrations-backend-sdk';
import { publishEvent } from '../lib/ably';

const lineItemInput = z.object({
  id: z.string().optional(),
  description: z.string().optional(),
  category: z.string().optional(),
  quantity: z.number().optional(),
  unitPrice: z.number().optional(),
  total: z.number().optional(),
});

export default createEndpoint({
  authenticated: true,
  description: 'Create or update a purchase order with its line items',
  inputSchema: z.object({
    id: z.string().optional(),
    projectCode: z.string().optional(),
    supplierName: z.string().optional(),
    issueDate: z.string().optional(),
    totalAmount: z.number().optional(),
    notes: z.string().optional(),
    category: z.string().optional(),
    paymentTerms: z.string().optional(),
    currency: z.string().optional(),
    serviceDescription: z.string().optional(),
    billingEntity: z.string().optional(),
    orderType: z.string().optional(),
    lineItems: z.array(lineItemInput).optional(),
    deletedLineItemIds: z.array(z.string()).optional(),
  }),
  outputSchema: z.object({ success: z.boolean(), id: z.string() }),
  execute: async ({ input, context }) => {
    const level = context.user!.purchaseLevel ?? 'Creador';
    const { id, lineItems, deletedLineItemIds, orderType, ...rest } = input;
    const fields = { ...rest, ...(orderType !== undefined ? { tipoDeOc: orderType } : {}) };
    const userName = [context.user!.firstName, context.user!.lastName].filter(Boolean).join(' ') || context.user!.email;

    let poId: string;

    if (id) {
      // Editing existing PO — validate permissions
      const po = await PurchaseOrders.findOne({ id });
      if (!po) throw new ZiteError({ code: 'NOT_FOUND', message: 'Orden de compra no encontrada' });

      if (po.status !== 'Borrador') {
        if (level !== 'Socios') {
          throw new ZiteError({ code: 'FORBIDDEN', message: 'Solo se pueden editar OCs en estatus Borrador' });
        }
      } else {
        // Status is Borrador: creator can edit, Aprobador/Finanzas/Socios can also edit
        const isCreator = po.createdBy === context.user!.email;
        if (!isCreator && (level === 'Creador' || level === 'Visor')) {
          throw new ZiteError({ code: 'FORBIDDEN', message: 'Solo puedes editar tus propias órdenes de compra' });
        }
      }

      await PurchaseOrders.update({ id, record: fields });
      poId = id;

      await PoAuditLog.create({
        record: {
          timestamp: new Date().toISOString(),
          purchaseOrder: id,
          action: 'Editada',
          userEmail: context.user!.email,
          userName,
          poNumber: String(po.poNumber ?? ''),
        },
      });
    } else {
      // Creating new PO — Visor cannot create
      if (level === 'Visor') {
        throw new ZiteError({ code: 'FORBIDDEN', message: 'No tienes permisos para crear órdenes de compra' });
      }
      const categoryPrefixes: Record<string, string> = {
        'Reclutamiento e Incentivos': 'RI',
        'Logística': 'LG',
        'Moderaciones': 'MD',
        'Management': 'MG',
        'Otros': 'TR',
      };
      const prefix = rest.category ? (categoryPrefixes[rest.category] ?? 'OC') : 'OC';

      const [page1, page2] = await Promise.all([
        PurchaseOrders.findAll({ limit: 2000, fields: ['poNumber'] }),
        PurchaseOrders.findAll({ limit: 2000, fields: ['poNumber'], offset: 2000 }),
      ]);
      const allPoNumbers = [...page1.records, ...page2.records]
        .map(r => String(r.poNumber ?? ''))
        .filter(Boolean);

      // Find the max number among existing POs in the 03xxx series for this prefix
      const seriesPrefix = `${prefix}-03`;
      const seriesNums = allPoNumbers
        .filter(n => n.startsWith(seriesPrefix))
        .map(n => parseInt(n.slice(prefix.length + 1), 10))
        .filter(n => !isNaN(n));
      const maxNum = seriesNums.length > 0 ? Math.max(...seriesNums) : 3000;
      const nextNum = maxNum + 1;
      const poNumber = `${prefix}-${String(nextNum).padStart(5, '0')}`;

      const record = await PurchaseOrders.create({
        record: { ...fields, poNumber, createdBy: context.user!.email, status: 'Borrador', origen: 'Sistema' },
      });
      poId = record.id;

      await PoAuditLog.create({
        record: {
          timestamp: new Date().toISOString(),
          purchaseOrder: poId,
          action: 'Creada',
          userEmail: context.user!.email,
          userName,
          poNumber,
        },
      });
    }

    if (deletedLineItemIds && deletedLineItemIds.length > 0) {
      for (const itemId of deletedLineItemIds) {
        await PoLineItems.delete({ id: itemId });
      }
    }

    if (lineItems && lineItems.length > 0) {
      const toCreate = lineItems.filter(i => !i.id).map(({ id: _id, ...item }) => ({ ...item, poId }));
      const toUpdate = lineItems.filter(i => !!i.id);
      if (toCreate.length > 0) await PoLineItems.bulkCreate({ records: toCreate });
      for (const item of toUpdate) {
        const { id: itemId, ...itemFields } = item;
        await PoLineItems.update({ id: itemId!, record: { ...itemFields, poId } });
      }
    }

    try { await publishEvent('purchases:global', 'po.changed', { id: poId, action: id ? 'updated' : 'created', senderEmail: context.user!.email, timestamp: new Date().toISOString() }); } catch { /* silent */ }
    return { success: true, id: poId };
  },
});

src/api/syncOutlookInvite.ts.content:
import { z } from 'zod';
import { createEndpoint, CalendarEvents, BoardColumns, CellValues, Boards } from 'zite-integrations-backend-sdk';

const GRAPH_BASE = 'https://graph.microsoft.com/v1.0/me';

// Parse attendees string into Graph API format
function parseAttendees(raw?: string): { emailAddress: { address: string }; type: string }[] {
  if (!raw) return [];
  return raw
    .split(/[,;\n\r]+/)
    .map(s => s.trim())
    .filter(Boolean)
    .map(address => ({ emailAddress: { address }, type: 'required' }));
}

// Add durationHours to an ISO datetime string
function addHours(isoDate: string, hours: number): string {
  const d = new Date(isoDate);
  d.setMinutes(d.getMinutes() + Math.round(hours * 60));
  return d.toISOString();
}

// Format date as "lunes 6 de abril 2026 — 18:00–19:30 hrs (Mexico City)"
function formatWhenText(startIso: string, durationHours: number): string {
  const tz = 'America/Mexico_City';
  const start = new Date(startIso);
  const end = new Date(addHours(startIso, durationHours));

  const dateOpts: Intl.DateTimeFormatOptions = {
    timeZone: tz,
    weekday: 'long',
    day: 'numeric',
    month: 'long',
    year: 'numeric',
  };
  const timeOpts: Intl.DateTimeFormatOptions = {
    timeZone: tz,
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  };

  const datePart = new Intl.DateTimeFormat('es-MX', dateOpts).format(start);
  const startTime = new Intl.DateTimeFormat('es-MX', timeOpts).format(start);
  const endTime = new Intl.DateTimeFormat('es-MX', timeOpts).format(end);

  return `${datePart} — ${startTime}–${endTime} hrs (Mexico City)`;
}

// Build the section divider HTML
const DIVIDER = `
  <div style="height:24px;"></div>
  <div style="border-top:1px solid #E9EDF3; width:100%; line-height:1px;">&nbsp;</div>
  <div style="height:24px;"></div>`;

// Build a labeled section
function section(label: string, content: string): string {
  return `${DIVIDER}
  <div style="font-variant:small-caps; letter-spacing:.4px; color:#F1A34F; font-weight:800; font-size:22px;">${label}</div>
  <div style="color:#111; font-size:18px; padding-top:6px;">${content}</div>`;
}

// Convert newline-separated text into <li> items
function toListItems(text: string): string {
  return text
    .split(/\n+/)
    .map(s => s.trim())
    .filter(Boolean)
    .map(s => `<li>${s}</li>`)
    .join('\n');
}

// Build the full HTML email body
function buildEmailHtml(opts: {
  subject: string;
  whenText: string;
  dinamica: string;
  profile: string;
  descripcion: string;
  detailsText: string;
  link: string;
}): string {
  const { subject, whenText, dinamica, profile, descripcion, detailsText, link } = opts;

  const dinamicaSection = dinamica
    ? section('Dinámica', dinamica)
    : '';

  const profileSection = profile
    ? section('Perfil', profile)
    : '';

  const descripcionSection = descripcion
    ? section('Descripción', descripcion)
    : '';

  const detailsSection = detailsText
    ? `${DIVIDER}
  <div style="font-variant:small-caps; letter-spacing:.4px; color:#F1A34F; font-weight:800; font-size:22px;">Detalles</div>
  <ul style="margin:8px 0 0 20px; padding:0; color:#111; font-size:16px; line-height:1.5;">
    ${toListItems(detailsText)}
  </ul>`
    : '';

  const linkSection = link
    ? `${DIVIDER}
  <div style="font-variant:small-caps; letter-spacing:.4px; color:#F1A34F; font-weight:800; font-size:22px;">Link de conexión</div>
  <div style="color:#111; font-size:18px; padding-top:6px; word-break:break-word;">
    <a href="${link}" target="_blank" style="color:#0e4b5a; text-decoration:underline;">${link}</a>
  </div>
  <div style="text-align:center; padding:24px 0 16px;">
    <!--[if mso]>
    <v:roundrect xmlns:v="urn:schemas-microsoft-com:vml" href="${link}" style="height:52px; v-text-anchor:middle; width:360px;" arcsize="10%" stroke="f" fillcolor="#F1A34F">
      <w:anchorlock/>
      <center style="color:#ffffff; font-family:Trebuchet MS, Arial, sans-serif; font-size:20px; font-weight:800;">Unirse a la reunión</center>
    </v:roundrect>
    <![endif]-->
    <!--[if !mso]><!-- -->
    <a href="${link}" target="_blank" style="display:block; width:100%; max-width:360px; margin:0 auto; background:#F1A34F; color:#ffffff; text-decoration:none; font-family:Trebuchet MS, Arial, sans-serif; font-size:20px; font-weight:800; text-align:center; padding:16px 24px; border-radius:8px; min-height:48px; line-height:1.2; border:1px solid #d8913a; box-shadow:0 2px 0 #cf8a3f; mso-padding-alt:16px 24px;">
      Unirse a la reunión
    </a>
    <!--<![endif]-->
  </div>
  <div style="color:#6b7280; font-size:14px; text-align:center;">
    Si el botón no funciona, copia y pega este enlace en tu navegador:<br>
    <a href="${link}" target="_blank" style="color:#0e4b5a;">${link}</a>
  </div>`
    : '';

  return `<!doctype html>
<html lang="es">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>${subject}</title>
</head>
<body style="margin:0; padding:0; background:#f7f9fc;">
  <table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="background:#f7f9fc;">
    <tr>
      <td align="center" style="padding:20px;">
        <table role="presentation" cellpadding="0" cellspacing="0" width="680" style="width:680px; max-width:100%; background:#ffffff; border:1px solid #E9EDF3; border-radius:8px;">
          <tr>
            <td style="padding:32px; font-family:Trebuchet MS, Arial, sans-serif; color:#0e4b5a;">

              <div style="text-align:center; font-size:30px; line-height:1.35; font-weight:800;">${subject}</div>
              <div style="height:16px;"></div>

              <div style="font-variant:small-caps; letter-spacing:.4px; color:#F1A34F; font-weight:800; font-size:22px;">Fecha y hora</div>
              <div style="color:#111; font-size:18px; padding-top:6px;">${whenText}</div>
              <div style="color:#6b7280; font-size:16px; padding-top:8px;">UTC−06:00 · Si te conectas desde otra zona horaria, verifica la hora local.</div>

              ${dinamicaSection}
              ${profileSection}
              ${descripcionSection}
              ${detailsSection}
              ${linkSection}

              <div style="height:24px;"></div>
              <div style="border-top:1px solid #E9EDF3; width:100%; line-height:1px;">&nbsp;</div>
              <div style="height:24px;"></div>

              <div style="text-align:center;">
                <img src="https://i.imgur.com/GayErMC.png" alt="SAPIENCE" width="260" style="display:block; margin:0 auto; border:0; outline:none; text-decoration:none;">
                <div style="color:#808a98; font-size:14px; padding-top:8px; font-weight:600; letter-spacing:.8px;">Human Insights Strategy</div>
              </div>

            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>
</body>
</html>`;
}

// Replace {{placeholder}} tokens in custom HTML with dynamic column values
// Supports conditional blocks: {{#key}}...{{/key}} — removed if key is empty
function replaceTemplatePlaceholders(
  html: string,
  boardData: Record<string, string>,
  whenText: string,
): string {
  // Helper: resolve a placeholder key to a value (or empty string)
  const resolve = (rawKey: string): string => {
    const normalized = rawKey.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[\s_-]+/g, '');
    if (normalized === 'fechahora' || normalized === 'fechayhora') return whenText;
    for (const [colName, value] of Object.entries(boardData)) {
      if (colName.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[\s_-]+/g, '') === normalized) return value;
    }
    const aliases: Record<string, string[]> = {
      'linkconexion': ['link', 'liga'],
      'linkdeconexion': ['link', 'liga'],
    };
    const aliasList = aliases[normalized];
    if (aliasList) {
      for (const alias of aliasList) {
        for (const [colName, value] of Object.entries(boardData)) {
          if (colName.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[\s_-]+/g, '') === alias) return value;
        }
      }
    }
    return '';
  };

  // Step 1: Process conditional blocks {{#key}}...{{/key}}
  let result = html.replace(
    /\{\{#(\s*[^}]+?\s*)\}\}([\s\S]*?)\{\{\/\1\}\}/g,
    (_match, rawKey: string, blockContent: string) => {
      const value = resolve(rawKey.trim());
      return value ? blockContent : '';
    }
  );

  // Step 2: Simple placeholder substitution {{key}}
  result = result.replace(/\{\{(\s*[^}#/]+?\s*)\}\}/g, (_match, rawKey: string) => {
    const value = resolve(rawKey.trim());
    return value || `{{${rawKey.trim()}}}`;
  });

  return result;
}

export default createEndpoint({
  description: 'Sync a calendar event with Outlook via Microsoft Graph API (create, update, or cancel)',
  authenticated: true,
  inputSchema: z.object({
    eventId: z.string(),
    action: z.enum(['create', 'update', 'cancel']),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    outlookEventLink: z.string().optional(),
    outlookEventId: z.string().optional(),
    inviteStatus: z.string().optional(),
    inviteBodyHtml: z.string().optional(),
    message: z.string().optional(),
  }),
  execute: async ({ input }) => {
    const accessToken = process.env.ZITE_OUTLOOK_ACCESS_TOKEN ?? '';
    if (!accessToken) throw new Error('Outlook access token not configured');

    // Fetch the calendar event
    const event = await CalendarEvents.findOne({ id: input.eventId });
    if (!event) throw new Error(`Calendar event not found: ${input.eventId}`);

    // Handle cancel via Graph API
    if (input.action === 'cancel') {
      if (event.outlookEventId) {
        const cancelRes = await fetch(`${GRAPH_BASE}/events/${event.outlookEventId}/cancel`, {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${accessToken}`,
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({ comment: 'Evento cancelado.' }),
        });
        if (!cancelRes.ok) {
          const err = await cancelRes.text();
          throw new Error(`Graph API cancel failed (${cancelRes.status}): ${err}`);
        }
      }
      await CalendarEvents.update({ id: input.eventId, record: { inviteStatus: 'Cancelado' } });
      return { success: true, inviteStatus: 'Cancelado', message: 'Invitación cancelada' };
    }

    // ── Resolve boardId: UUID-first, legacy fallback with ambiguity detection ──
    let resolvedBoardId: string | null = null;

    if (event.boardId) {
      // UUID-first: use boardId exclusively
      resolvedBoardId = event.boardId;
    } else if (event.projectCode && event.calendarName) {
      // Legacy lookup with ambiguity detection
      const { records } = await Boards.findAll({
        filters: { boardName: event.calendarName, projectCode: event.projectCode, boardType: 'calendar' } as any,
        limit: 10,
      });
      const activeBoards = records.filter(b => !b.deletedAt);
      if (activeBoards.length > 1) {
        throw new Error(`Ambiguity: ${activeBoards.length} calendars named "${event.calendarName}" for project ${event.projectCode}. Update event boardId to disambiguate.`);
      }
      if (activeBoards.length === 1) {
        resolvedBoardId = activeBoards[0].id;
      } else {
        // Last resort: legacy composite
        resolvedBoardId = `cal-${event.projectCode}-${event.calendarName}`;
      }
    }

    // Fetch dynamic column data (dinamica, profile, details, link, etc.)
    let boardData: Record<string, string> = {};
    if (resolvedBoardId) {
      const [colRes, cellRes] = await Promise.all([
        BoardColumns.findAll({ filters: { boardId: resolvedBoardId } as any, limit: 100 }),
        CellValues.findAll({ filters: { boardId: resolvedBoardId, rowId: input.eventId } as any, limit: 200 }),
      ]);

      const colMap = new Map(colRes.records.map(c => [c.id, (c.columnName ?? c.id).toLowerCase()]));
      for (const cell of cellRes.records) {
        if (!cell.columnId) continue;
        const colName = colMap.get(cell.columnId) ?? cell.columnId;
        const value = String(cell.textValue ?? cell.numberValue ?? cell.dateValue ?? '');
        if (value) boardData[colName] = value;
      }
    }

    // Helper to find a value in boardData by multiple possible key names
    const pick = (...keys: string[]): string => {
      for (const k of keys) {
        const hit = Object.entries(boardData).find(([key]) =>
          key.toLowerCase().replace(/[\s_-]/g, '') === k.toLowerCase().replace(/[\s_-]/g, '')
        );
        if (hit?.[1]) return hit[1];
      }
      return '';
    };

    const startIso = event.eventDate ?? new Date().toISOString();
    const durationHours = event.durationHours ?? 1;
    const endIso = addHours(startIso, durationHours);

    const dinamica = pick('Dinámica', 'Dinamica', 'dinamica');
    const profile = pick('Perfil', 'perfil');
    const descripcion = pick('Descripción', 'descripcion');
    const detailsText = pick('Detalles adicionales', 'Detalles', 'detalles');
    const link = pick('Link', 'link', 'Liga', 'liga');
    const customHtml = pick('HTML Invite', 'htmlinvite', 'HTML Personalizado', 'htmlpersonalizado');

    const whenText = formatWhenText(startIso, durationHours);
    const subject = event.eventName ?? 'Sesión';

    const inviteBodyHtml = (customHtml ? replaceTemplatePlaceholders(customHtml, boardData, whenText) : null) || buildEmailHtml({ subject, whenText, dinamica, profile, descripcion, detailsText, link });

    const attendees = parseAttendees(event.inviteEmails ?? '');
    // Use "Dirección" dynamic column for Outlook location (external-facing address)
    // "Ubicación Interna" (native location field) is internal-only and excluded here
    const location = pick('Dirección', 'direccion') || '';

    // Convert UTC ISO strings to CDMX local time representation for Graph API
    // Graph interprets dateTime as the given timeZone, so we must pass local CDMX time
    const toLocalCdmx = (isoUtc: string): string => {
      const d = new Date(isoUtc);
      const parts = new Intl.DateTimeFormat('en-CA', {
        timeZone: 'America/Mexico_City',
        year: 'numeric', month: '2-digit', day: '2-digit',
        hour: '2-digit', minute: '2-digit', second: '2-digit',
        hour12: false,
      }).formatToParts(d);
      const get = (t: string) => parts.find(p => p.type === t)?.value ?? '00';
      return `${get('year')}-${get('month')}-${get('day')}T${get('hour')}:${get('minute')}:${get('second')}`;
    };

    const startLocal = toLocalCdmx(startIso);
    const endLocal = toLocalCdmx(endIso);

    // Restringir reenvío: usar singleValueExtendedProperties con DoNotForward del PS_PUBLIC_STRINGS namespace
    const isRestrictedForwarding = !!event.permitirReenvio;
    const graphBase = GRAPH_BASE;

    console.log(`[syncOutlookInvite] eventId=${input.eventId} action=${input.action} restrictedForwarding=${isRestrictedForwarding} endpoint=v1.0 ${isRestrictedForwarding ? "property='DoNotForward', propertySet='00020329-0000-0000-C000-000000000046'" : 'invite normal (sin restricción de reenvío)'}`);

    const graphBody = {
      subject,
      body: { contentType: 'HTML', content: inviteBodyHtml },
      start: { dateTime: startLocal, timeZone: 'America/Mexico_City' },
      end: { dateTime: endLocal, timeZone: 'America/Mexico_City' },
      ...(location ? { location: { displayName: location } } : {}),
      ...(attendees.length ? { attendees } : {}),
      ...(isRestrictedForwarding ? {
        singleValueExtendedProperties: [
          {
            id: 'Boolean {00020329-0000-0000-C000-000000000046} Name DoNotForward',
            value: 'true',
          }
        ]
      } : {}),
    };

    let graphRes: Response;
    if (input.action === 'create') {
      graphRes = await fetch(`${graphBase}/events`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${accessToken}`, 'Content-Type': 'application/json' },
        body: JSON.stringify(graphBody),
      });
    } else {
      // update
      const existingId = event.outlookEventId;
      if (!existingId) throw new Error('No outlookEventId found to update');
      graphRes = await fetch(`${graphBase}/events/${existingId}`, {
        method: 'PATCH',
        headers: { Authorization: `Bearer ${accessToken}`, 'Content-Type': 'application/json' },
        body: JSON.stringify(graphBody),
      });
    }

    if (!graphRes.ok) {
      const err = await graphRes.text();
      console.error(`[syncOutlookInvite] Graph API error`, { eventId: input.eventId, action: input.action, status: graphRes.status, restrictedForwarding: isRestrictedForwarding, endpoint: 'v1.0', error: err });
      throw new Error(`Graph API ${input.action} failed (${graphRes.status}): ${err}`);
    }

    const created = await graphRes.json() as { id?: string; webLink?: string };

    // Verify DoNotForward property was set correctly
    if (isRestrictedForwarding && created.id) {
      const DO_NOT_FORWARD_ID = 'Boolean {00020329-0000-0000-C000-000000000046} Name DoNotForward';
      const verifyRes = await fetch(
        `${GRAPH_BASE}/events/${created.id}?$expand=singleValueExtendedProperties($filter=id eq '${DO_NOT_FORWARD_ID}')`,
        { headers: { Authorization: `Bearer ${accessToken}` } }
      );
      if (verifyRes.ok) {
        const verifyData = await verifyRes.json() as { singleValueExtendedProperties?: { id: string; value: string }[] };
        const props = verifyData.singleValueExtendedProperties ?? [];
        const doNotForward = props.find(p => p.id === DO_NOT_FORWARD_ID);
        console.log(`[syncOutlookInvite] DoNotForward verification: ${doNotForward ? `value=${doNotForward.value}` : 'NOT FOUND on event'}`);
      } else {
        console.warn(`[syncOutlookInvite] DoNotForward verification failed: ${verifyRes.status}`);
      }
    }

    const outlookEventId = created.id ?? event.outlookEventId ?? undefined;
    const outlookEventLink = created.webLink ?? event.outlookEventLink ?? undefined;

    await CalendarEvents.update({
      id: input.eventId,
      record: {
        inviteStatus: 'Enviado',
        ...(outlookEventId ? { outlookEventId } : {}),
        ...(outlookEventLink ? { outlookEventLink } : {}),
        inviteBodyHtml,
      },
    });

    return {
      success: true,
      outlookEventId,
      outlookEventLink,
      inviteStatus: 'Enviado',
      inviteBodyHtml,
      message: `Evento ${input.action === 'create' ? 'creado' : 'actualizado'} en Outlook`,
    };
  },
});

