// ── Dedupe tracking ─────────────────────────────────────────────────────────
const playedIds = new Map<string, number>(); // messageId → timestamp played
const DEDUPE_TTL_MS = 2 * 60 * 1000; // 2 minutes

/**
 * Returns true if this messageId should trigger a ding (first time seen within 2 min).
 * Automatically prunes expired entries.
 */
export function shouldPlayDing(messageId: string): boolean {
  const now = Date.now();
  for (const [id, ts] of playedIds.entries()) {
    if (now - ts > DEDUPE_TTL_MS) playedIds.delete(id);
  }
  if (playedIds.has(messageId)) return false;
  playedIds.set(messageId, now);
  return true;
}

// ── Singleton Audio (preloaded once at module import) ────────────────────────
const DING_URL = 'https://files.catbox.moe/3l4s1x.mp3';

let _dingAudio: HTMLAudioElement | null = null;

function getDingAudio(): HTMLAudioElement | null {
  if (typeof window === 'undefined') return null;
  if (!_dingAudio) {
    try {
      _dingAudio = new Audio(DING_URL);
      _dingAudio.volume = 0.7;
      _dingAudio.preload = 'auto';
      // Fire-and-forget load so the browser caches it
      _dingAudio.load();
    } catch {
      _dingAudio = null;
    }
  }
  return _dingAudio;
}

// Kick off preload immediately when the module is imported
getDingAudio();

// ── Audio unlock ─────────────────────────────────────────────────────────────
/**
 * Call this once after a user interaction (click, keypress, etc.) to unlock
 * the browser's autoplay policy for the ding audio.
 * Plays the singleton at volume 0 and immediately pauses — enough to satisfy Chrome.
 */
export function unlockAudio(): void {
  const audio = getDingAudio();
  if (!audio) return;
  try {
    const prev = audio.volume;
    audio.volume = 0;
    audio.play()
      .then(() => { audio.pause(); audio.currentTime = 0; audio.volume = prev; })
      .catch(() => { audio.volume = prev; });
  } catch { /* ignore */ }
}

// ── Audio playback ───────────────────────────────────────────────────────────
function playDingFallback(): void {
  try {
    const CtxClass =
      (window as typeof window & { webkitAudioContext?: typeof AudioContext }).webkitAudioContext ??
      window.AudioContext;
    if (!CtxClass) return;
    const ctx = new CtxClass();
    if (ctx.state === 'suspended') ctx.resume().catch(() => {});

    const t = ctx.currentTime;

    // Primary tone: 830 Hz → 600 Hz
    const osc1 = ctx.createOscillator();
    const gain1 = ctx.createGain();
    osc1.type = 'sine';
    osc1.frequency.setValueAtTime(830, t);
    osc1.frequency.exponentialRampToValueAtTime(600, t + 0.08);
    gain1.gain.setValueAtTime(0.18, t);
    gain1.gain.exponentialRampToValueAtTime(0.001, t + 0.15);
    osc1.connect(gain1);
    gain1.connect(ctx.destination);
    osc1.start(t);
    osc1.stop(t + 0.15);

    // Harmonic overtone: 1200 Hz → 900 Hz
    const osc2 = ctx.createOscillator();
    const gain2 = ctx.createGain();
    osc2.type = 'sine';
    osc2.frequency.setValueAtTime(1200, t);
    osc2.frequency.exponentialRampToValueAtTime(900, t + 0.06);
    gain2.gain.setValueAtTime(0.07, t);
    gain2.gain.exponentialRampToValueAtTime(0.001, t + 0.10);
    osc2.connect(gain2);
    gain2.connect(ctx.destination);
    osc2.start(t);
    osc2.stop(t + 0.10);
  } catch { /* ignore */ }
}

/**
 * Plays the notification ding using the preloaded singleton Audio.
 * If the audio is already playing, rewinds to the start.
 * If the mp3 fails (blocked or unavailable), logs a warning and does nothing —
 * the Browser Notification with silent:false covers background sound.
 */
export function playChatDing(): void {
  const audio = getDingAudio();
  if (audio) {
    try {
      audio.currentTime = 0;
      audio.play().catch(() => {
        console.warn('Chat ding failed — mp3 not available or blocked');
      });
      return;
    } catch {
      console.warn('Chat ding failed — mp3 not available or blocked');
    }
  }
}

// ── Browser notification ─────────────────────────────────────────────────────
export type ChatNotificationPayload = {
  channel: string;
  messageId?: string;
  senderName?: string;
  hasMention: boolean;
};

/**
 * Shows a browser Notification.
 * Skips only if the user is actively viewing the same channel.
 * Does nothing if permission has not been granted.
 *
 * silent strategy:
 *  - Tab focused  → silent: true  (custom ding already played)
 *  - Tab blurred  → silent: false (OS native sound acts as fallback
 *                                  in case Chrome blocks Audio.play())
 */
export function showChatBrowserNotification(payload: ChatNotificationPayload, activeChannel?: string): void {
  if (!('Notification' in window) || Notification.permission !== 'granted') return;
  if (activeChannel && activeChannel === payload.channel) return;
  try {
    const tabFocused = document.hasFocus();
    const title = `${payload.senderName ?? 'Nuevo mensaje'} en #${payload.channel}`;
    const body = payload.hasMention ? '💬 Te mencionaron en este canal' : '💬 Nuevo mensaje';
    const notif = new Notification(title, {
      body,
      tag: `chat-${payload.channel}`,
      silent: tabFocused, // true when focused (custom ding covers it), false when in background
    });
    notif.onclick = () => { window.focus(); notif.close(); };
    setTimeout(() => notif.close(), 6000);
  } catch { /* ignore */ }
}

src/lib/duplicateIdentity.ts.content:
import { z } from 'zod';

// ── Normalizers ─────────────────────────────────────────────────────────────

export function normalizeEmail(s?: string): string {
  return (s ?? '').toLowerCase().trim();
}

export function normalizeName(s?: string): string {
  return (s ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim()
    .replace(/\s+/g, ' ');
}

export function normalizePhone(s?: string): string {
  return (s ?? '').replace(/[^\d]/g, '');
}

// ── Zod enum & signal types ─────────────────────────────────────────────────

export type Signal = 'same_client' | 'recent' | 'old' | 'registered_only' | 'same_board_duplicate';

export const DuplicateSignalEnum = z.enum([
  'same_client', 'recent', 'old', 'registered_only', 'same_board_duplicate',
]);

export const SIGNAL_RANK: Record<Signal, number> = {
  same_client:          5,
  recent:               4,
  old:                  3,
  registered_only:      2,
  same_board_duplicate: 1,
};

export function resolveSignals(signalSet: Set<Signal>): {
  signals: Signal[];
  primaryBadge: Signal | null;
  secondaryBadges: Signal[];
} {
  const sorted = [...signalSet].sort((a, b) => SIGNAL_RANK[b] - SIGNAL_RANK[a]);
  return {
    signals:         sorted,
    primaryBadge:    sorted[0] ?? null,
    secondaryBadges: sorted.slice(1),
  };
}

// ── Union-Find ──────────────────────────────────────────────────────────────

export function makeUnionFind(ids: string[]) {
  const parent = new Map<string, string>();
  for (const id of ids) parent.set(id, id);

  function find(id: string): string {
    const p = parent.get(id) ?? id;
    if (p !== id) {
      const root = find(p);
      parent.set(id, root);
      return root;
    }
    return id;
  }

  function union(a: string, b: string) {
    const ra = find(a), rb = find(b);
    if (ra !== rb) parent.set(ra, rb);
  }

  return { find, union };
}

// ── Identity clustering ─────────────────────────────────────────────────────

export type IdentityRow = {
  id: string;
  email?: string;
  participantName?: string;
  phone?: string;
  [key: string]: any;
};

export type MatchReason = 'email' | 'name' | 'phone';

export type IdentityCluster = {
  rowIds: string[];
  matchReasons: Map<string, Set<MatchReason>>;
};

/**
 * Groups rows into identity clusters using union-find with transitive closure.
 * Two rows belong to the same cluster if they share any normalized identity field,
 * even through intermediary rows (A↔B by phone, B↔C by email → A,B,C in one cluster).
 */
export function buildIdentityClusters(rows: IdentityRow[]): Map<string, IdentityCluster> {
  if (rows.length === 0) return new Map();

  // Build per-field indexes
  const emailToIds = new Map<string, string[]>();
  const nameToIds  = new Map<string, string[]>();
  const phoneToIds = new Map<string, string[]>();

  for (const r of rows) {
    if (r.email) {
      const k = normalizeEmail(r.email);
      if (k) {
        if (!emailToIds.has(k)) emailToIds.set(k, []);
        emailToIds.get(k)!.push(r.id);
      }
    }
    if (r.participantName) {
      const k = normalizeName(r.participantName);
      if (k.length > 2) {
        if (!nameToIds.has(k)) nameToIds.set(k, []);
        nameToIds.get(k)!.push(r.id);
      }
    }
    if (r.phone) {
      const k = normalizePhone(r.phone);
      if (k.length >= 7) {
        if (!phoneToIds.has(k)) phoneToIds.set(k, []);
        phoneToIds.get(k)!.push(r.id);
      }
    }
  }

  // Run union-find
  const { find, union } = makeUnionFind(rows.map(r => r.id));

  for (const ids of emailToIds.values()) {
    for (let i = 1; i < ids.length; i++) union(ids[0], ids[i]);
  }
  for (const ids of nameToIds.values()) {
    for (let i = 1; i < ids.length; i++) union(ids[0], ids[i]);
  }
  for (const ids of phoneToIds.values()) {
    for (let i = 1; i < ids.length; i++) union(ids[0], ids[i]);
  }

  // Group rows by root
  const clusterRows = new Map<string, string[]>();
  for (const r of rows) {
    const root = find(r.id);
    if (!clusterRows.has(root)) clusterRows.set(root, []);
    clusterRows.get(root)!.push(r.id);
  }

  // Build per-row index for match-reason computation
  const rowById = new Map(rows.map(r => [r.id, r]));

  // Compute match reasons per row within each cluster
  const result = new Map<string, IdentityCluster>();

  for (const [clusterId, rowIds] of clusterRows) {
    const matchReasons = new Map<string, Set<MatchReason>>();

    // Build cluster-level field sets for comparison
    const clusterEmails = new Map<string, string[]>(); // normEmail → rowIds
    const clusterNames  = new Map<string, string[]>();
    const clusterPhones = new Map<string, string[]>();

    for (const rid of rowIds) {
      const r = rowById.get(rid)!;
      if (r.email) {
        const k = normalizeEmail(r.email);
        if (k) {
          if (!clusterEmails.has(k)) clusterEmails.set(k, []);
          clusterEmails.get(k)!.push(rid);
        }
      }
      if (r.participantName) {
        const k = normalizeName(r.participantName);
        if (k.length > 2) {
          if (!clusterNames.has(k)) clusterNames.set(k, []);
          clusterNames.get(k)!.push(rid);
        }
      }
      if (r.phone) {
        const k = normalizePhone(r.phone);
        if (k.length >= 7) {
          if (!clusterPhones.has(k)) clusterPhones.set(k, []);
          clusterPhones.get(k)!.push(rid);
        }
      }
      matchReasons.set(rid, new Set());
    }

    // A row gets a reason if its normalized field matches at least one OTHER row in the cluster
    for (const ids of clusterEmails.values()) {
      if (ids.length > 1) {
        for (const id of ids) matchReasons.get(id)!.add('email');
      }
    }
    for (const ids of clusterNames.values()) {
      if (ids.length > 1) {
        for (const id of ids) matchReasons.get(id)!.add('name');
      }
    }
    for (const ids of clusterPhones.values()) {
      if (ids.length > 1) {
        for (const id of ids) matchReasons.get(id)!.add('phone');
      }
    }

    result.set(clusterId, { rowIds, matchReasons });
  }

  return result;
}

/**
 * Helper: find the cluster that contains a specific row ID.
 */
export function findClusterForRow(
  clusters: Map<string, IdentityCluster>,
  rowId: string,
): { clusterId: string; cluster: IdentityCluster } | null {
  for (const [clusterId, cluster] of clusters) {
    if (cluster.rowIds.includes(rowId)) return { clusterId, cluster };
  }
  return null;
}

/**
 * Helper: aggregate all match reasons across a cluster into a flat array.
 */
export function aggregateClusterReasons(cluster: IdentityCluster): MatchReason[] {
  const all = new Set<MatchReason>();
  for (const reasons of cluster.matchReasons.values()) {
    for (const r of reasons) all.add(r);
  }
  return [...all];
}

