import { z } from 'zod';
import { createEndpoint, ZiteError, PoAttachments } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Delete an evidence attachment from a purchase order',
  inputSchema: z.object({ id: z.string() }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    const att = await PoAttachments.findOne({ id: input.id });
    if (!att) throw new ZiteError({ code: 'NOT_FOUND', message: 'Evidencia no encontrada' });

    const level = context.user!.purchaseLevel ?? 'Creador';
    const isHighLevel = level === 'Finanzas' || level === 'Socios';
    const isOwner = att.uploadedByEmail === context.user!.email;

    if (!isOwner && !isHighLevel) {
      throw new ZiteError({ code: 'FORBIDDEN', message: 'Solo puedes eliminar tus propias evidencias' });
    }

    await PoAttachments.delete({ id: input.id });
    return { success: true };
  },
});

src/api/exportConfigBackup.ts.content:
import { z } from 'zod';
import { createEndpoint, BoardColumns, SharedViews, Boards } from 'zite-integrations-backend-sdk';
import type { BoardsRecordType, BoardColumnsRecordType, SharedViewsRecordType } from 'zite-integrations-backend-sdk';

async function loadAllBoards(): Promise<BoardsRecordType[]> {
  const all: BoardsRecordType[] = [];
  let offset = 0;
  let hasMore = true;
  while (hasMore) {
    const res = await Boards.findAll({ offset, limit: 2000 });
    all.push(...res.records);
    hasMore = res.hasMore;
    offset += res.records.length;
  }
  return all;
}

function buildBoardMaps(boards: BoardsRecordType[]) {
  const byId = new Map<string, BoardsRecordType>();
  const legacy = new Map<string, BoardsRecordType>();
  for (const b of boards) {
    byId.set(b.id, b);
    const pc = b.projectCode || '';
    const bn = b.boardName || '';
    for (const prefix of ['pm-', 'cal-', 'recruitment-']) {
      const key = bn ? `${prefix}${pc}-${bn}` : `${prefix}${pc}`;
      if (!legacy.has(key)) legacy.set(key, b);
    }
  }
  return { byId, legacy };
}

function resolveBoard(boardId: string, maps: ReturnType<typeof buildBoardMaps>): BoardsRecordType | null {
  return maps.byId.get(boardId) || maps.legacy.get(boardId) || null;
}

export default createEndpoint({
  authenticated: true,
  description: 'Export BoardColumns or SharedViews as a full JSON backup with board resolution and stats',
  inputSchema: z.object({
    table: z.enum(['BoardColumns', 'SharedViews']),
  }),
  outputSchema: z.object({
    jsonData: z.string(),
  }),
  execute: async ({ input }) => {
    const boards = await loadAllBoards();
    const maps = buildBoardMaps(boards);

    if (input.table === 'BoardColumns') {
      // Paginate all BoardColumns
      const all: BoardColumnsRecordType[] = [];
      let offset = 0;
      let hasMore = true;
      while (hasMore) {
        const res = await BoardColumns.findAll({ offset, limit: 2000 });
        all.push(...res.records);
        hasMore = res.hasMore;
        offset += res.records.length;
      }

      const enriched = all.map(c => {
        const bid = c.boardId || '';
        const board = resolveBoard(bid, maps);
        return {
          columnId: c.id,
          columnName: c.columnName,
          columnType: c.columnType,
          columnOrder: c.columnOrder,
          optionsJson: c.optionsJson || null,
          deletedAt: c.deletedAt || null,
          deletedBy: c.deletedBy || null,
          currentBoardId: bid,
          resolvedBoardUUID: board?.id || null,
          boardProjectCode: board?.projectCode || null,
          boardName: board?.boardName || null,
          boardType: board?.boardType || null,
          boardDeleted: board?.deletedAt ? true : false,
        };
      });

      const active = enriched.filter(c => !c.deletedAt);
      const deleted = enriched.filter(c => c.deletedAt);
      const resolved = enriched.filter(c => c.resolvedBoardUUID);

      const byProject: Record<string, { active: number; deleted: number; total: number }> = {};
      for (const c of enriched) {
        const pc = c.boardProjectCode || '(unresolved)';
        if (!byProject[pc]) byProject[pc] = { active: 0, deleted: 0, total: 0 };
        byProject[pc].total++;
        if (c.deletedAt) byProject[pc].deleted++;
        else byProject[pc].active++;
      }

      const byBoardId: Record<string, number> = {};
      for (const c of enriched) {
        const bid = c.currentBoardId || '(none)';
        byBoardId[bid] = (byBoardId[bid] || 0) + 1;
      }

      const backup = {
        _exportType: 'BoardColumns_Backup',
        _exportDate: new Date().toISOString(),
        _summary: {
          totalColumns: all.length,
          activeColumns: active.length,
          deletedColumns: deleted.length,
          resolvedToBoard: resolved.length,
          unresolvedColumns: all.length - resolved.length,
          projectCount: Object.keys(byProject).length,
          uniqueBoardIds: Object.keys(byBoardId).length,
        },
        _countsByProject: byProject,
        _countsByBoardId: byBoardId,
        records: enriched,
      };

      return { jsonData: JSON.stringify(backup, null, 2) };
    }

    // SharedViews
    const all: SharedViewsRecordType[] = [];
    let offset = 0;
    let hasMore = true;
    while (hasMore) {
      const res = await SharedViews.findAll({ offset, limit: 2000 });
      all.push(...res.records);
      hasMore = res.hasMore;
      offset += res.records.length;
    }

    const enriched = all.map(v => {
      const bid = v.boardId || '';
      const board = resolveBoard(bid, maps);
      return {
        viewId: v.id,
        viewName: v.viewName,
        boardId: bid,
        projectCode: v.projectCode || null,
        boardName: v.boardName || null,
        token: v.token || null,
        sharedToken: v.sharedToken || null,
        filtersJson: v.filtersJson || null,
        visibleColumnsJson: v.visibleColumnsJson || null,
        createdBy: v.createdBy || null,
        active: v.active,
        type: v.type || null,
        viewOrder: v.viewOrder,
        resolvedBoardUUID: board?.id || null,
        resolvedBoardType: board?.boardType || null,
        boardDeleted: board?.deletedAt ? true : false,
      };
    });

    const activeViews = enriched.filter(v => v.active !== false);
    const inactiveViews = enriched.filter(v => v.active === false);
    const internal = enriched.filter(v => v.type === 'Internal');
    const external = enriched.filter(v => v.type === 'External');
    const resolved = enriched.filter(v => v.resolvedBoardUUID);

    const byProject: Record<string, { active: number; inactive: number; total: number }> = {};
    for (const v of enriched) {
      const pc = v.projectCode || '(none)';
      if (!byProject[pc]) byProject[pc] = { active: 0, inactive: 0, total: 0 };
      byProject[pc].total++;
      if (v.active === false) byProject[pc].inactive++;
      else byProject[pc].active++;
    }

    const byBoardId: Record<string, number> = {};
    for (const v of enriched) {
      const bid = v.boardId || '(none)';
      byBoardId[bid] = (byBoardId[bid] || 0) + 1;
    }

    const backup = {
      _exportType: 'SharedViews_Backup',
      _exportDate: new Date().toISOString(),
      _summary: {
        totalViews: all.length,
        activeViews: activeViews.length,
        inactiveViews: inactiveViews.length,
        internalViews: internal.length,
        externalViews: external.length,
        resolvedToBoard: resolved.length,
        unresolvedViews: all.length - resolved.length,
        projectCount: Object.keys(byProject).length,
        uniqueBoardIds: Object.keys(byBoardId).length,
      },
      _countsByProject: byProject,
      _countsByBoardId: byBoardId,
      records: enriched,
    };

    return { jsonData: JSON.stringify(backup, null, 2) };
  },
});

src/api/getApprovalPreview.ts.content:
import { z } from 'zod';
import { createEndpoint, Deals, Cotizaciones, CotizacionLineItems, Users, ZiteError } from 'zite-integrations-backend-sdk';

const RUBROS_ORDER = [
  'Reclutamiento e incentivos',
  'Moderación',
  'Management',
  'Logística y operación',
  'Back office',
];

export default createEndpoint({
  authenticated: true,
  description: 'Get a preview of the deal approval: line items grouped by rubro with assigned users from cotizacionRubros field',
  inputSchema: z.object({ dealId: z.string() }),
  outputSchema: z.object({
    rubros: z.array(z.object({
      rubroName: z.string(),
      users: z.array(z.object({ id: z.string(), name: z.string(), email: z.string() })),
      lineItems: z.array(z.object({
        id: z.string(),
        subRubro: z.string(),
        cantidad: z.number(),
        componentes: z.number(),
        unitCost: z.number(),
        total: z.number(),
        cotizacionName: z.string(),
      })),
    })),
    currency: z.string(),
  }),
  execute: async ({ input }) => {
    const deal = await Deals.findOne({ id: input.dealId });
    if (!deal) throw new ZiteError({ code: 'NOT_FOUND', message: 'Deal no encontrado' });

    // Get included cotizaciones
    const { records: allCots } = await Cotizaciones.findAll({
      filters: { deal: { contains: input.dealId } },
      limit: 200,
    });
    const included = allCots.filter(c => {
      const ids = Array.isArray(c.deal) ? c.deal : c.deal ? [c.deal] : [];
      return ids.includes(input.dealId) && (c as any).included === true;
    });

    // Get all line items, tagging each with its cotización name
    let allLineItems: any[] = [];
    if (included.length > 0) {
      const results = await Promise.all(
        included.map(c => CotizacionLineItems.findAll({
          filters: { cotizacion: { contains: c.id } },
          limit: 500,
        })),
      );
      allLineItems = results.flatMap((r, i) =>
        r.records.map(li => ({
          ...li,
          _cotizacionName: included[i].cotizacionName ?? `Cotización ${i + 1}`,
        })),
      );
    }

    // Get all users with cotizacionRubros assigned
    const { records: allUsers } = await Users.findAll({
      limit: 300,
      fields: ['id', 'email', 'firstName', 'lastName', 'cotizacionRubros'],
    });

    // Group line items by rubro
    const rubroItemsMap = new Map<string, any[]>();
    for (const li of allLineItems) {
      const rubro = li.rubro as string;
      if (!rubro) continue;
      if (!rubroItemsMap.has(rubro)) rubroItemsMap.set(rubro, []);
      rubroItemsMap.get(rubro)!.push(li);
    }

    // Build rubro → users map
    const rubroUsersMap = new Map<string, typeof allUsers>();
    for (const user of allUsers) {
      const rubros = (user as any).cotizacionRubros as string[] | undefined;
      if (!rubros || rubros.length === 0) continue;
      for (const rubro of rubros) {
        if (!rubroUsersMap.has(rubro)) rubroUsersMap.set(rubro, []);
        rubroUsersMap.get(rubro)!.push(user);
      }
    }

    const rawCurrency = (deal.currency ?? 'MXN').replace(/ 🇲🇽| 🇺🇸| 🇪🇺/g, '').trim();

    const rubroNames = [...rubroItemsMap.keys()].sort((a, b) => {
      const ai = RUBROS_ORDER.indexOf(a);
      const bi = RUBROS_ORDER.indexOf(b);
      if (ai === -1 && bi === -1) return a.localeCompare(b);
      if (ai === -1) return 1;
      if (bi === -1) return -1;
      return ai - bi;
    });

    const rubros = rubroNames.map(rubroName => {
      const items = rubroItemsMap.get(rubroName) ?? [];
      const users = rubroUsersMap.get(rubroName) ?? [];
      return {
        rubroName,
        users: users.map(u => ({
          id: u.id,
          name: [u.firstName, u.lastName].filter(Boolean).join(' ') || u.email || u.id,
          email: u.email ?? '',
        })),
        lineItems: items.map(li => {
          const cantidad = Number(li.cantidad ?? 0);
          const componentes = Number(li.componentes ?? 1);
          const unitCost = Number(li.unitCost ?? 0);
          return {
            id: li.id,
            subRubro: li.subRubro ?? '',
            cantidad,
            componentes,
            unitCost,
            total: cantidad * componentes * unitCost,
            cotizacionName: li._cotizacionName as string,
          };
        }),
      };
    });

    return { rubros, currency: rawCurrency };
  },
});

src/api/getCommercialViews.ts.content:
import { z } from 'zod';
import { createEndpoint, CommercialDashboardViews } from 'zite-integrations-backend-sdk';

const ViewOut = z.object({
  dbId: z.string(),
  viewId: z.string(),
  viewName: z.string(),
  isDefault: z.boolean(),
  isShared: z.boolean(),
  filtersJson: z.string(),
  widgetsJson: z.string(),
  dateReference: z.string(),
  sortOrder: z.number(),
});

export default createEndpoint({
  authenticated: true,
  description: 'Get commercial dashboard views for the current user (owned + shared)',
  inputSchema: z.object({}),
  outputSchema: z.object({ views: z.array(ViewOut) }),
  execute: async ({ context }) => {
    const result = await CommercialDashboardViews.findAll({});
    const userId = context.user!.id;

    const relevant = result.records.filter(v => {
      const ownerArr = Array.isArray(v.owner) ? v.owner : v.owner ? [v.owner] : [];
      return ownerArr.includes(userId) || v.isShared === true;
    });

    return {
      views: relevant
        .map(v => ({
          dbId: v.id,
          viewId: v.viewId ?? v.id,
          viewName: v.viewName ?? 'Sin nombre',
          isDefault: v.isDefault ?? false,
          isShared: v.isShared ?? false,
          filtersJson: v.filtersJson ?? '{}',
          widgetsJson: v.widgetsJson ?? '[]',
          dateReference: v.dateReference === 'Fecha de aprobación' ? 'approvalDate' : 'proposalDate',
          sortOrder: v.sortOrder ?? 0,
        }))
        .sort((a, b) => a.sortOrder - b.sortOrder),
    };
  },
});

src/api/getExpenseAuditLog.ts.content:
import { z } from 'zod';
import { createEndpoint, ExpenseAuditLog } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Get audit log entries for a specific expense',
  inputSchema: z.object({ expenseId: z.string() }),
  outputSchema: z.object({
    entries: z.array(z.object({
      id: z.string(),
      timestamp: z.string().optional().nullable(),
      action: z.string().optional().nullable(),
      userEmail: z.string().optional().nullable(),
      userName: z.string().optional().nullable(),
      comments: z.string().optional().nullable(),
      expenseNumber: z.string().optional().nullable(),
    })),
  }),
  execute: async ({ input }) => {
    const { records } = await ExpenseAuditLog.findAll({
      filters: { expense: input.expenseId } as never,
      limit: 200,
    });

    records.sort((a, b) => (b.timestamp ?? '').localeCompare(a.timestamp ?? ''));

    return {
      entries: records.map(e => ({
        id: e.id,
        timestamp: e.timestamp ?? null,
        action: e.action ?? null,
        userEmail: e.userEmail ?? null,
        userName: e.userName ?? null,
        comments: e.comments ?? null,
        expenseNumber: e.expenseNumber ?? null,
      })),
    };
  },
});

