          onRulesChange={setAdvancedFilters}
          filterMode={filterMode}
          onFilterModeChange={setFilterMode}
          colUniqueValues={colUniqueValues}
          columnFilters={columnFilters}
          onClearColumnFilter={key => setColFilter(key, new Set())}
