src/api/getLinkedEventsInfo.ts.content:
import { z } from 'zod';
import { createEndpoint, CalendarEvents, BoardColumns, CellValues } from 'zite-integrations-backend-sdk';

const eventInfoSchema = z.object({
  eventName: z.string().optional(),
  eventDate: z.string().optional(),
  durationHours: z.number().optional(),
  location: z.string().optional(),
});

export default createEndpoint({
  authenticated: true,
  description: 'Batch-fetch calendar event info for a list of eventIds. Returns a map { [eventId]: eventInfo }. Falls back to dynamic CellValues when native fields are null.',
  inputSchema: z.object({
    eventIds: z.array(z.string()),
  }),
  outputSchema: z.object({
    events: z.record(z.string(), eventInfoSchema),
  }),
  execute: async ({ input }) => {
    const { eventIds } = input;
    if (eventIds.length === 0) return { events: {} };

    const { records } = await CalendarEvents.findAll({
      filters: { id: { in: eventIds } },
      limit: 2000,
    });

    const events: Record<string, z.infer<typeof eventInfoSchema>> = {};
    const needsFallback: string[] = [];

    for (const ev of records) {
      events[ev.id] = {
        eventName: ev.eventName,
        eventDate: ev.eventDate ?? undefined,
        durationHours: ev.durationHours ?? undefined,
        location: ev.location ?? undefined,
      };
      // Flag events that need dynamic column fallback
      if (!ev.eventDate) needsFallback.push(ev.id);
    }

    // ── Fallback: read dynamic CellValues for events missing native fields ──
    if (needsFallback.length > 0) {
      // Get all cell values for these events
      const { records: cells } = await CellValues.findAll({
        filters: { rowId: { in: needsFallback } },
        limit: 2000,
      });

      if (cells.length > 0) {
        // Get unique column IDs referenced by these cells
        const colIds = [...new Set(cells.map(c => c.columnId).filter((id): id is string => !!id))];
        const { records: cols } = await BoardColumns.findAll({
          filters: { id: { in: colIds } },
          limit: 500,
        });

        const colById = new Map(cols.map(c => [c.id, c]));

        for (const cell of cells) {
          const eventId = cell.rowId;
          if (!eventId || !events[eventId]) continue;
          const col = colById.get(cell.columnId ?? '');
          if (!col?.columnName) continue;

          if (col.columnName === 'Fecha y hora' && cell.dateValue && !events[eventId].eventDate) {
            events[eventId].eventDate = cell.dateValue;
          } else if (col.columnName === 'Duración (hrs)' && cell.numberValue != null && events[eventId].durationHours == null) {
            events[eventId].durationHours = cell.numberValue;
          } else if ((col.columnName === 'Ubicación Interna' || col.columnName === 'Ubicación (interna)') && cell.textValue && !events[eventId].location) {
            events[eventId].location = cell.textValue;
          }
        }
      }
    }

    return { events };
  },
});

src/api/getProjectDocuments.ts.content:
import { z } from 'zod';
import { createEndpoint, Documents } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Fetches all documents for a given project, sorted by uploadDate desc',
  inputSchema: z.object({
    projectCode: z.string(),
  }),
  outputSchema: z.object({
    documents: z.array(z.object({
      id: z.string(),
      documentName: z.string().optional(),
      category: z.string().optional(),
      fileUrl: z.string().optional(),
      version: z.string().optional(),
      uploadDate: z.string().optional(),
      notes: z.string().optional(),
    })),
  }),
  execute: async ({ input }) => {
    const result = await Documents.findAll({
      filters: { projectCode: input.projectCode },
      limit: 500,
    });

    const sorted = result.records.sort((a, b) => {
      const da = a.uploadDate ?? '';
      const db = b.uploadDate ?? '';
      return db.localeCompare(da);
    });

    return {
      documents: sorted.map(d => ({
        id: d.id,
        documentName: d.documentName,
        category: d.category,
        fileUrl: d.fileUrl,
        version: d.version,
        uploadDate: d.uploadDate,
        notes: d.notes,
      })),
    };
  },
});

src/api/getReferenceOptions.ts.content:
import { z } from 'zod';
import { createEndpoint, Users, Projects, CalendarEvents, RecruitmentRows, Tasks } from 'zite-integrations-backend-sdk';

// ── In-memory cache (10 min TTL) ─────────────────────────────────────────────
const CACHE_TTL_MS = 10 * 60 * 1000;
let cache: {
  data: {
    members: { id: string; email?: string; firstName?: string; lastName?: string }[];
    projects: { code: string; name?: string; status?: string }[];
    events: { id: string; name: string; date?: string; projectCode?: string }[];
    groups: { name: string; projectCode?: string }[];
    tasks: { id: string; name: string; projectCode?: string; status?: string; boardName?: string }[];
  };
  expiresAt: number;
} | null = null;

export default createEndpoint({
  description: 'Get team members, projects, events, groups and tasks for the mention reference picker',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    members: z.array(z.object({
      id: z.string(),
      email: z.string().optional(),
      firstName: z.string().optional(),
      lastName: z.string().optional(),
    })),
    projects: z.array(z.object({
      code: z.string(),
      name: z.string().optional(),
      status: z.string().optional(),
    })),
    events: z.array(z.object({
      id: z.string(),
      name: z.string(),
      date: z.string().optional(),
      projectCode: z.string().optional(),
    })),
    groups: z.array(z.object({
      name: z.string(),
      projectCode: z.string().optional(),
    })),
    tasks: z.array(z.object({
      id: z.string(),
      name: z.string(),
      projectCode: z.string().optional(),
      status: z.string().optional(),
      boardName: z.string().optional(),
    })),
  }),
  execute: async () => {
    // Return cached data if still fresh
    if (cache && Date.now() < cache.expiresAt) {
      return cache.data;
    }

    const [
      { records: users },
      { records: projects },
      { records: eventRecords },
      { records: recruitRows },
      { records: taskRecords },
    ] = await Promise.all([
      Users.findAll({ limit: 100, fields: ['email', 'firstName', 'lastName', 'hiddenFromChat'] }),
      Projects.findAll({ limit: 200, fields: ['projectCode', 'fullName', 'status'] }),
      CalendarEvents.findAll({ limit: 200, fields: ['eventName', 'eventDate', 'projectCode'] }),
      RecruitmentRows.findAll({ limit: 500, fields: ['group', 'projectCode'] }),
      Tasks.findAll({ limit: 500, fields: ['taskName', 'projectCode', 'status', 'boardName', 'parentTaskId'] }),
    ]);

    // Deduplicate groups by name
    const seenGroups = new Map<string, string | undefined>();
    for (const row of recruitRows) {
      if (row.group && !seenGroups.has(row.group)) {
        seenGroups.set(row.group, row.projectCode ?? undefined);
      }
    }

    const data = {
      members: users.filter(u => !u.hiddenFromChat).map(u => ({
        id: u.id,
        email: u.email ?? undefined,
        firstName: u.firstName ?? undefined,
        lastName: u.lastName ?? undefined,
      })),
      projects: projects
        .filter(p => p.projectCode)
        .map(p => ({
          code: p.projectCode!,
          name: p.fullName ?? p.projectCode ?? '',
          status: p.status ?? undefined,
        })),
      events: eventRecords
        .filter(e => e.eventName)
        .map(e => ({
          id: e.id,
          name: e.eventName!,
          date: e.eventDate ?? undefined,
          projectCode: e.projectCode ?? undefined,
        })),
      groups: Array.from(seenGroups.entries()).map(([name, projectCode]) => ({
        name,
        projectCode,
      })),
      tasks: taskRecords
        .filter(t => t.taskName && !t.parentTaskId)
        .map(t => ({
          id: t.id,
          name: t.taskName!,
          projectCode: t.projectCode ?? undefined,
          status: t.status ?? undefined,
          boardName: t.boardName ?? undefined,
        })),
    };

    // Store in cache
    cache = { data, expiresAt: Date.now() + CACHE_TTL_MS };

    return data;
  },
});

src/api/getRubroAssignments.ts.content:
import { z } from 'zod';
import { createEndpoint, Users, RubroAssignments } from 'zite-integrations-backend-sdk';

const RUBROS_LIST = [
  'Reclutamiento e incentivos',
  'Moderación',
  'Management',
  'Logística y operación',
  'Back office',
] as const;

export default createEndpoint({
  authenticated: true,
  description: 'Get the user assigned to each quotation rubro, plus the full user list',
  inputSchema: z.object({}),
  outputSchema: z.object({
    assignments: z.array(z.object({
      id: z.string().optional(),
      rubro: z.string(),
      assignedUserId: z.string().optional(),
      assignedUserName: z.string().optional(),
      assignedUserEmail: z.string().optional(),
    })),
    users: z.array(z.object({ id: z.string(), name: z.string(), email: z.string() })),
  }),
  execute: async () => {
    const [{ records: dbAssignments }, { records: allUsers }] = await Promise.all([
      RubroAssignments.findAll({ limit: 20 }),
      Users.findAll({ limit: 300, fields: ['id', 'email', 'firstName', 'lastName'] }),
    ]);

    const userById = new Map(allUsers.map(u => [u.id, u]));

    const assignments = RUBROS_LIST.map(rubro => {
      const found = dbAssignments.find(a => a.rubro === rubro);
      const assignedUserId = found
        ? ((Array.isArray(found.assignedUser) ? found.assignedUser[0] : found.assignedUser) as string | undefined)
        : undefined;
      const user = assignedUserId ? userById.get(assignedUserId) : undefined;
      return {
        id: found?.id,
        rubro,
        assignedUserId,
        assignedUserName: user
          ? ([user.firstName, user.lastName].filter(Boolean).join(' ') || user.email || undefined)
          : undefined,
        assignedUserEmail: user?.email || undefined,
      };
    });

    return {
      assignments,
      users: allUsers.map(u => ({
        id: u.id,
        name: [u.firstName, u.lastName].filter(Boolean).join(' ') || u.email || u.id,
        email: u.email || '',
      })),
    };
  },
});

src/api/getSupplierInvoices.ts.content:
import { z } from 'zod';
import { createEndpoint, SupplierInvoices, PurchaseOrders } from 'zite-integrations-backend-sdk';

const invoiceSchema = z.object({
  id: z.string(),
  invoiceNumber: z.string().optional(),
  supplierId: z.string().optional(),
  supplierName: z.string().optional(),
  poId: z.string().optional(),
  poNumber: z.string().optional(),
  poTotalAmount: z.number().optional(),
  poServiceDescription: z.string().optional(),
  poPaymentTerms: z.string().optional(),
  amount: z.number().optional(),
  currency: z.string().optional(),
  status: z.string().optional(),
  uploadDate: z.string().optional(),
  uploadedBy: z.string().optional(),
  projectCode: z.string().optional(),
});

export default createEndpoint({
  description: 'Get all supplier invoices for internal review (lightweight list)',
  authenticated: true,
  inputSchema: z.object({
    status: z.string().optional(),
    supplierName: z.string().optional(),
    projectCode: z.string().optional(),
  }),
  outputSchema: z.object({
    invoices: z.array(invoiceSchema),
    stats: z.object({
      pending: z.number(),
      inReview: z.number(),
      validated: z.number(),
      rejected: z.number(),
      totalAmount: z.number(),
    }),
  }),
  execute: async ({ input }) => {
    // Only fetch the fields needed for the list view — NO attachments
    const invResult = await SupplierInvoices.findAll({
      limit: 500,
      fields: [
        'invoiceNumber', 'supplierId', 'supplierName', 'poId', 'poNumber',
        'amount', 'currency', 'status', 'uploadDate', 'uploadedBy', 'projectCode',
      ],
    });

    const uniquePoIds = [...new Set(invResult.records.map(inv => inv.poId).filter(Boolean))] as string[];

    const posResult = uniquePoIds.length > 0
      ? await PurchaseOrders.findAll({
          filters: { id: { in: uniquePoIds } },
          limit: 500,
          fields: ['poNumber', 'totalAmount', 'serviceDescription', 'paymentTerms'],
        })
      : { records: [] as { id: string; poNumber?: string; totalAmount?: number; serviceDescription?: string; paymentTerms?: string }[] };

    const poMap: Record<string, { poNumber: string; totalAmount: number; serviceDescription: string; paymentTerms: string }> = {};
    posResult.records.forEach(po => {
      poMap[po.id] = {
        poNumber: String(po.poNumber ?? ''),
        totalAmount: po.totalAmount ?? 0,
        serviceDescription: po.serviceDescription ?? '',
        paymentTerms: po.paymentTerms ?? '',
      };
    });

    let invoices = invResult.records.map(inv => {
      const po = inv.poId ? poMap[inv.poId] : undefined;
      return {
        id: inv.id,
        invoiceNumber: inv.invoiceNumber,
        supplierId: inv.supplierId,
        supplierName: inv.supplierName,
        poId: inv.poId,
        poNumber: po?.poNumber ?? inv.poNumber,
        poTotalAmount: po?.totalAmount,
        poServiceDescription: po?.serviceDescription,
        poPaymentTerms: po?.paymentTerms,
        amount: inv.amount,
        currency: inv.currency,
        status: inv.status,
        uploadDate: inv.uploadDate,
        uploadedBy: inv.uploadedBy,
        projectCode: inv.projectCode,
      };
    });

    if (input.status) invoices = invoices.filter(i => i.status === input.status);
    if (input.supplierName) invoices = invoices.filter(i => i.supplierName?.toLowerCase().includes(input.supplierName!.toLowerCase()));
    if (input.projectCode) invoices = invoices.filter(i => i.projectCode === input.projectCode);

    const now = new Date();
    const thisMonth = (s: string) => { const d = new Date(s); return d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear(); };

    const stats = {
      pending: invResult.records.filter(i => i.status === 'Pendiente').length,
      inReview: invResult.records.filter(i => i.status === 'En revisión').length,
      validated: invResult.records.filter(i => i.status === 'Validada' && i.uploadDate && thisMonth(i.uploadDate)).length,
      rejected: invResult.records.filter(i => i.status === 'Rechazada').length,
      totalAmount: invResult.records.filter(i => i.status === 'Validada').reduce((s, i) => s + (i.amount ?? 0), 0),
    };

    return { invoices, stats };
  },
});

src/api/rejectPurchaseOrder.ts.content:
import { z } from 'zod';
import { createEndpoint, PurchaseOrders, PoAuditLog, ZiteError } from 'zite-integrations-backend-sdk';
import { publishEvent } from '../lib/ably';

export default createEndpoint({
  authenticated: true,
  description: 'Reject a purchase order and return it to Borrador',
  inputSchema: z.object({
    id: z.string(),
    comments: z.string().min(1, 'El motivo del rechazo es obligatorio'),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    const level = context.user!.purchaseLevel ?? 'Creador';
    if (level !== 'Aprobador' && level !== 'Finanzas' && level !== 'Socios') throw new ZiteError({ code: 'FORBIDDEN', message: 'No tienes permisos para rechazar órdenes de compra' });

    const po = await PurchaseOrders.findOne({ id: input.id });
    if (!po) throw new ZiteError({ code: 'NOT_FOUND', message: 'Orden de compra no encontrada' });
    if (po.status !== 'Enviada a aprobación') throw new ZiteError({ code: 'BAD_REQUEST', message: 'Solo se pueden rechazar OCs en estatus Enviada a aprobación' });

    if (level === 'Aprobador') {
      const costCenters = context.user!.costCenters ?? [];
      if (po.category && !costCenters.includes(po.category)) {
        throw new ZiteError({ code: 'FORBIDDEN', message: 'Solo puedes rechazar OCs de tu área' });
      }
    }

    await PurchaseOrders.update({ id: input.id, record: { status: 'Borrador', rejectionReason: input.comments } });

    const userName = [context.user!.firstName, context.user!.lastName].filter(Boolean).join(' ') || context.user!.email;
    await PoAuditLog.create({
      record: {
        timestamp: new Date().toISOString(),
        purchaseOrder: input.id,
        action: 'Rechazada',
        userEmail: context.user!.email,
        userName,
        comments: input.comments,
        poNumber: String(po.poNumber ?? ''),
      },
    });

    try { await publishEvent('purchases:global', 'po.changed', { id: input.id, action: 'rejected', senderEmail: context.user!.email, timestamp: new Date().toISOString() }); } catch { /* silent */ }
    return { success: true };
  },
});

src/api/saveRubroAssignment.ts.content:
import { z } from 'zod';
import { createEndpoint, RubroAssignments } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Assign or unassign a user to a quotation rubro. Upserts by rubro name.',
  inputSchema: z.object({
    id: z.string().optional(),
    rubro: z.string(),
    assignedUserId: z.string().optional(),
  }),
  outputSchema: z.object({ success: z.boolean(), id: z.string() }),
  execute: async ({ input }) => {
    const assignedUser = input.assignedUserId ? [input.assignedUserId] : null;

    // Update existing record if ID is provided
    if (input.id) {
      const result = await RubroAssignments.update({
        id: input.id,
        record: { assignedUser: assignedUser as any },
      });
      return { success: true, id: result.id };
    }

    // Find existing by rubro name (upsert)
    const { records } = await RubroAssignments.findAll({
      filters: { rubro: input.rubro },
      limit: 5,
    });
    const existing = records[0];

    if (existing) {
      const result = await RubroAssignments.update({
        id: existing.id,
        record: { assignedUser: assignedUser as any },
      });
      return { success: true, id: result.id };
    }

    // Create new record
    const result = await RubroAssignments.create({
      record: {
        rubro: input.rubro,
        assignedUser: assignedUser as any,
      },
    });
    return { success: true, id: result.id };
  },
});

src/api/submitPurchaseOrder.ts.content:
import { z } from 'zod';
import { createEndpoint, PurchaseOrders, PoLineItems, PoAuditLog, ZiteError } from 'zite-integrations-backend-sdk';
import { publishEvent } from '../lib/ably';

export default createEndpoint({
  authenticated: true,
  description: 'Submit a purchase order for approval (Borrador → Enviada a aprobación)',
  inputSchema: z.object({ id: z.string() }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    const level = context.user!.purchaseLevel ?? 'Creador';

    const po = await PurchaseOrders.findOne({ id: input.id });
    if (!po) throw new ZiteError({ code: 'NOT_FOUND', message: 'Orden de compra no encontrada' });
    if (po.status !== 'Borrador') throw new ZiteError({ code: 'BAD_REQUEST', message: 'Solo se pueden enviar OCs en estatus Borrador' });

    // Only creator or Finanzas/Socios can submit
    const isCreator = po.createdBy === context.user!.email;
    if (!isCreator && level !== 'Finanzas' && level !== 'Socios') {
      throw new ZiteError({ code: 'FORBIDDEN', message: 'Solo puedes enviar tus propias órdenes de compra' });
    }

    if (!po.supplierName) throw new ZiteError({ code: 'BAD_REQUEST', message: 'La OC debe tener un proveedor asignado' });
    if (!po.totalAmount || po.totalAmount <= 0) throw new ZiteError({ code: 'BAD_REQUEST', message: 'La OC debe tener un monto mayor a cero' });

    const { records: lines } = await PoLineItems.findAll({ filters: { poId: input.id }, limit: 1 });
    if (lines.length === 0) throw new ZiteError({ code: 'BAD_REQUEST', message: 'La OC debe tener al menos una línea de detalle' });

    await PurchaseOrders.update({ id: input.id, record: { status: 'Enviada a aprobación', rejectionReason: '' } });

    const userName = [context.user!.firstName, context.user!.lastName].filter(Boolean).join(' ') || context.user!.email;
    await PoAuditLog.create({
      record: {
        timestamp: new Date().toISOString(),
        purchaseOrder: input.id,
        action: 'Enviada a aprobación',
        userEmail: context.user!.email,
        userName,
        poNumber: String(po.poNumber ?? ''),
      },
    });

    try { await publishEvent('purchases:global', 'po.changed', { id: input.id, action: 'submitted', senderEmail: context.user!.email, timestamp: new Date().toISOString() }); } catch { /* silent */ }
    return { success: true };
  },
});

