import React, { useState, useEffect, useRef, useMemo, memo } from 'react';
import { saveTask, reorderTasks, duplicateRows } from 'zite-endpoints-sdk';
import { Button } from '@/components/ui/button';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { Checkbox } from '@/components/ui/checkbox';
import { toast } from 'sonner';
import { Plus, Pencil, Trash2, ChevronRight, ChevronDown, ChevronUp, FolderPlus, GripVertical, ArrowUpDown, ClipboardCopy, ChevronsDownUp, ChevronsUpDown, CornerDownRight } from 'lucide-react';
import { DynamicColumnHeaders, DynamicColumnCells, type DynCols } from '../DynamicColumns';
import { ColumnFilterPopover } from '../ColumnFilterPopover';
import { getGroupColor, useResizableCol, cellDisplayValue } from '../table/tableUtils';
import { InlineInput } from '../table/InlineInput';
import { GroupSectionHeader } from '../table/GroupSectionHeader';
import { ChildSubTable } from '../table/ChildSubTable';
import { TimelineCell } from './TimelineCell';
import { Task } from './pmTypes';

export const TaskList = memo(function TaskList({ tasks, onEdit, onDelete, onSaveName, onQuickCreate, onCreateGroup, dynCols, childDynCols, groupDynCols, childLabel, onChildLabelChange, columnFilters, setColFilter, colUniqueValues, hiddenColumns, onTasksChange, sortColumn, sortDirection, toggleSort, onDuplicateGroup, onRefresh, onBulkDelete, onGroupStructureChanged }: {
  tasks: Task[];
  onEdit: (t: Task) => void;
  onDelete: (id: string) => void;
  onSaveName: (id: string, name: string) => void;
  onQuickCreate: (name: string, parentId?: string, groupId?: string) => void;
  onCreateGroup: () => void;
  dynCols: DynCols; childDynCols: DynCols; groupDynCols: DynCols;
  childLabel: string; onChildLabelChange: (l: string) => void;
  columnFilters?: Record<string, Set<string>>;
  setColFilter?: (col: string, vals: Set<string>) => void;
  colUniqueValues?: (col: string) => string[];
  hiddenColumns: Set<string>;
  onTasksChange: React.Dispatch<React.SetStateAction<Task[]>>;
  sortColumn: string | null;
  sortDirection: 'asc' | 'desc';
  toggleSort: (col: string) => void;
  onDuplicateGroup?: (groupId: string) => void;
  onRefresh?: () => void;
  onBulkDelete?: (ids: string[]) => void;
  onGroupStructureChanged?: () => void;
}) {
  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set(['__none__']));
  const [expandedTasks,  setExpandedTasks]  = useState<Set<string>>(new Set());
  const [editingName,    setEditingName]    = useState<string | null>(null);
  const [addingChildTo,  setAddingChildTo]  = useState<string | null>(null);
  const [newChildName,   setNewChildName]   = useState('');
  const [newTaskNames,   setNewTaskNames]   = useState<Record<string, string>>({});
  const [selectedIds,    setSelectedIds]    = useState<Set<string>>(new Set());
  const [duplicating,    setDuplicating]    = useState(false);
  const [dragGroupId,    setDragGroupId]    = useState<string | null>(null);

  const showBulkConfirm = (label: string, applyAll: () => void) => {
    if (selectedIds.size <= 1) return;
    toast(`¿Aplicar a las ${selectedIds.size} filas seleccionadas?`, {
      description: `"${label}"`,
      action: { label: 'Aplicar a todas', onClick: applyAll },
      cancel: { label: 'Solo esta fila', onClick: () => {} },
      duration: 5000,
    });
  };
  const [dropTargetId,   setDropTargetId]   = useState<string | null>(null);
  const [dragRowId,      setDragRowId]      = useState<string | null>(null);
  const [dropRowGroupId, setDropRowGroupId] = useState<string | null>(null);

  const dropRowGroupRef = useRef<string | null>(null);
  const dropTargetRef   = useRef<{ rowId: string; position: 'before' | 'after' } | null>(null);
  const dropLineRef     = useRef<HTMLDivElement>(null);
  const dragRowIdRef    = useRef<string | null>(null);
  const dragClientYRef  = useRef<number>(0);
  const rafIdRef        = useRef<number | null>(null);
  const tableContainerRef = useRef<HTMLDivElement>(null);

  const nameCol = useResizableCol('pm-tasks-name-col', 250, 120);

  // ── Fixed date columns ────────────────────────────────────────────────────
  const startDynCol = dynCols.columns.find(c => c.columnName === 'Inicio');
  const endDynCol   = dynCols.columns.find(c => c.columnName === 'Fin');

  const getEffectiveDate = (task: Task, field: 'start' | 'end'): string => {
    const dynCol = field === 'start' ? startDynCol : endDynCol;
    if (dynCol) {
      const v = dynCols.getCellVal(task.id, dynCol.id)?.dateValue?.split('T')[0];
      if (v) return v;
    }
    return (field === 'start' ? task.startDate : task.endDate)?.split('T')[0] || '';
  };

  const saveTimelineRange = async (taskId: string, start: string, end: string) => {
    onTasksChange(prev => prev.map(t => t.id === taskId ? { ...t, startDate: start || undefined, endDate: end || undefined } : t));
    try {
      await saveTask({ id: taskId, startDate: start || undefined, endDate: end || undefined });
      if (startDynCol) dynCols.setCellVal(taskId, startDynCol.id, { dateValue: start ? start + 'T00:00:00' : undefined });
      if (endDynCol)   dynCols.setCellVal(taskId, endDynCol.id,   { dateValue: end   ? end   + 'T00:00:00' : undefined });
    } catch {
      toast.error('Error al guardar fechas');
    }
  };

  const hideDropLine = () => { if (dropLineRef.current) dropLineRef.current.style.opacity = '0'; };
  const cancelRaf = () => { if (rafIdRef.current !== null) { cancelAnimationFrame(rafIdRef.current); rafIdRef.current = null; } };

  const seenGroupIds = useRef(new Set<string>(['__none__']));
  const groupColIds = groupDynCols.columns.map(c => c.id).join(',');
  useEffect(() => {
    setExpandedGroups(prev => {
      const n = new Set(prev);
      groupDynCols.columns.forEach(g => { if (!seenGroupIds.current.has(g.id)) { n.add(g.id); seenGroupIds.current.add(g.id); } });
      return n;
    });
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [groupColIds]);

  const toggleSelect = (id: string) => setSelectedIds(prev => { const n = new Set(prev); n.has(id) ? n.delete(id) : n.add(id); return n; });
  const groups = groupDynCols.columns;

  const getTaskGroupId = (taskId: string) =>
    groups.find(g => groupDynCols.getCellVal(taskId, g.id)?.textValue === '1')?.id ?? null;

  const recentColors = useMemo(() => {
    const colorCols = dynCols.columns.filter(c => c.columnType === 'Color');
    if (!colorCols.length) return [];
    const seen = new Set<string>();
    const result: string[] = [];
    for (const t of tasks) {
      for (const col of colorCols) {
        const hex = dynCols.getCellVal(t.id, col.id)?.textValue;
        if (hex && !seen.has(hex)) { seen.add(hex); result.push(hex); }
        if (result.length >= 10) return result;
      }
    }
    return result;
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [dynCols.columns, dynCols.getCellVal, tasks]);

  const sortedTopLevel = useMemo(() => {
    const topLevel = tasks.filter(t => !t.parentTaskId);
    if (!sortColumn) return topLevel;
    return [...topLevel].sort((a, b) => {
      let aVal = '';
      let bVal = '';
      if (sortColumn === 'taskName') {
        aVal = (a.taskName || '').toLowerCase();
        bVal = (b.taskName || '').toLowerCase();
      } else {
        const col = dynCols.columns.find(c => c.id === sortColumn);
        aVal = (cellDisplayValue(dynCols.getCellVal(a.id, sortColumn), col?.columnType) || '').toLowerCase();
        bVal = (cellDisplayValue(dynCols.getCellVal(b.id, sortColumn), col?.columnType) || '').toLowerCase();
      }
      if (!aVal && bVal) return 1;
      if (aVal && !bVal) return -1;
      const cmp = aVal < bVal ? -1 : aVal > bVal ? 1 : 0;
      return sortDirection === 'asc' ? cmp : -cmp;
    });
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tasks, sortColumn, sortDirection, dynCols.getCellVal, dynCols.columns]);

  const grouped: Record<string, Task[]> = { __none__: [] };
  for (const g of groups) grouped[g.id] = [];
  for (const t of sortedTopLevel) {
    const gid = getTaskGroupId(t.id);
    if (gid && grouped[gid]) grouped[gid].push(t);
    else grouped.__none__.push(t);
  }

  const groupOrder = useMemo(
    () => [{ id: '__none__', columnName: 'Sin grupo', columnType: undefined as string | undefined }, ...groups],
    [groups]
  );

  const toggleGroup = (id: string) => setExpandedGroups(prev => { const n = new Set(prev); n.has(id) ? n.delete(id) : n.add(id); return n; });
  const getChildTasks = (id: string) => tasks.filter(t => t.parentTaskId === id);

  const sortedDynCols = [...dynCols.columns].sort((a, b) => (a.columnOrder ?? 0) - (b.columnOrder ?? 0));
  const visibleDynCols = sortedDynCols.filter(c => !hiddenColumns.has(c.id));
  const totalCols = 2 + 1 + visibleDynCols.length + 1; // +1 for fixed Timeline column

  const handleRowOnRowDrop = async (draggedId: string, targetTask: Task, position: 'before' | 'after') => {
    const targetGroupId  = getTaskGroupId(targetTask.id) ?? '__none__';
    const draggedGroupId = getTaskGroupId(draggedId) ?? '__none__';
    const draggedTask = sortedTopLevel.find(t => t.id === draggedId);
    if (!draggedTask) return;

    const sortedGroup = [...(grouped[targetGroupId] ?? [])]
      .sort((a, b) => (a.order ?? 0) - (b.order ?? 0))
      .filter(t => t.id !== draggedId);

    const targetIdx = sortedGroup.findIndex(t => t.id === targetTask.id);
    const insertIdx = position === 'before' ? Math.max(0, targetIdx) : targetIdx + 1;
    sortedGroup.splice(insertIdx, 0, { ...draggedTask });

    const updates = sortedGroup.map((t, i) => ({ id: t.id, order: (i + 1) * 1000 }));
    const orderMap = new Map(updates.map(u => [u.id, u.order]));

    onTasksChange(prev => prev.map(t => orderMap.has(t.id) ? { ...t, order: orderMap.get(t.id)! } : t));

    if (draggedGroupId !== targetGroupId) {
      // Clear ALL groups for this task (not just the detected one) to fix phantom assignments
      await Promise.all(groups.filter(g => groupDynCols.getCellVal(draggedId, g.id)?.textValue === '1').map(g => groupDynCols.setCellVal(draggedId, g.id, { textValue: undefined })));
      if (targetGroupId !== '__none__') await groupDynCols.setCellVal(draggedId, targetGroupId, { textValue: '1' });
      toast.success('Tarea movida al grupo');
    }

    await reorderTasks({ updates });
  };

  const handleGroupDrop = async (e: React.DragEvent, targetGroupId: string) => {
    e.preventDefault();
    dropTargetRef.current = null; cancelRaf(); hideDropLine();
    if (e.dataTransfer.types.includes('rowid')) {
      const rowId = e.dataTransfer.getData('rowId');
      if (rowId) {
        const draggedGroupId = getTaskGroupId(rowId) ?? '__none__';
        if (draggedGroupId !== targetGroupId) {
          // Clear ALL groups for this task to fix phantom assignments
          await Promise.all(groups.filter(g => groupDynCols.getCellVal(rowId, g.id)?.textValue === '1').map(g => groupDynCols.setCellVal(rowId, g.id, { textValue: undefined })));
          if (targetGroupId !== '__none__') await groupDynCols.setCellVal(rowId, targetGroupId, { textValue: '1' });
          toast.success('Tarea movida al grupo');
        }
        const targetGroupTasks = grouped[targetGroupId] ?? [];
        const maxOrder = targetGroupTasks.length > 0 ? Math.max(...targetGroupTasks.map(t => t.order ?? 0)) + 1000 : 1000;
        onTasksChange(prev => prev.map(t => t.id === rowId ? { ...t, order: maxOrder } : t));
        await reorderTasks({ updates: [{ id: rowId, order: maxOrder }] });
      }
      setDragRowId(null); setDropRowGroupId(null); dropRowGroupRef.current = null;
      return;
    }
    if (!dragGroupId || dragGroupId === targetGroupId || targetGroupId === '__none__') return;
    const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
    const side = e.clientY < rect.top + rect.height / 2 ? 'left' : 'right';
    await groupDynCols.reorderColumns(dragGroupId, targetGroupId, side);
    setDragGroupId(null); setDropTargetId(null);
  };

  const containerDragOver = (e: React.DragEvent) => {
    if (!e.dataTransfer.types.includes('rowid')) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    dragClientYRef.current = e.clientY;
    if (rafIdRef.current !== null) return;
    rafIdRef.current = requestAnimationFrame(() => {
      rafIdRef.current = null;
      const container = tableContainerRef.current;
      const dropLine  = dropLineRef.current;
      const draggedId = dragRowIdRef.current;
      if (!container || !dropLine || !draggedId) return;
      const clientY = dragClientYRef.current;
      const containerRect = container.getBoundingClientRect();
      const candidates = Array.from(container.querySelectorAll<HTMLTableRowElement>('tr[data-row-id]'))
        .filter(tr => tr.getAttribute('data-row-id') !== draggedId);
      if (candidates.length === 0) { hideDropLine(); return; }
      if (dropRowGroupRef.current) { dropRowGroupRef.current = null; setDropRowGroupId(null); }
      let targetId = candidates[candidates.length - 1].getAttribute('data-row-id')!;
      let position: 'before' | 'after' = 'after';
      let lineY = candidates[candidates.length - 1].getBoundingClientRect().bottom;
      for (const tr of candidates) {
        const rect = tr.getBoundingClientRect();
        const mid  = rect.top + rect.height / 2;
        if (clientY < mid) { targetId = tr.getAttribute('data-row-id')!; position = 'before'; lineY = rect.top; break; }
      }
      dropTargetRef.current = { rowId: targetId, position };
      const localY = lineY - containerRect.top + container.scrollTop;
      dropLine.style.transform = `translateY(${localY - 1.5}px)`;
      dropLine.style.opacity   = '1';
    });
  };

  const containerDrop = (e: React.DragEvent) => {
    if (!e.dataTransfer.types.includes('rowid')) return;
    e.preventDefault();
    const srcRowId = e.dataTransfer.getData('rowId');
    const cur = dropTargetRef.current;
    dropTargetRef.current = null; cancelRaf(); hideDropLine();
    dropRowGroupRef.current = null; dragRowIdRef.current = null;
    if (!srcRowId || !cur) { setDragRowId(null); setDropRowGroupId(null); return; }
    const targetTask = tasks.find(t => t.id === cur.rowId);
    if (!targetTask || srcRowId === targetTask.id) { setDragRowId(null); setDropRowGroupId(null); return; }
    handleRowOnRowDrop(srcRowId, targetTask, cur.position);
    setDragRowId(null); setDropRowGroupId(null);
  };

  const containerDragLeave = (e: React.DragEvent) => {
    const container = tableContainerRef.current;
    if (container && !container.contains(e.relatedTarget as Node)) {
      dropTargetRef.current = null; cancelRaf(); hideDropLine();
    }
  };

  const cellBorder = '1px solid hsl(var(--border) / 0.3)';

  const renderRow = (task: Task) => {
    const children   = getChildTasks(task.id);
    const isExpanded = expandedTasks.has(task.id);
    const showNested = isExpanded && (children.length > 0 || addingChildTo === task.id);
    const taskGroupId = getTaskGroupId(task.id);
    const taskGroupColorId = taskGroupId ? groups.find(g => g.id === taskGroupId)?.columnType : undefined;
    const rowColor = taskGroupId ? getGroupColor(taskGroupColorId) : undefined;
    const effectiveStart = getEffectiveDate(task, 'start');
    const effectiveEnd   = getEffectiveDate(task, 'end');

    return (
      <React.Fragment key={task.id}>
        <tr data-row-id={task.id} className={`group${dragRowId === task.id ? ' opacity-25' : ''}${selectedIds.has(task.id) ? ' bg-primary/5' : ''}`}>
          <td className={`h-9 pl-1 group-hover:bg-muted ${selectedIds.has(task.id) ? 'bg-primary/5' : 'bg-card'}`}
            style={{ position: 'sticky', left: 0, zIndex: 10, borderBottom: cellBorder, borderLeft: rowColor ? `3px solid ${rowColor}` : '3px solid transparent' }}>
            <div className="flex items-center gap-0.5 h-full">
              <div
                draggable
                onDragStart={e => { e.stopPropagation(); e.dataTransfer.setData('rowId', task.id); e.dataTransfer.effectAllowed = 'move'; setDragRowId(task.id); dragRowIdRef.current = task.id; }}
                onDragEnd={() => { dragRowIdRef.current = null; cancelRaf(); hideDropLine(); setDragRowId(null); setDropRowGroupId(null); dropTargetRef.current = null; dropRowGroupRef.current = null; }}
                onClick={e => e.stopPropagation()}
                className="opacity-0 group-hover:opacity-100 cursor-grab active:cursor-grabbing text-muted-foreground/30 hover:text-muted-foreground transition-all flex-shrink-0 py-1"
              >
                <GripVertical className="w-3 h-3" />
              </div>
              <Checkbox checked={selectedIds.has(task.id)} onCheckedChange={() => toggleSelect(task.id)} className="h-3.5 w-3.5" />
            </div>
          </td>

          <td className={`px-2 py-0 h-9 overflow-hidden group-hover:bg-muted border-r border-border/40 ${selectedIds.has(task.id) ? 'bg-primary/5' : 'bg-card'}`}
            style={{ position: 'sticky', left: 35, zIndex: 10, borderBottom: cellBorder }}>
            <div className="flex items-center gap-1.5 w-full h-full">
              <button onClick={() => setExpandedTasks(p => { const n = new Set(p); n.has(task.id) ? n.delete(task.id) : n.add(task.id); return n; })} className="text-muted-foreground flex-shrink-0 hover:text-foreground w-4">
                {(children.length > 0 || isExpanded) ? (isExpanded ? <ChevronDown className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />) : <span className="w-3 inline-block" />}
              </button>
              {editingName === task.id ? (
                <InlineInput value={task.taskName ?? ''} className="font-medium text-foreground flex-1"
                  onSave={val => {
                    if (val.trim()) {
                      onSaveName(task.id, val.trim());
                      if (selectedIds.has(task.id)) showBulkConfirm(val.trim(), () => [...selectedIds].filter(id => id !== task.id).forEach(id => onSaveName(id, val.trim())));
                    }
                    setEditingName(null);
                  }}
                  onCancel={() => setEditingName(null)} />
              ) : (
                <span className="text-sm font-medium cursor-pointer hover:text-primary flex-1 truncate"
                  onClick={() => setEditingName(task.id)}>{task.taskName}</span>
              )}
              <div className="flex items-center gap-0.5 flex-shrink-0 opacity-0 group-hover:opacity-100 transition-opacity">
                <button title={`Agregar ${childLabel}`} onClick={() => { setAddingChildTo(task.id); setNewChildName(''); setExpandedTasks(p => new Set([...p, task.id])); }} className="text-muted-foreground hover:text-primary p-0.5 rounded hover:bg-primary/10"><Plus className="w-3 h-3" /></button>
                <button onClick={() => onEdit(task)} className="text-muted-foreground hover:text-foreground p-0.5 rounded hover:bg-muted"><Pencil className="w-3 h-3" /></button>
                <button onClick={() => onDelete(task.id)} className="text-muted-foreground hover:text-destructive p-0.5 rounded hover:bg-destructive/10"><Trash2 className="w-3 h-3" /></button>
              </div>
            </div>
          </td>

          <td style={{ borderBottom: cellBorder, borderRight: '1px solid hsl(var(--border) / 0.3)', padding: 0, width: 180 }} className="group-hover:bg-muted">
            <TimelineCell taskId={task.id} startDate={effectiveStart} endDate={effectiveEnd} onSave={saveTimelineRange} />
          </td>
          <DynamicColumnCells rowId={task.id} dynCols={dynCols} hiddenColumns={hiddenColumns} recentColors={recentColors}
            colUniqueValues={colUniqueValues}
            selectedIds={selectedIds}
            onBulkSave={(colId, value, label) => showBulkConfirm(label, () => {
              const ops = [...selectedIds].filter(id => id !== task.id).map(id => ({ rowId: id, colId, value }));
              if (ops.length > 0) dynCols.batchSetCellVals(ops);
            })} />
        </tr>

        {showNested && (
          <tr>
            <td colSpan={totalCols} style={{ padding: 0, borderBottom: '1px solid hsl(var(--border) / 0.2)' }}>
              <ChildSubTable childDynCols={childDynCols} childLabel={childLabel} onLabelChange={onChildLabelChange}
                addingName={addingChildTo === task.id ? newChildName : ''}
                onAddingNameChange={v => { setAddingChildTo(task.id); setNewChildName(v); }}
                onCommit={() => { if (newChildName.trim()) { onQuickCreate(newChildName.trim(), task.id); setNewChildName(''); setAddingChildTo(null); } }}
                onCancel={() => { setAddingChildTo(null); setNewChildName(''); }}>
                {children.map(child => (
                  <tr key={child.id} className="hover:bg-muted/20 border-t border-border/20 group/child">
                    <td className="pl-2 pr-0 py-1.5 w-8"><Checkbox checked={selectedIds.has(child.id)} onCheckedChange={() => toggleSelect(child.id)} className="h-3.5 w-3.5" /></td>
                    <td className="px-3 py-1.5 min-w-[180px]">
                      <div className="flex items-center gap-1.5">
                        <CornerDownRight className="w-3 h-3 text-muted-foreground/30 flex-shrink-0" />
                        {editingName === child.id ? (
                          <InlineInput value={child.taskName ?? ''} className="text-foreground flex-1"
                            onSave={val => { if (val.trim()) onSaveName(child.id, val.trim()); setEditingName(null); }}
                            onCancel={() => setEditingName(null)} />
                        ) : (
                          <span className="text-sm cursor-pointer hover:text-primary flex-1 truncate" onClick={() => setEditingName(child.id)}>{child.taskName}</span>
                        )}
                        <div className="flex items-center gap-0.5 flex-shrink-0 opacity-0 group-hover/child:opacity-100 transition-opacity">
                          <button onClick={() => onEdit(child)} className="text-muted-foreground hover:text-foreground p-0.5 rounded hover:bg-muted"><Pencil className="w-3 h-3" /></button>
                          <button onClick={() => onDelete(child.id)} className="text-muted-foreground hover:text-destructive p-0.5 rounded hover:bg-destructive/10"><Trash2 className="w-3 h-3" /></button>
                        </div>
                      </div>
                    </td>
                    <DynamicColumnCells rowId={child.id} dynCols={childDynCols} />
                  </tr>
                ))}
              </ChildSubTable>
            </td>
          </tr>
        )}
      </React.Fragment>
    );
  };

  return (
    <>
      {selectedIds.size > 0 && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 z-50 flex items-center gap-3 px-4 py-2.5 bg-primary text-primary-foreground rounded-xl shadow-lg animate-in slide-in-from-bottom-2 duration-200">
          <span className="text-sm font-medium">{selectedIds.size} seleccionada{selectedIds.size > 1 ? 's' : ''}</span>
          <div className="flex items-center gap-1 ml-auto">
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button size="sm" variant="outline" className="h-7 text-xs gap-1 bg-primary-foreground/15 border-primary-foreground/25 text-primary-foreground hover:bg-primary-foreground/25"><FolderPlus className="w-3 h-3" /> Mover a...</Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" className="w-48">
                <DropdownMenuItem onClick={async () => { for (const id of selectedIds) { const g = getTaskGroupId(id); if (g) await groupDynCols.setCellVal(id, g, { textValue: undefined }); } setSelectedIds(new Set()); toast.success('Movido a Sin grupo'); }} className="text-xs gap-2">
                  <div className="w-2.5 h-2.5 rounded-full border border-dashed border-muted-foreground/40 flex-shrink-0" />Sin grupo
                </DropdownMenuItem>
                <div className="my-1 border-t border-border/30" />
                {groups.map(g => (
                  <DropdownMenuItem key={g.id} onClick={async () => { for (const id of selectedIds) { const cg = getTaskGroupId(id); if (cg) await groupDynCols.setCellVal(id, cg, { textValue: undefined }); await groupDynCols.setCellVal(id, g.id, { textValue: '1' }); } setSelectedIds(new Set()); toast.success(`Movido a ${g.columnName}`); }} className="text-xs gap-2">
                    <div className="w-2.5 h-2.5 rounded-full flex-shrink-0" style={{ backgroundColor: getGroupColor(g.columnType) }} />
                    <span className="truncate">{g.columnName}</span>
                  </DropdownMenuItem>
                ))}
              </DropdownMenuContent>
            </DropdownMenu>
            <Button size="sm" variant="outline"
              className="h-7 text-xs gap-1 bg-primary-foreground/15 border-primary-foreground/25 text-primary-foreground hover:bg-primary-foreground/25"
              disabled={duplicating}
              onClick={async () => {
                setDuplicating(true);
                try {
                  await duplicateRows({ ids: [...selectedIds], tableType: 'task' });
                  toast.success(`${selectedIds.size} tarea${selectedIds.size !== 1 ? 's' : ''} duplicada${selectedIds.size !== 1 ? 's' : ''}`);
                  setSelectedIds(new Set());
                  onRefresh?.();
                  dynCols.softReload(); childDynCols.softReload(); groupDynCols.softReload();
                } catch { toast.error('Error al duplicar'); }
                setDuplicating(false);
              }}
            >
              {duplicating ? <div className="w-3 h-3 border border-primary-foreground/30 border-t-primary-foreground rounded-full animate-spin" /> : <ClipboardCopy className="w-3 h-3" />}
              Duplicar
            </Button>
            <Button size="sm" variant="outline" className="h-7 text-xs gap-1 bg-destructive/80 text-destructive-foreground hover:bg-destructive border-0" onClick={() => { if (onBulkDelete) { onBulkDelete([...selectedIds]); } else { selectedIds.forEach(id => onDelete(id)); } setSelectedIds(new Set()); }}><Trash2 className="w-3 h-3" /> Eliminar</Button>
            <Button size="sm" variant="ghost" className="h-7 text-xs text-primary-foreground/70 hover:text-primary-foreground hover:bg-primary-foreground/10" onClick={() => setSelectedIds(new Set())}>Cancelar</Button>
          </div>
        </div>
      )}
      <div className="flex items-center gap-2 px-4 py-1.5 border-b border-border/20 bg-muted/20 flex-shrink-0">
        <Button size="sm" variant="outline" className="gap-1.5 h-7 text-xs"
          onClick={() => expandedGroups.size > 0 ? setExpandedGroups(new Set()) : setExpandedGroups(new Set(groupOrder.map(g => g.id)))}>
          {expandedGroups.size > 0 ? <ChevronsDownUp className="w-3.5 h-3.5" /> : <ChevronsUpDown className="w-3.5 h-3.5" />}
          {expandedGroups.size > 0 ? 'Colapsar todos' : 'Expandir todos'}
        </Button>
      </div>

      <div ref={tableContainerRef}
        className="bg-card border rounded-lg overflow-auto max-h-[calc(100vh-360px)]"
        style={{ position: 'relative' }}
        onDragOver={containerDragOver}
        onDrop={containerDrop}
        onDragLeave={containerDragLeave}
      >
        <div ref={dropLineRef} style={{
          position: 'absolute', left: 0, right: 0, height: 3, pointerEvents: 'none', opacity: 0, zIndex: 50,
          background: 'hsl(var(--primary))', borderRadius: 9999, boxShadow: '0 0 10px hsl(var(--primary) / 0.6)',
          willChange: 'transform, opacity', transform: 'translateY(0)', transition: 'opacity 0.08s',
        }}>
          <div style={{ position: 'absolute', left: 4, top: '50%', transform: 'translateY(-50%)', width: 10, height: 10, borderRadius: '50%', background: 'hsl(var(--primary))', border: '2px solid hsl(var(--card))' }} />
          <div style={{ position: 'absolute', right: 4, top: '50%', transform: 'translateY(-50%)', width: 10, height: 10, borderRadius: '50%', background: 'hsl(var(--primary))', border: '2px solid hsl(var(--card))' }} />
        </div>

        <table style={{ tableLayout: 'fixed', borderCollapse: 'separate', borderSpacing: 0, width: 32 + nameCol.width + 180 + visibleDynCols.reduce((sum, c) => sum + dynCols.getColWidth(c.id), 0) + 60, minWidth: '100%' }}>
          <colgroup>
            <col style={{ width: 32 }} />
            <col style={{ width: nameCol.width }} />
            <col style={{ width: 180 }} />
            {visibleDynCols.map(c => { const w = dynCols.getColWidth(c.id); return <col key={c.id} data-col-id={c.id} style={{ width: w, minWidth: w, maxWidth: w }} />; })}
            <col />
          </colgroup>
          <thead>
            <tr style={{ height: 33 }}>
              <th className="bg-muted border-b border-border/50"
                style={{ position: 'sticky', top: 0, left: 0, zIndex: 40 }} />
              <th className="text-left px-2 text-xs font-semibold whitespace-nowrap bg-muted border-b border-border/50 border-r border-border/40 relative group/nth"
                style={{ position: 'sticky', top: 0, left: 35, zIndex: 40 }}>
                <div className="flex items-center">
                  <button onClick={() => toggleSort('taskName')} className="flex items-center gap-1 hover:bg-muted-foreground/10 transition-colors rounded px-1 -mx-1">
                    Tarea
                    {sortColumn === 'taskName' ? (sortDirection === 'asc' ? <ChevronUp className="w-3 h-3 text-primary" /> : <ChevronDown className="w-3 h-3 text-primary" />) : <ArrowUpDown className="w-3 h-3 text-muted-foreground/30 opacity-0 group-hover/nth:opacity-100" />}
                  </button>
                  {setColFilter && (
                    <ColumnFilterPopover allValues={colUniqueValues?.('taskName') ?? []} activeValues={columnFilters?.['taskName'] ?? new Set()} onApply={v => setColFilter('taskName', v)} />
                  )}
                </div>
                <div className="absolute top-0 right-0 bottom-0 w-2 cursor-col-resize hover:bg-primary/50 opacity-0 group-hover/nth:opacity-100 transition-opacity z-10"
                  onMouseDown={e => { e.preventDefault(); e.stopPropagation(); nameCol.startResize(e.clientX); }} />
              </th>
              <th className="text-left px-2 text-xs font-semibold whitespace-nowrap bg-muted border-b border-border/50 border-r border-border/40" style={{ position: 'sticky', top: 0, zIndex: 30, width: 180 }}>Timeline</th>
              <DynamicColumnHeaders
                dynCols={dynCols}
                sticky
                columnFilters={columnFilters}
                setColFilter={setColFilter}
                colUniqueValues={colUniqueValues}
                hiddenColumns={hiddenColumns}
                sortColumn={sortColumn}
                sortDirection={sortDirection}
                onToggleSort={toggleSort}
              />
            </tr>
          </thead>

          <tbody>
            {groupOrder.map((g, idx) => {
              const tasksInGroup = grouped[g.id] ?? [];
              const isExpanded   = expandedGroups.has(g.id);
              const isNone       = g.id === '__none__';
              return (
                <React.Fragment key={g.id}>
                  {idx > 0 && (
                    <tr aria-hidden="true">
                      <td colSpan={totalCols} style={{ height: 12, padding: 0, border: 'none', background: 'transparent' }} />
                    </tr>
                  )}
                  <GroupSectionHeader
                    groupId={g.id}
                    name={g.columnName ?? 'Sin grupo'}
                    colorId={g.columnType}
                    optionsJson={isNone ? undefined : groupDynCols.columns.find(c => c.id === g.id)?.optionsJson}
                    itemCount={tasksInGroup.length}
                    isExpanded={isExpanded}
                    isNone={isNone}
                    onToggle={() => toggleGroup(g.id)}
                    groupDynCols={groupDynCols}
                    colSpan={totalCols}
                    itemIds={tasksInGroup.map(t => t.id)}
                    selectedIds={selectedIds}
                    onToggleSelectAll={(ids, select) => setSelectedIds(prev => { const n = new Set(prev); ids.forEach(id => select ? n.add(id) : n.delete(id)); return n; })}
                    onDragStart={id => setDragGroupId(id)}
                    onDragOver={(e, id) => {
                      e.preventDefault();
                      if (e.dataTransfer.types.includes('rowid')) {
                        cancelRaf(); hideDropLine();
                        if (dropTargetRef.current) dropTargetRef.current = null;
                        if (dropRowGroupRef.current !== id) { dropRowGroupRef.current = id; setDropRowGroupId(id); }
                      } else {
                        setDropTargetId(id);
                      }
                    }}
                    onDragEnd={() => { setDragGroupId(null); setDropTargetId(null); }}
                    onDrop={handleGroupDrop}
                    isDragOver={(dropTargetId === g.id && dragGroupId !== g.id) || dropRowGroupId === g.id}
                    onDuplicateGroup={onDuplicateGroup && !isNone ? () => onDuplicateGroup(g.id) : undefined}
                    onGroupStructureChanged={!isNone ? onGroupStructureChanged : undefined}
                  />

                  {isExpanded && (
                    <>
                      {tasksInGroup.length === 0 && (
                        <tr>
                          <td colSpan={totalCols} className="px-10 py-3 text-xs text-muted-foreground/50 italic"
                            style={{ borderBottom: '1px solid hsl(var(--border) / 0.2)' }}>
                            {isNone ? 'Todas las tareas están en un grupo.' : 'Grupo vacío — agrega tareas aquí.'}
                          </td>
                        </tr>
                      )}
                      {(sortColumn ? tasksInGroup : [...tasksInGroup].sort((a, b) => (a.order ?? 0) - (b.order ?? 0))).map(t => renderRow(t))}

                      <tr>
                        <td colSpan={totalCols} className="px-10 py-2"
                          style={{ borderBottom: '1px dashed hsl(var(--border) / 0.3)' }}>
                          <div className="flex items-center gap-2 text-muted-foreground">
                            <Plus className="w-3 h-3 opacity-40 flex-shrink-0" />
                            <input
                              value={newTaskNames[g.id] ?? ''}
                              onChange={e => setNewTaskNames(p => ({ ...p, [g.id]: e.target.value }))}
                              onKeyDown={e => {
                                const v = newTaskNames[g.id] ?? '';
                                if (e.key === 'Enter' && v.trim()) { onQuickCreate(v.trim(), undefined, isNone ? undefined : g.id); setNewTaskNames(p => ({ ...p, [g.id]: '' })); }
                                if (e.key === 'Escape') setNewTaskNames(p => ({ ...p, [g.id]: '' }));
                              }}
                              placeholder="Nueva tarea...  (Enter para crear)"
                              className="flex-1 bg-transparent outline-none border-0 text-sm placeholder:text-muted-foreground/40 focus:text-foreground transition-colors"
                            />
                          </div>
                        </td>
                      </tr>
                    </>
                  )}
                </React.Fragment>
              );
            })}

            <tr>
              <td colSpan={totalCols} className="px-3 py-2" style={{ borderTop: '1px dashed hsl(var(--border) / 0.3)' }}>
                <button onClick={onCreateGroup} className="flex items-center gap-1.5 text-xs text-muted-foreground hover:text-primary hover:bg-primary/5 px-2 py-1.5 rounded-md transition-colors">
                  <FolderPlus className="w-3.5 h-3.5" /> Nueva fase
                </button>
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </>
  );
});

src/context/ProjectContext.tsx.content:
import React, { createContext, useContext, useState } from 'react';
import type { GetProjectsOutputType } from 'zite-endpoints-sdk';

type Project = GetProjectsOutputType['projects'][0];

interface ProjectContextType {
  selectedProject: string | null;
  setSelectedProject: (code: string | null) => void;
  projects: Project[];
  setProjects: (projects: Project[]) => void;
  projectsLoading: boolean;
  setProjectsLoading: (loading: boolean) => void;
}

const ProjectContext = createContext<ProjectContextType>({
  selectedProject: null,
  setSelectedProject: () => {},
  projects: [],
  setProjects: () => {},
  projectsLoading: true,
  setProjectsLoading: () => {},
});

export const ProjectProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [selectedProject, setSelectedProject] = useState<string | null>(null);
  const [projects, setProjects] = useState<Project[]>([]);
  const [projectsLoading, setProjectsLoading] = useState(true);

  return (
    <ProjectContext.Provider value={{ selectedProject, setSelectedProject, projects, setProjects, projectsLoading, setProjectsLoading }}>
      {children}
    </ProjectContext.Provider>
  );
};

export const useProject = () => useContext(ProjectContext);

src/hooks/useDynamicColumns.ts.content:
import { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { toast } from 'sonner';
import {
  getBoardColumns, getCellValues, saveBoardColumn,
  deleteBoardColumn, saveCellValue,
} from 'zite-endpoints-sdk';
import type { GetBoardColumnsOutputType, GetCellValuesOutputType } from 'zite-endpoints-sdk';

export type DynColumn = GetBoardColumnsOutputType['columns'][0];
export type DynCell   = GetCellValuesOutputType['cells'][0];
export type DynCellValue = Pick<DynCell, 'textValue' | 'numberValue' | 'dateValue' | 'booleanValue' | 'fileUrl'>;

/** Minimal row shape needed to seed the cell map */
export type SeedRow = { id: string; cellData?: string | null };

const KEY = (rowId: string, colId: string) => `${rowId}::${colId}`;

/**
 * Fallback default columns for boards that have no columns yet.
 * PM timeline defaults are now created server-side via ensureTimelineDefaultColumns
 * (called by saveProject and createBoardWithTemplate), so no pm- prefix is needed here.
 */
const BOARD_DEFAULTS: { prefix: string; cols: { name: string; type: string; options?: string; order?: number }[] }[] = [
  {
    prefix: 'cal-',
    cols: [
      { name: 'Responsable',            type: 'Persona',  order: 500   },
      { name: 'Fecha y hora',           type: 'Datetime', order: 1000  },
      { name: 'Duración (hrs)',         type: 'Número',   order: 2000  },
      { name: 'Dinámica',               type: 'Texto',    order: 3000  },
      { name: 'Perfil',                 type: 'Texto',    order: 4000  },
      { name: 'Descripción',            type: 'Texto',    order: 5000  },
      { name: 'Detalles adicionales',   type: 'Texto',    order: 6000  },
      { name: 'Detalles adicionales 2', type: 'Texto',    order: 7000  },
      { name: 'Status',                 type: 'Select',   order: 8000, options: JSON.stringify(['Por realizar', 'Realizada', 'Cancelada', 'Reprogramada', 'Caída', 'Reposición']) },
      { name: 'Ubicación Interna',      type: 'Select',   order: 9000, options: JSON.stringify(['Online', 'Sala 5-A', 'Sala 5-B', 'Sala 5-C', 'Sala 6-A', 'Sala 6-B', 'Sala 6-D', 'Sala 6-F', 'Sala 6-G', 'Sala 6-H', 'Otro']) },
      { name: 'Link',                   type: 'Texto',    order: 11000 },
      { name: 'Dirección',              type: 'Texto',    order: 12000 },
    ],
  },
  {
    prefix: 'events-',
    cols: [
      { name: 'Calendario',     type: 'Texto' },
      { name: 'Fecha y hora',   type: 'Datetime' },
      { name: 'Duración (hrs)', type: 'Número' },
      { name: 'Lugar',          type: 'Texto' },
      { name: 'Asistentes',     type: 'Texto' },
      { name: 'Invite enviado', type: 'Checkbox' },
    ],
  },
];

// ── Module-level caches (survive re-renders and tab switches) ─────────────────
const colCache        = new Map<string, DynColumn[]>();
const cellMapCache    = new Map<string, Map<string, DynCell>>();
// Boards whose cache was pre-seeded (rename or duplicate) — skip fetch on next effect run
const preloadedBoards = new Set<string>();

// ── Module-level pending saves tracking ───────────────────────────────────────
let _pendingSaveCount   = 0;
let _completedSaveCount = 0;
let _failedSaveCount    = 0;
let _totalSaveCount     = 0;
const _saveListeners: Array<() => void> = [];

function _notifySaveListeners() {
  for (const cb of _saveListeners) cb();
}

export function subscribeToPendingSaves(callback: () => void): () => void {
  _saveListeners.push(callback);
  return () => {
    const idx = _saveListeners.indexOf(callback);
    if (idx !== -1) _saveListeners.splice(idx, 1);
  };
}

export function getPendingSaveState() {
  return {
    pending:   _pendingSaveCount,
    completed: _completedSaveCount,
    failed:    _failedSaveCount,
    total:     _totalSaveCount,
  };
}

async function saveWithRetry(
  boardId: string,
  op: { rowId: string; colId: string; value: DynCellValue },
  maxRetries = 2,
): Promise<boolean> {
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      await saveCellValue({ boardId, rowId: op.rowId, columnId: op.colId, ...op.value });
      return true;
    } catch {
      if (attempt < maxRetries) {
        await new Promise(r => setTimeout(r, 2000 * (attempt + 1)));
      }
    }
  }
  return false;
}

/**
 * Persists a batch of cell value changes to the backend.
 * Lives at module scope so it survives component unmounts (e.g. navigating away).
 * Tracks progress and retries failed operations up to 2 times.
 */
async function persistBatchInBackground(
  boardId: string,
  ops: Array<{ rowId: string; colId: string; value: DynCellValue }>,
) {
  if (ops.length === 0) return;

  _pendingSaveCount   += ops.length;
  _totalSaveCount     += ops.length;
  _notifySaveListeners();

  // ── Group ops by rowId ────────────────────────────────────────────────────
  // saveCellValue does a read-modify-write on cellData. Running two ops for the
  // same row concurrently causes a race: both read stale cellData and the second
  // write overwrites the first. Serialising per-row eliminates this.
  const byRow = new Map<string, Array<{ rowId: string; colId: string; value: DynCellValue }>>();
  for (const op of ops) {
    if (!byRow.has(op.rowId)) byRow.set(op.rowId, []);
    byRow.get(op.rowId)!.push(op);
  }
  const rowGroups = [...byRow.values()];

  // Process up to 5 different rows concurrently, but each row's ops run sequentially
  const ROW_CONCURRENCY = 2;
  for (let i = 0; i < rowGroups.length; i += ROW_CONCURRENCY) {
    const concurrentRows = rowGroups.slice(i, i + ROW_CONCURRENCY);

    await Promise.all(concurrentRows.map(async (rowOps) => {
      for (const op of rowOps) {
        const success = await saveWithRetry(boardId, op);
        _pendingSaveCount--;
        if (success) _completedSaveCount++;
        else          _failedSaveCount++;
        _notifySaveListeners();
      }
    }));

    // Small delay between row-batches to avoid rate limits
    if (i + ROW_CONCURRENCY < rowGroups.length) {
      await new Promise(r => setTimeout(r, 200));
    }
  }

  // Reset counters once all pending saves are done
  if (_pendingSaveCount === 0) {
    setTimeout(() => {
      _completedSaveCount = 0;
      _failedSaveCount    = 0;
      _totalSaveCount     = 0;
      _notifySaveListeners();
    }, 3000); // Keep visible briefly so user sees "all done"
  }
}

/**
 * Pre-seeds the column cache for a newly duplicated board so that
 * useDynamicColumns finds data immediately without an extra fetch.
 * Call this BEFORE changing the active board.
 */
export function preSeedBoardCache(boardId: string, columns: DynColumn[], cells?: DynCell[]) {
  colCache.set(boardId, columns);
  if (cells && cells.length > 0) {
    const m = new Map<string, DynCell>();
    for (const cell of cells) {
      if (cell.rowId && cell.columnId) m.set(KEY(cell.rowId, cell.columnId), cell);
    }
    cellMapCache.set(boardId, m);
  }
  preloadedBoards.add(boardId);
}

/**
 * Migrates column and cell caches from oldBoardId to newBoardId.
 * Also handles the `::groups` variant automatically.
 * Call this BEFORE changing activeBoard so hooks find data in cache immediately.
 */
export function renameBoardCache(oldBoardId: string, newBoardId: string) {
  const suffixes = ['', '::groups'];
  for (const suffix of suffixes) {
    const oldKey = `${oldBoardId}${suffix}`;
    const newKey = `${newBoardId}${suffix}`;
    if (colCache.has(oldKey)) {
      colCache.set(newKey, colCache.get(oldKey)!);
      colCache.delete(oldKey);
    }
    if (cellMapCache.has(oldKey)) {
      cellMapCache.set(newKey, cellMapCache.get(oldKey)!);
      cellMapCache.delete(oldKey);
    }
    // Mark new key as preloaded so the hook skips the premature fetch
    preloadedBoards.add(newKey);
  }
  console.log('[useDynamicColumns] renamed cache', { oldBoardId, newBoardId });
}

// In-flight dedup for column fetches
const inFlightCols = new Map<string, Promise<{ columns: DynColumn[] }>>();

function fetchCols(boardId: string) {
  if (!inFlightCols.has(boardId)) {
    const p = getBoardColumns({ boardId }).finally(() => inFlightCols.delete(boardId));
    inFlightCols.set(boardId, p);
  }
  return inFlightCols.get(boardId)!;
}

// ── Generic concurrency limiter (max N concurrent DB fetches) ─────────────────
function makeConcurrencyLimiter(maxConcurrent: number) {
  let active = 0;
  const queue: Array<() => void> = [];
  return function withLimit<T>(fn: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      const run = () => {
        active++;
        fn().then(resolve, reject).finally(() => {
          active--;
          if (queue.length > 0) queue.shift()!();
        });
      };
      if (active < maxConcurrent) run();
      else queue.push(run);
    });
  };
}

// Serialize all cell fetches (1 at a time) to avoid rate limits
const withCellFetchLimit = makeConcurrencyLimiter(4);
// Serialize all board column saves (1 at a time) to avoid rate limits
const withColSaveLimit = makeConcurrencyLimiter(1);

/** Returns true if column data for this boardId is already in the module-level cache.
 *  Use this to decide whether staggered loading can be skipped (cache hit = no network call needed). */
export function isBoardCached(boardId: string): boolean {
  return colCache.has(boardId);
}

/** Build cell map from raw CellValues records (legacy / fallback path) */
const buildMap = (cells: DynCell[]): Map<string, DynCell> => {
  const m = new Map<string, DynCell>();
  cells.forEach(c => { if (c.rowId && c.columnId) m.set(KEY(c.rowId, c.columnId), c); });
  return m;
};

/**
 * Build cell map from rows' denormalized cellData JSON.
 * cellData format: { [columnId]: { textValue?, numberValue?, dateValue?, booleanValue?, fileUrl? } }
 * This is instant — no network call needed.
 */
const buildMapFromRows = (rows: SeedRow[]): Map<string, DynCell> => {
  const m = new Map<string, DynCell>();
  for (const row of rows) {
    if (!row.cellData) continue;
    try {
      const parsed = JSON.parse(row.cellData) as Record<string, Partial<DynCellValue>>;
      for (const [colId, val] of Object.entries(parsed)) {
        if (!val || typeof val !== 'object') continue;
        m.set(KEY(row.id, colId), {
          id: `${row.id}::${colId}`,
          rowId: row.id,
          columnId: colId,
          textValue: val.textValue,
          numberValue: val.numberValue,
          dateValue: val.dateValue,
          booleanValue: val.booleanValue,
          fileUrl: val.fileUrl,
        });
      }
    } catch { /* invalid JSON — skip */ }
  }
  return m;
};

/**
 * Hook for managing dynamic board columns and cell values.
 *
 * @param boardId  - Unique board identifier
 * @param seedRows - Optional rows with denormalized cellData. When provided,
 *                   cell values are read from these rows instead of fetching
 *                   from the CellValues API (dramatically faster).
 */
export function useDynamicColumns(boardId: string, seedRows?: SeedRow[], options?: { onCellSaved?: (rowId: string, result: { inviteStatusChanged?: boolean; columnId?: string; value?: DynCellValue }) => void; enabled?: boolean }) {
  // Default true — when enabled is explicitly false, skip all fetching and return empty state
  const isEnabled = options?.enabled !== false;

  // ── Lazy initial state from cache — avoids an empty render on first mount ─
  const [prevBoardId,  setPrevBoardId]  = useState(boardId);
  const [columns,      setColumns]      = useState<DynColumn[]>(() => boardId ? (colCache.get(boardId) ?? []) : []);
  const [cellMap,      setCellMap]      = useState<Map<string, DynCell>>(() => boardId ? (cellMapCache.get(boardId) ?? new Map()) : new Map());
  const [cellsLoading, setCellsLoading] = useState(() => isEnabled && !!boardId && !cellMapCache.has(boardId) && !(seedRows && seedRows.length > 0));
  const [refreshKey,   setRefreshKey]   = useState(0);

  // ── Initial load tracking — gate UI until first fetch completes ────────────
  // Tracks which boardId has completed its first load. Once set, subsequent
  // reloads (softReload, refreshColumns) do NOT reset it — the flag is
  // one-way per boardId and only resets when boardId changes (unless cache hit).
  const [initialLoadedBoard, setInitialLoadedBoard] = useState<string>(() => {
    if (!isEnabled || !boardId) return '';
    // Cache hit at mount: columns are already available
    if (colCache.has(boardId) || preloadedBoards.has(boardId)) return boardId;
    return '';
  });

  // ── Derived state: synchronously apply cache on boardId change ─────────────
  // When boardId changes React re-renders immediately with these new values,
  // so there is never a "frame" where rows exist but columns/cellMap are empty.
  if (prevBoardId !== boardId) {
    setPrevBoardId(boardId);
    setColumns(boardId ? (colCache.get(boardId) ?? []) : []);
    setCellMap(boardId ? (cellMapCache.get(boardId) ?? new Map()) : new Map());
    setCellsLoading(isEnabled && !!boardId && !cellMapCache.has(boardId) && !(seedRows && seedRows.length > 0));
    // Reset initial load tracking — cache hit = instantly loaded
    if (isEnabled && boardId && (colCache.has(boardId) || preloadedBoards.has(boardId))) {
      setInitialLoadedBoard(boardId);
    } else {
      setInitialLoadedBoard('');
    }
  }

  const loadedRef = useRef<string>('');
  const softReloadResolveRef = useRef<(() => void) | null>(null);

  // ── Column widths — sync with localStorage when boardId changes ───────────
  const [colWidths, setColWidths] = useState<Record<string, number>>(() => {
    try { return JSON.parse(localStorage.getItem(`col-widths-${boardId}`) ?? '{}'); } catch { return {}; }
  });

  useEffect(() => {
    if (!boardId) { setColWidths({}); return; }
    try { setColWidths(JSON.parse(localStorage.getItem(`col-widths-${boardId}`) ?? '{}')); }
    catch { setColWidths({}); }
  }, [boardId]);

  // ── Seed version: stable key that only changes when actual cellData changes ─
  // Using sum of cellData string lengths — changes only when cells are added/modified.
  // This prevents spurious effect re-runs when rows change for other reasons (name, status, etc.)
  const seedVersion = useMemo(() => {
    if (!seedRows) return -1;
    let v = 0;
    for (const r of seedRows) { if (r.cellData) v += r.cellData.length; }
    return v;
  }, [seedRows]);

  // ── Main effect: load columns + build cell map ─────────────────────────────
  useEffect(() => {
    // Only count a row as having seed data if its cellData is valid JSON that parses
    // to a non-null object with at least one key. Plain `{}` or null must NOT trigger
    // the fast path — it would produce an empty map and block the CellValues API call.
    const isValidCellDataJson = (raw: string | null | undefined): boolean => {
      if (!raw) return false;
      try {
        const parsed = JSON.parse(raw);
        return parsed !== null && typeof parsed === 'object' && !Array.isArray(parsed) && Object.keys(parsed).length > 0;
      } catch {
        return false;
      }
    };

    const hasSeedData = !!seedRows && seedRows.length > 0 && seedRows.some(r => isValidCellDataJson(r.cellData));

    // When there is no valid seed data, exclude seedVersion from the runKey so that
    // background row refreshes (which change seedVersion) don't cancel the in-flight
    // getCellValues fetch and leave cellsLoading stuck at true forever.
    const runKey = `${boardId}::${refreshKey}::${hasSeedData ? seedVersion : 'api'}`;

    // Skip all fetching when disabled — leave existing cached state untouched
    if (!isEnabled) return;

    if (!boardId) {
      setColumns([]);
      setCellMap(new Map());
      return;
    }
    // Already up to date — skip
    if (loadedRef.current === runKey) return;

    // ── Preloaded-cache fast-exit (rename / duplicate) ───────────────────────
    // If renameBoardCache or preSeedBoardCache already populated the caches for
    // this boardId, apply them immediately and skip the backend fetch entirely.
    // This avoids the race condition where the fetch arrives before the backend
    // has finished migrating records to the new boardId.
    if (preloadedBoards.has(boardId) && colCache.has(boardId)) {
      console.log('[useDynamicColumns] using preloaded cache', { boardId, runKey });
      setColumns(colCache.get(boardId)!);
      const cachedMap = cellMapCache.get(boardId);
      if (cachedMap) setCellMap(cachedMap);
      setCellsLoading(false);
      loadedRef.current = runKey;
      setInitialLoadedBoard(boardId);
      if (softReloadResolveRef.current) { softReloadResolveRef.current(); softReloadResolveRef.current = null; }
      preloadedBoards.delete(boardId);
      return;
    }

    // Apply cached columns immediately (instant on board switch)
    const cachedCols = colCache.get(boardId);
    if (cachedCols) setColumns(cachedCols);

    // ── FAST PATH: build cell map from seedRows synchronously ───────────────
    if (hasSeedData && seedRows) {
      const builtMap = buildMapFromRows(seedRows);
      cellMapCache.set(boardId, builtMap);
      setCellMap(builtMap);
      setCellsLoading(false);
      // Still need to fetch columns if not cached — done in run() below
    } else {
      // Apply cached cell map while we fetch fresh data
      const cachedMap = cellMapCache.get(boardId);
      if (cachedMap) {
        setCellMap(cachedMap);
      } else if (!seedRows || seedRows.length === 0) {
        // Only show loading skeletons when there are NO seedRows at all.
        // When seedRows exist but have empty cellData, skip skeletons —
        // cells will be empty briefly while the API fetches in background,
        // matching the previous behavior before the isValidCellDataJson fix.
        setCellsLoading(true);
      }
    }

    let cancelled = false;

    const run = async () => {
      try {
        // ── Step 1: Fetch columns ────────────────────────────────────────────
        let cols = cachedCols;
        if (!cols) {
          const colsData = await fetchCols(boardId);
          if (cancelled) return;
          cols = colsData.columns;
        }

        // ── Step 2: Seed default columns if this is a known prefix board ─────
        if (cols.length === 0 && !boardId.includes('::')) {
          const matched = BOARD_DEFAULTS.find(b => boardId.startsWith(b.prefix));
          if (matched) {
            for (let i = 0; i < matched.cols.length; i++) {
              const d = matched.cols[i];
              await withColSaveLimit(() => saveBoardColumn({ columnName: d.name, boardId, columnType: d.type, optionsJson: d.options, columnOrder: d.order ?? i }));
            }
            const fresh = await getBoardColumns({ boardId });
            if (cancelled) return;
            cols = fresh.columns;
          }
        }

        if (cancelled) return;
        colCache.set(boardId, cols);
        setColumns(cols);

        // ── Step 3: Cells ────────────────────────────────────────────────────
        if (hasSeedData) {
          // Already built synchronously above — just mark loaded
          loadedRef.current = runKey;
          setInitialLoadedBoard(boardId);
          if (softReloadResolveRef.current) { softReloadResolveRef.current(); softReloadResolveRef.current = null; }
        } else {
          // ── SLOW PATH: paginated CellValues API (fallback when no cellData) ─
          // Retry helper: up to 2 retries with exponential backoff on rate-limit errors.
          // Each failed attempt waits 2s then 4s before giving up.
          const fetchCellPage = async (pageOffset: number) => {
            for (let attempt = 0; attempt < 3; attempt++) {
              try {
                return await withCellFetchLimit(() => getCellValues({ boardId, limit: 500, offset: pageOffset }));
              } catch (err) {
                if (cancelled) return null;
                const msg = (err as Error)?.message ?? '';
                const isRateLimit = msg.includes('Too many requests') || msg.includes('429');
                if (attempt < 2 && isRateLimit) {
                  await new Promise(r => setTimeout(r, 2000 * (attempt + 1)));
                  if (cancelled) return null;
                } else {
                  throw err;
                }
              }
            }
            return null;
          };

          let allCells: DynCell[] = [];
          const firstPage = await fetchCellPage(0);
          if (!firstPage || cancelled) return;
          allCells = [...firstPage.cells];
          const firstMap = buildMap(allCells);
          cellMapCache.set(boardId, firstMap);
          setCellMap(firstMap);

          if (firstPage.hasMore) {
            let offset  = firstPage.nextOffset;
            let hasMore: boolean = firstPage.hasMore;
            while (hasMore && !cancelled) {
              const page = await fetchCellPage(offset);
              if (!page || cancelled) return;
              allCells = [...allCells, ...page.cells];
              const partialMap = buildMap(allCells);
              cellMapCache.set(boardId, partialMap);
              setCellMap(partialMap);
              offset  = page.nextOffset;
              hasMore = page.hasMore;
            }
          }

          if (!cancelled) {
            setCellsLoading(false);
            loadedRef.current = runKey;
            setInitialLoadedBoard(boardId);
            if (softReloadResolveRef.current) { softReloadResolveRef.current(); softReloadResolveRef.current = null; }
          }
        }
      } catch (e) {
        console.error('useDynamicColumns error:', e);
        if (!cancelled) setCellsLoading(false);
      }
    };

    run();
    return () => { cancelled = true; };
  // seedVersion in deps: only re-runs when actual cellData changes, not on every row update
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [boardId, refreshKey, seedVersion, isEnabled]);

  // ── Cell accessors ─────────────────────────────────────────────────────────
  // useCallback with [cellMap] dep so parent memos can track cell changes
  const getCellVal = useCallback(
    (rowId: string, colId: string): DynCell | undefined => cellMap.get(KEY(rowId, colId)),
    [cellMap]
  );

  const setLocalCellVal = (rowId: string, colId: string, value: DynCellValue) => {
    const k = KEY(rowId, colId);
    const existing = cellMap.get(k);
    const entry: DynCell = { id: existing?.id ?? '__local__', boardId, rowId, columnId: colId, ...value };
    setCellMap(prev => {
      const next = new Map(prev).set(k, entry);
      cellMapCache.set(boardId, next);
      return next;
    });
  };

  const setCellVal = async (rowId: string, colId: string, value: DynCellValue) => {
    const k = KEY(rowId, colId);
    const existing = cellMap.get(k);
    const optimistic: DynCell = { id: existing?.id ?? '__opt__', boardId, rowId, columnId: colId, ...value };
    setCellMap(prev => new Map(prev).set(k, optimistic));
    try {
      const result = await saveCellValue({ boardId, rowId, columnId: colId, ...value });
      const saved = { ...optimistic, id: result.id };
      setCellMap(prev => {
        const next = new Map(prev).set(k, saved);
        cellMapCache.set(boardId, next);
        return next;
      });
      options?.onCellSaved?.(rowId, { inviteStatusChanged: result.inviteStatusChanged, columnId: colId, value });
    } catch {
      setCellMap(prev => {
        const next = new Map(prev);
        if (existing) next.set(k, existing); else next.delete(k);
        return next;
      });
    }
  };

  /**
   * Batch-update many cells at once.
   * - Applies ALL optimistic updates in a single setState (one re-render).
   * - Persists to backend in background batches of 50, fire-and-forget.
   * Pass `value: {}` (empty object / undefined fields) to clear a cell.
   */
  const batchSetCellVals = (ops: Array<{ rowId: string; colId: string; value: DynCellValue }>) => {
    if (ops.length === 0) return;

    // 1. Single optimistic update for all ops
    setCellMap(prev => {
      const next = new Map(prev);
      for (const op of ops) {
        const k = KEY(op.rowId, op.colId);
        const existing = prev.get(k);
        const hasAnyValue = op.value.textValue !== undefined || op.value.numberValue !== undefined ||
          op.value.dateValue !== undefined || op.value.booleanValue !== undefined || op.value.fileUrl !== undefined;
        if (hasAnyValue) {
          next.set(k, { id: existing?.id ?? '__opt__', boardId, rowId: op.rowId, columnId: op.colId, ...op.value });
        } else {
          next.delete(k);
        }
      }
      cellMapCache.set(boardId, next);
      return next;
    });

    // 2. Persist to backend via module-level function (survives component unmount)
    persistBatchInBackground(boardId, ops);
  };

  // ── Column mutations ───────────────────────────────────────────────────────
  // Optimistic: shows new column instantly, persists in background.
  const addColumn = (columnName: string, columnType: string, optionsJson?: string, atIndex?: number): Promise<string> => {
    const snapshot = [...columns];
    const sorted = [...columns].sort((a, b) => (a.columnOrder ?? 0) - (b.columnOrder ?? 0));
    const insertAt = atIndex !== undefined ? atIndex : sorted.length;
    const toShift = sorted.filter(c => (c.columnOrder ?? 0) >= insertAt);

    // 1. Build optimistic column list and update state immediately
    const tempId = `temp-col-${Date.now()}`;
    const tempCol: DynColumn = {
      id: tempId,
      boardId,
      columnName,
      columnType,
      optionsJson,
      columnOrder: insertAt,
    };
    const shifted = sorted.map(c =>
      (c.columnOrder ?? 0) >= insertAt ? { ...c, columnOrder: (c.columnOrder ?? 0) + 1 } : c
    );
    const optimistic = [...shifted, tempCol].sort((a, b) => (a.columnOrder ?? 0) - (b.columnOrder ?? 0));
    setColumns(optimistic);
    colCache.set(boardId, optimistic);

    // 2. Persist in background — returns a promise that resolves with the real column ID
    const savePromise = (async (): Promise<string> => {
      try {
        for (const c of toShift) {
          await withColSaveLimit(() =>
            saveBoardColumn({ id: c.id, columnName: c.columnName ?? '', boardId, columnType: c.columnType ?? '', optionsJson: c.optionsJson, columnOrder: (c.columnOrder ?? 0) + 1 })
          );
        }
        const result = await withColSaveLimit(() =>
          saveBoardColumn({ columnName, boardId, columnType, optionsJson, columnOrder: insertAt })
        );
        const realId = result.id;

        // Swap temp ID → real ID in columns state (preserves list structure, no full re-fetch)
        setColumns(prev => {
          const updated = prev.map(c => c.id === tempId ? { ...c, id: realId } : c);
          colCache.set(boardId, updated);
          return updated;
        });

        // Remap any cells assigned to temp column ID → real column ID
        setCellMap(prev => {
          let changed = false;
          const next = new Map<string, DynCell>();
          for (const [key, cell] of prev) {
            if (cell.columnId === tempId) {
              changed = true;
              const newKey = KEY(cell.rowId!, realId);
              next.set(newKey, { ...cell, columnId: realId });
            } else {
              next.set(key, cell);
            }
          }
          if (changed) cellMapCache.set(boardId, next);
          return changed ? next : prev;
        });

        return realId;
      } catch (err) {
        // Rollback to pre-add state
        setColumns(snapshot);
        colCache.set(boardId, snapshot);
        toast.error('Error al crear columna');
        throw err;
      }
    })();

    return savePromise;
  };

  // Optimistic: removes column instantly, restores on error.
  const removeColumn = async (colId: string) => {
    const snapshot = [...columns];
    const updated = columns.filter(c => c.id !== colId);
    setColumns(updated);
    colCache.set(boardId, updated);
    try {
      await deleteBoardColumn({ id: colId });
    } catch {
      setColumns(snapshot);
      colCache.set(boardId, snapshot);
      toast.error('Error al eliminar columna');
    }
  };

  const renameColumn = async (colId: string, newName: string) => {
    const col = columns.find(c => c.id === colId);
    if (!col) return;
    const updated = columns.map(c => c.id === colId ? { ...c, columnName: newName } : c);
    setColumns(updated);
    colCache.set(boardId, updated);
    await withColSaveLimit(() => saveBoardColumn({ id: colId, columnName: newName, boardId, columnType: col.columnType, optionsJson: col.optionsJson, columnOrder: col.columnOrder }));
  };

  const updateColumn = async (colId: string, updates: { columnName?: string; columnType?: string; optionsJson?: string }) => {
    const col = columns.find(c => c.id === colId);
    if (!col) return;
    const merged = { ...col, ...updates };
    const updated = columns.map(c => c.id === colId ? merged : c);
    setColumns(updated);
    colCache.set(boardId, updated);
    await withColSaveLimit(() => saveBoardColumn({
      id: colId,
      columnName: merged.columnName ?? col.columnName ?? '',
      boardId,
      columnType: merged.columnType ?? col.columnType ?? '',
      optionsJson: merged.optionsJson ?? col.optionsJson,
      columnOrder: merged.columnOrder ?? col.columnOrder ?? 0,
    }));
  };

  const reorderColumns = async (dragId: string, dropId: string, side: 'left' | 'right') => {
    const sorted = [...columns].sort((a, b) => (a.columnOrder ?? 0) - (b.columnOrder ?? 0));
    const dragIdx = sorted.findIndex(c => c.id === dragId);
    if (dragIdx === -1 || dragId === dropId) return;
    const [dragged] = sorted.splice(dragIdx, 1);
    let dropIdx = sorted.findIndex(c => c.id === dropId);
    if (side === 'right') dropIdx += 1;
    sorted.splice(dropIdx, 0, dragged);
    const reordered = sorted.map((c, i) => ({ ...c, columnOrder: i }));
    setColumns(reordered);
    colCache.set(boardId, reordered);
    // Only persist columns whose order actually changed
    const oldOrderMap = new Map(columns.map(c => [c.id, c.columnOrder ?? 0]));
    const changed = reordered.filter(c => (c.columnOrder ?? 0) !== (oldOrderMap.get(c.id) ?? -1));
    try {
      for (const c of changed) {
        await withColSaveLimit(() => saveBoardColumn({ id: c.id, columnName: c.columnName ?? '', boardId, columnType: c.columnType ?? '', optionsJson: c.optionsJson, columnOrder: c.columnOrder ?? 0 }));
      }
    } catch {
      toast.error('Error al guardar el orden de columnas');
    }
  };

  // ── Column resize ──────────────────────────────────────────────────────────

  // Compute smart default widths once when columns or cell data changes
  const smartDefaults = useMemo(() => {
    const TYPE_MIN_WIDTHS: Record<string, number> = {
      'Checkbox': 70, 'Rating': 100, 'Color': 110, 'Status': 140, 'Select': 140,
      'Fecha': 130, 'Datetime': 160, 'Número': 100, 'Persona': 150, 'Botón': 130,
      'Fórmula': 120, 'Texto': 160, 'Email': 180, 'Teléfono': 140, 'Archivo': 160,
    };

    // Single pass through cellMap to collect content samples per column (max 20 per col)
    const samples: Record<string, string[]> = {};
    for (const [key, cell] of cellMap) {
      const colId = key.split('::')[1];
      if (!colId) continue;
      if (!samples[colId]) samples[colId] = [];
      if (samples[colId].length >= 20) continue;
      let text = '';
      if (cell.textValue) text = cell.textValue;
      else if (cell.numberValue != null) text = String(cell.numberValue);
      else if (cell.dateValue) text = cell.dateValue.split('T')[0];
      if (!text) continue;
      samples[colId].push(text);
    }

    const defaults: Record<string, number> = {};
    for (const col of columns) {
      const headerWidth = (col.columnName ?? '').length * 8 + 60;
      const typeMinWidth = TYPE_MIN_WIDTHS[col.columnType ?? ''] ?? 160;

      let maxSampleWidth = 0;
      const colSamples = samples[col.id];
      if (colSamples) {
        for (const text of colSamples) {
          const truncLen = Math.min(text.length, 40);
          const sw = truncLen * 7 + 40;
          if (sw > maxSampleWidth) maxSampleWidth = sw;
        }
      }

      const calculated = Math.max(headerWidth, typeMinWidth, maxSampleWidth);
      defaults[col.id] = Math.min(Math.max(calculated, 70), 340);
    }
    return defaults;
  }, [columns, cellMap]);

  const getColWidth = (colId: string) => colWidths[colId] ?? smartDefaults[colId] ?? 140;

  const startResize = (colId: string, startX: number) => {
    const startWidth = colWidths[colId] ?? 140;
    const key = `col-widths-${boardId}`;
    let currentW = startWidth;
    document.body.style.cursor = 'col-resize';
    document.body.style.userSelect = 'none';
    const onMove = (e: MouseEvent) => {
      currentW = Math.min(800, Math.max(40, startWidth + e.clientX - startX));
      // Mutate DOM directly — no setState, no re-render
      const colEl = document.querySelector(`col[data-col-id="${colId}"]`) as HTMLElement | null;
      if (colEl) {
        colEl.style.width = `${currentW}px`;
        colEl.style.minWidth = `${currentW}px`;
        colEl.style.maxWidth = `${currentW}px`;
      }
    };
    const onUp = () => {
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
      // Single setState + localStorage write only on release
      setColWidths(prev => {
        const next = { ...prev, [colId]: currentW };
        localStorage.setItem(key, JSON.stringify(next));
        return next;
      });
      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('mouseup', onUp);
    };
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
  };

  // ── Derived values ─────────────────────────────────────────────────────────
  const visibleColumns = columns.filter(c => c.columnType !== '__fillout_link__');
  const linkCol = columns.find(c => c.columnType === '__fillout_link__');
  const linkedFormInfo: { formId: string; formName: string; linkedAt: string } | null = linkCol?.optionsJson
    ? (() => { try { return JSON.parse(linkCol.optionsJson); } catch { return null; } })()
    : null;

  const reload = () => {
    colCache.delete(boardId);
    cellMapCache.delete(boardId);
    loadedRef.current = '';
    setRefreshKey(k => k + 1);
  };

  const softReload = (): Promise<void> => {
    return new Promise<void>((resolve) => {
      softReloadResolveRef.current = resolve;
      loadedRef.current = '';
      setRefreshKey(k => k + 1);
    });
  };

  /** Fetch fresh columns from the server without touching cell cache or showing skeletons.
   *  Ideal for group structure changes where columns change but cells don't. */
  const refreshColumns = async () => {
    if (!boardId) return;
    try {
      const colsData = await fetchCols(boardId);
      colCache.set(boardId, colsData.columns);
      setColumns(colsData.columns);
    } catch (e) {
      console.error('[useDynamicColumns] refreshColumns error:', e);
    }
  };

  return {
    columns: visibleColumns,
    linkedFormInfo,
    reload,
    softReload,
    refreshColumns,
    getCellVal,
    setCellVal,
    batchSetCellVals,
    addColumn,
    removeColumn,
    renameColumn,
    updateColumn,
    reorderColumns,
    loading: false,       // columns apply instantly from cache
    cellsLoading,
    hasInitiallyLoaded: initialLoadedBoard === boardId,
    getColWidth,
    startResize,
    setLocalCellVal,
  };
}

