import { useState, useEffect, useMemo } from 'react';
import { useAuth } from 'zite-auth-sdk';
import { getProjects, getMultiProjectCostAnalysis } from 'zite-endpoints-sdk';
import type { GetMultiProjectCostAnalysisOutputType, GetProjectsOutputType } from 'zite-endpoints-sdk';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Skeleton } from '@/components/ui/skeleton';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Checkbox } from '@/components/ui/checkbox';
import { BarChart2, ChevronDown, RefreshCw, Search, X } from 'lucide-react';
import { toast } from 'sonner';
import { cn } from '@/lib/utils';
import CostSummaryCards from '@/components/finance/CostSummaryCards';
import ProjectCostRow from '@/components/finance/ProjectCostRow';
import ProjectSelectorDialog from '@/components/finance/ProjectSelectorDialog';

type Project = GetProjectsOutputType['projects'][0];
type Analysis = GetMultiProjectCostAnalysisOutputType;

const fmt = (v: number) =>
  new Intl.NumberFormat('es-MX', { style: 'currency', currency: 'MXN', maximumFractionDigits: 0 }).format(v);

function FilterPill({ label, active, onClick }: { label: string; active: boolean; onClick: () => void }) {
  return (
    <button
      onClick={onClick}
      className={cn(
        'inline-flex items-center gap-1 px-3 py-1 rounded-full border text-xs font-medium transition-colors whitespace-nowrap',
        active
          ? 'bg-primary/10 text-primary border-primary/30'
          : 'bg-background text-muted-foreground border-border hover:border-foreground/30 hover:text-foreground'
      )}
    >
      {label}
    </button>
  );
}

export default function ProjectCostsPage() {
  const { user, isLoading: authLoading, loginWithRedirect } = useAuth();
  const [allProjects, setAllProjects] = useState<Project[]>([]);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [analysis, setAnalysis] = useState<Analysis | null>(null);
  const [loadingProjects, setLoadingProjects] = useState(true);
  const [loadingAnalysis, setLoadingAnalysis] = useState(false);
  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());
  const [search, setSearch] = useState('');
  const [selectedStatuses, setSelectedStatuses] = useState<Set<string>>(new Set());
  const [selectedClients, setSelectedClients] = useState<Set<string>>(new Set());
  const [selectedYears, setSelectedYears] = useState<Set<string>>(new Set());
  const [clientSearch, setClientSearch] = useState('');
  const [clientPopoverOpen, setClientPopoverOpen] = useState(false);

  useEffect(() => {
    if (!authLoading && !user) loginWithRedirect({ redirectUrl: window.location.href });
  }, [authLoading, user, loginWithRedirect]);

  useEffect(() => {
    getProjects({ search: '' }).then(r => {
      setAllProjects(r.projects);
      const ids = r.projects.map(p => p.id);
      setSelectedIds(new Set(ids));
      setLoadingProjects(false);
      if (ids.length > 0) runAnalysis(ids);
    });
  }, []);

  const runAnalysis = async (ids: string[], silent = false) => {
    if (ids.length === 0) { toast.warning('Selecciona al menos un proyecto'); return; }
    if (!silent) setLoadingAnalysis(true);
    try {
      const data = await getMultiProjectCostAnalysis({ projectIds: ids });
      setAnalysis(data);
    } catch { toast.error('Error al cargar el análisis'); }
    finally { setLoadingAnalysis(false); }
  };

  const handleDialogConfirm = (ids: Set<string>) => {
    setSelectedIds(ids);
    if (ids.size === 0) {
      setAnalysis(null);
    } else {
      runAnalysis(Array.from(ids));
    }
  };

  const toggleExpand = (id: string) =>
    setExpandedIds(prev => { const n = new Set(prev); n.has(id) ? n.delete(id) : n.add(id); return n; });

  // Build projectId → { client, year } map from allProjects
  const projectMeta = useMemo(() => {
    const map = new Map<string, { client: string; year: string }>();
    allProjects.forEach(p => {
      const year = p.startDate ? new Date(p.startDate).getFullYear().toString() : '';
      map.set(p.id, { client: p.client ?? '', year });
    });
    return map;
  }, [allProjects]);

  // Unique filter options
  const uniqueStatuses = useMemo(() => {
    if (!analysis) return [];
    const s = new Set<string>();
    analysis.projects.forEach(pa => { if (pa.project.status) s.add(pa.project.status); });
    return Array.from(s).sort();
  }, [analysis]);

  const uniqueClients = useMemo(() => {
    const s = new Set<string>();
    allProjects.forEach(p => { if (p.client) s.add(p.client); });
    return Array.from(s).sort();
  }, [allProjects]);

  const uniqueYears = useMemo(() => {
    const s = new Set<string>();
    allProjects.forEach(p => {
      if (p.startDate) {
        const y = new Date(p.startDate).getFullYear().toString();
        s.add(y);
      }
    });
    return Array.from(s).sort((a, b) => b.localeCompare(a));
  }, [allProjects]);

  const toggleStatus = (s: string) =>
    setSelectedStatuses(prev => { const n = new Set(prev); n.has(s) ? n.delete(s) : n.add(s); return n; });

  const toggleClient = (c: string) =>
    setSelectedClients(prev => { const n = new Set(prev); n.has(c) ? n.delete(c) : n.add(c); return n; });

  const toggleYear = (y: string) =>
    setSelectedYears(prev => { const n = new Set(prev); n.has(y) ? n.delete(y) : n.add(y); return n; });

  const clearAllFilters = () => {
    setSearch('');
    setSelectedStatuses(new Set());
    setSelectedClients(new Set());
    setSelectedYears(new Set());
  };

  const hasActiveFilters = search || selectedStatuses.size > 0 || selectedClients.size > 0 || selectedYears.size > 0;

  const filteredClients = useMemo(() =>
    uniqueClients.filter(c => c.toLowerCase().includes(clientSearch.toLowerCase())),
    [uniqueClients, clientSearch]
  );

  if (authLoading || !user) return null;

  return (
    <div className="p-6 space-y-5">
      {/* Header */}
      <div className="flex items-start justify-between gap-4 flex-wrap">
        <div>
          <h1 className="text-2xl font-bold text-foreground">Costos por Proyecto</h1>
          <p className="text-muted-foreground text-sm mt-1">Análisis P&L: cotizado vs. vendido vs. gastado por rubro</p>
        </div>
        <div className="flex items-center gap-2 shrink-0 mt-1">
          <ProjectSelectorDialog
            projects={allProjects}
            selectedIds={selectedIds}
            loadingProjects={loadingProjects}
            onConfirm={handleDialogConfirm}
          />
          {analysis && (
            <Button
              variant="outline"
              size="sm"
              onClick={() => runAnalysis(Array.from(selectedIds))}
              disabled={loadingAnalysis || selectedIds.size === 0}
              className="gap-2"
            >
              <RefreshCw className={cn('w-4 h-4', loadingAnalysis && 'animate-spin')} />
              Actualizar
            </Button>
          )}
        </div>
      </div>

      {/* Empty state */}
      {!analysis && !loadingAnalysis && (
        <div className="flex flex-col items-center justify-center py-24 text-muted-foreground">
          <BarChart2 className="w-14 h-14 mb-4 opacity-20" />
          <p className="text-base font-medium">Aún no has analizado ningún proyecto</p>
          <p className="text-sm mt-1 opacity-70">Haz clic en &quot;Seleccionar proyectos&quot; para empezar</p>
        </div>
      )}

      {/* Skeleton while loading */}
      {loadingAnalysis && (
        <div className="space-y-4">
          <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-7 gap-3">
            {[...Array(7)].map((_, i) => <Skeleton key={i} className="h-24" />)}
          </div>
          <Skeleton className="h-12 w-full" />
          <Skeleton className="h-12 w-full" />
          <Skeleton className="h-12 w-full" />
        </div>
      )}

      {/* Results */}
      {analysis && !loadingAnalysis && (() => {
        const q = search.trim().toLowerCase();

        const filtered = analysis.projects.filter(pa => {
          if (q && !(pa.project.fullName?.toLowerCase().includes(q) || pa.deal?.dealName?.toLowerCase().includes(q))) return false;
          if (selectedStatuses.size > 0 && !selectedStatuses.has(pa.project.status ?? '')) return false;
          const meta = projectMeta.get(pa.project.id);
          if (selectedClients.size > 0 && !selectedClients.has(meta?.client ?? '')) return false;
          if (selectedYears.size > 0 && !selectedYears.has(meta?.year ?? '')) return false;
          return true;
        });

        const filteredTotals = filtered.reduce(
          (acc, pa) => ({
            cotizado: acc.cotizado + pa.totals.cotizado,
            costoConMarkup: acc.costoConMarkup + pa.totals.costoConMarkup,
            precioCliente: acc.precioCliente + pa.totals.precioCliente,
            gastado: acc.gastado + pa.totals.gastado,
            markUpInicial: acc.markUpInicial + pa.totals.markUpInicial,
            markUpFinal: acc.markUpFinal + pa.totals.markUpFinal,
          }),
          { cotizado: 0, costoConMarkup: 0, precioCliente: 0, gastado: 0, markUpInicial: 0, markUpFinal: 0 }
        );
        const filteredDiferenciaTotalMxn = filteredTotals.markUpFinal - filteredTotals.markUpInicial;
        const filteredRevenueInicial = filteredTotals.precioCliente > 0
          ? (filteredTotals.markUpInicial / filteredTotals.precioCliente) * 100
          : null;
        const filteredRevenueFinal = filteredTotals.precioCliente > 0
          ? (filteredTotals.markUpFinal / filteredTotals.precioCliente) * 100
          : null;

        const displayTotals = hasActiveFilters
          ? {
              ...filteredTotals,
              diferenciaTotalMxn: filteredDiferenciaTotalMxn,
              revenueInicial: filteredRevenueInicial,
              revenueFinal: filteredRevenueFinal,
            }
          : analysis.grandTotals;

        return (
          <div className="space-y-4">
            <CostSummaryCards totals={displayTotals} hasDeal={displayTotals.precioCliente > 0} />

            {/* Search + Filters bar */}
            <div className="flex flex-wrap items-center gap-2">
              {/* Search */}
              <div className="relative w-56">
                <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground pointer-events-none" />
                <Input
                  placeholder="Buscar proyecto o deal..."
                  value={search}
                  onChange={e => setSearch(e.target.value)}
                  className="pl-8 pr-8 h-9 text-sm"
                />
                {search && (
                  <button
                    onClick={() => setSearch('')}
                    className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
                  >
                    <X className="w-4 h-4" />
                  </button>
                )}
              </div>

              {/* Separator */}
              <div className="h-7 w-px bg-border" />

              {/* Status pills */}
              {uniqueStatuses.map(s => (
                <FilterPill
                  key={s}
                  label={s}
                  active={selectedStatuses.has(s)}
                  onClick={() => toggleStatus(s)}
                />
              ))}

              {uniqueStatuses.length > 0 && uniqueYears.length > 0 && (
                <div className="h-7 w-px bg-border" />
              )}

              {/* Year pills */}
              {uniqueYears.map(y => (
                <FilterPill
                  key={y}
                  label={y}
                  active={selectedYears.has(y)}
                  onClick={() => toggleYear(y)}
                />
              ))}

              {uniqueYears.length > 0 && (
                <div className="h-7 w-px bg-border" />
              )}

              {/* Client popover */}
              <Popover open={clientPopoverOpen} onOpenChange={setClientPopoverOpen}>
                <PopoverTrigger asChild>
                  <button
                    className={cn(
                      'inline-flex items-center gap-1.5 px-3 py-1 rounded-full border text-xs font-medium transition-colors whitespace-nowrap',
                      selectedClients.size > 0
                        ? 'bg-primary/10 text-primary border-primary/30'
                        : 'bg-background text-muted-foreground border-border hover:border-foreground/30 hover:text-foreground'
                    )}
                  >
                    {selectedClients.size > 0 ? `${selectedClients.size} cliente${selectedClients.size > 1 ? 's' : ''}` : 'Cliente'}
                    <ChevronDown className="w-3 h-3 opacity-70" />
                  </button>
                </PopoverTrigger>
                <PopoverContent className="w-60 p-0" align="start">
                  <div className="p-2 border-b border-border">
                    <div className="relative">
                      <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground pointer-events-none" />
                      <Input
                        placeholder="Buscar cliente..."
                        value={clientSearch}
                        onChange={e => setClientSearch(e.target.value)}
                        className="pl-7 h-7 text-xs"
                      />
                    </div>
                  </div>
                  <div className="max-h-56 overflow-y-auto p-1">
                    {filteredClients.length === 0 ? (
                      <p className="text-xs text-muted-foreground text-center py-4">Sin resultados</p>
                    ) : filteredClients.map(c => (
                      <label
                        key={c}
                        className="flex items-center gap-2 px-2 py-1.5 rounded hover:bg-muted cursor-pointer"
                      >
                        <Checkbox
                          checked={selectedClients.has(c)}
                          onCheckedChange={() => toggleClient(c)}
                          className="w-3.5 h-3.5"
                        />
                        <span className="text-xs truncate">{c}</span>
                      </label>
                    ))}
                  </div>
                  {selectedClients.size > 0 && (
                    <div className="border-t border-border p-2">
                      <button
                        onClick={() => setSelectedClients(new Set())}
                        className="text-xs text-muted-foreground hover:text-foreground w-full text-center"
                      >
                        Limpiar selección
                      </button>
                    </div>
                  )}
                </PopoverContent>
              </Popover>

              {/* Clear all */}
              {hasActiveFilters && (
                <button
                  onClick={clearAllFilters}
                  className="inline-flex items-center gap-1 px-2 py-1 text-xs text-muted-foreground hover:text-foreground transition-colors"
                >
                  <X className="w-3 h-3" />
                  Limpiar
                </button>
              )}
            </div>

            <div className="overflow-x-auto overflow-y-auto rounded-lg border border-border max-h-[calc(100vh-380px)]">
              <table className="w-full text-sm min-w-[960px]">
                <thead className="bg-muted text-muted-foreground border-b border-border sticky top-0 z-10">
                  <tr>
                    <th className="w-10" />
                    <th className="px-3 py-3 text-left font-medium">Proyecto</th>
                    <th className="px-3 py-3 text-left font-medium">Deal</th>
                    <th className="px-3 py-3 text-right font-medium">Cotizados</th>
                    <th className="px-3 py-3 text-right font-medium">Mark Up Inicial</th>
                    <th className="px-3 py-3 text-right font-medium">Subtotal Precio</th>
                    <th className="px-3 py-3 text-right font-medium">Precio a cliente (F)</th>
                    <th className="px-3 py-3 text-right font-medium">Costos Reales</th>
                    <th className="px-3 py-3 text-right font-medium">Diferencia Total MXN</th>
                    <th className="px-3 py-3 text-right font-medium">Mark Up Final</th>
                    <th className="px-3 py-3 text-right font-medium">Revenue Inicial %</th>
                    <th className="px-3 py-3 text-right font-medium">Revenue Final %</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border bg-card">
                  {filtered.length === 0 ? (
                    <tr>
                      <td colSpan={12} className="px-3 py-10 text-center text-muted-foreground text-sm">
                        No hay proyectos que coincidan con los filtros aplicados
                      </td>
                    </tr>
                  ) : filtered.map(pa => (
                    <ProjectCostRow
                      key={pa.project.id}
                      analysis={pa}
                      dealsList={analysis.dealsList}
                      isExpanded={expandedIds.has(pa.project.id)}
                      onToggle={() => toggleExpand(pa.project.id)}
                      onRefreshAnalysis={() => runAnalysis(Array.from(selectedIds), true)}
                      onDealUpdated={(projectId, deal) => {
                        setAnalysis(prev => {
                          if (!prev) return prev;
                          return {
                            ...prev,
                            projects: prev.projects.map(pa =>
                              pa.project.id === projectId
                                ? { ...pa, deal: deal ? { id: deal.id, dealName: deal.dealName, clientPrice: deal.clientPrice } : null,
                                    totals: { ...pa.totals, precioCliente: deal?.clientPrice ?? 0 } }
                                : pa
                            ),
                          };
                        });
                      }}
                    />
                  ))}
                </tbody>
                <tfoot className="bg-muted border-t-2 border-border font-semibold text-sm sticky bottom-0 z-10">
                  <tr>
                    <td colSpan={3} className="px-3 py-3 text-foreground font-semibold">
                      TOTAL — {filtered.length}{hasActiveFilters ? ` de ${analysis.projects.length}` : ''} proyectos
                    </td>
                    <td className="px-3 py-3 text-right tabular-nums text-muted-foreground">{fmt(filteredTotals.cotizado)}</td>
                    <td className="px-3 py-3 text-right tabular-nums"><span className={filteredTotals.markUpInicial >= 0 ? 'text-emerald-600' : 'text-destructive'}>{fmt(filteredTotals.markUpInicial)}</span></td>
                    <td className="px-3 py-3 text-right tabular-nums">{fmt(filteredTotals.costoConMarkup)}</td>
                    <td className="px-3 py-3 text-right tabular-nums font-semibold">{fmt(filteredTotals.precioCliente)}</td>
                    <td className="px-3 py-3 text-right tabular-nums">{fmt(filteredTotals.gastado)}</td>
                    <td className="px-3 py-3 text-right tabular-nums"><span className={filteredDiferenciaTotalMxn >= 0 ? 'text-emerald-600' : 'text-destructive'}>{fmt(filteredDiferenciaTotalMxn)}</span></td>
                    <td className="px-3 py-3 text-right tabular-nums"><span className={filteredTotals.markUpFinal >= 0 ? 'text-emerald-600' : 'text-destructive'}>{fmt(filteredTotals.markUpFinal)}</span></td>
                    <td className="px-3 py-3 text-right">{filteredRevenueInicial !== null ? <span className={filteredRevenueInicial >= 0 ? 'text-emerald-600' : 'text-destructive'}>{filteredRevenueInicial.toFixed(1)}%</span> : <span className="text-muted-foreground">—</span>}</td>
                    <td className="px-3 py-3 text-right">{filteredRevenueFinal !== null ? <span className={filteredRevenueFinal >= 0 ? 'text-emerald-600' : 'text-destructive'}>{filteredRevenueFinal.toFixed(1)}%</span> : <span className="text-muted-foreground">—</span>}</td>
                  </tr>
                </tfoot>
              </table>
            </div>
          </div>
        );
      })()}
    </div>
  );
}

src/api/approvePurchaseOrder.ts.content:
import { z } from 'zod';
import { createEndpoint, PurchaseOrders, ApprovalLimits, PoAuditLog, ZiteError } from 'zite-integrations-backend-sdk';
import { publishEvent } from '../lib/ably';
import { fmtCurrency } from '../lib/format';

export default createEndpoint({
  authenticated: true,
  description: 'Approve a purchase order with limit validation',
  inputSchema: z.object({ id: z.string() }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    const level = context.user!.purchaseLevel ?? 'Creador';
    if (level !== 'Aprobador' && level !== 'Finanzas' && level !== 'Socios') throw new ZiteError({ code: 'FORBIDDEN', message: 'No tienes permisos para aprobar órdenes de compra' });

    const po = await PurchaseOrders.findOne({ id: input.id });
    if (!po) throw new ZiteError({ code: 'NOT_FOUND', message: 'Orden de compra no encontrada' });
    if (po.status !== 'Enviada a aprobación') {
      throw new ZiteError({ code: 'BAD_REQUEST', message: 'Solo se pueden aprobar OCs en estatus "Enviada a aprobación". Primero debe ser enviada a aprobación por su creador.' });
    }

    if (level === 'Aprobador') {
      const costCenters = context.user!.costCenters ?? [];
      if (po.category && !costCenters.includes(po.category)) {
        throw new ZiteError({ code: 'FORBIDDEN', message: 'Solo puedes aprobar OCs de tu área' });
      }
    }

    // Socios: sin límite de monto
    if (level !== 'Socios') {
      // 1. Límite personal del usuario (tiene prioridad)
      const personalLimit = context.user!.maxApprovalAmount;
      let effectiveLimit: number | null = null;
      let limitSource = '';

      if (personalLimit != null && personalLimit > 0) {
        effectiveLimit = personalLimit;
        limitSource = 'personal';
      } else {
        // 2. Fallback: límite por nivel + centro de costo
        const { records: limits } = await ApprovalLimits.findAll({
          filters: { approvalLevel: level, costCenter: po.category } as never,
          limit: 1,
        });
        if (limits.length > 0 && limits[0].maxAmount != null) {
          effectiveLimit = limits[0].maxAmount;
          limitSource = `del nivel ${level}`;
        }
      }

      if (effectiveLimit != null) {
        const poAmount = po.totalAmount ?? 0;
        if (poAmount > effectiveLimit) {
          throw new ZiteError({
            code: 'FORBIDDEN',
            message: `El monto de esta OC (${fmtCurrency(poAmount)}) excede tu límite de aprobación ${limitSource} (${fmtCurrency(effectiveLimit)}). Se requiere aprobación de un nivel superior.`,
          });
        }
      }
    }

    await PurchaseOrders.update({ id: input.id, record: { status: 'Aprobada', approvedBy: context.user!.email } });

    const userName = [context.user!.firstName, context.user!.lastName].filter(Boolean).join(' ') || context.user!.email;
    await PoAuditLog.create({
      record: {
        timestamp: new Date().toISOString(),
        purchaseOrder: input.id,
        action: 'Aprobada',
        userEmail: context.user!.email,
        userName,
        poNumber: String(po.poNumber ?? ''),
      },
    });

    try { await publishEvent('purchases:global', 'po.changed', { id: input.id, action: 'approved', senderEmail: context.user!.email, timestamp: new Date().toISOString() }); } catch { /* silent */ }
    return { success: true };
  },
});

src/api/deleteCommercialView.ts.content:
import { z } from 'zod';
import { createEndpoint, CommercialDashboardViews, ZiteError } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Delete a commercial dashboard view by viewId.',
  inputSchema: z.object({ viewId: z.string() }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input }) => {
    const record = await CommercialDashboardViews.findOne({
      filters: { viewId: input.viewId },
    });

    if (!record) throw new ZiteError({ code: 'NOT_FOUND', message: 'Vista no encontrada' });

    await CommercialDashboardViews.delete({ id: record.id });
    return { success: true };
  },
});

src/api/deleteRecruitmentRow.ts.content:
import { z } from 'zod';
import { createEndpoint, RecruitmentRows } from 'zite-integrations-backend-sdk';
import { publishEvent } from '../lib/ably';

const sleep = (ms: number) => new Promise(r => setTimeout(r, ms));

export default createEndpoint({
  authenticated: true,
  description: 'Soft-delete a recruitment row and its children',
  inputSchema: z.object({ id: z.string() }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    const now = new Date().toISOString();

    // Fetch the row first to get projectCode for Ably publish
    const row = await RecruitmentRows.findOne({ id: input.id });

    // Find child rows
    const { records: children } = await RecruitmentRows.findAll({
      filters: { parentRowId: input.id },
      fields: ['id'],
      limit: 100,
    });

    const allIds = [input.id, ...children.map(c => c.id)];

    // Soft-delete all in batches of 10
    for (let i = 0; i < allIds.length; i += 10) {
      await Promise.all(allIds.slice(i, i + 10).map(id =>
        RecruitmentRows.update({ id, record: { deletedAt: now } })
      ));
      if (i + 10 < allIds.length) await sleep(250);
    }

    // Publish Ably realtime event so other open screens remove the row instantly
    if (row?.projectCode) {
      try {
        await publishEvent(`board:${row.projectCode}`, 'recruitment.deleted', {
          id: input.id,
          projectCode: row.projectCode,
          senderEmail: context?.user?.email ?? '',
          timestamp: new Date().toISOString(),
        });
      } catch (err) {
        console.error('[ably] recruitment.deleted publish failed:', err);
      }
    }

    return { success: true };
  },
});

src/api/filloutNativeWebhook.ts.content:
import { z } from 'zod';
import { createEndpoint, RecruitmentRows, Participants, BoardColumns, CellValues, Projects } from 'zite-integrations-backend-sdk';
import { lookupBoardUUID } from '../serverUtils/resolveBoardId';

type ProjectDates = { startDate?: string; endDate?: string };

const normalize = (str: string) =>
  str.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();

const CORE_NAME_EXACT  = new Set(['nombre', 'name', 'nombre completo', 'full name', 'nombre del participante', 'nombre participante']);
const CORE_EMAIL_EXACT = new Set(['email', 'e-mail', 'correo', 'correo electronico', 'mail']);
const CORE_PHONE_EXACT = new Set(['telefono', 'telefono', 'phone', 'celular', 'numero de telefono', 'numero de celular', 'tel']);
const CORE_ID_EXACT    = new Set(['documento', 'cedula', 'cedula', 'id doc', 'numero de documento', 'identificacion', 'identificacion', 'num documento']);

const matchCore = (name: string): string | null => {
  const n = normalize(name);
  if (CORE_NAME_EXACT.has(n))  return 'participantName';
  if (CORE_EMAIL_EXACT.has(n)) return 'email';
  if (CORE_PHONE_EXACT.has(n)) return 'phone';
  if (CORE_ID_EXACT.has(n))    return 'idNumber';
  const words = n.split(/\s+/);
  if (words[0] === 'nombre' && words.length <= 3) return 'participantName';
  if ((words[0] === 'telefono' || words[0] === 'celular') && words.length <= 3) return 'phone';
  return null;
};

/**
 * Converts a raw string value to the correct typed cell value object
 * based on the BoardColumn type. Ensures Número→numberValue, Fecha→dateValue, etc.
 */
const toTypedValue = (rawValue: string, colType: string): Record<string, unknown> => {
  if (!rawValue) return {};
  switch (colType) {
    case 'Número': {
      const cleaned = rawValue.replace(/,/g, '.').replace(/[^0-9.\-]/g, '');
      const n = parseFloat(cleaned);
      return isNaN(n) ? { textValue: rawValue } : { numberValue: n };
    }
    case 'Fecha':
    case 'Datetime':
      return { dateValue: rawValue };
    case 'Checkbox':
      return { booleanValue: ['true', '1', 'sí', 'si', 'yes', 'x'].includes(rawValue.toLowerCase().trim()) };
    case 'Archivo':
      return { fileUrl: rawValue };
    default:
      return { textValue: rawValue };
  }
};

const toText = (rawVal: unknown): string => {
  if (rawVal == null) return '';
  if (typeof rawVal === 'string') return rawVal.trim();
  if (typeof rawVal === 'number' || typeof rawVal === 'boolean') return String(rawVal);
  if (Array.isArray(rawVal)) {
    if (rawVal.length > 0 && typeof rawVal[0] === 'object' && rawVal[0] !== null && 'url' in rawVal[0]) {
      return rawVal.map((f: any) => f.url ?? f.filename ?? '').filter(Boolean).join(', ');
    }
    return rawVal.map(v => String(v)).filter(Boolean).join(', ');
  }
  if (typeof rawVal === 'object' && rawVal !== null) {
    if ('url' in rawVal) return (rawVal as any).url ?? '';
    return JSON.stringify(rawVal);
  }
  return '';
};

const buildParticipationNote = (
  allRows: { id: string; projectCode?: string; boardName?: string; status?: string; group?: string }[],
  newRecordId: string,
  currentProjectCode: string,
  currentBoardName: string,
  projectDatesMap: Map<string, ProjectDates> = new Map(),
): string => {
  const otherRows = allRows.filter(r => r.id !== newRecordId);
  if (otherRows.length === 0) return '';

  const parts: string[] = [];
  const currentDates = projectDatesMap.get(currentProjectCode);
  const currentStart = currentDates?.startDate ? new Date(currentDates.startDate) : null;

  const diffProjectRows = otherRows.filter(r => r.projectCode && r.projectCode !== currentProjectCode);
  const participatedProjects = new Map<string, string>();
  const externalDupProjects  = new Map<string, string>();

  for (const r of diffProjectRows) {
    if (!r.projectCode) continue;
    const label = r.boardName ? `${r.projectCode} (${r.boardName})` : r.projectCode;
    const meetsParticipation = r.status === 'Asistió' || (!!r.group && r.group.trim() !== '');
    if (meetsParticipation) {
      const otherDates = projectDatesMap.get(r.projectCode);
      const otherEnd   = otherDates?.endDate ? new Date(otherDates.endDate) : null;
      const confirmedBefore = currentStart && otherEnd && otherEnd < currentStart;
      if (confirmedBefore) {
        participatedProjects.set(r.projectCode, label);
      } else if (!participatedProjects.has(r.projectCode) && !externalDupProjects.has(r.projectCode)) {
        externalDupProjects.set(r.projectCode, label);
      }
    } else if (!participatedProjects.has(r.projectCode) && !externalDupProjects.has(r.projectCode)) {
      externalDupProjects.set(r.projectCode, label);
    }
  }

  if (participatedProjects.size > 0) parts.push(`🔴 YA PARTICIPÓ: ${[...participatedProjects.values()].join(', ')}.`);
  const extLabels = [...externalDupProjects.entries()].filter(([k]) => !participatedProjects.has(k)).map(([, v]) => v);
  if (extLabels.length > 0) parts.push(`🟡 DUPLICADO EXTERNO: ${extLabels.join(', ')}.`);

  const sameProjectDiffBoard = otherRows.filter(r => r.projectCode === currentProjectCode && r.boardName && r.boardName !== currentBoardName);
  if (sameProjectDiffBoard.length > 0) {
    const boardNames = [...new Set(sameProjectDiffBoard.map(r => r.boardName).filter(Boolean) as string[])];
    parts.push(`🟠 MISMO PROYECTO: ${boardNames.join(', ')}.`);
  }

  const internalRows = otherRows.filter(r => r.projectCode === currentProjectCode && r.boardName === currentBoardName);
  if (internalRows.length > 0) parts.push(`🔵 ×${internalRows.length + 1} EN ESTE TABLERO`);

  return parts.join(' ');
};

const questionSchema = z.object({
  id: z.string(),
  name: z.string().optional(),
  type: z.string().optional(),
  value: z.unknown().optional(),
});

export default createEndpoint({
  description: 'Receives real-time form submissions directly from Fillout webhooks',
  inputSchema: z.object({
    formId: z.string().optional(),
    submissionId: z.string().optional(),
    // Fillout may send questions at the top level or nested inside submission
    questions: z.array(questionSchema).optional(),
    answers: z.array(questionSchema).optional(),
    submission: z.object({
      questions: z.array(questionSchema).optional(),
      answers: z.array(questionSchema).optional(),
    }).optional(),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input }) => {
    const formId = input.formId;
    if (!formId) return { success: true };

    // ── 1. Find the board linked to this formId ────────────────────────────
    const { records: linkCols } = await BoardColumns.findAll({
      filters: { columnType: '__fillout_link__' },
      limit: 200,
    });

    const linkCol = linkCols.find(col => {
      if (!col.optionsJson) return false;
      try {
        const meta = JSON.parse(col.optionsJson);
        return meta.formId === formId;
      } catch { return false; }
    });

    if (!linkCol?.optionsJson) return { success: true };

    const meta = JSON.parse(linkCol.optionsJson) as {
      formId: string;
      formName: string;
      boardId: string;
      legacyBoardId?: string;
      projectCode: string;
      boardName: string;
      questionMapping?: { filloutId: string; columnId: string; questionName: string }[];
    };
    const { projectCode, boardName, formName, questionMapping = [] } = meta;

    // ── Resolve boardId: if meta.boardId is legacy (pre-migration link), try UUID ─
    const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    let boardId = meta.boardId;
    if (!UUID_RE.test(boardId) && projectCode && boardName) {
      const lookup = await lookupBoardUUID(projectCode, boardName, 'recruitment');
      if (lookup.found && lookup.uuid) {
        console.log('[filloutNativeWebhook] Resolved legacy meta.boardId to UUID', {
          legacy: boardId, uuid: lookup.uuid,
        });
        boardId = lookup.uuid;
      } else {
        console.warn('[filloutNativeWebhook] Could not resolve legacy meta.boardId, using as-is', {
          boardId, reason: lookup.reason,
        });
      }
    }

    const idToColId = new Map<string, string>();
    for (const entry of questionMapping) idToColId.set(entry.filloutId, entry.columnId);

    // ── 1b. Fetch board column types ──────────────────────────────────────
    const { records: boardCols } = await BoardColumns.findAll({
      filters: { boardId },
      limit: 500,
      fields: ['id', 'columnType'],
    });
    const colIdToType = new Map(boardCols.map(c => [c.id, c.columnType ?? '']));

    // ── 2. Extract questions from the payload ─────────────────────────────
    const questions: any[] =
      input.questions ??
      input.answers ??
      input.submission?.questions ??
      input.submission?.answers ??
      [];

    if (questions.length === 0) return { success: true };

    // ── 3. Parse core fields and dynamic cells ────────────────────────────
    const coreFields: Record<string, string> = {};
    const cellsToWrite: { columnId: string; value: string }[] = [];

    for (const q of questions) {
      const name  = (q.name ?? q.label ?? '').trim();
      const value = toText(q.value);
      const coreKey = matchCore(name);
      if (coreKey && value) coreFields[coreKey] = value;
      const colId = idToColId.get(q.id);
      if (colId && value) cellsToWrite.push({ columnId: colId, value });
    }

    if (!coreFields.participantName && !coreFields.email) return { success: true };

    // ── 4. Dedup check ────────────────────────────────────────────────────
    const emailLower = coreFields.email?.toLowerCase() ?? '';
    const existingChecks: Promise<{ records: any[] }>[] = [];
    if (emailLower) existingChecks.push(RecruitmentRows.findAll({ filters: { email: emailLower, boardName, projectCode }, limit: 5, fields: ['id', 'email'] }));
    else if (coreFields.participantName) existingChecks.push(RecruitmentRows.findAll({ filters: { participantName: { contains: coreFields.participantName }, boardName, projectCode }, limit: 5, fields: ['id', 'participantName'] }));

    if (existingChecks.length > 0) {
      const [result] = await Promise.all(existingChecks);
      if (result.records.length > 0) return { success: true };
    }

    // ── 5. Upsert participant ─────────────────────────────────────────────
    await Participants.bulkCreate({
      records: [{
        fullName: coreFields.participantName,
        email: coreFields.email,
        phone: coreFields.phone,
        idNumber: coreFields.idNumber,
      }],
      matchOn: coreFields.email ? ['email'] : undefined,
    });

    // ── 6. Create recruitment row ─────────────────────────────────────────
    // boardId is already resolved to UUID above (via lookupBoardUUID)
    const UUID_RE_CHECK = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    const resolvedRowBoardId = UUID_RE_CHECK.test(boardId) ? boardId : undefined;
    if (!resolvedRowBoardId) {
      console.warn('[filloutNativeWebhook] boardId is not a UUID, skipping boardId on row', { boardId });
    }

    const record = await RecruitmentRows.create({
      record: {
        rowName: coreFields.participantName ?? coreFields.email ?? 'Sin nombre',
        projectCode, boardName,
        boardId: resolvedRowBoardId,
        participantName: coreFields.participantName,
        email: coreFields.email,
        phone: coreFields.phone,
        idNumber: coreFields.idNumber,
        status: 'Pendiente',
        sourceForm: formName,
        level: 0,
      },
    });

    // ── 7. Write cell values — typed per column type ──────────────────────
    if (cellsToWrite.length > 0) {
      const cellRecords = cellsToWrite.map(c => {
        const colType = colIdToType.get(c.columnId) ?? 'Texto';
        return {
          boardId,
          rowId: record.id,
          columnId: c.columnId,
          ...toTypedValue(c.value, colType),
        };
      });
      for (let ci = 0; ci < cellRecords.length; ci += 100) {
        await CellValues.bulkCreate({ records: cellRecords.slice(ci, ci + 100) });
      }
      await RecruitmentRows.update({
        id: record.id,
        record: {
          cellData: JSON.stringify(
            Object.fromEntries(cellsToWrite.map(c => {
              const colType = colIdToType.get(c.columnId) ?? 'Texto';
              return [c.columnId, toTypedValue(c.value, colType)];
            }))
          ),
        },
      });
    }

    // ── 8. Duplicate detection ────────────────────────────────────────────
    try {
      const { records: allProjects } = await Projects.findAll({ limit: 500, fields: ['projectCode', 'startDate', 'endDate'] });
      const projectDatesMap = new Map<string, ProjectDates>();
      for (const p of allProjects) {
        if (p.projectCode) projectDatesMap.set(p.projectCode, { startDate: p.startDate, endDate: p.endDate });
      }

      const detectionFields = ['id', 'participantName', 'email', 'phone', 'projectCode', 'boardName', 'status', 'group', 'deletedAt'];
      const queries: Promise<{ records: any[] }>[] = [];
      if (coreFields.email) queries.push(RecruitmentRows.findAll({ filters: { email: coreFields.email }, limit: 50, fields: detectionFields }));
      if (coreFields.participantName) queries.push(RecruitmentRows.findAll({ filters: { participantName: { contains: coreFields.participantName } }, limit: 50, fields: detectionFields }));
      if (coreFields.phone) queries.push(RecruitmentRows.findAll({ filters: { phone: coreFields.phone }, limit: 50, fields: detectionFields }));

      if (queries.length > 0) {
        const results = await Promise.all(queries);
        const seen = new Set<string>();
        const merged: any[] = [];
        for (const { records } of results) {
          for (const r of records) { if (!seen.has(r.id)) { seen.add(r.id); merged.push(r); } }
        }
        const activeRows = merged.filter(r => !r.deletedAt);
        const note = buildParticipationNote(activeRows, record.id, projectCode, boardName, projectDatesMap);
        if (note) await RecruitmentRows.update({ id: record.id, record: { notes: note } });
      }
    } catch { /* non-blocking */ }

    return { success: true };
  },
});

src/api/getAllCalendarEvents.ts.content:
import { z } from 'zod';
import { createEndpoint, CalendarEvents, Boards } from 'zite-integrations-backend-sdk';

const dedup = <T extends { id: string }>(a: T[], b: T[]): T[] => {
  const seen = new Map<string, T>();
  for (const r of a) seen.set(r.id, r);
  for (const r of b) if (!seen.has(r.id)) seen.set(r.id, r);
  return Array.from(seen.values());
};

const eventSchema = z.object({
  id: z.string(),
  eventName: z.string().optional(),
  projectCode: z.string().optional(),
  calendarName: z.string().optional(),
  boardId: z.string().optional(),
  eventDate: z.string().optional(),
  durationHours: z.number().optional(),
  location: z.string().optional(),
  attendees: z.string().optional(),
  notes: z.string().optional(),
  parentEventId: z.string().optional(),
  inviteStatus: z.string().optional(),
  outlookEventId: z.string().optional(),
  outlookEventLink: z.string().optional(),
  inviteBodyHtml: z.string().optional(),
  inviteEmails: z.string().optional(),
});

export default createEndpoint({
  authenticated: true,
  description: 'Get all calendar events, optionally filtered by date range. Excludes events from deleted calendar boards.',
  inputSchema: z.object({
    startDate: z.string().optional(),
    endDate: z.string().optional(),
    boardId: z.string().optional(),
    projectCode: z.string().optional(),
    calendarName: z.string().optional(),
  }),
  outputSchema: z.object({ events: z.array(eventSchema) }),
  execute: async ({ input }) => {
    // Build date filters
    const dateFilters: Record<string, any> = {};
    if (input.startDate && input.endDate) {
      dateFilters.eventDate = { gte: new Date(input.startDate), lte: new Date(input.endDate) };
    } else if (input.startDate) {
      dateFilters.eventDate = { gte: new Date(input.startDate) };
    } else if (input.endDate) {
      dateFilters.eventDate = { lte: new Date(input.endDate) };
    }

    let records: any[];

    if (input.boardId) {
      // ── UUID-first: boardId exclusively ──
      const q1 = await CalendarEvents.findAll({
        filters: { boardId: input.boardId, ...dateFilters },
        limit: 2000,
      });

      // Also pick up legacy events that have no boardId but match by name (transition period)
      let fallback: any[] = [];
      if (input.projectCode && input.calendarName) {
        const q2 = await CalendarEvents.findAll({
          filters: { projectCode: input.projectCode, calendarName: input.calendarName, ...dateFilters },
          limit: 2000,
        });
        fallback = q2.records.filter(e => !e.boardId);
      }

      records = dedup(q1.records, fallback);
    } else {
      // ── Legacy path (unchanged) ──
      const result = await CalendarEvents.findAll({ filters: dateFilters, limit: 2000 });
      records = result.records;
    }

    // ── Fetch active calendar boards — build UUID set + legacy key set ──
    const { records: activeBoards } = await Boards.findAll({
      filters: { deletedAt: null as any, boardType: 'calendar' },
      fields: ['boardName', 'projectCode'],
      limit: 500,
    });

    const activeBoardIds = new Set(activeBoards.map(b => b.id));
    const activeBoardKeys = new Set(
      activeBoards.map(b => `${b.projectCode ?? ''}||${b.boardName ?? ''}`)
    );

    // ── Filter: UUID-first validation, legacy fallback for old events ──
    const events = records.filter(ev => {
      if (ev.boardId) {
        // Event has UUID → validate against active board IDs
        return activeBoardIds.has(ev.boardId);
      }
      if (ev.calendarName) {
        // No UUID, legacy event → validate against name-based keys
        const key = `${ev.projectCode ?? ''}||${ev.calendarName}`;
        return activeBoardKeys.has(key);
      }
      // No boardId, no calendarName → orphan-safe, include it
      return true;
    });

    return {
      events: events.map(ev => ({
        id: ev.id,
        eventName: ev.eventName,
        projectCode: ev.projectCode,
        calendarName: ev.calendarName,
        boardId: ev.boardId,
        eventDate: ev.eventDate,
        durationHours: ev.durationHours,
        location: ev.location,
        attendees: ev.attendees,
        notes: ev.notes,
        parentEventId: ev.parentEventId,
        inviteStatus: ev.inviteStatus,
        outlookEventId: ev.outlookEventId,
        outlookEventLink: ev.outlookEventLink,
        inviteBodyHtml: ev.inviteBodyHtml,
        inviteEmails: ev.inviteEmails,
      })),
    };
  },
});

