src/api/getChatConversations.ts.content:
import { z } from 'zod';
import { createEndpoint, ChatConversations } from 'zite-integrations-backend-sdk';
import { parseMembers } from '../lib/chatJson';

export default createEndpoint({
  description: 'Get all DM and group conversations for the current user',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    dms: z.array(z.object({
      id: z.string(),
      members: z.array(z.string()),
      lastMessageAt: z.string().optional(),
    })),
    groups: z.array(z.object({
      id: z.string(),
      name: z.string(),
      members: z.array(z.string()),
      lastMessageAt: z.string().optional(),
    })),
  }),
  execute: async ({ context }) => {
    const myEmail = context.user!.email;

    const { records } = await ChatConversations.findAll({
      filters: { members: { contains: myEmail } },
      limit: 500,
    });

    const dms = records
      .filter(r => r.type === 'DM')
      .map(r => ({
        id: r.id,
        members: parseMembers(r.members),
        lastMessageAt: r.lastMessageAt ?? undefined,
      }))
      .sort((a, b) => new Date(b.lastMessageAt ?? 0).getTime() - new Date(a.lastMessageAt ?? 0).getTime());

    const groups = records
      .filter(r => r.type === 'Group')
      .map(r => ({
        id: r.id,
        name: r.conversationName ?? 'Grupo',
        members: parseMembers(r.members),
        lastMessageAt: r.lastMessageAt ?? undefined,
      }))
      .sort((a, b) => new Date(b.lastMessageAt ?? 0).getTime() - new Date(a.lastMessageAt ?? 0).getTime());

    return { dms, groups };
  },
});

src/api/getCotizacionesAdmin.ts.content:
import { z } from 'zod';
import { createEndpoint, Cotizaciones, Deals } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Get all cotizaciones with resolved deal names for the admin management page',
  inputSchema: z.object({}),
  outputSchema: z.object({
    cotizaciones: z.array(z.object({
      id: z.string(),
      cotizacionName: z.string(),
      currency: z.string(),
      totalCost: z.number().nullable(),
      clientPrice: z.number().nullable(),
      status: z.string(),
      included: z.boolean(),
      dealId: z.string().nullable(),
      dealName: z.string().nullable(),
    })),
    dealsList: z.array(z.object({ id: z.string(), dealName: z.string() })),
  }),
  execute: async () => {
    const [{ records: cotizRecords }, { records: dealRecords }] = await Promise.all([
      Cotizaciones.findAll({ limit: 2000 }),
      Deals.findAll({ fields: ['dealName'], limit: 2000 }),
    ]);

    const dealsById: Record<string, string> = {};
    for (const d of dealRecords) dealsById[d.id] = d.dealName ?? '';

    const cotizaciones = cotizRecords.map(c => {
      const dealId = Array.isArray(c.deal) ? (c.deal[0] ?? null) : (c.deal ?? null);
      return {
        id: c.id,
        cotizacionName: c.cotizacionName ?? '',
        currency: c.currency ?? 'MXN',
        totalCost: c.totalCost ?? null,
        clientPrice: c.clientPrice ?? null,
        status: c.status ?? 'Borrador',
        included: c.included ?? false,
        dealId: dealId as string | null,
        dealName: dealId ? (dealsById[dealId] ?? null) : null,
      };
    });

    return {
      cotizaciones,
      dealsList: dealRecords.map(d => ({ id: d.id, dealName: d.dealName ?? '' })),
    };
  },
});

src/api/getInvoiceWidgetData.ts.content:
import { z } from 'zod';
import { createEndpoint, SupplierInvoices } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Returns unpaid supplier invoice count and last 10 invoices for the dashboard widget',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    unpaidCount: z.number(),
    invoices: z.array(z.object({
      id: z.string(),
      invoiceNumber: z.string().optional(),
      supplierName: z.string().optional(),
      amount: z.number().optional(),
      currency: z.string().optional(),
      status: z.string().optional(),
      uploadDate: z.string().optional(),
      projectCode: z.string().optional(),
    })),
  }),
  execute: async () => {
    const { records } = await SupplierInvoices.findAll({
      filters: { status: { not: 'Validada' } },
      limit: 500,
    });

    // Sort by uploadDate desc
    const sorted = records
      .filter(r => r.uploadDate)
      .sort((a, b) => new Date(b.uploadDate!).getTime() - new Date(a.uploadDate!).getTime());

    const noDateRecords = records.filter(r => !r.uploadDate);
    const allSorted = [...sorted, ...noDateRecords];

    return {
      unpaidCount: allSorted.length,
      invoices: allSorted.slice(0, 10).map(r => ({
        id: r.id,
        invoiceNumber: r.invoiceNumber,
        supplierName: r.supplierName,
        amount: r.amount,
        currency: r.currency,
        status: r.status,
        uploadDate: r.uploadDate,
        projectCode: r.projectCode,
      })),
    };
  },
});

src/api/getRecruitmentGroups.ts.content:
import { z } from 'zod';
import { createEndpoint, Boards, BoardColumns } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Get all recruitment groups for a project, with their current linked event (if any)',
  inputSchema: z.object({
    projectCode: z.string(),
  }),
  outputSchema: z.object({
    groups: z.array(z.object({
      groupId: z.string(),
      groupName: z.string(),
      boardName: z.string(),
      recruitmentBoardId: z.string(),
      linkedEventId: z.string().optional(),
      linkedCalBoardId: z.string().optional(),
    })),
  }),
  execute: async ({ input }) => {
    const { projectCode } = input;

    // 1. Find all recruitment boards for this project
    const boardsResult = await Boards.findAll({
      filters: { projectCode },
      limit: 200,
    });

    const recBoards = boardsResult.records.filter(
      b => !b.deletedAt && !!b.boardName && b.boardType !== 'pm' && b.boardType !== 'calendar'
    );

    const groups: {
      groupId: string;
      groupName: string;
      boardName: string;
      recruitmentBoardId: string;
      linkedEventId?: string;
      linkedCalBoardId?: string;
    }[] = [];

    // 2. For each recruitment board, fetch group columns from BOTH UUID and legacy
    for (const board of recBoards) {
      const boardName = board.boardName!;
      const recruitmentBoardId = `recruitment-${projectCode}-${boardName}`;
      const legacyGroupId = `${recruitmentBoardId}::groups`;
      const uuidGroupId = `${board.id}::groups`;

      // Fetch from both sources in parallel, merge & deduplicate by column id
      // Build candidate board IDs (deduplicated)
      const groupBoardIds = [uuidGroupId];
      if (legacyGroupId !== uuidGroupId) groupBoardIds.push(legacyGroupId);

      const colResults = await Promise.all(
        groupBoardIds.map(id => BoardColumns.findAll({ filters: { boardId: id }, limit: 200 }))
      );

      const seen = new Set<string>();
      const allCols = colResults.flatMap(r => r.records); // UUID first

      for (const col of allCols) {
        if (col.deletedAt || !col.columnName || seen.has(col.id)) continue;
        seen.add(col.id);

        let linkedEventId: string | undefined;
        let linkedCalBoardId: string | undefined;

        // Parse optionsJson for linkedCalEvent
        if (col.optionsJson) {
          try {
            const opts = JSON.parse(col.optionsJson) as Record<string, unknown>;
            const link = opts.linkedCalEvent as { calBoardId?: string; eventId?: string } | undefined;
            if (link?.eventId) {
              linkedEventId = link.eventId;
              linkedCalBoardId = link.calBoardId;
            }
          } catch { /* ignore */ }
        }

        groups.push({
          groupId: col.id,
          groupName: col.columnName,
          boardName,
          recruitmentBoardId,
          linkedEventId,
          linkedCalBoardId,
        });
      }
    }

    return { groups };
  },
});

src/api/mergeSupplierRecords.ts.content:
import { z } from 'zod';
import { createEndpoint, Suppliers, PurchaseOrders } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Merge duplicate supplier records: reassigns POs from duplicates to the primary supplier name, then deletes the duplicate supplier records.',
  inputSchema: z.object({
    primarySupplierId: z.string(),
    duplicateSupplierIds: z.array(z.string()),
  }),
  outputSchema: z.object({
    posUpdated: z.number(),
    suppliersDeleted: z.number(),
  }),
  execute: async ({ input }) => {
    // Get primary supplier name
    const primary = await Suppliers.findOne({ id: input.primarySupplierId });
    if (!primary || !primary.supplierName) {
      throw new Error('Proveedor principal no encontrado');
    }
    const primaryName = primary.supplierName;

    // Get all duplicate suppliers to know their names
    const duplicates: { id: string; name: string }[] = [];
    for (const id of input.duplicateSupplierIds) {
      const s = await Suppliers.findOne({ id });
      if (s && s.supplierName) duplicates.push({ id, name: s.supplierName });
    }

    // Reassign POs from each duplicate supplier name to the primary name
    let posUpdated = 0;
    for (const dup of duplicates) {
      if (dup.name === primaryName) continue;
      const { records: posToUpdate } = await PurchaseOrders.findAll({
        filters: { supplierName: dup.name },
        fields: ['id'],
        limit: 2000,
      });
      for (const po of posToUpdate) {
        await PurchaseOrders.update({ id: po.id, record: { supplierName: primaryName } });
        posUpdated++;
      }
    }

    // Delete duplicate supplier records
    let suppliersDeleted = 0;
    for (const dup of duplicates) {
      await Suppliers.delete({ id: dup.id });
      suppliersDeleted++;
    }

    return { posUpdated, suppliersDeleted };
  },
});

src/api/migrateProjectToUUID.ts.content:
import { z } from 'zod';
import { createEndpoint, Boards, BoardColumns, SharedViews } from 'zite-integrations-backend-sdk';

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const KNOWN_PREFIXES = [
  { prefix: 'recruitment-', boardType: 'recruitment' },
  { prefix: 'cal-', boardType: 'calendar' },
  { prefix: 'events-', boardType: 'events' },
  { prefix: 'pm-', boardType: 'pm' },
] as const;

function buildLegacyVariants(boardType: string, projectCode: string, boardName: string): string[] {
  const prefix = boardType === 'calendar' ? 'cal-'
    : boardType === 'recruitment' ? 'recruitment-'
    : boardType === 'events' ? 'events-'
    : 'pm-';
  const base = boardName ? `${prefix}${projectCode}-${boardName}` : `${prefix}${projectCode}`;
  return [base, `${base}::groups`, `${base}::children`];
}

function detectLegacyProjectCode(boardId: string): string | null {
  for (const { prefix } of KNOWN_PREFIXES) {
    if (boardId.startsWith(prefix)) return boardId.slice(prefix.length).split('-').slice(0, 2).join('-');
  }
  return null;
}

function isLegacyBoardId(id: string): boolean {
  const base = id.replace(/::groups$|::children$/, '');
  return !UUID_RE.test(base);
}

export default createEndpoint({
  authenticated: true,
  description: 'Migrate BoardColumns and SharedViews from legacy composite boardId to UUID for a given project',
  inputSchema: z.object({
    projectCode: z.string(),
    dryRun: z.boolean(),
  }),
  outputSchema: z.object({
    boardMap: z.record(z.string(), z.string()),
    columns: z.object({
      total: z.number(),
      migrated: z.number(),
      alreadyUUID: z.number(),
      failed: z.number(),
      byBoard: z.record(z.string(), z.number()),
    }),
    views: z.object({
      total: z.number(),
      migrated: z.number(),
      alreadyUUID: z.number(),
    }),
    dryRun: z.boolean(),
  }),
  execute: async ({ input }) => {
    const { projectCode, dryRun } = input;

    // 1. Load all boards for this project
    const { records: boards } = await Boards.findAll({
      filters: { projectCode },
      limit: 200,
    });
    const activeBoards = boards.filter(b => !b.deletedAt);

    // 2. Build legacy → UUID map (including ::groups and ::children variants)
    const boardMap: Record<string, string> = {};
    for (const board of activeBoards) {
      const bType = board.boardType || 'pm';
      const bName = board.boardName ?? '';
      const variants = buildLegacyVariants(bType, projectCode, bName);
      // variants[0] = base, variants[1] = ::groups, variants[2] = ::children
      boardMap[variants[0]] = board.id;
      boardMap[variants[1]] = `${board.id}::groups`;
      boardMap[variants[2]] = `${board.id}::children`;
    }

    // 3. Scan all BoardColumns with pagination, filter legacy ones for this project
    const colResult = { total: 0, migrated: 0, alreadyUUID: 0, failed: 0, byBoard: {} as Record<string, number> };
    let colOffset = 0;
    let colHasMore = true;
    const colBatchUpdates: { id: string; newBoardId: string }[] = [];

    while (colHasMore) {
      const { records, hasMore } = await BoardColumns.findAll({ offset: colOffset, limit: 2000 });
      for (const col of records) {
        const bid = col.boardId ?? '';
        if (!bid) continue;

        // Check if this column belongs to this project
        const belongsToProject = boardMap[bid] !== undefined
          || (isLegacyBoardId(bid) && detectLegacyProjectCode(bid)?.startsWith(projectCode));

        if (!belongsToProject) {
          // Check if it's a UUID that maps to one of our boards
          const base = bid.replace(/::groups$|::children$/, '');
          if (UUID_RE.test(base) && activeBoards.some(b => b.id === base)) {
            colResult.total++;
            colResult.alreadyUUID++;
          }
          continue;
        }

        colResult.total++;

        if (!isLegacyBoardId(bid)) {
          colResult.alreadyUUID++;
          continue;
        }

        const mapped = boardMap[bid];
        if (mapped) {
          colBatchUpdates.push({ id: col.id, newBoardId: mapped });
          colResult.byBoard[bid] = (colResult.byBoard[bid] ?? 0) + 1;
        } else {
          colResult.failed++;
        }
      }
      colOffset += records.length;
      colHasMore = hasMore;
    }

    // 4. Apply column updates in batches of 100
    if (!dryRun) {
      for (let i = 0; i < colBatchUpdates.length; i += 100) {
        const batch = colBatchUpdates.slice(i, i + 100);
        await Promise.all(batch.map(u =>
          BoardColumns.update({ id: u.id, record: { boardId: u.newBoardId } })
        ));
      }
    }
    colResult.migrated = dryRun ? 0 : colBatchUpdates.length;
    // If dryRun, report how many WOULD be migrated via byBoard totals

    // 5. Scan SharedViews with pagination
    const viewResult = { total: 0, migrated: 0, alreadyUUID: 0 };
    let viewOffset = 0;
    let viewHasMore = true;
    const viewBatchUpdates: { id: string; newBoardId: string }[] = [];

    while (viewHasMore) {
      const { records, hasMore } = await SharedViews.findAll({
        filters: { projectCode },
        offset: viewOffset,
        limit: 2000,
      });
      for (const view of records) {
        const bid = view.boardId ?? '';
        if (!bid) continue;
        viewResult.total++;

        if (!isLegacyBoardId(bid)) {
          viewResult.alreadyUUID++;
          continue;
        }

        const mapped = boardMap[bid];
        if (mapped) {
          viewBatchUpdates.push({ id: view.id, newBoardId: mapped });
        }
      }
      viewOffset += records.length;
      viewHasMore = hasMore;
    }

    // 6. Apply view updates in batches of 100
    if (!dryRun) {
      for (let i = 0; i < viewBatchUpdates.length; i += 100) {
        const batch = viewBatchUpdates.slice(i, i + 100);
        await Promise.all(batch.map(u =>
          SharedViews.update({ id: u.id, record: { boardId: u.newBoardId } })
        ));
      }
    }
    viewResult.migrated = dryRun ? 0 : viewBatchUpdates.length;

    return {
      boardMap,
      columns: colResult,
      views: viewResult,
      dryRun,
    };
  },
});

