import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { ChevronRight, ChevronDown, CornerDownRight, ZoomIn, ZoomOut } from 'lucide-react';
import { useDebouncedCallback } from 'use-debounce';
import { saveCellValue, saveTask } from 'zite-endpoints-sdk';
import { toast } from 'sonner';
import { type Task, type GanttScale, type BoardGanttGroup } from './pmTypes';
import { BOARD_GANTT_STATUS_COLORS } from './pmConstants';
import { fmtDate } from './pmDateUtils';
import { getGroupColor } from '../table/tableUtils';
import { type DynCols } from '../DynamicColumns';
import type { DynColumn } from '../../hooks/useDynamicColumns';

// ── Row height constants ─────────────────────────────────────────────────────
const PARENT_ROW_H = 36;
const CHILD_ROW_H  = 30;
const GROUP_H      = 30;

// ── Color picker ─────────────────────────────────────────────────────────────
function BoardGanttBarColorPicker({ taskId, boardId, colorColId, currentColor, recentColors, onColorChange }: {
  taskId: string; boardId: string; colorColId: string; currentColor: string;
  recentColors: string[]; onColorChange: (taskId: string, color: string) => void;
}) {
  const [open, setOpen] = useState(false);
  const [localHex, setLocalHex] = useState(currentColor || '#6366f1');
  const inputRef = useRef<HTMLInputElement>(null);

  const debouncedSave = useDebouncedCallback(async (hex: string) => {
    onColorChange(taskId, hex);
    try { await saveCellValue({ boardId, rowId: taskId, columnId: colorColId, textValue: hex }); } catch { /* best-effort */ }
  }, 400);

  const applyColor = async (hex: string) => {
    setLocalHex(hex); onColorChange(taskId, hex); setOpen(false);
    try { await saveCellValue({ boardId, rowId: taskId, columnId: colorColId, textValue: hex }); } catch { /* best-effort */ }
  };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <button className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" onClick={e => { e.stopPropagation(); setOpen(true); }} title="Cambiar color" />
      </PopoverTrigger>
      <PopoverContent className="p-0 w-52" align="center" onClick={e => e.stopPropagation()}>
        <div className="p-2 border-b border-border"><p className="text-xs font-medium text-muted-foreground px-1">Color de la barra</p></div>
        <div className="p-3 space-y-3">
          {recentColors.length > 0 && (
            <div>
              <p className="text-[10px] text-muted-foreground mb-1.5">Recientes</p>
              <div className="flex flex-wrap gap-1.5">
                {recentColors.map(hex => (
                  <button key={hex} title={hex} onClick={() => applyColor(hex)}
                    className={`w-5 h-5 rounded-full border transition-all hover:scale-110 ${currentColor === hex ? 'ring-2 ring-offset-1 ring-foreground scale-110' : 'border-border/50'}`}
                    style={{ backgroundColor: hex }} />
                ))}
              </div>
            </div>
          )}
          <div>
            <input ref={inputRef} type="color" className="sr-only" value={localHex}
              onChange={e => { setLocalHex(e.target.value); debouncedSave(e.target.value); }} />
            <button onClick={() => inputRef.current?.click()}
              className="w-full flex items-center gap-2.5 px-2 py-1.5 rounded-md border border-border/50 hover:bg-muted transition-colors text-left">
              <div className="w-5 h-5 rounded-full border border-border/50 flex-shrink-0" style={{ backgroundColor: localHex }} />
              <span className="text-xs text-foreground">Elegir color personalizado</span>
            </button>
          </div>
        </div>
        {currentColor && (
          <div className="px-3 pb-3">
            <button className="w-full text-xs text-muted-foreground hover:text-destructive text-center py-1 rounded hover:bg-muted/50 transition-colors"
              onClick={async () => { onColorChange(taskId, ''); setOpen(false); try { await saveCellValue({ boardId, rowId: taskId, columnId: colorColId, textValue: '' }); } catch { /**/ } }}>
              Quitar color
            </button>
          </div>
        )}
      </PopoverContent>
    </Popover>
  );
}

// ── Row types ─────────────────────────────────────────────────────────────────
type GanttRow =
  | { kind: 'group-header'; group: BoardGanttGroup; groupColor: string }
  | { kind: 'task';         task: Task;              groupColor: string }
  | { kind: 'child';        task: Task;              groupColor: string };

const rowH   = (r: GanttRow) => r.kind === 'group-header' ? GROUP_H : r.kind === 'child' ? CHILD_ROW_H : PARENT_ROW_H;
const rowKey = (r: GanttRow) => r.kind === 'group-header' ? `g:${r.group.id}` : `t:${r.task.id}`;

// ── Main component ────────────────────────────────────────────────────────────
export function GanttView({ tasks, dynCols, childDynCols, groupDynCols, boardId }: {
  tasks: Task[]; dynCols: DynCols; childDynCols: DynCols; groupDynCols: DynCols; boardId: string;
}) {
  const [scale, setScale]               = useState<GanttScale>('weeks');
  const [colorMode, setColorMode]       = useState<'status' | 'color'>('status');
  const [localColors, setLocalColors]   = useState<Map<string, string>>(new Map());
  const [localDates, setLocalDates]     = useState<Map<string, { start: string; end: string }>>(new Map());
  const [collapsedGroups, setCollapsedGroups] = useState<Set<string>>(new Set());
  const [hoveredKey, setHoveredKey]     = useState<string | null>(null);

  const hasScrolledRef = useRef(false);
  const scrollRef      = useRef<HTMLDivElement>(null);
  const dragRef        = useRef<{
    taskId: string; edge: 'left' | 'right'; origStart: string; origEnd: string;
    startX: number; curStart: string; curEnd: string;
  } | null>(null);
  const ppdRef        = useRef(4);
  const padMinRef     = useRef(new Date());
  const saveResizeRef = useRef<((id: string, s: string, e: string) => Promise<void>) | null>(null);
  const [dragPreview, setDragPreview] = useState<{
    taskId: string; bLeft: number; bWidth: number; label: string; mouseX: number; mouseY: number;
  } | null>(null);

  // Mouse events for drag-resize
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      const drag = dragRef.current;
      if (!drag) return;
      const deltaDays = Math.round((e.clientX - drag.startX) / ppdRef.current);
      let newStart = drag.origStart, newEnd = drag.origEnd;
      if (drag.edge === 'left') {
        const d = new Date(drag.origStart + 'T00:00:00'); d.setDate(d.getDate() + deltaDays);
        if (d < new Date(drag.origEnd + 'T00:00:00')) newStart = d.toISOString().split('T')[0];
      } else {
        const d = new Date(drag.origEnd + 'T00:00:00'); d.setDate(d.getDate() + deltaDays);
        if (d > new Date(drag.origStart + 'T00:00:00')) newEnd = d.toISOString().split('T')[0];
      }
      drag.curStart = newStart; drag.curEnd = newEnd;
      const bLeft  = Math.max(0, (new Date(newStart + 'T00:00:00').getTime() - padMinRef.current.getTime()) / 86400000 * ppdRef.current);
      const bWidth = Math.max(((new Date(newEnd + 'T00:00:00').getTime() - new Date(newStart + 'T00:00:00').getTime()) / 86400000 + 1) * ppdRef.current, 4);
      setDragPreview({ taskId: drag.taskId, bLeft, bWidth, label: drag.edge === 'left' ? fmtDate(new Date(newStart + 'T00:00:00')) : fmtDate(new Date(newEnd + 'T00:00:00')), mouseX: e.clientX, mouseY: e.clientY });
    };
    const handleMouseUp = () => {
      const drag = dragRef.current;
      if (!drag) return;
      dragRef.current = null;
      document.body.style.cursor = '';
      setDragPreview(null);
      if (drag.curStart !== drag.origStart || drag.curEnd !== drag.origEnd)
        saveResizeRef.current?.(drag.taskId, drag.curStart, drag.curEnd);
    };
    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
    return () => { document.removeEventListener('mousemove', handleMouseMove); document.removeEventListener('mouseup', handleMouseUp); };
  }, []);

  // ── Helpers ──────────────────────────────────────────────────────────────
  const findCol = (name: string) =>
    (dynCols.columns.find(c => c.columnName === name) ?? childDynCols.columns.find(c => c.columnName === name)) as DynColumn | undefined;
  const startCol  = findCol('Inicio');
  const endCol    = findCol('Fin');
  const statusCol = findCol('Estado');
  const colorCol  = dynCols.columns.find(c => c.columnName?.toLowerCase() === 'color');

  const getDateVal = (id: string, col?: DynColumn) =>
    col ? ((dynCols.getCellVal(id, col.id) ?? childDynCols.getCellVal(id, col.id))?.dateValue?.split('T')[0] ?? '') : '';

  const getStatus = (t: Task) => {
    if (statusCol) {
      const c = dynCols.getCellVal(t.id, statusCol.id) ?? childDynCols.getCellVal(t.id, statusCol.id);
      if (c?.textValue) return c.textValue;
    }
    return t.status ?? 'Pendiente';
  };

  const tStart = (t: Task) => localDates.get(t.id)?.start || getDateVal(t.id, startCol) || t.startDate?.split('T')[0] || '';
  const tEnd   = (t: Task) => localDates.get(t.id)?.end   || getDateVal(t.id, endCol)   || t.endDate?.split('T')[0]   || '';

  const getTaskBarColor = (t: Task, fallback: string) => {
    if (colorMode === 'color') {
      const lc = localColors.get(t.id);
      if (lc !== undefined) return lc || fallback;
      const stored = colorCol ? (dynCols.getCellVal(t.id, colorCol.id)?.textValue ?? '') : '';
      return stored || fallback;
    }
    return BOARD_GANTT_STATUS_COLORS[getStatus(t)] ?? fallback;
  };

  const groups        = groupDynCols.columns;
  const getTaskGroupId = (taskId: string) =>
    groups.find(g => groupDynCols.getCellVal(taskId, g.id)?.textValue === '1')?.id ?? null;

  const topLevelWithDates = tasks.filter(t => !t.parentTaskId && tStart(t) && tEnd(t));

  // eslint-disable-next-line react-hooks/exhaustive-deps
  const recentColors = useMemo(() => {
    if (!colorCol) return [];
    const seen = new Set<string>(); const result: string[] = [];
    for (const t of tasks.filter(t => !t.parentTaskId)) {
      const hex = dynCols.getCellVal(t.id, colorCol.id)?.textValue;
      if (hex && !seen.has(hex)) { seen.add(hex); result.push(hex); }
      if (result.length >= 10) break;
    }
    return result;
  }, [tasks, colorCol, dynCols.getCellVal]);

  if (topLevelWithDates.length === 0) return (
    <div className="text-center text-muted-foreground py-16">No hay tareas con fechas de inicio y fin para el Gantt.</div>
  );

  // ── Date math ─────────────────────────────────────────────────────────────
  const allDates  = topLevelWithDates.flatMap(t => [new Date(tStart(t)), new Date(tEnd(t))]);
  const minD      = new Date(Math.min(...allDates.map(d => d.getTime())));
  const maxD      = new Date(Math.max(...allDates.map(d => d.getTime())));
  const padMin    = new Date(minD.getFullYear(), 0, 1);
  const padMax    = new Date(maxD.getFullYear(), 11, 31);
  const totalDays = Math.max(Math.ceil((padMax.getTime() - padMin.getTime()) / 86400000), 1);
  const pxPerDay  = scale === 'days' ? 40 : scale === 'weeks' ? 12 : 4;
  const totalWidth = totalDays * pxPerDay;
  ppdRef.current    = pxPerDay;
  padMinRef.current = padMin;

  const getLeft = (d: string) => Math.max(0, (new Date(d).getTime() - padMin.getTime()) / 86400000 * pxPerDay);
  const getBarW = (s: string, e: string) => Math.max(((new Date(e).getTime() - new Date(s).getTime()) / 86400000 + 1) * pxPerDay, 4);

  // ── Day columns & grid lines ───────────────────────────────────────────────
  const DAY_LABELS = ['D', 'L', 'M', 'X', 'J', 'V', 'S'];
  const dayCols = Array.from({ length: totalDays }, (_, i) => {
    const d = new Date(padMin); d.setDate(d.getDate() + i); d.setHours(0, 0, 0, 0);
    const dow = d.getDay();
    return { idx: i, left: i * pxPerDay, dow, isWeekend: dow === 0 || dow === 6, label: DAY_LABELS[dow], dayNum: d.getDate() };
  });
  const weekendCols = dayCols.filter(d => d.isWeekend);

  const gridLines: { label: string; left: number; isMajor: boolean }[] = [];
  {
    const cur = new Date(padMin);
    if (scale === 'days') {
      cur.setHours(0, 0, 0, 0);
      while (cur <= padMax) {
        const isMonday = cur.getDay() === 1, isFirst = cur.getDate() === 1;
        gridLines.push({ label: isFirst ? cur.toLocaleDateString('es', { day: 'numeric', month: 'short' }) : cur.getDate().toString(), left: (cur.getTime() - padMin.getTime()) / 86400000 * pxPerDay, isMajor: isMonday || isFirst });
        cur.setDate(cur.getDate() + 1);
      }
    } else if (scale === 'weeks') {
      cur.setHours(0, 0, 0, 0);
      while (cur.getDay() !== 1) cur.setDate(cur.getDate() + 1);
      while (cur <= padMax) {
        gridLines.push({ label: cur.toLocaleDateString('es', { day: 'numeric', month: 'short' }), left: (cur.getTime() - padMin.getTime()) / 86400000 * pxPerDay, isMajor: cur.getDate() <= 7 });
        cur.setDate(cur.getDate() + 7);
      }
    } else {
      const mCur = new Date(padMin.getFullYear(), padMin.getMonth(), 1);
      while (mCur <= padMax) {
        gridLines.push({ label: mCur.toLocaleDateString('es', { month: 'short', year: '2-digit' }), left: (mCur.getTime() - padMin.getTime()) / 86400000 * pxPerDay, isMajor: true });
        mCur.setMonth(mCur.getMonth() + 1);
      }
    }
  }

  const todayD    = new Date(); todayD.setHours(0, 0, 0, 0);
  const todayLeft = (todayD.getTime() - padMin.getTime()) / 86400000 * pxPerDay;
  const showToday = todayLeft > 0 && todayLeft < totalWidth;

  // ── Build groups ──────────────────────────────────────────────────────────
  const byGroup = new Map<string, Task[]>();
  byGroup.set('__none__', []);
  for (const g of groups) byGroup.set(g.id, []);
  for (const t of topLevelWithDates) {
    const gid = getTaskGroupId(t.id) ?? '__none__';
    (byGroup.get(gid) ?? byGroup.get('__none__')!).push(t);
  }
  const ganttGroups: BoardGanttGroup[] = [];
  const noneTs = byGroup.get('__none__') ?? [];
  if (noneTs.length > 0) ganttGroups.push({ id: '__none__', name: 'Sin grupo', tasks: noneTs });
  for (const g of groups) {
    const ts = byGroup.get(g.id) ?? [];
    if (ts.length > 0) ganttGroups.push({ id: g.id, name: g.columnName ?? 'Grupo', colorId: g.columnType, tasks: ts });
  }

  // ── Build flat rows array ─────────────────────────────────────────────────
  const flatRows: GanttRow[] = [];
  for (const group of ganttGroups) {
    const groupColor = getGroupColor(group.colorId);
    flatRows.push({ kind: 'group-header', group, groupColor });
    if (!collapsedGroups.has(group.id)) {
      for (const task of group.tasks) {
        flatRows.push({ kind: 'task', task, groupColor });
        tasks.filter(t => t.parentTaskId === task.id && tStart(t) && tEnd(t))
          .forEach(child => flatRows.push({ kind: 'child', task: child, groupColor }));
      }
    }
  }

  // ── Save resize ───────────────────────────────────────────────────────────
  saveResizeRef.current = async (taskId: string, newStart: string, newEnd: string) => {
    const isChild = !!tasks.find(t => t.id === taskId)?.parentTaskId;
    if (startCol && endCol) {
      const effectiveBoardId = isChild ? `${boardId}::children` : boardId;
      (isChild ? childDynCols : dynCols).setCellVal(taskId, startCol.id, { dateValue: newStart + 'T00:00:00' });
      (isChild ? childDynCols : dynCols).setCellVal(taskId, endCol.id,   { dateValue: newEnd   + 'T00:00:00' });
      try {
        await Promise.all([
          saveCellValue({ boardId: effectiveBoardId, rowId: taskId, columnId: startCol.id, dateValue: newStart + 'T00:00:00' }),
          saveCellValue({ boardId: effectiveBoardId, rowId: taskId, columnId: endCol.id,   dateValue: newEnd   + 'T00:00:00' }),
        ]);
        toast.success('Fechas actualizadas');
      } catch { toast.error('Error al guardar fechas'); }
    } else {
      setLocalDates(prev => new Map(prev).set(taskId, { start: newStart, end: newEnd }));
      try {
        await saveTask({ id: taskId, startDate: newStart, endDate: newEnd });
        toast.success('Fechas actualizadas');
      } catch {
        setLocalDates(prev => { const n = new Map(prev); n.delete(taskId); return n; });
        toast.error('Error al guardar fechas');
      }
    }
  };

  const startResize = (e: React.MouseEvent, task: Task, edge: 'left' | 'right') => {
    e.preventDefault(); e.stopPropagation();
    const s = tStart(task), en = tEnd(task);
    if (!s || !en) return;
    dragRef.current = { taskId: task.id, edge, origStart: s, origEnd: en, startX: e.clientX, curStart: s, curEnd: en };
    document.body.style.cursor = 'col-resize';
  };

  const toggleGroup = (id: string) => setCollapsedGroups(p => { const n = new Set(p); n.has(id) ? n.delete(id) : n.add(id); return n; });

  // Auto-scroll to today on first render
  if (!hasScrolledRef.current && scrollRef.current && showToday) {
    hasScrolledRef.current = true;
    requestAnimationFrame(() => scrollRef.current?.scrollTo({ left: Math.max(0, todayLeft - 400) }));
  }

  const headerH = scale !== 'months' ? 48 : 32;

  // ── Shared sub-components (rendered inside each timeline row) ─────────────
  const WeekendShading = () => <>{weekendCols.map(d => (
    <div key={d.idx} className="absolute top-0 bottom-0 pointer-events-none" style={{ left: d.left, width: pxPerDay, background: 'repeating-linear-gradient(135deg, transparent, transparent 3px, hsl(var(--muted)/0.3) 3px, hsl(var(--muted)/0.3) 5px), hsl(var(--muted)/0.7)' }} />
  ))}</>;

  const GridLinesComp = () => <>{gridLines.map((g, i) => (
    <div key={i} className={`absolute top-0 bottom-0 ${g.isMajor ? 'border-l border-border/30' : 'border-l border-border/10'}`} style={{ left: g.left }} />
  ))}</>;

  // ── LEFT column render ────────────────────────────────────────────────────
  const renderLeft = (row: GanttRow) => {
    const h = rowH(row), k = rowKey(row), isHov = hoveredKey === k;

    if (row.kind === 'group-header') {
      const collapsed = collapsedGroups.has(row.group.id);
      return (
        <div key={`l-${k}`}
          style={{ height: h, borderLeft: `3px solid ${row.groupColor}`, background: `color-mix(in srgb, ${row.groupColor} 10%, hsl(var(--card)))` }}
          className="flex items-center gap-2 px-3 border-b border-border/30 cursor-pointer select-none overflow-hidden"
          onClick={() => toggleGroup(row.group.id)}
          onMouseEnter={() => setHoveredKey(k)} onMouseLeave={() => setHoveredKey(null)}>
          {collapsed ? <ChevronRight className="w-3.5 h-3.5 text-muted-foreground flex-shrink-0" /> : <ChevronDown className="w-3.5 h-3.5 text-muted-foreground flex-shrink-0" />}
          <div className="w-2 h-2 rounded-full flex-shrink-0" style={{ background: row.groupColor }} />
          <span className="text-xs font-semibold truncate flex-1" style={{ color: row.groupColor }}>{row.group.name}</span>
          <span className="text-[10px] text-muted-foreground/60 flex-shrink-0">({row.group.tasks.length})</span>
        </div>
      );
    }

    const isChild = row.kind === 'child';
    return (
      <div key={`l-${k}`}
        style={{ height: h, ...(!isChild ? { borderLeft: `3px solid ${row.groupColor}` } : {}) }}
        className={`flex items-center border-b overflow-hidden ${isChild ? 'border-border/10' : 'border-border/20'} ${isHov ? 'bg-muted/20' : 'bg-card'}`}
        onMouseEnter={() => setHoveredKey(k)} onMouseLeave={() => setHoveredKey(null)}>
        {isChild ? (
          <div className="flex items-center gap-1 w-full overflow-hidden" style={{ paddingLeft: 20, paddingRight: 12 }}>
            <CornerDownRight className="w-3 h-3 text-muted-foreground/30 flex-shrink-0" />
            <span className="truncate text-xs text-muted-foreground">{row.task.taskName}</span>
          </div>
        ) : (
          <div className="flex items-center w-full overflow-hidden px-3">
            <span className="truncate text-sm font-medium">{row.task.taskName}</span>
          </div>
        )}
      </div>
    );
  };

  // ── TIMELINE rows render ──────────────────────────────────────────────────
  const renderTimeline = (row: GanttRow) => {
    const h = rowH(row), k = rowKey(row), isHov = hoveredKey === k;

    if (row.kind === 'group-header') {
      return (
        <div key={`tl-${k}`}
          style={{ height: h, position: 'relative', background: `color-mix(in srgb, ${row.groupColor} 5%, transparent)` }}
          className="border-b border-border/30 cursor-pointer"
          onClick={() => toggleGroup(row.group.id)}
          onMouseEnter={() => setHoveredKey(k)} onMouseLeave={() => setHoveredKey(null)}>
          <WeekendShading /><GridLinesComp />
        </div>
      );
    }

    const task = row.task, isChild = row.kind === 'child';
    const s = tStart(task), e = tEnd(task);
    const barColor      = getTaskBarColor(task, row.groupColor);
    const isDragging    = dragPreview?.taskId === task.id;
    const finalLeft     = isDragging ? dragPreview!.bLeft  : (s ? getLeft(s) : 0);
    const finalWidth    = isDragging ? dragPreview!.bWidth : (s && e ? getBarW(s, e) : 0);
    const currentColor  = localColors.has(task.id) ? (localColors.get(task.id) ?? '') : (colorCol ? (dynCols.getCellVal(task.id, colorCol.id)?.textValue ?? '') : '');

    return (
      <div key={`tl-${k}`}
        style={{ height: h, position: 'relative' }}
        className={`border-b ${isChild ? 'border-border/10' : 'border-border/20'} ${isHov ? 'bg-muted/20' : ''}`}
        onMouseEnter={() => setHoveredKey(k)} onMouseLeave={() => setHoveredKey(null)}>
        <WeekendShading />
        <GridLinesComp />
        {s && e && (
          <div className={`absolute ${isChild ? 'top-1 h-5 rounded shadow-sm' : 'top-1.5 h-6 rounded-md shadow-sm'}`}
            style={{ left: finalLeft, width: finalWidth, backgroundColor: barColor, border: `${isChild ? 1 : 1.5}px solid ${barColor}`, userSelect: 'none' }}>
            {/* Left resize */}
            <div className="absolute left-0 top-0 bottom-0 w-3 z-20 cursor-col-resize flex items-center justify-center rounded-l-sm hover:bg-white/20 transition-colors"
              onMouseDown={ev => startResize(ev, task, 'left')}>
              <div className={`w-px ${isChild ? 'h-2.5' : 'h-3'} bg-white/60 rounded-full`} />
            </div>
            {/* Label */}
            <div className="absolute inset-0 flex items-center overflow-hidden pl-3 pr-3 pointer-events-none">
              {!isChild && <div className="w-1.5 h-1.5 rounded-full flex-shrink-0 mr-1" style={{ background: BOARD_GANTT_STATUS_COLORS[getStatus(task)] ?? '#94a3b8' }} />}
              {finalWidth > (isChild ? 60 : 72) && (
                <span className={`text-[10px] text-white truncate leading-none drop-shadow-sm ${!isChild ? 'font-semibold' : ''}`}>{task.taskName}</span>
              )}
            </div>
            {/* Color picker */}
            {colorMode === 'color' && colorCol && !isChild && (
              <BoardGanttBarColorPicker taskId={task.id} boardId={boardId} colorColId={colorCol.id} currentColor={currentColor} recentColors={recentColors} onColorChange={(id, c) => setLocalColors(p => new Map(p).set(id, c))} />
            )}
            {/* Right resize */}
            <div className="absolute right-0 top-0 bottom-0 w-3 z-20 cursor-col-resize flex items-center justify-center rounded-r-sm hover:bg-white/20 transition-colors"
              onMouseDown={ev => startResize(ev, task, 'right')}>
              <div className={`w-px ${isChild ? 'h-2.5' : 'h-3'} bg-white/60 rounded-full`} />
            </div>
          </div>
        )}
        {showToday && <div className="absolute top-0 bottom-0 w-0.5 bg-destructive/60 z-10 pointer-events-none" style={{ left: todayLeft }} />}
      </div>
    );
  };

  // ── RIGHT column render ───────────────────────────────────────────────────
  const renderRight = (row: GanttRow) => {
    const h = rowH(row), k = rowKey(row), isHov = hoveredKey === k;

    if (row.kind === 'group-header') {
      return (
        <div key={`r-${k}`}
          style={{ height: h, background: `color-mix(in srgb, ${row.groupColor} 10%, hsl(var(--card)))` }}
          className="border-b border-border/30" />
      );
    }

    if (row.kind === 'task') {
      const status = getStatus(row.task), color = BOARD_GANTT_STATUS_COLORS[status] ?? '#94a3b8';
      return (
        <div key={`r-${k}`}
          style={{ height: h }}
          className={`flex items-center px-2 border-b border-border/20 ${isHov ? 'bg-muted/20' : 'bg-card'}`}
          onMouseEnter={() => setHoveredKey(k)} onMouseLeave={() => setHoveredKey(null)}>
          <span className="text-xs px-1.5 py-0.5 rounded whitespace-nowrap" style={{ backgroundColor: color + '20', color }}>{status}</span>
        </div>
      );
    }

    // child
    return (
      <div key={`r-${k}`}
        style={{ height: h }}
        className={`border-b border-border/10 ${isHov ? 'bg-muted/10' : 'bg-card'}`}
        onMouseEnter={() => setHoveredKey(k)} onMouseLeave={() => setHoveredKey(null)} />
    );
  };

  // ── JSX ───────────────────────────────────────────────────────────────────
  return (
    <div className="space-y-3">
      {/* Toolbar */}
      <div className="flex items-center justify-between gap-3 flex-wrap">
        <div className="flex items-center gap-2 flex-wrap">
          <span className="text-xs text-muted-foreground font-medium">Escala:</span>
          <div className="flex items-center bg-muted/50 rounded-lg p-0.5 border border-border/40">
            {([{ key: 'days', label: 'Días' }, { key: 'weeks', label: 'Semanas' }, { key: 'months', label: 'Meses' }] as const).map(opt => (
              <button key={opt.key} onClick={() => setScale(opt.key)}
                className={`px-3 py-1 text-xs rounded-md transition-all ${scale === opt.key ? 'bg-primary text-primary-foreground font-semibold shadow-sm' : 'text-muted-foreground hover:text-foreground hover:bg-muted'}`}>
                {opt.label}
              </button>
            ))}
          </div>
          <div className="flex items-center gap-1">
            <button onClick={() => setScale(s => s === 'months' ? 'weeks' : 'days')} className="p-1.5 rounded-md hover:bg-muted text-muted-foreground transition-colors" title="Acercar"><ZoomIn className="w-4 h-4" /></button>
            <button onClick={() => setScale(s => s === 'days' ? 'weeks' : 'months')} className="p-1.5 rounded-md hover:bg-muted text-muted-foreground transition-colors" title="Alejar"><ZoomOut className="w-4 h-4" /></button>
          </div>
          {showToday && (
            <button onClick={() => scrollRef.current?.scrollTo({ left: Math.max(0, todayLeft - 300), behavior: 'smooth' })} className="text-xs text-muted-foreground hover:text-foreground px-2 py-1 rounded-md hover:bg-muted transition-colors">
              📍 Hoy
            </button>
          )}
        </div>
        <div className="flex items-center gap-2">
          <div className="flex items-center bg-muted rounded-lg p-0.5 gap-0.5">
            <button className={`px-2.5 py-1 rounded-md text-xs font-medium transition-colors ${colorMode === 'status' ? 'bg-card text-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'}`} onClick={() => setColorMode('status')}>Estado</button>
            <button className={`px-2.5 py-1 rounded-md text-xs font-medium transition-colors ${colorMode === 'color'  ? 'bg-card text-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'}`} onClick={() => setColorMode('color')}>Color</button>
          </div>
          {colorMode === 'color' && colorCol && <span className="text-xs text-muted-foreground italic">Click en barra para cambiar color</span>}
          {colorMode === 'status' && (
            <div className="hidden sm:flex items-center gap-3">
              {Object.entries(BOARD_GANTT_STATUS_COLORS).map(([s, c]) => (
                <div key={s} className="flex items-center gap-1">
                  <div className="w-2 h-2 rounded-full" style={{ background: c }} />
                  <span className="text-[10px] text-muted-foreground">{s}</span>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Board — 3 separate zones, only the middle scrolls horizontally */}
      <div className="border rounded-xl overflow-hidden bg-card">
        <div className="flex">

          {/* ── LEFT: task names — never moves horizontally ── */}
          <div className="w-52 flex-shrink-0 bg-card border-r border-border" style={{ zIndex: 30 }}>
            <div style={{ height: headerH }} className="flex items-center px-3 border-b border-border bg-muted/50 text-xs font-semibold">
              Tarea
            </div>
            {flatRows.map(renderLeft)}
          </div>

          {/* ── MIDDLE: timeline — only this section scrolls horizontally ── */}
          <div ref={scrollRef} className="flex-1 overflow-x-auto">
            <div style={{ width: totalWidth }}>
              {/* Timeline header */}
              <div style={{ height: headerH, position: 'relative' }} className="border-b border-border bg-muted/50">
                <WeekendShading />
                {gridLines.map((g, i) => (
                  <span key={i}
                    className={`absolute text-xs whitespace-nowrap ${scale !== 'months' ? 'top-1' : 'top-1/2 -translate-y-1/2'} ${g.isMajor ? 'text-foreground/70 font-medium' : 'text-muted-foreground/50'}`}
                    style={{ left: g.left + 4 }}>
                    {g.label}
                  </span>
                ))}
                {scale !== 'months' && dayCols.map(d => (
                  <div key={d.idx} className="absolute bottom-0 flex flex-col items-center justify-center overflow-hidden"
                    style={{ left: d.left, width: pxPerDay, height: scale === 'days' ? 22 : 14 }}>
                    {scale === 'days' ? (
                      <>
                        <span className={`text-[9px] font-medium leading-none ${d.isWeekend ? 'text-destructive/60' : 'text-muted-foreground/50'}`}>{d.label}</span>
                        <span className={`text-[9px] leading-none mt-0.5 ${d.isWeekend ? 'text-destructive/60' : 'text-muted-foreground/50'}`}>{d.dayNum}</span>
                      </>
                    ) : (
                      <span className={`text-[8px] leading-none ${d.isWeekend ? 'text-destructive/60' : 'text-muted-foreground/50'}`}>{d.label}</span>
                    )}
                  </div>
                ))}
              </div>
              {/* Timeline rows */}
              {flatRows.map(renderTimeline)}
            </div>
          </div>

          {/* ── RIGHT: status badges — never moves horizontally ── */}
          <div className="w-24 flex-shrink-0 bg-card border-l border-border" style={{ zIndex: 30 }}>
            <div style={{ height: headerH }} className="flex items-center px-2 border-b border-border bg-muted/50 text-xs font-semibold">
              Estado
            </div>
            {flatRows.map(renderRight)}
          </div>

        </div>
      </div>

      {/* Drag preview tooltip */}
      {dragPreview && (
        <div className="fixed z-[300] bg-foreground text-background text-xs font-semibold px-2.5 py-1 rounded-lg shadow-xl pointer-events-none"
          style={{ left: dragPreview.mouseX + 14, top: dragPreview.mouseY - 10 }}>
          {dragPreview.label}
        </div>
      )}
    </div>
  );
}

src/hooks/useDocumentChannel.ts.content:
import { useEffect, useRef, useCallback, useState } from 'react';
import { getAblyToken } from 'zite-endpoints-sdk';

export type DocChannelStatus = 'connecting' | 'connected' | 'error' | 'disabled';

interface UseDocumentChannelOptions {
  docId: string | null;
  myUserId: string;
  onBlockLock?: (data: any) => void;
  onBlockUnlock?: (data: any) => void;
  onBlockLockHeartbeat?: (data: any) => void;
  onBlockUpdate?: (data: any) => void;
  onStructureChanged?: (data: any) => void;
  onReload?: (data: any) => void;
  enabled?: boolean;
}

export function useDocumentChannel({
  docId,
  myUserId,
  onBlockLock,
  onBlockUnlock,
  onBlockLockHeartbeat,
  onBlockUpdate,
  onStructureChanged,
  onReload,
  enabled = true,
}: UseDocumentChannelOptions): { status: DocChannelStatus } {
  const [status, setStatus] = useState<DocChannelStatus>('disabled');
  const eventSourceRef  = useRef<EventSource | null>(null);
  const tokenRef        = useRef<{ token: string; expires: number } | null>(null);
  const retryTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Stable callback refs
  const cbRef = useRef({ onBlockLock, onBlockUnlock, onBlockLockHeartbeat, onBlockUpdate, onStructureChanged, onReload, myUserId });
  cbRef.current = { onBlockLock, onBlockUnlock, onBlockLockHeartbeat, onBlockUpdate, onStructureChanged, onReload, myUserId };

  const cleanup = useCallback(() => {
    if (eventSourceRef.current) {
      eventSourceRef.current.close();
      eventSourceRef.current = null;
    }
    if (retryTimeoutRef.current) {
      clearTimeout(retryTimeoutRef.current);
      retryTimeoutRef.current = null;
    }
  }, []);

  useEffect(() => {
    if (!enabled || !docId) {
      cleanup();
      setStatus('disabled');
      return;
    }

    let cancelled = false;
    const ablyChannel = `doc:${docId}`;

    const connect = async () => {
      setStatus('connecting');

      const now = Math.floor(Date.now() / 1000);
      if (!tokenRef.current || tokenRef.current.expires - now < 300) {
        try {
          const res = await getAblyToken({ channels: [ablyChannel] });
          if (res.token && res.expires) {
            tokenRef.current = { token: res.token, expires: res.expires };
          } else {
            setStatus('error');
            if (!cancelled) retryTimeoutRef.current = setTimeout(connect, 10000);
            return;
          }
        } catch {
          setStatus('error');
          if (!cancelled) retryTimeoutRef.current = setTimeout(connect, 10000);
          return;
        }
      }

      if (cancelled) return;

      const sseUrl = `https://realtime.ably.io/sse?channels=${encodeURIComponent(ablyChannel)}&accessToken=${encodeURIComponent(tokenRef.current!.token)}&v=1.2`;
      const es = new EventSource(sseUrl);
      eventSourceRef.current = es;

      es.onopen = () => {
        if (!cancelled) setStatus('connected');
      };

      es.onmessage = (event) => {
        try {
          const parsed = JSON.parse(event.data);
          const data = typeof parsed.data === 'string' ? JSON.parse(parsed.data) : parsed.data;
          if (!data) return;

          // Ignore own events
          if (data.userId === cbRef.current.myUserId) return;

          switch (parsed.name) {
            case 'block.lock':            cbRef.current.onBlockLock?.(data); break;
            case 'block.unlock':          cbRef.current.onBlockUnlock?.(data); break;
            case 'block.lock_heartbeat':  cbRef.current.onBlockLockHeartbeat?.(data); break;
            case 'block.update':          cbRef.current.onBlockUpdate?.(data); break;
            case 'doc.structure_changed': cbRef.current.onStructureChanged?.(data); break;
            case 'doc.reload':            cbRef.current.onReload?.(data); break;
          }
        } catch { /* ignore malformed */ }
      };

      es.onerror = () => {
        if (!cancelled) {
          setStatus('error');
          es.close();
          eventSourceRef.current = null;
          tokenRef.current = null;
          retryTimeoutRef.current = setTimeout(connect, 3000);
        }
      };
    };

    connect();

    return () => {
      cancelled = true;
      cleanup();
      setStatus('disabled');
    };
  }, [docId, enabled, cleanup]);

  return { status };
}

src/hooks/useProjectPresence.ts.content:
import { useEffect, useRef, useCallback, useState } from 'react';
import { updatePresence, getPresence, publishPresenceEvent } from 'zite-endpoints-sdk';
import { getCachedAblyToken, invalidateAblyToken } from '../lib/ablyTokenCache';

export type PresenceMember = {
  email: string;
  name?: string;
  profilePhoto?: string;
  pageName?: string;
};

type UseProjectPresenceOptions = {
  projectCode: string | null;
  pageName: string;
  enabled: boolean;
  user?: {
    email?: string;
    firstName?: string;
    lastName?: string;
    profilePhoto?: string;
  };
};

export function useProjectPresence({
  projectCode,
  pageName,
  enabled,
  user,
}: UseProjectPresenceOptions) {
  const [members, setMembers] = useState<PresenceMember[]>([]);

  const lastPublishRef    = useRef<number>(0);
  const eventSourceRef    = useRef<EventSource | null>(null);
  const tokenRef          = useRef<{ token: string; expires: number } | null>(null);
  const retryTimeoutRef   = useRef<ReturnType<typeof setTimeout> | null>(null);
  const heartbeatRef      = useRef<ReturnType<typeof setInterval> | null>(null);
  const pollRef           = useRef<ReturnType<typeof setInterval> | null>(null);
  // Cache name+photo from real-time events so polls can enrich presence
  const profileCacheRef   = useRef<Map<string, { name?: string; profilePhoto?: string }>>(new Map());

  const myEmail      = user?.email;
  const name         = user ? (`${user.firstName ?? ''} ${user.lastName ?? ''}`.trim() || user.email) : undefined;
  const profilePhoto = user?.profilePhoto;

  const sseCleanup = useCallback(() => {
    eventSourceRef.current?.close();
    eventSourceRef.current = null;
    if (retryTimeoutRef.current) { clearTimeout(retryTimeoutRef.current); retryTimeoutRef.current = null; }
  }, []);

  useEffect(() => {
    if (!enabled || !projectCode || !myEmail) {
      sseCleanup();
      setMembers([]);
      return;
    }

    const activeChannel = `project:${projectCode}:${pageName}`;
    const ablyChannel   = `board:${projectCode}`;
    let cancelled = false;

    // ── Publish own presence (updatePresence + publishPresenceEvent) ──────────
    const publishPresence = async () => {
      const now = Date.now();
      const isFirst = lastPublishRef.current === 0;
      if (!isFirst && now - lastPublishRef.current < 60000) return;

      try { await updatePresence({ activeChannel }); } catch { /* silent */ }
      try {
        await publishPresenceEvent({
          projectCode,
          pageName,
          activeChannel,
          name: name || undefined,
          profilePhoto: profilePhoto || undefined,
        });
        lastPublishRef.current = Date.now();
      } catch (err) {
        console.warn('[presence] publishPresenceEvent failed (rate limit?)', err);
      }
    };

    // ── Fetch full presence snapshot from DB and merge with profile cache ─────
    const fetchAndSetPresence = async () => {
      try {
        const data = await getPresence({});
        const prefix   = `project:${projectCode}:`;
        const filtered = data.users.filter(u => u.email !== myEmail && u.activeChannel?.startsWith(prefix));
        setMembers(filtered.map(u => {
          const cached   = profileCacheRef.current.get(u.email);
          const pg       = (u.activeChannel ?? '').slice(prefix.length);
          // Prefer SSE cache (most recent), fall back to DB fields from poll
          const fullName = cached?.name
            ?? ([u.firstName, u.lastName].filter(Boolean).join(' ').trim() || undefined);
          const photo    = cached?.profilePhoto ?? u.profilePhoto ?? undefined;
          return { email: u.email, name: fullName, profilePhoto: photo, pageName: pg };
        }));
      } catch { /* silent */ }
    };

    // ── SSE connection — shares Ably token with useRealtimeBoardEvents ────────
    // Both hooks connect to the same board:{projectCode} channel. Using the
    // shared token cache ensures only one getAblyToken request fires even if
    // both hooks connect simultaneously.
    const connect = async () => {
      const now = Math.floor(Date.now() / 1000);
      if (!tokenRef.current || tokenRef.current.expires - now < 300) {
        const tokenResult = await getCachedAblyToken(ablyChannel);
        if (tokenResult) {
          tokenRef.current = tokenResult;
        } else {
          if (!cancelled) retryTimeoutRef.current = setTimeout(connect, 10000);
          return;
        }
      }
      if (cancelled) return;

      const sseUrl = `https://realtime.ably.io/sse?channels=${encodeURIComponent(ablyChannel)}&accessToken=${encodeURIComponent(tokenRef.current!.token)}&v=1.2`;
      const es = new EventSource(sseUrl);
      eventSourceRef.current = es;

      es.onmessage = (event) => {
        try {
          const parsed = JSON.parse(event.data);
          if (parsed.name !== 'user.presence') return;

          const data: {
            email: string;
            name?: string;
            profilePhoto?: string;
            pageName?: string;
            projectCode?: string;
            activeChannel?: string;
          } = typeof parsed.data === 'string' ? JSON.parse(parsed.data) : parsed.data;

          if (!data.email || data.email === myEmail) return;
          if (data.projectCode !== projectCode) return;

          // Cache profile info for future poll merges
          profileCacheRef.current.set(data.email, { name: data.name, profilePhoto: data.profilePhoto });

          setMembers(prev => {
            const others = prev.filter(m => m.email !== data.email);
            return [...others, {
              email: data.email,
              name: data.name,
              profilePhoto: data.profilePhoto,
              pageName: data.pageName,
            }];
          });
        } catch { /* ignore malformed events */ }
      };

      es.onerror = () => {
        if (!cancelled) {
          es.close();
          eventSourceRef.current = null;
          // Invalidate shared cache so next connect fetches a fresh token
          invalidateAblyToken(ablyChannel);
          tokenRef.current = null;
          retryTimeoutRef.current = setTimeout(connect, 3000);
        }
      };
    };

    // Initial publish + fetch, then connect SSE
    publishPresence();
    fetchAndSetPresence();
    connect();

    // Heartbeat every 120s to keep presence alive
    heartbeatRef.current = setInterval(() => { if (document.visibilityState === 'visible') publishPresence(); }, 300000);

    // Full state poll every 3 min as fallback (SSE handles real-time updates)
    pollRef.current = setInterval(() => { if (document.visibilityState === 'visible') fetchAndSetPresence(); }, 600000);

    return () => {
      cancelled = true;
      sseCleanup();
      if (heartbeatRef.current) { clearInterval(heartbeatRef.current); heartbeatRef.current = null; }
      if (pollRef.current)      { clearInterval(pollRef.current);      pollRef.current = null; }
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projectCode, pageName, enabled, myEmail, name, profilePhoto]);

  return { members, count: members.length };
}

src/hooks/useRealtimeChannel.ts.content:
import { useEffect, useRef, useCallback, useState } from 'react';
import { getAblyToken } from 'zite-endpoints-sdk';

type RealtimeMessage = {
  id: string;
  channel?: string;
  content?: string;
  senderName?: string;
  senderEmail?: string;
  sentAt?: string;
  parentMessageId?: string;
  reactions?: string;
  pinned?: boolean;
  attachments?: string;
};

type ReactionPayload = { messageId: string; channel: string; reactions: string };
type PinnedPayload   = { messageId: string; channel: string; pinned: boolean };
type PollPayload     = { messageId: string; channel: string; content: string };
export type TypingPayload = { channel: string; userEmail: string; userName: string; sentAt: string };

type UseRealtimeChannelOptions = {
  channel: string;
  onMessageCreated?: (msg: RealtimeMessage) => void;
  onReactionUpdated?: (payload: ReactionPayload) => void;
  onMessagePinned?:   (payload: PinnedPayload)   => void;
  onPollUpdated?:     (payload: PollPayload)      => void;
  onTyping?:          (payload: TypingPayload)    => void;
  enabled?: boolean;
};

export type RealtimeStatus = 'connecting' | 'connected' | 'error' | 'disabled';

export function useRealtimeChannel({
  channel,
  onMessageCreated,
  onReactionUpdated,
  onMessagePinned,
  onPollUpdated,
  onTyping,
  enabled = true,
}: UseRealtimeChannelOptions): { status: RealtimeStatus } {
  const callbackRef  = useRef(onMessageCreated);
  const reactionRef  = useRef(onReactionUpdated);
  const pinnedRef    = useRef(onMessagePinned);
  const pollRef      = useRef(onPollUpdated);
  const typingRef    = useRef(onTyping);

  callbackRef.current  = onMessageCreated;
  reactionRef.current  = onReactionUpdated;
  pinnedRef.current    = onMessagePinned;
  pollRef.current      = onPollUpdated;
  typingRef.current    = onTyping;

  const [status, setStatus] = useState<RealtimeStatus>('disabled');
  const eventSourceRef   = useRef<EventSource | null>(null);
  const tokenRef         = useRef<{ token: string; expires: number } | null>(null);
  const retryTimeoutRef  = useRef<ReturnType<typeof setTimeout> | null>(null);

  const cleanup = useCallback(() => {
    if (eventSourceRef.current) {
      eventSourceRef.current.close();
      eventSourceRef.current = null;
    }
    if (retryTimeoutRef.current) {
      clearTimeout(retryTimeoutRef.current);
      retryTimeoutRef.current = null;
    }
  }, []);

  useEffect(() => {
    if (!enabled || !channel) {
      cleanup();
      setStatus('disabled');
      return;
    }

    let cancelled = false;

    const connect = async () => {
      setStatus('connecting');
      console.log('[ably][sse connecting]', { channel, ablyChannel: `chat:${channel}` });

      // Get or refresh token
      const now = Math.floor(Date.now() / 1000);
      if (!tokenRef.current || tokenRef.current.expires - now < 300) {
        try {
          const ablyChannel = `chat:${channel}`;
          const res = await getAblyToken({ channels: [ablyChannel] });
          if (res.token && res.expires) {
            tokenRef.current = { token: res.token, expires: res.expires };
            console.log('[ably][token ok]', { channel, expiresIn: res.expires - now });
          } else {
            console.warn('[ably][token failed]', { channel, error: res.error ?? 'no token returned' });
            setStatus('error');
            if (!cancelled) {
              retryTimeoutRef.current = setTimeout(connect, 10000);
            }
            return;
          }
        } catch (err) {
          console.warn('[ably][token error]', { channel, error: (err as Error).message });
          setStatus('error');
          if (!cancelled) {
            retryTimeoutRef.current = setTimeout(connect, 10000);
          }
          return;
        }
      }

      if (cancelled) return;

      const ablyChannel = `chat:${channel}`;
      const sseUrl = `https://realtime.ably.io/sse?channels=${encodeURIComponent(ablyChannel)}&accessToken=${encodeURIComponent(tokenRef.current!.token)}&v=1.2`;

      const es = new EventSource(sseUrl);
      eventSourceRef.current = es;

      es.onopen = () => {
        if (!cancelled) {
          setStatus('connected');
          console.log('[ably][sse connected] ✓', { channel, ablyChannel });
        }
      };

      es.onmessage = (event) => {
        console.log('[ably][raw event]', { channel, data: event.data?.slice?.(0, 300) });
        try {
          const parsed = JSON.parse(event.data);

          if (parsed.name === 'message.created' && parsed.data) {
            const msg: RealtimeMessage = typeof parsed.data === 'string' ? JSON.parse(parsed.data) : parsed.data;
            console.log('[ably][event received]', { name: parsed.name, id: msg.id, channel: msg.channel });
            callbackRef.current?.(msg);
          }

          if (parsed.name === 'reaction.updated' && parsed.data) {
            const payload: ReactionPayload = typeof parsed.data === 'string' ? JSON.parse(parsed.data) : parsed.data;
            console.log('[ably][received reaction.updated]', payload);
            reactionRef.current?.(payload);
          }

          if (parsed.name === 'message.pinned' && parsed.data) {
            const payload: PinnedPayload = typeof parsed.data === 'string' ? JSON.parse(parsed.data) : parsed.data;
            console.log('[ably][received message.pinned]', payload);
            pinnedRef.current?.(payload);
          }

          if (parsed.name === 'poll.updated' && parsed.data) {
            const payload: PollPayload = typeof parsed.data === 'string' ? JSON.parse(parsed.data) : parsed.data;
            console.log('[ably][received poll.updated]', payload);
            pollRef.current?.(payload);
          }

          if (parsed.name === 'typing' && parsed.data) {
            const payload: TypingPayload = typeof parsed.data === 'string' ? JSON.parse(parsed.data) : parsed.data;
            typingRef.current?.(payload);
          }
        } catch {
          // Ignore malformed events
        }
      };

      es.onerror = () => {
        console.warn('[ably][sse error]', { channel, ablyChannel, readyState: es.readyState });
        if (!cancelled) {
          setStatus('error');
          es.close();
          eventSourceRef.current = null;
          tokenRef.current = null; // Force re-fetch
          retryTimeoutRef.current = setTimeout(connect, 3000);
        }
      };
    };

    connect();

    // Refresh token before expiry (every 50 minutes)
    const tokenRefreshInterval = setInterval(() => {
      if (!cancelled && tokenRef.current) {
        const now = Math.floor(Date.now() / 1000);
        if (tokenRef.current.expires - now < 600) {
          cleanup();
          tokenRef.current = null;
          connect();
        }
      }
    }, 50 * 60 * 1000);

    return () => {
      cancelled = true;
      clearInterval(tokenRefreshInterval);
      cleanup();
      setStatus('disabled');
      console.log('[ably][sse disconnected]', { channel });
    };
  }, [channel, enabled, cleanup]);

  return { status };
}

src/api/backfillExchangeRates.ts.content:
import { z } from 'zod';
import { createEndpoint, Deals } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Backfill exchange rates for USD deals missing exchangeRate',
  inputSchema: z.object({}),
  outputSchema: z.object({
    updated: z.number(),
    skipped: z.number(),
    rates: z.array(z.object({ date: z.string(), rate: z.number(), dealCount: z.number() })),
  }),
  execute: async () => {
    // Fetch all USD deals without exchangeRate
    const { records: allUsd } = await Deals.findAll({
      filters: { currency: { contains: 'USD' } },
      limit: 2000,
    });
    const missing = allUsd.filter(d => !d.exchangeRate);
    if (missing.length === 0) return { updated: 0, skipped: 0, rates: [] };

    // Group by date
    const byDate = new Map<string, typeof missing>();
    for (const deal of missing) {
      const date = deal.approvalDate || new Date().toISOString().slice(0, 10);
      const arr = byDate.get(date) || [];
      arr.push(deal);
      byDate.set(date, arr);
    }

    // Fetch rates per unique date
    const rateCache = new Map<string, number>();
    for (const date of byDate.keys()) {
      let rate: number | null = null;
      try {
        const res = await fetch(`https://cdn.jsdelivr.net/npm/@fawazahmed0/currency-api@${date}/v1/currencies/usd.json`);
        if (res.ok) {
          const json = await res.json() as { usd?: { mxn?: number } };
          if (json.usd?.mxn) rate = json.usd.mxn;
        }
      } catch {}
      if (!rate) {
        try {
          const res = await fetch('https://cdn.jsdelivr.net/npm/@fawazahmed0/currency-api@latest/v1/currencies/usd.json');
          if (res.ok) {
            const json = await res.json() as { usd?: { mxn?: number } };
            if (json.usd?.mxn) rate = json.usd.mxn;
          }
        } catch {}
      }
      if (rate) rateCache.set(date, rate);
    }

    let updated = 0;
    let skipped = 0;
    const ratesOut: { date: string; rate: number; dealCount: number }[] = [];

    for (const [date, deals] of byDate.entries()) {
      const rate = rateCache.get(date);
      if (!rate) { skipped += deals.length; continue; }
      ratesOut.push({ date, rate, dealCount: deals.length });
      for (const deal of deals) {
        await Deals.update({ id: deal.id, record: { exchangeRate: rate } });
        updated++;
      }
    }

    return { updated, skipped, rates: ratesOut };
  },
});

src/api/fixOrphanedCellValues.ts.content:
import { z } from 'zod';
import { createEndpoint, CellValues } from 'zite-integrations-backend-sdk';

const sleep = (ms: number) => new Promise(r => setTimeout(r, ms));

/**
 * Repairs CellValues whose boardId embeds an old project code.
 * Runs in pages of 200, up to maxPages iterations per prefix, so it won't timeout.
 * Call repeatedly until done = true.
 */
export default createEndpoint({
  authenticated: true,
  description: 'Repair orphaned CellValues boardIds for a given old→new project code mapping. Returns { done, fixedThisRun, totalFixed } — call repeatedly until done=true.',
  inputSchema: z.object({
    oldCode: z.string(),
    newCode: z.string(),
    maxPages: z.number().optional(), // pages of 200 per call, default 10
  }),
  outputSchema: z.object({
    done: z.boolean(),
    fixedThisRun: z.number(),
    remainingEstimate: z.number(),
  }),
  execute: async ({ input }) => {
    const { oldCode, newCode, maxPages = 10 } = input;
    const escaped = oldCode.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const prefixes = [`pm-${oldCode}-`, `cal-${oldCode}-`, `recruitment-${oldCode}-`];
    const pageSize = 200;
    let fixedThisRun = 0;
    let remainingEstimate = 0;
    let allDone = true;

    for (const prefix of prefixes) {
      let pages = 0;
      while (pages < maxPages) {
        const { records, hasMore } = await CellValues.findAll({
          filters: { boardId: { contains: prefix } } as any,
          limit: pageSize, offset: 0, // Always offset 0 — we update them so next call gets fresh ones
          fields: ['id', 'boardId'],
        });

        if (records.length === 0) break;

        // Update in chunks of 15
        for (let i = 0; i < records.length; i += 15) {
          const chunk = records.slice(i, i + 15);
          await Promise.all(chunk.map(r => {
            const newBoardId = (r.boardId ?? '').replace(
              new RegExp(`(pm|cal|recruitment)-${escaped}-`),
              `$1-${newCode}-`
            );
            return CellValues.update({ id: r.id, record: { boardId: newBoardId } } as any);
          }));
          await sleep(150);
        }

        fixedThisRun += records.length;
        pages++;

        if (!hasMore) break;

        // If still more after maxPages, mark as not done
        if (pages >= maxPages && hasMore) {
          allDone = false;
          remainingEstimate += 999; // estimate
        }

        await sleep(200);
      }
    }

    return { done: allDone, fixedThisRun, remainingEstimate };
  },
});

src/api/generateSupplierToken.ts.content:
import { z } from 'zod';
import { createEndpoint, Suppliers } from 'zite-integrations-backend-sdk';

function randomAlphanumeric(length: number): string {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789';
  let result = '';
  for (let i = 0; i < length; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
}

function generateUUID(): string {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

export default createEndpoint({
  description: 'Generate or regenerate portal access token and password for a supplier',
  authenticated: true,
  inputSchema: z.object({ supplierId: z.string() }),
  outputSchema: z.object({
    token: z.string(),
    password: z.string(),
    portalUrl: z.string(),
  }),
  execute: async ({ input }) => {
    const token = generateUUID();
    const password = randomAlphanumeric(8);
    const appUrl = process.env.ZITE_APP_URL ?? '';

    await Suppliers.update({
      id: input.supplierId,
      record: { accessToken: token, portalPassword: password },
    });

    return {
      token,
      password,
      portalUrl: `${appUrl}/portal/${token}`,
    };
  },
});

src/api/getLinkedParticipants.ts.content:
import { z } from 'zod';
import { createEndpoint, RecruitmentRows } from 'zite-integrations-backend-sdk';

const participantSchema = z.object({
  id: z.string(),
  rowName: z.string().optional(),
  participantName: z.string().optional(),
  email: z.string().optional(),
  phone: z.string().optional(),
  status: z.string().optional(),
  cellData: z.string().optional(),
  rowOrder: z.number().optional(),
});

export default createEndpoint({
  authenticated: true,
  description: 'Get participants belonging to a specific recruitment group (groupColumnId) within a board',
  inputSchema: z.object({
    projectCode: z.string(),
    boardName: z.string(),
    groupColumnId: z.string(),
  }),
  outputSchema: z.object({
    participants: z.array(participantSchema),
  }),
  execute: async ({ input }) => {
    const { projectCode, boardName, groupColumnId } = input;

    const allRows: z.infer<typeof participantSchema>[] = [];
    let offset = 0;

    while (true) {
      const { records, hasMore } = await RecruitmentRows.findAll({
        filters: { projectCode, boardName, group: groupColumnId },
        limit: 500,
        offset,
      });

      const active = records.filter(r => !r.deletedAt);
      allRows.push(
        ...active.map(r => ({
          id: r.id,
          rowName: r.rowName,
          participantName: r.participantName,
          email: r.email,
          phone: r.phone,
          status: r.status,
          cellData: r.cellData,
          rowOrder: r.rowOrder,
        }))
      );

      if (!hasMore || records.length === 0) break;
      offset += records.length;
    }

    // Sort by rowOrder
    allRows.sort((a, b) => (a.rowOrder ?? 0) - (b.rowOrder ?? 0));

    return { participants: allRows };
  },
});

src/api/getSupplierPortalData.ts.content:
import { z } from 'zod';
import { createEndpoint, Suppliers, PurchaseOrders, SupplierInvoices, Payments, PoAuditLog } from 'zite-integrations-backend-sdk';

const poSchema = z.object({
  id: z.string(),
  poNumber: z.any().optional(),
  serviceDescription: z.string().optional(),
  totalAmount: z.number().optional(),
  currency: z.string().optional(),
  issueDate: z.string().optional(),
  status: z.string().optional(),
  category: z.string().optional(),
  projectCode: z.string().optional(),
  paymentTerms: z.string().optional(),
  pdfUrl: z.string().optional(),
  pdfBase64: z.string().optional(),
  pdfFile: z.array(z.object({ url: z.string() })).optional(),
  cancellationReason: z.string().optional(),
  // Embedded invoice (latest for this PO)
  invoiceId: z.string().optional(),
  invoiceNumber: z.string().optional(),
  invoiceAmount: z.number().optional(),
  invoiceCurrency: z.string().optional(),
  invoiceStatus: z.string().optional(),
  invoiceUploadDate: z.string().optional(),
  invoiceReviewNotes: z.string().optional(),
  invoiceSubtotal: z.number().optional(),
  invoiceIvaRate: z.number().optional(),
  invoiceIvaAmount: z.number().optional(),
  invoiceRetencionIva: z.number().optional(),
  invoiceRetencionIsr: z.number().optional(),
});

const paymentSchema = z.object({
  id: z.string(),
  paymentId: z.any().optional(),
  amount: z.number().optional(),
  currency: z.string().optional(),
  dueDate: z.string().optional(),
  paymentDate: z.string().optional(),
  status: z.string().optional(),
  method: z.string().optional(),
  poNumber: z.string().optional(),
  reference: z.string().optional(),
  attachment: z.array(z.object({ url: z.string() })).optional(),
});

export default createEndpoint({
  description: 'Get supplier portal data (public endpoint, validated by token + password)',
  inputSchema: z.object({ token: z.string(), password: z.string() }),
  outputSchema: z.object({
    supplier: z.object({ id: z.string(), name: z.string(), email: z.string().optional() }),
    purchaseOrders: z.array(poSchema),
    payments: z.array(paymentSchema),
  }),
  execute: async ({ input }) => {
    const supplier = await Suppliers.findOne({ filters: { accessToken: input.token } });
    if (!supplier) throw new Error('Token de acceso inválido.');
    if (supplier.portalPassword !== input.password) throw new Error('Clave de acceso incorrecta.');

    const [posResult, invResult, paymentsResult] = await Promise.all([
      PurchaseOrders.findAll({
        filters: { supplierName: supplier.supplierName },
        limit: 500,
      }),
      SupplierInvoices.findAll({ filters: { supplierId: supplier.id }, limit: 500 }),
      Payments.findAll({ filters: { supplierName: supplier.supplierName }, limit: 500 }),
    ]);

    // Show POs that have both a PDF generated AND an email sent, OR are cancelled (were previously sent)
    const visiblePos = posResult.records.filter(p =>
      (p.pdfUrl || p.pdfBase64 || (p.pdfFile && p.pdfFile.length > 0)) && p.emailSentAt
    );

    // Build PO number map
    const poMap: Record<string, string> = {};
    posResult.records.forEach(p => { poMap[p.id] = String(p.poNumber ?? ''); });

    // Group invoices by poId, keep only the latest per PO
    const latestInvByPo: Record<string, typeof invResult.records[0]> = {};
    invResult.records.forEach(inv => {
      if (!inv.poId) return;
      const existing = latestInvByPo[inv.poId];
      if (!existing) {
        latestInvByPo[inv.poId] = inv;
      } else {
        const existingDate = existing.uploadDate ?? '';
        const newDate = inv.uploadDate ?? '';
        if (newDate > existingDate) latestInvByPo[inv.poId] = inv;
      }
    });

    // Fetch cancellation reasons for cancelled POs
    const cancelledPoIds = visiblePos.filter(p => p.status === 'Cancelada').map(p => p.id);
    const cancelReasonByPoId: Record<string, string> = {};
    if (cancelledPoIds.length > 0) {
      const auditResult = await PoAuditLog.findAll({ filters: { action: 'Cancelada' }, limit: 500 });
      auditResult.records.forEach(log => {
        const poId = Array.isArray(log.purchaseOrder) ? log.purchaseOrder[0] : log.purchaseOrder;
        if (poId && cancelledPoIds.includes(poId) && log.comments && !cancelReasonByPoId[poId]) {
          cancelReasonByPoId[poId] = log.comments;
        }
      });
    }

    return {
      supplier: { id: supplier.id, name: supplier.supplierName ?? '', email: supplier.email },
      purchaseOrders: visiblePos.map(p => {
        const inv = latestInvByPo[p.id];
        return {
          id: p.id,
          poNumber: p.poNumber,
          serviceDescription: p.serviceDescription,
          totalAmount: p.totalAmount,
          currency: p.currency,
          issueDate: p.issueDate,
          status: p.status,
          category: p.category,
          projectCode: p.projectCode,
          paymentTerms: p.paymentTerms,
          pdfUrl: p.pdfUrl,
          pdfBase64: p.pdfBase64,
          pdfFile: p.pdfFile,
          cancellationReason: p.status === 'Cancelada' ? cancelReasonByPoId[p.id] : undefined,
          invoiceId: inv?.id,
          invoiceNumber: inv?.invoiceNumber,
          invoiceAmount: inv?.amount,
          invoiceCurrency: inv?.currency,
          invoiceStatus: inv?.status,
          invoiceUploadDate: inv?.uploadDate,
          invoiceReviewNotes: inv?.reviewNotes,
          invoiceSubtotal: inv?.subtotal,
          invoiceIvaRate: inv?.ivaRate,
          invoiceIvaAmount: inv?.ivaAmount,
          invoiceRetencionIva: inv?.retencionIva,
          invoiceRetencionIsr: inv?.retencionIsr,
        };
      }),
      payments: paymentsResult.records.map(p => ({
        id: p.id,
        paymentId: p.paymentId,
        amount: p.amount,
        currency: p.currency,
        dueDate: p.dueDate,
        paymentDate: p.paymentDate,
        status: p.status,
        method: p.method,
        poNumber: p.poId ? poMap[p.poId] : undefined,
        reference: p.reference,
        attachment: p.attachment,
      })),
    };
  },
});

src/api/reviewSupplierInvoice.ts.content:
import { z } from 'zod';
import { createEndpoint, SupplierInvoices, Payments, Suppliers } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Validate or reject a supplier invoice. When validating, auto-creates a scheduled payment. When rejecting, notifies the supplier by email.',
  authenticated: true,
  inputSchema: z.object({
    invoiceId: z.string(),
    action: z.enum(['validar', 'rechazar']),
    notes: z.string().optional(),
    scheduledPaymentDate: z.string().optional(), // ISO date string, required when action = 'validar'
    // Validated tax breakdown (editable by reviewer before approving)
    validatedSubtotal: z.number().optional(),
    validatedIvaRate: z.number().optional(),
    validatedIvaAmount: z.number().optional(),
    validatedRetencionIva: z.number().optional(),
    validatedRetencionIsr: z.number().optional(),
    validatedTotal: z.number().optional(),
  }),
  outputSchema: z.object({ success: z.boolean(), paymentId: z.string().optional(), emailSent: z.boolean().optional() }),
  execute: async ({ input, context }) => {
    const status = input.action === 'validar' ? 'Validada' : 'Rechazada';

    // Build the record update — include validated tax breakdown when validating
    const invoiceUpdate: Record<string, unknown> = {
      status,
      reviewedBy: context.user!.email,
      reviewedAt: new Date().toISOString(),
      reviewNotes: input.notes,
    };
    if (input.action === 'validar') {
      if (input.validatedSubtotal !== undefined) invoiceUpdate.subtotal = input.validatedSubtotal;
      if (input.validatedIvaRate !== undefined) invoiceUpdate.ivaRate = input.validatedIvaRate;
      if (input.validatedIvaAmount !== undefined) invoiceUpdate.ivaAmount = input.validatedIvaAmount;
      if (input.validatedRetencionIva !== undefined) invoiceUpdate.retencionIva = input.validatedRetencionIva;
      if (input.validatedRetencionIsr !== undefined) invoiceUpdate.retencionIsr = input.validatedRetencionIsr;
      if (input.validatedTotal !== undefined) invoiceUpdate.amount = input.validatedTotal;
    }

    // Update invoice status
    await SupplierInvoices.update({
      id: input.invoiceId,
      record: invoiceUpdate,
    });

    // If validating, create a scheduled payment
    if (input.action === 'validar') {
      const invoice = await SupplierInvoices.findOne({ id: input.invoiceId });
      if (invoice) {
        // Use the validated total if provided, fall back to stored amount
        const paymentAmount = input.validatedTotal ?? invoice.amount;
        const payment = await Payments.create({
          record: {
            type: 'Pago a proveedor',
            poId: invoice.poId,
            supplierName: invoice.supplierName,
            supplierInvoiceNumber: invoice.invoiceNumber,
            amount: paymentAmount,
            currency: invoice.currency ?? 'MXN',
            projectCode: invoice.projectCode,
            dueDate: input.scheduledPaymentDate,
            status: 'Programado',
            notes: `Pago programado automáticamente al validar factura ${invoice.invoiceNumber ?? ''}`,
          },
        });
        return { success: true, paymentId: payment.id };
      }
    }

    // If rejecting, send email notification to supplier
    if (input.action === 'rechazar') {
      let emailSent = false;
      try {
        const invoice = await SupplierInvoices.findOne({ id: input.invoiceId });
        if (invoice?.supplierName) {
          const supplier = await Suppliers.findOne({ filters: { supplierName: invoice.supplierName } });
          const recipientEmail = supplier?.email;
          const accessToken = process.env.ZITE_OUTLOOK_ACCESS_TOKEN;

          if (recipientEmail && accessToken) {
            const contactName = supplier?.contactName || invoice.supplierName;
            const invoiceNumber = invoice.invoiceNumber ?? 'Sin número';
            const amount = invoice.amount != null
              ? new Intl.NumberFormat('es-MX', { style: 'currency', currency: invoice.currency ?? 'MXN' }).format(invoice.amount)
              : '—';
            const rejectionNotes = input.notes || 'No se especificó un motivo.';
            const sendAsEmail = process.env.ZITE_OUTLOOK_SEND_AS_EMAIL?.trim() || undefined;

            const htmlBody = `
<!DOCTYPE html>
<html lang="es">
<head><meta charset="UTF-8"></head>
<body style="font-family: Arial, sans-serif; color: #333; max-width: 600px; margin: 0 auto; padding: 20px;">
  <p style="font-size: 16px;">Estimado/a <strong>${contactName}</strong>,</p>

  <p>Hemos revisado la factura que nos enviaste y hemos detectado que <strong>requiere correcciones</strong> antes de poder procesarla.</p>

  <table style="width: 100%; border-collapse: collapse; margin: 20px 0; font-size: 14px;">
    <tr style="background-color: #f5f5f5;">
      <td style="padding: 10px 14px; font-weight: bold; border: 1px solid #ddd; width: 40%;">Número de factura</td>
      <td style="padding: 10px 14px; border: 1px solid #ddd;">${invoiceNumber}</td>
    </tr>
    <tr>
      <td style="padding: 10px 14px; font-weight: bold; border: 1px solid #ddd;">Monto</td>
      <td style="padding: 10px 14px; border: 1px solid #ddd;">${amount}</td>
    </tr>
  </table>

  <p style="font-weight: bold; margin-bottom: 6px;">Motivo del rechazo:</p>
  <div style="background-color: #fff3cd; border-left: 4px solid #f0ad4e; padding: 14px 18px; border-radius: 4px; font-size: 14px; margin-bottom: 20px;">
    ${rejectionNotes}
  </div>

  <p>Por favor, realiza las correcciones necesarias y reenvía la factura corregida lo antes posible para que podamos continuar con el proceso de pago.</p>

  <p>Si tienes alguna duda, no dudes en contactarnos respondiendo a este correo.</p>

  <br>
  <p style="color: #555;">Saludos,<br>
  <strong>Equipo de Compras — Sapience</strong></p>
</body>
</html>`;

            const mailPayload = {
              message: {
                subject: `Factura ${invoiceNumber} — Corrección requerida`,
                body: { contentType: 'HTML', content: htmlBody },
                toRecipients: [{ emailAddress: { address: recipientEmail } }],
                ...(sendAsEmail ? { from: { emailAddress: { address: sendAsEmail } } } : {}),
              },
              saveToSentItems: true,
            };

            const graphResp = await fetch('https://graph.microsoft.com/v1.0/me/sendMail', {
              method: 'POST',
              headers: {
                Authorization: `Bearer ${accessToken}`,
                'Content-Type': 'application/json',
              },
              body: JSON.stringify(mailPayload),
            });

            if (graphResp.ok) {
              emailSent = true;
            } else {
              const errText = await graphResp.text().catch(() => '');
              console.error(`Error al enviar email de rechazo (${graphResp.status}): ${errText.slice(0, 300)}`);
            }
          }
        }
      } catch (err) {
        console.error('Error inesperado al enviar email de rechazo de factura:', err);
      }

      return { success: true, emailSent };
    }

    return { success: true };
  },
});

src/api/sendCalendarToWebhook.ts.content:
import { z } from 'zod';
import { createEndpoint, CalendarEvents, Projects, BoardColumns, CellValues, Boards, Documents } from 'zite-integrations-backend-sdk';

function toKey(name: string): string {
  return name
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, '_')
    .replace(/[^a-z0-9_]/g, '');
}

function mapColType(type: string | null | undefined): string {
  switch (type) {
    case 'Status':        return 'status';
    case 'Fecha':         return 'date';
    case 'Datetime':      return 'datetime';
    case 'Persona':       return 'people';
    case 'Color':         return 'color_picker';
    case 'Texto':         return 'text';
    case 'Número':        return 'numbers';
    case 'Número entero': return 'numbers';
    case 'Select':        return 'dropdown';
    default:              return (type ?? 'text').toLowerCase();
  }
}

function colDefaults(type: string): { width: number; align: string } {
  switch (type) {
    case 'date': case 'datetime': case 'time': return { width: 12, align: 'center' };
    case 'numbers': case 'number':              return { width: 10, align: 'center' };
    case 'status': case 'dropdown':             return { width: 14, align: 'center' };
    case 'people':                              return { width: 14, align: 'left'   };
    default:                                    return { width: 20, align: 'left'   };
  }
}

const FIXED_DEFS = [
  { id: 'dinamica',    key: 'dinamica',    title: 'Dinámica',    type: 'text',   width: 20, align: 'left'   },
  { id: 'fecha',       key: 'fecha',       title: 'Fecha',       type: 'date',   width: 12, align: 'center' },
  { id: 'hora_mx',     key: 'hora_mx',     title: 'Hora (MX)',   type: 'time',   width: 11, align: 'center' },
  { id: 'duracion',    key: 'duracion',    title: 'Duración',    type: 'number', width: 10, align: 'center' },
  { id: 'moderador',   key: 'moderador',   title: 'Moderador',   type: 'text',   width: 14, align: 'left'   },
  { id: 'descripcion', key: 'descripcion', title: 'Descripción', type: 'text',   width: 30, align: 'left'   },
] as const;

const LOGO_URL = 'https://i.ibb.co/pBZgRxSJ/logo-sapience-alargado-timelines-transparente.png';

type ColDef = { id: string; key: string; title: string; type: string; width: number; align: string };

export default createEndpoint({
  authenticated: true,
  description: 'Sends calendar events to n8n webhook with clean columnConfig + groups/rows payload format',
  inputSchema: z.object({
    projectCode: z.string(),
    calendarName: z.string().optional(),
    boardId: z.string().optional(),
    columnOrder: z.array(z.string()).optional(),
    selectedColumnIds: z.array(z.string()).optional(),
    overrideVersion: z.string().optional(),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    eventCount: z.number(),
    calendarStatus: z.string().optional(),
    fileUrl: z.string().optional(),
    version: z.string().optional(),
  }),
  execute: async ({ input }) => {
    const webhookUrl = process.env.ZITE_N8N_CALENDAR_WEBHOOK_URL ?? '';
    if (!webhookUrl) throw new Error('Webhook URL de calendario no configurada');

    const nowISO = new Date().toISOString();

    // ── Resolve board UUID ─────────────────────────────────────────────────
    let resolvedBoardId: string;
    let boardResult: any = null;

    if (input.boardId) {
      // UUID-first: use boardId exclusively for ALL queries
      resolvedBoardId = input.boardId;
      boardResult = await Boards.findOne({ id: input.boardId });
    } else {
      // Legacy fallback — require calendarName, check for ambiguity
      if (!input.calendarName) throw new Error('Either boardId or calendarName is required.');
      const boardsResult = await Boards.findAll({
        filters: { boardName: input.calendarName, projectCode: input.projectCode, boardType: 'calendar' } as any,
        limit: 10,
      });
      const activeBoards = boardsResult.records.filter(b => !b.deletedAt);
      if (activeBoards.length > 1) {
        throw new Error(`Ambiguity: ${activeBoards.length} calendars named "${input.calendarName}" exist for project ${input.projectCode}. Pass boardId to disambiguate.`);
      }
      if (activeBoards.length === 1) {
        resolvedBoardId = activeBoards[0].id;
        boardResult = activeBoards[0];
      } else {
        // 0 matches — use legacy composite as last resort
        resolvedBoardId = `cal-${input.projectCode}-${input.calendarName}`;
        boardResult = null;
      }
    }

    const groupBoardId = `${resolvedBoardId}::groups`;

    // ── Fetch events: UUID-first, no dual-path when boardId exists ─────────
    const eventsFilter: Record<string, string> = input.boardId
      ? { boardId: input.boardId }
      : { projectCode: input.projectCode, calendarName: input.calendarName! };

    const [eventsResult, projectResult, colRes, cellRes, groupColRes, groupCellRes] = await Promise.all([
      CalendarEvents.findAll({ filters: eventsFilter as any, limit: 500 }),
      Projects.findOne({ filters: { projectCode: input.projectCode } }),
      BoardColumns.findAll({ filters: { boardId: resolvedBoardId } as any, limit: 200 }),
      CellValues.findAll({ filters: { boardId: resolvedBoardId } as any, limit: 2000 }),
      BoardColumns.findAll({ filters: { boardId: groupBoardId } as any, limit: 100 }),
      CellValues.findAll({ filters: { boardId: groupBoardId } as any, limit: 2000 }),
    ]);

    const events      = eventsResult.records;
    const projectName = projectResult?.fullName || input.projectCode;

    // ── Version counter ────────────────────────────────────────────────────
    const newVersion = (boardResult?.calendarVersion ?? 0) + 1;
    const versionStr = input.overrideVersion ?? String(newVersion);

    // ── Active columns & cells ─────────────────────────────────────────────
    const activeCols  = colRes.records.filter(c => !c.deletedAt);
    const activeCells = cellRes.records.filter(c => !c.deletedAt);

    const cellsByEventCol = new Map<string, Map<string, typeof activeCells[0]>>();
    for (const cell of activeCells) {
      if (!cell.rowId || !cell.columnId) continue;
      if (!cellsByEventCol.has(cell.rowId)) cellsByEventCol.set(cell.rowId, new Map());
      cellsByEventCol.get(cell.rowId)!.set(cell.columnId, cell);
    }

    const deduped = new Map<string, typeof activeCols[0]>();
    for (const col of activeCols) {
      deduped.set((col.columnName ?? col.id).toLowerCase().trim(), col);
    }

    // ── Build all column defs ──────────────────────────────────────────────
    const fixedColDefs: ColDef[] = FIXED_DEFS.map(fd => ({ ...fd }));

    const dynColDefs: ColDef[] = [];
    for (const [, col] of deduped) {
      const key  = toKey(col.columnName ?? col.id);
      const type = mapColType(col.columnType);
      const title = col.columnName ?? col.id;
      if (title === 'Ubicación Interna' || title === 'Ubicación (interna)') continue;
      if (type === 'datetime') {
        dynColDefs.push({ id: `${col.id}__fecha`, key: `${key}_fecha`, title: 'Fecha', type: 'date', width: 12, align: 'center' });
        dynColDefs.push({ id: `${col.id}__hora`,  key: `${key}_hora`,  title: 'Hora',  type: 'time', width: 11, align: 'center' });
      } else {
        const def = colDefaults(type);
        dynColDefs.push({ id: col.id, key, title, type, ...def });
      }
    }

    const allDefs: ColDef[] = [...fixedColDefs, ...dynColDefs];

    if (input.columnOrder && input.columnOrder.length > 0) {
      const orderMap = new Map(input.columnOrder.map((id, i) => [id, i]));
      allDefs.sort((a, b) => {
        const ai: number = orderMap.has(a.id) ? (orderMap.get(a.id) as number) : 9999;
        const bi: number = orderMap.has(b.id) ? (orderMap.get(b.id) as number) : 9999;
        return ai - bi;
      });
    }

    // ── Selection ──────────────────────────────────────────────────────────
    const selectedSet = input.selectedColumnIds ? new Set(input.selectedColumnIds) : null;
    const isSelected  = (id: string) => !selectedSet || selectedSet.has(id);

    const columnConfig = allDefs.map((def, i) => ({
      key:     def.key,
      title:   def.title,
      enabled: isSelected(def.id),
      order:   i + 1,
      type:    def.type,
      width:   def.width,
      align:   def.align,
    }));

    const sortedDynDefs = allDefs.filter(d => dynColDefs.some(dd => dd.id === d.id));

    // ── Group membership ───────────────────────────────────────────────────
    const activeGroupCols  = groupColRes.records.filter(c => !c.deletedAt);
    const activeGroupCells = groupCellRes.records.filter(c => !c.deletedAt);
    activeGroupCols.sort((a, b) => (a.columnOrder ?? 0) - (b.columnOrder ?? 0));

    const eventGroupMap = new Map<string, string>();
    for (const cell of activeGroupCells) {
      if (cell.textValue === '1' && cell.rowId && cell.columnId) {
        if (!eventGroupMap.has(cell.rowId)) eventGroupMap.set(cell.rowId, cell.columnId);
      }
    }

    // ── Build flat row ─────────────────────────────────────────────────────
    function buildRow(ev: typeof events[0]): Record<string, string | number> {
      const eventDate = ev.eventDate ? new Date(ev.eventDate) : null;
      const fecha     = eventDate ? eventDate.toLocaleDateString('en-CA', { timeZone: 'America/Mexico_City' }) : '';
      const hora_mx   = eventDate
        ? eventDate.toLocaleTimeString('es-MX', {
            hour: '2-digit', minute: '2-digit', hour12: false,
            timeZone: 'America/Mexico_City',
          })
        : '';

      const row: Record<string, string | number> = {
        rowId:       ev.id,
        dinamica:    ev.eventName ?? '',
        fecha,
        hora_mx,
        duracion:    ev.durationHours ?? '',
        moderador:   ev.attendees ?? '',
        descripcion: ev.notes ?? '',
      };

      const eventCells = cellsByEventCol.get(ev.id);
      for (const dyn of sortedDynDefs) {
        const isFecha   = dyn.id.endsWith('__fecha');
        const isHora    = dyn.id.endsWith('__hora');
        const realColId = (isFecha || isHora) ? dyn.id.replace(/__fecha$|__hora$/, '') : dyn.id;
        const cell      = eventCells?.get(realColId);
        let val: string | number = '';
        if (cell) {
          if (isFecha || isHora) {
            const rawDate = cell.dateValue;
            if (rawDate) {
              const d = new Date(rawDate);
              val = isFecha
                ? d.toLocaleDateString('en-CA', { timeZone: 'America/Mexico_City' })
                : d.toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: 'America/Mexico_City' });
            }
          } else if (cell.textValue) {
            val = cell.textValue;
          } else if (cell.dateValue) {
            val = new Date(cell.dateValue).toLocaleDateString('en-CA', { timeZone: 'America/Mexico_City' });
          } else if (cell.numberValue != null) {
            val = cell.numberValue;
          }
        }
        row[dyn.key] = val;
      }

      return row;
    }

    // ── Bucket events into groups ──────────────────────────────────────────
    const topLevelEvents = events.filter(e => !e.parentEventId);
    const groupBuckets   = new Map<string, typeof events>();
    for (const g of activeGroupCols) groupBuckets.set(g.id, []);
    const ungrouped: typeof events = [];

    for (const e of topLevelEvents) {
      const gid = eventGroupMap.get(e.id);
      if (gid && groupBuckets.has(gid)) groupBuckets.get(gid)!.push(e);
      else ungrouped.push(e);
    }

    const groups: { groupId: string; groupName: string; rows: Record<string, string | number>[] }[] = [];
    for (const g of activeGroupCols) {
      groups.push({
        groupId:   g.id,
        groupName: g.columnName ?? 'Sin nombre',
        rows:      (groupBuckets.get(g.id) ?? []).map(buildRow),
      });
    }
    if (ungrouped.length > 0 || groups.length === 0) {
      groups.push({ groupId: 'ungrouped', groupName: 'Sin grupo', rows: ungrouped.map(buildRow) });
    }

    // ── Payload ────────────────────────────────────────────────────────────
    const calendarLabel = boardResult?.boardName ?? input.calendarName ?? 'Calendar';
    const tematica     = (projectResult as any)?.tematica ?? '';
    const calendarTitle = tematica ? `${tematica} - ${calendarLabel}` : calendarLabel;
    const payload = {
      title:       calendarTitle,
      project:     projectName,
      version:     versionStr,
      last_update: nowISO,
      logo_url:    LOGO_URL,
      columnConfig,
      groups,
    };

    let webhookBody: Record<string, any> = {};
    try {
      const res = await fetch(webhookUrl, {
        method:  'POST',
        headers: { 'Content-Type': 'application/json' },
        body:    JSON.stringify(payload),
      });
      const raw = await res.json();
      webhookBody = Array.isArray(raw) ? (raw[0] ?? {}) : raw;
    } catch { /* network error or non-JSON body */ }

    const resolvedFileUrl: string | undefined =
      webhookBody.fileUrl ?? webhookBody.file_url ?? webhookBody.url ??
      webhookBody.webUrl  ?? webhookBody.pdfUrl   ?? undefined;

    // ── Persist version + columns + fileUrl ────────────────────────────────
    if (boardResult?.id) {
      const updates: Record<string, unknown> = { calendarVersion: newVersion };
      if (input.columnOrder || input.selectedColumnIds) {
        updates.excelColumnsJson = JSON.stringify({
          order:    input.columnOrder    ?? allDefs.map(d => d.id),
          selected: input.selectedColumnIds ?? allDefs.map(d => d.id),
        });
      }
      if (resolvedFileUrl) {
        updates.calendarFileUrl = resolvedFileUrl;
      }
      try {
        await Boards.update({ id: boardResult.id, record: updates as any });
      } catch { /* best-effort */ }
    }

    // ── Save document record when we have a fileUrl ────────────────────────
    if (resolvedFileUrl) {
      try {
        const today = new Date().toISOString().split('T')[0];
        await Documents.create({
          record: {
            documentName: `${calendarLabel} - v${versionStr}`,
            projectCode: input.projectCode,
            category: 'Calendario',
            fileUrl: resolvedFileUrl,
            uploadDate: today,
            version: versionStr,
          },
        });
      } catch { /* best-effort */ }
    }

    if (resolvedFileUrl) {
      return { success: true, eventCount: events.length, calendarStatus: 'Listo', fileUrl: resolvedFileUrl, version: versionStr };
    }
    return { success: true, eventCount: events.length, calendarStatus: 'Listo', version: versionStr };
  },
});

src/api/sendTimelineToWebhook.ts.content:
import { z } from 'zod';
import { createEndpoint, Tasks, Projects, BoardColumns, CellValues, Documents, Users, Boards } from 'zite-integrations-backend-sdk';

// Convert HSL (0-360, 0-100, 0-100) to hex string
function hslToHex(h: number, s: number, l: number): string {
  s /= 100; l /= 100;
  const k = (n: number) => (n + h / 30) % 12;
  const a = s * Math.min(l, 1 - l);
  const f = (n: number) => l - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1)));
  return '#' + [f(0), f(8), f(4)].map(x => Math.round(x * 255).toString(16).padStart(2, '0')).join('');
}

// Color ID → [h, s, l] from CSS variables in index.css
const COLOR_HSL: Record<string, [number, number, number]> = {
  'red-1':    [4,   85, 65], 'red-2':    [4,   85, 55], 'red-3':    [4,   82, 45], 'red-4':    [4,   78, 37], 'red-5':    [4,   72, 28],
  'orange-1': [25,  90, 65], 'orange-2': [25,  88, 55], 'orange-3': [25,  85, 45], 'orange-4': [25,  82, 37], 'orange-5': [25,  78, 28],
  'yellow-1': [47,  95, 62], 'yellow-2': [47,  92, 52], 'yellow-3': [47,  88, 43], 'yellow-4': [47,  84, 35], 'yellow-5': [47,  78, 27],
  'green-1':  [142, 52, 60], 'green-2':  [142, 56, 50], 'green-3':  [142, 58, 40], 'green-4':  [142, 56, 32], 'green-5':  [142, 52, 24],
  'blue-1':   [215, 82, 68], 'blue-2':   [215, 80, 58], 'blue-3':   [215, 78, 48], 'blue-4':   [215, 76, 38], 'blue-5':   [215, 72, 29],
  'purple-1': [265, 68, 68], 'purple-2': [265, 70, 58], 'purple-3': [265, 68, 48], 'purple-4': [265, 65, 38], 'purple-5': [265, 62, 29],
  // Legacy backward-compat IDs
  chart1: [215, 80, 58], chart2: [142, 56, 50], chart3: [25, 85, 45],
  chart4: [265, 70, 58], chart5: [199, 80, 52], primary: [215, 78, 48],
  destructive: [4, 82, 45], muted: [215, 15, 50],
  'group-pink': [4, 85, 65], 'group-yellow': [47, 92, 52], 'group-lime': [84, 58, 44],
  'group-teal': [174, 58, 40], 'group-indigo': [239, 68, 52], 'group-amber': [35, 88, 50],
  'group-rose': [4, 85, 55], 'group-emerald': [152, 58, 42], 'group-sky': [199, 80, 52],
  'group-violet': [262, 68, 52], 'group-fuchsia': [293, 68, 50], 'group-slate': [215, 18, 50],
};

function colorIdToHex(colorId: string | null | undefined): string {
  if (!colorId) return '#6B7280';
  const hsl = COLOR_HSL[colorId];
  return hsl ? hslToHex(...hsl) : '#6B7280';
}

// Map internal column types to monday.com-compatible types
function mapColType(type: string | null | undefined): string {
  switch (type) {
    case 'Status':        return 'status';
    case 'Fecha':         return 'date';
    case 'Persona':       return 'people';
    case 'Color':         return 'color_picker';
    case 'Texto':         return 'text';
    case 'Número':        return 'numbers';
    case 'Número entero': return 'numbers';
    default:              return (type ?? 'text').toLowerCase();
  }
}

export default createEndpoint({
  authenticated: true,
  description: 'Sends project tasks grouped by group to n8n webhook for timeline/Excel generation',
  inputSchema: z.object({
    projectCode: z.string(),
    boardName: z.string().optional(),
    boardId: z.string().optional(),
    version: z.string().optional(),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    taskCount: z.number(),
    timelineStatus: z.string().optional(),
    fileUrl: z.string().optional(),
    version: z.string().optional(),
  }),
  execute: async ({ input }) => {
    const webhookUrl = process.env.ZITE_N8N_TIMELINE_WEBHOOK_URL ?? '';
    if (!webhookUrl) throw new Error('Webhook URL not configured');

    // ── Resolve board identity: UUID-first, legacy fallback ────────────────
    let resolvedBoardId: string;
    let boardRecord: any = null;

    if (input.boardId) {
      // UUID path — use directly, no name-based lookup
      resolvedBoardId = input.boardId;
      boardRecord = await Boards.findOne({ id: input.boardId });
    } else if (input.boardName) {
      // Legacy fallback with ambiguity check
      const { records: matchingBoards } = await Boards.findAll({
        filters: { boardName: input.boardName, projectCode: input.projectCode, boardType: 'pm' } as any,
        limit: 10,
      });
      const activeBoards = matchingBoards.filter(b => !b.deletedAt);
      if (activeBoards.length > 1) {
        throw new Error(`Ambiguity: ${activeBoards.length} active boards named "${input.boardName}" in project ${input.projectCode}. Pass boardId to resolve.`);
      }
      if (activeBoards.length === 1) {
        resolvedBoardId = activeBoards[0].id;
        boardRecord = activeBoards[0];
      } else {
        // Zero matches — backward-compat legacy composite
        resolvedBoardId = `pm-${input.projectCode}-${input.boardName}`;
      }
    } else {
      resolvedBoardId = `pm-${input.projectCode}`;
    }

    const boardId      = resolvedBoardId;
    const groupBoardId = `${boardId}::groups`;

    // Build task filters: prefer boardId when UUID, fallback to boardName
    const taskFilters: Record<string, any> = { projectCode: input.projectCode };
    if (input.boardId) {
      taskFilters.boardId = input.boardId;
    } else if (input.boardName) {
      taskFilters.boardName = input.boardName;
    }

    // Fetch everything in parallel
    const [tasksResult, projectResult, colRes, cellRes, groupColRes, groupCellRes, usersResult] = await Promise.all([
      Tasks.findAll({ filters: taskFilters as any, limit: 500 }),
      Projects.findOne({ filters: { projectCode: input.projectCode } }),
      BoardColumns.findAll({ filters: { boardId } as any, limit: 200 }),
      CellValues.findAll({ filters: { boardId } as any, limit: 2000 }),
      BoardColumns.findAll({ filters: { boardId: groupBoardId } as any, limit: 100 }),
      CellValues.findAll({ filters: { boardId: groupBoardId } as any, limit: 2000 }),
      Users.findAll({ limit: 200, fields: ['firstName', 'lastName', 'email'] }),
    ]);

    // ── Version counter ───────────────────────────────────────────────────
    const autoVersion = (boardRecord?.timelineVersion ?? 0) + 1;
    const versionStr  = input.version ?? String(autoVersion);

    // Build ID→name map for resolving Persona cell values
    const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    const userById = new Map(usersResult.records.map(u => [u.id, u]));
    const resolvePersona = (val: string | null | undefined): string => {
      if (!val) return '';
      if (!UUID_RE.test(val)) return val; // legacy: already a name
      const u = userById.get(val);
      return u ? ([u.firstName, u.lastName].filter(Boolean).join(' ') || u.email || val) : val;
    };

    const tasks       = tasksResult.records;
    const projectName = projectResult?.fullName || input.projectCode;
    const now         = new Date().toISOString();

    // Build title: "{tematica} - {boardName}" or just "{boardName}" if no tematica
    const tematica    = (projectResult as any)?.tematica ?? '';
    const boardLabel  = input.boardName ?? 'Timeline';
    const titleStr    = tematica ? `${tematica} - ${boardLabel}` : boardLabel;

    // ── Task columns & cells ────────────────────────────────────────────────
    const activeCols  = colRes.records.filter(c => !c.deletedAt);
    const activeCells = cellRes.records.filter(c => !c.deletedAt);

    // taskId -> { columnId -> cell }
    const cellsByTaskCol = new Map<string, Map<string, typeof activeCells[0]>>();
    for (const cell of activeCells) {
      if (!cell.rowId || !cell.columnId) continue;
      if (!cellsByTaskCol.has(cell.rowId)) cellsByTaskCol.set(cell.rowId, new Map());
      cellsByTaskCol.get(cell.rowId)!.set(cell.columnId, cell);
    }

    // Group columns by normalised name to handle duplicates
    const colsByName = new Map<string, typeof activeCols>();
    for (const col of activeCols) {
      const key = (col.columnName ?? '').toLowerCase().trim();
      if (!colsByName.has(key)) colsByName.set(key, []);
      colsByName.get(key)!.push(col);
    }

    function resolveCell(taskId: string, colName: string) {
      const cols = colsByName.get(colName.toLowerCase().trim()) ?? [];
      const taskCells = cellsByTaskCol.get(taskId);
      if (!taskCells) return undefined;
      for (const col of cols) {
        const cell = taskCells.get(col.id);
        if (cell) return cell;
      }
      return undefined;
    }

    // Deduped columns for board schema (last one wins on duplicate names)
    const deduped = new Map<string, typeof activeCols[0]>();
    for (const col of activeCols) {
      deduped.set((col.columnName ?? col.id).toLowerCase().trim(), col);
    }

    const boardColumns: { id: string; title: string; type: string }[] = [
      { id: 'name', title: 'Name', type: 'name' },
      ...Array.from(deduped.values()).map(col => ({
        id: col.id,
        title: col.columnName ?? col.id,
        type: mapColType(col.columnType),
      })),
    ];

    const hasCronograma = deduped.has('cronograma') || deduped.has('cronograma general');
    if (!hasCronograma) {
      boardColumns.push({ id: 'cronograma_calc', title: 'Cronograma', type: 'timeline' });
    }

    // ── Group columns & membership ──────────────────────────────────────────
    const activeGroupCols  = groupColRes.records.filter(c => !c.deletedAt);
    const activeGroupCells = groupCellRes.records.filter(c => !c.deletedAt);

    // Sort groups by their column order
    activeGroupCols.sort((a, b) => (a.columnOrder ?? 0) - (b.columnOrder ?? 0));

    // taskId -> groupColumnId (first group with textValue === '1')
    const taskGroupMap = new Map<string, string>();
    for (const cell of activeGroupCells) {
      if (cell.textValue === '1' && cell.rowId && cell.columnId) {
        if (!taskGroupMap.has(cell.rowId)) {
          taskGroupMap.set(cell.rowId, cell.columnId);
        }
      }
    }

    // ── Build task subitem ──────────────────────────────────────────────────
    function buildSubitem(t: typeof tasks[0]) {
      const startCell      = resolveCell(t.id, 'Inicio');
      const endCell        = resolveCell(t.id, 'Fin');
      const statusCell     = resolveCell(t.id, 'Estado');
      const responsableCell = resolveCell(t.id, 'Responsable');
      // Resolve color: match by name "Color" OR by columnType === 'Color'
      const colorColByType = Array.from(deduped.values()).find(c => c.columnType === 'Color');
      const colorCell      = resolveCell(t.id, 'Color') ??
        (colorColByType ? cellsByTaskCol.get(t.id)?.get(colorColByType.id) : undefined);

      const startDate  = startCell?.dateValue?.split('T')[0]  || t.startDate?.split('T')[0]  || '';
      const endDate    = endCell?.dateValue?.split('T')[0]    || t.endDate?.split('T')[0]    || '';
      const status     = statusCell?.textValue  || t.status     || '';
      const assignedTo = resolvePersona(responsableCell?.textValue || t.assignedTo || '');
      const color      = colorCell?.textValue   || null;

      const cronText  = startDate && endDate ? `${startDate} - ${endDate}` : (startDate || endDate || '');
      const cronValue = startDate || endDate
        ? JSON.stringify({ to: endDate || startDate, from: startDate || endDate, changed_at: now })
        : null;

      const column_values = Array.from(deduped.values()).map(col => {
        const colType     = mapColType(col.columnType);
        const cell        = cellsByTaskCol.get(t.id)?.get(col.id);
        const colNameLower = (col.columnName ?? '').toLowerCase().trim();

        if (colNameLower === 'inicio') {
          return { id: col.id, text: startDate, value: startDate ? JSON.stringify({ date: startDate, changed_at: now }) : null, type: colType };
        }
        if (colNameLower === 'fin') {
          return { id: col.id, text: endDate, value: endDate ? JSON.stringify({ date: endDate, changed_at: now }) : null, type: colType };
        }
        if (colNameLower === 'estado') {
          return { id: col.id, text: status, value: status ? JSON.stringify({ index: 0, post_id: null, changed_at: now }) : null, type: colType };
        }
        if (colNameLower === 'responsable' || colType === 'people') {
          return { id: col.id, text: assignedTo, value: assignedTo ? JSON.stringify({ changed_at: now, personsAndTeams: [{ id: assignedTo, kind: 'person' }] }) : null, type: colType };
        }
        if (colNameLower === 'color' || colType === 'color_picker') {
          return { id: col.id, text: color, value: color ? JSON.stringify({ color, changed_at: now }) : null, type: colType };
        }
        const text = cell?.textValue || cell?.dateValue?.split('T')[0] || '';
        return { id: col.id, text, value: text || null, type: colType };
      });

      if (!hasCronograma) {
        column_values.push({ id: 'cronograma_calc', text: cronText, value: cronValue, type: 'timeline' });
      }

      return { id: t.id, name: t.taskName ?? '', column_values };
    }

    // ── Bucket tasks into groups ────────────────────────────────────────────
    const topLevelTasks = tasks.filter(t => !t.parentTaskId);

    // One bucket per group (in order), plus a catch-all for ungrouped
    const groupBuckets = new Map<string, typeof tasks>();
    for (const g of activeGroupCols) groupBuckets.set(g.id, []);
    const ungrouped: typeof tasks = [];

    for (const t of topLevelTasks) {
      const gid = taskGroupMap.get(t.id);
      if (gid && groupBuckets.has(gid)) {
        groupBuckets.get(gid)!.push(t);
      } else {
        ungrouped.push(t);
      }
    }

    // ── Helper: resolve a task's start date for chronological sorting ──────
    const getTaskStartDate = (t: typeof tasks[0]): string =>
      resolveCell(t.id, 'Inicio')?.dateValue?.split('T')[0] || t.startDate?.split('T')[0] || '';

    const sortByStartDate = (arr: typeof tasks) =>
      [...arr].sort((a, b) => {
        const da = getTaskStartDate(a);
        const db = getTaskStartDate(b);
        if (!da && !db) return 0;
        if (!da) return 1;   // tasks without date go last
        if (!db) return -1;
        return da < db ? -1 : da > db ? 1 : 0;
      });

    // ── Build items array ───────────────────────────────────────────────────
    // Ungrouped tasks go FIRST (chronological), then named groups (each chronological)
    const boardDef = { id: boardId, columns: boardColumns };

    const items: object[] = [];

    // 1. Ungrouped tasks at the top (with empty header)
    if (ungrouped.length > 0 || activeGroupCols.length === 0) {
      items.push({
        id: 'ungrouped',
        name: ' ',
        color: null,
        color_hex: '#6B7280',
        board: boardDef,
        column_values: [],
        subitems: sortByStartDate(ungrouped).map(buildSubitem),
      });
    }

    // 2. Named groups, each with tasks sorted by start date
    for (const g of activeGroupCols) {
      const bucket   = groupBuckets.get(g.id) ?? [];
      const colorId  = g.columnType ?? null;
      items.push({
        id: g.id,
        name: g.columnName ?? 'Sin nombre',
        color: colorId,
        color_hex: colorIdToHex(colorId),
        board: boardDef,
        column_values: [],
        subitems: sortByStartDate(bucket).map(buildSubitem),
      });
    }

    const payload = {
      project: projectName,
      title: titleStr,
      version: versionStr,
      logo_url: 'https://i.postimg.cc/hjCKc6D1/logo-sapience-transparente.png',
      items,
    };

    try {
      const res = await fetch(webhookUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });

      if (!res.ok) throw new Error(`Webhook responded with ${res.status}`);

      let body: Record<string, any> = {};
      try { body = await res.json(); } catch { /* not JSON */ }

      // Resolve file URL from any common field name n8n might return
      const resolvedFileUrl: string | undefined =
        body.fileUrl ?? body.file_url ?? body.url ??
        body.webUrl  ?? body.pdfUrl   ?? undefined;

      const updatedAt = new Date().toISOString();

      if (body.status === 'success' && resolvedFileUrl) {
        if (projectResult?.id) {
          try {
            await Projects.update({ id: projectResult.id, record: { timelineStatus: 'Listo', timelineUrl: resolvedFileUrl, timelineUpdatedAt: updatedAt } });
          } catch { /* best-effort */ }
        }
        // Save document record
        try {
          const today = new Date().toISOString().split('T')[0];
          await Documents.create({
            record: {
              documentName: `${boardLabel} - ${input.projectCode}`,
              projectCode: input.projectCode,
              category: 'Timeline',
              fileUrl: resolvedFileUrl,
              uploadDate: today,
            },
          });
        } catch { /* best-effort */ }
        // Persist version counter in Board record
        if (boardRecord?.id) {
          try { await Boards.update({ id: boardRecord.id, record: { timelineVersion: autoVersion } as any }); } catch { /* best-effort */ }
        }
        return { success: true, taskCount: tasks.length, timelineStatus: 'Listo', fileUrl: resolvedFileUrl, version: versionStr };
      } else {
        if (projectResult?.id) {
          await Projects.update({ id: projectResult.id, record: { timelineStatus: 'Error', timelineUpdatedAt: updatedAt } });
        }
        // Still persist version counter even on n8n error
        if (boardRecord?.id) {
          try { await Boards.update({ id: boardRecord.id, record: { timelineVersion: autoVersion } as any }); } catch { /* best-effort */ }
        }
        return { success: true, taskCount: tasks.length, timelineStatus: 'Error', version: versionStr };
      }
    } catch (err) {
      if (projectResult?.id) {
        try { await Projects.update({ id: projectResult.id, record: { timelineStatus: 'Error', timelineUpdatedAt: new Date().toISOString() } }); } catch { /* best-effort */ }
      }
      throw err;
    }
  },
});

