src/api/getTimelineBoardStatus.ts.content:
import { z } from 'zod';
import { createEndpoint, Boards } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Returns timelineVersion and fileUrl for a given PM board',
  inputSchema: z.object({
    projectCode: z.string(),
    boardName: z.string().optional(),
    boardId: z.string().optional(),
  }),
  outputSchema: z.object({
    currentVersion: z.number().nullable(),
    fileUrl: z.string().nullable(),
  }),
  execute: async ({ input }) => {
    let board: any = null;

    if (input.boardId) {
      // UUID path — direct lookup
      board = await Boards.findOne({ id: input.boardId });
    } else if (input.boardName) {
      // Legacy fallback with ambiguity check
      const { records } = await Boards.findAll({
        filters: {
          boardName: input.boardName,
          projectCode: input.projectCode,
          boardType: 'pm',
        } as any,
        limit: 10,
      });
      const active = records.filter(b => !b.deletedAt);
      if (active.length > 1) {
        throw new Error(`Ambiguity: ${active.length} active boards named "${input.boardName}" in project ${input.projectCode}. Pass boardId to resolve.`);
      }
      board = active[0] ?? null;
    }

    return {
      currentVersion: board?.timelineVersion ?? null,
      fileUrl: null,
    };
  },
});

src/api/normalizeSupplierNames.ts.content:
import { z } from 'zod';
import { createEndpoint, Suppliers, PurchaseOrders } from 'zite-integrations-backend-sdk';

const sleep = (ms: number) => new Promise(r => setTimeout(r, ms));

export default createEndpoint({
  authenticated: true,
  description: 'Normalize supplier name variants in Purchase Orders to a single canonical name. Optionally creates a Supplier record.',
  inputSchema: z.object({
    canonicalName: z.string(),
    variantNames: z.array(z.string()),
    createSupplier: z.boolean(),
  }),
  outputSchema: z.object({
    posUpdated: z.number(),
    supplierCreated: z.boolean(),
  }),
  execute: async ({ input }) => {
    const { canonicalName, variantNames, createSupplier } = input;

    // Variants to replace (exclude canonical itself if included)
    const toReplace = new Set(variantNames.filter(n => n !== canonicalName));
    if (toReplace.size === 0 && !createSupplier) {
      return { posUpdated: 0, supplierCreated: false };
    }

    let posUpdated = 0;

    if (toReplace.size > 0) {
      let offset = 0;
      while (true) {
        const { records, hasMore } = await PurchaseOrders.findAll({
          fields: ['supplierName'],
          limit: 500,
          offset,
        });

        const toUpdate = records.filter(po => toReplace.has(po.supplierName ?? ''));

        for (let i = 0; i < toUpdate.length; i++) {
          await PurchaseOrders.update({ id: toUpdate[i].id, record: { supplierName: canonicalName } });
          posUpdated++;
          if (i > 0 && i % 10 === 0) await sleep(200);
        }

        if (!hasMore) break;
        offset += records.length;
        await sleep(150);
      }
    }

    let supplierCreated = false;
    if (createSupplier) {
      await Suppliers.bulkCreate({
        records: [{ supplierName: canonicalName }],
        matchOn: ['supplierName'],
      });
      supplierCreated = true;
    }

    return { posUpdated, supplierCreated };
  },
});

src/api/reorderRecruitmentRows.ts.content:
import { z } from 'zod';
import { createEndpoint, RecruitmentRows } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Batch update rowOrder for recruitment rows to persist drag-and-drop reordering',
  inputSchema: z.object({
    updates: z.array(z.object({ id: z.string(), rowOrder: z.number() })),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input }) => {
    // Process in chunks of 50 to stay within rate limits
    for (let i = 0; i < input.updates.length; i += 50) {
      const chunk = input.updates.slice(i, i + 50);
      await Promise.all(chunk.map(u => RecruitmentRows.update({ id: u.id, record: { rowOrder: u.rowOrder } })));
    }
    return { success: true };
  },
});

src/api/saveQuotationLineItems.ts.content:
import { z } from 'zod';
import { createEndpoint, CotizacionLineItems, Cotizaciones } from 'zite-integrations-backend-sdk';

const LineItemInput = z.object({
  subRubro: z.string(),
  rubro: z.string(),
  cantidad: z.number(),
  componentes: z.number(),
  unitCost: z.number(),
  hasMarkup: z.boolean(),
  markupPct: z.number(),
  finalPrice: z.number(),
});

export default createEndpoint({
  authenticated: true,
  description: 'Replace all line items for a cotizacion and update totals',
  inputSchema: z.object({
    cotizacionId: z.string(),
    lineItems: z.array(LineItemInput),
    totalCost: z.number(),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input }) => {
    // Delete all existing line items
    const existing = await CotizacionLineItems.findAll({
      filters: { cotizacion: { contains: input.cotizacionId } },
    });
    const toDelete = existing.records.filter(r => {
      const ids = Array.isArray(r.cotizacion) ? r.cotizacion : r.cotizacion ? [r.cotizacion] : [];
      return ids.includes(input.cotizacionId);
    });
    await Promise.all(toDelete.map(r => CotizacionLineItems.delete({ id: r.id })));

    // Bulk create new ones
    if (input.lineItems.length > 0) {
      await CotizacionLineItems.bulkCreate({
        records: input.lineItems.map(li => ({
          ...li,
          cotizacion: [input.cotizacionId],
        })),
      });
    }

    // Recalculate both totals from line items
    const totalCost   = input.lineItems.reduce((sum, li) => sum + li.cantidad * li.componentes * li.unitCost, 0);
    const clientPrice = input.lineItems.reduce((sum, li) => sum + li.finalPrice, 0);
    await Cotizaciones.update({
      id: input.cotizacionId,
      record: { totalCost, clientPrice },
    });

    return { success: true };
  },
});

src/api/syncCalendarCellValues.ts.content:
import { z } from 'zod';
import { createEndpoint, CalendarEvents, BoardColumns, CellValues } from 'zite-integrations-backend-sdk';

const DATE_NAMES = ['Fecha y hora'];
const DUR_NAMES  = ['Duración (hrs)'];
const LOC_NAMES  = ['Ubicación Interna', 'Ubicación (interna)', 'Espacio', 'Ubicación'];

export default createEndpoint({
  authenticated: true,
  description: 'Sync stale CellValues to match native CalendarEvents fields. Supports dry-run mode.',
  inputSchema: z.object({
    projectCode: z.string().optional(),
    boardId: z.string().optional(),
    dryRun: z.boolean().default(true),
  }),
  outputSchema: z.object({
    scannedEvents: z.number(),
    mismatchedDateCount: z.number(),
    mismatchedDurationCount: z.number(),
    mismatchedLocationCount: z.number(),
    fixedCount: z.number(),
    examples: z.array(z.object({
      eventId: z.string(),
      eventName: z.string(),
      field: z.string(),
      nativeValue: z.any(),
      cellValue: z.any(),
    })),
  }),
  execute: async ({ input }) => {
    const { projectCode, boardId: filterBoardId, dryRun } = input;

    // Load events with optional filters
    const filters: Record<string, any> = {};
    if (projectCode) filters.projectCode = projectCode;
    if (filterBoardId) filters.boardId = filterBoardId;

    let allEvents: any[] = [];
    let offset = 0;
    let hasMore = true;
    while (hasMore) {
      const res = await CalendarEvents.findAll({ filters, offset, limit: 2000 });
      allEvents = allEvents.concat(res.records);
      hasMore = res.hasMore;
      offset += res.records.length;
    }

    // Group by boardId
    const byBoard: Record<string, any[]> = {};
    for (const ev of allEvents) {
      if (!ev.boardId) continue;
      (byBoard[ev.boardId] ??= []).push(ev);
    }

    let mismatchedDateCount = 0;
    let mismatchedDurationCount = 0;
    let mismatchedLocationCount = 0;
    let fixedCount = 0;
    const examples: { eventId: string; eventName: string; field: string; nativeValue: any; cellValue: any }[] = [];

    for (const [bid, events] of Object.entries(byBoard)) {
      const { records: cols } = await BoardColumns.findAll({ filters: { boardId: bid }, limit: 100 });
      const activeCols = cols.filter(c => !c.deletedAt);
      if (activeCols.length === 0) continue;

      const dateCol = activeCols.find(c => DATE_NAMES.includes(c.columnName ?? ''));
      const durCol  = activeCols.find(c => DUR_NAMES.includes(c.columnName ?? ''));
      const locCol  = activeCols.find(c => LOC_NAMES.includes(c.columnName ?? ''));

      // Bulk load cells
      let allCells: any[] = [];
      let cOff = 0;
      let cMore = true;
      while (cMore) {
        const r = await CellValues.findAll({ filters: { boardId: bid }, offset: cOff, limit: 2000 });
        allCells = allCells.concat(r.records);
        cMore = r.hasMore;
        cOff += r.records.length;
      }
      const cellMap: Record<string, any> = {};
      for (const c of allCells) cellMap[`${c.rowId}|${c.columnId}`] = c;

      for (const ev of events) {
        // eventDate
        if (dateCol && ev.eventDate) {
          const cell = cellMap[`${ev.id}|${dateCol.id}`];
          if (cell && cell.dateValue !== ev.eventDate) {
            mismatchedDateCount++;
            examples.push({ eventId: ev.id, eventName: ev.eventName ?? '', field: 'eventDate', nativeValue: ev.eventDate, cellValue: cell.dateValue });
            if (!dryRun) {
              await CellValues.update({ id: cell.id, record: { dateValue: ev.eventDate } });
              fixedCount++;
            }
          }
        }
        // durationHours
        if (durCol && ev.durationHours != null) {
          const cell = cellMap[`${ev.id}|${durCol.id}`];
          if (cell && cell.numberValue !== ev.durationHours) {
            mismatchedDurationCount++;
            examples.push({ eventId: ev.id, eventName: ev.eventName ?? '', field: 'durationHours', nativeValue: ev.durationHours, cellValue: cell.numberValue });
            if (!dryRun) {
              await CellValues.update({ id: cell.id, record: { numberValue: ev.durationHours } });
              fixedCount++;
            }
          }
        }
        // location
        if (locCol && ev.location) {
          const cell = cellMap[`${ev.id}|${locCol.id}`];
          if (cell && cell.textValue !== ev.location) {
            mismatchedLocationCount++;
            examples.push({ eventId: ev.id, eventName: ev.eventName ?? '', field: 'location', nativeValue: ev.location, cellValue: cell.textValue });
            if (!dryRun) {
              await CellValues.update({ id: cell.id, record: { textValue: ev.location } });
              fixedCount++;
            }
          }
        }
      }
    }

    return {
      scannedEvents: allEvents.length,
      mismatchedDateCount,
      mismatchedDurationCount,
      mismatchedLocationCount,
      fixedCount,
      examples: examples.slice(0, 50),
    };
  },
});

