import { useState } from 'react';
import { ParseOdcCsvOutputType } from 'zite-endpoints-sdk';
import { Button } from '@/components/ui/button';
import { FolderPlus, Building2, ChevronDown, ChevronRight, CheckCircle2, MinusCircle } from 'lucide-react';
import SearchableSelect, { SelectOption } from './SearchableSelect';

type Preview = ParseOdcCsvOutputType;

interface Props {
  preview: Preview;
  projectMappings: Record<string, string>;
  supplierMappings: Record<string, string>;
  onProjectMap: (code: string, decision: string) => void;
  onSupplierMap: (key: string, decision: string) => void;
}

export default function OdcMappingPanel({ preview, projectMappings, supplierMappings, onProjectMap, onSupplierMap }: Props) {
  const [showProjects, setShowProjects] = useState(true);
  const [showSuppliers, setShowSuppliers] = useState(true);

  const hasIssues = preview.projectsToCreate.length > 0 || preview.suppliersNotFound.length > 0;
  if (!hasIssues) return null;

  const projectOptions: SelectOption[] = [
    { value: 'create', label: '➕ Crear proyecto nuevo' },
    { value: 'skip', label: '⏭️ Dejar sin vincular', sub: 'Se importa la ODC sin proyecto' },
    ...preview.existingProjects.map(p => ({
      value: p.code,
      label: p.code,
      sub: p.fullName || undefined,
    })),
  ];

  const supplierOptions: SelectOption[] = [
    { value: 'raw', label: '📝 Guardar nombre del CSV' },
    { value: 'create', label: '➕ Crear proveedor nuevo en BD' },
    ...preview.existingSuppliers.map(s => ({
      value: s.name,
      label: s.name,
      sub: s.rfc ? `RFC: ${s.rfc}` : undefined,
    })),
  ];

  const projectDecisionLabel = (decision: string) => {
    if (!decision || decision === 'create') return '➕ Crear proyecto nuevo';
    return decision;
  };

  const supplierDecisionLabel = (decision: string) => {
    if (!decision || decision === 'raw') return '📝 Guardar nombre del CSV';
    if (decision === 'create') return '➕ Crear proveedor nuevo en BD';
    return decision;
  };

  return (
    <div className="space-y-3">
      {/* Projects */}
      {preview.projectsToCreate.length > 0 && (
        <div className="rounded-xl border border-amber-200 bg-amber-50/50 p-4 space-y-3">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <FolderPlus className="w-4 h-4 text-amber-600" />
              <p className="text-sm font-medium text-amber-800">
                {preview.projectsToCreate.length} proyectos no encontrados en BD
              </p>
            </div>
            <Button size="sm" variant="ghost" className="text-amber-700 text-xs h-7 gap-1" onClick={() => setShowProjects(p => !p)}>
              {showProjects ? <ChevronDown className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />}
              {showProjects ? 'Colapsar' : 'Resolver'}
            </Button>
          </div>
          {showProjects && (
            <div className="space-y-2">
              <p className="text-xs text-amber-700">
                Para cada proyecto del CSV, elige si crearlo nuevo o vincularlo a uno existente:
              </p>
              {preview.projectsToCreate.map(code => {
                const decision = projectMappings[code] ?? 'create';
                const isLinkedToExisting = decision !== 'create' && decision !== 'skip';
                const isSkip = decision === 'skip';
                return (
                  <div key={code} className="flex items-center gap-3 bg-white/60 rounded-lg px-3 py-2 border border-amber-100">
                    <div className="flex-1 min-w-0">
                      <p className="text-xs font-semibold text-foreground truncate">{code}</p>
                    </div>
                    {isLinkedToExisting && <CheckCircle2 className="w-3.5 h-3.5 text-primary shrink-0" />}
                    {isSkip && <MinusCircle className="w-3.5 h-3.5 text-muted-foreground shrink-0" />}
                    <SearchableSelect
                      value={decision}
                      onChange={v => onProjectMap(code, v)}
                      options={projectOptions}
                      placeholder="Elegir acción…"
                    />
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {/* Suppliers */}
      {preview.suppliersNotFound.length > 0 && (
        <div className="rounded-xl border border-orange-200 bg-orange-50/40 p-4 space-y-3">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Building2 className="w-4 h-4 text-orange-600" />
              <p className="text-sm font-medium text-orange-800">
                {preview.suppliersNotFound.length} proveedores sin match por RFC/email/nombre
              </p>
            </div>
            <Button size="sm" variant="ghost" className="text-orange-700 text-xs h-7 gap-1" onClick={() => setShowSuppliers(p => !p)}>
              {showSuppliers ? <ChevronDown className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />}
              {showSuppliers ? 'Colapsar' : 'Resolver'}
            </Button>
          </div>
          {showSuppliers && (
            <div className="space-y-2">
              <p className="text-xs text-orange-700">
                Para cada proveedor, elige si guardar el nombre tal como viene, crear en BD, o vincularlo a uno existente:
              </p>
              {preview.suppliersNotFound.map((s, i) => {
                const key = s.rfc || s.name || `row-${i}`;
                const decision = supplierMappings[key] ?? (s.suggestedMatch ?? 'raw');
                const isLinked = decision !== 'raw' && decision !== 'create';
                const isCreating = decision === 'create';
                const hasSuggestion = !!s.suggestedMatch && (s.suggestedScore ?? 0) > 0.4;
                const isUsingSuggestion = hasSuggestion && decision === s.suggestedMatch;
                return (
                  <div key={key} className="flex items-start gap-3 bg-white/60 rounded-lg px-3 py-2 border border-orange-100">
                    <div className="flex-1 min-w-0">
                      <p className="text-xs font-semibold text-foreground truncate">{s.name || '—'}</p>
                      <div className="flex items-center gap-1.5 mt-0.5 flex-wrap">
                        <p className="text-[10px] text-muted-foreground">
                          {s.rfc ? `RFC: ${s.rfc}` : 'Sin RFC'} · {s.odcCount} ODC{s.odcCount !== 1 ? 's' : ''}
                        </p>
                        {hasSuggestion && isUsingSuggestion && (
                          <span className="text-[10px] px-1.5 py-0.5 rounded bg-primary/10 text-primary font-medium border border-primary/20">
                            ✨ sugerido {s.suggestedScore ? `${Math.round(s.suggestedScore * 100)}%` : ''}
                          </span>
                        )}
                        {hasSuggestion && !isUsingSuggestion && decision === 'raw' && (
                          <span className="text-[10px] px-1.5 py-0.5 rounded bg-muted text-muted-foreground border border-border">
                            posible: {s.suggestedMatch}
                          </span>
                        )}
                      </div>
                    </div>
                    {(isLinked || isCreating) && (
                      <CheckCircle2 className={`w-3.5 h-3.5 shrink-0 mt-0.5 ${isCreating ? 'text-amber-500' : 'text-primary'}`} />
                    )}
                    <SearchableSelect
                      value={decision}
                      onChange={v => onSupplierMap(key, v)}
                      options={supplierOptions}
                      placeholder="Elegir acción…"
                    />
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

src/components/PendingSavesBar.tsx.content:
import { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Loader2, CheckCircle2, AlertCircle } from 'lucide-react';
import { Progress } from '@/components/ui/progress';
import { subscribeToPendingSaves, getPendingSaveState } from '../hooks/useDynamicColumns';

export default function PendingSavesBar() {
  const [state, setState] = useState(getPendingSaveState());

  useEffect(() => {
    const unsub = subscribeToPendingSaves(() => {
      setState(getPendingSaveState());
    });
    return unsub;
  }, []);

  const { pending, completed, failed, total } = state;
  const isActive = total > 0;
  const isDone   = isActive && pending === 0;
  const progress = total > 0 ? Math.round(((completed + failed) / total) * 100) : 0;

  return (
    <AnimatePresence>
      {isActive && (
        <motion.div
          key="pending-saves-bar"
          initial={{ y: 60, opacity: 0 }}
          animate={{ y: 0,  opacity: 1 }}
          exit={{ y: 60, opacity: 0 }}
          transition={{ type: 'spring', stiffness: 380, damping: 32 }}
          className="fixed bottom-4 left-1/2 -translate-x-1/2 z-50 pointer-events-none"
        >
          <div className="bg-card border border-border shadow-lg rounded-xl px-4 py-2.5 flex items-center gap-3 min-w-[280px] max-w-sm">
            {/* Icon */}
            {!isDone ? (
              <Loader2 className="w-4 h-4 text-primary animate-spin flex-shrink-0" />
            ) : failed > 0 ? (
              <AlertCircle className="w-4 h-4 text-destructive flex-shrink-0" />
            ) : (
              <CheckCircle2 className="w-4 h-4 text-chart-2 flex-shrink-0" />
            )}

            {/* Text + bar */}
            <div className="flex-1 min-w-0">
              {!isDone ? (
                <>
                  <p className="text-xs font-medium text-foreground leading-tight">
                    Guardando cambios&hellip;&nbsp;
                    <span className="text-muted-foreground font-normal">
                      {completed + failed} de {total}
                    </span>
                  </p>
                  <Progress value={progress} className="h-1 mt-1.5" />
                </>
              ) : failed > 0 ? (
                <p className="text-xs font-medium text-destructive leading-tight">
                  {failed} cambio{failed !== 1 ? 's' : ''} no se pudi{failed !== 1 ? 'eron' : 'o'} guardar
                </p>
              ) : (
                <p className="text-xs font-medium text-chart-2 leading-tight">
                  Todos los cambios guardados ✓
                </p>
              )}
            </div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

src/components/pm/BoardTabsBar.tsx.content:
import React, { useRef, useState } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Plus, Trash2, Copy, X } from 'lucide-react';
import type { BoardObj } from './pmTypes';

interface BoardBadge {
  version?: number;
  url?: string;
  status?: string;
}

interface BoardTabsBarProps {
  boards: string[];
  boardObjects?: BoardObj[];
  activeBoard: string;
  onActiveBoardChange: (board: string) => void;
  adding: boolean;
  setAdding: (v: boolean) => void;
  newBoardName: string;
  setNewBoardName: (v: string) => void;
  onAddBoard: () => void;
  onDuplicateBoard: (boardName: string) => void;
  onDeleteBoard: (boardIdOrName: string) => void;
  onReorder: (fromIdx: number, toIdx: number) => void;
  onRenameBoard?: (keyOrOldName: string, newName: string) => void;
  addLabel: string;
  inputPlaceholder: string;
  getBadge?: (keyOrName: string) => BoardBadge | undefined;
}

export function BoardTabsBar({
  boards,
  boardObjects,
  activeBoard,
  onActiveBoardChange,
  adding,
  setAdding,
  newBoardName,
  setNewBoardName,
  onAddBoard,
  onDuplicateBoard,
  onDeleteBoard,
  onReorder,
  onRenameBoard,
  addLabel,
  inputPlaceholder,
  getBadge,
}: BoardTabsBarProps) {
  const dragIdxRef = useRef<number>(-1);
  const [dragOverIdx, setDragOverIdx] = useState<number>(-1);
  // editingBoard stores the item key (UUID when boardObjects present, name otherwise)
  const [editingBoard, setEditingBoard] = useState<string | null>(null);
  const [editingValue, setEditingValue] = useState('');

  // Unified items array: key for identity, label for display
  const items = boardObjects
    ? boardObjects.map(b => ({ key: b.id, label: b.name }))
    : boards.map(b => ({ key: b, label: b }));

  const displayItems = items;

  const startEdit = (key: string, label: string) => {
    setEditingBoard(key);
    setEditingValue(label);
  };

  const commitEdit = (key: string, originalLabel: string) => {
    const trimmed = editingValue.trim();
    setEditingBoard(null);
    if (trimmed && trimmed !== originalLabel) {
      onRenameBoard?.(key, trimmed);
    }
  };

  const cancelEdit = () => {
    setEditingBoard(null);
    setEditingValue('');
  };

  return (
    <div className="flex items-center gap-0.5 px-4 pt-3 border-b border-border bg-card overflow-x-auto flex-shrink-0 min-w-0 scrollbar-thin">
      {displayItems.map((item, idx) => {
        const isDropTarget = dragOverIdx === idx && dragIdxRef.current !== idx;
        const badge = getBadge?.(item.key);
        const isEditing = editingBoard === item.key;
        return (
          <div
            key={item.key}
            draggable={!isEditing}
            onDragStart={e => { dragIdxRef.current = idx; e.dataTransfer.effectAllowed = 'move'; }}
            onDragOver={e => { e.preventDefault(); setDragOverIdx(idx); }}
            onDragLeave={() => setDragOverIdx(-1)}
            onDrop={e => { e.preventDefault(); onReorder(dragIdxRef.current, idx); setDragOverIdx(-1); }}
            onDragEnd={() => { dragIdxRef.current = -1; setDragOverIdx(-1); }}
            className={`group/tab flex-shrink-0 flex items-center border-b-2 transition-colors whitespace-nowrap ${isEditing ? 'cursor-text' : 'cursor-grab active:cursor-grabbing'} relative ${
              activeBoard === item.key ? 'border-primary' : 'border-transparent'
            } ${isDropTarget ? 'border-l-2 border-l-primary' : ''}`}
          >
            {isEditing ? (
              <Input
                className="h-7 w-32 text-sm px-2 my-1 mx-1"
                value={editingValue}
                onChange={e => setEditingValue(e.target.value)}
                onKeyDown={e => {
                  if (e.key === 'Enter') { e.preventDefault(); commitEdit(item.key, item.label); }
                  if (e.key === 'Escape') { e.preventDefault(); cancelEdit(); }
                }}
                onBlur={() => commitEdit(item.key, item.label)}
                autoFocus
                onClick={e => e.stopPropagation()}
              />
            ) : (
              <button
                onClick={() => onActiveBoardChange(item.key)}
                onDoubleClick={e => { e.preventDefault(); if (onRenameBoard) startEdit(item.key, item.label); }}
                className={`px-3 py-2 text-sm font-medium transition-colors flex items-center gap-1.5 ${
                  activeBoard === item.key ? 'text-primary' : 'text-muted-foreground hover:text-foreground'
                }`}
                title={`${item.label} · ${item.key.slice(0, 6)}${onRenameBoard ? ' · Doble clic para renombrar' : ''}`}
              >
                {item.label}
                {badge?.version && (
                  <a
                    href={badge.url ?? '#'}
                    target="_blank"
                    rel="noopener noreferrer"
                    onClick={e => { e.stopPropagation(); if (!badge.url) e.preventDefault(); }}
                    title={badge.url ? 'Abrir archivo Excel' : `V${badge.version}`}
                    className="inline-flex items-center gap-0.5 text-[10px] font-semibold px-1.5 py-0.5 rounded-full bg-emerald-100 text-emerald-700 hover:bg-emerald-200 transition-colors"
                  >
                    V{badge.version} ✓
                  </a>
                )}
              </button>
            )}
            {!isEditing && (
              <>
                <button
                  onClick={e => { e.stopPropagation(); onDuplicateBoard(item.label); }}
                  className="opacity-0 group-hover/tab:opacity-100 transition-opacity p-0.5 rounded text-muted-foreground/40 hover:text-primary hover:bg-primary/10"
                  title={`Duplicar "${item.label}"`}
                >
                  <Copy className="w-3 h-3" />
                </button>
                <button
                  onClick={e => { e.stopPropagation(); onDeleteBoard(item.key); }}
                  className="opacity-0 group-hover/tab:opacity-100 transition-opacity p-0.5 mr-1 rounded text-muted-foreground/40 hover:text-destructive hover:bg-destructive/10"
                  title={`Eliminar "${item.label}"`}
                >
                  <Trash2 className="w-3 h-3" />
                </button>
              </>
            )}
          </div>
        );
      })}

      {adding ? (
        <div className="flex items-center gap-1 px-2 py-1 flex-shrink-0">
          <Input
            className="h-7 w-36 text-xs"
            placeholder={inputPlaceholder}
            value={newBoardName}
            onChange={e => setNewBoardName(e.target.value)}
            onKeyDown={e => {
              if (e.key === 'Enter') onAddBoard();
              if (e.key === 'Escape') setAdding(false);
            }}
            autoFocus
          />
          <Button size="sm" className="h-7 text-xs px-2" onClick={onAddBoard}>OK</Button>
          <Button size="sm" variant="ghost" className="h-7 w-7 p-0" onClick={() => setAdding(false)}>
            <X className="w-3 h-3" />
          </Button>
        </div>
      ) : (
        <button
          onClick={() => setAdding(true)}
          className="px-3 py-2 text-xs text-muted-foreground hover:text-foreground flex items-center gap-1 flex-shrink-0 whitespace-nowrap transition-colors"
        >
          <Plus className="w-3 h-3" /> {addLabel}
        </button>
      )}
    </div>
  );
}

src/components/pm/TimelineCell.tsx.content:
import { useState, useMemo } from 'react';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Calendar } from '@/components/ui/calendar';
import { CalendarDays } from 'lucide-react';
import { format, isSameMonth, isSameYear } from 'date-fns';
import { es } from 'date-fns/locale/es';
import { fmt, toISO, normalizeRange } from './pmDateUtils';

export function TimelineCell({ taskId, startDate, endDate, onSave }: {
  taskId: string;
  startDate: string;
  endDate: string;
  onSave: (taskId: string, start: string, end: string) => void;
}) {
  const [open, setOpen]           = useState(false);
  const [anchorDate, setAnchorDate] = useState<Date | undefined>(undefined);
  const [hoverDate,  setHoverDate]  = useState<Date | undefined>(undefined);

  const startParsed = useMemo(() => startDate ? (() => { const d = new Date(startDate + 'T00:00:00'); return isNaN(d.getTime()) ? undefined : d; })() : undefined, [startDate]);
  const endParsed   = useMemo(() => endDate   ? (() => { const d = new Date(endDate   + 'T00:00:00'); return isNaN(d.getTime()) ? undefined : d; })() : undefined, [endDate]);

  const committedRange = useMemo(() => {
    if (startParsed && endParsed) return normalizeRange(startParsed, endParsed);
    if (startParsed) return { from: startParsed, to: startParsed };
    return undefined;
  }, [startParsed, endParsed]);

  const previewRange = useMemo(() => {
    if (!anchorDate) return undefined;
    return normalizeRange(anchorDate, hoverDate ?? anchorDate);
  }, [anchorDate, hoverDate]);

  const defaultMonth = startParsed ?? endParsed ?? new Date();

  // Compact label
  const label = (() => {
    if (!startParsed && !endParsed) return null;
    if (startParsed && endParsed) {
      const year = endParsed.getFullYear();
      if (isSameMonth(startParsed, endParsed) && isSameYear(startParsed, endParsed)) {
        return `${startParsed.getDate()} → ${endParsed.getDate()} ${format(endParsed, 'MMM yyyy', { locale: es }).replace(/\.$/, '')}`;
      }
      if (isSameYear(startParsed, endParsed)) {
        return `${fmt(startParsed)} → ${fmt(endParsed)} ${year}`;
      }
      return `${fmt(startParsed)} ${startParsed.getFullYear()} → ${fmt(endParsed)} ${year}`;
    }
    if (startParsed) return `${fmt(startParsed)} →`;
    return `→ ${fmt(endParsed!)}`;
  })();

  const hasRange = !!(startParsed && endParsed);

  const handleDayClick = (day: Date) => {
    const clicked = new Date(day); clicked.setHours(0, 0, 0, 0);

    if (!anchorDate) {
      // First click — set anchor, keep popover open for second click
      setAnchorDate(clicked);
      setHoverDate(clicked);
      return;
    }

    // Second click — finalize range, save, close
    const range = normalizeRange(anchorDate, clicked);
    onSave(taskId, toISO(range.from), toISO(range.to));
    setAnchorDate(undefined);
    setHoverDate(undefined);
    setOpen(false);
  };

  const handleOpenChange = (next: boolean) => {
    setOpen(next);
    if (!next) {
      setAnchorDate(undefined);
      setHoverDate(undefined);
    }
  };

  // Build modifiers for visual feedback
  const visibleRange = previewRange ?? committedRange;
  const modifiers: Record<string, Date | { from: Date; to: Date } | undefined> = {};
  const modifiersClassNames: Record<string, string> = {};

  if (visibleRange) {
    if (anchorDate) {
      // In-progress selection: show preview range
      modifiers.previewInner = { from: visibleRange.from, to: visibleRange.to };
      modifiers.previewStart = visibleRange.from;
      modifiers.previewEnd   = visibleRange.to;
      modifiersClassNames.previewInner = 'bg-accent/50 text-foreground !rounded-none';
      modifiersClassNames.previewStart = '!bg-primary !text-primary-foreground !rounded-l-md !rounded-r-none';
      modifiersClassNames.previewEnd   = '!bg-primary !text-primary-foreground !rounded-r-md !rounded-l-none';
    } else {
      // Committed (saved) range
      modifiers.committed      = { from: visibleRange.from, to: visibleRange.to };
      modifiers.committedStart = visibleRange.from;
      modifiers.committedEnd   = visibleRange.to;
      modifiersClassNames.committed      = 'bg-primary/15 text-foreground !rounded-none';
      modifiersClassNames.committedStart = '!bg-primary !text-primary-foreground !rounded-l-md !rounded-r-none';
      modifiersClassNames.committedEnd   = '!bg-primary !text-primary-foreground !rounded-r-md !rounded-l-none';
    }
  }

  return (
    <Popover open={open} onOpenChange={handleOpenChange} modal>
      <PopoverTrigger asChild>
        <button
          className={`group/tc flex items-center gap-1.5 w-full h-full px-2.5 py-1 text-left transition-colors hover:bg-primary/10 ${hasRange ? 'bg-primary/5' : ''}`}
          style={{ minHeight: 28 }}
        >
          {label ? (
            <span className="text-[11px] font-medium text-foreground tabular-nums leading-none">{label}</span>
          ) : (
            <span className="flex items-center gap-1 text-xs text-muted-foreground/30">
              <span>—</span>
              <CalendarDays className="w-3 h-3 opacity-0 group-hover/tc:opacity-100 transition-opacity" />
            </span>
          )}
        </button>
      </PopoverTrigger>
      <PopoverContent
        className="w-auto p-0"
        align="start"
        sideOffset={4}
        onOpenAutoFocus={e => e.preventDefault()}
      >
        {anchorDate && (
          <div className="px-3 pt-2.5 pb-0 text-xs text-muted-foreground">
            Ahora selecciona la fecha de fin…
          </div>
        )}
        <Calendar
          mode="default"
          defaultMonth={defaultMonth}
          numberOfMonths={2}
          locale={es}
          onDayClick={handleDayClick}
          onDayMouseEnter={(day) => {
            if (!anchorDate) return;
            const d = new Date(day); d.setHours(0, 0, 0, 0);
            setHoverDate(d);
          }}
          onDayMouseLeave={() => {
            if (anchorDate) setHoverDate(anchorDate);
          }}
          modifiers={modifiers as Parameters<typeof Calendar>[0]['modifiers']}
          modifiersClassNames={modifiersClassNames}
        />
        {(startDate || endDate) && (
          <div className="px-3 pb-2.5 border-t border-border/30 pt-2">
            <button
              className="text-xs text-muted-foreground hover:text-destructive transition-colors"
              onClick={() => { onSave(taskId, '', ''); setAnchorDate(undefined); setHoverDate(undefined); setOpen(false); }}
            >
              Limpiar fechas
            </button>
          </div>
        )}
      </PopoverContent>
    </Popover>
  );
}

