import { useState, useEffect, useMemo, useRef } from 'react';
import { getSupplierInvoices, getSupplierInvoiceById, reviewSupplierInvoice, getPoLineItems, GetSupplierInvoicesOutputType, GetSupplierInvoiceByIdOutputType, GetPoLineItemsOutputType } from 'zite-endpoints-sdk';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Switch } from '@/components/ui/switch';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Skeleton } from '@/components/ui/skeleton';
import { Separator } from '@/components/ui/separator';
import { ScrollArea } from '@/components/ui/scroll-area';
import { toast } from 'sonner';
import {
  FileText, CheckCircle2, Clock, XCircle, ExternalLink,
  AlertCircle, FileX, ChevronDown, ChevronRight, Bell,
} from 'lucide-react';

type InvoiceListItem = GetSupplierInvoicesOutputType['invoices'][0];
type InvoiceDetail = NonNullable<GetSupplierInvoiceByIdOutputType['invoice']>;
type Stats = GetSupplierInvoicesOutputType['stats'];

const STATUS_STYLES: Record<string, string> = {
  'Pendiente':   'bg-orange-100 text-orange-700 border-orange-200',
  'En revisión': 'bg-blue-100 text-blue-700 border-blue-200',
  'Validada':    'bg-green-100 text-green-700 border-green-200',
  'Rechazada':   'bg-red-100 text-red-700 border-red-200',
};

function fmtCurrency(amount?: number, currency?: string) {
  if (!amount) return '—';
  return `${currency === 'USD' ? 'USD ' : '$'}${amount.toLocaleString('es-MX', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}
function fmtDate(s?: string) { if (!s) return '—'; return new Date(s).toLocaleDateString('es-MX'); }

function isNew(uploadDate?: string | null) {
  if (!uploadDate) return false;
  return Date.now() - new Date(uploadDate).getTime() < 48 * 60 * 60 * 1000;
}

// ── Stat card ────────────────────────────────────────────────────────────────
function StatCard({ label, value, icon: Icon, color }: { label: string; value: string | number; icon: React.ElementType; color: string }) {
  return (
    <div className="bg-card border border-border rounded-xl p-4 flex items-center gap-3">
      <div className={`w-10 h-10 rounded-lg flex items-center justify-center shrink-0 ${color}`}>
        <Icon className="w-5 h-5" />
      </div>
      <div>
        <p className="text-xl font-bold">{value}</p>
        <p className="text-xs text-muted-foreground">{label}</p>
      </div>
    </div>
  );
}

// ── File link ────────────────────────────────────────────────────────────────
function FileLink({ label, url }: { label: string; url: string }) {
  return (
    <a href={url} target="_blank" rel="noopener noreferrer"
      className="flex items-center gap-2 px-3 py-2 rounded-lg border border-border hover:bg-muted/50 transition-colors text-sm">
      <FileText className="w-4 h-4 text-muted-foreground shrink-0" />
      <span className="flex-1 truncate">{label}</span>
      <ExternalLink className="w-3.5 h-3.5 text-muted-foreground shrink-0" />
    </a>
  );
}

// ── Invoice group section ─────────────────────────────────────────────────────
interface GroupProps {
  title: string;
  count: number;
  icon: React.ElementType;
  headerClass: string;
  defaultOpen: boolean;
  invoices: InvoiceListItem[];
  onSelect: (inv: InvoiceListItem) => void;
}

function InvoiceGroup({ title, count, icon: Icon, headerClass, defaultOpen, invoices, onSelect }: GroupProps) {
  const [open, setOpen] = useState(defaultOpen);

  if (count === 0) return null;

  return (
    <div className="border border-border rounded-xl overflow-hidden">
      {/* Section header */}
      <button
        onClick={() => setOpen(o => !o)}
        className={`w-full flex items-center gap-3 px-4 py-3 text-left transition-colors ${headerClass}`}
      >
        <Icon className="w-4 h-4 shrink-0" />
        <span className="font-semibold text-sm flex-1">{title}</span>
        <span className="text-xs font-medium px-2 py-0.5 rounded-full bg-background/60 border border-border/50">{count}</span>
        {open ? <ChevronDown className="w-4 h-4 opacity-60" /> : <ChevronRight className="w-4 h-4 opacity-60" />}
      </button>

      {/* Rows */}
      {open && (
        <div className="bg-card">
          <table className="w-full text-sm">
            <thead className="bg-muted/40 border-t border-border">
              <tr>
                <th className="text-left px-4 py-2.5 text-xs font-semibold">Proveedor</th>
                <th className="text-left px-4 py-2.5 text-xs font-semibold"># Factura</th>
                <th className="text-left px-4 py-2.5 text-xs font-semibold">ODC</th>
                <th className="text-left px-4 py-2.5 text-xs font-semibold">Monto</th>
                <th className="text-left px-4 py-2.5 text-xs font-semibold">Estado</th>
                <th className="text-left px-4 py-2.5 text-xs font-semibold">Fecha</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border">
              {invoices.map(inv => (
                <tr key={inv.id}
                  className="hover:bg-muted/30 transition-colors cursor-pointer"
                  onClick={() => onSelect(inv)}>
                  <td className="px-4 py-3 font-medium">
                    <div className="flex items-center gap-2">
                      {inv.supplierName || '—'}
                      {isNew(inv.uploadDate) && (
                        <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-primary text-primary-foreground leading-none">
                          Nueva
                        </span>
                      )}
                    </div>
                  </td>
                  <td className="px-4 py-3 font-mono text-xs">{inv.invoiceNumber || '—'}</td>
                  <td className="px-4 py-3 text-muted-foreground font-mono text-xs">#{inv.poNumber || '—'}</td>
                  <td className="px-4 py-3 font-semibold whitespace-nowrap">{fmtCurrency(inv.amount ?? undefined, inv.currency ?? undefined)}</td>
                  <td className="px-4 py-3">
                    {inv.status && (
                      <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-medium border ${STATUS_STYLES[inv.status] ?? 'bg-muted text-muted-foreground border-border'}`}>
                        {inv.status}
                      </span>
                    )}
                  </td>
                  <td className="px-4 py-3 text-muted-foreground whitespace-nowrap">{fmtDate(inv.uploadDate)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

// ── Invoice detail dialog ─────────────────────────────────────────────────────
// Parse paymentTerms string → number of days
function paymentTermsToDays(terms?: string | null): number {
  if (!terms) return 30;
  if (terms === 'Contado') return 0;
  const match = terms.match(/(\d+)/);
  return match ? parseInt(match[1]) : 30;
}

function defaultPaymentDate(terms?: string | null): string {
  const days = paymentTermsToDays(terms);
  const d = new Date();
  d.setDate(d.getDate() + days);
  return d.toISOString().split('T')[0];
}

function InvoiceDetailDialog({ invoiceId, open, onClose, onRefresh }: {
  invoiceId: string | null; open: boolean; onClose: () => void; onRefresh: () => void;
}) {
  const [invoice, setInvoice] = useState<InvoiceDetail | null>(null);
  const [loadingDetail, setLoadingDetail] = useState(false);
  const [lineItems, setLineItems] = useState<GetPoLineItemsOutputType['lineItems']>([]);
  const [loadingLines, setLoadingLines] = useState(false);
  const [notes, setNotes] = useState('');
  const [rejectReason, setRejectReason] = useState('');
  const [rejectReasonError, setRejectReasonError] = useState(false);
  const [saving, setSaving] = useState<'validar' | 'rechazar' | null>(null);
  const [confirmingValidation, setConfirmingValidation] = useState(false);
  const [confirmingRejection, setConfirmingRejection] = useState(false);
  const [paymentDate, setPaymentDate] = useState('');

  // Editable tax breakdown
  const [editSubtotal, setEditSubtotal] = useState('');
  const [editIvaEnabled, setEditIvaEnabled] = useState(false);
  const [editIvaMode, setEditIvaMode] = useState<'percent' | 'amount'>('percent');
  const [editIvaRate, setEditIvaRate] = useState('16');
  const [editIvaFixedAmount, setEditIvaFixedAmount] = useState('');
  const [editRetencionIva, setEditRetencionIva] = useState('');
  const [editRetencionIsr, setEditRetencionIsr] = useState('');

  // Derived totals from editable fields
  const eSub    = parseFloat(editSubtotal) || 0;
  const eIvaAmt = !editIvaEnabled ? 0 : editIvaMode === 'percent'
    ? eSub * ((parseFloat(editIvaRate) || 0) / 100)
    : (parseFloat(editIvaFixedAmount) || 0);
  const eRetIva = parseFloat(editRetencionIva) || 0;
  const eRetIsr = parseFloat(editRetencionIsr) || 0;
  const eTotal  = eSub + eIvaAmt - eRetIva - eRetIsr;

  useEffect(() => {
    if (open && invoiceId) {
      setInvoice(null);
      setLineItems([]);
      setLoadingDetail(true);
      getSupplierInvoiceById({ invoiceId })
        .then(r => {
          const inv = r.invoice;
          if (!inv) return;
          setInvoice(inv);
          setNotes(inv.reviewNotes ?? '');
          setRejectReason('');
          setRejectReasonError(false);
          setConfirmingValidation(false);
          setConfirmingRejection(false);
          setPaymentDate(defaultPaymentDate(inv.poPaymentTerms));

          const sub = inv.subtotal ?? inv.amount ?? 0;
          setEditSubtotal(sub > 0 ? String(sub) : '');
          const hasIvaByRate = (inv.ivaRate ?? 0) > 0;
          const hasIvaByAmount = (inv.ivaAmount ?? 0) > 0;
          setEditIvaEnabled(hasIvaByRate || hasIvaByAmount);
          if (hasIvaByRate) {
            setEditIvaMode('percent');
            setEditIvaRate(((inv.ivaRate! * 100)).toFixed(0));
            setEditIvaFixedAmount('');
          } else if (hasIvaByAmount) {
            setEditIvaMode('amount');
            setEditIvaFixedAmount(String(inv.ivaAmount));
            setEditIvaRate('16');
          } else {
            setEditIvaMode('percent');
            setEditIvaRate('16');
            setEditIvaFixedAmount('');
          }
          setEditRetencionIva(inv.retencionIva ? String(inv.retencionIva) : '');
          setEditRetencionIsr(inv.retencionIsr ? String(inv.retencionIsr) : '');

          if (inv.poId) {
            setLoadingLines(true);
            getPoLineItems({ poId: inv.poId })
              .then(lr => setLineItems(lr.lineItems))
              .catch(() => {})
              .finally(() => setLoadingLines(false));
          }
        })
        .catch(() => {})
        .finally(() => setLoadingDetail(false));
    }
  }, [open, invoiceId]);

  const handleValidarClick = () => {
    setPaymentDate(defaultPaymentDate(invoice?.poPaymentTerms));
    setConfirmingValidation(true);
  };

  const handleRejectClick = () => {
    setConfirmingRejection(true);
    setRejectReasonError(false);
  };

  const handleAction = async (action: 'validar' | 'rechazar') => {
    if (!invoice) return;
    if (action === 'rechazar' && !rejectReason.trim()) {
      setRejectReasonError(true);
      return;
    }
    setSaving(action);
    try {
      await reviewSupplierInvoice({
        invoiceId: invoice.id,
        action,
        notes: action === 'rechazar' ? rejectReason : (notes || undefined),
        scheduledPaymentDate: action === 'validar' ? paymentDate : undefined,
        ...(action === 'validar' ? {
          validatedSubtotal: eSub || undefined,
          validatedIvaRate: editIvaEnabled && editIvaMode === 'percent' ? (parseFloat(editIvaRate) || 0) / 100 : undefined,
          validatedIvaAmount: eIvaAmt || undefined,
          validatedRetencionIva: eRetIva || undefined,
          validatedRetencionIsr: eRetIsr || undefined,
          validatedTotal: eTotal || undefined,
        } : {}),
      });
      toast.success(action === 'validar'
        ? `Factura validada ✓ — pago de ${fmtCurrency((eTotal || invoice.amount) ?? undefined, invoice.currency ?? undefined)} programado para ${new Date(paymentDate + 'T12:00:00').toLocaleDateString('es-MX')}`
        : 'Factura rechazada — el proveedor será notificado con el motivo'
      );
      onRefresh();
      onClose();
    } catch {
      toast.error('Error al procesar la factura');
    } finally { setSaving(null); setConfirmingValidation(false); setConfirmingRejection(false); }
  };

  const canReview = invoice ? (invoice.status === 'Pendiente' || invoice.status === 'En revisión') : false;
  const pdfUrl = invoice?.pdfFile?.[0]?.url;

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-6xl w-full h-[90vh] flex flex-col p-0 gap-0 overflow-hidden">
        {(loadingDetail || !invoice) ? (
          <div className="flex flex-col items-center justify-center h-full gap-4">
            <Skeleton className="h-8 w-48" />
            <Skeleton className="h-4 w-32" />
            <div className="grid grid-cols-2 gap-3 w-64 mt-4">
              <Skeleton className="h-16" /><Skeleton className="h-16" />
              <Skeleton className="h-16" /><Skeleton className="h-16" />
            </div>
          </div>
        ) : (
        <>
        <DialogHeader className="px-6 pt-5 pb-4 border-b shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 bg-primary/10 rounded-xl flex items-center justify-center shrink-0">
              <FileText className="w-4 h-4 text-primary" />
            </div>
            <div className="flex-1 min-w-0">
              <DialogTitle className="text-base leading-tight">Factura {invoice.invoiceNumber}</DialogTitle>
              <p className="text-sm text-muted-foreground truncate">{invoice.supplierName}</p>
            </div>
            {isNew(invoice.uploadDate) && (
              <span className="text-[10px] font-bold px-2 py-1 rounded-full bg-primary text-primary-foreground">Nueva</span>
            )}
            {invoice.status && (
              <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-xs font-medium border ${STATUS_STYLES[invoice.status] ?? 'bg-muted text-muted-foreground border-border'}`}>
                {invoice.status}
              </span>
            )}
          </div>
        </DialogHeader>

        <div className="flex flex-1 min-h-0">
          {/* LEFT — PDF viewer */}
          <div className="w-[55%] border-r border-border bg-muted/30 flex flex-col min-w-0">
            {pdfUrl ? (
              <iframe src={pdfUrl} className="w-full h-full border-0" title="Vista previa del PDF" />
            ) : (
              <div className="flex flex-col items-center justify-center h-full gap-3 text-muted-foreground">
                <FileX className="w-14 h-14 opacity-30" />
                <p className="text-sm font-medium">Sin PDF disponible</p>
                <p className="text-xs opacity-60">El proveedor no adjuntó un archivo PDF</p>
              </div>
            )}
          </div>

          {/* RIGHT — Details & actions */}
          <div className="w-[45%] shrink-0 flex flex-col min-h-0">
            <ScrollArea className="flex-1">
              <div className="px-5 py-4 space-y-5">
                <div className="grid grid-cols-2 gap-3">
                  {[
                    ['# Factura', invoice.invoiceNumber],
                    ['Moneda', invoice.currency],
                    ['Subida el', fmtDate(invoice.uploadDate)],
                    ['Subida por', invoice.uploadedBy],
                    ['Proyecto', invoice.projectCode],
                  ].map(([l, v]) => (
                    <div key={l as string}>
                      <p className="text-[11px] text-muted-foreground mb-0.5">{l}</p>
                      <p className="text-sm font-medium break-all">{(v as string) || '—'}</p>
                    </div>
                  ))}
                </div>

                <Separator />

                <div>
                  <p className="text-[11px] font-semibold uppercase tracking-wider text-muted-foreground mb-2">ODC Vinculada</p>
                  <div className="bg-muted/40 rounded-lg p-3 space-y-2">
                    <div className="flex justify-between items-center">
                      <span className="text-xs text-muted-foreground">OC #</span>
                      <span className="text-sm font-mono font-semibold">{invoice.poNumber || '—'}</span>
                    </div>
                    <div className="flex justify-between items-center">
                      <span className="text-xs text-muted-foreground">Monto ODC</span>
                      <span className="text-sm font-semibold">{fmtCurrency(invoice.poTotalAmount ?? undefined)}</span>
                    </div>
                    {invoice.poServiceDescription && (
                      <div>
                        <p className="text-xs text-muted-foreground">Servicio</p>
                        <p className="text-xs mt-0.5">{invoice.poServiceDescription}</p>
                      </div>
                    )}
                    {/* Line items */}
                    {loadingLines && (
                      <div className="border-t border-border/60 pt-2 space-y-1.5">
                        <Skeleton className="h-3 w-full" />
                        <Skeleton className="h-3 w-5/6" />
                        <Skeleton className="h-3 w-4/6" />
                      </div>
                    )}
                    {!loadingLines && lineItems.length > 0 && (
                      <div className="border-t border-border/60 pt-2">
                        <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wide mb-1.5">Líneas de la ODC</p>
                        <div className="overflow-x-auto">
                          <table className="w-full text-[11px]">
                            <thead>
                              <tr className="border-b border-border/60">
                                <th className="text-left pb-1 text-muted-foreground font-medium">Descripción</th>
                                <th className="text-left pb-1 text-muted-foreground font-medium">Cat.</th>
                                <th className="text-right pb-1 text-muted-foreground font-medium">Cant.</th>
                                <th className="text-right pb-1 text-muted-foreground font-medium">P.U.</th>
                                <th className="text-right pb-1 text-muted-foreground font-medium">Total</th>
                              </tr>
                            </thead>
                            <tbody className="divide-y divide-border/40">
                              {lineItems.map(li => (
                                <tr key={li.id}>
                                  <td className="py-1 pr-1 leading-snug">{li.description || '—'}</td>
                                  <td className="py-1 pr-1 text-muted-foreground whitespace-nowrap">{li.category || '—'}</td>
                                  <td className="py-1 text-right whitespace-nowrap">{li.quantity}</td>
                                  <td className="py-1 pl-1 text-right whitespace-nowrap">{fmtCurrency(li.unitPrice, invoice.currency ?? undefined)}</td>
                                  <td className="py-1 pl-1 text-right font-semibold whitespace-nowrap">{fmtCurrency(li.total, invoice.currency ?? undefined)}</td>
                                </tr>
                              ))}
                            </tbody>
                          </table>
                        </div>
                      </div>
                    )}
                  </div>
                </div>

                {/* ── Tax breakdown ──────────────────────────── */}
                <Separator />
                <div>
                  <div className="flex items-center justify-between mb-2">
                    <p className="text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">Desglose fiscal</p>
                    {canReview && (
                      <span className="text-[10px] text-muted-foreground italic">Verifica con el PDF →</span>
                    )}
                  </div>

                  {canReview ? (
                    /* Editable breakdown for pending/in-review */
                    <div className="space-y-2.5 rounded-lg border border-border bg-muted/20 p-3">
                      {/* Subtotal */}
                      <div className="space-y-1">
                        <Label className="text-xs">Subtotal (sin IVA)</Label>
                        <Input
                          type="number" min={0} placeholder="0.00"
                          value={editSubtotal}
                          onChange={e => setEditSubtotal(e.target.value)}
                          className="h-8 text-sm"
                        />
                      </div>
                      {/* IVA toggle */}
                      <div className="space-y-2">
                        <div className="flex items-center gap-2.5">
                          <Switch id="iva-sw" checked={editIvaEnabled} onCheckedChange={setEditIvaEnabled} />
                          <Label htmlFor="iva-sw" className="text-xs cursor-pointer">Aplica IVA</Label>
                        </div>
                        {editIvaEnabled && (
                          <div className="flex items-center gap-2 ml-1">
                            <div className="flex rounded-md border border-border overflow-hidden shrink-0">
                              <button type="button" onClick={() => setEditIvaMode('percent')}
                                className={`px-2 py-1 text-xs font-semibold transition-colors ${editIvaMode === 'percent' ? 'bg-primary text-primary-foreground' : 'bg-card text-muted-foreground hover:bg-muted'}`}>%</button>
                              <button type="button" onClick={() => setEditIvaMode('amount')}
                                className={`px-2 py-1 text-xs font-semibold border-l border-border transition-colors ${editIvaMode === 'amount' ? 'bg-primary text-primary-foreground' : 'bg-card text-muted-foreground hover:bg-muted'}`}>$</button>
                            </div>
                            {editIvaMode === 'percent' ? (
                              <div className="flex items-center gap-1.5 flex-1">
                                <Input type="number" min={0} max={100} placeholder="16"
                                  value={editIvaRate} onChange={e => setEditIvaRate(e.target.value)}
                                  className="h-8 text-xs" />
                                <span className="text-xs text-muted-foreground shrink-0">%</span>
                              </div>
                            ) : (
                              <Input type="number" min={0} placeholder="Monto de IVA"
                                value={editIvaFixedAmount} onChange={e => setEditIvaFixedAmount(e.target.value)}
                                className="h-8 text-xs flex-1" />
                            )}
                          </div>
                        )}
                      </div>
                      {/* Retenciones */}
                      <div className="grid grid-cols-2 gap-2">
                        <div className="space-y-1">
                          <Label className="text-xs">Ret. IVA <span className="text-muted-foreground font-normal text-[10px]">(opc.)</span></Label>
                          <Input type="number" min={0} placeholder="0.00"
                            value={editRetencionIva} onChange={e => setEditRetencionIva(e.target.value)}
                            className="h-8 text-sm" />
                        </div>
                        <div className="space-y-1">
                          <Label className="text-xs">Ret. ISR <span className="text-muted-foreground font-normal text-[10px]">(opc.)</span></Label>
                          <Input type="number" min={0} placeholder="0.00"
                            value={editRetencionIsr} onChange={e => setEditRetencionIsr(e.target.value)}
                            className="h-8 text-sm" />
                        </div>
                      </div>
                      {/* Running total */}
                      {eSub > 0 && (
                        <div className="rounded-md bg-muted/50 border border-border/60 px-2.5 py-2 space-y-1 text-xs">
                          <div className="flex justify-between text-muted-foreground">
                            <span>Subtotal</span><span>{fmtCurrency(eSub, invoice.currency ?? undefined)}</span>
                          </div>
                          {editIvaEnabled && eIvaAmt > 0 && (
                            <div className="flex justify-between text-muted-foreground">
                              <span>+ IVA{editIvaMode === 'percent' && editIvaRate ? ` (${editIvaRate}%)` : ''}</span>
                              <span>{fmtCurrency(eIvaAmt, invoice.currency ?? undefined)}</span>
                            </div>
                          )}
                          {eRetIva > 0 && (
                            <div className="flex justify-between text-muted-foreground">
                              <span>− Ret. IVA</span><span>−{fmtCurrency(eRetIva, invoice.currency ?? undefined)}</span>
                            </div>
                          )}
                          {eRetIsr > 0 && (
                            <div className="flex justify-between text-muted-foreground">
                              <span>− Ret. ISR</span><span>−{fmtCurrency(eRetIsr, invoice.currency ?? undefined)}</span>
                            </div>
                          )}
                          <div className="flex justify-between font-bold border-t border-border/60 pt-1 mt-1">
                            <span>= Total a pagar</span>
                            <span className="text-primary">{fmtCurrency(eTotal, invoice.currency ?? undefined)}</span>
                          </div>
                        </div>
                      )}
                    </div>
                  ) : (
                    /* Read-only breakdown for validated/rejected */
                    <div className="rounded-lg bg-muted/30 border border-border/60 px-3 py-2.5 space-y-1.5 text-xs">
                      {invoice.subtotal ? (
                        <>
                          <div className="flex justify-between text-muted-foreground">
                            <span>Subtotal</span><span>{fmtCurrency(invoice.subtotal, invoice.currency ?? undefined)}</span>
                          </div>
                          {(invoice.ivaAmount ?? 0) > 0 && (
                            <div className="flex justify-between text-muted-foreground">
                              <span>+ IVA{invoice.ivaRate ? ` (${(invoice.ivaRate * 100).toFixed(0)}%)` : ''}</span>
                              <span>{fmtCurrency(invoice.ivaAmount!, invoice.currency ?? undefined)}</span>
                            </div>
                          )}
                          {(invoice.retencionIva ?? 0) > 0 && (
                            <div className="flex justify-between text-muted-foreground">
                              <span>− Ret. IVA</span><span>−{fmtCurrency(invoice.retencionIva!, invoice.currency ?? undefined)}</span>
                            </div>
                          )}
                          {(invoice.retencionIsr ?? 0) > 0 && (
                            <div className="flex justify-between text-muted-foreground">
                              <span>− Ret. ISR</span><span>−{fmtCurrency(invoice.retencionIsr!, invoice.currency ?? undefined)}</span>
                            </div>
                          )}
                          <div className="flex justify-between font-bold border-t border-border/60 pt-1.5 mt-1">
                            <span>Total</span>
                            <span>{fmtCurrency(invoice.amount ?? undefined, invoice.currency ?? undefined)}</span>
                          </div>
                        </>
                      ) : (
                        <div className="flex justify-between font-semibold">
                          <span>Monto total</span>
                          <span>{fmtCurrency(invoice.amount ?? undefined, invoice.currency ?? undefined)}</span>
                        </div>
                      )}
                    </div>
                  )}
                </div>

                {(invoice.xmlFile?.[0] || invoice.supportFile?.[0] || pdfUrl) && (
                  <>
                    <Separator />
                    <div>
                      <p className="text-[11px] font-semibold uppercase tracking-wider text-muted-foreground mb-2">Archivos adjuntos</p>
                      <div className="space-y-2">
                        {pdfUrl && <FileLink label="PDF de factura" url={pdfUrl} />}
                        {invoice.xmlFile?.[0] && <FileLink label="XML / CFDI" url={invoice.xmlFile[0].url} />}
                        {invoice.supportFile?.[0] && <FileLink label="Archivo de soporte" url={invoice.supportFile[0].url} />}
                      </div>
                    </div>
                  </>
                )}

                <Separator />

                {/* Supplier comment */}
                {invoice.supplierComment && (
                  <>
                    <div>
                      <p className="text-[11px] font-semibold uppercase tracking-wider text-muted-foreground mb-2">Comentario del proveedor</p>
                      <div className="bg-blue-50 border border-blue-200 rounded-lg p-3 text-sm text-blue-900 leading-relaxed whitespace-pre-wrap">
                        {invoice.supplierComment}
                      </div>
                    </div>
                    <Separator />
                  </>
                )}

                {/* Review notes (read-only for already reviewed) */}
                {!canReview && invoice.reviewNotes ? (
                  <div>
                    <p className="text-[11px] text-muted-foreground mb-1">Notas de revisión</p>
                    <div className="bg-muted/40 rounded-lg p-3 text-sm">{invoice.reviewNotes}</div>
                  </div>
                ) : canReview ? (
                  <div className="space-y-1.5">
                    <Label className="text-xs">Notas internas (opcionales)</Label>
                    <Textarea rows={2} value={notes} onChange={e => setNotes(e.target.value)}
                      placeholder="Notas internas sobre esta factura..." className="text-sm resize-none" />
                  </div>
                ) : null}

                {invoice.reviewedBy && (
                  <p className="text-xs text-muted-foreground">
                    Revisada por <strong>{invoice.reviewedBy}</strong> el {fmtDate(invoice.reviewedAt ?? undefined)}
                  </p>
                )}
              </div>
            </ScrollArea>

            {canReview && (
              <div className="px-5 py-4 border-t shrink-0 space-y-3">
                {confirmingValidation ? (
                  <>
                    <div className="bg-green-50 border border-green-200 rounded-lg p-3 space-y-3">
                      <p className="text-xs font-semibold text-green-800 flex items-center gap-1.5">
                        <CheckCircle2 className="w-3.5 h-3.5" />
                        Programar pago
                      </p>

                      {/* Payment terms */}
                      <div className="text-xs text-green-900">
                        <span className="opacity-70">Condiciones de pago de la ODC: </span>
                        <span className="font-semibold">
                          {invoice?.poPaymentTerms
                            ? invoice.poPaymentTerms
                            : 'Sin condiciones definidas — se asumen 30 días'}
                        </span>
                      </div>

                      {/* Calculated date explanation */}
                      <div className="text-xs text-green-900">
                        <span className="opacity-70">Fecha estimada: </span>
                        <span className="font-semibold">
                          {paymentDate
                            ? new Date(paymentDate + 'T12:00:00').toLocaleDateString('es-MX', { day: 'numeric', month: 'long', year: 'numeric' })
                            : '—'}
                        </span>
                        <span className="opacity-60 ml-1">
                          ({paymentTermsToDays(invoice?.poPaymentTerms)} días a partir de hoy)
                        </span>
                      </div>

                      {/* Editable date */}
                      <div className="space-y-1">
                        <Label className="text-xs text-green-700">Ajustar fecha si es necesario</Label>
                        <input
                          type="date"
                          value={paymentDate}
                          onChange={e => setPaymentDate(e.target.value)}
                          className="w-full text-sm border border-green-300 rounded-md px-3 py-1.5 bg-white focus:outline-none focus:ring-1 focus:ring-green-500"
                        />
                      </div>

                      {/* Validated amount summary */}
                      {eTotal > 0 && (
                        <div className="text-xs text-green-900 bg-green-100/60 rounded-md px-2.5 py-2 flex justify-between font-semibold">
                          <span>Monto del pago</span>
                          <span>{fmtCurrency(eTotal, invoice?.currency ?? undefined)}</span>
                        </div>
                      )}
                      <p className="text-xs text-green-800 font-medium pt-0.5">
                        ¿Estás de acuerdo con esta fecha de pago?
                      </p>
                    </div>
                    <div className="flex gap-2">
                      <Button variant="outline" size="sm" className="flex-1"
                        onClick={() => setConfirmingValidation(false)} disabled={!!saving}>
                        Cancelar
                      </Button>
                      <Button size="sm" className="flex-1 bg-green-600 hover:bg-green-700 text-white text-xs"
                        onClick={() => handleAction('validar')} disabled={!!saving || !paymentDate}>
                        <CheckCircle2 className="w-3.5 h-3.5 mr-1" />
                        {saving === 'validar' ? 'Validando...' : 'Confirmar y programar pago'}
                      </Button>
                    </div>
                  </>
                ) : confirmingRejection ? (
                  <>
                    <div className="bg-destructive/5 border border-destructive/20 rounded-lg p-3 space-y-2.5">
                      <p className="text-xs font-semibold text-destructive flex items-center gap-1.5">
                        <XCircle className="w-3.5 h-3.5" />
                        Motivo de rechazo (requerido)
                      </p>
                      <Textarea
                        rows={3}
                        value={rejectReason}
                        onChange={e => { setRejectReason(e.target.value); setRejectReasonError(false); }}
                        placeholder="Describe el motivo del rechazo. El proveedor verá este mensaje en su portal…"
                        className={`text-xs resize-none ${rejectReasonError ? 'border-destructive ring-1 ring-destructive' : ''}`}
                        autoFocus
                      />
                      {rejectReasonError && (
                        <p className="text-[11px] text-destructive">El motivo de rechazo es obligatorio.</p>
                      )}
                    </div>
                    <div className="flex gap-2">
                      <Button variant="outline" size="sm" className="flex-1"
                        onClick={() => setConfirmingRejection(false)} disabled={!!saving}>
                        Cancelar
                      </Button>
                      <Button size="sm" variant="destructive" className="flex-1 text-xs"
                        onClick={() => handleAction('rechazar')} disabled={!!saving || !rejectReason.trim()}>
                        <XCircle className="w-3.5 h-3.5 mr-1" />
                        {saving === 'rechazar' ? 'Rechazando...' : 'Confirmar rechazo'}
                      </Button>
                    </div>
                  </>
                ) : (
                  <div className="flex gap-2">
                    <Button variant="outline" size="sm"
                      className="flex-1 border-destructive text-destructive hover:bg-destructive/10"
                      onClick={handleRejectClick} disabled={!!saving}>
                      <XCircle className="w-4 h-4 mr-1.5" />
                      Rechazar
                    </Button>
                    <Button size="sm" className="flex-1 bg-green-600 hover:bg-green-700 text-white"
                      onClick={handleValidarClick} disabled={!!saving}>
                      <CheckCircle2 className="w-4 h-4 mr-1.5" />
                      Validar
                    </Button>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
        </>
        )}
      </DialogContent>
    </Dialog>
  );
}

// ── Main page ─────────────────────────────────────────────────────────────────
export default function SupplierInvoicesPage() {
  const [invoices, setInvoices] = useState<InvoiceListItem[]>([]);
  const [stats, setStats] = useState<Stats>({ pending: 0, inReview: 0, validated: 0, rejected: 0, totalAmount: 0 });
  const [loading, setLoading] = useState(true);
  const [filterStatus, setFilterStatus] = useState('');
  const [search, setSearch] = useState('');
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const isInitialLoad = useRef(true);

  const load = async (silent = false) => {
    if (!silent) setLoading(true);
    try {
      const data = await getSupplierInvoices({ status: filterStatus || undefined });
      setInvoices(data.invoices);
      setStats(data.stats);
    } catch { if (!silent) toast.error('Error al cargar facturas'); }
    finally { if (!silent) setLoading(false); }
  };

  useEffect(() => {
    isInitialLoad.current = true;
    load(false);
    isInitialLoad.current = false;
    const interval = setInterval(() => { if (document.visibilityState === 'visible') load(true); }, 120000);
    return () => clearInterval(interval);
  }, [filterStatus]);

  const filtered = useMemo(() => {
    if (!search) return invoices;
    const q = search.toLowerCase();
    return invoices.filter(i =>
      i.supplierName?.toLowerCase().includes(q) ||
      i.invoiceNumber?.toLowerCase().includes(q) ||
      (i.poNumber ?? '').toLowerCase().includes(q)
    );
  }, [invoices, search]);

  const groups = useMemo(() => ({
    pending: filtered.filter(i => i.status === 'Pendiente' || i.status === 'En revisión'),
    validated: filtered.filter(i => i.status === 'Validada'),
    rejected: filtered.filter(i => i.status === 'Rechazada'),
  }), [filtered]);

  const newCount = useMemo(() => groups.pending.filter(i => isNew(i.uploadDate)).length, [groups.pending]);

  return (
    <div className="p-6 max-w-[1400px] mx-auto">
      <div className="mb-6">
        <h1 className="text-xl font-bold">Facturas de Proveedores</h1>
        <p className="text-sm text-muted-foreground mt-0.5">Revisión y validación de facturas recibidas</p>
      </div>

      {/* KPIs */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 mb-4">
        <StatCard label="Pendientes de revisión" value={stats.pending} icon={AlertCircle} color="bg-orange-100 text-orange-600" />
        <StatCard label="En revisión" value={stats.inReview} icon={Clock} color="bg-blue-100 text-blue-600" />
        <StatCard label="Validadas" value={stats.validated} icon={CheckCircle2} color="bg-green-100 text-green-600" />
        <StatCard label="Total validado" value={`$${stats.totalAmount.toLocaleString('es-MX', { maximumFractionDigits: 0 })}`} icon={FileText} color="bg-primary/10 text-primary" />
      </div>

      {/* New invoices alert banner */}
      {newCount > 0 && (
        <div className="flex items-center gap-3 px-4 py-3 rounded-xl border border-primary/30 bg-primary/5 mb-4">
          <Bell className="w-4 h-4 text-primary shrink-0" />
          <p className="text-sm font-medium text-primary">
            {newCount === 1
              ? '1 factura nueva por revisar en las últimas 48 horas'
              : `${newCount} facturas nuevas por revisar en las últimas 48 horas`}
          </p>
        </div>
      )}

      {/* Filters */}
      <div className="flex flex-wrap gap-3 mb-5">
        <Input
          placeholder="Buscar proveedor o # factura..."
          value={search}
          onChange={e => setSearch(e.target.value)}
          className="w-56 h-9"
        />
        <Select value={filterStatus} onValueChange={setFilterStatus}>
          <SelectTrigger className="w-44 h-9">
            <SelectValue placeholder="Todos los estados" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="Pendiente">Pendiente</SelectItem>
            <SelectItem value="En revisión">En revisión</SelectItem>
            <SelectItem value="Validada">Validada</SelectItem>
            <SelectItem value="Rechazada">Rechazada</SelectItem>
          </SelectContent>
        </Select>
        {filterStatus && <Button variant="ghost" size="sm" onClick={() => setFilterStatus('')} className="h-9">Limpiar</Button>}
      </div>

      {/* Grouped sections */}
      {loading ? (
        <div className="space-y-2">{[1, 2, 3, 4].map(i => <Skeleton key={i} className="h-14 w-full" />)}</div>
      ) : filtered.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-24 bg-card border rounded-xl text-center">
          <FileText className="w-14 h-14 text-muted-foreground/30 mb-4" />
          <p className="font-semibold">No hay facturas</p>
          <p className="text-sm text-muted-foreground mt-1">Las facturas enviadas por proveedores aparecerán aquí.</p>
        </div>
      ) : (
        <div className="space-y-3">
          <InvoiceGroup
            title="Por revisar"
            count={groups.pending.length}
            icon={Clock}
            headerClass="bg-orange-50 hover:bg-orange-100/70 text-orange-800 border-b border-orange-100"
            defaultOpen={true}
            invoices={groups.pending}
            onSelect={inv => setSelectedId(inv.id)}
          />
          <InvoiceGroup
            title="Validadas"
            count={groups.validated.length}
            icon={CheckCircle2}
            headerClass="bg-green-50 hover:bg-green-100/70 text-green-800 border-b border-green-100"
            defaultOpen={false}
            invoices={groups.validated}
            onSelect={inv => setSelectedId(inv.id)}
          />
          <InvoiceGroup
            title="Rechazadas"
            count={groups.rejected.length}
            icon={XCircle}
            headerClass="bg-red-50 hover:bg-red-100/70 text-red-800 border-b border-red-100"
            defaultOpen={false}
            invoices={groups.rejected}
            onSelect={inv => setSelectedId(inv.id)}
          />
        </div>
      )}

      <InvoiceDetailDialog invoiceId={selectedId} open={!!selectedId} onClose={() => setSelectedId(null)} onRefresh={load} />
    </div>
  );
}

src/api/analyzeRecruitmentStatus.ts.content:
import { z } from 'zod';
import { createEndpoint, Projects, RecruitmentRows, BoardColumns, CellValues, Boards } from 'zite-integrations-backend-sdk';
import OpenAI from 'openai';

// ─── Zod schemas ──────────────────────────────────────────────────────────────

const distributionItem = z.object({ label: z.string(), count: z.number() });

const distributionSchema = z.object({
  fieldName: z.string(),
  chartType: z.enum(['donut', 'bar']),
  items: z.array(distributionItem),
});

const inlineDistribution = z.object({
  chartType: z.enum(['donut', 'bar']),
  items: z.array(distributionItem),
});

const criterionSchema = z.object({
  criterion: z.string(),
  expected: z.string(),
  actual: z.string(),
  status: z.enum(['cumple', 'revisar', 'no_cumple']),
  action: z.string().optional(),
  distribution: inlineDistribution.optional(),
});

const participantRecord = z.object({ name: z.string(), fields: z.record(z.string(), z.string()) });

const groupAnalysis = z.object({
  groupName: z.string(),
  totalParticipants: z.number(),
  requiredParticipants: z.number().nullable(),
  criteria: z.array(criterionSchema),
  alerts: z.array(z.string()),
  status: z.enum(['cumple', 'revisar', 'no_cumple']),
  complianceNote: z.string(),
  participants: z.array(participantRecord),
});

// ─── Helpers ──────────────────────────────────────────────────────────────────

async function fetchAllCellValues(filters: Record<string, any>): Promise<any[]> {
  const all: any[] = [];
  let offset = 0;
  while (true) {
    const { records, hasMore } = await CellValues.findAll({ filters: filters as any, limit: 2000, offset });
    all.push(...records);
    if (!hasMore) break;
    offset += records.length;
  }
  return all;
}

type DistItem = { label: string; count: number };
type CalcDist = { fieldName: string; chartType: 'donut' | 'bar'; items: DistItem[] };

// ─── Field detection patterns ─────────────────────────────────────────────────

const FIELD_PATTERNS = {
  gender: /g[eé]nero|sexo/i,
  age:    /^edad$|rango.{0,10}edad|edad.{0,10}rango|^edad\b/i,
  region: /regi[oó]n|ciudad|estado|zona|localidad/i,
  brand:  /marca|favorit|preferid|indispensable|principal|m[aá]s.{0,10}consum/i,
  nse:    /^nse$|nivel.{0,10}socio.?econ/i,
};

// ─── AMAI 2020 NSE calculation ────────────────────────────────────────────────

const AMAI_COL = {
  escolaridad:  /escolaridad\s*jdf|escolaridad\s*jefe/i,
  banos:        /ba[ñn]os?\s*complet/i,
  autos:        /autom[oó]vil/i,
  internet:     /conexi[oó]n.*m[oó]vil|internet|banda\s*ancha/i,
  trabajadores: /trabajador/i,
  habitaciones: /habitaci[oó]n/i,
};

function scoreAMAI(key: keyof typeof AMAI_COL, value: string): number {
  const v = value.toLowerCase().trim();
  switch (key) {
    case 'escolaridad': {
      if (/diplomado|maestr[ií]a|doctorado/.test(v)) return 72;
      if (/licenciatura\s*(completa|terminada|trunca)?|carrera\s*(profesional|universit)|ingenier[ií]a/.test(v)) {
        if (/complet|terminad/.test(v)) return 52;
        return 38; // incompleta
      }
      if (/preparatoria|bachillerato|prepa/.test(v)) return 38;
      if (/secundaria/.test(v)) return 22;
      if (/primaria/.test(v)) return 22;
      return 0;
    }
    case 'banos': {
      const n = parseInt(v);
      if (!isNaN(n)) return n >= 2 ? 42 : n === 1 ? 18 : 0;
      if (/2|dos|m[aá]s/.test(v)) return 42;
      if (/1|un/.test(v)) return 18;
      return 0;
    }
    case 'autos': {
      const n = parseInt(v);
      if (!isNaN(n)) return n >= 2 ? 41 : n === 1 ? 22 : 0;
      if (/2|dos|m[aá]s/.test(v)) return 41;
      if (/1|un/.test(v)) return 22;
      return 0;
    }
    case 'internet': {
      return /s[ií]|tiene|cuenta|yes/.test(v) ? 10 : 0;
    }
    case 'trabajadores': {
      const n = parseInt(v);
      if (!isNaN(n)) return n >= 3 ? 31 : n >= 1 ? 12 : 0;
      if (/ninguno|cero|no\s*tiene/.test(v)) return 0;
      if (/[3456789]|m[aá]s/.test(v)) return 31;
      return 12;
    }
    case 'habitaciones': {
      const n = parseInt(v);
      if (!isNaN(n)) {
        if (n >= 4) return 22;
        if (n === 3) return 14;
        if (n === 2) return 8;
        return 0;
      }
      return 0;
    }
  }
}

function scoreToNSE(score: number): string {
  if (score >= 193) return 'A/B';
  if (score >= 155) return 'C+';
  if (score >= 128) return 'C';
  if (score >= 105) return 'C-';
  if (score >= 80)  return 'D+';
  if (score >= 33)  return 'D';
  return 'E';
}

const NSE_ORDER = ['A/B', 'C+', 'C', 'C-', 'D+', 'D', 'E'];

const AMAI_MAX: Record<keyof typeof AMAI_COL, number> = {
  escolaridad:  72,
  banos:        42,
  autos:        41,
  trabajadores: 31,
  habitaciones: 22,
  internet:     10,
};

function calculateNSE(participantData: Record<string, string>): string | null {
  const fieldNames = Object.keys(participantData);
  let score = 0;
  let maxPossible = 0;
  let matched = 0;
  for (const [amaiKey, pattern] of Object.entries(AMAI_COL) as [keyof typeof AMAI_COL, RegExp][]) {
    const colName = fieldNames.find(f => pattern.test(f));
    if (!colName) continue;
    const val = participantData[colName];
    if (!val || val.trim() === '') continue;
    score += scoreAMAI(amaiKey, val);
    maxPossible += AMAI_MAX[amaiKey as keyof typeof AMAI_COL];
    matched++;
  }
  if (matched < 2 || maxPossible === 0) return null;
  const normalizedScore = Math.round((score / maxPossible) * 218);
  return scoreToNSE(normalizedScore);
}

function computeNSEDist(groupRows: Record<string, string>[]): CalcDist | null {
  const counts: Record<string, number> = {};
  let computed = 0;
  for (const row of groupRows) {
    const level = calculateNSE(row);
    if (!level) continue;
    counts[level] = (counts[level] ?? 0) + 1;
    computed++;
  }
  if (computed === 0) return null;
  const items = NSE_ORDER.filter(l => counts[l] > 0).map(l => ({ label: l, count: counts[l] }));
  return { fieldName: 'NSE (estimado)', chartType: 'donut', items };
}

// ─── Distribution helpers ─────────────────────────────────────────────────────

/** Generate per-age distribution, or return as categories if values are already text ranges */
function bucketAge(values: string[]): DistItem[] {
  // If values look like text ranges ("19 a 24 años", "25-35 años"), treat as categories
  const isTextRange = (v: string) => / a /i.test(v) || /años/i.test(v) || /\d+-\d+/.test(v);
  const textRangeCount = values.filter(isTextRange).length;
  if (textRangeCount > values.length * 0.4) {
    const counts: Record<string, number> = {};
    for (const v of values) {
      const key = v.trim();
      counts[key] = (counts[key] ?? 0) + 1;
    }
    return Object.entries(counts)
      .sort(([, a], [, b]) => b - a)
      .map(([label, count]) => ({ label, count }));
  }
  // Numeric ages — one item per individual age in full range, including zeros (gaps)
  const nums = values.map(v => parseInt(v, 10)).filter(n => !isNaN(n));
  if (!nums.length) return [];
  const counts: Record<number, number> = {};
  for (const n of nums) counts[n] = (counts[n] ?? 0) + 1;
  const min = Math.min(...nums);
  const max = Math.max(...nums);
  const items: DistItem[] = [];
  for (let age = min; age <= max; age++) {
    items.push({ label: String(age), count: counts[age] ?? 0 });
  }
  return items;
}

/** Compute value distribution for a field across a list of participant data objects */
function calcFieldDist(fieldName: string, rows: Record<string, string>[]): DistItem[] {
  const counts: Record<string, number> = {};
  for (const row of rows) {
    const val = row[fieldName];
    if (!val || val.trim() === '') continue;
    counts[val.trim()] = (counts[val.trim()] ?? 0) + 1;
  }
  return Object.entries(counts)
    .sort(([, a], [, b]) => b - a)
    .map(([label, count]) => ({ label, count }));
}

/** Detect relevant fields from all available field names in the dataset */
function detectRelevantFields(allFieldNames: string[]): Record<keyof typeof FIELD_PATTERNS, string | null> {
  const result = {} as Record<keyof typeof FIELD_PATTERNS, string | null>;
  for (const [key, pattern] of Object.entries(FIELD_PATTERNS)) {
    if (key === 'age') {
      // Prefer exact match "Edad" (numeric) before fuzzy patterns like "Rango de edad"
      const exact = allFieldNames.find(f => /^edad$/i.test(f));
      result.age = exact ?? allFieldNames.find(f => pattern.test(f)) ?? null;
    } else {
      result[key as keyof typeof FIELD_PATTERNS] = allFieldNames.find(f => pattern.test(f)) ?? null;
    }
  }
  return result;
}

type GroupDists = Record<keyof typeof FIELD_PATTERNS, CalcDist | null> & { nseCalc: CalcDist | null };

/** Pre-compute distributions for a group's participants, including AMAI NSE */
function computeGroupDistributions(
  groupRows: Record<string, string>[],
  detectedFields: Record<keyof typeof FIELD_PATTERNS, string | null>
): GroupDists {
  const result = {} as GroupDists;

  for (const key of Object.keys(FIELD_PATTERNS) as Array<keyof typeof FIELD_PATTERNS>) {
    const fieldName = detectedFields[key];
    if (!fieldName) { result[key] = null; continue; }

    if (key === 'age') {
      const vals = groupRows.map(r => r[fieldName]).filter(Boolean);
      const buckets = bucketAge(vals);
      result[key] = buckets.length ? { fieldName, chartType: 'bar', items: buckets } : null;
    } else {
      const items = calcFieldDist(fieldName, groupRows);
      if (!items.length) { result[key] = null; continue; }
      const chartType: 'donut' | 'bar' = items.length <= 6 ? 'donut' : 'bar';
      result[key] = { fieldName, chartType, items };
    }
  }

  // AMAI-based NSE calculation (overrides any literal NSE column if absent)
  result.nseCalc = computeNSEDist(groupRows) ?? result.nse;

  return result;
}

/** Match a criterion label to a pre-computed distribution */
function matchCriterionDist(
  criterionLabel: string,
  dists: GroupDists
): { chartType: 'donut' | 'bar'; items: DistItem[] } | undefined {
  const l = criterionLabel.toLowerCase();
  if (/g[eé]nero|sexo/.test(l) && dists.gender) return { chartType: dists.gender.chartType, items: dists.gender.items };
  if (/edad|rango.{0,10}edad/.test(l) && dists.age) return { chartType: dists.age.chartType, items: dists.age.items };
  if (/regi[oó]n|ciudad|estado|zona/.test(l) && dists.region) return { chartType: dists.region.chartType, items: dists.region.items };
  if (/marca|favorit|preferid/.test(l) && dists.brand) return { chartType: dists.brand.chartType, items: dists.brand.items };
  if (/nse|nivel.{0,10}soci|nivel.{0,10}econ|ingreso/.test(l) && dists.nseCalc) return { chartType: dists.nseCalc.chartType, items: dists.nseCalc.items };
  return undefined;
}

/** Aggregate distributions from all groups for the global view */
function aggregateGlobalDistributions(groupDists: GroupDists[]): CalcDist[] {
  const aggregate: Record<string, CalcDist> = {};

  const addDist = (dist: CalcDist | null) => {
    if (!dist) return;
    if (!aggregate[dist.fieldName]) {
      aggregate[dist.fieldName] = { fieldName: dist.fieldName, chartType: dist.chartType, items: [] };
    }
    for (const item of dist.items) {
      const existing = aggregate[dist.fieldName].items.find(i => i.label === item.label);
      if (existing) existing.count += item.count;
      else aggregate[dist.fieldName].items.push({ ...item });
    }
  };

  for (const dists of groupDists) {
    addDist(dists.gender);
    addDist(dists.age);
    addDist(dists.region);
    addDist(dists.brand);
    addDist(dists.nseCalc); // use calculated NSE (AMAI or literal column)
  }

  // Sort NSE items by canonical order
  return Object.values(aggregate).map(d => ({
    ...d,
    items: d.fieldName === 'NSE (estimado)'
      ? NSE_ORDER.filter(l => d.items.find(i => i.label === l)).map(l => d.items.find(i => i.label === l)!)
      : d.items.sort((a, b) => b.count - a.count),
  }));
}

// ─── Endpoint ─────────────────────────────────────────────────────────────────

export default createEndpoint({
  authenticated: true,
  description: 'Analyzes recruitment data for a board against the project muestra criteria using AI',
  inputSchema: z.object({ projectCode: z.string(), boardName: z.string() }),
  outputSchema: z.object({
    muestra: z.string(),
    groups: z.array(groupAnalysis),
    globalSummary: z.string(),
    globalDistributions: z.array(distributionSchema),
    overallStatus: z.enum(['cumple', 'revisar', 'no_cumple']),
    totalParticipants: z.number(),
    generatedAt: z.string(),
  }),
  execute: async ({ input }) => {
    const { projectCode, boardName } = input;

    const project = await Projects.findOne({ filters: { projectCode } });
    const muestra = project?.muestra ?? '';
    const muestraImagen = project?.muestraImagen ?? '';
    const analysisInstructions = project?.instruccionesDeAnalisis ?? '';

    // Resolve board UUID — try direct lookup first, fall back to legacy composite
    const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    let boardId: string;
    const { records: matchingBoards } = await Boards.findAll({
      filters: { projectCode, boardName },
      limit: 5,
    });
    const activeBoard = matchingBoards.find(b => !b.deletedAt);
    if (activeBoard) {
      boardId = activeBoard.id;
    } else {
      boardId = `recruitment-${projectCode}-${boardName}`;
    }
    const groupsBoardId = `${boardId}::groups`;

    // For CellValues/BoardColumns dual-read, prepare both UUID and legacy candidates
    const legacyBoardId = `recruitment-${projectCode}-${boardName}`;
    const boardIdCandidates = boardId !== legacyBoardId ? [boardId, legacyBoardId] : [boardId];

    // Dual-read: fetch from UUID groups board + legacy groups board
    const legacyGroupsBoardId = `${legacyBoardId}::groups`;
    const groupsCandidates = boardId !== legacyBoardId ? [groupsBoardId, legacyGroupsBoardId] : [groupsBoardId];

    const [{ records: rows }] = await Promise.all([
      RecruitmentRows.findAll({ filters: { projectCode, boardName }, limit: 2000 }),
    ]);

    // Dual-read group columns
    const groupColumnsSeen = new Set<string>();
    const groupColumns: typeof rows extends any[] ? any[] : never = [];
    for (const gBid of groupsCandidates) {
      const { records } = await BoardColumns.findAll({ filters: { boardId: gBid } as any, limit: 200 });
      for (const r of records) { if (!groupColumnsSeen.has(r.id)) { groupColumnsSeen.add(r.id); groupColumns.push(r); } }
    }

    // Dual-read group assignments
    const groupAssignmentsSeen = new Set<string>();
    const groupAssignments: any[] = [];
    for (const gBid of groupsCandidates) {
      const { records } = await CellValues.findAll({ filters: { boardId: gBid, textValue: '1' } as any, limit: 2000 });
      for (const r of records) {
        const key = `${r.rowId}::${r.columnId}`;
        if (!groupAssignmentsSeen.has(key)) { groupAssignmentsSeen.add(key); groupAssignments.push(r); }
      }
    }

    const groupColMap: Record<string, string> = {};
    for (const col of groupColumns) {
      if (col.id && col.columnName) groupColMap[col.id] = col.columnName;
    }

    const rowGroupMap: Record<string, string> = {};
    for (const cv of groupAssignments) {
      if (cv.rowId && cv.columnId && groupColMap[cv.columnId]) {
        rowGroupMap[cv.rowId] = groupColMap[cv.columnId];
      }
    }

    const rowsWithGroup = rows.filter(r => rowGroupMap[r.id]);

    if (rowsWithGroup.length === 0) {
      return {
        muestra: muestra || (muestraImagen ? '(ver imagen adjunta)' : 'Sin criterios definidos'),
        groups: [], globalSummary: 'No hay participantes asignados a grupos en este tablero.',
        globalDistributions: [], overallStatus: 'revisar' as const,
        totalParticipants: 0, generatedAt: new Date().toISOString(),
      };
    }

    const assignedRowIds = rowsWithGroup.map(r => r.id);

    // Dual-read main board columns + cell values
    const mainColsSeen = new Set<string>();
    const mainBoardCols: any[] = [];
    for (const bid of boardIdCandidates) {
      const { records } = await BoardColumns.findAll({ filters: { boardId: bid } as any, limit: 200 });
      for (const r of records) { if (!mainColsSeen.has(r.id)) { mainColsSeen.add(r.id); mainBoardCols.push(r); } }
    }

    let allParticipantCells: any[] = [];
    for (const bid of boardIdCandidates) {
      const cells = await fetchAllCellValues({ boardId: bid, rowId: { in: assignedRowIds } });
      allParticipantCells.push(...cells);
    }
    // Deduplicate by rowId::columnId (prefer UUID)
    const cellSeen = new Set<string>();
    allParticipantCells = allParticipantCells.filter(cv => {
      const key = `${cv.rowId}::${cv.columnId}`;
      if (cellSeen.has(key)) return false;
      cellSeen.add(key);
      return true;
    });

    const mainColNames: Record<string, string> = {};
    for (const col of mainBoardCols) {
      if (col.id && col.columnName && !col.deletedAt) mainColNames[col.id] = col.columnName;
    }

    const SYSTEM_COLS = new Set(['NDA Firmado', 'Identificación 2', 'Asistencia', 'NR', 'Reclutador', 'Dirección', 'Motivo Rechazo']);
    const cellsByRow: Record<string, Record<string, string>> = {};
    for (const cv of allParticipantCells) {
      if (!cv.rowId || !cv.columnId || !cv.textValue || cv.deletedAt) continue;
      const colName = mainColNames[cv.columnId];
      if (!colName || SYSTEM_COLS.has(colName)) continue;
      const val = cv.textValue;
      if (val.startsWith('http') || val.length > 200) continue;
      if (!cellsByRow[cv.rowId]) cellsByRow[cv.rowId] = {};
      cellsByRow[cv.rowId][colName] = val;
    }

    // Build participant data with group assignment
    const participantData = rowsWithGroup.map(row => ({
      nombre: row.participantName ?? row.rowName ?? 'Sin nombre',
      grupo: rowGroupMap[row.id],
      datos: cellsByRow[row.id] ?? {},
    }));

    // ── Pre-compute distributions (real data, no AI) ──────────────────────────

    const allFieldNames = [...new Set(participantData.flatMap(p => Object.keys(p.datos)))];
    const detectedFields = detectRelevantFields(allFieldNames);

    // Group participants by group name
    const rowsByGroup: Record<string, Record<string, string>[]> = {};
    const rawByGroup: Record<string, Array<{ name: string; fields: Record<string, string> }>> = {};
    for (const p of participantData) {
      if (!rowsByGroup[p.grupo]) { rowsByGroup[p.grupo] = []; rawByGroup[p.grupo] = []; }
      rowsByGroup[p.grupo].push(p.datos);
      rawByGroup[p.grupo].push({ name: p.nombre, fields: p.datos });
    }

    // Pre-compute distributions per group (including AMAI NSE)
    const groupDistributions: Record<string, GroupDists> = {};
    for (const [groupName, gRows] of Object.entries(rowsByGroup)) {
      groupDistributions[groupName] = computeGroupDistributions(gRows, detectedFields);
    }

    // Global distributions — aggregate all groups
    const globalDistributions = aggregateGlobalDistributions(Object.values(groupDistributions));

    // Match participants to AI-simplified group names
    const matchParticipants = (aiName: string) => {
      if (rawByGroup[aiName]) return rawByGroup[aiName];
      const aiLow = aiName.toLowerCase();
      for (const [orig, parts] of Object.entries(rawByGroup)) {
        if (orig.toLowerCase().includes(aiLow)) return parts;
      }
      const words = aiLow.split(/[\s\-\(\)\/]+/).filter(w => w.length > 3);
      let best = { n: 0, key: '' };
      for (const orig of Object.keys(rawByGroup)) {
        const origL = orig.toLowerCase();
        const n = words.filter(w => origL.includes(w)).length;
        if (n > best.n) best = { n, key: orig };
      }
      return best.n >= 1 ? (rawByGroup[best.key] ?? []) : [];
    };

    // Match pre-computed distributions to AI group name
    const matchGroupDist = (aiName: string): GroupDists | null => {
      if (groupDistributions[aiName]) return groupDistributions[aiName];
      const aiLow = aiName.toLowerCase();
      for (const [orig, dists] of Object.entries(groupDistributions)) {
        if (orig.toLowerCase().includes(aiLow)) return dists;
      }
      const words = aiLow.split(/[\s\-\(\)\/]+/).filter(w => w.length > 3);
      let best = { n: 0, key: '' };
      for (const orig of Object.keys(groupDistributions)) {
        const origL = orig.toLowerCase();
        const n = words.filter(w => origL.includes(w)).length;
        if (n > best.n) best = { n, key: orig };
      }
      return best.n >= 1 ? groupDistributions[best.key] : null;
    };

    // ── Build AI prompt (NO distributions requested from AI) ──────────────────

    const client = new OpenAI({ apiKey: process.env.ZITE_OPENAI_ACCESS_TOKEN });

    const criteriosText = muestra.trim()
      ? `CRITERIOS DE MUESTRA:\n${muestra}`
      : muestraImagen
      ? 'Los criterios de muestra están en la imagen adjunta.'
      : 'No se especificaron criterios. Analiza los datos y genera estadísticas descriptivas.';

    const criteriosDeEvaluacion = analysisInstructions.trim()
      ? `\n━━━ CRITERIOS DE EVALUACIÓN DEFINIDOS POR EL USUARIO ━━━\nUsa estos criterios exactos como checklist para cada grupo:\n\n${analysisInstructions.trim()}\n\nIMPORTANTE: Evalúa TODOS estos criterios para cada grupo, aunque cumplan.\n`
      : `\n━━━ CRITERIOS A INFERIR ━━━\nInfiere los criterios relevantes de la muestra y los datos. Evalúa al menos: género, edad/rango, marca (si aplica), NSE (si aplica), región, participantes requeridos.\n`;

    // Summary data per group (no raw participant details to keep prompt small)
    const groupSummaries = Object.entries(rowsByGroup).map(([groupName, gRows]) => {
      const total = gRows.length;
      const fieldSummary: Record<string, string> = {};
      for (const [key, fieldName] of Object.entries(detectedFields)) {
        if (!fieldName) continue;
        const vals = gRows.map(r => r[fieldName]).filter(Boolean);
        if (!vals.length) continue;
        if (key === 'age') {
          // Detect if values are text ranges ("19 a 24 años") or numeric ages
          const isTextRange = (v: string) => / a /i.test(v) || /años/i.test(v) || /\d+-\d+/.test(v);
          const textRangeCount = vals.filter(isTextRange).length;
          if (textRangeCount > vals.length * 0.4) {
            // Categorical ranges — summarize as counts
            const counts: Record<string, number> = {};
            vals.forEach(v => { counts[v.trim()] = (counts[v.trim()] ?? 0) + 1; });
            fieldSummary[fieldName] = Object.entries(counts).map(([v, c]) => `${v}: ${c}`).join(', ');
          } else {
            const nums = vals.map(v => parseInt(v)).filter(n => !isNaN(n));
            if (nums.length) {
              const ageCounts: Record<number, number> = {};
              nums.forEach(n => { ageCounts[n] = (ageCounts[n] ?? 0) + 1; });
              const distStr = Object.entries(ageCounts)
                .sort(([a], [b]) => Number(a) - Number(b))
                .map(([age, count]) => `${age}→${count}`)
                .join(', ');
              const prom = Math.round(nums.reduce((a, b) => a + b, 0) / nums.length);
              fieldSummary[fieldName] = `Distribución: ${distStr} | min ${Math.min(...nums)}, max ${Math.max(...nums)}, prom ${prom}`;
            }
          }
        } else {
          const counts: Record<string, number> = {};
          vals.forEach(v => { counts[v.trim()] = (counts[v.trim()] ?? 0) + 1; });
          fieldSummary[fieldName] = Object.entries(counts).map(([v, c]) => `${v}: ${c}`).join(', ');
        }
      }
      // Include NSE distribution in summary so AI knows the breakdown
      const nseDist = groupDistributions[groupName]?.nseCalc;
      if (nseDist) {
        fieldSummary['NSE (estimado AMAI)'] = nseDist.items.map(i => `${i.label}: ${i.count}`).join(', ');
      }
      // Sample other fields
      const otherFields = Object.keys(gRows[0] ?? {}).filter(f =>
        !Object.values(detectedFields).includes(f) && !SYSTEM_COLS.has(f)
      ).slice(0, 3);
      for (const f of otherFields) {
        const counts: Record<string, number> = {};
        gRows.forEach(r => { if (r[f]) counts[r[f].trim()] = (counts[r[f].trim()] ?? 0) + 1; });
        if (Object.keys(counts).length) fieldSummary[f] = Object.entries(counts).map(([v, c]) => `${v}: ${c}`).join(', ');
      }
      return { grupo: groupName, total, resumen: fieldSummary };
    });

    const userPrompt = `${criteriosText}${criteriosDeEvaluacion}

RESUMEN POR GRUPO (${groupSummaries.length} grupos, ${participantData.length} participantes):
${JSON.stringify(groupSummaries, null, 1)}

${muestraImagen ? 'IMPORTANTE: Lee la imagen adjunta para obtener los criterios completos.\n' : ''}
━━━ INSTRUCCIONES ━━━

Para CADA grupo genera un scorecard de cumplimiento. Devuelve TODOS los grupos.

REGLAS:
- criteria: incluye TODOS los criterios verificables aunque cumplan (vigilancia continua)
- Sé específico con números en "actual": "100% Mujer (8/8)", "Rango 29-45, promedio 34.5"
- Si no cumple, incluye "action" con sugerencia accionable y numérica
- NO incluyas "distribution" — las gráficas se calculan por separado con datos reales
- Para EDAD: verifica que haya dispersión a lo largo de todo el rango requerido. El campo Edad llega como "Distribución: 18→1, 19→3, 21→2..." — úsalo para evaluar balance real. Si más del 40% de participantes tienen la misma edad exacta, marca como "revisar" e indica la concentración (ej: "⚠ 3/8 tienen 19 años, falta distribución uniforme")
- STATUS: "cumple" solo si TODOS los criteria son cumple
- overallStatus = el PEOR status individual

━━━ FORMATO JSON ━━━
{
  "groups": [
    {
      "groupName": "nombre simplificado (conserva Lovers/Rejectors/NSE/edad/etc.)",
      "totalParticipants": número,
      "requiredParticipants": número o null,
      "criteria": [
        { "criterion": "Género", "expected": "Mujer", "actual": "100% Mujer (8/8)", "status": "cumple" },
        { "criterion": "Rango de edad", "expected": "25-45 años", "actual": "Rango 27-42, promedio 33 años", "status": "cumple" },
        { "criterion": "NSE", "expected": "C+ o superior", "actual": "60% C+, 30% C (90% cumple)", "status": "cumple" },
        { "criterion": "Participantes requeridos", "expected": "6", "actual": "8 reclutados", "status": "cumple" }
      ],
      "alerts": [],
      "status": "cumple",
      "complianceNote": "Una línea sobre el estado general"
    }
  ],
  "globalSummary": "globalSummary debe ser un RESUMEN ULTRA BREVE de cuotas por grupo, formato: 'Grupo X: 6/8 ✓ | Grupo Y: 3/6 ⚠ faltan 3 mujeres | Grupo Z: 5/5 ✓'. Solo una línea por grupo con reclutados/requeridos y si algo no cumple. Máximo 2 líneas totales. NO repitas criterios individuales..",
  "overallStatus": "cumple" | "revisar" | "no_cumple"
}`;

    let aiResult: {
      groups: Array<{
        groupName: string; totalParticipants: number; requiredParticipants: number | null;
        criteria: Array<{ criterion: string; expected: string; actual: string; status: 'cumple' | 'revisar' | 'no_cumple'; action?: string }>;
        alerts: string[]; status: 'cumple' | 'revisar' | 'no_cumple'; complianceNote: string;
      }>;
      globalSummary: string; overallStatus: 'cumple' | 'revisar' | 'no_cumple';
    };

    try {
      const userContent: Array<{ type: string; text?: string; image_url?: { url: string; detail: string } }> = [
        { type: 'text', text: userPrompt },
      ];
      if (muestraImagen) userContent.push({ type: 'image_url', image_url: { url: muestraImagen, detail: 'high' } });

      const completion = await client.chat.completions.create({
        model: 'gpt-4o',
        messages: [
          { role: 'system', content: 'Eres un experto en análisis de reclutamiento para investigación de mercados. Responde ÚNICAMENTE con JSON válido, sin markdown.' },
          { role: 'user', content: userContent as any },
        ],
        response_format: { type: 'json_object' },
        temperature: 0.1,
        max_tokens: 16384,
      });
      aiResult = JSON.parse(completion.choices[0].message.content ?? '{}');
    } catch {
      aiResult = { groups: [], globalSummary: 'No se pudo generar el análisis. Intenta nuevamente.', overallStatus: 'revisar' };
    }

    // ── Merge AI criteria with pre-computed distributions ─────────────────────

    const parsedGroups = (aiResult.groups ?? []).map(g => {
      const dists = matchGroupDist(g.groupName ?? '');

      const criteria = (g.criteria ?? []).map(c => {
        const distribution = dists ? matchCriterionDist(c.criterion ?? '', dists) : undefined;
        return {
          criterion: c.criterion ?? '',
          expected: c.expected ?? '',
          actual: c.actual ?? '',
          status: (['cumple', 'revisar', 'no_cumple'].includes(c.status) ? c.status : 'revisar') as 'cumple' | 'revisar' | 'no_cumple',
          ...(c.action ? { action: c.action } : {}),
          ...(distribution ? { distribution } : {}),
        };
      });

      return {
        groupName: g.groupName ?? 'Sin nombre',
        totalParticipants: g.totalParticipants ?? 0,
        requiredParticipants: g.requiredParticipants ?? null,
        criteria,
        alerts: g.alerts ?? [],
        status: (g.status ?? 'revisar') as 'cumple' | 'revisar' | 'no_cumple',
        complianceNote: g.complianceNote ?? '',
        participants: matchParticipants(g.groupName ?? ''),
      };
    });

    const generatedAt = new Date().toISOString();

    const result = {
      muestra: muestra || (muestraImagen ? '(criterios en imagen)' : 'Sin criterios definidos'),
      groups: parsedGroups,
      globalDistributions,
      globalSummary: aiResult.globalSummary ?? '',
      overallStatus: (aiResult.overallStatus ?? 'revisar') as 'cumple' | 'revisar' | 'no_cumple',
      totalParticipants: participantData.length,
      generatedAt,
    };

    // Persist result to DB (fire-and-forget — don't block the response)
    if (project?.id) {
      try {
        const existingJson = project.lastAnalysisJson ? JSON.parse(project.lastAnalysisJson) : {};
        existingJson[boardName] = result;
        await Projects.update({
          id: project.id,
          record: {
            lastAnalysisJson: JSON.stringify(existingJson),
            lastAnalysisAt: generatedAt,
          },
        });
      } catch {
        // Non-fatal — don't surface save errors to the user
      }
    }

    return result;
  },
});

src/api/detectDuplicateSuppliers.ts.content:
import { z } from 'zod';
import { createEndpoint, Suppliers, PurchaseOrders } from 'zite-integrations-backend-sdk';

const SUFFIXES = [
  'sapi de cv mi', 'sapi de cv', 'sa de cv mi', 'sa de cv', 's a de c v',
  's a de cv', 's de rl de cv', 's de rl', 'de cv', 'a c', 's c',
  'sa', 's a', 'sl', 'srl', 'inc', 'llc', 'ltd', 'corp', 'corporation',
  'sociedad anonima de capital variable', 'sociedad anonima', 'sociedad civil',
];

function cleanRaw(name: string): string {
  let n = name;
  n = n.replace(/\S+@\S+\.\S+/g, ' ');
  n = n.replace(/https?:\/\/\S+/gi, ' ').replace(/www\.\S+/gi, ' ');
  n = n.replace(/\d[\d\s.\-]{5,}\d/g, ' ');
  n = n.replace(/[|\\#@]/g, ' ');
  return n;
}

function normalizeName(name: string): string {
  let n = cleanRaw(name).toLowerCase().trim();
  n = n.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  n = n.replace(/[.,/#!$%^&*;:{}=\-_`~()'\\"]/g, ' ');
  for (const suffix of SUFFIXES) {
    const re = new RegExp(`\\b${suffix.replace(/\s+/g, '\\s+')}\\b`, 'g');
    n = n.replace(re, ' ');
  }
  return n.replace(/\s+/g, ' ').trim();
}

function tokenize(normalized: string): Set<string> {
  return new Set(normalized.split(' ').filter(t => t.length >= 2));
}

function jaccardScore(a: Set<string>, b: Set<string>): number {
  if (a.size === 0 || b.size === 0) return 0;
  let intersection = 0;
  for (const t of a) { if (b.has(t)) intersection++; }
  const union = new Set([...a, ...b]).size;
  return intersection / union;
}

/** Merge singleton groups into multi-variant groups using Jaccard >= threshold with >= minShared tokens */
function fuzzyMergeGroups<T>(
  groups: Record<string, T[]>,
  threshold: number,
  minShared: number,
): void {
  const singletonKeys = Object.keys(groups).filter(k => groups[k].length === 1);
  const multiEntries = Object.keys(groups)
    .filter(k => groups[k].length >= 2)
    .map(k => ({ key: k, tokens: tokenize(k) }));

  for (const singleKey of singletonKeys) {
    if (!groups[singleKey]) continue; // already merged
    const singleTokens = tokenize(singleKey);
    let bestMatch: { key: string; score: number } | null = null;
    for (const { key, tokens } of multiEntries) {
      if (!groups[key]) continue;
      const score = jaccardScore(singleTokens, tokens);
      const shared = [...singleTokens].filter(t => tokens.has(t)).length;
      if (score >= threshold && shared >= minShared) {
        if (!bestMatch || score > bestMatch.score) bestMatch = { key, score };
      }
    }
    if (bestMatch) {
      for (const item of groups[singleKey]) groups[bestMatch.key].push(item);
      delete groups[singleKey];
    }
  }
}

export default createEndpoint({
  authenticated: true,
  description: 'Detect supplier name variants across Purchase Orders and duplicate suppliers in the Suppliers table. Uses aggressive cleaning and fuzzy matching (Jaccard).',
  inputSchema: z.object({}),
  outputSchema: z.object({
    groups: z.array(z.object({
      normalizedName: z.string(),
      variants: z.array(z.object({
        name: z.string(),
        poCount: z.number(),
        inDb: z.boolean(),
      })),
    })),
    existingSuppliers: z.array(z.object({
      name: z.string(),
      taxId: z.string().optional(),
    })),
    unregistered: z.array(z.object({
      name: z.string(),
      poCount: z.number(),
      suggestedMatch: z.object({
        name: z.string(),
        score: z.number(),
      }).optional(),
    })),
    supplierDuplicates: z.array(z.object({
      normalizedName: z.string(),
      suppliers: z.array(z.object({
        id: z.string(),
        name: z.string(),
        taxId: z.string().optional(),
        poCount: z.number(),
      })),
    })),
    totalGroups: z.number(),
    totalVariants: z.number(),
    totalUnregistered: z.number(),
    totalSupplierDuplicates: z.number(),
  }),
  execute: async () => {
    const [{ records: pos }, { records: suppliers }] = await Promise.all([
      PurchaseOrders.findAll({ fields: ['supplierName'], limit: 2000 }),
      Suppliers.findAll({ fields: ['supplierName', 'taxId'], limit: 2000 }),
    ]);

    // DB supplier index for fuzzy matching on unregistered
    const dbSupplierNames = new Set(
      suppliers.map(s => s.supplierName?.trim() ?? '').filter(Boolean)
    );
    const dbIndex: { originalName: string; tokens: Set<string> }[] = [];
    for (const s of suppliers) {
      if (!s.supplierName) continue;
      const norm = normalizeName(s.supplierName);
      if (norm.length < 2) continue;
      dbIndex.push({ originalName: s.supplierName, tokens: tokenize(norm) });
    }

    // Count POs per exact supplier name
    const poCountByName: Record<string, number> = {};
    for (const po of pos) {
      const name = po.supplierName?.trim();
      if (!name) continue;
      poCountByName[name] = (poCountByName[name] || 0) + 1;
    }

    // ── PO variant groups ──────────────────────────────────────────────────────
    const poGroups: Record<string, string[]> = {};
    for (const name of Object.keys(poCountByName)) {
      const key = normalizeName(name);
      if (!key || key.length < 2) continue;
      if (!poGroups[key]) poGroups[key] = [];
      poGroups[key].push(name);
    }

    // Second pass: fuzzy-merge singleton PO groups into multi-variant groups
    fuzzyMergeGroups(poGroups, 0.6, 2);

    const duplicateGroups = Object.entries(poGroups)
      .filter(([, variants]) => variants.length >= 2)
      .map(([normalizedName, variants]) => ({
        normalizedName,
        variants: variants
          .map(name => ({
            name,
            poCount: poCountByName[name] ?? 0,
            inDb: dbSupplierNames.has(name),
          }))
          .sort((a, b) => b.poCount - a.poCount),
      }))
      .sort((a, b) =>
        b.variants.reduce((s, v) => s + v.poCount, 0) -
        a.variants.reduce((s, v) => s + v.poCount, 0)
      );

    // ── Unregistered suppliers ─────────────────────────────────────────────────
    const unregistered = Object.entries(poCountByName)
      .filter(([name]) => name.length > 0 && !dbSupplierNames.has(name))
      .map(([name, poCount]) => {
        const normTokens = tokenize(normalizeName(name));
        let bestMatch: { name: string; score: number } | undefined;
        if (normTokens.size >= 1) {
          for (const entry of dbIndex) {
            const score = jaccardScore(normTokens, entry.tokens);
            const sharedCount = [...normTokens].filter(t => entry.tokens.has(t)).length;
            if (score >= 0.5 && sharedCount >= 2) {
              if (!bestMatch || score > bestMatch.score) {
                bestMatch = { name: entry.originalName, score };
              }
            }
          }
        }
        return { name, poCount, suggestedMatch: bestMatch };
      })
      .sort((a, b) => {
        if (!!a.suggestedMatch !== !!b.suggestedMatch) return a.suggestedMatch ? -1 : 1;
        return b.poCount - a.poCount;
      });

    // ── Supplier table duplicates ──────────────────────────────────────────────
    type SupplierItem = { id: string; supplierName: string; taxId?: string };
    const supplierGroups: Record<string, SupplierItem[]> = {};
    for (const s of suppliers) {
      if (!s.supplierName) continue;
      const norm = normalizeName(s.supplierName);
      if (!norm || norm.length < 2) continue;
      if (!supplierGroups[norm]) supplierGroups[norm] = [];
      supplierGroups[norm].push({ id: s.id, supplierName: s.supplierName, taxId: s.taxId || undefined });
    }

    // Second pass: fuzzy-merge singleton supplier groups
    fuzzyMergeGroups(supplierGroups, 0.6, 2);

    const supplierDuplicates = Object.entries(supplierGroups)
      .filter(([, arr]) => arr.length >= 2)
      .map(([normalizedName, arr]) => ({
        normalizedName,
        suppliers: arr
          .map(s => ({
            id: s.id,
            name: s.supplierName,
            taxId: s.taxId,
            poCount: poCountByName[s.supplierName] ?? 0,
          }))
          .sort((a, b) => b.poCount - a.poCount),
      }))
      .sort((a, b) => b.suppliers.length - a.suppliers.length);

    return {
      groups: duplicateGroups,
      existingSuppliers: suppliers
        .map(s => ({ name: s.supplierName ?? '', taxId: s.taxId || undefined }))
        .filter(s => s.name.length > 0),
      unregistered,
      supplierDuplicates,
      totalGroups: duplicateGroups.length,
      totalVariants: duplicateGroups.reduce((sum, g) => sum + g.variants.length - 1, 0),
      totalUnregistered: unregistered.length,
      totalSupplierDuplicates: supplierDuplicates.length,
    };
  },
});

src/api/searchParticipantHistory.ts.content:
import { z } from 'zod';
import { createEndpoint, RecruitmentRows, Projects } from 'zite-integrations-backend-sdk';
import {
  buildIdentityClusters, findClusterForRow, aggregateClusterReasons,
  resolveSignals, DuplicateSignalEnum, Signal, IdentityRow,
} from '../lib/duplicateIdentity';

const normalizeClient = (s?: string) => (s ?? '').toLowerCase().trim();

const STATUS_PRIORITY = ['Asistió', 'Confirmado', 'Contactado', 'Pendiente', 'Descartado', 'No show'];

// ── History entry shape ─────────────────────────────────────────────────────
const HistoryEntrySchema = z.object({
  rowId:            z.string().optional(),
  projectCode:      z.string(),
  boardName:        z.string().optional(),
  group:            z.string().optional(),
  status:           z.string().optional(),
  sourceForm:       z.string().optional(),
  participated:     z.boolean(),
  sameProject:      z.boolean(),
  sameBoard:        z.boolean(),
  isCurrentRow:     z.boolean(),
  clientName:       z.string().optional(),
  projectStartDate: z.string().optional(),
  sameClient:       z.boolean(),
  isRecent:         z.boolean(),
  warningLevel:     z.enum(['same_client', 'recent', 'old', 'same_board']).nullable(),
});

type EntryShape = z.infer<typeof HistoryEntrySchema>;

const ResultSchema = z.object({
  id:                   z.string(),
  fullName:             z.string().optional(),
  email:                z.string().optional(),
  phone:                z.string().optional(),
  matchedBy:            z.array(z.string()),
  signals:              z.array(DuplicateSignalEnum),
  primaryBadge:         DuplicateSignalEnum.nullable(),
  secondaryBadges:      z.array(DuplicateSignalEnum),
  sameBoardCount:       z.number(),
  hasHighRisk:          z.boolean(),
  hasInternalDuplicate: z.boolean(),
  identityClusterId:    z.string(),
  identityMatchReasons: z.array(z.enum(['email', 'name', 'phone'])),
  history:              z.array(HistoryEntrySchema),
});

// ── Shared: build history + signals from a set of rows ──────────────────────
function buildPersonResult(
  personRows: IdentityRow[],
  opts: {
    projectCode?: string;
    boardName?: string;
    rowId?: string;
    currentClientNorm: string;
    referenceDate: Date;
    sixMonthsAgo: Date;
    projectMap: Map<string, { client?: string; startDate?: string }>;
    clusterId: string;
    clusterReasons: ('email' | 'name' | 'phone')[];
    matchedBy: string[];
  },
) {
  const { projectCode, boardName, rowId, currentClientNorm, referenceDate, sixMonthsAgo, projectMap } = opts;

  let fullName: string | undefined;
  let email: string | undefined;
  let phone: string | undefined;
  for (const r of personRows) {
    if (!fullName && r.participantName) fullName = r.participantName;
    if (!email    && r.email)           email    = r.email;
    if (!phone    && r.phone)           phone    = r.phone;
  }

  const sameBoardEntries: EntryShape[] = [];
  const crossBoardMap = new Map<string, EntryShape>();

  for (const row of personRows) {
    if (!row.projectCode) continue;

    const rawParticipated = row.status === 'Asistió' || (!!row.group && String(row.group).trim() !== '');
    const sameProject     = !!projectCode && row.projectCode === projectCode;
    const sameBoard       = sameProject && !!boardName && row.boardName === boardName;
    const isCurrentRow    = !!rowId && row.id === rowId;

    const projData         = projectMap.get(row.projectCode) ?? {};
    const clientName       = projData.client;
    const projectStartDate = projData.startDate;

    const otherStartDate  = projectStartDate ? new Date(projectStartDate) : null;
    const isFutureProject = !sameProject && !sameBoard && !!otherStartDate && otherStartDate > referenceDate;
    const isRecent        = !projectStartDate || new Date(projectStartDate) > sixMonthsAgo;

    const sameClient = !isFutureProject && !sameBoard && !sameProject && !!currentClientNorm &&
      !!clientName && normalizeClient(clientName) === currentClientNorm;

    let participated: boolean;
    let warningLevel: EntryShape['warningLevel'];

    if (isFutureProject) {
      participated = false; warningLevel = null;
    } else if (sameBoard) {
      participated = false; warningLevel = 'same_board';
    } else if (sameClient && rawParticipated) {
      participated = true; warningLevel = 'same_client';
    } else if (!sameProject && rawParticipated && isRecent) {
      participated = true; warningLevel = 'recent';
    } else if (!sameProject && rawParticipated && !isRecent) {
      participated = false; warningLevel = 'old';
    } else {
      participated = false; warningLevel = null;
    }

    const entry: EntryShape = {
      rowId: row.id, projectCode: row.projectCode, boardName: row.boardName,
      group: row.group, status: row.status, sourceForm: row.sourceForm,
      participated, sameProject, sameBoard, isCurrentRow,
      clientName, projectStartDate, sameClient, isRecent, warningLevel,
    };

    if (sameBoard) {
      sameBoardEntries.push(entry);
    } else {
      const boardKey = `${row.projectCode}||${row.boardName ?? ''}`;
      const existing = crossBoardMap.get(boardKey);
      if (!existing) {
        crossBoardMap.set(boardKey, entry);
      } else {
        const curIdx  = STATUS_PRIORITY.indexOf(row.status ?? '');
        const prevIdx = STATUS_PRIORITY.indexOf(existing.status ?? '');
        const betterStatus = (curIdx !== -1 && (prevIdx === -1 || curIdx < prevIdx)) ? row.status : existing.status;
        const levelRank = (l: EntryShape['warningLevel']) =>
          l === 'same_client' ? 4 : l === 'recent' ? 3 : l === 'old' ? 2 : l === 'same_board' ? 1 : 0;
        const worstWarning = levelRank(entry.warningLevel) >= levelRank(existing.warningLevel)
          ? entry.warningLevel : existing.warningLevel;
        const finalParticipated = worstWarning === 'same_client' || worstWarning === 'recent';
        crossBoardMap.set(boardKey, {
          ...existing,
          status: betterStatus,
          group: existing.group || row.group,
          sourceForm: existing.sourceForm || row.sourceForm,
          participated: finalParticipated,
          warningLevel: worstWarning,
          sameClient: existing.sameClient || entry.sameClient,
        });
      }
    }
  }

  sameBoardEntries.sort((a, b) => {
    if (a.isCurrentRow && !b.isCurrentRow) return -1;
    if (!a.isCurrentRow && b.isCurrentRow) return 1;
    return STATUS_PRIORITY.indexOf(a.status ?? '') - STATUS_PRIORITY.indexOf(b.status ?? '');
  });

  const history: EntryShape[] = [...sameBoardEntries, ...[...crossBoardMap.values()]];

  const sameBoardCount = sameBoardEntries.length;
  const signalSet = new Set<Signal>();

  for (const entry of crossBoardMap.values()) {
    if (entry.sameProject) continue;
    if (entry.projectStartDate && new Date(entry.projectStartDate) > referenceDate) continue;

    if (entry.warningLevel === 'same_client')  signalSet.add('same_client');
    else if (entry.warningLevel === 'recent')  signalSet.add('recent');
    else if (entry.warningLevel === 'old')     signalSet.add('old');
    else if (entry.warningLevel === null)      signalSet.add('registered_only');
  }

  if (sameBoardCount > 1) signalSet.add('same_board_duplicate');

  const { signals, primaryBadge, secondaryBadges } = resolveSignals(signalSet);

  return {
    id:                   opts.clusterId,
    fullName,
    email,
    phone,
    matchedBy:            opts.matchedBy,
    signals,
    primaryBadge,
    secondaryBadges,
    sameBoardCount,
    hasHighRisk:          primaryBadge === 'same_client' || primaryBadge === 'recent',
    hasInternalDuplicate: sameBoardCount > 1,
    identityClusterId:    opts.clusterId,
    identityMatchReasons: opts.clusterReasons,
    history,
  };
}

// ── Helper: load all active rows paginated ──────────────────────────────────
async function loadAllActiveRows(): Promise<IdentityRow[]> {
  const allRows: IdentityRow[] = [];
  let offset = 0;
  let hasMore = true;
  while (hasMore) {
    const batch = await RecruitmentRows.findAll({
      limit: 2000,
      offset,
      fields: ['id', 'participantName', 'email', 'phone', 'projectCode', 'boardName', 'status', 'group', 'sourceForm', 'deletedAt'],
    });
    allRows.push(...batch.records);
    hasMore = batch.hasMore;
    offset += batch.records.length;
  }
  return allRows.filter(r => !r.deletedAt);
}

// ── Helper: load project metadata ───────────────────────────────────────────
async function loadProjectMap(projectCodes: string[]): Promise<Map<string, { client?: string; startDate?: string }>> {
  const projectMap = new Map<string, { client?: string; startDate?: string }>();
  if (projectCodes.length === 0) return projectMap;
  const { records } = await Projects.findAll({
    filters: { projectCode: { in: [...new Set(projectCodes)] } },
    fields: ['projectCode', 'client', 'startDate'],
    limit: 500,
  });
  for (const p of records) {
    if (p.projectCode) projectMap.set(p.projectCode, { client: p.client, startDate: p.startDate });
  }
  return projectMap;
}

// ── Endpoint ────────────────────────────────────────────────────────────────

export default createEndpoint({
  authenticated: true,
  description: 'Search participant history — seed mode (canonical, complete) or query mode (exploratory)',
  inputSchema: z.object({
    seedRowId:     z.string().optional(),
    query:         z.string().optional(),
    projectCode:   z.string().optional(),
    boardName:     z.string().optional(),
    rowId:         z.string().optional(),
    currentClient: z.string().optional(),
  }),
  outputSchema: z.object({
    results: z.array(ResultSchema),
  }),

  execute: async ({ input }) => {
    const isSeedMode = !!input.seedRowId;

    // ═══════════════════════════════════════════════════════════════════════
    // SEED MODE — canonical, complete identity resolution
    // ═══════════════════════════════════════════════════════════════════════
    if (isSeedMode) {
      const activeRows = await loadAllActiveRows();
      if (activeRows.length === 0) return { results: [] };

      const clusters = buildIdentityClusters(activeRows);
      const match = findClusterForRow(clusters, input.seedRowId!);
      if (!match) return { results: [] };

      const { clusterId, cluster } = match;
      const rowById = new Map(activeRows.map(r => [r.id, r]));
      const personRows = cluster.rowIds.map(id => rowById.get(id)).filter((r): r is IdentityRow => !!r);

      const clusterProjectCodes = personRows.map(r => r.projectCode).filter(Boolean) as string[];
      if (input.projectCode) clusterProjectCodes.push(input.projectCode);
      const projectMap = await loadProjectMap(clusterProjectCodes);

      const currentProjectStartDate = input.projectCode ? projectMap.get(input.projectCode)?.startDate : undefined;
      const referenceDate = currentProjectStartDate ? new Date(currentProjectStartDate) : new Date();
      const sixMonthsAgo = new Date(referenceDate);
      sixMonthsAgo.setMonth(sixMonthsAgo.getMonth() - 6);
      const currentClientNorm = normalizeClient(input.currentClient);

      const clusterReasons = aggregateClusterReasons(cluster);

      const result = buildPersonResult(personRows, {
        projectCode:     input.projectCode,
        boardName:       input.boardName,
        rowId:           input.rowId ?? input.seedRowId,
        currentClientNorm,
        referenceDate,
        sixMonthsAgo,
        projectMap,
        clusterId,
        clusterReasons,
        matchedBy: clusterReasons,
      });

      return { results: [result] };
    }

    // ═══════════════════════════════════════════════════════════════════════
    // QUERY MODE — exploratory search
    // ═══════════════════════════════════════════════════════════════════════
    const q = (input.query ?? '').trim();
    if (q.length < 2) return { results: [] };

    const searchFields = ['id', 'participantName', 'email', 'phone', 'projectCode', 'boardName', 'status', 'group', 'sourceForm', 'deletedAt'];

    const [byName, byEmail, byPhone] = await Promise.all([
      RecruitmentRows.findAll({ filters: { participantName: { contains: q } }, limit: 200, fields: searchFields }),
      RecruitmentRows.findAll({ filters: { email:           { contains: q } }, limit: 200, fields: searchFields }),
      RecruitmentRows.findAll({ filters: { phone:           { contains: q } }, limit: 200, fields: searchFields }),
    ]);

    const matchedByEmailIds = new Set(byEmail.records.map(r => r.id));
    const matchedByNameIds  = new Set(byName.records.map(r => r.id));
    const matchedByPhoneIds = new Set(byPhone.records.map(r => r.id));

    const seen = new Set<string>();
    const allRows: IdentityRow[] = [];
    for (const r of [...byEmail.records, ...byName.records, ...byPhone.records]) {
      if (!seen.has(r.id)) { seen.add(r.id); allRows.push(r); }
    }
    const activeRows = allRows.filter(r => !r.deletedAt);
    if (activeRows.length === 0) return { results: [] };

    const clusters = buildIdentityClusters(activeRows);

    const rowProjectCodes = activeRows.map(r => r.projectCode).filter(Boolean) as string[];
    if (input.projectCode) rowProjectCodes.push(input.projectCode);
    const projectMap = await loadProjectMap(rowProjectCodes);

    const currentProjectStartDate = input.projectCode ? projectMap.get(input.projectCode)?.startDate : undefined;
    const referenceDate = currentProjectStartDate ? new Date(currentProjectStartDate) : new Date();
    const sixMonthsAgo = new Date(referenceDate);
    sixMonthsAgo.setMonth(sixMonthsAgo.getMonth() - 6);
    const currentClientNorm = normalizeClient(input.currentClient);

    const rowById = new Map(activeRows.map(r => [r.id, r]));

    const results = [...clusters.entries()].slice(0, 10).map(([clusterId, cluster]) => {
      const personRows = cluster.rowIds.map(id => rowById.get(id)).filter((r): r is IdentityRow => !!r);
      if (personRows.length === 0) return null;

      const queryMatchedBy = new Set<string>();
      for (const rid of cluster.rowIds) {
        if (matchedByEmailIds.has(rid)) queryMatchedBy.add('email');
        if (matchedByNameIds.has(rid))  queryMatchedBy.add('name');
        if (matchedByPhoneIds.has(rid)) queryMatchedBy.add('phone');
      }

      const clusterReasons = aggregateClusterReasons(cluster);

      return buildPersonResult(personRows, {
        projectCode:     input.projectCode,
        boardName:       input.boardName,
        rowId:           input.rowId,
        currentClientNorm,
        referenceDate,
        sixMonthsAgo,
        projectMap,
        clusterId,
        clusterReasons,
        matchedBy: [...queryMatchedBy],
      });
    }).filter((r): r is NonNullable<typeof r> => r !== null);

    results.sort((a, b) => b.history.length - a.history.length);

    return { results };
  },
});

