import { useState, useCallback, useRef } from 'react';
import { uploadFile } from 'zite-file-upload-sdk';
import { parseOdcCsv, importOdcFromCsv, ParseOdcCsvOutputType } from 'zite-endpoints-sdk';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Upload, Loader2, Play, CheckCircle2, AlertTriangle, FileText, Trash2, Plus, RefreshCw, DollarSign } from 'lucide-react';
import { cn } from '@/lib/utils';
import { toast } from 'sonner';
import OdcMappingPanel from './OdcMappingPanel';

type Preview = ParseOdcCsvOutputType;
type ImportMode = 'new_only' | 'all' | 'amounts_only';

function StatCard({ label, value, sub }: { label: string; value: string | number; sub?: string }) {
  return (
    <div className="rounded-xl border bg-card p-4 space-y-1">
      <p className="text-xs text-muted-foreground font-medium">{label}</p>
      <p className="text-2xl font-bold text-foreground">{typeof value === 'number' ? value.toLocaleString('es-MX') : value}</p>
      {sub && <p className="text-xs text-muted-foreground">{sub}</p>}
    </div>
  );
}

function SampleTable({ odcs, existingPoNumbers }: { odcs: Preview['sampleOdcs']; existingPoNumbers?: string[] }) {
  const existingSet = new Set(existingPoNumbers ?? []);
  return (
    <div className="rounded-xl border overflow-hidden text-sm">
      <div className="bg-muted/50 px-4 py-2 border-b">
        <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">Muestra de ODCs (primeras 25)</p>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full">
          <thead>
            <tr className="border-b text-xs text-muted-foreground">
              <th className="text-left px-4 py-2 font-medium">ODC</th>
              <th className="text-left px-4 py-2 font-medium">Proyecto</th>
              <th className="text-left px-4 py-2 font-medium">Descripción</th>
              <th className="text-left px-4 py-2 font-medium">Proveedor</th>
              <th className="text-left px-4 py-2 font-medium">Rubro</th>
              <th className="text-right px-4 py-2 font-medium">Total MXN</th>
              <th className="text-center px-4 py-2 font-medium">Items</th>
              <th className="text-center px-4 py-2 font-medium">Estado</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-border">
            {odcs.map((odc, i) => (
              <tr key={i} className={cn('hover:bg-muted/30 text-xs', existingSet.has(odc.poNumber) && 'opacity-40')}>
                <td className="px-4 py-2 font-mono font-bold text-primary">
                  {odc.poNumber}
                  {existingSet.has(odc.poNumber) && (
                    <span className="ml-1.5 text-[9px] px-1 py-0.5 rounded bg-muted text-muted-foreground border border-border font-sans">existente</span>
                  )}
                </td>
                <td className="px-4 py-2 font-medium max-w-[100px] truncate">{odc.projectCode || '—'}</td>
                <td className="px-4 py-2 text-muted-foreground max-w-[160px] truncate">{odc.description || <em className="opacity-50">sin nombre</em>}</td>
                <td className="px-4 py-2 max-w-[140px] truncate">
                  <span className={odc.supplierFound ? 'text-foreground' : 'text-muted-foreground'}>{odc.supplierName}</span>
                  {odc.supplierFound && odc.matchedBy === 'email' && <span className="ml-1 text-[10px] text-sky-600 bg-sky-50 px-1 rounded">email</span>}
                  {odc.supplierFound && odc.matchedBy === 'name' && <span className="ml-1 text-[10px] text-violet-600 bg-violet-50 px-1 rounded">nombre</span>}
                  {!odc.supplierFound && odc.supplierName !== '—' && <span className="ml-1 text-[10px] text-amber-600 bg-amber-50 px-1 rounded">no match</span>}
                </td>
                <td className="px-4 py-2 text-muted-foreground max-w-[120px] truncate">{odc.rubro}</td>
                <td className="px-4 py-2 text-right font-mono">{odc.totalAmount > 0 ? `$${odc.totalAmount.toLocaleString('es-MX', { maximumFractionDigits: 0 })}` : '—'}</td>
                <td className="px-4 py-2 text-center">{odc.lineItemCount > 0 ? odc.lineItemCount : <span className="text-muted-foreground">—</span>}</td>
                <td className="px-4 py-2 text-center">
                  <span className={cn('text-[10px] px-2 py-0.5 rounded-full font-medium border',
                    odc.status === 'Pagada' ? 'bg-primary/10 text-primary border-primary/20' : 'bg-muted text-muted-foreground border-border'
                  )}>{odc.status}</span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function ImportModeSelector({
  mode,
  onChange,
  preview,
}: {
  mode: ImportMode;
  onChange: (m: ImportMode) => void;
  preview: Preview;
}) {
  const { newOdcCount, existingOdcCount, totalOdcs } = preview;

  return (
    <div className="space-y-2">
      <p className="text-sm font-semibold text-foreground">¿Qué ODCs importar?</p>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
        {/* Solo nuevas */}
        <button
          type="button"
          onClick={() => onChange('new_only')}
          className={cn(
            'relative text-left rounded-xl border-2 p-4 transition-all focus:outline-none',
            mode === 'new_only'
              ? 'border-primary bg-primary/5 shadow-sm'
              : 'border-border bg-card hover:border-primary/40 hover:bg-muted/30'
          )}
        >
          <div className="flex items-start gap-3">
            <div className={cn('mt-0.5 flex-shrink-0 w-9 h-9 rounded-lg flex items-center justify-center',
              mode === 'new_only' ? 'bg-primary/15 text-primary' : 'bg-muted text-muted-foreground'
            )}>
              <Plus className="w-4 h-4" />
            </div>
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2 flex-wrap">
                <span className="font-semibold text-sm text-foreground">Solo importar nuevas</span>
                <Badge className="bg-primary/15 text-primary border-primary/20 hover:bg-primary/15 text-xs">
                  {newOdcCount.toLocaleString('es-MX')} nuevas
                </Badge>
              </div>
              <p className="text-xs text-muted-foreground mt-1">
                {existingOdcCount > 0
                  ? `Las ${existingOdcCount.toLocaleString('es-MX')} ODCs existentes se ignorarán`
                  : 'No hay ODCs existentes que ignorar'}
              </p>
            </div>
          </div>
          {/* Radio indicator */}
          <div className={cn(
            'absolute top-3.5 right-3.5 w-4 h-4 rounded-full border-2 flex items-center justify-center',
            mode === 'new_only' ? 'border-primary' : 'border-muted-foreground/30'
          )}>
            {mode === 'new_only' && <div className="w-2 h-2 rounded-full bg-primary" />}
          </div>
        </button>

        {/* Importar todas */}
        <button
          type="button"
          onClick={() => onChange('all')}
          className={cn(
            'relative text-left rounded-xl border-2 p-4 transition-all focus:outline-none',
            mode === 'all'
              ? 'border-primary bg-primary/5 shadow-sm'
              : 'border-border bg-card hover:border-primary/40 hover:bg-muted/30'
          )}
        >
          <div className="flex items-start gap-3">
            <div className={cn('mt-0.5 flex-shrink-0 w-9 h-9 rounded-lg flex items-center justify-center',
              mode === 'all' ? 'bg-primary/15 text-primary' : 'bg-muted text-muted-foreground'
            )}>
              <RefreshCw className="w-4 h-4" />
            </div>
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2 flex-wrap">
                <span className="font-semibold text-sm text-foreground">Importar todas</span>
                <Badge variant="secondary" className="text-xs">
                  {totalOdcs.toLocaleString('es-MX')} totales
                </Badge>
              </div>
              <p className="text-xs text-muted-foreground mt-1">
                {existingOdcCount > 0
                  ? `${existingOdcCount.toLocaleString('es-MX')} existentes se actualizarán`
                  : 'No hay ODCs existentes para actualizar'}
              </p>
            </div>
          </div>
          <div className={cn(
            'absolute top-3.5 right-3.5 w-4 h-4 rounded-full border-2 flex items-center justify-center',
            mode === 'all' ? 'border-primary' : 'border-muted-foreground/30'
          )}>
            {mode === 'all' && <div className="w-2 h-2 rounded-full bg-primary" />}
          </div>
        </button>
      </div>

      {/* Solo actualizar montos — full width */}
      <button
        type="button"
        onClick={() => onChange('amounts_only')}
        className={cn(
          'relative w-full text-left rounded-xl border-2 p-4 transition-all focus:outline-none',
          mode === 'amounts_only'
            ? 'border-primary bg-primary/5 shadow-sm'
            : 'border-border bg-card hover:border-primary/40 hover:bg-muted/30'
        )}
      >
        <div className="flex items-start gap-3">
          <div className={cn('mt-0.5 flex-shrink-0 w-9 h-9 rounded-lg flex items-center justify-center',
            mode === 'amounts_only' ? 'bg-primary/15 text-primary' : 'bg-muted text-muted-foreground'
          )}>
            <DollarSign className="w-4 h-4" />
          </div>
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 flex-wrap">
              <span className="font-semibold text-sm text-foreground">Solo actualizar montos</span>
              <Badge variant="outline" className="text-xs text-muted-foreground">
                {existingOdcCount.toLocaleString('es-MX')} ODCs existentes
              </Badge>
            </div>
            <p className="text-xs text-muted-foreground mt-1">
              Solo actualiza <strong className="text-foreground">totalAmount</strong>, <strong className="text-foreground">tipoDeOc</strong> y <strong className="text-foreground">subitems</strong> en ODCs ya existentes.
              No toca proveedores ni proyectos. Las ODCs sin número de match se ignoran.
            </p>
          </div>
        </div>
        <div className={cn(
          'absolute top-3.5 right-3.5 w-4 h-4 rounded-full border-2 flex items-center justify-center',
          mode === 'amounts_only' ? 'border-primary' : 'border-muted-foreground/30'
        )}>
          {mode === 'amounts_only' && <div className="w-2 h-2 rounded-full bg-primary" />}
        </div>
      </button>
    </div>
  );
}

export default function OdcImportSection() {
  const [dragging, setDragging] = useState(false);
  const [fileName, setFileName] = useState<string | null>(null);
  const [csvUrl, setCsvUrl] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);
  const [preview, setPreview] = useState<Preview | null>(null);
  const [importMode, setImportMode] = useState<ImportMode>('new_only');
  const [projectMappings, setProjectMappings] = useState<Record<string, string>>({});
  const [supplierMappings, setSupplierMappings] = useState<Record<string, string>>({});
  const [importing, setImporting] = useState(false);
  const [progress, setProgress] = useState({ done: 0, total: 0 });
  const [importDone, setImportDone] = useState(false);
  const [importSummary, setImportSummary] = useState({ newCount: 0, updatedCount: 0 });
  const [error, setError] = useState<string | null>(null);
  const fileRef = useRef<HTMLInputElement>(null);

  const reset = () => {
    setFileName(null); setCsvUrl(null); setPreview(null);
    setImportDone(false); setError(null); setProgress({ done: 0, total: 0 });
    setImportSummary({ newCount: 0, updatedCount: 0 });
    setProjectMappings({}); setSupplierMappings({});
    setImportMode('new_only');
  };

  const handleFile = useCallback(async (file: File) => {
    if (!file.name.endsWith('.csv')) { setError('Solo se aceptan archivos .csv'); return; }
    setError(null); setPreview(null); setImportDone(false);
    setFileName(file.name); setUploading(true);
    try {
      const { fileUrl } = await uploadFile({ data: file, filename: file.name });
      setCsvUrl(fileUrl);
      const result = await parseOdcCsv({ csvUrl: fileUrl });
      if (result.totalOdcs === 0) {
        setError('No se encontraron ODCs (códigos como RI-001, MD-001, etc.) en el archivo.');
        setFileName(null);
      } else {
        setPreview(result);
        setImportMode(result.newOdcCount > 0 ? 'new_only' : 'all');
        const pm: Record<string, string> = {};
        result.projectsToCreate.forEach(code => { pm[code] = 'create'; });
        setProjectMappings(pm);
        const sm: Record<string, string> = {};
        result.suppliersNotFound.forEach((s, i) => {
          const key = s.rfc || s.name || `row-${i}`;
          sm[key] = s.suggestedMatch ?? 'raw';
        });
        setSupplierMappings(sm);
      }
    } catch (e: any) {
      setError(e?.message ?? 'Error al procesar el archivo');
      setFileName(null);
    } finally {
      setUploading(false);
    }
  }, []);

  const handleImport = async () => {
    if (!csvUrl || !preview) return;
    const skipExisting = importMode === 'new_only';
    const amountsOnly = importMode === 'amounts_only';
    const odcCountForImport = amountsOnly
      ? preview.existingOdcCount
      : skipExisting ? preview.newOdcCount : preview.totalOdcs;
    setImporting(true);
    setProgress({ done: 0, total: odcCountForImport });
    let totalNew = 0;
    let totalUpdated = 0;
    let offset = 0;
    const batchSize = 50;
    try {
      while (true) {
        const result = await importOdcFromCsv({
          csvUrl,
          batchOffset: offset,
          batchSize,
          projectMappings,
          supplierMappings,
          skipExisting,
          amountsOnly,
        });
        totalNew += result.newCount;
        totalUpdated += result.updatedCount;
        setProgress({ done: totalNew + totalUpdated, total: odcCountForImport });
        if (result.done) break;
        offset += batchSize;
      }
      setImportSummary({ newCount: totalNew, updatedCount: totalUpdated });
      setImportDone(true);
      const msg = totalUpdated > 0
        ? `✅ ${totalNew} ODCs nuevas, ${totalUpdated} actualizadas`
        : `✅ ${totalNew} ODCs importadas correctamente`;
      toast.success(msg);
      setPreview(null); setFileName(null); setCsvUrl(null);
    } catch (e: any) {
      toast.error(e?.message ?? 'Error durante la importación');
    } finally {
      setImporting(false);
    }
  };

  const onDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault(); setDragging(false);
    const file = e.dataTransfer.files[0];
    if (file) handleFile(file);
  }, [handleFile]);

  if (importDone) {
    return (
      <div className="flex flex-col items-center justify-center py-16 space-y-4">
        <div className="w-16 h-16 rounded-full bg-primary/10 flex items-center justify-center"><CheckCircle2 className="w-8 h-8 text-primary" /></div>
        <p className="text-lg font-bold">¡Importación completada!</p>
        <div className="flex flex-col items-center gap-1.5">
          <div className="flex items-center gap-2 text-sm">
            <span className="w-2.5 h-2.5 rounded-full bg-primary inline-block" />
            <span className="font-semibold text-foreground">{importSummary.newCount.toLocaleString('es-MX')}</span>
            <span className="text-muted-foreground">ODCs nuevas creadas</span>
          </div>
          {importSummary.updatedCount > 0 && (
            <div className="flex items-center gap-2 text-sm">
              <span className="w-2.5 h-2.5 rounded-full bg-muted-foreground inline-block" />
              <span className="font-semibold text-foreground">{importSummary.updatedCount.toLocaleString('es-MX')}</span>
              <span className="text-muted-foreground">ODCs existentes actualizadas</span>
            </div>
          )}
        </div>
        <Button variant="outline" onClick={reset}>Importar otro archivo</Button>
      </div>
    );
  }

  // Derived values based on mode
  const displayOdcCount = preview
    ? (importMode === 'new_only' ? preview.newOdcCount : preview.totalOdcs)
    : 0;
  const displayLineItems = preview
    ? (importMode === 'new_only'
        ? Math.round(preview.totalLineItems * (preview.newOdcCount / Math.max(preview.totalOdcs, 1)))
        : preview.totalLineItems)
    : 0;
  const filteredSampleOdcs = preview
    ? (importMode === 'new_only'
        ? preview.sampleOdcs.filter(o => !preview.existingPoNumbers.includes(o.poNumber))
        : preview.sampleOdcs)
    : [];

  return (
    <div className="space-y-6">
      {/* Drop zone */}
      {!preview && (
        <div
          onDragOver={e => { e.preventDefault(); setDragging(true); }}
          onDragLeave={() => setDragging(false)}
          onDrop={onDrop}
          onClick={() => !uploading && fileRef.current?.click()}
          className={cn(
            'border-2 border-dashed rounded-2xl p-12 flex flex-col items-center justify-center gap-4 transition-all',
            uploading ? 'cursor-wait opacity-70' : 'cursor-pointer',
            dragging ? 'border-primary bg-primary/5 scale-[1.01]' : 'border-border bg-muted/20 hover:border-primary/50 hover:bg-muted/40'
          )}
        >
          <div className={cn('w-14 h-14 rounded-full flex items-center justify-center', dragging ? 'bg-primary/20' : 'bg-muted')}>
            {uploading ? <Loader2 className="w-6 h-6 animate-spin text-primary" /> : <Upload className={cn('w-6 h-6', dragging ? 'text-primary' : 'text-muted-foreground')} />}
          </div>
          <div className="text-center">
            <p className="font-semibold text-foreground">{uploading ? 'Analizando archivo…' : dragging ? 'Suelta el archivo aquí' : 'Arrastra el CSV aquí'}</p>
            <p className="text-sm text-muted-foreground mt-1">{uploading ? 'Subiendo y parseando, un momento…' : 'CSV exportado de Monday.com — ODC Reclutamiento'}</p>
          </div>
          <input ref={fileRef} type="file" accept=".csv" className="hidden" onChange={e => { const f = e.target.files?.[0]; if (f) handleFile(f); e.target.value = ''; }} />
        </div>
      )}

      {error && <Alert variant="destructive"><AlertTriangle className="h-4 w-4" /><AlertDescription>{error}</AlertDescription></Alert>}

      {preview && (
        <div className="space-y-5">
          {/* File info */}
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <FileText className="w-4 h-4 text-muted-foreground" />
              <span className="text-sm font-medium">{fileName}</span>
              <Badge variant="secondary">{preview.totalOdcs.toLocaleString('es-MX')} ODCs encontradas</Badge>
              {preview.existingOdcCount > 0 && (
                <Badge variant="outline" className="text-muted-foreground">
                  {preview.existingOdcCount.toLocaleString('es-MX')} ya existen
                </Badge>
              )}
            </div>
            <Button variant="ghost" size="sm" onClick={reset} className="gap-1.5 text-muted-foreground"><Trash2 className="w-3.5 h-3.5" />Limpiar</Button>
          </div>

          {/* Import mode selector */}
          <ImportModeSelector mode={importMode} onChange={setImportMode} preview={preview} />

          {/* Stats */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
            <StatCard label="ODCs a importar" value={displayOdcCount} />
            <StatCard label="Line items aprox." value={displayLineItems} />
            {importMode !== 'amounts_only' && (
              <StatCard
                label="Proyectos"
                value={preview.totalProjects}
                sub={preview.projectsToCreate.length > 0 ? `${preview.projectsToCreate.length} a resolver` : 'todos existentes'}
              />
            )}
            <StatCard label="Total (MXN$)" value={`${Math.round(preview.totalAmount).toLocaleString('es-MX')}`} />
          </div>

          {/* Mapping panel — hidden in amounts_only mode */}
          {importMode !== 'amounts_only' && (
            <OdcMappingPanel
              preview={preview}
              projectMappings={projectMappings}
              supplierMappings={supplierMappings}
              onProjectMap={(code, decision) => setProjectMappings(prev => ({ ...prev, [code]: decision }))}
              onSupplierMap={(key, decision) => setSupplierMappings(prev => ({ ...prev, [key]: decision }))}
            />
          )}

          {/* Sample */}
          <SampleTable
            odcs={importMode === 'new_only' ? filteredSampleOdcs : preview.sampleOdcs}
            existingPoNumbers={importMode === 'all' ? preview.existingPoNumbers : []}
          />

          {/* Import button / progress */}
          {importing ? (
            <div className="rounded-xl border bg-card p-5 space-y-3">
              <div className="flex items-center justify-between text-sm">
                <span className="font-medium flex items-center gap-2"><Loader2 className="w-4 h-4 animate-spin text-primary" />Importando ODCs…</span>
                <span className="text-muted-foreground font-mono">{progress.done.toLocaleString('es-MX')} / {progress.total.toLocaleString('es-MX')}</span>
              </div>
              <Progress value={progress.total > 0 ? (progress.done / progress.total) * 100 : 0} className="h-2" />
              <p className="text-xs text-muted-foreground">No cierres esta página. El proceso puede tardar varios minutos.</p>
            </div>
          ) : (
            <div className="flex items-center justify-between pt-2">
              <p className="text-sm text-muted-foreground">
                {importMode === 'new_only' ? (
                  <>Se importarán <strong className="text-foreground">{preview.newOdcCount.toLocaleString('es-MX')} ODCs nuevas</strong>.
                  {preview.existingOdcCount > 0 && <span className="ml-1">Las {preview.existingOdcCount.toLocaleString('es-MX')} existentes se ignorarán.</span>}</>
                ) : importMode === 'amounts_only' ? (
                  <>Se actualizarán montos y subitems de <strong className="text-foreground">{preview.existingOdcCount.toLocaleString('es-MX')} ODCs existentes</strong>. No se crean registros nuevos.</>
                ) : (
                  <>Se importarán <strong className="text-foreground">{preview.totalOdcs.toLocaleString('es-MX')} ODCs</strong> con{' '}
                  <strong className="text-foreground">{preview.totalLineItems.toLocaleString('es-MX')} líneas de detalle</strong>.
                  {preview.existingOdcCount > 0 && <span className="ml-1">{preview.existingOdcCount.toLocaleString('es-MX')} se actualizarán.</span>}</>
                )}
              </p>
              <Button onClick={handleImport} className="gap-2 min-w-[200px]">
                {importMode === 'new_only' ? (
                  <><Plus className="w-4 h-4" />Importar {preview.newOdcCount.toLocaleString('es-MX')} ODCs nuevas</>
                ) : importMode === 'amounts_only' ? (
                  <><DollarSign className="w-4 h-4" />Actualizar {preview.existingOdcCount.toLocaleString('es-MX')} montos</>
                ) : (
                  <><Play className="w-4 h-4" />Importar {preview.totalOdcs.toLocaleString('es-MX')} ODCs{preview.existingOdcCount > 0 ? ` (${preview.existingOdcCount} actualizaciones)` : ''}</>
                )}
              </Button>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

src/components/ProjectDocuments.tsx.content:
import { useEffect, useState } from 'react';
import { FileSpreadsheet, BarChart3, ExternalLink, FileText, RefreshCw } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Skeleton } from '@/components/ui/skeleton';
import { getProjectDocuments, GetProjectDocumentsOutputType } from 'zite-endpoints-sdk';

type Document = GetProjectDocumentsOutputType['documents'][0];

interface Props {
  projectCode: string;
}

function formatDate(iso?: string) {
  if (!iso) return '';
  const d = new Date(iso + 'T00:00:00');
  return d.toLocaleDateString('es-MX', { day: '2-digit', month: 'short', year: 'numeric' });
}

function DocCard({ doc }: { doc: Document }) {
  return (
    <div className="flex items-center justify-between gap-4 py-3 px-4 rounded-lg bg-muted/40 hover:bg-muted/70 transition-colors group">
      <div className="min-w-0">
        <p className="text-sm font-medium text-foreground truncate">
          {doc.documentName ?? 'Sin nombre'}
        </p>
        <div className="flex items-center gap-2 mt-0.5 flex-wrap">
          {doc.version && (
            <span className="text-xs text-muted-foreground">v{doc.version}</span>
          )}
          {doc.uploadDate && (
            <span className="text-xs text-muted-foreground">{formatDate(doc.uploadDate)}</span>
          )}
        </div>
      </div>
      {doc.fileUrl ? (
        <Button
          variant="ghost"
          size="sm"
          className="gap-1.5 flex-shrink-0 text-primary opacity-70 group-hover:opacity-100"
          onClick={() => window.open(doc.fileUrl!, '_blank', 'noopener,noreferrer')}
        >
          <ExternalLink className="w-3.5 h-3.5" />
          <span className="hidden sm:inline text-xs">Abrir</span>
        </Button>
      ) : (
        <span className="text-xs text-muted-foreground flex-shrink-0">Sin link</span>
      )}
    </div>
  );
}

function DocSection({
  title,
  icon: Icon,
  docs,
  iconClass,
}: {
  title: string;
  icon: React.ComponentType<{ className?: string }>;
  docs: Document[];
  iconClass: string;
}) {
  return (
    <div>
      <div className="flex items-center gap-2 mb-3">
        <div className={`w-7 h-7 rounded-lg flex items-center justify-center ${iconClass}`}>
          <Icon className="w-4 h-4 text-primary-foreground" />
        </div>
        <h3 className="text-sm font-semibold text-foreground">{title}</h3>
        <span className="text-xs text-muted-foreground">({docs.length})</span>
      </div>
      {docs.length === 0 ? (
        <p className="text-xs text-muted-foreground italic pl-9">No hay documentos todavía</p>
      ) : (
        <div className="space-y-1.5">
          {docs.map(doc => <DocCard key={doc.id} doc={doc} />)}
        </div>
      )}
    </div>
  );
}

export default function ProjectDocuments({ projectCode }: Props) {
  const [docs, setDocs] = useState<Document[]>([]);
  const [loading, setLoading] = useState(true);

  const load = async () => {
    setLoading(true);
    try {
      const res = await getProjectDocuments({ projectCode });
      setDocs(res.documents);
    } catch { /* ignore */ } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, [projectCode]);

  const calendarios = docs.filter(d => d.category === 'Calendario');
  const timelines   = docs.filter(d => d.category === 'Timeline');
  const isEmpty     = docs.length === 0;

  if (loading) {
    return (
      <div className="p-6 space-y-6">
        <Skeleton className="h-6 w-40" />
        <div className="space-y-2">
          <Skeleton className="h-12 w-full" />
          <Skeleton className="h-12 w-full" />
        </div>
        <Skeleton className="h-6 w-32 mt-4" />
        <div className="space-y-2">
          <Skeleton className="h-12 w-full" />
        </div>
      </div>
    );
  }

  if (isEmpty) {
    return (
      <div className="flex flex-col items-center justify-center h-full text-center p-12">
        <div className="w-16 h-16 rounded-2xl bg-muted flex items-center justify-center mb-4">
          <FileText className="w-8 h-8 text-muted-foreground" />
        </div>
        <h3 className="text-lg font-semibold mb-2">Sin documentos aún</h3>
        <p className="text-muted-foreground text-sm max-w-sm">
          Los archivos de Excel de timelines y calendarios generados aparecerán aquí automáticamente.
        </p>
      </div>
    );
  }

  return (
    <div className="p-6 max-w-2xl space-y-8">
      <div className="flex items-center justify-between">
        <h2 className="text-base font-semibold text-foreground">Documentos del proyecto</h2>
        <Button variant="ghost" size="sm" className="gap-1.5 text-muted-foreground" onClick={load}>
          <RefreshCw className="w-3.5 h-3.5" />
          Actualizar
        </Button>
      </div>

      <DocSection
        title="Calendarios"
        icon={FileSpreadsheet}
        docs={calendarios}
        iconClass="bg-primary"
      />
      <DocSection
        title="Timelines"
        icon={BarChart3}
        docs={timelines}
        iconClass="bg-primary"
      />
    </div>
  );
}

src/components/SearchableSelect.tsx.content:
import { useState } from 'react';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Check, ChevronsUpDown } from 'lucide-react';
import { cn } from '@/lib/utils';

export interface SelectOption {
  value: string;
  label: string;
  sub?: string;
}

interface Props {
  value: string;
  onChange: (v: string) => void;
  options: SelectOption[];
  placeholder?: string;
  className?: string;
}

export default function SearchableSelect({ value, onChange, options, placeholder = 'Seleccionar...', className }: Props) {
  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState('');

  const selected = options.find(o => o.value === value);
  const filtered = search.trim()
    ? options.filter(o => o.label.toLowerCase().includes(search.toLowerCase()) || o.sub?.toLowerCase().includes(search.toLowerCase()))
    : options;

  return (
    <Popover open={open} onOpenChange={o => { setOpen(o); if (!o) setSearch(''); }}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          size="sm"
          className={cn('justify-between font-normal text-xs h-8 min-w-[220px] max-w-[300px]', className)}
        >
          <span className="truncate">{selected?.label ?? placeholder}</span>
          <ChevronsUpDown className="ml-2 h-3 w-3 shrink-0 opacity-40" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="p-0 w-80" align="start">
        <div className="p-2 border-b">
          <Input
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Buscar..."
            className="h-7 text-xs"
            autoFocus
          />
        </div>
        <div className="max-h-56 overflow-y-auto py-1">
          {filtered.length === 0 && (
            <p className="text-xs text-muted-foreground text-center py-4">Sin resultados</p>
          )}
          {filtered.map(opt => (
            <button
              key={opt.value}
              className={cn(
                'w-full text-left px-3 py-2 text-xs hover:bg-accent flex items-start gap-2 transition-colors',
                value === opt.value && 'bg-accent/70'
              )}
              onClick={() => { onChange(opt.value); setOpen(false); setSearch(''); }}
            >
              <Check className={cn('mt-0.5 h-3 w-3 shrink-0', value === opt.value ? 'opacity-100 text-primary' : 'opacity-0')} />
              <div className="min-w-0">
                <p className="font-medium leading-tight">{opt.label}</p>
                {opt.sub && <p className="text-muted-foreground mt-0.5 truncate">{opt.sub}</p>}
              </div>
            </button>
          ))}
        </div>
      </PopoverContent>
    </Popover>
  );
}

src/components/SharedViewDialog.tsx.content:
import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Checkbox } from '@/components/ui/checkbox';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import {
  createSharedView, getSharedViews, deleteSharedView,
  updateSharedView, getBoardGroups, GetSharedViewsOutputType, GetBoardGroupsOutputType,
} from 'zite-endpoints-sdk';
import { Share2, Copy, CheckCheck, Trash2, ExternalLink, Link2, Eye, Pencil, Plus, ArrowLeft, Layers, CopyPlus } from 'lucide-react';
import { toast } from 'sonner';
import { FilterRuleRow, FilterRule, FilterColumn, OPS, FilterColumnType } from './AdvancedFilterSheet';
import { getGroupColor, dynColFilterType, parseDynColOptions } from './table/tableUtils';

type SharedView = GetSharedViewsOutputType['views'][0];
type BoardGroup = GetBoardGroupsOutputType['groups'][0];

const FIXED_COLUMNS: FilterColumn[] = [
  { key: 'participantName', label: 'Participante', type: 'text' },
  { key: 'email',           label: 'Email',        type: 'text' },
  { key: 'phone',           label: 'Teléfono',     type: 'text' },
  { key: 'idNumber',        label: 'ID / Doc',     type: 'text' },
  { key: 'status',          label: 'Estado',       type: 'select',
    options: ['Pendiente', 'Contactado', 'Confirmado', 'Asistió', 'No show', 'Descartado'] },
];

const FIXED_VISIBLE = [
  { key: 'participantName', label: 'Participante', alwaysOn: true },
  { key: 'email',           label: 'Email' },
  { key: 'phone',           label: 'Teléfono' },
  { key: 'idNumber',        label: 'ID / Doc' },
  { key: 'status',          label: 'Estado' },
];

const defaultVisibleCols = new Set(FIXED_VISIBLE.filter(c => c.key !== 'idNumber').map(c => c.key));

function useViewForm(dynamicColumns: Array<{ id: string; columnName?: string; columnType?: string; optionsJson?: string }>, boardGroups: BoardGroup[]) {
  const [viewName, setViewName] = useState('');
  const [filterRules, setFilterRules] = useState<FilterRule[]>([]);
  const [filterMode, setFilterMode] = useState<'and' | 'or'>('and');
  const [visibleCols, setVisibleCols] = useState<Set<string>>(new Set(defaultVisibleCols));
  // null = no group filter (show all). Otherwise: array of group IDs to include.
  const [selectedGroupIds, setSelectedGroupIds] = useState<string[] | null>(null);
  const [showNoGroup, setShowNoGroup] = useState(true);

  const allFilterCols: FilterColumn[] = [
    ...FIXED_COLUMNS,
    ...dynamicColumns.map(c => {
      const t = dynColFilterType(c.columnType);
      let options: string[] | undefined;
      if (c.columnType === 'Checkbox') {
        options = ['Sí', 'No'];
      } else if (c.columnType === 'Status' || c.columnType === 'Select') {
        try {
          const opts = JSON.parse(c.optionsJson ?? '[]');
          options = Array.isArray(opts)
            ? (opts as unknown[]).map(o => typeof o === 'string' ? o : (o as { label?: string }).label ?? '').filter(Boolean)
            : undefined;
        } catch { options = undefined; }
      }
      return { key: c.id, label: c.columnName ?? 'Columna', type: t, options };
    }),
  ];

  const resetForm = () => {
    setViewName('');
    setFilterRules([]);
    setFilterMode('and');
    setVisibleCols(new Set(defaultVisibleCols));
    setSelectedGroupIds(null);
    setShowNoGroup(true);
  };

  const populateFromView = (v: SharedView) => {
    setViewName(v.viewName ?? '');
    const filtersData = v.filtersJson ? JSON.parse(v.filtersJson) : {};
    const rules: FilterRule[] = filtersData.filterRules ?? [];
    if (rules.length === 0 && filtersData.statuses?.length > 0) {
      rules.push({
        id: 'legacy_status',
        column: 'status',
        operator: 'es_alguno',
        value: '',
        selectedValues: filtersData.statuses,
      });
    }
    setFilterRules(rules);
    setFilterMode(filtersData.filterMode ?? 'and');
    const cols: string[] = v.visibleColumnsJson ? JSON.parse(v.visibleColumnsJson) : [...defaultVisibleCols];
    setVisibleCols(new Set(cols));
    // Groups
    const sg = filtersData.selectedGroups;
    setSelectedGroupIds(sg !== undefined ? sg : null);
    setShowNoGroup(filtersData.showNoGroup ?? true);
  };

  const addFilterRule = () => {
    const first = allFilterCols[0];
    const t: FilterColumnType = first?.type ?? 'text';
    setFilterRules(prev => [...prev, {
      id: `r_${Date.now()}`,
      column: first?.key ?? '',
      operator: OPS[t][0].value,
      value: '',
      selectedValues: [],
    }]);
  };

  const updateRule = (id: string, patch: Partial<FilterRule>) =>
    setFilterRules(prev => prev.map(r => r.id === id ? { ...r, ...patch } : r));
  const removeRule = (id: string) => setFilterRules(prev => prev.filter(r => r.id !== id));

  const toggleCol = (key: string) =>
    setVisibleCols(prev => { const n = new Set(prev); n.has(key) ? n.delete(key) : n.add(key); return n; });

  // Toggle a specific group ID in/out of selectedGroupIds
  const toggleGroup = (id: string) => {
    setSelectedGroupIds(prev => {
      // null means all shown — convert to explicit list with this one removed
      const base = prev ?? boardGroups.map(g => g.id);
      const next = base.includes(id) ? base.filter(x => x !== id) : [...base, id];
      // If all groups selected + showNoGroup, revert to null (no filter)
      if (next.length === boardGroups.length && showNoGroup) return null;
      return next;
    });
  };

  const toggleShowNoGroup = () => {
    setShowNoGroup(prev => {
      const next = !prev;
      // If everything is now "all included", revert to null
      if (next && (selectedGroupIds === null || selectedGroupIds.length === boardGroups.length)) {
        setSelectedGroupIds(null);
        return true;
      }
      return next;
    });
  };

  const isGroupSelected = (id: string) =>
    selectedGroupIds === null || selectedGroupIds.includes(id);

  return {
    viewName, setViewName,
    filterRules, filterMode, setFilterMode,
    visibleCols, toggleCol,
    allFilterCols, addFilterRule, updateRule, removeRule,
    resetForm, populateFromView,
    selectedGroupIds, showNoGroup, isGroupSelected, toggleGroup, toggleShowNoGroup,
    getFiltersJson: () => {
      const groupPart = selectedGroupIds !== null
        ? { selectedGroups: selectedGroupIds, showNoGroup }
        : {};
      return JSON.stringify({ filterRules, filterMode, ...groupPart });
    },
    getVisibleColsJson: () => JSON.stringify([...visibleCols]),
  };
}

export function SharedViewDialog({
  open, onOpenChange, boardId, projectCode, boardName, dynamicColumns = [], colUniqueValues = () => [],
}: {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  boardId: string;
  projectCode: string;
  boardName: string;
  dynamicColumns?: Array<{ id: string; columnName?: string; columnType?: string; optionsJson?: string }>;
  colUniqueValues?: (key: string) => string[];
}) {
  const [tab, setTab] = useState('create');
  const [boardGroups, setBoardGroups] = useState<BoardGroup[]>([]);
  const form = useViewForm(dynamicColumns, boardGroups);
  const [creating, setCreating] = useState(false);
  const [createdUrl, setCreatedUrl] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  const [views, setViews] = useState<SharedView[]>([]);
  const [loadingViews, setLoadingViews] = useState(false);
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [editingView, setEditingView] = useState<SharedView | null>(null);
  const [saving, setSaving] = useState(false);
  const [duplicatingId, setDuplicatingId] = useState<string | null>(null);

  // Load board groups once when dialog opens
  useEffect(() => {
    if (!open || !boardId) return;
    getBoardGroups({ boardId })
      .then(res => setBoardGroups(res.groups))
      .catch(() => setBoardGroups([]));
  }, [open, boardId]);

  useEffect(() => {
    if (!open) {
      form.resetForm();
      setCreating(false);
      setCreatedUrl(null);
      setCopied(false);
      setTab('create');
      setEditingView(null);
    }
  }, [open]);

  const loadViews = async () => {
    if (!boardId) return;
    setLoadingViews(true);
    try {
      const res = await getSharedViews({ boardId });
      setViews(res.views);
    } catch {
      toast.error('Error al cargar vistas');
    }
    setLoadingViews(false);
  };

  useEffect(() => {
    if (open && tab === 'views') loadViews();
  }, [open, tab]);

  const handleCreate = async () => {
    if (!form.viewName.trim()) { toast.error('Ingresa un nombre para la vista'); return; }
    setCreating(true);
    try {
      const res = await createSharedView({
        viewName: form.viewName.trim(),
        boardId,
        projectCode,
        boardName,
        filtersJson: form.getFiltersJson(),
        visibleColumnsJson: form.getVisibleColsJson(),
      });
      setCreatedUrl(res.shareUrl);
    } catch {
      toast.error('Error al crear la vista');
    }
    setCreating(false);
  };

  const handleSaveEdit = async () => {
    if (!editingView) return;
    if (!form.viewName.trim()) { toast.error('Ingresa un nombre para la vista'); return; }
    setSaving(true);
    try {
      await updateSharedView({
        id: editingView.id,
        viewName: form.viewName.trim(),
        filtersJson: form.getFiltersJson(),
        visibleColumnsJson: form.getVisibleColsJson(),
      });
      toast.success('Vista actualizada');
      setEditingView(null);
      await loadViews();
    } catch {
      toast.error('Error al guardar');
    }
    setSaving(false);
  };

  const handleCopy = async (url: string, id?: string) => {
    await navigator.clipboard.writeText(url);
    if (id) { setCopiedId(id); setTimeout(() => setCopiedId(null), 2000); }
    else { setCopied(true); setTimeout(() => setCopied(false), 2000); }
    toast.success('Link copiado al portapapeles');
  };

  const handleDelete = async (id: string) => {
    try {
      await deleteSharedView({ id });
      setViews(prev => prev.filter(v => v.id !== id));
      toast.success('Vista eliminada');
    } catch {
      toast.error('Error al eliminar');
    }
  };

  const handleDuplicate = async (v: SharedView) => {
    setDuplicatingId(v.id);
    try {
      await createSharedView({ duplicateFromToken: v.token });
      toast.success('Vista duplicada');
      await loadViews();
    } catch {
      toast.error('Error al duplicar la vista');
    }
    setDuplicatingId(null);
  };

  const startEdit = (v: SharedView) => {
    form.populateFromView(v);
    setEditingView(v);
    setTab('views');
  };

  const allVisibleCols = [
    ...FIXED_VISIBLE,
    ...dynamicColumns.map(c => ({ key: c.id, label: c.columnName ?? 'Columna', alwaysOn: false })),
  ];

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-6xl max-h-[90vh] overflow-y-auto" aria-describedby={undefined}>
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Share2 className="w-4 h-4 text-primary" />
            Vistas compartidas
            <span className="text-xs font-normal text-muted-foreground ml-1">— {boardName}</span>
          </DialogTitle>
        </DialogHeader>

        <Tabs value={tab} onValueChange={v => { setTab(v); setEditingView(null); if (v === 'views') loadViews(); }}>
          <TabsList className="w-full">
            <TabsTrigger value="create" className="flex-1">Nueva vista</TabsTrigger>
            <TabsTrigger value="views" className="flex-1">
              Mis vistas {views.length > 0 && tab !== 'create' && <Badge variant="secondary" className="ml-1.5 text-[10px] h-4 px-1">{views.length}</Badge>}
            </TabsTrigger>
          </TabsList>

          {/* ── CREATE TAB ── */}
          <TabsContent value="create" className="mt-4">
            {createdUrl ? (
              <div className="space-y-4">
                <div className="rounded-xl bg-primary/5 border border-primary/20 p-4 space-y-3">
                  <div className="flex items-center gap-2 text-sm font-semibold text-primary">
                    <CheckCheck className="w-4 h-4" /> ¡Vista creada!
                  </div>
                  <p className="text-xs text-muted-foreground">Comparte este link con quien necesite ver los datos:</p>
                  <div className="flex items-center gap-2">
                    <Input value={createdUrl} readOnly className="text-[11px] font-mono flex-1 h-8" />
                    <Button size="sm" variant="outline" className="h-8 px-3 flex-shrink-0 gap-1.5" onClick={() => handleCopy(createdUrl)}>
                      {copied ? <CheckCheck className="w-3.5 h-3.5 text-primary" /> : <Copy className="w-3.5 h-3.5" />}
                      {copied ? 'Copiado' : 'Copiar'}
                    </Button>
                  </div>
                  <a href={createdUrl} target="_blank" rel="noopener noreferrer" className="inline-flex items-center gap-1.5 text-xs text-primary hover:underline">
                    <ExternalLink className="w-3 h-3" /> Abrir en nueva pestaña
                  </a>
                </div>
                <div className="flex gap-2">
                  <Button variant="outline" size="sm" className="flex-1" onClick={() => { setCreatedUrl(null); form.resetForm(); }}>
                    Crear otra
                  </Button>
                  <Button size="sm" className="flex-1 gap-1.5" onClick={() => { setTab('views'); loadViews(); setCreatedUrl(null); }}>
                    <Eye className="w-3.5 h-3.5" /> Ver mis vistas
                  </Button>
                </div>
              </div>
            ) : (
              <ViewForm
                form={form}
                allVisibleCols={allVisibleCols}
                boardGroups={boardGroups}
                onSubmit={handleCreate}
                submitting={creating}
                submitLabel="Generar link"
                submitIcon={<Link2 className="w-3.5 h-3.5" />}
                colUniqueValues={colUniqueValues}
              />
            )}
          </TabsContent>

          {/* ── VIEWS TAB ── */}
          <TabsContent value="views" className="mt-4">
            {editingView ? (
              <div className="space-y-4">
                <div className="flex items-center gap-2">
                  <button onClick={() => { setEditingView(null); form.resetForm(); }} className="text-muted-foreground hover:text-foreground transition-colors">
                    <ArrowLeft className="w-4 h-4" />
                  </button>
                  <span className="text-sm font-medium">Editar vista</span>
                </div>
                <ViewForm
                  form={form}
                  allVisibleCols={allVisibleCols}
                  boardGroups={boardGroups}
                  onSubmit={handleSaveEdit}
                  submitting={saving}
                  submitLabel="Guardar cambios"
                  submitIcon={<CheckCheck className="w-3.5 h-3.5" />}
                  colUniqueValues={colUniqueValues}
                />
              </div>
            ) : loadingViews ? (
              <div className="flex items-center justify-center py-10">
                <div className="w-5 h-5 border-2 border-primary/30 border-t-primary rounded-full animate-spin" />
              </div>
            ) : views.length === 0 ? (
              <div className="flex flex-col items-center py-10 text-center">
                <Share2 className="w-8 h-8 text-muted-foreground/20 mb-3" />
                <p className="text-sm font-medium text-muted-foreground">Sin vistas compartidas</p>
                <p className="text-xs text-muted-foreground/60 mt-1">Crea una en la pestaña "Nueva vista"</p>
              </div>
            ) : (
              <ScrollArea className="max-h-96">
                <div className="space-y-2 pr-1">
                  {views.map(v => (
                    <div key={v.id} className="rounded-lg border border-border/60 bg-card p-3 space-y-2.5">
                      <div className="flex items-start justify-between gap-2">
                        <p className="text-sm font-medium truncate flex-1">{v.viewName || 'Sin nombre'}</p>
                        <div className="flex items-center gap-1 flex-shrink-0">
                          <button
                            onClick={() => startEdit(v)}
                            className="text-muted-foreground hover:text-primary p-1 rounded hover:bg-primary/10 transition-colors"
                            title="Editar vista"
                          >
                            <Pencil className="w-3.5 h-3.5" />
                          </button>
                          <button
                            onClick={() => handleDuplicate(v)}
                            disabled={duplicatingId === v.id}
                            className="text-muted-foreground hover:text-primary p-1 rounded hover:bg-primary/10 transition-colors disabled:opacity-40"
                            title="Duplicar vista"
                          >
                            {duplicatingId === v.id
                              ? <div className="w-3.5 h-3.5 border-2 border-primary/30 border-t-primary rounded-full animate-spin" />
                              : <CopyPlus className="w-3.5 h-3.5" />
                            }
                          </button>
                          <button
                            onClick={() => handleDelete(v.id)}
                            className="text-muted-foreground hover:text-destructive p-1 rounded hover:bg-destructive/10 transition-colors"
                            title="Eliminar vista"
                          >
                            <Trash2 className="w-3.5 h-3.5" />
                          </button>
                        </div>
                      </div>
                      <div className="flex items-center gap-1.5">
                        <Input value={v.shareUrl} readOnly className="text-[11px] font-mono h-7 flex-1" />
                        <Button size="sm" variant="outline" className="h-7 w-7 p-0 flex-shrink-0" title="Copiar link" onClick={() => handleCopy(v.shareUrl, v.id)}>
                          {copiedId === v.id ? <CheckCheck className="w-3 h-3 text-primary" /> : <Copy className="w-3 h-3" />}
                        </Button>
                        <a href={v.shareUrl} target="_blank" rel="noopener noreferrer">
                          <Button size="sm" variant="outline" className="h-7 w-7 p-0 flex-shrink-0" title="Abrir vista">
                            <ExternalLink className="w-3 h-3" />
                          </Button>
                        </a>
                      </div>
                    </div>
                  ))}
                </div>
              </ScrollArea>
            )}
          </TabsContent>
        </Tabs>
      </DialogContent>
    </Dialog>
  );
}

// ── ViewForm ──────────────────────────────────────────────────────────────────
function ViewForm({
  form, allVisibleCols, boardGroups, onSubmit, submitting, submitLabel, submitIcon, colUniqueValues,
}: {
  form: ReturnType<typeof useViewForm>;
  allVisibleCols: Array<{ key: string; label: string; alwaysOn?: boolean }>;
  boardGroups: BoardGroup[];
  onSubmit: () => void;
  submitting: boolean;
  submitLabel: string;
  submitIcon: React.ReactNode;
  colUniqueValues: (key: string) => string[];
}) {
  return (
    <div className="space-y-5">
      {/* ── Two-column grid ── */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

        {/* ── LEFT: Name + Filters ── */}
        <div className="space-y-4">
          {/* Name */}
          <div className="space-y-1.5">
            <Label>Nombre de la vista</Label>
            <Input
              placeholder='ej: Confirmados — Reclutador A'
              value={form.viewName}
              onChange={e => form.setViewName(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && onSubmit()}
              autoFocus
            />
          </div>

          {/* Filters */}
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <Label className="text-sm">Filtros</Label>
              {form.filterRules.length >= 2 && (
                <div className="flex items-center bg-muted rounded-md p-0.5 gap-0.5">
                  {(['and', 'or'] as const).map(m => (
                    <button
                      key={m}
                      onClick={() => form.setFilterMode(m)}
                      className={`px-2 py-0.5 text-xs rounded transition-all ${form.filterMode === m ? 'bg-background text-foreground shadow-sm font-semibold' : 'text-muted-foreground hover:text-foreground'}`}
                    >
                      {m === 'and' ? 'Todas' : 'Cualquiera'}
                    </button>
                  ))}
                </div>
              )}
            </div>
            {/* Filter rules — no max-height, flow naturally */}
            <div className="space-y-2">
              {form.filterRules.map((rule, idx) => (
                <FilterRuleRow
                  key={rule.id}
                  rule={rule}
                  idx={idx}
                  columns={form.allFilterCols}
                  colUniqueValues={colUniqueValues}
                  filterMode={form.filterMode}
                  onUpdate={patch => form.updateRule(rule.id, patch)}
                  onRemove={() => form.removeRule(rule.id)}
                />
              ))}
              {form.filterRules.length === 0 && (
                <p className="text-xs text-muted-foreground/60 italic px-1 py-2">
                  Sin filtros — se mostrarán todos los participantes del tablero.
                </p>
              )}
            </div>
            <Button variant="outline" size="sm" className="w-full gap-1.5" onClick={form.addFilterRule}>
              <Plus className="w-3.5 h-3.5" /> Agregar condición
            </Button>
          </div>
        </div>

        {/* ── RIGHT: Groups + Visible columns ── */}
        <div className="space-y-4">
          {/* Groups visible — only when board has groups */}
          {boardGroups.length > 0 && (
            <div className="space-y-2">
              <div className="flex items-center gap-1.5">
                <Label className="text-sm">Grupos visibles</Label>
                <Layers className="w-3 h-3 text-muted-foreground" />
              </div>
              <div className="rounded-lg border border-border/50 bg-muted/20 p-2 space-y-1">
                {boardGroups.map(g => {
                  const color = getGroupColor(g.colorId);
                  const checked = form.isGroupSelected(g.id);
                  return (
                    <label
                      key={g.id}
                      className="flex items-center gap-2.5 text-sm px-2 py-1.5 rounded-md cursor-pointer hover:bg-muted transition-colors"
                    >
                      <Checkbox
                        checked={checked}
                        onCheckedChange={() => form.toggleGroup(g.id)}
                        className="h-3.5 w-3.5"
                      />
                      <div className="w-2.5 h-2.5 rounded-full flex-shrink-0" style={{ backgroundColor: color }} />
                      <span className="truncate">{g.name}</span>
                    </label>
                  );
                })}
                <label className="flex items-center gap-2.5 text-sm px-2 py-1.5 rounded-md cursor-pointer hover:bg-muted transition-colors">
                  <Checkbox
                    checked={form.showNoGroup}
                    onCheckedChange={() => form.toggleShowNoGroup()}
                    className="h-3.5 w-3.5"
                  />
                  <div className="w-2.5 h-2.5 rounded-full border border-dashed border-muted-foreground/40 flex-shrink-0" />
                  <span className="text-muted-foreground italic">Sin grupo</span>
                </label>
              </div>
              {form.selectedGroupIds !== null && (
                <p className="text-[11px] text-muted-foreground flex items-center gap-1">
                  <span className="w-1.5 h-1.5 rounded-full bg-primary inline-block" />
                  Filtro activo: {form.selectedGroupIds.length} de {boardGroups.length} grupos seleccionados
                </p>
              )}
            </div>
          )}

          {/* Visible columns */}
          <div className="space-y-2">
            <Label className="text-sm">Columnas visibles</Label>
            <div className="rounded-lg border border-border/50 bg-muted/20 p-2 grid grid-cols-2 gap-0.5">
              {allVisibleCols.map(col => (
                <label
                  key={col.key}
                  className={`flex items-center gap-2 text-sm px-2 py-1.5 rounded-md transition-colors ${col.alwaysOn ? 'opacity-50' : 'cursor-pointer hover:bg-muted'}`}
                >
                  <Checkbox
                    checked={form.visibleCols.has(col.key)}
                    onCheckedChange={() => !col.alwaysOn && form.toggleCol(col.key)}
                    disabled={col.alwaysOn}
                    className="h-3.5 w-3.5"
                  />
                  <span className="truncate text-xs">{col.label}</span>
                  {col.alwaysOn && <span className="text-[10px] text-muted-foreground ml-auto">(siempre)</span>}
                </label>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* ── Full-width bottom: info + submit ── */}
      <div className="space-y-3 pt-1 border-t border-border/40">
        <div className="rounded-md bg-muted/50 border border-border/40 px-3 py-2.5 text-xs text-muted-foreground flex items-center gap-4">
          <p>✦ Vista de <strong>solo lectura</strong> — nadie puede editar</p>
          <p>✦ No requiere login para abrirlo</p>
        </div>
        <Button onClick={onSubmit} disabled={submitting || !form.viewName.trim()} className="w-full gap-2">
          {submitting
            ? <><div className="w-3.5 h-3.5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> Guardando...</>
            : <>{submitIcon} {submitLabel}</>
          }
        </Button>
      </div>
    </div>
  );
}

