import { useState, useMemo } from 'react';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Checkbox } from '@/components/ui/checkbox';
import { ChevronDown, X, Users } from 'lucide-react';
type User = {
  id: string;
  email?: string;
  firstName?: string;
  lastName?: string;
  profilePhoto?: string;
  role?: string;
};

interface TeamMemberPickerProps {
  users: User[];
  selected: string[];
  onChange: (ids: string[]) => void;
  label: string;
  multiple?: boolean;
  placeholder?: string;
}

function userName(u: User) {
  const name = [u.firstName, u.lastName].filter(Boolean).join(' ');
  return name || u.email;
}

export default function TeamMemberPicker({
  users,
  selected,
  onChange,
  label,
  multiple = true,
  placeholder = 'Seleccionar...',
}: TeamMemberPickerProps) {
  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState('');

  const filtered = useMemo(() => {
    if (!search) return users;
    const q = search.toLowerCase();
    return users.filter(u =>
      (userName(u) ?? '').toLowerCase().includes(q) ||
      (u.email ?? '').toLowerCase().includes(q)
    );
  }, [users, search]);

  const selectedUsers = users.filter(u => selected.includes(u.id));

  const toggle = (id: string) => {
    if (!multiple) {
      onChange(selected.includes(id) ? [] : [id]);
      setOpen(false);
      return;
    }
    onChange(selected.includes(id) ? selected.filter(x => x !== id) : [...selected, id]);
  };

  const remove = (id: string) => onChange(selected.filter(x => x !== id));

  return (
    <div className="space-y-1.5">
      <div className="flex items-center gap-1.5">
        <Users className="w-3.5 h-3.5 text-muted-foreground" />
        <span className="text-xs font-medium text-muted-foreground">{label}</span>
      </div>

      {/* Selected badges */}
      {selectedUsers.length > 0 && (
        <div className="flex flex-wrap gap-1">
          {selectedUsers.map(u => (
            <Badge key={u.id} variant="secondary" className="gap-1 text-xs pr-1 h-6">
              <span className="truncate max-w-[100px]">{userName(u)}</span>
              <button
                onClick={() => remove(u.id)}
                className="text-muted-foreground hover:text-foreground flex-shrink-0"
              >
                <X className="w-3 h-3" />
              </button>
            </Badge>
          ))}
        </div>
      )}

      {/* Picker popover */}
      <Popover open={open} onOpenChange={o => { setOpen(o); if (!o) setSearch(''); }}>
        <PopoverTrigger asChild>
          <Button
            variant="outline"
            size="sm"
            className="h-8 text-xs gap-1.5 w-full justify-between"
          >
            <span className="text-muted-foreground">{placeholder}</span>
            <ChevronDown className="w-3.5 h-3.5 text-muted-foreground flex-shrink-0" />
          </Button>
        </PopoverTrigger>
        <PopoverContent className="w-64 p-2" align="start">
          <Input
            className="h-7 text-xs mb-2"
            placeholder="Buscar usuario..."
            value={search}
            onChange={e => setSearch(e.target.value)}
            autoFocus
          />
          <div className="max-h-48 overflow-y-auto space-y-0.5">
            {filtered.length === 0 ? (
              <p className="text-xs text-muted-foreground text-center py-3">Sin resultados</p>
            ) : filtered.map(u => (
              <label
                key={u.id}
                className="flex items-center gap-2 px-2 py-1.5 rounded hover:bg-muted cursor-pointer"
              >
                <Checkbox
                  checked={selected.includes(u.id)}
                  onCheckedChange={() => toggle(u.id)}
                  className="h-3.5 w-3.5 flex-shrink-0"
                />
                <div className="min-w-0">
                  <p className="text-xs font-medium truncate">{userName(u)}</p>
                  <p className="text-[10px] text-muted-foreground truncate">
                    {[u.email, u.role].filter(Boolean).join(' · ')}
                  </p>
                </div>
              </label>
            ))}
          </div>
        </PopoverContent>
      </Popover>
    </div>
  );
}

src/hooks/useRealtimeBoardEvents.ts.content:
import { useEffect, useRef, useCallback, useState } from 'react';
import { getCachedAblyToken, invalidateAblyToken } from '../lib/ablyTokenCache';

type DeletedPayload = { id: string; projectCode: string; senderEmail?: string; changeType?: string };

export type BoardFieldUpdatedPayload = {
  projectCode: string;
  boardId: string;
  entityType: 'recruitmentRow' | 'task' | 'event' | 'unknown';
  fieldType: 'dynamic' | 'fixed';
  rowId: string;
  columnId?: string;
  value?: { textValue?: string; numberValue?: number; dateValue?: string; booleanValue?: boolean; fileUrl?: string };
  fields?: Record<string, unknown>;
  senderEmail?: string;
  timestamp?: string;
};

type UseRealtimeBoardEventsOptions = {
  projectCode: string | null;
  userEmail: string;
  onTaskDeleted?: (payload: DeletedPayload) => void;
  onEventDeleted?: (payload: DeletedPayload) => void;
  onRecruitmentDeleted?: (payload: DeletedPayload) => void;
  onRecruitmentGroupsChanged?: (payload: DeletedPayload) => void;
  onRecruitmentRowsChanged?: (payload: DeletedPayload) => void;
  onBoardFieldUpdated?: (payload: BoardFieldUpdatedPayload) => void;
  enabled?: boolean;
};

export type RealtimeStatus = 'connecting' | 'connected' | 'error' | 'disabled';

export function useRealtimeBoardEvents({
  projectCode,
  userEmail,
  onTaskDeleted,
  onEventDeleted,
  onRecruitmentDeleted,
  onRecruitmentGroupsChanged,
  onRecruitmentRowsChanged,
  onBoardFieldUpdated,
  enabled = true,
}: UseRealtimeBoardEventsOptions): { status: RealtimeStatus } {
  const onTaskDeletedRef               = useRef(onTaskDeleted);
  const onEventDeletedRef              = useRef(onEventDeleted);
  const onRecruitmentDeletedRef        = useRef(onRecruitmentDeleted);
  const onRecruitmentGroupsChangedRef  = useRef(onRecruitmentGroupsChanged);
  const onRecruitmentRowsChangedRef    = useRef(onRecruitmentRowsChanged);
  const onBoardFieldUpdatedRef         = useRef(onBoardFieldUpdated);
  onTaskDeletedRef.current               = onTaskDeleted;
  onEventDeletedRef.current              = onEventDeleted;
  onRecruitmentDeletedRef.current        = onRecruitmentDeleted;
  onRecruitmentGroupsChangedRef.current  = onRecruitmentGroupsChanged;
  onRecruitmentRowsChangedRef.current    = onRecruitmentRowsChanged;
  onBoardFieldUpdatedRef.current         = onBoardFieldUpdated;

  const [status, setStatus] = useState<RealtimeStatus>('disabled');
  const eventSourceRef      = useRef<EventSource | null>(null);
  const tokenRef            = useRef<{ token: string; expires: number } | null>(null);
  const retryTimeoutRef     = useRef<ReturnType<typeof setTimeout> | null>(null);
  // Exponential backoff: starts at 3s, doubles on each error, caps at 30s
  const retryDelayRef       = useRef(3000);
  const activeChannelKeyRef = useRef('');

  const cleanup = useCallback(() => {
    if (eventSourceRef.current) {
      eventSourceRef.current.close();
      eventSourceRef.current = null;
    }
    if (retryTimeoutRef.current) {
      clearTimeout(retryTimeoutRef.current);
      retryTimeoutRef.current = null;
    }
  }, []);

  useEffect(() => {
    if (!enabled || !projectCode) {
      cleanup();
      activeChannelKeyRef.current = '';
      setStatus('disabled');
      return;
    }

    // Skip reconnect if we already have a live (or connecting) EventSource for this channel
    const channelKey = `${projectCode}::${userEmail}`;
    if (
      channelKey === activeChannelKeyRef.current &&
      eventSourceRef.current !== null &&
      eventSourceRef.current.readyState !== EventSource.CLOSED
    ) {
      return;
    }
    activeChannelKeyRef.current = channelKey;

    const ablyChannel = `board:${projectCode}`;
    console.log('[ably-board] subscribing', { channel: ablyChannel, projectCode, enabled, userEmail });
    let cancelled = false;

    const connect = async () => {
      setStatus('connecting');

      // Get or refresh token — uses shared cache to avoid duplicate requests
      // when useProjectPresence is also connecting to the same channel
      const now = Math.floor(Date.now() / 1000);
      if (!tokenRef.current || tokenRef.current.expires - now < 300) {
        const tokenResult = await getCachedAblyToken(ablyChannel);
        if (tokenResult) {
          tokenRef.current = tokenResult;
        } else {
          console.warn('[ably][board] Token failed');
          setStatus('error');
          if (!cancelled) retryTimeoutRef.current = setTimeout(connect, retryDelayRef.current);
          return;
        }
      }

      if (cancelled) return;

      const sseUrl = `https://realtime.ably.io/sse?channels=${encodeURIComponent(ablyChannel)}&accessToken=${encodeURIComponent(tokenRef.current!.token)}&v=1.2`;
      const es = new EventSource(sseUrl);
      eventSourceRef.current = es;

      es.onopen = () => {
        if (!cancelled) {
          setStatus('connected');
          // Reset backoff on successful connection
          retryDelayRef.current = 3000;
        }
      };

      es.onmessage = (event) => {
        try {
          const parsed = JSON.parse(event.data);
          const data: DeletedPayload = typeof parsed.data === 'string'
            ? JSON.parse(parsed.data)
            : parsed.data;

          // Handle recruitment.groups.changed BEFORE senderEmail filter —
          // all tabs (even same user) should refresh group structure
          if (parsed.name === 'recruitment.groups.changed' && data?.projectCode) {
            console.log('[ably-board] received recruitment.groups.changed', {
              data,
              senderEmail: data?.senderEmail,
              userEmail,
              isSameUser: data?.senderEmail === userEmail,
            });
            onRecruitmentGroupsChangedRef.current?.(data);
            return;
          }

          // Handle recruitment.rows.changed BEFORE senderEmail filter —
          // all tabs (even same user) should refresh row list
          if (parsed.name === 'recruitment.rows.changed' && data?.projectCode) {
            console.log('[ably-board] received recruitment.rows.changed', {
              data,
              senderEmail: data?.senderEmail,
              userEmail,
              isSameUser: data?.senderEmail === userEmail,
            });
            onRecruitmentRowsChangedRef.current?.(data);
            return;
          }

          // Handle board.field.updated BEFORE senderEmail filter —
          // allows same-user sync across tabs
          if (parsed.name === 'board.field.updated' && data) {
            onBoardFieldUpdatedRef.current?.(data as any);
            return;
          }

          // Ignore own events for all other event types
          if (data?.senderEmail && data.senderEmail === userEmail) {
            console.log('[ably-board] ignored own event by senderEmail', { event: parsed.name, senderEmail: data.senderEmail, userEmail });
            return;
          }

          if (parsed.name === 'task.deleted' && data?.id) {
            onTaskDeletedRef.current?.(data);
          } else if (parsed.name === 'event.deleted' && data?.id) {
            onEventDeletedRef.current?.(data);
          } else if (parsed.name === 'recruitment.deleted' && data?.id) {
            onRecruitmentDeletedRef.current?.(data);
          }
        } catch {
          // Ignore malformed events
        }
      };

      es.onerror = () => {
        if (!cancelled) {
          setStatus('error');
          es.close();
          eventSourceRef.current = null;
          // Invalidate shared token cache so next connect fetches a fresh token
          invalidateAblyToken(ablyChannel);
          tokenRef.current = null;
          // Exponential backoff: double delay on each error, cap at 30s
          retryTimeoutRef.current = setTimeout(connect, retryDelayRef.current);
          retryDelayRef.current = Math.min(retryDelayRef.current * 2, 30000);
        }
      };
    };

    connect();

    // Refresh token proactively every 50 minutes
    const tokenRefreshInterval = setInterval(() => {
      if (!cancelled && tokenRef.current) {
        const now = Math.floor(Date.now() / 1000);
        if (tokenRef.current.expires - now < 600) {
          cleanup();
          invalidateAblyToken(ablyChannel);
          tokenRef.current = null;
          connect();
        }
      }
    }, 50 * 60 * 1000);

    return () => {
      cancelled = true;
      clearInterval(tokenRefreshInterval);
      cleanup();
      activeChannelKeyRef.current = '';
      setStatus('disabled');
    };
  }, [projectCode, enabled, userEmail, cleanup]);

  return { status };
}

src/pages/CotizacionesAdminPage.tsx.content:
import { useState, useEffect, useMemo } from 'react';
import { useAuth } from 'zite-auth-sdk';
import { getCotizacionesAdmin, saveCotizacion, importCotizacionesFromCsv } from 'zite-endpoints-sdk';
import type { GetCotizacionesAdminOutputType } from 'zite-endpoints-sdk';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Skeleton } from '@/components/ui/skeleton';
import { Switch } from '@/components/ui/switch';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { toast } from 'sonner';
import { Link2, RefreshCw, Upload, Search, ExternalLink } from 'lucide-react';

type Cotizacion = GetCotizacionesAdminOutputType['cotizaciones'][0];
type Deal = GetCotizacionesAdminOutputType['dealsList'][0];

const fmt = (v: number | null) =>
  v == null ? '—' : new Intl.NumberFormat('es-MX', { style: 'currency', currency: 'MXN', maximumFractionDigits: 0 }).format(v);

// ── Row component ─────────────────────────────────────────────────────────────
function CotizRow({
  cotiz, deals, onLinked, onToggleIncluded,
}: {
  cotiz: Cotizacion;
  deals: Deal[];
  onLinked: () => void;
  onToggleIncluded: (id: string, val: boolean) => Promise<void>;
}) {
  const [selectedDealId, setSelectedDealId] = useState('');
  const [linking, setLinking] = useState(false);
  const [toggling, setToggling] = useState(false);

  const handleLink = async () => {
    if (!selectedDealId) return;
    setLinking(true);
    try {
      await saveCotizacion({ id: cotiz.id, deal: [selectedDealId] });
      toast.success('Cotización vinculada al deal');
      onLinked();
    } catch {
      toast.error('Error al vincular');
    } finally {
      setLinking(false);
    }
  };

  const handleToggle = async (val: boolean) => {
    setToggling(true);
    try {
      await onToggleIncluded(cotiz.id, val);
    } finally {
      setToggling(false);
    }
  };

  return (
    <tr className="border-b border-border hover:bg-muted/30 transition-colors">
      <td className="px-4 py-3 text-sm font-medium text-foreground max-w-xs truncate">
        {cotiz.cotizacionName || <span className="text-muted-foreground italic">Sin nombre</span>}
      </td>
      <td className="px-4 py-3 text-sm text-muted-foreground">{cotiz.currency}</td>
      <td className="px-4 py-3 text-sm text-right tabular-nums">{fmt(cotiz.totalCost)}</td>
      <td className="px-4 py-3 text-sm text-right tabular-nums font-medium">{fmt(cotiz.clientPrice)}</td>
      <td className="px-4 py-3">
        {cotiz.dealName ? (
          <span className="text-sm text-foreground">{cotiz.dealName}</span>
        ) : (
          <div className="flex items-center gap-2">
            <Badge variant="secondary" className="text-xs">Sin deal</Badge>
            <Select value={selectedDealId} onValueChange={setSelectedDealId}>
              <SelectTrigger className="h-7 text-xs w-40">
                <SelectValue placeholder="Elegir deal..." />
              </SelectTrigger>
              <SelectContent>
                {deals.map(d => (
                  <SelectItem key={d.id} value={d.id}>{d.dealName}</SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Button
              size="sm"
              variant="outline"
              className="h-7 text-xs gap-1"
              disabled={!selectedDealId || linking}
              onClick={handleLink}
            >
              <Link2 className="w-3 h-3" />
              {linking ? 'Vinculando...' : 'Vincular'}
            </Button>
          </div>
        )}
      </td>
      <td className="px-4 py-3">
        <Badge variant={cotiz.status === 'Aprobada' ? 'default' : 'secondary'} className="text-xs">
          {cotiz.status}
        </Badge>
      </td>
      <td className="px-4 py-3">
        <Switch
          checked={cotiz.included}
          disabled={toggling}
          onCheckedChange={handleToggle}
        />
      </td>
    </tr>
  );
}

// ── Import panel ──────────────────────────────────────────────────────────────
function ImportPanel({ onDone }: { onDone: () => void }) {
  const [csvUrl, setCsvUrl] = useState('');
  const [currency, setCurrency] = useState('MXN');
  const [importing, setImporting] = useState(false);
  const [result, setResult] = useState<{
    totalCotizaciones: number; matchedCount: number;
    unmatchedNames: string[]; totalLineItems: number;
  } | null>(null);

  const handleImport = async () => {
    if (!csvUrl.trim()) { toast.error('Ingresa la URL del CSV'); return; }
    setImporting(true);
    setResult(null);
    try {
      const res = await importCotizacionesFromCsv({ csvUrl: csvUrl.trim(), currency });
      setResult(res);
      toast.success(`Importadas ${res.totalCotizaciones} cotizaciones (${res.matchedCount} con deal)`);
      onDone();
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : 'Error al importar';
      toast.error(msg);
    } finally {
      setImporting(false);
    }
  };

  return (
    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
      <p className="text-sm font-medium text-foreground flex items-center gap-2">
        <Upload className="w-4 h-4 text-muted-foreground" />
        Importar cotizaciones desde CSV
      </p>
      <div className="flex gap-2 flex-wrap">
        <Input
          className="flex-1 min-w-60 h-9 text-sm"
          placeholder="URL del archivo CSV..."
          value={csvUrl}
          onChange={e => setCsvUrl(e.target.value)}
        />
        <Select value={currency} onValueChange={setCurrency}>
          <SelectTrigger className="w-28 h-9">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="MXN">MXN</SelectItem>
            <SelectItem value="USD">USD</SelectItem>
          </SelectContent>
        </Select>
        <Button size="sm" disabled={importing} onClick={handleImport} className="h-9 gap-2">
          {importing ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Upload className="w-4 h-4" />}
          {importing ? 'Importando...' : 'Importar'}
        </Button>
      </div>
      {result && (
        <div className="text-xs text-muted-foreground space-y-1">
          <p>✅ {result.totalCotizaciones} cotizaciones · {result.totalLineItems} line items · {result.matchedCount} con deal</p>
          {result.unmatchedNames.length > 0 && (
            <details>
              <summary className="cursor-pointer text-amber-600">
                ⚠️ {result.unmatchedNames.length} sin match con deal (click para ver)
              </summary>
              <div className="mt-1 max-h-32 overflow-y-auto pl-2 space-y-0.5">
                {result.unmatchedNames.map(n => <p key={n}>{n}</p>)}
              </div>
            </details>
          )}
        </div>
      )}
    </div>
  );
}

// ── Main page ─────────────────────────────────────────────────────────────────
export default function CotizacionesAdminPage() {
  const { user, isLoading, loginWithRedirect } = useAuth();
  const [data, setData] = useState<GetCotizacionesAdminOutputType | null>(null);
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState<'all' | 'sin-deal' | 'con-deal'>('all');
  const [search, setSearch] = useState('');
  const [showImport, setShowImport] = useState(false);

  useEffect(() => {
    if (!isLoading && !user) loginWithRedirect({ redirectUrl: window.location.href });
  }, [isLoading, user, loginWithRedirect]);

  const load = async () => {
    setLoading(true);
    try {
      const res = await getCotizacionesAdmin({});
      setData(res);
    } catch { toast.error('Error al cargar cotizaciones'); }
    finally { setLoading(false); }
  };

  useEffect(() => { load(); }, []);

  const handleToggleIncluded = async (id: string, val: boolean) => {
    await saveCotizacion({ id, included: val });
    setData(prev => prev ? {
      ...prev,
      cotizaciones: prev.cotizaciones.map(c => c.id === id ? { ...c, included: val } : c),
    } : prev);
  };

  const filtered = useMemo(() => {
    if (!data) return [];
    let list = data.cotizaciones;
    if (tab === 'sin-deal') list = list.filter(c => !c.dealId);
    if (tab === 'con-deal') list = list.filter(c => !!c.dealId);
    if (search.trim()) {
      const q = search.toLowerCase();
      list = list.filter(c =>
        c.cotizacionName?.toLowerCase().includes(q) ||
        c.dealName?.toLowerCase().includes(q)
      );
    }
    return list;
  }, [data, tab, search]);

  const sinDealCount = data?.cotizaciones.filter(c => !c.dealId).length ?? 0;

  if (isLoading || !user) return null;

  return (
    <div className="p-6 space-y-5">
      {/* Header */}
      <div className="flex items-start justify-between gap-4 flex-wrap">
        <div>
          <h1 className="text-2xl font-bold text-foreground">Cotizaciones</h1>
          <p className="text-muted-foreground text-sm mt-1">
            Gestión y vinculación de cotizaciones a deals
          </p>
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          <Button variant="outline" size="sm" onClick={() => setShowImport(v => !v)} className="gap-2">
            <Upload className="w-4 h-4" />
            Importar CSV
          </Button>
          <Button variant="outline" size="sm" onClick={load} disabled={loading} className="gap-2">
            <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
            Actualizar
          </Button>
        </div>
      </div>

      {/* Import panel */}
      {showImport && <ImportPanel onDone={() => { setShowImport(false); load(); }} />}

      {/* Filters */}
      <div className="flex items-center gap-3 flex-wrap">
        <Tabs value={tab} onValueChange={v => setTab(v as typeof tab)}>
          <TabsList>
            <TabsTrigger value="all">Todas {data && `(${data.cotizaciones.length})`}</TabsTrigger>
            <TabsTrigger value="sin-deal">
              Sin deal
              {sinDealCount > 0 && (
                <Badge variant="destructive" className="ml-1.5 text-xs px-1.5 py-0">{sinDealCount}</Badge>
              )}
            </TabsTrigger>
            <TabsTrigger value="con-deal">Con deal</TabsTrigger>
          </TabsList>
        </Tabs>
        <div className="relative flex-1 min-w-52 max-w-72">
          <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground" />
          <Input
            className="pl-8 h-9 text-sm"
            placeholder="Buscar cotización o deal..."
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>
      </div>

      {/* Table */}
      <div className="rounded-lg border border-border overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm min-w-[800px]">
            <thead className="bg-muted/50 text-muted-foreground border-b border-border">
              <tr>
                <th className="px-4 py-3 text-left font-medium">Nombre</th>
                <th className="px-4 py-3 text-left font-medium">Moneda</th>
                <th className="px-4 py-3 text-right font-medium">Costo Total</th>
                <th className="px-4 py-3 text-right font-medium">P. Cliente</th>
                <th className="px-4 py-3 text-left font-medium">Deal vinculado</th>
                <th className="px-4 py-3 text-left font-medium">Status</th>
                <th className="px-4 py-3 text-left font-medium">Incluida</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border bg-card">
              {loading ? (
                [...Array(8)].map((_, i) => (
                  <tr key={i}><td colSpan={7} className="px-4 py-3"><Skeleton className="h-5 w-full" /></td></tr>
                ))
              ) : filtered.length === 0 ? (
                <tr>
                  <td colSpan={7} className="px-4 py-12 text-center text-muted-foreground text-sm">
                    <ExternalLink className="w-8 h-8 mx-auto mb-2 opacity-20" />
                    No hay cotizaciones que mostrar
                  </td>
                </tr>
              ) : (
                filtered.map(c => (
                  <CotizRow
                    key={c.id}
                    cotiz={c}
                    deals={data?.dealsList ?? []}
                    onLinked={load}
                    onToggleIncluded={handleToggleIncluded}
                  />
                ))
              )}
            </tbody>
          </table>
        </div>
        {!loading && filtered.length > 0 && (
          <div className="px-4 py-2 bg-muted/30 border-t border-border text-xs text-muted-foreground">
            {filtered.length} cotizaciones
          </div>
        )}
      </div>
    </div>
  );
}

