src/api/importCotizacionesFromCsv.ts.content:
import { z } from 'zod';
import { createEndpoint, Deals, Cotizaciones, CotizacionLineItems } from 'zite-integrations-backend-sdk';

// ── Helpers ───────────────────────────────────────────────────────────────────

function parseNum(v: string | undefined): number {
  if (!v) return 0;
  const cleaned = String(v).replace(/,/g, '').trim();
  const n = parseFloat(cleaned);
  return isNaN(n) ? 0 : n;
}

function normalize(s: string): string {
  return s
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[-_]/g, ' ')
    .replace(/\s+/g, ' ')
    .replace(/\(aprobado\)/g, '')
    .replace(/\(aprobada\)/g, '')
    .trim();
}

/** Simple CSV row parser that handles quoted fields */
function parseCsvRow(line: string): string[] {
  const result: string[] = [];
  let current = '';
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === '"') {
      if (inQuotes && line[i + 1] === '"') { current += '"'; i++; }
      else inQuotes = !inQuotes;
    } else if (ch === ',' && !inQuotes) {
      result.push(current.trim());
      current = '';
    } else {
      current += ch;
    }
  }
  result.push(current.trim());
  return result;
}

const RUBROS_SET = new Set([
  'RECLUTAMIENTO E INCENTIVOS', 'MODERACIÓN', 'MANAGEMENT',
  'LOGÍSTICA Y OPERACIÓN', 'BACK OFFICE',
]);
const RUBRO_MAP: Record<string, string> = {
  'RECLUTAMIENTO E INCENTIVOS': 'Reclutamiento e incentivos',
  'MODERACIÓN': 'Moderación',
  'MANAGEMENT': 'Management',
  'LOGÍSTICA Y OPERACIÓN': 'Logística y operación',
  'BACK OFFICE': 'Back office',
};
const SKIP_VALS = new Set([
  'Template', 'Name', 'Subitems', 'COTIZACIONES - MXN$', 'COTIZACIONES - USD$', '',
]);

// ── Matching ──────────────────────────────────────────────────────────────────

function findDealMatch(
  cotizName: string,
  deals: { id: string; dealName: string }[],
): { id: string; dealName: string } | null {
  const normCotiz = normalize(cotizName);

  // (a) Exact normalized match
  for (const d of deals) {
    if (normalize(d.dealName) === normCotiz) return d;
  }

  // (b+c) Contains match — pick longest deal name that fits
  let best: { id: string; dealName: string } | null = null;
  let bestLen = 0;
  for (const d of deals) {
    const normDeal = normalize(d.dealName);
    if (normDeal.length < 4) continue;
    if (normCotiz.startsWith(normDeal) || normCotiz.includes(normDeal)) {
      if (normDeal.length > bestLen) {
        best = d;
        bestLen = normDeal.length;
      }
    }
  }
  return best;
}

// ── Chunked bulkCreate ────────────────────────────────────────────────────────

async function bulkCreateChunked<T>(
  items: T[],
  fn: (chunk: T[]) => Promise<unknown>,
  chunkSize = 100,
): Promise<void> {
  for (let i = 0; i < items.length; i += chunkSize) {
    await fn(items.slice(i, i + chunkSize));
  }
}

// ── Endpoint ──────────────────────────────────────────────────────────────────

export default createEndpoint({
  authenticated: true,
  description: 'Import cotizaciones from a Monday-exported CSV and link them to existing deals',
  inputSchema: z.object({
    csvUrl: z.string(),
    currency: z.string().optional(),
  }),
  outputSchema: z.object({
    totalCotizaciones: z.number(),
    totalLineItems: z.number(),
    matchedCount: z.number(),
    unmatchedNames: z.array(z.string()),
    matchDetails: z.array(z.object({ cotizName: z.string(), dealName: z.string() })),
  }),
  execute: async ({ input }) => {
    const currency = input.currency ?? 'MXN';

    // 1. Fetch CSV
    const resp = await fetch(input.csvUrl);
    const rawText = await resp.text();
    const lines = rawText.split(/\r?\n/);

    // 2. Parse all rows
    const rows = lines.map(parseCsvRow);

    // 3. Fetch all deals for matching
    const { records: dealRecords } = await Deals.findAll({ fields: ['dealName'], limit: 2000 });
    const deals = dealRecords.map(d => ({ id: d.id, dealName: d.dealName ?? '' }));

    // 4. Extract cotización blocks
    interface LineItemRaw {
      rubro: string;
      subRubro: string;
      cantidad: number;
      componentes: number;
      unitCost: number;
      subtotal: number;
      markupPct: number;
      finalPrice: number;
    }
    interface CotizBlock {
      name: string;
      lineItems: LineItemRaw[];
    }

    const blocks: CotizBlock[] = [];
    let currentBlock: CotizBlock | null = null;
    let currentRubro = '';

    for (const row of rows) {
      const col0 = (row[0] ?? '').trim();
      const col1 = (row[1] ?? '').trim();

      if (!col0) {
        // Possible line item
        if (currentBlock && currentRubro && col1) {
          currentBlock.lineItems.push({
            rubro: currentRubro,
            subRubro: col1,
            cantidad: parseNum(row[2]),
            componentes: parseNum(row[3]),
            unitCost: parseNum(row[4]),
            subtotal: parseNum(row[5]),
            markupPct: parseNum(row[6]),
            finalPrice: parseNum(row[8]),
          });
        }
        continue;
      }

      if (RUBROS_SET.has(col0)) {
        currentRubro = col0;
        continue;
      }

      if (SKIP_VALS.has(col0) || col0.startsWith('Duplicate of')) {
        continue;
      }

      // New cotización block
      if (currentBlock) blocks.push(currentBlock);
      currentBlock = { name: col0, lineItems: [] };
      currentRubro = '';
    }
    if (currentBlock) blocks.push(currentBlock);

    // 5. Import each block
    let totalLineItems = 0;
    const unmatchedNames: string[] = [];
    const matchDetails: { cotizName: string; dealName: string }[] = [];

    for (const block of blocks) {
      const match = findDealMatch(block.name, deals);
      if (match) {
        matchDetails.push({ cotizName: block.name, dealName: match.dealName });
      } else {
        unmatchedNames.push(block.name);
      }

      const totalCost = block.lineItems.reduce((s, li) => s + li.subtotal, 0);
      const clientPrice = block.lineItems.reduce((s, li) => s + li.finalPrice, 0);

      const cotizRecord: Record<string, unknown> = {
        cotizacionName: block.name,
        status: 'Borrador',
        currency,
        totalCost,
        clientPrice,
        included: false, // always false — user enables manually
      };
      if (match) cotizRecord.deal = [match.id];

      const created = await Cotizaciones.create({ record: cotizRecord as never });

      // Create line items in chunks of 100
      const liItems = block.lineItems
        .filter(li => li.subRubro)
        .map(li => ({
          subRubro: li.subRubro,
          cotizacion: [created.id],
          rubro: RUBRO_MAP[li.rubro] ?? li.rubro,
          cantidad: li.cantidad || undefined,
          componentes: li.componentes || undefined,
          unitCost: li.unitCost || undefined,
          hasMarkup: li.markupPct > 0,
          markupPct: li.markupPct || undefined,
          finalPrice: li.finalPrice || undefined,
        }));

      await bulkCreateChunked(liItems, chunk =>
        CotizacionLineItems.bulkCreate({ records: chunk as never }),
      );

      totalLineItems += liItems.length;
    }

    return {
      totalCotizaciones: blocks.length,
      totalLineItems,
      matchedCount: matchDetails.length,
      unmatchedNames,
      matchDetails,
    };
  },
});

src/api/recalculateDuplicateNotes.ts.content:
import { z } from 'zod';
import { createEndpoint, RecruitmentRows, Projects } from 'zite-integrations-backend-sdk';

type RowLike = {
  id: string;
  projectCode?: string;
  boardName?: string;
  status?: string;
  group?: string;
};

type ProjectDates = { startDate?: string; client?: string };

/**
 * 4-level duplicate/participation detection.
 *
 * 🔴 YA PARTICIPÓ  — different project, status 'Asistió' OR has group,
 *                    AND that project's endDate < current project's startDate
 *                    (time-based: they participated BEFORE this project started).
 *                    When dates are missing/overlapping → demote to 🟡.
 * 🟡 DUPLICADO EXTERNO  — different project, no (confirmed) prior participation
 * 🟠 MISMO PROYECTO     — same project, different board
 * 🔵 ×N EN ESTE TABLERO — same project AND same board
 */
const buildParticipationNote = (
  allRows: RowLike[],
  currentId: string,
  currentProjectCode: string,
  currentBoardName: string,
  projectDatesMap: Map<string, ProjectDates> = new Map(),
): string => {
  const otherRows = allRows.filter(r => r.id !== currentId);
  if (otherRows.length === 0) return '';

  const currentProjData = projectDatesMap.get(currentProjectCode);
  const referenceDate = currentProjData?.startDate ? new Date(currentProjData.startDate) : new Date();
  const sixMonthsAgo = new Date(referenceDate);
  sixMonthsAgo.setMonth(sixMonthsAgo.getMonth() - 6);

  const normalizeStr = (s?: string) =>
    (s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
  const currentClientNorm = normalizeStr(currentProjData?.client);

  // ── 🟠 Orange: same board ×N ─────────────────────────────────────────────
  const sameBoardRows = otherRows.filter(
    r => r.projectCode === currentProjectCode && r.boardName === currentBoardName,
  );

  // ── Other board/project rows → 🔴 RED or 🔵 BLUE ─────────────────────────
  const otherBoardRows = otherRows.filter(
    r => !(r.projectCode === currentProjectCode && r.boardName === currentBoardName),
  );

  const redProjects  = new Map<string, string>();
  const blueProjects = new Map<string, string>();

  for (const r of otherBoardRows) {
    if (!r.projectCode) continue;
    const label       = r.boardName ? `${r.projectCode} (${r.boardName})` : r.projectCode;
    const participated = r.status === 'Asistió' || (!!r.group && r.group.trim() !== '');
    const projData    = projectDatesMap.get(r.projectCode);
    const otherStart  = projData?.startDate ? new Date(projData.startDate) : null;
    const otherClient = normalizeStr(projData?.client);

    // ── Temporal filter: ignore projects that started AFTER the current project ──
    if (otherStart && otherStart > referenceDate) continue;

    const isSameClient     = !!currentClientNorm && !!otherClient && otherClient === currentClientNorm;
    // Recent: other project started within 6 months before current project's startDate
    const isRecentOrActive = !otherStart || otherStart > sixMonthsAgo;
    // Same client is red ONLY if the person actually participated (not just filled a form)
    const isRed = (isSameClient && participated) || (participated && isRecentOrActive);
    if (isRed) {
      redProjects.set(r.projectCode, label);
    } else if (!redProjects.has(r.projectCode)) {
      blueProjects.set(r.projectCode, label);
    }
  }

  const parts: string[] = [];
  if (redProjects.size > 0) {
    parts.push(`🔴 ALERTA: ${[...redProjects.values()].join(', ')}.`);
  }
  const blueLabels = [...blueProjects.entries()]
    .filter(([k]) => !redProjects.has(k))
    .map(([, v]) => v);
  if (blueLabels.length > 0) {
    parts.push(`🔵 DUPLICADO EXTERNO: ${blueLabels.join(', ')}.`);
  }
  if (sameBoardRows.length > 0) {
    parts.push(`🟠 ×${sameBoardRows.length + 1} EN ESTE TABLERO`);
  }

  return parts.join(' ');
};

export default createEndpoint({
  authenticated: true,
  description: 'Recalculate duplicate/participation notes for all active recruitment rows',
  inputSchema: z.object({
    projectCode: z.string().optional(),
  }),
  outputSchema: z.object({ updated: z.number(), total: z.number() }),
  execute: async ({ input }) => {
    // ── 0. Fetch project dates for temporal comparison ────────────────────
    const { records: allProjects } = await Projects.findAll({
      limit: 500,
      fields: ['projectCode', 'startDate', 'client'],
    });
    const projectDatesMap = new Map<string, ProjectDates>();
    for (const p of allProjects) {
      if (p.projectCode) projectDatesMap.set(p.projectCode, { startDate: p.startDate, client: p.client });
    }

    // ── 1. Fetch ALL active rows (cross-project for full duplicate detection)
    type RowRecord = Awaited<ReturnType<typeof RecruitmentRows.findAll>>['records'][0];
    const allRecords: RowRecord[] = [];
    let offset = 0;
    let hasMore = true;
    while (hasMore) {
      const batch = await RecruitmentRows.findAll({
        limit: 2000,
        offset,
        fields: ['id', 'email', 'participantName', 'phone', 'projectCode', 'boardName', 'status', 'group', 'notes', 'deletedAt'],
      });
      allRecords.push(...batch.records);
      hasMore = batch.hasMore;
      offset += batch.records.length;
    }

    const allActive = allRecords.filter(r => !r.deletedAt);
    const rowsToUpdate = input.projectCode
      ? allActive.filter(r => r.projectCode === input.projectCode)
      : allActive;

    // ── 2. Build lookup maps from ALL active rows ─────────────────────────
    const normalize = (s: string) =>
      s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();

    const emailMap  = new Map<string, string[]>();
    const nameMap   = new Map<string, string[]>();
    const phoneMap  = new Map<string, string[]>();

    for (const r of allActive) {
      if (r.email) {
        const k = r.email.toLowerCase().trim();
        if (!emailMap.has(k)) emailMap.set(k, []);
        emailMap.get(k)!.push(r.id);
      }
      if (r.participantName) {
        const k = normalize(r.participantName);
        if (k.length > 2) {
          if (!nameMap.has(k)) nameMap.set(k, []);
          nameMap.get(k)!.push(r.id);
        }
      }
      if (r.phone) {
        const k = r.phone.replace(/[\s\-().+]/g, '');
        if (k.length >= 7) {
          if (!phoneMap.has(k)) phoneMap.set(k, []);
          phoneMap.get(k)!.push(r.id);
        }
      }
    }

    // ── 3. Recalculate each row in the target project ─────────────────────
    const rowById = new Map(allActive.map(r => [r.id, r]));
    let updated = 0;

    for (const row of rowsToUpdate) {
      if (!row.projectCode) continue;

      const peerIds = new Set<string>();
      if (row.email) {
        const k = row.email.toLowerCase().trim();
        for (const id of emailMap.get(k) ?? []) peerIds.add(id);
      }
      if (row.participantName) {
        const k = normalize(row.participantName);
        if (k.length > 2) for (const id of nameMap.get(k) ?? []) peerIds.add(id);
      }
      if (row.phone) {
        const k = row.phone.replace(/[\s\-().+]/g, '');
        if (k.length >= 7) for (const id of phoneMap.get(k) ?? []) peerIds.add(id);
      }

      const allRows: RowLike[] = [row, ...[...peerIds]
        .filter(id => id !== row.id)
        .map(id => rowById.get(id))
        .filter((r): r is typeof row => !!r)];

      const newNote = buildParticipationNote(
        allRows,
        row.id,
        row.projectCode,
        row.boardName ?? '',
        projectDatesMap,
      );

      const currentNote = row.notes ?? '';
      if (newNote !== currentNote) {
        await RecruitmentRows.update({ id: row.id, record: { notes: newNote || undefined } });
        updated++;
      }
    }

    return { updated, total: rowsToUpdate.length };
  },
});

