import React from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import TeamMemberPicker from '../TeamMemberPicker';

interface TeamUser {
  id: string;
  firstName?: string;
  lastName?: string;
  email?: string;
}

interface TeamEditDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  teamUsers: TeamUser[];
  teamLider: string[];
  setTeamLider: (ids: string[]) => void;
  teamAnalistas: string[];
  setTeamAnalistas: (ids: string[]) => void;
  teamModeradores: string[];
  setTeamModeradores: (ids: string[]) => void;
  teamAsistentes: string[];
  setTeamAsistentes: (ids: string[]) => void;
  saving: boolean;
  onSave: () => void;
}

export function TeamEditDialog({
  open, onOpenChange,
  teamUsers,
  teamLider, setTeamLider,
  teamAnalistas, setTeamAnalistas,
  teamModeradores, setTeamModeradores,
  teamAsistentes, setTeamAsistentes,
  saving, onSave,
}: TeamEditDialogProps) {
  return (
    <Dialog open={open} onOpenChange={o => { if (!o) onOpenChange(false); }}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader><DialogTitle>Equipo del proyecto</DialogTitle></DialogHeader>
        <div className="space-y-4 py-1 max-h-[60vh] overflow-y-auto pr-1">
          <TeamMemberPicker
            users={teamUsers}
            selected={teamLider}
            onChange={ids => setTeamLider(ids.slice(0, 1))}
            label="Líder"
            multiple={false}
            placeholder="Seleccionar líder..."
          />
          <TeamMemberPicker
            users={teamUsers}
            selected={teamAnalistas}
            onChange={setTeamAnalistas}
            label="Analistas"
            placeholder="Agregar analistas..."
          />
          <TeamMemberPicker
            users={teamUsers}
            selected={teamModeradores}
            onChange={setTeamModeradores}
            label="Moderadores"
            placeholder="Agregar moderadores..."
          />
          <TeamMemberPicker
            users={teamUsers}
            selected={teamAsistentes}
            onChange={setTeamAsistentes}
            label="Asistentes"
            placeholder="Agregar asistentes..."
          />
        </div>
        <DialogFooter>
          <Button variant="outline" size="sm" onClick={() => onOpenChange(false)}>Cancelar</Button>
          <Button size="sm" onClick={onSave} disabled={saving}>
            {saving ? 'Guardando...' : 'Guardar equipo'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

src/components/table/GroupPicker.tsx.content:
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { getGroupColor } from './tableUtils';
import type { DynCols } from '../DynamicColumns';
import type { DynColumn } from '../../hooks/useDynamicColumns';

interface Props {
  rowId: string;
  groups: DynColumn[];
  groupDynCols: DynCols;
}

export function GroupPicker({ rowId, groups, groupDynCols }: Props) {
  const currentGroup = groups.find(g => groupDynCols.getCellVal(rowId, g.id)?.textValue === '1');
  const color = currentGroup ? getGroupColor(currentGroup.columnType) : undefined;

  if (groups.length === 0) return <span className="w-3 h-3 flex-shrink-0" />;

  const assign = async (newGroupId: string | null) => {
    // Clear ALL groups for this row to fix phantom assignments
    await Promise.all(groups.filter(g => groupDynCols.getCellVal(rowId, g.id)?.textValue === '1').map(g => groupDynCols.setCellVal(rowId, g.id, { textValue: undefined })));
    if (newGroupId) await groupDynCols.setCellVal(rowId, newGroupId, { textValue: '1' });
  };

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <button
          title={currentGroup ? `Grupo: ${currentGroup.columnName}` : 'Asignar grupo'}
          className={`w-3 h-3 rounded-full flex-shrink-0 transition-transform hover:scale-125 border ${
            currentGroup ? 'border-transparent' : 'border-dashed border-muted-foreground/40'
          }`}
          style={color ? { backgroundColor: color } : {}}
        />
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" className="w-44 p-1">
        <p className="text-[10px] text-muted-foreground uppercase tracking-wider px-2 py-1">Asignar a grupo</p>
        <DropdownMenuItem onClick={() => assign(null)} className="text-xs gap-2">
          <div className="w-3 h-3 rounded-full border border-dashed border-muted-foreground/40 flex-shrink-0" />
          Sin grupo
          {!currentGroup && <span className="ml-auto text-primary">✓</span>}
        </DropdownMenuItem>
        <div className="my-1 border-t border-border/30" />
        {groups.map(g => (
          <DropdownMenuItem key={g.id} onClick={() => assign(g.id)} className="text-xs gap-2">
            <div className="w-3 h-3 rounded-full flex-shrink-0" style={{ backgroundColor: getGroupColor(g.columnType) }} />
            <span className="truncate flex-1">{g.columnName}</span>
            {g.id === currentGroup?.id && <span className="ml-auto text-primary">✓</span>}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

src/components/table/InlineInput.tsx.content:
import { useState, useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';

interface Props {
  value: string;
  onSave: (v: string) => void;
  onCancel: () => void;
  className?: string;
  suggestions?: string[];
}

export function InlineInput({ value, onSave, onCancel, className = '', suggestions }: Props) {
  const [val, setVal] = useState(value);
  const [activeIdx, setActiveIdx] = useState(-1);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => { inputRef.current?.focus(); inputRef.current?.select(); }, []);

  const filtered = (suggestions && val.trim().length > 0)
    ? suggestions.filter(s => s && s !== val && s.toLowerCase().includes(val.toLowerCase())).slice(0, 8)
    : [];
  const showDrop = filtered.length > 0;

  const getDropPos = () => {
    if (!inputRef.current) return null;
    const r = inputRef.current.getBoundingClientRect();
    return { top: r.bottom + 2, left: r.left, width: Math.max(r.width, 180) };
  };

  const selectSugg = (s: string) => {
    setActiveIdx(-1);
    onSave(s);
  };

  return (
    <>
      <input
        ref={inputRef}
        value={val}
        onChange={e => { setVal(e.target.value); setActiveIdx(-1); }}
        onBlur={() => onSave(val)}
        onKeyDown={e => {
          if (showDrop) {
            if (e.key === 'ArrowDown') { e.preventDefault(); setActiveIdx(i => Math.min(i + 1, filtered.length - 1)); return; }
            if (e.key === 'ArrowUp') { e.preventDefault(); setActiveIdx(i => Math.max(i - 1, -1)); return; }
            if (e.key === 'Enter' && activeIdx >= 0) { e.preventDefault(); selectSugg(filtered[activeIdx]); return; }
          }
          if (e.key === 'Enter') { e.preventDefault(); onSave(val); }
          if (e.key === 'Escape') { e.preventDefault(); onCancel(); }
        }}
        className={`bg-transparent border-0 outline-none ring-0 p-0 m-0 text-sm leading-tight w-full ${className}`}
        style={{ boxShadow: 'none' }}
      />
      {showDrop && (() => {
        const pos = getDropPos();
        if (!pos) return null;
        return createPortal(
          <div
            style={{ position: 'fixed', top: pos.top, left: pos.left, width: pos.width, zIndex: 9999 }}
            className="bg-popover border border-border shadow-lg rounded-md overflow-hidden"
          >
            <div className="max-h-[200px] overflow-y-auto py-0.5">
              {filtered.map((s, i) => (
                <button
                  key={s}
                  type="button"
                  onMouseDown={e => { e.preventDefault(); selectSugg(s); }}
                  className={`w-full text-left px-2.5 py-1.5 text-xs truncate transition-colors block ${
                    i === activeIdx ? 'bg-accent text-accent-foreground' : 'hover:bg-muted text-foreground'
                  }`}
                >
                  {s}
                </button>
              ))}
            </div>
          </div>,
          document.body
        );
      })()}
    </>
  );
}

src/api/cleanupDuplicateCellValues.ts.content:
import { z } from 'zod';
import { createEndpoint, Boards, CellValues } from 'zite-integrations-backend-sdk';

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const SUFFIXES = ['', '::groups', '::children'] as const;
const BATCH_DELAY_MS = 300;
const delay = (ms: number) => new Promise(r => setTimeout(r, ms));

function buildLegacyId(boardType: string, projectCode: string, boardName: string): string {
  const prefix = boardType === 'calendar' ? 'cal-'
    : boardType === 'recruitment' ? 'recruitment-'
    : boardType === 'events' ? 'events-'
    : 'pm-';
  return boardName ? `${prefix}${projectCode}-${boardName}` : `${prefix}${projectCode}`;
}

const exampleSchema = z.object({
  rowId: z.string(),
  columnId: z.string(),
  legacyBoardId: z.string(),
  uuidBoardId: z.string(),
  keptId: z.string(),
  deletedIds: z.array(z.string()),
  action: z.string(),
});

export default createEndpoint({
  authenticated: true,
  description: 'Detect and clean up duplicate CellValues across legacy and UUID boardIds for a given project. Supports dryRun mode. Does not touch events- boards.',
  inputSchema: z.object({
    projectCode: z.string(),
    dryRun: z.boolean().default(true),
  }),
  outputSchema: z.object({
    projectCode: z.string(),
    dryRun: z.boolean(),
    boardPairsScanned: z.number(),
    totalCellsScanned: z.number(),
    duplicateGroupsFound: z.number(),
    recordsToKeep: z.number(),
    recordsToMigrate: z.number(),
    recordsToDelete: z.number(),
    migrated: z.number(),
    deleted: z.number(),
    failed: z.number(),
    examples: z.array(exampleSchema),
    elapsed: z.number(),
  }),
  execute: async ({ input }) => {
    const startTime = Date.now();
    const { projectCode, dryRun } = input;

    // 1. Load all active boards for this project
    const { records: boards } = await Boards.findAll({
      filters: { projectCode },
      limit: 200,
    });
    const activeBoards = boards.filter(b => !b.deletedAt);

    // 2. Build legacy→UUID pairs (skip events- boards)
    const boardPairs: Array<{
      uuid: string;
      legacy: string;
      suffix: string;
      boardName: string;
      boardType: string;
    }> = [];

    for (const board of activeBoards) {
      const bType = board.boardType || 'pm';
      if (bType === 'events') continue; // events- are permanent legacy
      const bName = board.boardName ?? '';
      const legacyBase = buildLegacyId(bType, projectCode, bName);

      for (const suffix of SUFFIXES) {
        boardPairs.push({
          uuid: suffix ? `${board.id}${suffix}` : board.id,
          legacy: suffix ? `${legacyBase}${suffix}` : legacyBase,
          suffix,
          boardName: bName,
          boardType: bType,
        });
      }
    }

    // 3. For each pair, load cells under both boardIds and detect duplicates
    let totalCellsScanned = 0;
    let duplicateGroupsFound = 0;
    let recordsToKeep = 0;
    let recordsToMigrate = 0;
    let recordsToDelete = 0;
    let migrated = 0;
    let deleted = 0;
    let failed = 0;
    const examples: z.infer<typeof exampleSchema>[] = [];

    for (const pair of boardPairs) {
      // Load all cells under UUID boardId
      const uuidCells: any[] = [];
      let offset = 0;
      let hasMore = true;
      while (hasMore) {
        const res = await CellValues.findAll({
          filters: { boardId: pair.uuid },
          offset,
          limit: 2000,
        });
        uuidCells.push(...res.records);
        hasMore = res.hasMore;
        offset += res.records.length;
      }

      // Load all cells under legacy boardId (skip if same as UUID)
      const legacyCells: any[] = [];
      if (pair.legacy !== pair.uuid) {
        offset = 0;
        hasMore = true;
        while (hasMore) {
          const res = await CellValues.findAll({
            filters: { boardId: pair.legacy },
            offset,
            limit: 2000,
          });
          legacyCells.push(...res.records);
          hasMore = res.hasMore;
          offset += res.records.length;
        }
      }

      totalCellsScanned += uuidCells.length + legacyCells.length;

      if (uuidCells.length === 0 && legacyCells.length === 0) continue;

      // Group all cells by rowId + columnId
      const groups: Record<string, { uuid: any[]; legacy: any[] }> = {};

      for (const cell of uuidCells) {
        const key = `${cell.rowId}|${cell.columnId}`;
        if (!groups[key]) groups[key] = { uuid: [], legacy: [] };
        groups[key].uuid.push(cell);
      }
      for (const cell of legacyCells) {
        const key = `${cell.rowId}|${cell.columnId}`;
        if (!groups[key]) groups[key] = { uuid: [], legacy: [] };
        groups[key].legacy.push(cell);
      }

      // Process each group
      for (const [key, group] of Object.entries(groups)) {
        const totalInGroup = group.uuid.length + group.legacy.length;
        if (totalInGroup <= 1 && group.legacy.length === 0) continue; // No action needed

        // Case 1: Legacy-only (no UUID) → migrate to UUID
        if (group.uuid.length === 0 && group.legacy.length > 0) {
          // Keep the first legacy cell, migrate it; delete extras
          const keeper = group.legacy[0];
          const extras = group.legacy.slice(1);

          duplicateGroupsFound += extras.length > 0 ? 1 : 0;
          recordsToKeep++;
          recordsToMigrate++;
          recordsToDelete += extras.length;

          if (!dryRun) {
            try {
              await CellValues.update({ id: keeper.id, record: { boardId: pair.uuid } });
              migrated++;
            } catch {
              failed++;
            }
            for (const extra of extras) {
              try {
                await CellValues.delete({ id: extra.id });
                deleted++;
              } catch {
                failed++;
              }
            }
            await delay(BATCH_DELAY_MS);
          }

          if (examples.length < 50) {
            examples.push({
              rowId: keeper.rowId ?? '',
              columnId: keeper.columnId ?? '',
              legacyBoardId: pair.legacy,
              uuidBoardId: pair.uuid,
              keptId: keeper.id,
              deletedIds: extras.map((e: any) => e.id),
              action: extras.length > 0 ? 'migrate+dedup' : 'migrate',
            });
          }
          continue;
        }

        // Case 2: UUID exists — legacy are duplicates to delete
        if (group.uuid.length >= 1 && group.legacy.length > 0) {
          duplicateGroupsFound++;
          // Keep the first UUID cell
          const keeper = group.uuid[0];
          const uuidExtras = group.uuid.slice(1);
          const toDelete = [...group.legacy, ...uuidExtras];

          recordsToKeep++;
          recordsToDelete += toDelete.length;

          if (!dryRun) {
            for (const dup of toDelete) {
              try {
                await CellValues.delete({ id: dup.id });
                deleted++;
              } catch {
                failed++;
              }
            }
            if (toDelete.length > 0) await delay(BATCH_DELAY_MS);
          }

          if (examples.length < 50) {
            examples.push({
              rowId: keeper.rowId ?? '',
              columnId: keeper.columnId ?? '',
              legacyBoardId: pair.legacy,
              uuidBoardId: pair.uuid,
              keptId: keeper.id,
              deletedIds: toDelete.map((d: any) => d.id),
              action: 'dedup-cross-boardId',
            });
          }
          continue;
        }

        // Case 3: Multiple UUID cells, no legacy — exact duplicates under same boardId
        if (group.uuid.length > 1 && group.legacy.length === 0) {
          duplicateGroupsFound++;
          const keeper = group.uuid[0];
          const extras = group.uuid.slice(1);

          recordsToKeep++;
          recordsToDelete += extras.length;

          if (!dryRun) {
            for (const dup of extras) {
              try {
                await CellValues.delete({ id: dup.id });
                deleted++;
              } catch {
                failed++;
              }
            }
            if (extras.length > 0) await delay(BATCH_DELAY_MS);
          }

          if (examples.length < 50) {
            examples.push({
              rowId: keeper.rowId ?? '',
              columnId: keeper.columnId ?? '',
              legacyBoardId: pair.legacy,
              uuidBoardId: pair.uuid,
              keptId: keeper.id,
              deletedIds: extras.map((e: any) => e.id),
              action: 'dedup-same-boardId',
            });
          }
        }
      }
    }

    return {
      projectCode,
      dryRun,
      boardPairsScanned: boardPairs.length,
      totalCellsScanned,
      duplicateGroupsFound,
      recordsToKeep,
      recordsToMigrate,
      recordsToDelete,
      migrated,
      deleted,
      failed,
      examples,
      elapsed: (Date.now() - startTime) / 1000,
    };
  },
});

src/components/TeamsChannelDialog.tsx.content:
import { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/tabs';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { ExternalLink, Loader2, Unlink, Link2, Plus, AlertCircle } from 'lucide-react';
import { toast } from 'sonner';
import {
  listTeamsChannels, createTeamsChannel, unlinkTeamsChannel,
  ListTeamsChannelsOutputType, GetProjectsOutputType,
} from 'zite-endpoints-sdk';

type Project = GetProjectsOutputType['projects'][0];
type Team = ListTeamsChannelsOutputType['teams'][0];

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  project: Project | null;
  onSuccess: () => void;
}

export default function TeamsChannelDialog({ open, onOpenChange, project, onSuccess }: Props) {
  const [team, setTeam] = useState<Team | null>(null);
  const [loadingTeams, setLoadingTeams] = useState(false);
  const [loadError, setLoadError] = useState(false);
  const [tab, setTab] = useState<'create' | 'link'>('create');

  const [createChannelName, setCreateChannelName] = useState('');
  const [linkChannelId, setLinkChannelId] = useState('');

  const [saving, setSaving] = useState(false);
  const [unlinking, setUnlinking] = useState(false);

  const hasChannel = !!(project?.teamsChannelStatus === 'Listo' && project?.teamsChannelUrl);

  useEffect(() => {
    if (!open) return;
    setCreateChannelName(project?.projectCode ?? '');
    setLinkChannelId('');
    setTab('create');
    setLoadError(false);

    setLoadingTeams(true);
    listTeamsChannels({})
      .then(res => {
        setTeam(res.teams[0] ?? null);
        if (res.teams.length === 0) setLoadError(true);
      })
      .catch(() => setLoadError(true))
      .finally(() => setLoadingTeams(false));
  }, [open, project?.projectCode]);

  const handleConfirm = async () => {
    if (!project || !team) return;
    setSaving(true);
    try {
      if (tab === 'create') {
        if (!createChannelName.trim()) { toast.error('Escribe el nombre del canal'); setSaving(false); return; }
        await createTeamsChannel({
          projectCode: project.projectCode ?? '',
          mode: 'create',
          teamId: team.id,
          channelName: createChannelName.trim(),
        });
        toast.success('¡Canal creado con carpetas — vinculado al proyecto!');
      } else {
        if (!linkChannelId) { toast.error('Selecciona un canal'); setSaving(false); return; }
        const ch = team.channels.find(c => c.id === linkChannelId);
        if (!ch?.webUrl) { toast.error('Este canal no tiene URL disponible'); setSaving(false); return; }
        await createTeamsChannel({ projectCode: project.projectCode ?? '', mode: 'link', channelUrl: ch.webUrl });
        toast.success('Canal vinculado exitosamente');
      }
      onSuccess();
      onOpenChange(false);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : 'Error al configurar el canal';
      toast.error(msg);
    } finally {
      setSaving(false);
    }
  };

  const handleUnlink = async () => {
    if (!project) return;
    setUnlinking(true);
    try {
      await unlinkTeamsChannel({ projectCode: project.projectCode ?? '' });
      toast.success('Canal desvinculado');
      onSuccess();
      onOpenChange(false);
    } catch {
      toast.error('Error al desvincular el canal');
    } finally {
      setUnlinking(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <span>Canal de Teams</span>
            {project?.projectCode && (
              <span className="text-xs font-mono bg-muted px-2 py-0.5 rounded-md text-muted-foreground">
                {project.projectCode}
              </span>
            )}
          </DialogTitle>
        </DialogHeader>

        {hasChannel ? (
          /* ── Already linked ── */
          <div className="space-y-4 py-2">
            <div className="flex items-center gap-3 p-3 rounded-lg bg-chart-2/10 border border-chart-2/20">
              <div className="w-8 h-8 rounded-full bg-chart-2/20 flex items-center justify-center flex-shrink-0">
                <Link2 className="w-4 h-4 text-chart-2" />
              </div>
              <div className="min-w-0 flex-1">
                <p className="text-xs font-semibold text-chart-2">Canal vinculado</p>
                <p className="text-xs text-muted-foreground truncate mt-0.5">{project?.teamsChannelUrl}</p>
              </div>
            </div>
            <div className="flex gap-2">
              <a href={project?.teamsChannelUrl ?? '#'} target="_blank" rel="noopener noreferrer" className="flex-1">
                <Button variant="outline" className="w-full gap-2 text-sm">
                  <ExternalLink className="w-3.5 h-3.5" /> Abrir en Teams
                </Button>
              </a>
              <Button
                variant="ghost"
                onClick={handleUnlink}
                disabled={unlinking}
                className="gap-2 text-sm text-destructive hover:text-destructive hover:bg-destructive/10"
              >
                {unlinking ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Unlink className="w-3.5 h-3.5" />}
                Desvincular
              </Button>
            </div>
          </div>
        ) : (
          /* ── No channel yet ── */
          <>
            {loadingTeams ? (
              <div className="flex items-center justify-center py-10 gap-2 text-muted-foreground text-sm">
                <Loader2 className="w-4 h-4 animate-spin" /> Cargando canales de Teams...
              </div>
            ) : loadError || !team ? (
              <div className="flex items-center gap-3 p-4 rounded-lg bg-destructive/5 border border-destructive/20 my-2">
                <AlertCircle className="w-5 h-5 text-destructive flex-shrink-0" />
                <div>
                  <p className="text-sm font-medium text-destructive">No se pudo cargar el equipo de Teams</p>
                  <p className="text-xs text-muted-foreground mt-0.5">Verifica la conexión con Microsoft Teams e intenta de nuevo.</p>
                </div>
              </div>
            ) : (
              <Tabs value={tab} onValueChange={v => setTab(v as 'create' | 'link')} className="py-2">
                <TabsList className="w-full">
                  <TabsTrigger value="create" className="flex-1 gap-1.5">
                    <Plus className="w-3.5 h-3.5" /> Crear nuevo
                  </TabsTrigger>
                  <TabsTrigger value="link" className="flex-1 gap-1.5">
                    <Link2 className="w-3.5 h-3.5" /> Vincular existente
                  </TabsTrigger>
                </TabsList>

                {/* ── Create tab ── */}
                <TabsContent value="create" className="space-y-4 mt-4">
                  <div className="flex items-center gap-2 px-3 py-2 rounded-lg bg-muted/50 border border-border/60">
                    <span className="text-xs text-muted-foreground">Equipo:</span>
                    <span className="text-xs font-semibold">{team.displayName}</span>
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-xs">Nombre del canal</Label>
                    <Input
                      value={createChannelName}
                      onChange={e => setCreateChannelName(e.target.value)}
                      placeholder={project?.projectCode ?? 'Nombre del canal'}
                      autoFocus
                    />
                  </div>
                  <p className="text-xs text-muted-foreground">
                    Se crearán automáticamente las carpetas: PROPUESTA, CALENDARIOS, TIMELINE, ENTREGABLES, MATERIALES, GRABACIONES y GUÍAS.
                  </p>
                </TabsContent>

                {/* ── Link tab ── */}
                <TabsContent value="link" className="space-y-4 mt-4">
                  <div className="flex items-center gap-2 px-3 py-2 rounded-lg bg-muted/50 border border-border/60">
                    <span className="text-xs text-muted-foreground">Equipo:</span>
                    <span className="text-xs font-semibold">{team.displayName}</span>
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-xs">Canal existente</Label>
                    <Select value={linkChannelId} onValueChange={setLinkChannelId}>
                      <SelectTrigger><SelectValue placeholder="Seleccionar canal…" /></SelectTrigger>
                      <SelectContent>
                        {team.channels.map(ch => (
                          <SelectItem key={ch.id} value={ch.id}>{ch.displayName}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                </TabsContent>
              </Tabs>
            )}

            {!loadingTeams && !loadError && team && (
              <DialogFooter>
                <Button variant="outline" onClick={() => onOpenChange(false)}>Cancelar</Button>
                <Button onClick={handleConfirm} disabled={saving} className="gap-2">
                  {saving && <Loader2 className="w-3.5 h-3.5 animate-spin" />}
                  {tab === 'create' ? 'Crear canal' : 'Vincular canal'}
                </Button>
              </DialogFooter>
            )}
          </>
        )}
      </DialogContent>
    </Dialog>
  );
}

src/components/pm/EventFormFields.tsx.content:
import { useState, useCallback } from 'react';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Calendar as CalendarUI } from '@/components/ui/calendar';
import { Button } from '@/components/ui/button';
import { Switch } from '@/components/ui/switch';
import { Clock } from 'lucide-react';

// ── Types ──────────────────────────────────────────────────────────────────────
export interface EventFormValues {
  eventDate: string;
  durationHours: number;
  location: string;
  locationCustom: boolean;
  inviteEmails: string;
  dinamica: string;
  perfil: string;
  descripcion: string;
  detallesAdicionales: string;
  detallesAdicionales2: string;
  direccion: string;
  link: string;
  notes: string;
  restringirReenvio: boolean;
}

export const EMPTY_EVENT_FORM: EventFormValues = {
  eventDate: '',
  durationHours: 1,
  location: '',
  locationCustom: false,
  inviteEmails: '',
  dinamica: '',
  perfil: '',
  descripcion: '',
  detallesAdicionales: '',
  detallesAdicionales2: '',
  direccion: '',
  link: '',
  notes: '',
  restringirReenvio: false,
};

export const PRESET_LOCS = [
  'Online', 'Sala 5-A', 'Sala 5-B', 'Sala 5-C',
  'Sala 6-A', 'Sala 6-B', 'Sala 6-D', 'Sala 6-F',
  'Sala 6-G', 'Sala 6-H', 'Otro',
];

// ── Datetime helpers ──────────────────────────────────────────────────────────
function fmtDatetime(isoStr: string): string {
  const d = new Date(isoStr);
  const day = d.getDate();
  const mon = d.toLocaleDateString('es', { month: 'short' }).replace('.', '');
  const year = String(d.getFullYear()).slice(-2);
  const hh = String(d.getHours()).padStart(2, '0');
  const mm = String(d.getMinutes()).padStart(2, '0');
  return `${day} ${mon} ${year}', ${hh}:${mm}`;
}

const HOURS = Array.from({ length: 24 }, (_, i) => i);
const MINUTES = Array.from({ length: 12 }, (_, i) => i * 5);

// ── DatetimePicker ────────────────────────────────────────────────────────────
export function DatetimePicker({ value, onChange }: { value: string; onChange: (iso: string) => void }) {
  const [open, setOpen] = useState(false);
  const [draftDate, setDraftDate] = useState<Date | undefined>(undefined);
  const [draftHour, setDraftHour] = useState(0);
  const [draftMinute, setDraftMinute] = useState(0);

  const parseInit = useCallback(() => {
    if (value) {
      const d = new Date(value);
      setDraftDate(new Date(d.getFullYear(), d.getMonth(), d.getDate()));
      setDraftHour(d.getHours());
      setDraftMinute(Math.round(d.getMinutes() / 5) * 5 % 60);
    } else {
      const now = new Date();
      setDraftDate(new Date(now.getFullYear(), now.getMonth(), now.getDate()));
      setDraftHour(now.getHours());
      setDraftMinute(Math.round(now.getMinutes() / 5) * 5 % 60);
    }
  }, [value]);

  const handleOpenChange = (o: boolean) => { if (o) parseInit(); setOpen(o); };

  const handleSave = () => {
    if (!draftDate) { onChange(''); setOpen(false); return; }
    const d = new Date(draftDate);
    d.setHours(draftHour, draftMinute, 0, 0);
    onChange(d.toISOString());
    setOpen(false);
  };

  const previewIso = draftDate
    ? (() => { const d = new Date(draftDate); d.setHours(draftHour, draftMinute, 0, 0); return d.toISOString(); })()
    : '';

  return (
    <Popover open={open} onOpenChange={handleOpenChange}>
      <PopoverTrigger asChild>
        <button
          type="button"
          className="w-full flex items-center gap-2 h-9 rounded-md border border-input bg-background px-3 text-sm text-left hover:bg-muted/50 transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-1"
        >
          <Clock className="w-3.5 h-3.5 text-muted-foreground/50 flex-shrink-0" />
          {value
            ? <span className="text-foreground">{fmtDatetime(value)}</span>
            : <span className="text-muted-foreground">Seleccionar fecha y hora…</span>}
        </button>
      </PopoverTrigger>
      <PopoverContent className="w-[320px] p-0" align="start">
        <CalendarUI mode="single" selected={draftDate} onSelect={d => setDraftDate(d)} initialFocus className="border-b border-border/30" />
        <div className="flex gap-0 border-b border-border/30">
          <div className="flex-1 border-r border-border/30">
            <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wide px-2 pt-2 pb-1">Hora</p>
            <div className="grid grid-cols-4 gap-0.5 px-2 pb-2 max-h-[100px] overflow-y-auto">
              {HOURS.map(h => (
                <button key={h} type="button" onClick={() => setDraftHour(h)}
                  className={`text-[11px] font-mono py-0.5 rounded transition-colors ${draftHour === h ? 'bg-primary text-primary-foreground font-semibold' : 'hover:bg-muted text-foreground'}`}>
                  {String(h).padStart(2, '0')}
                </button>
              ))}
            </div>
          </div>
          <div className="flex-1">
            <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wide px-2 pt-2 pb-1">Min</p>
            <div className="grid grid-cols-3 gap-0.5 px-2 pb-2">
              {MINUTES.map(m => (
                <button key={m} type="button" onClick={() => setDraftMinute(m)}
                  className={`text-[11px] font-mono py-0.5 rounded transition-colors ${draftMinute === m ? 'bg-primary text-primary-foreground font-semibold' : 'hover:bg-muted text-foreground'}`}>
                  {String(m).padStart(2, '0')}
                </button>
              ))}
            </div>
          </div>
        </div>
        <div className="flex items-center justify-between gap-2 px-3 py-2">
          <span className="text-xs text-muted-foreground font-mono">{previewIso ? fmtDatetime(previewIso) : '—'}</span>
          <div className="flex gap-2">
            <Button variant="outline" size="sm" className="h-7 text-xs" onClick={() => { onChange(''); setOpen(false); }}>Borrar</Button>
            <Button size="sm" className="h-7 text-xs" onClick={handleSave}>Guardar</Button>
          </div>
        </div>
      </PopoverContent>
    </Popover>
  );
}

// ── EventFormFields ───────────────────────────────────────────────────────────
