import { GetDealsOutputType } from 'zite-endpoints-sdk';
import { Calendar, DollarSign } from 'lucide-react';
import { PHASE_COLOR_MAP, getCurrencySymbol, fmtMoney } from './dealUtils';

type Deal = GetDealsOutputType['deals'][0];

interface Props {
  deal: Deal;
  onClick: () => void;
  onDragStart: () => void;
}

export default function DealCard({ deal, onClick, onDragStart }: Props) {
  const color = PHASE_COLOR_MAP[deal.phase ?? ''] ?? 'hsl(var(--muted-foreground))';
  const sym = getCurrencySymbol(deal.currency);
  const amount = deal.clientPrice ?? deal.quotedCost;

  return (
    <div
      className="bg-card border rounded-lg p-3 cursor-pointer hover:shadow-md transition-all duration-150 space-y-2 select-none"
      style={{ borderLeft: `3px solid ${color}` }}
      onClick={onClick}
      draggable
      onDragStart={onDragStart}
    >
      <div className="font-medium text-sm leading-tight line-clamp-2">
        {deal.dealName || <span className="text-muted-foreground italic">Sin nombre</span>}
      </div>

      {deal.client && (
        <div className="text-xs text-muted-foreground truncate">{deal.client}</div>
      )}

      {deal.tematica && (
        <div className="text-xs px-1.5 py-0.5 bg-muted rounded truncate">{deal.tematica}</div>
      )}

      <div className="flex items-center justify-between">
        {amount != null ? (
          <div className="flex items-center gap-0.5 text-xs font-semibold" style={{ color }}>
            <DollarSign className="w-3 h-3" />
            {fmtMoney(amount, sym)}
          </div>
        ) : <span />}

        {deal.proposalDate && (
          <div className="flex items-center gap-1 text-xs text-muted-foreground">
            <Calendar className="w-3 h-3" />
            {(() => { const [y,m,d] = deal.proposalDate!.slice(0,10).split('-').map(Number); return new Date(y,m-1,d).toLocaleDateString('es-MX', { day: '2-digit', month: 'short' }); })()}
          </div>
        )}
      </div>
    </div>
  );
}

src/components/commercial/dealUtils.ts.content:
export const PHASES = [
  { key: 'Prospecto', color: 'hsl(var(--muted-foreground))' },
  { key: 'Brief recibido', color: 'hsl(var(--chart-5))' },
  { key: 'Cotización enviada', color: 'hsl(var(--chart-4))' },
  { key: 'Negociación', color: 'hsl(var(--chart-1))' },
  { key: 'Ganado', color: 'hsl(var(--chart-2))' },
  { key: 'Perdido', color: 'hsl(var(--destructive))' },
] as const;

export const PHASE_COLOR_MAP: Record<string, string> = Object.fromEntries(
  PHASES.map(p => [p.key, p.color])
);

export const RUBROS = [
  'Reclutamiento e incentivos',
  'Moderación',
  'Management',
  'Logística y operación',
  'Back office',
] as const;

export const COTIZ_STATUSES = ['Borrador', 'Enviada', 'Aprobada', 'Rechazada'] as const;

export const COTIZ_STATUS_COLORS: Record<string, string> = {
  Borrador: 'hsl(var(--muted-foreground))',
  Enviada: 'hsl(var(--chart-5))',
  Aprobada: 'hsl(var(--chart-2))',
  Rechazada: 'hsl(var(--destructive))',
};

export const CURRENCIES = [
  { value: 'MXN 🇲🇽', label: 'MXN ($)' },
  { value: 'USD 🇺🇸', label: 'USD ($)' },
  { value: 'EUR 🇪🇺', label: 'EUR (€)' },
];

export const COTIZ_CURRENCIES = [
  { value: 'MXN', label: 'MXN ($)' },
  { value: 'USD', label: 'USD ($)' },
  { value: 'EUR', label: 'EUR (€)' },
];

export function getCurrencySymbol(currency?: string): string {
  if (currency?.startsWith('EUR')) return '€';
  return '$';
}

export function fmtMoney(amount?: number, symbol = '$'): string {
  if (amount == null) return '—';
  return `${symbol}${amount.toLocaleString('es-MX', { minimumFractionDigits: 0, maximumFractionDigits: 0 })}`;
}

export function fmtMoneyFull(amount?: number, symbol = '$'): string {
  if (amount == null) return '—';
  return `${symbol}${amount.toLocaleString('es-MX', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

