import { useState, useMemo, Fragment } from 'react';
import { GetDealsOutputType } from 'zite-endpoints-sdk';
import { Button } from '@/components/ui/button';
import { Pencil, ChevronUp, ChevronDown, ChevronRight, ChevronsUpDown, Clock, CalendarCheck, CheckCircle2 } from 'lucide-react';
import { PHASE_COLOR_MAP, getCurrencySymbol, fmtMoney } from './dealUtils';
import { cn } from '@/lib/utils';
import ApprovalReviewDialog from './ApprovalReviewDialog';

type Deal = GetDealsOutputType['deals'][0];

type SortField = 'dealName' | 'client' | 'phase' | 'tematica' | 'quotedCost' | 'clientPrice' | 'currency' | 'proposalDate' | 'approvalDate';
type SortDir = 'asc' | 'desc';
type SortMode = 'byField' | 'createdAt';

const APPROVE_PHASES = ['Cotización enviada', 'Negociación'];

/** Parsea una fecha ISO como fecha local (sin offset UTC) */
function parseLocalDate(dateStr: string): Date {
  const [y, m, d] = dateStr.slice(0, 10).split('-').map(Number);
  return new Date(y, m - 1, d);
}

function formatLocalDate(dateStr: string): string {
  return parseLocalDate(dateStr).toLocaleDateString('es-MX');
}

function getYear(deal: Deal): string {
  const d = deal.approvalDate ?? deal.proposalDate;
  if (!d) return 'Sin fecha';
  return d.slice(0, 4);
}

function sortDeals(deals: Deal[], field: SortField, dir: SortDir): Deal[] {
  return [...deals].sort((a, b) => {
    let av: any = a[field];
    let bv: any = b[field];

    if (field === 'proposalDate' || field === 'approvalDate') {
      av = av ? parseLocalDate(av).getTime() : 0;
      bv = bv ? parseLocalDate(bv).getTime() : 0;
    } else if (field === 'quotedCost' || field === 'clientPrice') {
      av = av ?? 0;
      bv = bv ?? 0;
    } else {
      av = (av ?? '').toString().toLowerCase();
      bv = (bv ?? '').toString().toLowerCase();
    }

    if (av < bv) return dir === 'asc' ? -1 : 1;
    if (av > bv) return dir === 'asc' ? 1 : -1;
    return 0;
  });
}

function SortIcon({ field, sortField, sortDir }: { field: SortField; sortField: SortField; sortDir: SortDir }) {
  if (sortField !== field) return <ChevronsUpDown className="w-3 h-3 opacity-30 ml-1 shrink-0" />;
  return sortDir === 'asc'
    ? <ChevronUp className="w-3 h-3 ml-1 shrink-0 text-primary" />
    : <ChevronDown className="w-3 h-3 ml-1 shrink-0 text-primary" />;
}

function ColHeader({ label, field, sortField, sortDir, onSort, disabled }: {
  label: string; field: SortField;
  sortField: SortField; sortDir: SortDir;
  onSort: (f: SortField) => void;
  disabled?: boolean;
}) {
  const active = !disabled && sortField === field;
  return (
    <th className="px-3 py-3 text-left">
      <button
        onClick={() => !disabled && onSort(field)}
        disabled={disabled}
        className={cn(
          'flex items-center gap-0.5 text-xs font-semibold whitespace-nowrap transition-colors',
          disabled ? 'text-muted-foreground/50 cursor-default' : 'hover:text-foreground',
          active ? 'text-primary' : 'text-muted-foreground'
        )}
      >
        {label}
        {!disabled && <SortIcon field={field} sortField={sortField} sortDir={sortDir} />}
      </button>
    </th>
  );
}

function DealRow({ deal, onDealClick, onApprove }: {
  deal: Deal;
  onDealClick: (deal: Deal) => void;
  onApprove: (deal: Deal) => void;
}) {
  const color = PHASE_COLOR_MAP[deal.phase ?? ''] ?? 'hsl(var(--muted-foreground))';
  const sym = getCurrencySymbol(deal.currency);
  const canApprove = APPROVE_PHASES.includes(deal.phase ?? '');
  return (
    <tr className="hover:bg-muted/30 cursor-pointer" onClick={() => onDealClick(deal)}>
      <td className="px-3 py-2.5 font-medium whitespace-nowrap">{deal.dealName || '—'}</td>
      <td className="px-3 py-2.5 text-muted-foreground whitespace-nowrap">{deal.client || '—'}</td>
      <td className="px-3 py-2.5">
        <span className="px-2 py-0.5 rounded-full text-xs font-medium whitespace-nowrap" style={{ backgroundColor: color + '25', color }}>
          {deal.phase || '—'}
        </span>
      </td>
      <td className="px-3 py-2.5 text-muted-foreground max-w-32 truncate">{deal.tematica || '—'}</td>
      <td className="px-3 py-2.5 whitespace-nowrap">{fmtMoney(deal.quotedCost, sym)}</td>
      <td className="px-3 py-2.5 font-medium whitespace-nowrap">{fmtMoney(deal.clientPrice, sym)}</td>
      <td className="px-3 py-2.5 text-muted-foreground text-xs whitespace-nowrap">{deal.currency?.split(' ')[0] || '—'}</td>
      <td className="px-3 py-2.5 text-muted-foreground text-xs whitespace-nowrap">
        {deal.proposalDate ? formatLocalDate(deal.proposalDate) : '—'}
      </td>
      <td className="px-3 py-2.5 text-xs whitespace-nowrap">
        {deal.approvalDate
          ? <span className="text-primary font-medium">{formatLocalDate(deal.approvalDate)}</span>
          : <span className="text-muted-foreground">—</span>}
      </td>
      <td className="px-3 py-2.5">
        <div className="flex items-center gap-1">
          {canApprove && (
            <Button
              size="icon"
              variant="ghost"
              className="h-7 w-7 text-primary hover:text-primary hover:bg-primary/10"
              title="Aprobar deal"
              onClick={e => { e.stopPropagation(); onApprove(deal); }}
            >
              <CheckCircle2 className="w-3.5 h-3.5" />
            </Button>
          )}
          <Button size="icon" variant="ghost" className="h-7 w-7" onClick={e => { e.stopPropagation(); onDealClick(deal); }}>
            <Pencil className="w-3 h-3" />
          </Button>
        </div>
      </td>
    </tr>
  );
}

function YearGroupHeader({ year, count, collapsed, onToggle }: {
  year: string; count: number; collapsed: boolean; onToggle: () => void;
}) {
  return (
    <tr>
      <td colSpan={10} className="px-3 pt-5 pb-1.5">
        <button
          onClick={onToggle}
          className="w-full flex items-center gap-2 group text-left"
        >
          {collapsed
            ? <ChevronRight className="w-3.5 h-3.5 text-primary shrink-0" />
            : <ChevronDown className="w-3.5 h-3.5 text-primary shrink-0" />}
          <span className="text-xs font-bold text-primary tracking-widest uppercase">{year}</span>
          <span className="text-xs text-muted-foreground">({count} deals)</span>
          <div className="flex-1 h-px bg-border group-hover:bg-primary/30 transition-colors" />
        </button>
      </td>
    </tr>
  );
}

interface DealTableProps {
  deals: Deal[];
  onDealClick: (deal: Deal) => void;
  onDealApproved?: (updated: Deal) => void;
}

export default function DealTable({ deals, onDealClick, onDealApproved }: DealTableProps) {
  const [sortField, setSortField] = useState<SortField>('approvalDate');
  const [sortDir, setSortDir] = useState<SortDir>('desc');
  const [sortMode, setSortMode] = useState<SortMode>('createdAt');
  const [collapsedYears, setCollapsedYears] = useState<Set<string>>(new Set());
  const [approvingDeal, setApprovingDeal] = useState<Deal | null>(null);

  const toggleYear = (year: string) => {
    setCollapsedYears(prev => {
      const next = new Set(prev);
      next.has(year) ? next.delete(year) : next.add(year);
      return next;
    });
  };

  const handleSort = (field: SortField) => {
    if (sortField === field) setSortDir(d => d === 'asc' ? 'desc' : 'asc');
    else { setSortField(field); setSortDir('desc'); }
  };

  const handleApprovalSuccess = (res: { projectCode: string; projectId: string; quotedCost: number; notificationsSent: number }) => {
    if (!approvingDeal) return;
    const today = new Date().toISOString().split('T')[0];
    const updated: Deal = { ...approvingDeal, phase: 'Ganado', approvalDate: today, quotedCost: res.quotedCost };
    (updated as any).projects = [res.projectId];
    onDealApproved?.(updated);
    setApprovingDeal(null);
  };

  const sorted = useMemo(() => {
    if (sortMode === 'createdAt') {
      return [...deals].sort((a, b) => (b.rowIndex ?? -1) - (a.rowIndex ?? -1));
    }
    return sortDeals(deals, sortField, sortDir);
  }, [deals, sortField, sortDir, sortMode]);

  // Group by year, most recent first, "Sin fecha" last
  const groups = useMemo(() => {
    const map = new Map<string, Deal[]>();
    for (const deal of sorted) {
      const y = getYear(deal);
      if (!map.has(y)) map.set(y, []);
      map.get(y)!.push(deal);
    }
    const years = [...map.keys()].sort((a, b) => {
      if (a === 'Sin fecha') return 1;
      if (b === 'Sin fecha') return -1;
      return parseInt(b) - parseInt(a);
    });
    return years.map(y => ({ year: y, deals: map.get(y)! }));
  }, [sorted]);

  const colProps = { sortField, sortDir, onSort: handleSort, disabled: sortMode === 'createdAt' };

  return (
    <>
      <div className="bg-card rounded-lg border overflow-x-auto">
        {/* Sort mode toggle */}
        <div className="flex items-center gap-2 px-3 py-2 border-b border-border bg-muted/30">
          <span className="text-xs text-muted-foreground font-medium">Ordenar por:</span>
          <div className="flex items-center rounded-lg border border-border overflow-hidden">
            <button
              onClick={() => setSortMode('createdAt')}
              className={cn(
                'flex items-center gap-1.5 px-2.5 py-1 text-xs font-medium transition-colors',
                sortMode === 'createdAt'
                  ? 'bg-primary text-primary-foreground'
                  : 'bg-card text-muted-foreground hover:bg-muted'
              )}
            >
              <Clock className="w-3 h-3" />
              Último creado
            </button>
            <button
              onClick={() => setSortMode('byField')}
              className={cn(
                'flex items-center gap-1.5 px-2.5 py-1 text-xs font-medium transition-colors',
                sortMode === 'byField'
                  ? 'bg-primary text-primary-foreground'
                  : 'bg-card text-muted-foreground hover:bg-muted'
              )}
            >
              <CalendarCheck className="w-3 h-3" />
              Por columna
            </button>
          </div>
          {sortMode === 'byField' && (
            <span className="text-xs text-muted-foreground italic">Haz clic en los encabezados para ordenar</span>
          )}
        </div>

        <table className="w-full text-sm">
          <thead className="bg-muted/50 border-b border-border">
            <tr>
              <ColHeader label="Deal" field="dealName" {...colProps} />
              <ColHeader label="Cliente" field="client" {...colProps} />
              <ColHeader label="Fase" field="phase" {...colProps} />
              <ColHeader label="Temática" field="tematica" {...colProps} />
              <ColHeader label="Costo cotizado" field="quotedCost" {...colProps} />
              <ColHeader label="Precio cliente" field="clientPrice" {...colProps} />
              <ColHeader label="Moneda" field="currency" {...colProps} />
              <ColHeader label="F. propuesta" field="proposalDate" {...colProps} />
              <ColHeader label="F. aprobación" field="approvalDate" {...colProps} />
              <th className="px-3 py-3 w-20" />
            </tr>
          </thead>
          <tbody className="divide-y divide-border">
            {sorted.length === 0 && (
              <tr><td colSpan={10} className="px-4 py-12 text-center text-muted-foreground">Sin deals. Crea el primero.</td></tr>
            )}
            {sortMode === 'createdAt'
              ? sorted.map(deal => (
                <DealRow key={deal.id} deal={deal} onDealClick={onDealClick} onApprove={setApprovingDeal} />
              ))
              : groups.map(({ year, deals: groupDeals }) => (
                <Fragment key={year}>
                  <YearGroupHeader
                    year={year}
                    count={groupDeals.length}
                    collapsed={collapsedYears.has(year)}
                    onToggle={() => toggleYear(year)}
                  />
                  {!collapsedYears.has(year) && groupDeals.map(deal => (
                    <DealRow key={deal.id} deal={deal} onDealClick={onDealClick} onApprove={setApprovingDeal} />
                  ))}
                </Fragment>
              ))
            }
          </tbody>
        </table>
      </div>

      {approvingDeal && (
        <ApprovalReviewDialog
          open={true}
          onClose={() => setApprovingDeal(null)}
          deal={approvingDeal}
          onApproved={handleApprovalSuccess}
        />
      )}
    </>
  );
}

src/components/finance/CostPnLTable.tsx.content:
import { cn } from '@/lib/utils';

const fmt = (v: number) =>
  new Intl.NumberFormat('es-MX', { style: 'currency', currency: 'MXN', maximumFractionDigits: 0 }).format(v);

type RubroRow = {
  rubro: string;
  cotizado: number;
  costoConMarkup: number;
  precioCliente: number;
  gastado: number;
  markUpInicial: number;
  markUpFinal: number;
  diferenciaTotalMxn: number;
  revenueInicial: number | null;
  revenueFinal: number | null;
};

type Props = {
  byRubro: RubroRow[];
  totals: Omit<RubroRow, 'rubro'>;
};

function NumCell({ value, currency = true }: { value: number; currency?: boolean }) {
  const pos = value >= 0;
  return (
    <td className={cn('px-3 py-3 text-right font-medium tabular-nums', pos ? 'text-emerald-600' : 'text-destructive')}>
      {currency ? fmt(value) : `${value.toFixed(1)}%`}
    </td>
  );
}

function PctCell({ value }: { value: number | null }) {
  if (value === null) return <td className="px-3 py-3 text-right text-muted-foreground">—</td>;
  return <NumCell value={value} currency={false} />;
}

function Row({ row, bold = false }: { row: Omit<RubroRow, 'rubro'> & { rubro?: string }; bold?: boolean }) {
  const cls = bold ? 'font-semibold bg-muted' : 'hover:bg-muted/30 transition-colors';
  return (
    <tr className={cls}>
      <td className={cn('px-3 py-3 text-foreground', bold && 'font-semibold')}>{row.rubro ?? 'Total'}</td>
      <td className="px-3 py-3 text-right text-muted-foreground tabular-nums">{fmt(row.cotizado)}</td>
      <NumCell value={row.markUpInicial} />
      <td className="px-3 py-3 text-right tabular-nums">{fmt(row.costoConMarkup)}</td>
      <td className="px-3 py-3 text-right tabular-nums font-medium">{fmt(row.precioCliente)}</td>
      <td className="px-3 py-3 text-right tabular-nums">{fmt(row.gastado)}</td>
      <NumCell value={row.diferenciaTotalMxn} />
      <NumCell value={row.markUpFinal} />
      <PctCell value={row.revenueInicial} />
      <PctCell value={row.revenueFinal} />
    </tr>
  );
}

export default function CostPnLTable({ byRubro, totals }: Props) {
  return (
    <div className="overflow-x-auto rounded-lg border border-border">
      <table className="w-full text-sm">
        <thead className="bg-muted text-muted-foreground border-b border-border">
          <tr>
            <th className="px-3 py-3 text-left font-medium">Elemento</th>
            <th className="px-3 py-3 text-right font-medium">Cotizados</th>
            <th className="px-3 py-3 text-right font-medium">
              <span title="Subtotal Precio − Cotizados">Mark Up Inicial</span>
            </th>
            <th className="px-3 py-3 text-right font-medium">Subtotal Precio</th>
            <th className="px-3 py-3 text-right font-medium">Precio a cliente (F)</th>
            <th className="px-3 py-3 text-right font-medium">Costos Reales</th>
            <th className="px-3 py-3 text-right font-medium">
              <span title="Mark Up Final − Mark Up Inicial">Diferencia Total MXN</span>
            </th>
            <th className="px-3 py-3 text-right font-medium">
              <span title="Precio a cliente − Costos Reales">Mark Up Final</span>
            </th>
            <th className="px-3 py-3 text-right font-medium">
              <span title="Mark Up Inicial / Precio a cliente">Revenue Inicial %</span>
            </th>
            <th className="px-3 py-3 text-right font-medium">
              <span title="Mark Up Final / Precio a cliente">Revenue Final %</span>
            </th>
          </tr>
        </thead>
        <tbody className="divide-y divide-border bg-card">
          {byRubro.map(row => <Row key={row.rubro} row={row} />)}
        </tbody>
        <tfoot className="border-t-2 border-border">
          <Row row={totals} bold />
        </tfoot>
      </table>
    </div>
  );
}

src/components/pm/EventDetailDialog.tsx.content:
import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Label } from '@/components/ui/label';
import { Eye, ExternalLink, RefreshCw, Loader2, Link2, Unlink, X } from 'lucide-react';
import { toast } from 'sonner';
import { saveCalendarEvent, linkGroupToEvent, GetRecruitmentGroupsOutputType } from 'zite-endpoints-sdk';
import type { CalEvent } from './pmTypes';
import type { DynCols } from '../DynamicColumns';
import { EventFormFields, EventFormValues, EMPTY_EVENT_FORM, PRESET_LOCS } from './EventFormFields';

type RecGroup = GetRecruitmentGroupsOutputType['groups'][0];

const invStatusColors: Record<string, string> = {
  'Enviado': 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400',
  'Por actualizar': 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400',
  'Por crear': 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400',
  'Cancelado': 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400',
};

interface EventDetailDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  editingEvent: CalEvent | null;
  calBoardId: string;
  presetLocs?: string[];
  calDynCols: DynCols;
  recGroups: RecGroup[];
  recGroupsLoading: boolean;
  linkingGroup: boolean;
  setLinkingGroup: (v: boolean) => void;
  outlookSyncing: boolean;
  htmlPreviewOpen: boolean;
  setHtmlPreviewOpen: (v: boolean) => void;
  onOutlookSync: (action: 'create' | 'update' | 'cancel') => void;
  onRecGroupsRefresh: () => void;
  onInviteStatusChanged?: (evId: string) => void;
  onSaved: () => void;
}

export function EventDetailDialog({
  open, onOpenChange,
  editingEvent,
  calBoardId,
  presetLocs = PRESET_LOCS,
  calDynCols,
  recGroups, recGroupsLoading,
  linkingGroup, setLinkingGroup,
  outlookSyncing,
  htmlPreviewOpen, setHtmlPreviewOpen,
  onOutlookSync,
  onRecGroupsRefresh,
  onInviteStatusChanged,
  onSaved,
}: EventDetailDialogProps) {
  const [form, setForm] = useState<EventFormValues>(EMPTY_EVENT_FORM);
  const [saving, setSaving] = useState(false);

  // ── Initialize form from event + calDynCols when opening ─────────────────
  useEffect(() => {
    if (!open || !editingEvent) return;
    const ev = editingEvent;

    const colByName = (name: string, excludeType?: string) =>
      calDynCols.columns.find(c => c.columnName === name && (!excludeType || c.columnType !== excludeType));

    const getTextVal = (name: string, excludeType?: string): string => {
      const col = colByName(name, excludeType);
      return (col ? calDynCols.getCellVal(ev.id, col.id)?.textValue : undefined) ?? '';
    };

    // Native first, CellValue as fallback
    const dateCol = colByName('Fecha y hora');
    const dateVal = ev.eventDate ?? (dateCol ? calDynCols.getCellVal(ev.id, dateCol.id)?.dateValue : undefined) ?? '';

    // Native first, CellValue as fallback
    const durCol = colByName('Duración (hrs)');
    const durVal = ev.durationHours ?? (durCol ? calDynCols.getCellVal(ev.id, durCol.id)?.numberValue : undefined) ?? 1;

    // Native first, CellValue as fallback
    const locCol =
      colByName('Ubicación Interna') ??
      colByName('Ubicación (interna)') ??
      colByName('Espacio');
    const locationVal = ev.location ?? (locCol ? calDynCols.getCellVal(ev.id, locCol.id)?.textValue : undefined) ?? '';
    const isCustomLoc = !!locationVal && !presetLocs.slice(0, -1).includes(locationVal); // exclude 'Otro'

    setForm({
      eventDate: dateVal,
      durationHours: durVal,
      location: locationVal,
      locationCustom: isCustomLoc,
      inviteEmails: ev.inviteEmails ?? '',
      dinamica: getTextVal('Dinámica'),
      perfil: getTextVal('Perfil'),
      descripcion: getTextVal('Descripción'),
      detallesAdicionales: getTextVal('Detalles adicionales'),
      detallesAdicionales2: getTextVal('Detalles adicionales 2'),
      direccion: getTextVal('Ubicación', 'Select'),
      link: getTextVal('Link'),
      notes: ev.notes ?? '',
      restringirReenvio: (ev as any).restringirReenvio ?? false,
    });
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, editingEvent?.id]);

  const handleChange = (field: keyof EventFormValues, value: string | boolean | number) => {
    setForm(prev => ({ ...prev, [field]: value }));
  };

  const handleSave = async () => {
    if (!editingEvent) return;
    setSaving(true);
    try {
      const res = await saveCalendarEvent({
        id: editingEvent.id,
        eventDate: form.eventDate || undefined,
        durationHours: form.durationHours > 0 ? form.durationHours : undefined,
        location: form.location || undefined,
        inviteEmails: form.inviteEmails || undefined,
        notes: form.notes || undefined,
        dinamica: form.dinamica || undefined,
        perfil: form.perfil || undefined,
        descripcion: form.descripcion || undefined,
        detallesAdicionales: form.detallesAdicionales || undefined,
        detallesAdicionales2: form.detallesAdicionales2 || undefined,
        direccion: form.direccion || undefined,
        link: form.link || undefined,
        restringirReenvio: form.restringirReenvio,
      });
      if (res.inviteStatusChanged) onInviteStatusChanged?.(editingEvent.id);
      toast.success('Guardado ✓');
      onOpenChange(false);
      onSaved();
    } catch {
      toast.error('Error al guardar');
    }
    setSaving(false);
  };

  const linkedGroup = recGroups.find(g => g.linkedEventId === editingEvent?.id);

  return (
    <>
      <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent className="sm:max-w-lg">
          <DialogHeader>
            <DialogTitle className="truncate pr-4 text-base">{editingEvent?.eventName}</DialogTitle>
          </DialogHeader>

          <div className="space-y-0 py-1 max-h-[60vh] overflow-y-auto pr-1">
            {/* ── Form Fields ── */}
            <EventFormFields values={form} onChange={handleChange} presetLocs={presetLocs} />

            {/* ── Grupo de reclutamiento ── */}
            <div className="border-t border-border/40 pt-3 mt-3 space-y-2">
              <div className="flex items-center gap-1.5">
                <Link2 className="w-3.5 h-3.5 text-muted-foreground" />
                <Label className="text-xs font-semibold">Grupo de reclutamiento</Label>
              </div>
              {recGroupsLoading ? (
                <div className="text-xs text-muted-foreground/60 italic">Cargando grupos...</div>
              ) : linkedGroup ? (
                <div className="flex items-center gap-2 px-3 py-2 rounded-lg bg-primary/8 border border-primary/20">
                  <div className="flex-1 min-w-0">
                    <p className="text-xs font-medium text-foreground truncate">{linkedGroup.groupName}</p>
                    <p className="text-[10px] text-muted-foreground truncate">{linkedGroup.boardName}</p>
                  </div>
                  <button
                    className="flex items-center gap-1 text-xs text-muted-foreground hover:text-destructive transition-colors flex-shrink-0"
                    disabled={linkingGroup}
                    onClick={async () => {
                      if (!editingEvent) return;
                      setLinkingGroup(true);
                      try {
                        await linkGroupToEvent({
                          groupColumnId: linkedGroup.groupId,
                          recruitmentBoardId: linkedGroup.recruitmentBoardId,
                          calendarBoardId: linkedGroup.linkedCalBoardId ?? calBoardId,
                          eventId: editingEvent.id,
                          unlink: true,
                        });
                        onRecGroupsRefresh();
                        toast.success('Grupo desvinculado');
                      } catch { toast.error('Error al desvincular'); }
                      setLinkingGroup(false);
                    }}
                  >
                    <Unlink className="w-3 h-3" /> Desvincular
                  </button>
                </div>
              ) : recGroups.length === 0 ? (
                <p className="text-xs text-muted-foreground/60 italic">No hay grupos en este proyecto.</p>
              ) : (
                <Select
                  value=""
                  onValueChange={async (groupId) => {
                    if (!groupId || !editingEvent) return;
                    const group = recGroups.find(g => g.groupId === groupId);
                    if (!group) return;
                    setLinkingGroup(true);
                    try {
                      await linkGroupToEvent({
                        groupColumnId: group.groupId,
                        recruitmentBoardId: group.recruitmentBoardId,
                        calendarBoardId: calBoardId,
                        eventId: editingEvent.id,
                      });
                      onRecGroupsRefresh();
                      toast.success(`Vinculado a "${group.groupName}"`);
                    } catch { toast.error('Error al vincular'); }
                    setLinkingGroup(false);
                  }}
                >
                  <SelectTrigger className="text-sm h-8" disabled={linkingGroup}>
                    <SelectValue placeholder={linkingGroup ? 'Vinculando...' : 'Seleccionar grupo...'} />
                  </SelectTrigger>
                  <SelectContent>
                    {recGroups.map(g => (
                      <SelectItem key={g.groupId} value={g.groupId}>
                        <span className="text-muted-foreground text-xs mr-1">{g.boardName} ›</span>
                        {g.groupName}
                        {g.linkedEventId && g.linkedEventId !== editingEvent?.id && (
                          <span className="ml-1 text-[10px] text-muted-foreground/50">(vinculado)</span>
                        )}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}
            </div>

            {/* ── Outlook sync ── */}
            <div className="border-t border-border/40 pt-3 mt-3 space-y-2">
              <div className="flex items-center justify-between gap-2 flex-wrap">
                <div className="flex items-center gap-2">
                  <span className="text-xs font-medium text-muted-foreground">Outlook</span>
                  {editingEvent?.inviteStatus && (() => {
                    const cls = invStatusColors[editingEvent.inviteStatus] ?? 'bg-muted text-muted-foreground';
                    return <span className={`text-[11px] font-semibold px-2 py-0.5 rounded-full ${cls}`}>{editingEvent.inviteStatus}</span>;
                  })()}
                </div>
                <div className="flex items-center gap-2">
                  {editingEvent?.inviteBodyHtml && (
                    <button onClick={() => setHtmlPreviewOpen(true)}
                      className="text-[11px] font-medium text-primary hover:underline flex items-center gap-1">
                      <Eye className="w-3 h-3" /> Vista previa
                    </button>
                  )}
                  {editingEvent?.outlookEventLink && (
                    <a href={editingEvent.outlookEventLink} target="_blank" rel="noopener noreferrer"
                      className="inline-flex items-center gap-1 text-xs text-primary hover:underline">
                      <ExternalLink className="w-3 h-3" /> Ver en Outlook
                    </a>
                  )}
                </div>
              </div>
              <div className="flex items-center gap-2">
                <Button size="sm" variant="outline" className="h-7 text-xs gap-1.5 flex-1"
                  onClick={() => onOutlookSync(editingEvent?.outlookEventId ? 'update' : 'create')}
                  disabled={outlookSyncing}>
                  {outlookSyncing ? <Loader2 className="w-3 h-3 animate-spin" /> : <RefreshCw className="w-3 h-3" />}
                  {editingEvent?.outlookEventId ? 'Actualizar invitación' : 'Crear invitación'}
                </Button>
                {editingEvent?.outlookEventId && (
                  <Button size="sm" variant="ghost"
                    className="h-7 text-xs gap-1 text-destructive hover:text-destructive hover:bg-destructive/10"
                    onClick={() => onOutlookSync('cancel')} disabled={outlookSyncing}>
                    <X className="w-3 h-3" /> Cancelar invitación
                  </Button>
                )}
              </div>
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" size="sm" onClick={() => onOpenChange(false)} disabled={saving}>Cancelar</Button>
            <Button size="sm" onClick={handleSave} disabled={saving}>
              {saving ? <><Loader2 className="w-3.5 h-3.5 animate-spin mr-1.5" />Guardando…</> : 'Guardar'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* HTML invite preview dialog */}
      <Dialog open={htmlPreviewOpen} onOpenChange={setHtmlPreviewOpen}>
        <DialogContent className="sm:max-w-3xl h-[80vh] flex flex-col p-0 gap-0">
          <DialogHeader className="px-4 pt-4 pb-2 flex-shrink-0 border-b border-border">
            <DialogTitle className="text-sm font-semibold">Vista previa del email — {editingEvent?.eventName}</DialogTitle>
          </DialogHeader>
          <div className="flex-1 min-h-0 overflow-hidden">
            {editingEvent?.inviteBodyHtml ? (
              <iframe srcDoc={editingEvent.inviteBodyHtml} className="w-full h-full border-0"
                title="Vista previa del email de Outlook" sandbox="allow-same-origin" />
            ) : (
              <div className="flex items-center justify-center h-full text-muted-foreground text-sm">Sin contenido HTML disponible</div>
            )}
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}

