import { ExternalLink } from 'lucide-react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  fileUrl: string;
  projectName?: string;
}

export function TimelinePreviewDialog({ open, onOpenChange, fileUrl, projectName }: Props) {
  const embedUrl = fileUrl
    ? `https://view.officeapps.live.com/op/embed.aspx?src=${encodeURIComponent(fileUrl)}`
    : '';

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-6xl h-[85vh] flex flex-col p-0 gap-0">
        <DialogHeader className="flex flex-row items-center justify-between px-5 py-3 border-b border-border/50 flex-shrink-0">
          <DialogTitle className="text-sm font-semibold">
            Timeline — {projectName || 'Proyecto'}
          </DialogTitle>
          {fileUrl && (
            <Button
              size="sm"
              variant="outline"
              className="gap-1.5 h-7 text-xs flex-shrink-0"
              onClick={() => window.open(fileUrl, '_blank')}
            >
              <ExternalLink className="w-3.5 h-3.5" />
              Abrir en nueva pestaña
            </Button>
          )}
        </DialogHeader>

        <div className="flex-1 min-h-0">
          {fileUrl ? (
            <iframe
              src={embedUrl}
              className="w-full h-full border-0"
              title={`Timeline ${projectName || ''}`}
              allowFullScreen
            />
          ) : (
            <div className="flex items-center justify-center h-full text-muted-foreground text-sm">
              No hay archivo disponible
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

src/components/admin/CotizacionesTab.tsx.content:
import { useState, useEffect, useMemo, useCallback } from 'react';
import { getCotizacionesAdmin, saveCotizacion, importCotizacionesFromCsv } from 'zite-endpoints-sdk';
import type { GetCotizacionesAdminOutputType } from 'zite-endpoints-sdk';
import { uploadFile } from 'zite-file-upload-sdk';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Skeleton } from '@/components/ui/skeleton';
import { Switch } from '@/components/ui/switch';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { toast } from 'sonner';
import { Link2, RefreshCw, Search, ExternalLink, UploadCloud, FileSpreadsheet, X } from 'lucide-react';

type Cotizacion = GetCotizacionesAdminOutputType['cotizaciones'][0];
type Deal = GetCotizacionesAdminOutputType['dealsList'][0];

const fmt = (v: number | null) =>
  v == null ? '—' : new Intl.NumberFormat('es-MX', { style: 'currency', currency: 'MXN', maximumFractionDigits: 0 }).format(v);

// ── Row ───────────────────────────────────────────────────────────────────────

function CotizRow({ cotiz, deals, onLinked, onToggleIncluded }: {
  cotiz: Cotizacion;
  deals: Deal[];
  onLinked: (cotizId: string, dealId: string) => void;
  onToggleIncluded: (id: string, val: boolean) => Promise<void>;
}) {
  const [selectedDealId, setSelectedDealId] = useState('');
  const [linking, setLinking] = useState(false);
  const [toggling, setToggling] = useState(false);

  const handleLink = async () => {
    if (!selectedDealId) return;
    setLinking(true);
    try {
      await saveCotizacion({ id: cotiz.id, deal: [selectedDealId] });
      toast.success('Cotización vinculada');
      onLinked(cotiz.id, selectedDealId);
    } catch {
      toast.error('Error al vincular');
    } finally {
      setLinking(false);
    }
  };

  return (
    <tr className="border-b border-border hover:bg-muted/30 transition-colors">
      <td className="px-4 py-3 text-sm font-medium text-foreground max-w-xs truncate">
        {cotiz.cotizacionName || <span className="text-muted-foreground italic">Sin nombre</span>}
      </td>
      <td className="px-4 py-3 text-sm text-muted-foreground">{cotiz.currency}</td>
      <td className="px-4 py-3 text-sm text-right tabular-nums">{fmt(cotiz.totalCost)}</td>
      <td className="px-4 py-3 text-sm text-right tabular-nums font-medium">{fmt(cotiz.clientPrice)}</td>
      <td className="px-4 py-3">
        {cotiz.dealName ? (
          <span className="text-sm text-foreground">{cotiz.dealName}</span>
        ) : (
          <div className="flex items-center gap-2 flex-wrap">
            <Badge variant="secondary" className="text-xs shrink-0">Sin deal</Badge>
            <Select value={selectedDealId} onValueChange={setSelectedDealId}>
              <SelectTrigger className="h-7 text-xs w-44">
                <SelectValue placeholder="Elegir deal..." />
              </SelectTrigger>
              <SelectContent>
                {deals.map(d => (
                  <SelectItem key={d.id} value={d.id}>{d.dealName}</SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Button
              size="sm" variant="outline"
              className="h-7 text-xs gap-1 shrink-0"
              disabled={!selectedDealId || linking}
              onClick={handleLink}
            >
              <Link2 className="w-3 h-3" />
              {linking ? 'Vinculando...' : 'Vincular'}
            </Button>
          </div>
        )}
      </td>
      <td className="px-4 py-3">
        <Badge variant={cotiz.status === 'Aprobada' ? 'default' : 'secondary'} className="text-xs">
          {cotiz.status}
        </Badge>
      </td>
      <td className="px-4 py-3">
        <Switch
          checked={cotiz.included}
          disabled={toggling}
          onCheckedChange={async (val) => {
            setToggling(true);
            try { await onToggleIncluded(cotiz.id, val); }
            finally { setToggling(false); }
          }}
        />
      </td>
    </tr>
  );
}

// ── Drag & drop import panel ──────────────────────────────────────────────────

function ImportPanel({ onDone }: { onDone: () => void }) {
  const [isDragging, setIsDragging] = useState(false);
  const [file, setFile] = useState<File | null>(null);
  const [currency, setCurrency] = useState('MXN');
  const [uploading, setUploading] = useState(false);
  const [result, setResult] = useState<{
    totalCotizaciones: number; matchedCount: number;
    unmatchedNames: string[]; totalLineItems: number;
  } | null>(null);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const dropped = e.dataTransfer.files[0];
    if (dropped) setFile(dropped);
  }, []);

  const handleImport = async () => {
    if (!file) { toast.error('Selecciona un archivo primero'); return; }
    setUploading(true);
    setResult(null);
    try {
      const { fileUrl } = await uploadFile({ data: file, filename: file.name });
      const res = await importCotizacionesFromCsv({ csvUrl: fileUrl, currency });
      setResult(res);
      toast.success(`Importadas ${res.totalCotizaciones} cotizaciones (${res.matchedCount} con deal)`);
      onDone();
    } catch (e: unknown) {
      toast.error(e instanceof Error ? e.message : 'Error al importar');
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="rounded-xl border border-border bg-card p-5 space-y-4 max-w-2xl">
      <div className="flex items-center justify-between">
        <p className="text-sm font-semibold text-foreground">Importar cotizaciones</p>
        <Select value={currency} onValueChange={setCurrency}>
          <SelectTrigger className="w-24 h-8 text-xs">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="MXN">MXN</SelectItem>
            <SelectItem value="USD">USD</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {/* Drop zone */}
      <label
        htmlFor="cotiz-file-input"
        onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
        onDragLeave={() => setIsDragging(false)}
        onDrop={handleDrop}
        className={`flex flex-col items-center justify-center gap-3 border-2 border-dashed rounded-xl p-10 text-center cursor-pointer transition-all select-none ${
          isDragging
            ? 'border-primary bg-primary/5 scale-[1.01]'
            : file
            ? 'border-green-500/60 bg-green-500/5'
            : 'border-border hover:border-primary/50 hover:bg-muted/30'
        }`}
      >
        <input
          id="cotiz-file-input"
          type="file"
          accept=".csv,.xlsx"
          className="hidden"
          onChange={(e) => { const f = e.target.files?.[0]; if (f) setFile(f); }}
        />
        {file ? (
          <div className="flex items-center gap-3">
            <FileSpreadsheet className="w-8 h-8 text-green-600 shrink-0" />
            <div className="text-left">
              <p className="text-sm font-medium text-foreground">{file.name}</p>
              <p className="text-xs text-muted-foreground">{(file.size / 1024).toFixed(1)} KB</p>
            </div>
            <button
              type="button"
              className="ml-2 p-1 rounded hover:bg-muted text-muted-foreground hover:text-destructive transition-colors"
              onClick={(e) => { e.preventDefault(); setFile(null); setResult(null); }}
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        ) : (
          <>
            <UploadCloud className={`w-10 h-10 transition-colors ${isDragging ? 'text-primary' : 'text-muted-foreground/40'}`} />
            <div>
              <p className="text-sm font-medium text-foreground">
                {isDragging ? 'Suelta el archivo aquí' : 'Arrastra un archivo o haz clic para seleccionar'}
              </p>
              <p className="text-xs text-muted-foreground mt-1">.csv · .xlsx · máx. 25 MB</p>
            </div>
          </>
        )}
      </label>

      <div className="flex items-center gap-3 flex-wrap">
        <Button size="sm" disabled={!file || uploading} onClick={handleImport} className="gap-2">
          {uploading ? <RefreshCw className="w-4 h-4 animate-spin" /> : <UploadCloud className="w-4 h-4" />}
          {uploading ? 'Importando...' : 'Importar'}
        </Button>
        {result && (
          <p className="text-xs text-muted-foreground">
            ✅ {result.totalCotizaciones} cotizaciones · {result.totalLineItems} items · {result.matchedCount} con deal
            {result.unmatchedNames.length > 0 && (
              <span className="text-amber-600 ml-1">· ⚠️ {result.unmatchedNames.length} sin deal</span>
            )}
          </p>
        )}
      </div>
    </div>
  );
}

// ── Main tab ──────────────────────────────────────────────────────────────────

export default function CotizacionesTab() {
  const [data, setData] = useState<GetCotizacionesAdminOutputType | null>(null);
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState<'all' | 'sin-deal' | 'con-deal'>('all');
  const [search, setSearch] = useState('');
  const [showImport, setShowImport] = useState(false);

  const load = async () => {
    setLoading(true);
    try {
      const res = await getCotizacionesAdmin({});
      setData(res);
    } catch { toast.error('Error al cargar cotizaciones'); }
    finally { setLoading(false); }
  };

  useEffect(() => { load(); }, []);

  const handleToggleIncluded = async (id: string, val: boolean) => {
    await saveCotizacion({ id, included: val });
    setData(prev => prev ? {
      ...prev,
      cotizaciones: prev.cotizaciones.map(c => c.id === id ? { ...c, included: val } : c),
    } : prev);
  };

  const filtered = useMemo(() => {
    if (!data) return [];
    let list = data.cotizaciones;
    if (tab === 'sin-deal') list = list.filter(c => !c.dealId);
    if (tab === 'con-deal') list = list.filter(c => !!c.dealId);
    if (search.trim()) {
      const q = search.toLowerCase();
      list = list.filter(c =>
        c.cotizacionName?.toLowerCase().includes(q) ||
        c.dealName?.toLowerCase().includes(q)
      );
    }
    return list;
  }, [data, tab, search]);

  const sinDealCount = data?.cotizaciones.filter(c => !c.dealId).length ?? 0;

  return (
    <div className="space-y-5">
      {/* Toolbar */}
      <div className="flex items-center justify-between gap-4 flex-wrap">
        <p className="text-sm text-muted-foreground">
          Gestión y vinculación de cotizaciones a deals
        </p>
        <div className="flex items-center gap-2">
          <Button variant="outline" size="sm" onClick={() => setShowImport(v => !v)} className="gap-2">
            <UploadCloud className="w-4 h-4" />
            {showImport ? 'Ocultar importador' : 'Importar archivo'}
          </Button>
          <Button variant="outline" size="sm" onClick={load} disabled={loading} className="gap-2">
            <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
            Actualizar
          </Button>
        </div>
      </div>

      {showImport && <ImportPanel onDone={() => { setShowImport(false); load(); }} />}

      {/* Filters */}
      <div className="flex items-center gap-3 flex-wrap">
        <Tabs value={tab} onValueChange={v => setTab(v as typeof tab)}>
          <TabsList>
            <TabsTrigger value="all">Todas {data && `(${data.cotizaciones.length})`}</TabsTrigger>
            <TabsTrigger value="sin-deal">
              Sin deal
              {sinDealCount > 0 && (
                <Badge variant="destructive" className="ml-1.5 text-xs px-1.5 py-0">{sinDealCount}</Badge>
              )}
            </TabsTrigger>
            <TabsTrigger value="con-deal">Con deal</TabsTrigger>
          </TabsList>
        </Tabs>
        <div className="relative flex-1 min-w-52 max-w-72">
          <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground" />
          <Input
            className="pl-8 h-9 text-sm"
            placeholder="Buscar cotización o deal..."
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>
      </div>

      {/* Table */}
      <div className="rounded-lg border border-border overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm min-w-[820px]">
            <thead className="bg-muted/50 text-muted-foreground border-b border-border">
              <tr>
                <th className="px-4 py-3 text-left font-medium">Nombre</th>
                <th className="px-4 py-3 text-left font-medium">Moneda</th>
                <th className="px-4 py-3 text-right font-medium">Costo Total</th>
                <th className="px-4 py-3 text-right font-medium">P. Cliente</th>
                <th className="px-4 py-3 text-left font-medium">Deal vinculado</th>
                <th className="px-4 py-3 text-left font-medium">Status</th>
                <th className="px-4 py-3 text-left font-medium">Incluida</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border bg-card">
              {loading ? (
                [...Array(8)].map((_, i) => (
                  <tr key={i}>
                    <td colSpan={7} className="px-4 py-3"><Skeleton className="h-5 w-full" /></td>
                  </tr>
                ))
              ) : filtered.length === 0 ? (
                <tr>
                  <td colSpan={7} className="px-4 py-16 text-center text-muted-foreground text-sm">
                    <ExternalLink className="w-8 h-8 mx-auto mb-2 opacity-20" />
                    No hay cotizaciones que mostrar
                  </td>
                </tr>
              ) : (
                filtered.map(c => (
                  <CotizRow
                    key={c.id}
                    cotiz={c}
                    deals={data?.dealsList ?? []}
                    onLinked={(cotizId, dealId) => {
                      const deal = data?.dealsList.find(d => d.id === dealId);
                      setData(prev => prev ? {
                        ...prev,
                        cotizaciones: prev.cotizaciones.map(c =>
                          c.id === cotizId ? { ...c, dealId, dealName: deal?.dealName ?? '' } : c
                        ),
                      } : prev);
                    }}
                    onToggleIncluded={handleToggleIncluded}
                  />
                ))
              )}
            </tbody>
          </table>
        </div>
        {!loading && filtered.length > 0 && (
          <div className="px-4 py-2 bg-muted/30 border-t border-border text-xs text-muted-foreground">
            {filtered.length} cotizaciones
          </div>
        )}
      </div>
    </div>
  );
}

src/components/commercial/DealKanban.tsx.content:
import { useRef } from 'react';
import { GetDealsOutputType } from 'zite-endpoints-sdk';
import DealCard from './DealCard';
import { PHASES } from './dealUtils';
import { Plus } from 'lucide-react';
import { Button } from '@/components/ui/button';

type Deal = GetDealsOutputType['deals'][0];

interface Props {
  deals: Deal[];
  onDealClick: (deal: Deal) => void;
  onStatusChange: (dealId: string, newPhase: string) => void;
  onNewDeal: (phase: string) => void;
}

export default function DealKanban({ deals, onDealClick, onStatusChange, onNewDeal }: Props) {
  const dragId = useRef<string | null>(null);

  return (
    <div className="flex gap-3 overflow-x-auto pb-4 -mx-1 px-1">
      {PHASES.map(phase => {
        const phaseDeals = deals.filter(d => (d.phase ?? 'Prospecto') === phase.key);
        return (
          <div
            key={phase.key}
            className="flex-shrink-0 w-56 flex flex-col"
            onDragOver={e => e.preventDefault()}
            onDrop={() => {
              if (dragId.current) onStatusChange(dragId.current, phase.key);
              dragId.current = null;
            }}
          >
            {/* Column header */}
            <div className="flex items-center gap-2 mb-2 px-1">
              <div className="w-2.5 h-2.5 rounded-full flex-shrink-0" style={{ backgroundColor: phase.color }} />
              <span className="text-xs font-semibold text-muted-foreground uppercase tracking-wider truncate">
                {phase.key}
              </span>
              <span className="ml-auto text-xs text-muted-foreground bg-muted rounded-full px-1.5 py-0.5">
                {phaseDeals.length}
              </span>
            </div>

            {/* Cards area */}
            <div
              className="flex-1 min-h-24 bg-muted/30 rounded-xl p-2 space-y-2"
              style={{ borderTop: `2px solid ${phase.color}` }}
            >
              {phaseDeals.map(deal => (
                <DealCard
                  key={deal.id}
                  deal={deal}
                  onClick={() => onDealClick(deal)}
                  onDragStart={() => { dragId.current = deal.id; }}
                />
              ))}
              <Button
                variant="ghost"
                size="sm"
                className="w-full text-xs text-muted-foreground h-7 gap-1 opacity-60 hover:opacity-100"
                onClick={() => onNewDeal(phase.key)}
              >
                <Plus className="w-3 h-3" /> Agregar
              </Button>
            </div>
          </div>
        );
      })}
    </div>
  );
}

src/components/commercial/ResumenTab.tsx.content:
import { useState, useEffect } from 'react';
import { GetDealsOutputType, getCotizaciones, GetCotizacionesOutputType, getCotizacionLineItems } from 'zite-endpoints-sdk';
import { Skeleton } from '@/components/ui/skeleton';
import { CheckCircle2, TrendingUp } from 'lucide-react';
import { RUBROS, COTIZ_STATUS_COLORS, getCurrencySymbol, fmtMoneyFull } from './dealUtils';

type Deal = GetDealsOutputType['deals'][0];
type Cotizacion = GetCotizacionesOutputType['cotizaciones'][0];

export default function ResumenTab({ deal }: { deal: Deal }) {
  const [cotizaciones, setCotizaciones] = useState<Cotizacion[]>([]);
  const [rubroTotals, setRubroTotals] = useState<Record<string, number>>({});
  const [loading, setLoading] = useState(true);

  const sym = getCurrencySymbol(deal.currency);
  const fmt = (n?: number) => fmtMoneyFull(n, sym);

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      try {
        const data = await getCotizaciones({ dealId: deal.id });
        setCotizaciones(data.cotizaciones);
        const approved = data.cotizaciones.find(c => c.status === 'Aprobada');
        if (approved) {
          const liData = await getCotizacionLineItems({ cotizacionId: approved.id });
          const totals: Record<string, number> = {};
          liData.lineItems.forEach(li => {
            const r = li.rubro ?? 'Otro';
            totals[r] = (totals[r] ?? 0) + (li.finalPrice ?? 0);
          });
          setRubroTotals(totals);
        }
      } finally { setLoading(false); }
    };
    load();
  }, [deal.id]);

  if (loading) return <Skeleton className="h-60 w-full" />;

  const approved = cotizaciones.find(c => c.status === 'Aprobada');

  return (
    <div className="space-y-5">
      {/* Cotizaciones list */}
      <div>
        <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wide mb-2">Cotizaciones</h4>
        <div className="space-y-1.5">
          {cotizaciones.map(c => {
            const color = COTIZ_STATUS_COLORS[c.status ?? ''] ?? 'hsl(var(--muted-foreground))';
            const csym = getCurrencySymbol(c.currency ?? deal.currency);
            return (
              <div key={c.id} className={`flex items-center justify-between px-3 py-2 rounded-lg text-sm ${c.status === 'Aprobada' ? 'bg-primary/10 border border-primary/20' : 'bg-muted/30'}`}>
                <div className="flex items-center gap-2">
                  {c.status === 'Aprobada' && <CheckCircle2 className="w-3.5 h-3.5" style={{ color: 'hsl(var(--chart-2))' }} />}
                  <span className="font-medium">{c.cotizacionName || 'Sin nombre'}</span>
                  <span className="text-xs px-1.5 py-0.5 rounded-full" style={{ color, backgroundColor: color + '20' }}>{c.status}</span>
                </div>
                <span className="font-semibold">{fmtMoneyFull(c.totalCost, csym)}</span>
              </div>
            );
          })}
          {cotizaciones.length === 0 && <p className="text-sm text-muted-foreground py-2">Sin cotizaciones.</p>}
        </div>
      </div>

      {/* Rubro breakdown */}
      {approved && (
        <div>
          <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wide mb-2">
            Desglose por rubro — {approved.cotizacionName}
          </h4>
          <div className="space-y-1.5">
            {RUBROS.map(rubro => (
              <div key={rubro} className="flex items-center justify-between text-sm px-1">
                <span className="text-muted-foreground">{rubro}</span>
                <span className="font-medium">{rubroTotals[rubro] != null ? fmtMoneyFull(rubroTotals[rubro], sym) : '—'}</span>
              </div>
            ))}
            <div className="flex items-center justify-between font-semibold pt-2 border-t text-sm px-1">
              <span>Total costo</span><span>{fmt(approved.totalCost)}</span>
            </div>
          </div>
        </div>
      )}

      {/* Deal financials */}
      <div className="bg-muted/30 rounded-xl p-4 space-y-2">
        <div className="flex items-center gap-2 mb-3">
          <TrendingUp className="w-4 h-4 text-primary" />
          <h4 className="text-sm font-semibold">Resumen financiero del deal</h4>
        </div>
        <Row label="Precio a cliente" value={fmt(deal.clientPrice)} />
        {deal.taxesPct != null && deal.clientPrice != null && <>
          <Row label={`Impuestos (${deal.taxesPct}%)`} value={fmt(deal.clientPrice * deal.taxesPct / 100)} />
          <div className="border-t pt-2">
            <Row label="Total con impuestos" value={fmt(deal.clientPrice * (1 + deal.taxesPct / 100))} bold />
          </div>
        </>}
        {approved?.clientPrice != null && <Row label="Precio cotización aprobada" value={fmt(approved.clientPrice)} />}
      </div>
    </div>
  );
}

function Row({ label, value, bold = false }: { label: string; value: string; bold?: boolean }) {
  return (
    <div className={`flex items-center justify-between text-sm ${bold ? 'font-semibold' : ''}`}>
      <span className={bold ? '' : 'text-muted-foreground'}>{label}</span>
      <span>{value}</span>
    </div>
  );
}

src/components/dashboard/widgetConfig.ts.content:
export type WidgetSize = 'half' | 'full';
export type LayoutItem = { id: string; size: WidgetSize };

export type WidgetConfig = {
  id: string;
  label: string;
  defaultSize: WidgetSize;
  allowedSizes: WidgetSize[];
  accentColor: string;
};

export const WIDGET_REGISTRY: WidgetConfig[] = [
  {
    id: 'my_projects',
    label: 'Mis proyectos',
    defaultSize: 'half',
    allowedSizes: ['half', 'full'],
    accentColor: 'bg-[hsl(var(--chart-4))]',
  },
  {
    id: 'my_tasks',
    label: 'Mis tareas',
    defaultSize: 'full',
    allowedSizes: ['half', 'full'],
    accentColor: 'bg-primary',
  },
  {
    id: 'upcoming_events',
    label: 'Próximos eventos',
    defaultSize: 'half',
    allowedSizes: ['half', 'full'],
    accentColor: 'bg-secondary',
  },
  {
    id: 'purchase_orders',
    label: 'Órdenes de compra',
    defaultSize: 'full',
    allowedSizes: ['half', 'full'],
    accentColor: 'bg-[hsl(var(--chart-3))]',
  },
  {
    id: 'recent_mentions',
    label: 'Menciones recientes',
    defaultSize: 'half',
    allowedSizes: ['half', 'full'],
    accentColor: 'bg-[hsl(var(--chart-1))]',
  },
  {
    id: 'received_invoices',
    label: 'Facturas recibidas',
    defaultSize: 'half',
    allowedSizes: ['half', 'full'],
    accentColor: 'bg-[hsl(var(--chart-5))]',
  },
];

export const WIDGET_LABEL_TO_ID: Record<string, string> = {
  'Mis proyectos': 'my_projects',
  'Mis tareas': 'my_tasks',
  'Próximos eventos': 'upcoming_events',
  'Órdenes de compra': 'purchase_orders',
  'Menciones recientes': 'recent_mentions',
  'Facturas recibidas': 'received_invoices',
};

export const WIDGET_ID_TO_LABEL: Record<string, string> = Object.fromEntries(
  Object.entries(WIDGET_LABEL_TO_ID).map(([k, v]) => [v, k])
);

/**
 * Builds the final ordered layout for a user.
 * - If enabledLabels is empty → show all widgets (showAll pattern)
 * - Respects saved order and sizes from savedLayoutJson
 * - Falls back to defaultSize for invalid/missing sizes
 * - Appends newly enabled widgets at the end in registry order
 */
export function buildLayout(enabledLabels: string[], savedLayoutJson?: string): LayoutItem[] {
  // Determine enabled widget IDs
  let enabledIds: Set<string>;
  if (enabledLabels.length === 0) {
    enabledIds = new Set(WIDGET_REGISTRY.map(w => w.id));
  } else {
    enabledIds = new Set(
      enabledLabels
        .map(l => WIDGET_LABEL_TO_ID[l])
        .filter((id): id is string => !!id)
    );
  }

  // Parse saved layout defensively
  let saved: LayoutItem[] = [];
  if (savedLayoutJson) {
    try {
      const parsed = JSON.parse(savedLayoutJson);
      if (Array.isArray(parsed)) {
        saved = parsed.filter(
          (item): item is LayoutItem =>
            !!item &&
            typeof item.id === 'string' &&
            (item.size === 'half' || item.size === 'full')
        );
      }
    } catch {
      // ignore invalid JSON — use default
    }
  }

  const result: LayoutItem[] = [];
  const seenIds = new Set<string>();

  // Start with saved items that are still enabled
  for (const item of saved) {
    if (!enabledIds.has(item.id) || seenIds.has(item.id)) continue;
    const config = WIDGET_REGISTRY.find(w => w.id === item.id);
    if (!config) continue;
    const size: WidgetSize = config.allowedSizes.includes(item.size)
      ? item.size
      : config.defaultSize;
    result.push({ id: item.id, size });
    seenIds.add(item.id);
  }

  // Append enabled widgets not present in saved layout (maintain registry order)
  for (const config of WIDGET_REGISTRY) {
    if (enabledIds.has(config.id) && !seenIds.has(config.id)) {
      result.push({ id: config.id, size: config.defaultSize });
    }
  }

  return result;
}

src/components/purchases/POFormSheet.tsx.content:
import { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import SearchableSelect from '@/components/SearchableSelect';
import { CATEGORIES } from '../../lib/constants';
import { Trash2, Plus, AlertTriangle, Send } from 'lucide-react';
import { savePurchaseOrder, submitPurchaseOrder, getPoLineItems, GetPurchaseOrdersOutputType } from 'zite-endpoints-sdk';
import { toast } from 'sonner';
import { useProject } from '@/context/ProjectContext';

type PO = GetPurchaseOrdersOutputType['pos'][0];
type Supplier = GetPurchaseOrdersOutputType['suppliers'][0];
type BillingEntity = GetPurchaseOrdersOutputType['billingEntities'][0];

interface LineItem { id?: string; description: string; category: string; quantity: number; unitPrice: number; total: number; }



function newLine(): LineItem { return { description: '', category: '', quantity: 0, unitPrice: 0, total: 0 }; }
const fmtNum = (n: number) => n.toLocaleString('es-MX', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

function detectsAnticipo(form: FormState): boolean {
  const haystack = [form.serviceDescription, form.notes, form.supplierName].join(' ').toLowerCase();
  return haystack.includes('anticipo') && form.orderType !== 'Anticipo';
}

type FormState = {
  projectCode: string; supplierName: string; issueDate: string; category: string;
  paymentTerms: string; currency: string; notes: string;
  serviceDescription: string; billingEntity: string; orderType: string;
};

interface Props {
  open: boolean; onClose: () => void; onSaved: () => void;
  po: PO | null; suppliers: Supplier[]; userCostCenters: string[];
  billingEntities: BillingEntity[];
}

export default function POFormSheet({ open, onClose, onSaved, po, suppliers, userCostCenters, billingEntities }: Props) {
  const { projects } = useProject();
  const [saving, setSaving] = useState(false);
  const [savingAndSubmitting, setSavingAndSubmitting] = useState(false);
  const [lineItems, setLineItems] = useState<LineItem[]>([newLine()]);
  const [deletedIds, setDeletedIds] = useState<string[]>([]);
  const [anticipoWarn, setAnticipo] = useState(false);
  const [form, setForm] = useState<FormState>({
    projectCode: '', supplierName: '', issueDate: '', category: '',
    paymentTerms: '', currency: 'MXN', notes: '',
    serviceDescription: '', billingEntity: '', orderType: 'Normal',
  });

  useEffect(() => {
    if (!open) return;
    const defaultCat = userCostCenters.length === 1 ? userCostCenters[0] : '';
    if (po) {
      setForm({
        projectCode: po.projectCode ?? '', supplierName: po.supplierName ?? '',
        issueDate: po.issueDate ?? '', category: po.category ?? '',
        paymentTerms: po.paymentTerms ?? '', currency: po.currency ?? 'MXN',
        notes: po.notes ?? '', serviceDescription: po.serviceDescription ?? '',
        billingEntity: po.billingEntity ?? '', orderType: po.orderType ?? 'Normal',
      });
      getPoLineItems({ poId: po.id })
        .then(d => setLineItems(d.lineItems.length > 0 ? d.lineItems : [newLine()]))
        .catch(() => setLineItems([newLine()]));
    } else {
      setForm({
        projectCode: '', supplierName: '', issueDate: new Date().toISOString().split('T')[0],
        category: defaultCat, paymentTerms: '', currency: 'MXN', notes: '',
        serviceDescription: '', billingEntity: '', orderType: 'Normal',
      });
      setLineItems([newLine()]);
    }
    setDeletedIds([]);
  }, [open, po?.id]);

  const updateLine = (i: number, field: keyof LineItem, value: string | number) => {
    setLineItems(prev => prev.map((l, idx) => {
      if (idx !== i) return l;
      const updated = { ...l, [field]: value };
      if (field === 'quantity' || field === 'unitPrice') updated.total = Number(updated.quantity) * Number(updated.unitPrice);
      return updated;
    }));
  };

  const removeLine = (i: number) => {
    const item = lineItems[i];
    if (item.id) setDeletedIds(d => [...d, item.id!]);
    setLineItems(prev => prev.filter((_, idx) => idx !== i));
  };

  const total = lineItems.reduce((s, l) => s + (l.total || 0), 0);

  const doSave = async (andSubmit = false) => {
    if (andSubmit) setSavingAndSubmitting(true); else setSaving(true);
    try {
      const result = await savePurchaseOrder({ id: po?.id, ...form, totalAmount: total, lineItems, deletedLineItemIds: deletedIds });
      if (andSubmit && result?.id) {
        await submitPurchaseOrder({ id: result.id });
        toast.success('OC creada y enviada a aprobación');
      } else {
        toast.success(po ? 'OC actualizada' : 'OC guardada como borrador');
      }
      onSaved(); onClose();
    } catch (e: unknown) { toast.error((e as Error).message ?? 'Error al guardar la OC'); }
    if (andSubmit) setSavingAndSubmitting(false); else setSaving(false);
  };

  const [pendingSubmit, setPendingSubmit] = useState(false);

  const handleSave = (andSubmit = false) => {
    if (detectsAnticipo(form)) { setPendingSubmit(andSubmit); setAnticipo(true); return; }
    doSave(andSubmit);
  };

  const handleFixAndSave = () => {
    setAnticipo(false);
    setForm(f => ({ ...f, orderType: 'Anticipo' }));
    setTimeout(() => doSave(pendingSubmit), 0);
  };

  const allowedCats = userCostCenters.length > 0 ? userCostCenters : CATEGORIES;
  const showBanner = detectsAnticipo(form);

  return (
    <>
      <Dialog open={open} onOpenChange={v => { if (!v) onClose(); }}>
        <DialogContent className="max-w-4xl w-full p-0 gap-0 flex flex-col max-h-[90vh]" onInteractOutside={e => e.preventDefault()}>
          <DialogHeader className="px-6 py-4 border-b flex-shrink-0">
            <DialogTitle className="text-base">{po ? `Editar OC #${po.poNumber}` : 'Nueva Orden de Compra'}</DialogTitle>
          </DialogHeader>

          <div className="flex-1 min-h-0 overflow-y-auto">
            <div className="px-6 py-5 space-y-5">

              {showBanner && (
                <div className="flex items-start gap-2.5 px-4 py-3 rounded-lg bg-orange-50 border border-orange-300 dark:bg-orange-950/40 dark:border-orange-700 text-orange-800 dark:text-orange-300">
                  <AlertTriangle className="w-4 h-4 shrink-0 mt-0.5" />
                  <div className="text-sm leading-snug">
                    <span className="font-semibold">¿Es un anticipo?</span> Detectamos la palabra "anticipo" en la descripción o notas,
                    pero el <span className="font-semibold">Tipo de OC</span> está como <span className="font-semibold">"{form.orderType}"</span>.
                    {' '}Cambia el tipo a <button className="underline font-semibold hover:opacity-70 transition-opacity" onClick={() => setForm(f => ({ ...f, orderType: 'Anticipo' }))}>Anticipo</button> si corresponde.
                  </div>
                </div>
              )}

              {po && (
                <div className="flex items-center gap-2 px-3 py-2 rounded-lg bg-muted/50 border border-border">
                  <AlertTriangle className="w-3.5 h-3.5 text-amber-500" />
                  <p className="text-xs text-muted-foreground">
                    Solo se pueden editar OCs en estatus <strong>Borrador</strong>. El estatus se cambia mediante el flujo de aprobación.
                  </p>
                </div>
              )}

              <div className="grid grid-cols-3 gap-4">
                <div className="space-y-1.5">
                  <Label className="text-xs font-medium">Proveedor</Label>
                  <SearchableSelect
                    value={form.supplierName}
                    onChange={v => setForm(f => ({ ...f, supplierName: v }))}
                    options={suppliers.map(s => ({ value: s.supplierName, label: s.supplierName }))}
                    placeholder="Seleccionar..."
                    className="w-full h-9 text-sm min-w-0 max-w-none"
                  />
                </div>
                <div className="space-y-1.5">
                  <Label className="text-xs font-medium">Proyecto</Label>
                  <SearchableSelect
                    value={form.projectCode || '__none__'}
                    onChange={v => setForm(f => ({ ...f, projectCode: v === '__none__' ? '' : v }))}
                    options={[{ value: '__none__', label: 'Sin proyecto' }, ...projects.map(p => ({ value: p.projectCode ?? '', label: p.projectCode ?? '', sub: p.fullName ?? '' }))]}
                    placeholder="Sin proyecto"
                    className="w-full h-9 text-sm min-w-0 max-w-none"
                  />
                </div>
                <div className="space-y-1.5">
                  <Label className="text-xs font-medium">Rubro / Centro de costos</Label>
                  <Select value={form.category} onValueChange={v => setForm(f => ({ ...f, category: v }))}>
                    <SelectTrigger className="h-9 text-sm"><SelectValue placeholder="Seleccionar..." /></SelectTrigger>
                    <SelectContent>{allowedCats.map(c => <SelectItem key={c} value={c}>{c}</SelectItem>)}</SelectContent>
                  </Select>
                </div>
                <div className="space-y-1.5">
                  <Label className="text-xs font-medium">Fecha de emisión</Label>
                  <Input type="date" className="h-9 text-sm" value={form.issueDate} onChange={e => setForm(f => ({ ...f, issueDate: e.target.value }))} />
                </div>
                <div className="space-y-1.5">
                  <Label className="text-xs font-medium">Moneda</Label>
                  <Select value={form.currency} onValueChange={v => setForm(f => ({ ...f, currency: v }))}>
                    <SelectTrigger className="h-9 text-sm"><SelectValue /></SelectTrigger>
                    <SelectContent><SelectItem value="MXN">MXN</SelectItem><SelectItem value="USD">USD</SelectItem></SelectContent>
                  </Select>
                </div>
                <div className="space-y-1.5">
                  <Label className="text-xs font-medium">Condiciones de pago</Label>
                  <Input className="h-9 text-sm" placeholder="Ej: 30 días, Contado..." value={form.paymentTerms} onChange={e => setForm(f => ({ ...f, paymentTerms: e.target.value }))} />
                </div>
                <div className="space-y-1.5">
                  <Label className="text-xs font-medium">Tipo de OC</Label>
                  <Select value={form.orderType} onValueChange={v => setForm(f => ({ ...f, orderType: v }))}>
                    <SelectTrigger className={`h-9 text-sm ${showBanner ? 'border-orange-400 ring-1 ring-orange-300' : ''}`}><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="Normal">Normal</SelectItem>
                      <SelectItem value="Anticipo">Anticipo</SelectItem>
                      <SelectItem value="Cierre">Cierre</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-1.5 col-span-2">
                  <Label className="text-xs font-medium">Facturar a</Label>
                  <Select value={form.billingEntity} onValueChange={v => setForm(f => ({ ...f, billingEntity: v }))}>
                    <SelectTrigger className="h-9 text-sm"><SelectValue placeholder="Seleccionar entidad..." /></SelectTrigger>
                    <SelectContent>
                      {billingEntities.map(b => (
                        <SelectItem key={b.id} value={b.companyName}>
                          <span>{b.companyName}</span>
                          {b.rfc && <span className="text-muted-foreground ml-1.5 text-xs">· {b.rfc}</span>}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="space-y-1.5">
                <Label className="text-xs font-medium">Servicio / Descripción</Label>
                <Textarea className="text-sm resize-none" rows={2} value={form.serviceDescription} onChange={e => setForm(f => ({ ...f, serviceDescription: e.target.value }))} placeholder="Ej: Pago de incentivos a 20 participantes..." />
              </div>

              <div className="space-y-1.5">
                <Label className="text-xs font-medium">Notas internas</Label>
                <Textarea className="text-sm resize-none" rows={2} value={form.notes} onChange={e => setForm(f => ({ ...f, notes: e.target.value }))} placeholder="Notas opcionales..." />
              </div>

              {/* Line items */}
              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <Label className="text-xs font-medium">Líneas de detalle</Label>
                  <Button variant="ghost" size="sm" className="h-7 text-xs gap-1 text-primary" onClick={() => setLineItems(p => [...p, newLine()])}>
                    <Plus className="w-3 h-3" /> Agregar línea
                  </Button>
                </div>
                <div className="border border-border rounded-lg overflow-hidden">
                  <table className="w-full text-xs">
                    <thead className="bg-muted/50">
                      <tr>
                        <th className="text-left px-3 py-2 font-medium text-muted-foreground">Descripción</th>
                        <th className="text-right px-3 py-2 font-medium text-muted-foreground w-16">Cant.</th>
                        <th className="text-right px-3 py-2 font-medium text-muted-foreground w-32">Precio unit.</th>
                        <th className="text-right px-3 py-2 font-medium text-muted-foreground w-28">Total</th>
                        <th className="w-8" />
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-border">
                      {lineItems.map((line, i) => (
                        <tr key={i} className="hover:bg-muted/20">
                          <td className="px-2 py-1.5"><Input className="h-7 text-xs border-0 focus-visible:ring-0 bg-transparent" value={line.description} onChange={e => updateLine(i, 'description', e.target.value)} placeholder="Descripción..." /></td>
                          <td className="px-2 py-1.5"><Input type="number" className="h-7 text-xs border-0 focus-visible:ring-0 bg-transparent text-right w-14" value={line.quantity === 0 ? '' : line.quantity} placeholder="1" onChange={e => updateLine(i, 'quantity', e.target.value === '' ? 0 : Number(e.target.value))} min={1} /></td>
                          <td className="px-2 py-1.5"><Input type="number" className="h-7 text-xs border-0 focus-visible:ring-0 bg-transparent text-right" value={line.unitPrice === 0 ? '' : line.unitPrice} placeholder="0.00" onChange={e => updateLine(i, 'unitPrice', e.target.value === '' ? 0 : Number(e.target.value))} /></td>
                          <td className={`px-3 py-1.5 text-right font-medium ${line.total < 0 ? 'text-destructive' : line.total === 0 ? 'text-muted-foreground/50' : ''}`}>{line.total === 0 ? '—' : fmtNum(line.total)}</td>
                          <td className="px-1 py-1.5 text-center">
                            <button onClick={() => removeLine(i)} disabled={lineItems.length === 1} className="p-1 rounded text-muted-foreground hover:text-destructive disabled:opacity-20 transition-colors">
                              <Trash2 className="w-3 h-3" />
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                    <tfoot className="bg-muted/30 border-t border-border">
                      <tr>
                        <td colSpan={3} className="px-3 py-2 text-right text-xs font-semibold text-muted-foreground">Total {form.currency}</td>
                        <td className="px-3 py-2 text-right text-sm font-bold">{fmtNum(total)}</td>
                        <td />
                      </tr>
                    </tfoot>
                  </table>
                </div>
              </div>
            </div>
          </div>

          <DialogFooter className="px-6 py-4 border-t flex gap-2 flex-shrink-0">
            <Button variant="ghost" onClick={onClose} disabled={saving || savingAndSubmitting}>Cancelar</Button>
            {po ? (
              <Button onClick={() => handleSave(false)} disabled={saving} className="gap-1.5">
                {saving ? 'Guardando...' : 'Actualizar OC'}
              </Button>
            ) : (
              <>
                <Button variant="outline" onClick={() => handleSave(false)} disabled={saving || savingAndSubmitting} className="gap-1.5">
                  {saving ? 'Guardando...' : 'Guardar borrador'}
                </Button>
                <Button onClick={() => handleSave(true)} disabled={saving || savingAndSubmitting} className="gap-1.5">
                  {savingAndSubmitting ? 'Enviando...' : <><Send className="w-3.5 h-3.5" /> Guardar y enviar a aprobación</>}
                </Button>
              </>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <AlertDialog open={anticipoWarn} onOpenChange={setAnticipo}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle className="flex items-center gap-2">
              <AlertTriangle className="w-5 h-5 text-orange-500" /> ¿Esta OC es un anticipo?
            </AlertDialogTitle>
            <AlertDialogDescription asChild>
              <div className="space-y-2 text-sm text-muted-foreground">
                <p>Detectamos la palabra <strong>"anticipo"</strong> en la descripción o notas, pero el <strong>Tipo de OC</strong> está configurado como <strong>"{form.orderType}"</strong>.</p>
                <p>¿Qué deseas hacer?</p>
              </div>
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter className="flex-col sm:flex-row gap-2">
            <AlertDialogCancel onClick={() => setAnticipo(false)}>Volver y revisar</AlertDialogCancel>
            <AlertDialogAction onClick={handleFixAndSave} className="bg-orange-500 hover:bg-orange-600 text-white">
              Cambiar a "Anticipo" y guardar
            </AlertDialogAction>
            <AlertDialogAction onClick={() => { setAnticipo(false); doSave(pendingSubmit); }}>
              Guardar como "{form.orderType}"
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

