          <Tooltip
            contentStyle={{ fontSize: '11px', padding: '4px 8px', background: 'hsl(var(--card))', border: '1px solid hsl(var(--border))', borderRadius: '6px', boxShadow: 'none' }}
            formatter={(v: number) => [v]}
          />
          <Bar dataKey="count" radius={[0, 4, 4, 0]}>
