import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useProject } from '../../context/ProjectContext';
import { GetDashboardDataOutputType } from 'zite-endpoints-sdk';
import { Search, FolderOpen } from 'lucide-react';
import { Input } from '@/components/ui/input';

type Project = GetDashboardDataOutputType['myProjects'][0];

type Tab = 'active' | 'all';

function statusDot(status: string) {
  if (status === 'En curso') return 'bg-emerald-500';
  if (status === 'En pausa') return 'bg-amber-400';
  return 'bg-muted-foreground/30';
}

export default function ProjectCards({ projects }: { projects: Project[] }) {
  const navigate = useNavigate();
  const { setSelectedProject } = useProject();
  const [tab, setTab] = useState<Tab>('active');
  const [search, setSearch] = useState('');

  const filtered = projects.filter(p => {
    if (tab === 'active' && p.status !== 'En curso') return false;
    if (search) {
      const q = search.toLowerCase();
      return (
        p.projectCode?.toLowerCase().includes(q) ||
        p.fullName?.toLowerCase().includes(q)
      );
    }
    return true;
  });

  return (
    <div className="space-y-2">
      {/* Toolbar */}
      <div className="flex items-center gap-2">
        <div className="relative flex-1">
          <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground pointer-events-none" />
          <Input
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Buscar proyecto..."
            className="h-8 pl-8 text-xs bg-muted/40 border-border focus-visible:ring-1"
          />
        </div>
        <div className="flex items-center bg-muted rounded-lg p-0.5 shrink-0">
          {(['active', 'all'] as Tab[]).map(t => (
            <button
              key={t}
              onClick={() => setTab(t)}
              className={`text-xs px-3 py-1 rounded-md font-medium transition-all ${
                tab === t
                  ? 'bg-card text-foreground shadow-sm'
                  : 'text-muted-foreground hover:text-foreground'
              }`}
            >
              {t === 'active' ? 'Mis activos' : 'Todos'}
            </button>
          ))}
        </div>
      </div>

      {/* Grid */}
      {filtered.length === 0 ? (
        <div className="flex items-center gap-2 py-4 px-3 text-sm text-muted-foreground bg-muted/20 rounded-lg border border-dashed border-border">
          <FolderOpen className="w-4 h-4 text-muted-foreground/40 flex-shrink-0" />
          {search ? 'Sin resultados' : tab === 'active' ? 'No tienes proyectos activos' : 'No hay proyectos'}
        </div>
      ) : (
        <div className="max-h-[200px] overflow-y-auto pr-0.5">
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-2">
            {filtered.map(p => (
              <button
                key={p.id}
                onClick={() => { if (p.projectCode) { setSelectedProject(p.projectCode); navigate(`/operacion/proyectos/${p.projectCode}`); } }}
                title={p.fullName ?? p.projectCode ?? ''}
                className="flex items-center gap-2 bg-card border border-border rounded-lg px-3 py-2 hover:border-primary/50 hover:bg-muted/30 transition-all text-left group w-full min-w-0"
              >
                <span className={`w-2 h-2 rounded-full flex-shrink-0 ${statusDot(p.status ?? '')}`} />
                <span className="text-xs font-bold text-foreground truncate group-hover:text-primary transition-colors">
                  {p.projectCode}
                </span>
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

src/components/finance/CostRubroChart.ts.content:
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

type RubroRow = {
  rubro: string;
  cotizado: number;
  precioCliente: number;
  gastado: number;
};

const SHORT: Record<string, string> = {
  'Reclutamiento e incentivos': 'Reclutamiento',
  'Moderación': 'Moderación',
  'Management': 'Management',
  'Logística y operación': 'Logística',
  'Back office': 'Back office',
};

const fmtY = (v: number) => {
  if (v >= 1_000_000) return `$${(v / 1_000_000).toFixed(1)}M`;
  if (v >= 1_000) return `$${(v / 1_000).toFixed(0)}K`;
  return `$${v}`;
};

const fmtTooltip = (v: number) =>
  new Intl.NumberFormat('es-MX', { style: 'currency', currency: 'MXN', maximumFractionDigits: 0 }).format(v);

export default function CostRubroChart({ byRubro }: { byRubro: RubroRow[] }) {
  const data = byRubro.map(r => ({
    name: SHORT[r.rubro] ?? r.rubro,
    'Precio cliente': r.precioCliente,
    'Costo cotizado': r.cotizado,
    'Gastado (ODCs)': r.gastado,
  }));

  return (
    <ResponsiveContainer width="100%" height={320}>
      <BarChart data={data} margin={{ top: 8, right: 16, left: 16, bottom: 8 }} barCategoryGap="25%">
        <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
        <XAxis
          dataKey="name"
          tick={{ fontSize: 12, fill: 'hsl(var(--muted-foreground))' }}
          axisLine={{ stroke: 'hsl(var(--border))' }}
          tickLine={false}
        />
        <YAxis
          tickFormatter={fmtY}
          tick={{ fontSize: 11, fill: 'hsl(var(--muted-foreground))' }}
          axisLine={false}
          tickLine={false}
          width={64}
        />
        <Tooltip
          formatter={(v: number) => fmtTooltip(v)}
          contentStyle={{
            background: 'hsl(var(--card))',
            border: '1px solid hsl(var(--border))',
            borderRadius: '8px',
            fontSize: 13,
          }}
          labelStyle={{ color: 'hsl(var(--foreground))', fontWeight: 600 }}
        />
        <Legend wrapperStyle={{ fontSize: 12, paddingTop: 8 }} />
        <Bar dataKey="Precio cliente" fill="hsl(var(--primary))" radius={[4, 4, 0, 0]} />
        <Bar dataKey="Costo cotizado" fill="hsl(var(--muted-foreground))" radius={[4, 4, 0, 0]} opacity={0.6} />
        <Bar dataKey="Gastado (ODCs)" fill="hsl(var(--chart-2))" radius={[4, 4, 0, 0]} />
      </BarChart>
    </ResponsiveContainer>
  );
}

src/components/finance/ProjectCostRow.ts.content:
import { useState } from 'react';
import { ChevronRight, Link2, Unlink, RefreshCw, BarChart2, TableIcon } from 'lucide-react';
import { cn } from '@/lib/utils';
import { linkProjectDeal } from 'zite-endpoints-sdk';
import type { GetMultiProjectCostAnalysisOutputType } from 'zite-endpoints-sdk';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { toast } from 'sonner';
import CostPnLTable from './CostPnLTable';
import CostRubroChart from './CostRubroChart';

type ProjectAnalysis = GetMultiProjectCostAnalysisOutputType['projects'][0];
type DealItem = GetMultiProjectCostAnalysisOutputType['dealsList'][0];

const fmt = (v: number) =>
  new Intl.NumberFormat('es-MX', { style: 'currency', currency: 'MXN', maximumFractionDigits: 0 }).format(v);

function Num({ v, pct = false }: { v: number | null; pct?: boolean }) {
  if (v === null) return <span className="text-muted-foreground">—</span>;
  const pos = v >= 0;
  return (
    <span className={cn('font-medium tabular-nums', pos ? 'text-emerald-600' : 'text-destructive')}>
      {pct ? `${v.toFixed(1)}%` : fmt(v)}
    </span>
  );
}

interface Props {
  analysis: ProjectAnalysis;
  dealsList: DealItem[];
  isExpanded: boolean;
  onToggle: () => void;
  onDealUpdated: (projectId: string, deal: DealItem | null) => void;
  onRefreshAnalysis: () => void;
}

export default function ProjectCostRow({ analysis, dealsList, isExpanded, onToggle, onDealUpdated, onRefreshAnalysis }: Props) {
  const { project, deal, totals } = analysis;
  const [editingDeal, setEditingDeal] = useState(false);
  const [pendingDealId, setPendingDealId] = useState('');
  const [saving, setSaving] = useState(false);

  const saveDeal = async (dealId?: string) => {
    const matchedDeal = dealId ? (dealsList.find(d => d.id === dealId) ?? null) : null;
    // Optimistic update — update UI immediately
    onDealUpdated(project.id, matchedDeal);
    setEditingDeal(false);
    toast.success(dealId ? 'Deal vinculado' : 'Deal desvinculado');
    // Persist in background
    setSaving(true);
    try {
      await linkProjectDeal({ projectId: project.id, dealId });
      onRefreshAnalysis();
    } catch {
      toast.error('Error al guardar — recarga para ver el estado real');
    } finally {
      setSaving(false);
    }
  };

  return (
    <>
      {/* ── Summary row ── */}
      <tr className="hover:bg-muted/30 cursor-pointer border-b border-border transition-colors" onClick={onToggle}>
        <td className="px-3 py-3 text-center">
          <ChevronRight className={cn('w-4 h-4 text-muted-foreground transition-transform duration-200', isExpanded && 'rotate-90')} />
        </td>
        <td className="px-3 py-3">
          <span className="font-mono text-xs text-muted-foreground block">{project.projectCode}</span>
          {project.fullName && <span className="text-sm font-medium text-foreground leading-tight">{project.fullName}</span>}
        </td>
        <td className="px-3 py-3">
          {deal
            ? <span className="text-sm text-foreground truncate max-w-[10rem] block">{deal.dealName}</span>
            : <Badge variant="outline" className="text-xs text-muted-foreground font-normal">Sin deal</Badge>}
        </td>
        <td className="px-3 py-3 text-right text-sm text-muted-foreground tabular-nums">{fmt(totals.cotizado)}</td>
        <td className="px-3 py-3 text-right text-sm"><Num v={totals.markUpInicial} /></td>
        <td className="px-3 py-3 text-right text-sm tabular-nums">{fmt(totals.costoConMarkup)}</td>
        <td className="px-3 py-3 text-right text-sm tabular-nums font-medium">{fmt(totals.precioCliente)}</td>
        <td className="px-3 py-3 text-right text-sm tabular-nums">{fmt(totals.gastado)}</td>
        <td className="px-3 py-3 text-right text-sm"><Num v={totals.diferenciaTotalMxn} /></td>
        <td className="px-3 py-3 text-right text-sm"><Num v={totals.markUpFinal} /></td>
        <td className="px-3 py-3 text-right text-sm"><Num v={totals.revenueInicial} pct /></td>
        <td className="px-3 py-3 text-right text-sm"><Num v={totals.revenueFinal} pct /></td>
      </tr>

      {/* ── Expanded detail ── */}
      {isExpanded && (
        <tr className="bg-muted/10 border-b border-border">
          <td colSpan={11} className="px-6 py-5">
            <div className="space-y-4">
              {/* Deal linker */}
              <div className="flex flex-wrap items-center gap-3 bg-card border border-border rounded-lg px-4 py-3" onClick={e => e.stopPropagation()}>
                <Link2 className="w-4 h-4 text-muted-foreground shrink-0" />
                {!editingDeal ? (
                  <>
                    {deal ? (
                      <>
                        <span className="text-sm text-muted-foreground">Deal:</span>
                        <span className="text-sm font-semibold">{deal.dealName}</span>
                        {deal.clientPrice && <Badge variant="secondary" className="text-xs">{fmt(deal.clientPrice)}</Badge>}
                        <div className="flex gap-2 ml-auto">
                          <Button size="sm" variant="outline" onClick={() => { setEditingDeal(true); setPendingDealId(deal.id); }}>
                            <RefreshCw className="w-3 h-3 mr-1" />Cambiar
                          </Button>
                          <Button size="sm" variant="outline" onClick={() => saveDeal()} disabled={saving}>
                            <Unlink className="w-3 h-3 mr-1" />Desvincular
                          </Button>
                        </div>
                      </>
                    ) : (
                      <>
                        <span className="text-sm text-muted-foreground">Sin deal vinculado</span>
                        <Button size="sm" className="ml-auto" onClick={() => { setEditingDeal(true); setPendingDealId(''); }}>
                          <Link2 className="w-3 h-3 mr-1" />Vincular Deal
                        </Button>
                      </>
                    )}
                  </>
                ) : (
                  <>
                    <span className="text-sm font-medium">Seleccionar deal:</span>
                    <Select value={pendingDealId} onValueChange={setPendingDealId}>
                      <SelectTrigger className="w-72 h-8 text-sm"><SelectValue placeholder="Busca un deal..." /></SelectTrigger>
                      <SelectContent>
                        {dealsList.map(d => <SelectItem key={d.id} value={d.id}>{d.dealName}</SelectItem>)}
                      </SelectContent>
                    </Select>
                    <Button size="sm" onClick={() => saveDeal(pendingDealId)} disabled={saving || !pendingDealId}>Guardar</Button>
                    <Button size="sm" variant="ghost" onClick={() => setEditingDeal(false)}>Cancelar</Button>
                  </>
                )}
              </div>

              {/* P&L detail */}
              <Tabs defaultValue="tabla">
                <TabsList>
                  <TabsTrigger value="tabla" className="gap-1.5"><TableIcon className="w-3.5 h-3.5" />Tabla P&L</TabsTrigger>
                  <TabsTrigger value="grafico" className="gap-1.5"><BarChart2 className="w-3.5 h-3.5" />Gráfico</TabsTrigger>
                </TabsList>
                <TabsContent value="tabla" className="mt-3">
                  <CostPnLTable byRubro={analysis.byRubro} totals={analysis.totals} />
                </TabsContent>
                <TabsContent value="grafico" className="mt-3 bg-card border border-border rounded-lg p-4">
                  <CostRubroChart byRubro={analysis.byRubro} />
                </TabsContent>
              </Tabs>
            </div>
          </td>
        </tr>
      )}
    </>
  );
}

src/hooks/useRealtimeUserNotifications.t.content:
import { useEffect, useRef, useCallback, useState } from 'react';
import { getAblyToken } from 'zite-endpoints-sdk';

// Duplicated from src/lib/ably.ts — cannot import backend code from frontend
export function safeUserChannel(email: string): string {
  return 'user:' + email.trim().toLowerCase().replace(/[^a-z0-9_-]/g, '_');
}

export type UserNotificationPayload = {
  channel: string;
  messageId?: string;
  senderName?: string;
  senderEmail?: string;
  hasMention: boolean;
  sentAt?: string;
  contentPreview?: string;
  isActiveChannel?: boolean;
};

export type ConversationCreatedPayload = {
  conversationId: string;
  conversationType: 'DM' | 'Group';
  conversationName: string;
  members: string[];
  createdBy: string;
  createdAt: string;
};

type UseRealtimeUserNotificationsOptions = {
  userEmail: string;
  activeChannel: string;
  enabled?: boolean;
  onNewMessage: (payload: UserNotificationPayload) => void;
  onConversationCreated?: (payload: ConversationCreatedPayload) => void;
};

export function useRealtimeUserNotifications({
  userEmail,
  activeChannel,
  enabled = true,
  onNewMessage,
  onConversationCreated,
}: UseRealtimeUserNotificationsOptions): { status: 'connecting' | 'connected' | 'disconnected' } {
  // Use a ref for the callback so the SSE loop never goes stale without reconnecting
  const onNewMessageRef = useRef(onNewMessage);
  const onConversationCreatedRef = useRef(onConversationCreated);
  const activeChannelRef = useRef(activeChannel);
  onNewMessageRef.current = onNewMessage;
  onConversationCreatedRef.current = onConversationCreated;
  activeChannelRef.current = activeChannel;

  const [status, setStatus] = useState<'connecting' | 'connected' | 'disconnected'>('disconnected');

  const tokenRef = useRef<{ token: string; expires: number } | null>(null);
  const eventSourceRef = useRef<EventSource | null>(null);
  const retryTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const cleanup = useCallback(() => {
    if (eventSourceRef.current) {
      eventSourceRef.current.close();
      eventSourceRef.current = null;
    }
    if (retryTimeoutRef.current) {
      clearTimeout(retryTimeoutRef.current);
      retryTimeoutRef.current = null;
    }
  }, []);

  useEffect(() => {
    if (!enabled || !userEmail) {
      cleanup();
      return;
    }

    const ablyChannel = safeUserChannel(userEmail);
    let cancelled = false;

    const connect = async () => {
      console.log('[ably][user-notify][connecting]', { ablyChannel });
      if (!cancelled) setStatus('connecting');

      // Get or refresh token
      const now = Math.floor(Date.now() / 1000);
      if (!tokenRef.current || tokenRef.current.expires - now < 300) {
        try {
          const res = await getAblyToken({ channels: [ablyChannel] });
          if (res.token && res.expires) {
            tokenRef.current = { token: res.token, expires: res.expires };
            console.log('[ably][user-notify][token ok]', { ablyChannel, expiresIn: res.expires - now });
          } else {
            console.warn('[ably][user-notify][token failed]', { ablyChannel, error: res.error ?? 'no token' });
            if (!cancelled) {
              retryTimeoutRef.current = setTimeout(connect, 10000);
            }
            return;
          }
        } catch (err) {
          console.warn('[ably][user-notify][token error]', { ablyChannel, error: (err as Error).message });
          if (!cancelled) {
            retryTimeoutRef.current = setTimeout(connect, 10000);
          }
          return;
        }
      }

      if (cancelled) return;

      const sseUrl = `https://realtime.ably.io/sse?channels=${encodeURIComponent(ablyChannel)}&accessToken=${encodeURIComponent(tokenRef.current!.token)}&v=1.2`;
      const es = new EventSource(sseUrl);
      eventSourceRef.current = es;

      es.onopen = () => {
        if (!cancelled) {
          setStatus('connected');
          console.log('[ably][user-notify][connected] ✓', { ablyChannel });
        }
      };

      es.onmessage = (event) => {
        try {
          const parsed = JSON.parse(event.data);

          if (parsed.name === 'conversation.created' && parsed.data) {
            const convPayload: ConversationCreatedPayload = typeof parsed.data === 'string' ? JSON.parse(parsed.data) : parsed.data;
            console.log('[ably][user-notify][conversation.created]', { conversationId: convPayload.conversationId });
            onConversationCreatedRef.current?.(convPayload);
            return;
          }

          if (parsed.name !== 'notification.new_message' || !parsed.data) return;

          const payload: UserNotificationPayload = typeof parsed.data === 'string'
            ? JSON.parse(parsed.data)
            : parsed.data;

          console.log('[ably][user-notify][event]', { channel: payload.channel, hasMention: payload.hasMention });

          // If the user is viewing this channel, mark it — don't suppress so Layout can signal ChatPage
          if (payload.channel === activeChannelRef.current) {
            payload.isActiveChannel = true;
          }

          onNewMessageRef.current(payload);
        } catch {
          // Ignore malformed events
        }
      };

      es.onerror = () => {
        console.warn('[ably][user-notify][error]', { ablyChannel, readyState: es.readyState });
        if (!cancelled) {
          setStatus('disconnected');
          es.close();
          eventSourceRef.current = null;
          tokenRef.current = null; // force re-fetch on retry
          retryTimeoutRef.current = setTimeout(connect, 3000);
        }
      };
    };

    connect();

    // Refresh token before expiry (every 50 minutes)
    const tokenRefreshInterval = setInterval(() => {
      if (!cancelled && tokenRef.current) {
        const now = Math.floor(Date.now() / 1000);
        if (tokenRef.current.expires - now < 600) {
          cleanup();
          tokenRef.current = null;
          connect();
        }
      }
    }, 50 * 60 * 1000);

    return () => {
      cancelled = true;
      clearInterval(tokenRefreshInterval);
      cleanup();
      console.log('[ably][user-notify][disconnected]', { ablyChannel });
    };
  }, [userEmail, enabled, cleanup]);

  return { status };
}

src/lib/commercial-dashboard/chartData.t.content:
import { Deal, WidgetConfig, ChartDataPoint, DateReference } from './types';
import { calcMetricInCurrency, filterDealsByCurrency } from './metrics';
import { groupDeals, fillTimeSeries, getGroupKey, getGroupKeyStripped } from './grouping';

const MONTH_NAMES_ORDERED = ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'];
const QUARTER_NAMES_ORDERED = ['Q1', 'Q2', 'Q3', 'Q4'];

export function buildChartData(
  deals: Deal[],
  widget: WidgetConfig,
  dateRef: DateReference
): ChartDataPoint[] {
  // Pre-filter deals by the widget's currency preference
  const filteredDeals = filterDealsByCurrency(deals, widget.currency);

  if (widget.chartType === 'scatter') {
    return buildScatterData(filteredDeals, widget, dateRef);
  }
  const { compareBy: cb } = widget;
  if (cb && cb !== widget.groupBy) {
    return buildMultiSeriesData(filteredDeals, widget, dateRef, deals);
  }
  return buildSingleSeriesData(filteredDeals, widget, dateRef, deals);
}

function buildScatterData(deals: Deal[], widget: WidgetConfig, dateRef: DateReference): ChartDataPoint[] {
  const { metric, metricY, groupBy, displayOptions, currency } = widget;
  const grouped = groupDeals(deals, groupBy, dateRef);
  const points: ChartDataPoint[] = [];
  for (const [label, grpDeals] of grouped.entries()) {
    if (!label || label.startsWith('Sin ')) continue;
    points.push({
      label,
      value: calcMetricInCurrency(grpDeals, metric, currency),
      valueY: calcMetricInCurrency(grpDeals, metricY ?? 'dealCount', currency),
      deals: grpDeals,
    });
  }
  const dir = displayOptions.sortDirection ?? 'desc';
  points.sort((a, b) => dir === 'desc' ? b.value - a.value : a.value - b.value);
  return points.slice(0, displayOptions.limit ?? 50);
}

function buildSingleSeriesData(deals: Deal[], widget: WidgetConfig, dateRef: DateReference, allDeals?: Deal[]): ChartDataPoint[] {
  const { metric, groupBy, displayOptions, currency } = widget;
  const isTime = ['month', 'quarter', 'year'].includes(groupBy);

  let grouped = groupDeals(deals, groupBy, dateRef);
  if (isTime) grouped = fillTimeSeries(grouped, groupBy as 'month' | 'quarter' | 'year', allDeals ?? deals, dateRef);

  const points: ChartDataPoint[] = [...grouped.entries()].map(([label, grpDeals]) => ({
    label,
    value: calcMetricInCurrency(grpDeals, metric, currency),
    deals: grpDeals,
  }));

  if (!isTime && groupBy !== 'phase') {
    const dir = displayOptions.sortDirection ?? 'desc';
    points.sort((a, b) => dir === 'desc' ? b.value - a.value : a.value - b.value);
    return points.slice(0, displayOptions.limit ?? 50);
  }
  return points;
}

/** Auto-detect the top N compare values by total metric across all deals */
function getAutoCompareValues(
  deals: Deal[],
  compareBy: string,
  metric: WidgetConfig['metric'],
  dateRef: DateReference,
  limit: number,
  currency?: 'all' | 'MXN' | 'USD'
): string[] {
  const totals = new Map<string, number>();
  for (const d of deals) {
    const cv = getGroupKey(d, compareBy as any, dateRef);
    if (!cv || cv.startsWith('Sin ') || cv === 'Otro') continue;
    totals.set(cv, (totals.get(cv) ?? 0));
  }
  // compute metric per value
  for (const cv of totals.keys()) {
    const subset = deals.filter(d => getGroupKey(d, compareBy as any, dateRef) === cv);
    totals.set(cv, calcMetricInCurrency(subset, metric, currency));
  }
  return [...totals.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, limit)
    .map(([cv]) => cv);
}

function buildMultiSeriesData(deals: Deal[], widget: WidgetConfig, dateRef: DateReference, allDeals?: Deal[]): ChartDataPoint[] {
  const { metric, groupBy, compareBy, compareValues, compareMode, displayOptions, currency } = widget;
  const isTimeGroupBy = ['month', 'quarter', 'year'].includes(groupBy);
  const isTimeCompare = ['month', 'quarter', 'year'].includes(compareBy!);
  const seriesLimit = displayOptions.limit ?? 10;

  // Resolve which compare values to use.
  const isAuto = compareMode === 'auto' || !compareValues?.length;
  const resolvedValues = isAuto
    ? getAutoCompareValues(deals, compareBy!, metric, dateRef, isTimeCompare ? 100 : seriesLimit, currency)
    : compareValues!;

  if (resolvedValues.length === 0) return buildSingleSeriesData(deals, widget, dateRef, allDeals);

  // Case A: compareBy=year, groupBy=month/quarter → strip year from x-axis labels
  const useStripped = compareBy === 'year' && (groupBy === 'month' || groupBy === 'quarter');

  // Case B: compareBy is temporal (month/quarter/year), groupBy is non-temporal
  const timeCompareNonTimeGroup = isTimeCompare && !isTimeGroupBy;

  // Establish ordered x-axis labels
  let labels: string[];
  if (useStripped) {
    labels = groupBy === 'month' ? MONTH_NAMES_ORDERED : QUARTER_NAMES_ORDERED;
  } else if (timeCompareNonTimeGroup) {
    const labelSet = new Set<string>();
    for (const d of deals) {
      const lbl = getGroupKey(d, groupBy, dateRef);
      if (lbl && !lbl.startsWith('Sin ')) labelSet.add(lbl);
    }
    labels = [...labelSet];
  } else if (isTimeGroupBy) {
    const allGrouped = groupDeals(allDeals ?? deals, groupBy, dateRef);
    const filled = fillTimeSeries(allGrouped, groupBy as 'month' | 'quarter' | 'year', allDeals ?? deals, dateRef);
    labels = [...filled.keys()];
  } else {
    const labelSet = new Set<string>();
    for (const d of deals) {
      const lbl = getGroupKey(d, groupBy, dateRef);
      if (lbl) labelSet.add(lbl);
    }
    labels = [...labelSet];
  }

  // For each series value: compute metric per x-axis label
  const seriesData: { cv: string; byLabel: Map<string, number> }[] = [];
  for (const cv of resolvedValues) {
    const filtered = deals.filter(d => getGroupKey(d, compareBy!, dateRef) === cv);
    const byLabel = new Map<string, number>();

    if (useStripped) {
      const strippedGroups = new Map<string, Deal[]>();
      for (const d of filtered) {
        const k = getGroupKeyStripped(d, groupBy, dateRef);
        if (!strippedGroups.has(k)) strippedGroups.set(k, []);
        strippedGroups.get(k)!.push(d);
      }
      for (const lbl of labels) {
        byLabel.set(lbl, calcMetricInCurrency(strippedGroups.get(lbl) ?? [], metric, currency));
      }
    } else if (timeCompareNonTimeGroup) {
      const grouped = groupDeals(filtered, groupBy, dateRef);
      for (const lbl of labels) {
        byLabel.set(lbl, calcMetricInCurrency(grouped.get(lbl) ?? [], metric, currency));
      }
    } else {
      const grouped = groupDeals(filtered, groupBy, dateRef);
      for (const [lbl, ds] of grouped.entries()) {
        byLabel.set(lbl, calcMetricInCurrency(ds, metric, currency));
      }
    }
    seriesData.push({ cv, byLabel });
  }

  // For non-time x-axis: sort labels by combined value and apply seriesLimit
  if (!isTimeGroupBy && groupBy !== 'phase') {
    const combined = labels.map(lbl => ({
      lbl,
      total: seriesData.reduce((s, sd) => s + (sd.byLabel.get(lbl) ?? 0), 0),
    }));
    const dir = displayOptions.sortDirection ?? 'desc';
    combined.sort((a, b) => dir === 'desc' ? b.total - a.total : a.total - b.total);
    labels = combined.slice(0, seriesLimit).map(x => x.lbl);
  }

  // Collect deals per label across all series
  const dealsByLabel = new Map<string, Deal[]>();
  for (const cv of resolvedValues) {
    const filtered = deals.filter(d => getGroupKey(d, compareBy!, dateRef) === cv);
    for (const d of filtered) {
      const lbl = useStripped
        ? getGroupKeyStripped(d, groupBy, dateRef)
        : getGroupKey(d, groupBy, dateRef);
      if (labels.includes(lbl)) {
        if (!dealsByLabel.has(lbl)) dealsByLabel.set(lbl, []);
        dealsByLabel.get(lbl)!.push(d);
      }
    }
  }

  return labels.map(label => ({
    label,
    value: 0,
    series: Object.fromEntries(seriesData.map(({ cv, byLabel }) => [cv, byLabel.get(label) ?? 0])),
    deals: dealsByLabel.get(label) ?? [],
  }));
}

