import { useState, useRef } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Separator } from '@/components/ui/separator';
import { Progress } from '@/components/ui/progress';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { toast } from 'sonner';
import { fmtCurrency } from '../../lib/format';
import { sendPaymentReceipt, savePayment, GetPaymentsOutputType } from 'zite-endpoints-sdk';
import { uploadFile } from 'zite-file-upload-sdk';
import {
  CreditCard, Paperclip, FileText, Landmark, Receipt,
  Pencil, Trash2, Send, AlertCircle, Upload, Building2, X, CheckCircle, XCircle,
} from 'lucide-react';

type Payment = GetPaymentsOutputType['payments'][0];


function fmtDate(d?: string) {
  if (!d) return '—';
  return new Date(d.split('T')[0] + 'T12:00:00').toLocaleDateString('es-MX', { day: '2-digit', month: 'short', year: 'numeric' });
}

function StatusBadge({ status }: { status?: string }) {
  const styles: Record<string, string> = {
    'Programado': 'bg-yellow-100 text-yellow-700 border-yellow-200',
    'Realizado': 'bg-green-100 text-green-700 border-green-200',
    'Cancelado': 'bg-red-100 text-red-700 border-red-200',
  };
  return (
    <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-semibold border ${styles[status ?? ''] ?? 'bg-muted text-muted-foreground border-border'}`}>
      {status || '—'}
    </span>
  );
}

interface Props {
  payment: Payment | null;
  open: boolean;
  onOpenChange: (v: boolean) => void;
  onEdit: () => void;
  onDelete: () => void;
  onAttachmentUploaded?: (attachment: { url: string }[]) => void;
  onPaymentUpdated?: (updates: { status?: string; paymentDate?: string }) => void;
}

export function PaymentDetailDialog({ payment, open, onOpenChange, onEdit, onDelete, onAttachmentUploaded, onPaymentUpdated }: Props) {
  const [sending, setSending] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [dragging, setDragging] = useState(false);
  const [registering, setRegistering] = useState(false);
  const [cancelling, setCancelling] = useState(false);
  const [cancelConfirmOpen, setCancelConfirmOpen] = useState(false);
  const [localAttachment, setLocalAttachment] = useState<{ url: string }[] | null>(null);
  const [localStatus, setLocalStatus] = useState<string | null>(null);
  const [localPaymentDate, setLocalPaymentDate] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const currentAttachment = localAttachment ?? (payment?.attachment ?? []);
  const hasAttachment = currentAttachment.length > 0;
  const displayStatus = localStatus ?? payment?.status;
  const displayPaymentDate = localPaymentDate ?? payment?.paymentDate;

  if (!payment) return null;

  const isProgramado = displayStatus === 'Programado';
  const paidPct = payment.poTotalAmount ? Math.min(100, ((payment.amount ?? 0) / payment.poTotalAmount) * 100) : 0;
  const isOverdue = (() => {
    if (!payment.dueDate || !isProgramado) return false;
    const due = new Date(payment.dueDate.split('T')[0] + 'T12:00:00');
    due.setHours(0, 0, 0, 0);
    const today = new Date(); today.setHours(0, 0, 0, 0);
    return due < today;
  })();

  const handleUploadFile = async (file: File) => {
    setUploading(true);
    try {
      const { fileUrl } = await uploadFile({ data: file, filename: file.name });
      const newAttachment = [...currentAttachment, { url: fileUrl }];
      await savePayment({ id: payment.id, attachment: newAttachment });
      setLocalAttachment(newAttachment);
      onAttachmentUploaded?.(newAttachment);
      toast.success('Comprobante subido correctamente');
    } catch {
      toast.error('Error al subir el comprobante');
    }
    setUploading(false);
  };

  const handleRemoveAttachment = async (idx: number) => {
    const newAttachment = currentAttachment.filter((_, i) => i !== idx);
    try {
      await savePayment({ id: payment.id, attachment: newAttachment });
      setLocalAttachment(newAttachment);
      onAttachmentUploaded?.(newAttachment);
      toast.success('Comprobante eliminado');
    } catch {
      toast.error('Error al eliminar el comprobante');
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragging(false);
    const file = e.dataTransfer.files?.[0];
    if (file) handleUploadFile(file);
  };

  const handleRegisterPayment = async () => {
    if (!hasAttachment) {
      toast.error('Sube un comprobante antes de registrar el pago');
      return;
    }
    setRegistering(true);
    try {
      const today = new Date().toISOString().split('T')[0];
      await savePayment({ id: payment.id, status: 'Realizado', paymentDate: today });
      setLocalStatus('Realizado');
      setLocalPaymentDate(today);
      onPaymentUpdated?.({ status: 'Realizado', paymentDate: today });
      toast.success('Pago registrado como realizado');
    } catch {
      toast.error('Error al registrar el pago');
    }
    setRegistering(false);
  };

  const handleCancelPayment = async () => {
    setCancelConfirmOpen(false);
    setCancelling(true);
    try {
      await savePayment({ id: payment.id, status: 'Cancelado' });
      setLocalStatus('Cancelado');
      onPaymentUpdated?.({ status: 'Cancelado' });
      toast.success('Pago cancelado');
    } catch {
      toast.error('Error al cancelar el pago');
    }
    setCancelling(false);
  };

  const handleSendReceipt = async () => {
    setSending(true);
    try {
      const result = await sendPaymentReceipt({ paymentId: payment.id });
      toast.success(result.message);
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : 'Error al enviar comprobante';
      toast.error(msg);
    }
    setSending(false);
  };

  return (
    <>
      <Dialog open={open} onOpenChange={(v) => { if (!v) { setLocalAttachment(null); setLocalStatus(null); setLocalPaymentDate(null); } onOpenChange(v); }}>
        <DialogContent className="sm:max-w-2xl max-h-[90vh] flex flex-col p-0 gap-0">
          <DialogHeader className="px-6 pt-6 pb-4 border-b shrink-0">
            <div className="flex items-start gap-3">
              <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center shrink-0">
                <CreditCard className="w-5 h-5 text-primary" />
              </div>
              <div className="min-w-0 flex-1">
                <div className="flex items-center gap-2 flex-wrap">
                  <DialogTitle className="text-base font-bold">{String(payment.paymentId ?? '—')}</DialogTitle>
                  <StatusBadge status={displayStatus} />
                  {payment.currency && (
                    <span className="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-semibold border bg-blue-100 text-blue-700 border-blue-200">{payment.currency}</span>
                  )}
                </div>
                <p className="text-sm text-muted-foreground mt-0.5">{payment.supplierName ?? '—'}</p>
              </div>
            </div>
          </DialogHeader>

          <div className="flex-1 overflow-y-auto px-6 py-5 space-y-5">
            {/* Payment data */}
            <div>
              <p className="text-[11px] text-muted-foreground uppercase tracking-wider font-semibold mb-3 flex items-center gap-1.5">
                <Receipt className="w-3.5 h-3.5" /> Datos del pago
              </p>
              <div className="grid grid-cols-2 gap-x-6 gap-y-3">
                <div>
                  <p className="text-xs text-muted-foreground mb-0.5">Monto</p>
                  <p className="text-xl font-black text-primary">{fmtCurrency(payment.amount, payment.currency)}</p>
                </div>
                <div>
                  <p className="text-xs text-muted-foreground mb-0.5">Método</p>
                  <p className="text-sm font-medium">{payment.method || 'Transferencia'}</p>
                </div>
                <div>
                  <p className="text-xs text-muted-foreground mb-0.5">Fecha comprometida</p>
                  <div className="flex items-center gap-2">
                    <p className={`text-sm font-medium ${isOverdue ? 'text-destructive' : ''}`}>{fmtDate(payment.dueDate)}</p>
                    {isOverdue && <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-destructive/10 text-destructive border border-destructive/20 leading-none flex items-center gap-1"><AlertCircle className="w-2.5 h-2.5" />Vencido</span>}
                  </div>
                </div>
                <div>
                  <p className="text-xs text-muted-foreground mb-0.5">Fecha de pago real</p>
                  <p className="text-sm font-medium">{fmtDate(displayPaymentDate)}</p>
                </div>
                <div>
                  <p className="text-xs text-muted-foreground mb-0.5">Referencia</p>
                  <p className="text-sm font-medium font-mono">{payment.reference ?? '—'}</p>
                </div>
                <div>
                  <p className="text-xs text-muted-foreground mb-0.5"># Factura proveedor</p>
                  <p className="text-sm font-medium">{payment.supplierInvoiceNumber ?? '—'}</p>
                </div>
                <div>
                  <p className="text-xs text-muted-foreground mb-0.5">ODC vinculada</p>
                  <p className="text-sm font-medium font-mono">{payment.poNumber ? `ODC-${payment.poNumber}` : '—'}</p>
                </div>
                <div>
                  <p className="text-xs text-muted-foreground mb-0.5">Proyecto</p>
                  <p className="text-sm font-medium">{payment.projectCode ?? '—'}</p>
                </div>
                {payment.supplierEmail && (
                  <div>
                    <p className="text-xs text-muted-foreground mb-0.5">Email proveedor</p>
                    <p className="text-sm font-medium">{payment.supplierEmail}</p>
                  </div>
                )}
              </div>
            </div>

            {/* PO */}
            {payment.poId && (
              <>
                <Separator />
                <div>
                  <p className="text-[11px] text-muted-foreground uppercase tracking-wider font-semibold mb-3 flex items-center gap-1.5">
                    <FileText className="w-3.5 h-3.5" /> ODC vinculada
                  </p>
                  <div className="bg-muted/40 rounded-xl p-4 space-y-3">
                    <div className="flex items-center justify-between">
                      <span className="text-sm font-bold">ODC-{payment.poNumber}</span>
                      <span className="text-xs text-muted-foreground">{fmtCurrency(payment.poTotalAmount, payment.currency)}</span>
                    </div>
                    <div className="space-y-1">
                      <div className="flex justify-between text-xs text-muted-foreground">
                        <span>Saldo pendiente</span>
                        <span className="font-semibold text-foreground">{fmtCurrency(payment.poPendingAmount, payment.currency)}</span>
                      </div>
                      <Progress value={100 - paidPct} className="h-1.5" />
                    </div>
                  </div>
                </div>
              </>
            )}

            {/* Bank / Source info */}
            <Separator />
            <div>
              <p className="text-[11px] text-muted-foreground uppercase tracking-wider font-semibold mb-3 flex items-center gap-1.5">
                <Landmark className="w-3.5 h-3.5" /> Datos bancarios
              </p>
              <div className="grid grid-cols-2 gap-x-6 gap-y-3">
                {(payment.sourceCompany || payment.sourceBank || payment.sourceAccount) && (
                  <>
                    <div className="col-span-2">
                      <p className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider mb-2 flex items-center gap-1.5">
                        <Building2 className="w-3 h-3" /> Origen del pago
                      </p>
                    </div>
                    {payment.sourceCompany && (
                      <div>
                        <p className="text-xs text-muted-foreground mb-0.5">Empresa pagadora</p>
                        <p className="text-sm font-medium">{payment.sourceCompany}</p>
                      </div>
                    )}
                    {payment.sourceBank && (
                      <div>
                        <p className="text-xs text-muted-foreground mb-0.5">Banco origen</p>
                        <p className="text-sm font-medium">{payment.sourceBank}</p>
                      </div>
                    )}
                    {payment.sourceAccount && (
                      <div className="col-span-2">
                        <p className="text-xs text-muted-foreground mb-0.5">Cuenta origen</p>
                        <p className="text-sm font-medium font-mono">{payment.sourceAccount}</p>
                      </div>
                    )}
                    <div className="col-span-2 border-t border-border/50 pt-3 mt-1" />
                  </>
                )}
                <div className="col-span-2">
                  <p className="text-xs text-muted-foreground mb-0.5">Cuenta destino</p>
                  <p className="text-sm font-medium font-mono">{payment.destinationAccount ?? '—'}</p>
                </div>
              </div>
            </div>

            {/* Attachment / Upload */}
            <Separator />
            <div>
              <p className="text-[11px] text-muted-foreground uppercase tracking-wider font-semibold mb-3 flex items-center gap-1.5">
                <Paperclip className="w-3.5 h-3.5" /> Comprobante de pago
              </p>

              {isProgramado && !hasAttachment && (
                <div className="flex items-center gap-2 mb-3 px-3 py-2 rounded-lg bg-yellow-50 border border-yellow-200 text-yellow-700">
                  <AlertCircle className="w-3.5 h-3.5 shrink-0" />
                  <p className="text-xs font-medium">Sube un comprobante antes de registrar el pago</p>
                </div>
              )}

              {hasAttachment && (
                <div className="flex flex-wrap gap-2 mb-3">
                  {currentAttachment.map((a, i) => (
                    <div key={i} className="group flex items-center gap-1 pl-3 pr-1.5 py-1.5 rounded-lg bg-primary/10 text-primary text-sm font-medium">
                      <a href={a.url} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1.5 hover:underline">
                        <Paperclip className="w-3.5 h-3.5" />
                        Ver comprobante{currentAttachment.length > 1 ? ` ${i + 1}` : ''}
                      </a>
                      <button
                        onClick={() => handleRemoveAttachment(i)}
                        className="ml-1 p-0.5 rounded opacity-50 hover:opacity-100 hover:text-destructive transition-all"
                        title="Eliminar"
                      >
                        <X className="w-3 h-3" />
                      </button>
                    </div>
                  ))}
                </div>
              )}

              <div
                className={`relative border-2 border-dashed rounded-xl p-5 text-center transition-colors cursor-pointer ${dragging ? 'border-primary bg-primary/5' : 'border-border hover:border-primary/50 hover:bg-muted/30'} ${uploading ? 'pointer-events-none opacity-60' : ''}`}
                onDragOver={e => { e.preventDefault(); setDragging(true); }}
                onDragLeave={() => setDragging(false)}
                onDrop={handleDrop}
                onClick={() => fileInputRef.current?.click()}
              >
                <input
                  ref={fileInputRef}
                  type="file"
                  accept="image/*,application/pdf"
                  className="hidden"
                  onChange={e => { const f = e.target.files?.[0]; if (f) handleUploadFile(f); e.target.value = ''; }}
                />
                {uploading ? (
                  <div className="flex flex-col items-center gap-2">
                    <span className="animate-spin w-6 h-6 border-2 border-primary border-t-transparent rounded-full" />
                    <p className="text-sm text-muted-foreground">Subiendo comprobante…</p>
                  </div>
                ) : (
                  <div className="flex flex-col items-center gap-2">
                    <div className="w-10 h-10 rounded-xl bg-muted flex items-center justify-center">
                      <Upload className="w-5 h-5 text-muted-foreground" />
                    </div>
                    <p className="text-sm font-medium text-foreground">
                      {hasAttachment ? 'Agregar otro comprobante' : 'Subir comprobante'}
                    </p>
                    <p className="text-xs text-muted-foreground">Arrastra un archivo aquí o haz clic para buscar</p>
                    <p className="text-[10px] text-muted-foreground/60">PDF, JPG, PNG · Máx. 10 MB</p>
                  </div>
                )}
              </div>

              {hasAttachment && (
                <div className="pt-3">
                  {payment.supplierEmail ? (
                    <Button
                      variant="outline"
                      size="sm"
                      disabled={sending}
                      className="gap-2 border-primary/40 text-primary hover:bg-primary/5"
                      onClick={handleSendReceipt}
                    >
                      {sending ? (
                        <span className="animate-spin w-3.5 h-3.5 border-2 border-primary border-t-transparent rounded-full" />
                      ) : (
                        <Send className="w-3.5 h-3.5" />
                      )}
                      {sending ? 'Enviando…' : `Enviar comprobante a ${payment.supplierEmail}`}
                    </Button>
                  ) : (
                    <p className="text-xs text-muted-foreground flex items-center gap-1.5">
                      <AlertCircle className="w-3.5 h-3.5" />
                      No se puede enviar: el proveedor no tiene email registrado
                    </p>
                  )}
                </div>
              )}
            </div>

            {/* Notes */}
            {payment.notes && (
              <>
                <Separator />
                <div>
                  <p className="text-[11px] text-muted-foreground uppercase tracking-wider font-semibold mb-2">Notas</p>
                  <div className="bg-muted/40 rounded-lg p-3 text-sm leading-relaxed">{payment.notes}</div>
                </div>
              </>
            )}
          </div>

          {/* Footer */}
          <div className="px-6 py-4 border-t shrink-0">
            {isProgramado ? (
              <div className="flex items-center gap-2">
                <Button variant="ghost" size="sm" className="gap-1.5 text-muted-foreground" onClick={onEdit}>
                  <Pencil className="w-3.5 h-3.5" /> Editar
                </Button>
                <div className="flex-1" />
                <Button
                  variant="outline"
                  className="gap-2 text-destructive border-destructive/30 hover:bg-destructive/10"
                  onClick={() => setCancelConfirmOpen(true)}
                  disabled={cancelling}
                >
                  <XCircle className="w-4 h-4" /> Cancelar pago
                </Button>
                <Button
                  className="gap-2"
                  onClick={handleRegisterPayment}
                  disabled={registering || uploading}
                  title={!hasAttachment ? 'Sube un comprobante primero' : undefined}
                >
                  {registering ? (
                    <span className="animate-spin w-3.5 h-3.5 border-2 border-current border-t-transparent rounded-full" />
                  ) : (
                    <CheckCircle className="w-4 h-4" />
                  )}
                  {registering ? 'Registrando…' : 'Registrar pago'}
                </Button>
              </div>
            ) : (
              <div className="flex gap-2">
                <Button variant="outline" className="gap-2 text-destructive border-destructive/30 hover:bg-destructive/10 flex-1" onClick={onDelete}>
                  <Trash2 className="w-4 h-4" /> Eliminar
                </Button>
                <Button className="gap-2 flex-1" onClick={onEdit}>
                  <Pencil className="w-4 h-4" /> Editar pago
                </Button>
              </div>
            )}
          </div>
        </DialogContent>
      </Dialog>

      {/* Cancel confirmation dialog */}
      <AlertDialog open={cancelConfirmOpen} onOpenChange={setCancelConfirmOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>¿Cancelar este pago?</AlertDialogTitle>
            <AlertDialogDescription>
              El pago {String(payment.paymentId ?? '')} quedará marcado como cancelado. Esta acción no se puede revertir.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Volver</AlertDialogCancel>
            <AlertDialogAction
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              onClick={handleCancelPayment}
            >
              Sí, cancelar pago
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

src/components/dashboard/DraggableWidget.content:
import { ReactNode } from 'react';
import { ChevronUp, ChevronDown, Maximize2, Minimize2 } from 'lucide-react';
import { WIDGET_REGISTRY, LayoutItem, WidgetSize } from './widgetConfig';

interface Props {
  layout: LayoutItem[];
  editing: boolean;
  onLayoutChange: (layout: LayoutItem[]) => void;
  renderWidget: (id: string, size: WidgetSize) => ReactNode;
}

export default function DraggableWidgetGrid({ layout, editing, onLayoutChange, renderWidget }: Props) {
  const moveUp = (id: string) => {
    const idx = layout.findIndex(i => i.id === id);
    if (idx <= 0) return;
    const newLayout = [...layout];
    [newLayout[idx - 1], newLayout[idx]] = [newLayout[idx], newLayout[idx - 1]];
    onLayoutChange(newLayout);
  };

  const moveDown = (id: string) => {
    const idx = layout.findIndex(i => i.id === id);
    if (idx < 0 || idx >= layout.length - 1) return;
    const newLayout = [...layout];
    [newLayout[idx], newLayout[idx + 1]] = [newLayout[idx + 1], newLayout[idx]];
    onLayoutChange(newLayout);
  };

  const toggleSize = (id: string) => {
    onLayoutChange(
      layout.map(item => {
        if (item.id !== id) return item;
        const config = WIDGET_REGISTRY.find(w => w.id === id);
        if (!config || config.allowedSizes.length < 2) return item;
        return { ...item, size: item.size === 'full' ? 'half' : ('full' as WidgetSize) };
      })
    );
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
      {layout.map((item, idx) => {
        const content = renderWidget(item.id, item.size);
        if (content === null) return null;

        const config = WIDGET_REGISTRY.find(w => w.id === item.id);
        const canResize = (config?.allowedSizes.length ?? 0) > 1;
        const isFirst = idx === 0;
        const isLast = idx === layout.length - 1;

        if (!editing) {
          return (
            <div key={item.id} className={item.size === 'full' ? 'lg:col-span-2' : 'lg:col-span-1'}>
              {content}
            </div>
          );
        }

        return (
          <div
            key={item.id}
            className={`relative ${item.size === 'full' ? 'lg:col-span-2' : 'lg:col-span-1'}`}
          >
            {/* Editing outline */}
            <div className="absolute inset-0 border border-dashed border-primary/30 rounded-xl pointer-events-none z-10" />

            {/* Mini toolbar */}
            <div className="absolute top-2 right-2 z-20 bg-card shadow-lg border border-border rounded-lg px-1 py-0.5 flex items-center gap-0.5">
              <button
                onClick={() => moveUp(item.id)}
                disabled={isFirst}
                className="p-1 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition-colors disabled:opacity-30 disabled:cursor-not-allowed"
                title="Mover arriba"
              >
                <ChevronUp className="w-4 h-4" />
              </button>
              <button
                onClick={() => moveDown(item.id)}
                disabled={isLast}
                className="p-1 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition-colors disabled:opacity-30 disabled:cursor-not-allowed"
                title="Mover abajo"
              >
                <ChevronDown className="w-4 h-4" />
              </button>
              {canResize && (
                <>
                  <div className="h-4 w-px bg-border mx-0.5" />
                  <button
                    onClick={() => toggleSize(item.id)}
                    className="p-1 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
                    title={item.size === 'full' ? 'Reducir a mitad' : 'Ampliar a completo'}
                  >
                    {item.size === 'full'
                      ? <Minimize2 className="w-4 h-4" />
                      : <Maximize2 className="w-4 h-4" />
                    }
                  </button>
                </>
              )}
            </div>

            {/* Widget content — rendered normally, no restrictions */}
            {content}
          </div>
        );
      })}
    </div>
  );
}

src/components/finance/ProjectSelectorDi.content:
import { useState, useMemo } from 'react';
import { Search, SortAsc, Clock, ListFilter, Play, Trash2, ChevronDown, Check, X } from 'lucide-react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Checkbox } from '@/components/ui/checkbox';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { ScrollArea } from '@/components/ui/scroll-area';
import { cn } from '@/lib/utils';
import type { GetProjectsOutputType } from 'zite-endpoints-sdk';

type Project = GetProjectsOutputType['projects'][0];

const STATUSES = ['En curso', 'Finalizado', 'Prospecto', 'Cancelado'];

function statusStyle(s: string, active: boolean) {
  if (!active) return 'bg-muted/40 text-muted-foreground border-border hover:bg-muted';
  switch (s) {
    case 'En curso':   return 'bg-primary text-primary-foreground border-primary';
    case 'Finalizado': return 'bg-muted-foreground text-background border-muted-foreground';
    case 'Prospecto':  return 'bg-chart-4 text-background border-chart-4';
    case 'Cancelado':  return 'bg-destructive text-destructive-foreground border-destructive';
    default:           return 'bg-primary text-primary-foreground border-primary';
  }
}

function rowStatusBadge(s?: string) {
  switch (s) {
    case 'En curso':   return 'bg-primary/10 text-primary border-primary/25';
    case 'Finalizado': return 'bg-muted text-muted-foreground border-border';
    case 'Prospecto':  return 'bg-chart-4/10 text-chart-4 border-chart-4/25';
    case 'Cancelado':  return 'bg-destructive/10 text-destructive border-destructive/25';
    default:           return 'bg-muted text-muted-foreground border-border';
  }
}

function getYear(p: Project): string | null {
  const d = p.computedStartDate ?? p.startDate ?? p.computedEndDate ?? p.endDate;
  return d ? d.slice(0, 4) : null;
}

interface Props {
  projects: Project[];
  selectedIds: Set<string>;
  loadingProjects: boolean;
  onConfirm: (ids: Set<string>) => void;
}

export default function ProjectSelectorDialog({ projects, selectedIds, loadingProjects, onConfirm }: Props) {
  const [open, setOpen] = useState(false);
  const [draft, setDraft] = useState<Set<string>>(new Set());
  const [search, setSearch] = useState('');
  const [statusFilters, setStatusFilters] = useState<Set<string>>(new Set());
  const [yearFilters, setYearFilters] = useState<Set<string>>(new Set());
  const [clientFilters, setClientFilters] = useState<Set<string>>(new Set());
  const [sortBy, setSortBy] = useState<'az' | 'reciente'>('az');

  const years = useMemo(() => {
    const s = new Set<string>();
    projects.forEach(p => { const y = getYear(p); if (y) s.add(y); });
    return Array.from(s).sort((a, b) => b.localeCompare(a));
  }, [projects]);

  const clients = useMemo(() => {
    const s = new Set<string>();
    projects.forEach(p => { if (p.client) s.add(p.client); });
    return Array.from(s).sort((a, b) => a.localeCompare(b));
  }, [projects]);

  const handleOpen = () => {
    setDraft(new Set(selectedIds));
    setSearch('');
    setStatusFilters(new Set());
    setYearFilters(new Set());
    setClientFilters(new Set());
    setOpen(true);
  };

  const toggleFilter = (set: Set<string>, val: string, setter: (s: Set<string>) => void) => {
    const n = new Set(set);
    n.has(val) ? n.delete(val) : n.add(val);
    setter(n);
  };

  const filtered = useMemo(() => {
    const q = search.toLowerCase();
    return projects
      .filter(p => {
        const matchSearch = !q ||
          p.projectCode?.toLowerCase().includes(q) ||
          p.fullName?.toLowerCase().includes(q) ||
          p.client?.toLowerCase().includes(q);
        const matchStatus = statusFilters.size === 0 || statusFilters.has(p.status ?? '');
        const matchYear = yearFilters.size === 0 || yearFilters.has(getYear(p) ?? '');
        const matchClient = clientFilters.size === 0 || clientFilters.has(p.client ?? '');
        return matchSearch && matchStatus && matchYear && matchClient;
      })
      .sort((a, b) => {
        if (sortBy === 'az') return (a.projectCode ?? '').localeCompare(b.projectCode ?? '');
        const da = a.computedStartDate ?? a.startDate ?? '';
        const db = b.computedStartDate ?? b.startDate ?? '';
        return db.localeCompare(da);
      });
  }, [projects, search, statusFilters, yearFilters, clientFilters, sortBy]);

  const toggle = (id: string) =>
    setDraft(prev => { const n = new Set(prev); n.has(id) ? n.delete(id) : n.add(id); return n; });

  const allFilteredSel = filtered.length > 0 && filtered.every(p => draft.has(p.id));
  const someFilteredSel = filtered.some(p => draft.has(p.id));
  const isEmpty = draft.size === 0;

  const [clientSearch, setClientSearch] = useState('');
  const [clientPopoverOpen, setClientPopoverOpen] = useState(false);

  const filteredClientOptions = useMemo(() => {
    const q = clientSearch.toLowerCase();
    return q ? clients.filter(c => c.toLowerCase().includes(q)) : clients;
  }, [clients, clientSearch]);

  // Reusable pill component
  const Pill = ({ label, active, onClick }: { label: string; active: boolean; onClick: () => void }) => (
    <button
      onClick={onClick}
      className={cn(
        'px-2.5 py-1 rounded-full text-xs font-medium border transition-colors whitespace-nowrap shrink-0',
        active ? 'bg-primary text-primary-foreground border-primary' : 'bg-muted/40 text-muted-foreground border-border hover:bg-muted'
      )}
    >
      {label}
    </button>
  );

  const SortBtn = ({ label, icon: Icon, val }: { label: string; icon: typeof SortAsc; val: 'az' | 'reciente' }) => (
    <button
      onClick={() => setSortBy(val)}
      className={cn(
        'px-2.5 py-1 rounded-full text-xs font-medium border flex items-center gap-1 transition-colors shrink-0',
        sortBy === val ? 'bg-primary/10 text-primary border-primary/30' : 'bg-muted/40 text-muted-foreground border-border hover:bg-muted'
      )}
    >
      <Icon className="w-3 h-3" />{label}
    </button>
  );

  const FilterLabel = ({ label, count }: { label: string; count: number }) => (
    <span className="text-xs text-muted-foreground font-medium shrink-0 flex items-center gap-1">
      {label}
      {count > 0 && (
        <span className="bg-primary text-primary-foreground rounded-full px-1.5 py-0.5 text-[10px] leading-none font-semibold">
          {count}
        </span>
      )}
    </span>
  );

  return (
    <>
      <Button variant="outline" onClick={handleOpen} disabled={loadingProjects} className="gap-2">
        <ListFilter className="w-4 h-4" />
        Seleccionar proyectos
        <Badge variant="secondary" className="ml-0.5 text-xs">{selectedIds.size}</Badge>
      </Button>

      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent className="sm:max-w-2xl h-[80vh] flex flex-col gap-0 p-0 overflow-hidden">
          <DialogHeader className="px-6 pt-5 pb-4 shrink-0">
            <DialogTitle>Seleccionar proyectos</DialogTitle>
          </DialogHeader>
          <Separator />

          {/* ── Controls ── */}
          <div className="px-6 py-3 space-y-2.5 shrink-0">
            {/* Search */}
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground pointer-events-none" />
              <Input
                className="pl-9"
                placeholder="Buscar por código, nombre o cliente..."
                value={search}
                onChange={e => setSearch(e.target.value)}
                autoFocus
              />
            </div>

            {/* Row 1: Status + Sort */}
            <div className="flex items-center gap-2 overflow-x-auto pb-0.5 no-scrollbar">
              <FilterLabel label="Estado" count={statusFilters.size} />
              <div className="flex items-center gap-1.5 flex-1 overflow-x-auto no-scrollbar">
                {STATUSES.map(s => (
                  <button
                    key={s}
                    onClick={() => toggleFilter(statusFilters, s, setStatusFilters)}
                    className={cn(
                      'px-2.5 py-1 rounded-full text-xs font-medium border transition-colors whitespace-nowrap shrink-0',
                      statusStyle(s, statusFilters.has(s))
                    )}
                  >
                    {s}
                  </button>
                ))}
              </div>
              <div className="flex gap-1.5 shrink-0 ml-2 border-l border-border pl-2">
                <SortBtn label="A-Z" icon={SortAsc} val="az" />
                <SortBtn label="Reciente" icon={Clock} val="reciente" />
              </div>
            </div>

            {/* Row 2: Years */}
            {years.length > 0 && (
              <div className="flex items-center gap-2">
                <FilterLabel label="Año" count={yearFilters.size} />
                <div className="flex items-center gap-1.5 overflow-x-auto no-scrollbar pb-0.5">
                  {years.map(y => (
                    <Pill key={y} label={y} active={yearFilters.has(y)} onClick={() => toggleFilter(yearFilters, y, setYearFilters)} />
                  ))}
                </div>
              </div>
            )}

            {/* Row 3: Clients — combobox popover */}
            {clients.length > 0 && (
              <div className="flex items-center gap-2">
                <FilterLabel label="Cliente" count={clientFilters.size} />
                <Popover open={clientPopoverOpen} onOpenChange={open => { setClientPopoverOpen(open); if (!open) setClientSearch(''); }}>
                  <PopoverTrigger asChild>
                    <button
                      className={cn(
                        'flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium border transition-colors',
                        clientFilters.size > 0
                          ? 'bg-primary/10 text-primary border-primary/30'
                          : 'bg-muted/40 text-muted-foreground border-border hover:bg-muted'
                      )}
                    >
                      {clientFilters.size === 0
                        ? 'Todos los clientes'
                        : clientFilters.size === 1
                          ? Array.from(clientFilters)[0]
                          : `${clientFilters.size} clientes seleccionados`}
                      <ChevronDown className="w-3 h-3 opacity-60" />
                    </button>
                  </PopoverTrigger>
                  <PopoverContent align="start" className="p-0 w-64">
                    <div className="p-2 border-b border-border">
                      <div className="relative">
                        <Search className="absolute left-2 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground pointer-events-none" />
                        <Input
                          className="pl-7 h-7 text-xs"
                          placeholder="Buscar cliente..."
                          value={clientSearch}
                          onChange={e => setClientSearch(e.target.value)}
                          autoFocus
                        />
                      </div>
                    </div>
                    {clientFilters.size > 0 && (
                      <div className="px-2 py-1.5 border-b border-border">
                        <button
                          onClick={() => setClientFilters(new Set())}
                          className="text-xs text-muted-foreground hover:text-foreground flex items-center gap-1"
                        >
                          <X className="w-3 h-3" />Limpiar selección
                        </button>
                      </div>
                    )}
                    <ScrollArea className="max-h-52">
                      <div className="p-1">
                        {filteredClientOptions.length === 0 ? (
                          <p className="text-xs text-muted-foreground text-center py-3">Sin resultados</p>
                        ) : (
                          filteredClientOptions.map(c => (
                            <button
                              key={c}
                              onClick={() => toggleFilter(clientFilters, c, setClientFilters)}
                              className="w-full flex items-center gap-2 px-2 py-1.5 rounded text-xs hover:bg-muted text-left transition-colors"
                            >
                              <div className={cn(
                                'w-3.5 h-3.5 rounded-sm border flex items-center justify-center shrink-0 transition-colors',
                                clientFilters.has(c) ? 'bg-primary border-primary' : 'border-border'
                              )}>
                                {clientFilters.has(c) && <Check className="w-2.5 h-2.5 text-primary-foreground" />}
                              </div>
                              <span className="truncate">{c}</span>
                            </button>
                          ))
                        )}
                      </div>
                    </ScrollArea>
                  </PopoverContent>
                </Popover>
              </div>
            )}

            {/* Quick actions */}
            <div className="flex items-center gap-3 text-xs pt-0.5">
              <Checkbox
                checked={allFilteredSel ? true : someFilteredSel ? 'indeterminate' : false}
                onCheckedChange={v => {
                  if (v) setDraft(prev => { const n = new Set(prev); filtered.forEach(p => n.add(p.id)); return n; });
                  else   setDraft(prev => { const n = new Set(prev); filtered.forEach(p => n.delete(p.id)); return n; });
                }}
              />
              <span className="text-muted-foreground">{filtered.length} visibles</span>
              <span className="text-muted-foreground/40">·</span>
              <button onClick={() => setDraft(new Set(projects.map(p => p.id)))} className="text-primary hover:underline">Todos</button>
              <span className="text-muted-foreground/40">·</span>
              <button onClick={() => setDraft(new Set())} className="text-muted-foreground hover:underline">Ninguno</button>
              <span className="text-muted-foreground/40">·</span>
              <button onClick={() => setDraft(new Set(filtered.map(p => p.id)))} className="text-primary hover:underline">Solo filtrados</button>
            </div>
          </div>

          <Separator />

          {/* ── List ── */}
          <div className="flex-1 min-h-0 overflow-y-auto">
            {filtered.length === 0 ? (
              <div className="h-full flex items-center justify-center text-sm text-muted-foreground">
                No hay proyectos con esos filtros
              </div>
            ) : (
              <div className="divide-y divide-border">
                {filtered.map(p => {
                  const sel = draft.has(p.id);
                  return (
                    <label
                      key={p.id}
                      className={cn(
                        'flex items-center gap-4 px-6 py-3 cursor-pointer transition-colors hover:bg-muted/40 select-none',
                        sel && 'bg-primary/5'
                      )}
                    >
                      <Checkbox checked={sel} onCheckedChange={() => toggle(p.id)} />
                      <span className="font-mono text-xs font-semibold text-muted-foreground w-20 shrink-0">{p.projectCode}</span>
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium text-foreground truncate">{p.fullName ?? p.projectCode}</p>
                        {p.client && <p className="text-xs text-muted-foreground truncate">{p.client}</p>}
                      </div>
                      <div className="flex items-center gap-2 shrink-0">
                        {getYear(p) && <span className="text-xs text-muted-foreground font-mono">{getYear(p)}</span>}
                        {p.status && (
                          <span className={cn('text-xs px-2 py-0.5 rounded-full border', rowStatusBadge(p.status))}>
                            {p.status}
                          </span>
                        )}
                      </div>
                    </label>
                  );
                })}
              </div>
            )}
          </div>

          <Separator />

          {/* ── Footer ── */}
          <div className="px-6 py-4 flex items-center justify-between shrink-0">
            <p className="text-sm text-muted-foreground">
              <span className="font-semibold text-foreground">{draft.size}</span> de {projects.length} seleccionados
            </p>
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => setOpen(false)}>Cancelar</Button>
              {isEmpty ? (
                <Button variant="destructive" onClick={() => { setOpen(false); onConfirm(new Set()); }} className="gap-2">
                  <Trash2 className="w-4 h-4" />Limpiar análisis
                </Button>
              ) : (
                <Button onClick={() => { setOpen(false); onConfirm(new Set(draft)); }} className="gap-2">
                  <Play className="w-4 h-4" />
                  Analizar {draft.size} proyecto{draft.size !== 1 ? 's' : ''}
                </Button>
              )}
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}

