import { useState, useEffect, useRef } from 'react';
import { GetReferenceOptionsOutputType } from 'zite-endpoints-sdk';
import { getReferenceOptionsCached } from '../../../lib/referenceOptionsCache';
import { Loader2 } from 'lucide-react';
import type { TriggerState } from './MentionWrapper';

type Member = GetReferenceOptionsOutputType['members'][0];
type Project = GetReferenceOptionsOutputType['projects'][0];

interface ResultItem {
  kind: 'user' | 'project';
  id: string;
  label: string;
  subtitle: string;
}

interface Props {
  trigger: TriggerState;
  onSelect: (token: string) => void;
  onDismiss: () => void;
}

export default function ReferencePicker({ trigger, onSelect, onDismiss }: Props) {
  const [members, setMembers] = useState<Member[]>([]);
  const [projects, setProjects] = useState<Project[]>([]);
  const [loading, setLoading] = useState(false);
  const [activeIdx, setActiveIdx] = useState(0);
  const loadedRef = useRef(false);

  useEffect(() => {
    if (loadedRef.current) return;
    loadedRef.current = true;
    setLoading(true);
    getReferenceOptionsCached()
      .then(d => { setMembers(d.members); setProjects(d.projects); })
      .catch(() => {})
      .finally(() => setLoading(false));
  }, []);

  const results: ResultItem[] = trigger.type === 'user'
    ? members
        .filter(m => {
          const name = `${m.firstName ?? ''} ${m.lastName ?? ''}`.toLowerCase();
          const q = trigger.query.toLowerCase();
          return !q || name.includes(q) || (m.email ?? '').toLowerCase().includes(q);
        })
        .slice(0, 7)
        .map(m => ({
          kind: 'user',
          id: m.id,
          label: `${m.firstName ?? ''} ${m.lastName ?? ''}`.trim() || m.email || '?',
          subtitle: m.email ?? '',
        }))
    : projects
        .filter(p => {
          const q = trigger.query.toLowerCase();
          return !q || p.code.toLowerCase().includes(q) || (p.name ?? '').toLowerCase().includes(q);
        })
        .slice(0, 7)
        .map(p => ({
          kind: 'project',
          id: p.code,
          label: p.name ?? p.code,
          subtitle: p.status ?? p.code,
        }));

  // Reset active index when results/query change
  useEffect(() => { setActiveIdx(0); }, [trigger.query, trigger.type]);

  const handleSelect = (item: ResultItem) => {
    const token = item.kind === 'user'
      ? `[[user:${item.id}|${item.label}]]`
      : `[[project:${item.id}|${item.label}]]`;
    onSelect(token);
  };

  // Keyboard navigation
  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === 'ArrowDown') { e.preventDefault(); setActiveIdx(i => Math.min(i + 1, results.length - 1)); }
      else if (e.key === 'ArrowUp') { e.preventDefault(); setActiveIdx(i => Math.max(i - 1, 0)); }
      else if (e.key === 'Enter') { e.preventDefault(); if (results[activeIdx]) handleSelect(results[activeIdx]); }
      else if (e.key === 'Escape') { e.preventDefault(); onDismiss(); }
    };
    document.addEventListener('keydown', handleKey, true);
    return () => document.removeEventListener('keydown', handleKey, true);
  }, [results, activeIdx, onDismiss]);

  // Position: below caret, edge-aware
  const { rect } = trigger;
  const top = rect.bottom + window.scrollY + 6;
  const left = Math.min(rect.left + window.scrollX, window.innerWidth - 264);

  return (
    <div
      style={{ top, left, width: 256 }}
      className="fixed z-[9999] bg-card border border-border rounded-xl shadow-lg overflow-hidden"
    >
      <div className="px-3 py-1.5 border-b border-border/60 flex items-center gap-1.5 text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">
        {trigger.type === 'user' ? (
          <><span className="text-base leading-none">👤</span> Personas</>
        ) : (
          <><span className="text-base leading-none">📁</span> Proyectos</>
        )}
      </div>

      {loading ? (
        <div className="flex items-center justify-center py-5 gap-2 text-xs text-muted-foreground">
          <Loader2 className="w-3.5 h-3.5 animate-spin" /> Cargando...
        </div>
      ) : results.length === 0 ? (
        <div className="px-3 py-3 text-xs text-muted-foreground/60 italic">
          {trigger.query ? `Sin resultados para "${trigger.query}"` : 'Empieza a escribir para buscar...'}
        </div>
      ) : (
        <div className="max-h-56 overflow-y-auto">
          {results.map((item, idx) => (
            <button
              key={`${item.kind}-${item.id}`}
              onMouseDown={e => { e.preventDefault(); handleSelect(item); }}
              className={`w-full flex items-center gap-2.5 px-3 py-2 text-left transition-colors ${
                idx === activeIdx ? 'bg-primary/10' : 'hover:bg-muted'
              }`}
            >
              <div className={`w-7 h-7 rounded-full flex items-center justify-center flex-shrink-0 text-xs font-bold ${
                item.kind === 'user'
                  ? 'bg-chart-2/20 text-chart-2'
                  : 'bg-chart-4/20 text-chart-4'
              }`}>
                {item.kind === 'user' ? (item.label[0]?.toUpperCase() ?? '?') : '#'}
              </div>
              <div className="min-w-0 flex-1">
                <div className={`text-sm font-medium truncate ${idx === activeIdx ? 'text-primary' : 'text-foreground'}`}>
                  {item.label}
                </div>
                <div className="text-xs text-muted-foreground truncate">{item.subtitle}</div>
              </div>
            </button>
          ))}
        </div>
      )}

      <div className="px-3 py-1.5 border-t border-border/40 text-[10px] text-muted-foreground/40 flex items-center gap-2">
        <span>↑↓ navegar</span><span>·</span><span>Enter seleccionar</span><span>·</span><span>Esc cerrar</span>
      </div>
    </div>
  );
}

src/components/commercial-dashboard/Funn.content:
import { ChartDataPoint } from '@/lib/commercial-dashboard/types';
import { PHASE_COLOR_MAP } from '@/components/commercial/dealUtils';

interface Props {
  data: ChartDataPoint[];
}

export default function FunnelWidget({ data }: Props) {
  const max = Math.max(...data.map(d => d.value), 1);
  const topValue = data[0]?.value ?? 1;
  if (data.length === 0) return <div className="text-center text-sm text-muted-foreground py-8">Sin datos</div>;

  return (
    <div className="space-y-1.5 py-2">
      {data.map(item => {
        const widthPct = Math.max((item.value / max) * 100, 8);
        const convPct = topValue > 0 ? ((item.value / topValue) * 100).toFixed(0) : '0';
        const color = PHASE_COLOR_MAP[item.label] ?? 'hsl(var(--primary))';
        return (
          <div key={item.label} className="flex items-center gap-2">
            <div className="w-28 text-xs text-right text-muted-foreground truncate shrink-0">{item.label}</div>
            <div className="flex-1 flex justify-center">
              <div
                className="flex items-center justify-center h-7 rounded text-xs font-semibold text-white transition-all"
                style={{ width: `${widthPct}%`, backgroundColor: color }}
              >
                {item.value}
              </div>
            </div>
            <div className="w-10 text-xs text-muted-foreground text-right shrink-0">{convPct}%</div>
          </div>
        );
      })}
    </div>
  );
}

src/components/commercial/CotizacionRubr.content:
import { AccordionContent, AccordionItem, AccordionTrigger } from '@/components/ui/accordion';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Checkbox } from '@/components/ui/checkbox';
import NumericInput from '@/components/NumericInput';
import { Plus, Trash2 } from 'lucide-react';
import { fmtMoneyFull } from './dealUtils';

export type LineItemLocal = {
  localId: string;
  subRubro: string;
  cantidad: number;
  componentes: number;
  unitCost: number;
  hasMarkup: boolean;
  markupPct: number;
};

export function calcBase(item: LineItemLocal): number {
  return item.cantidad * item.componentes * item.unitCost;
}

export function calcFinal(item: LineItemLocal): number {
  const base = calcBase(item);
  return item.hasMarkup ? base * (1 + item.markupPct / 100) : base;
}

interface Props {
  rubro: string;
  items: LineItemLocal[];
  currencySymbol: string;
  readOnly?: boolean;
  onUpdate: (items: LineItemLocal[]) => void;
}

const GRID = 'grid-cols-[1fr_52px_52px_80px_28px_52px_80px_80px_28px]';

export default function CotizacionRubroSection({ rubro, items, currencySymbol, readOnly = false, onUpdate }: Props) {
  const subtotalBase = items.reduce((s, i) => s + calcBase(i), 0);
  const subtotalFinal = items.reduce((s, i) => s + calcFinal(i), 0);

  const addItem = () => onUpdate([...items, {
    localId: Math.random().toString(36).slice(2),
    subRubro: '', cantidad: 0, componentes: 0, unitCost: 0, hasMarkup: false, markupPct: 0,
  }]);

  const update = (localId: string, patch: Partial<LineItemLocal>) =>
    onUpdate(items.map(it => it.localId === localId ? { ...it, ...patch } : it));

  const remove = (localId: string) => onUpdate(items.filter(it => it.localId !== localId));

  const visibleItems = readOnly
    ? items.filter(i => i.cantidad > 0 || i.unitCost > 0)
    : items;

  return (
    <AccordionItem value={rubro} className="border rounded-lg px-3 mb-1">
      <AccordionTrigger className="text-sm font-semibold hover:no-underline py-3">
        <div className="flex items-center gap-3 w-full pr-2">
          <span>{rubro}</span>
          {visibleItems.length > 0 && (
            <span className="ml-auto text-xs font-normal text-muted-foreground">
              {visibleItems.length} ítem{visibleItems.length !== 1 ? 's' : ''} · Costo: {fmtMoneyFull(subtotalBase, currencySymbol)} · Precio: {fmtMoneyFull(subtotalFinal, currencySymbol)}
            </span>
          )}
        </div>
      </AccordionTrigger>
      <AccordionContent>
        <div className="pb-3 space-y-1.5">
          {visibleItems.length > 0 && (
            <div className={`grid ${GRID} gap-1 text-xs text-muted-foreground px-1 mb-1`}>
              <span>Sub-rubro</span>
              <span title="Unidades de cotización">UDC</span>
              <span title="Componentes por UDC">Comp.</span>
              <span>P. unit.</span>
              <span title="Markup">MU</span>
              <span>%</span>
              <span>Costo</span>
              <span>Precio</span>
              <span />
            </div>
          )}
          {visibleItems.map(item => {
            const base = calcBase(item);
            const final = calcFinal(item);
            return (
              <div key={item.localId} className={`grid ${GRID} gap-1 items-center`}>
                {readOnly ? (
                  <span className="text-xs px-1 truncate">{item.subRubro || '—'}</span>
                ) : (
                  <Input
                    value={item.subRubro}
                    onChange={e => update(item.localId, { subRubro: e.target.value })}
                    placeholder="Nombre"
                    className="h-7 text-xs px-2"
                  />
                )}
                {readOnly ? (
                  <span className="text-xs px-1 tabular-nums">{item.cantidad}</span>
                ) : (
                  <NumericInput value={item.cantidad} min={0} onChange={v => update(item.localId, { cantidad: v })} className="h-7 text-xs px-2" title="UDC — unidades de cotización" />
                )}
                {readOnly ? (
                  <span className="text-xs px-1 tabular-nums">{item.componentes}</span>
                ) : (
                  <NumericInput value={item.componentes} min={0} onChange={v => update(item.localId, { componentes: v })} className="h-7 text-xs px-2" title="Componentes por UDC" />
                )}
                {readOnly ? (
                  <span className="text-xs px-1 tabular-nums">{fmtMoneyFull(item.unitCost, currencySymbol)}</span>
                ) : (
                  <NumericInput value={item.unitCost} min={0} onChange={v => update(item.localId, { unitCost: v })} className="h-7 text-xs px-2" title="Precio unitario" />
                )}
                {readOnly ? (
                  <span className="text-xs px-1 text-muted-foreground">{item.hasMarkup ? '✓' : '—'}</span>
                ) : (
                  <Checkbox checked={item.hasMarkup} onCheckedChange={v => update(item.localId, { hasMarkup: Boolean(v) })} />
                )}
                {readOnly ? (
                  <span className="text-xs px-1 tabular-nums text-muted-foreground">{item.hasMarkup ? `${item.markupPct}%` : '—'}</span>
                ) : (
                  <NumericInput value={item.markupPct} min={0} disabled={!item.hasMarkup} onChange={v => update(item.localId, { markupPct: v })} className="h-7 text-xs px-2 disabled:opacity-40" />
                )}
                {/* Costo base (sin markup) */}
                <div className="text-xs text-muted-foreground text-right pr-1 tabular-nums">
                  {fmtMoneyFull(base, currencySymbol)}
                </div>
                {/* Precio final (con markup) */}
                <div className="text-xs font-medium text-right pr-1 tabular-nums">
                  {fmtMoneyFull(final, currencySymbol)}
                </div>
                {readOnly ? (
                  <span />
                ) : (
                  <Button size="icon" variant="ghost" className="h-6 w-6 text-destructive" onClick={() => remove(item.localId)}>
                    <Trash2 className="w-3 h-3" />
                  </Button>
                )}
              </div>
            );
          })}
          {!readOnly && (
            <Button size="sm" variant="ghost" className="gap-1 text-xs h-7 text-muted-foreground" onClick={addItem}>
              <Plus className="w-3 h-3" /> Sub-rubro
            </Button>
          )}
        </div>
      </AccordionContent>
    </AccordionItem>
  );
}

