src/components/expenses/ExcelImportExpen.content:
import { useState, useRef, useCallback } from 'react';
import { uploadFile } from 'zite-file-upload-sdk';
import { parseExcelFile } from 'zite-endpoints-sdk';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { ScrollArea } from '@/components/ui/scroll-area';
import { FileSpreadsheet, Upload, Loader2, AlertCircle, CheckCircle2 } from 'lucide-react';
import { toast } from 'sonner';
import type { LineItem } from './ExpenseFormSheet';

// Field targets for mapping
const TARGETS = [
  { value: '__skip__', label: '— Ignorar —' },
  { value: 'description', label: 'Descripción' },
  { value: 'category', label: 'Categoría' },
  { value: 'amount', label: 'Monto' },
  { value: 'date', label: 'Fecha' },
  { value: 'notes', label: 'Notas' },
] as const;

type TargetKey = 'description' | 'category' | 'amount' | 'date' | 'notes' | '__skip__';

const CATEGORIES = ['Viáticos', 'Transporte', 'Alimentación', 'Hospedaje', 'Compras menores', 'Papelería', 'Materiales', 'Otros'];

// Auto-detect column mappings from header names
function autoDetect(headers: string[]): Record<number, TargetKey> {
  const map: Record<number, TargetKey> = {};
  const used = new Set<TargetKey>();

  const rules: { patterns: string[]; target: TargetKey }[] = [
    { patterns: ['descripcion', 'description', 'concepto', 'detalle', 'nombre', 'item'], target: 'description' },
    { patterns: ['monto', 'amount', 'importe', 'total', 'valor', 'precio', 'costo'], target: 'amount' },
    { patterns: ['fecha', 'date', 'dia', 'día', 'cuando'], target: 'date' },
    { patterns: ['categoria', 'category', 'tipo', 'rubro', 'type'], target: 'category' },
    { patterns: ['notas', 'notes', 'nota', 'comentario', 'observacion', 'observación', 'remarks'], target: 'notes' },
  ];

  headers.forEach((h, i) => {
    const norm = h.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
    for (const rule of rules) {
      if (!used.has(rule.target) && rule.patterns.some(p => norm.includes(p))) {
        map[i] = rule.target;
        used.add(rule.target);
        return;
      }
    }
    map[i] = '__skip__';
  });

  return map;
}

// Parse a cell value as a date → YYYY-MM-DD
function parseDate(raw: string): string {
  if (!raw) return '';
  // Excel serial date number
  const num = Number(raw);
  if (!isNaN(num) && num > 1000 && num < 100000) {
    const d = new Date((num - 25569) * 86400 * 1000);
    if (!isNaN(d.getTime())) return d.toISOString().split('T')[0];
  }
  // Try parsing common date strings
  const cleaned = raw.replace(/\//g, '-');
  const d = new Date(cleaned);
  if (!isNaN(d.getTime())) return d.toISOString().split('T')[0];
  return '';
}

// Parse a cell value as a number
function parseAmount(raw: string): number {
  const cleaned = raw.replace(/[$,\s]/g, '').replace(',', '.');
  const n = parseFloat(cleaned);
  return isNaN(n) ? 0 : n;
}

// Match category by fuzzy comparison
function matchCategory(raw: string): string {
  if (!raw) return '';
  const norm = raw.toLowerCase();
  return CATEGORIES.find(c => c.toLowerCase().includes(norm) || norm.includes(c.toLowerCase())) ?? raw;
}

function rowToLineItem(row: string[], mapping: Record<number, TargetKey>, defaultDate: string): LineItem {
  const line: LineItem = { description: '', category: '', amount: 0, date: defaultDate, receipt: [], notes: '' };
  Object.entries(mapping).forEach(([colStr, target]) => {
    if (target === '__skip__') return;
    const val = row[Number(colStr)] ?? '';
    if (target === 'description') line.description = val;
    else if (target === 'category') line.category = matchCategory(val);
    else if (target === 'amount') line.amount = parseAmount(val);
    else if (target === 'date') line.date = parseDate(val) || defaultDate;
    else if (target === 'notes') line.notes = val;
  });
  return line;
}

interface Props {
  open: boolean;
  onClose: () => void;
  onImport: (lines: LineItem[]) => void;
  defaultDate: string;
}

type Step = 'upload' | 'mapping' | 'preview';

export default function ExcelImportExpenseDialog({ open, onClose, onImport, defaultDate }: Props) {
  const [step, setStep] = useState<Step>('upload');
  const [uploading, setUploading] = useState(false);
  const [parsing, setParsing] = useState(false);
  const [headers, setHeaders] = useState<string[]>([]);
  const [rows, setRows] = useState<string[][]>([]);
  const [mapping, setMapping] = useState<Record<number, TargetKey>>({});
  const [fileName, setFileName] = useState('');
  const [isDragging, setIsDragging] = useState(false);
  const fileRef = useRef<HTMLInputElement>(null);

  const reset = () => {
    setStep('upload');
    setHeaders([]);
    setRows([]);
    setMapping({});
    setFileName('');
  };

  const handleClose = () => { reset(); onClose(); };

  const processFile = useCallback(async (file: File) => {

    setUploading(true);
    setFileName(file.name);
    try {
      const { fileUrl } = await uploadFile({ data: file, filename: file.name });
      setParsing(true);
      setUploading(false);
      const result = await parseExcelFile({ fileUrl, fileName: file.name });
      const allRows = result.rows;
      if (!result.headers.length && !allRows.length) {
        toast.error('El archivo está vacío o no tiene datos detectables');
        setParsing(false);
        return;
      }
      setHeaders(result.headers);
      setRows(allRows);
      setMapping(autoDetect(result.headers));
      setStep('mapping');
    } catch (err: unknown) {
      toast.error((err as { message?: string })?.message ?? 'Error al leer el archivo');
    }
    setUploading(false);
    setParsing(false);
  }, []);

  const handleFile = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    e.target.value = '';
    if (file) processFile(file);
  }, [processFile]);

  const handleDragOver = (e: React.DragEvent) => { e.preventDefault(); setIsDragging(true); };
  const handleDragLeave = (e: React.DragEvent) => { e.preventDefault(); setIsDragging(false); };
  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files?.[0];
    if (file) processFile(file);
  };

  const previewRows = rows.slice(0, 5);

  const mappedLines = rows
    .map(r => rowToLineItem(r, mapping, defaultDate))
    .filter(l => l.description.trim() || l.amount > 0);

  const hasDescription = Object.values(mapping).includes('description');
  const hasAmount = Object.values(mapping).includes('amount');

  const handleConfirm = () => {
    if (mappedLines.length === 0) {
      toast.error('No hay filas válidas para importar');
      return;
    }
    onImport(mappedLines);
    handleClose();
    toast.success(`${mappedLines.length} partida${mappedLines.length !== 1 ? 's' : ''} importada${mappedLines.length !== 1 ? 's' : ''}`);
  };

  return (
    <Dialog open={open} onOpenChange={v => { if (!v) handleClose(); }}>
      <DialogContent className="max-w-3xl max-h-[85vh] flex flex-col p-0 gap-0">
        <DialogHeader className="px-6 pt-5 pb-4 border-b border-border flex-shrink-0">
          <DialogTitle className="text-base flex items-center gap-2">
            <FileSpreadsheet className="w-4 h-4 text-primary" />
            Importar partidas desde Excel / CSV
          </DialogTitle>
        </DialogHeader>

        <ScrollArea className="flex-1 min-h-0">
          <div className="px-6 py-5">

            {/* Step: Upload */}
            {step === 'upload' && (
              <div className="flex flex-col items-center justify-center py-10 gap-4">
                <div
                  className={`w-full border-2 border-dashed rounded-xl p-10 flex flex-col items-center gap-3 cursor-pointer transition-colors ${isDragging ? 'border-primary bg-primary/5' : 'border-border hover:border-primary hover:bg-muted/30'}`}
                  onClick={() => fileRef.current?.click()}
                  onDragOver={handleDragOver}
                  onDragEnter={handleDragOver}
                  onDragLeave={handleDragLeave}
                  onDrop={handleDrop}
                >
                  {uploading || parsing ? (
                    <Loader2 className="w-8 h-8 text-primary animate-spin" />
                  ) : (
                    <Upload className="w-8 h-8 text-muted-foreground" />
                  )}
                  <div className="text-center">
                    <p className="text-sm font-medium">
                      {uploading ? 'Subiendo archivo...' : parsing ? 'Procesando...' : 'Haz clic para seleccionar archivo'}
                    </p>
                    <p className="text-xs text-muted-foreground mt-1">Excel (.xlsx) o CSV — máx. 10 MB</p>
                  </div>
                </div>
                <div className="flex items-start gap-2 text-xs text-muted-foreground bg-muted/40 rounded-lg p-3 w-full">
                  <AlertCircle className="w-3.5 h-3.5 mt-0.5 flex-shrink-0" />
                  <span>
                    El archivo debe tener encabezados en la primera fila. Columnas sugeridas:{' '}
                    <strong>Descripción, Categoría, Monto, Fecha, Notas</strong>
                  </span>
                </div>
                <input ref={fileRef} type="file" className="hidden" accept=".xlsx,.xls,.csv"
                  onChange={handleFile} />
              </div>
            )}

            {/* Step: Mapping */}
            {step === 'mapping' && (
              <div className="space-y-5">
                <div className="flex items-center gap-2 text-xs text-muted-foreground bg-muted/40 rounded-lg px-3 py-2">
                  <CheckCircle2 className="w-3.5 h-3.5 text-emerald-500 flex-shrink-0" />
                  <span>
                    <strong>{fileName}</strong> — {rows.length} fila{rows.length !== 1 ? 's' : ''} detectada{rows.length !== 1 ? 's' : ''}.
                    Asigna cada columna al campo correspondiente.
                  </span>
                </div>

                {/* Column mapping */}
                <div className="border border-border rounded-lg overflow-hidden">
                  <table className="w-full text-xs">
                    <thead className="bg-muted/50 border-b border-border">
                      <tr>
                        <th className="text-left px-3 py-2 font-medium text-muted-foreground">Columna en Excel</th>
                        <th className="text-left px-3 py-2 font-medium text-muted-foreground">Ejemplo de dato</th>
                        <th className="text-left px-3 py-2 font-medium text-muted-foreground w-44">Mapear a campo</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-border">
                      {headers.map((h, i) => (
                        <tr key={i} className="hover:bg-muted/20">
                          <td className="px-3 py-2 font-medium">{h || `Columna ${i + 1}`}</td>
                          <td className="px-3 py-2 text-muted-foreground truncate max-w-[160px]">
                            {rows[0]?.[i] ?? '—'}
                          </td>
                          <td className="px-3 py-2">
                            <Select
                              value={mapping[i] ?? '__skip__'}
                              onValueChange={v => setMapping(prev => ({ ...prev, [i]: v as TargetKey }))}
                            >
                              <SelectTrigger className="h-7 text-xs w-40">
                                <SelectValue />
                              </SelectTrigger>
                              <SelectContent>
                                {TARGETS.map(t => (
                                  <SelectItem key={t.value} value={t.value}>{t.label}</SelectItem>
                                ))}
                              </SelectContent>
                            </Select>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>

                {(!hasDescription || !hasAmount) && (
                  <div className="flex items-center gap-2 text-xs text-amber-600 bg-amber-50 border border-amber-200 rounded-lg px-3 py-2">
                    <AlertCircle className="w-3.5 h-3.5 flex-shrink-0" />
                    <span>
                      {!hasDescription && !hasAmount
                        ? 'Asigna al menos una columna a Descripción y una a Monto.'
                        : !hasDescription
                          ? 'Recuerda asignar una columna a Descripción.'
                          : 'Recuerda asignar una columna a Monto.'}
                    </span>
                  </div>
                )}

                {/* Preview table */}
                <div className="space-y-1.5">
                  <p className="text-xs font-medium text-muted-foreground">Vista previa (primeras {Math.min(5, rows.length)} filas)</p>
                  <div className="border border-border rounded-lg overflow-x-auto">
                    <table className="w-full text-xs">
                      <thead className="bg-muted/50 border-b border-border">
                        <tr>
                          <th className="text-left px-3 py-1.5 font-medium text-muted-foreground">Descripción</th>
                          <th className="text-left px-3 py-1.5 font-medium text-muted-foreground">Categoría</th>
                          <th className="text-right px-3 py-1.5 font-medium text-muted-foreground">Monto</th>
                          <th className="text-left px-3 py-1.5 font-medium text-muted-foreground">Fecha</th>
                          <th className="text-left px-3 py-1.5 font-medium text-muted-foreground">Notas</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-border">
                        {previewRows.map((row, ri) => {
                          const line = rowToLineItem(row, mapping, defaultDate);
                          return (
                            <tr key={ri} className="hover:bg-muted/20">
                              <td className="px-3 py-1.5 truncate max-w-[160px]">{line.description || <span className="text-muted-foreground italic">—</span>}</td>
                              <td className="px-3 py-1.5 truncate max-w-[100px]">{line.category || <span className="text-muted-foreground italic">—</span>}</td>
                              <td className="px-3 py-1.5 text-right tabular-nums">
                                {line.amount > 0 ? line.amount.toLocaleString('es-MX', { minimumFractionDigits: 2 }) : <span className="text-muted-foreground italic">—</span>}
                              </td>
                              <td className="px-3 py-1.5">{line.date || <span className="text-muted-foreground italic">—</span>}</td>
                              <td className="px-3 py-1.5 truncate max-w-[120px]">{line.notes || <span className="text-muted-foreground italic">—</span>}</td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  </div>
                  {rows.length > 5 && (
                    <p className="text-xs text-muted-foreground text-right">
                      …y {rows.length - 5} fila{rows.length - 5 !== 1 ? 's' : ''} más
                    </p>
                  )}
                </div>
              </div>
            )}
          </div>
        </ScrollArea>

        <DialogFooter className="px-6 py-4 border-t border-border flex-shrink-0 flex items-center justify-between gap-2">
          <div className="text-xs text-muted-foreground">
            {step === 'mapping' && mappedLines.length > 0 && (
              <span className="text-emerald-600 font-medium">{mappedLines.length} partida{mappedLines.length !== 1 ? 's' : ''} listas para importar</span>
            )}
          </div>
          <div className="flex items-center gap-2">
            {step === 'mapping' && (
              <Button variant="ghost" size="sm" onClick={() => { reset(); }} className="text-xs">
                Cambiar archivo
              </Button>
            )}
            <Button variant="ghost" size="sm" onClick={handleClose} className="text-xs">Cancelar</Button>
            {step === 'mapping' && (
              <Button size="sm" onClick={handleConfirm} disabled={mappedLines.length === 0} className="text-xs min-w-[120px]">
                Importar {mappedLines.length > 0 ? `${mappedLines.length} partida${mappedLines.length !== 1 ? 's' : ''}` : ''}
              </Button>
            )}
          </div>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

src/components/commercial-dashboard/Char.content:
import { useState } from 'react';
import {
  BarChart, Bar, LineChart, Line, PieChart, Pie, Cell,
  XAxis, YAxis, Tooltip, ResponsiveContainer, Legend,
  ScatterChart, Scatter, ZAxis, CartesianGrid,
} from 'recharts';
import { Deal, WidgetConfig, DateReference } from '@/lib/commercial-dashboard/types';
import { METRIC_LABELS } from '@/lib/commercial-dashboard/constants';
import { buildChartData } from '@/lib/commercial-dashboard/chartData';
import RankingTableWidget, { fmtMetric } from './RankingTableWidget';
import FunnelWidget from './FunnelWidget';
import DrillDownSheet from './DrillDownSheet';

const COLORS = [
  'hsl(var(--chart-1))', 'hsl(var(--chart-2))', 'hsl(var(--chart-3))',
  'hsl(var(--chart-4))', 'hsl(var(--chart-5))',
];

interface Props {
  widget: WidgetConfig;
  deals: Deal[];
  dateRef: DateReference;
}

export default function ChartRenderer({ widget, deals, dateRef }: Props) {
  const { chartType, metric, displayOptions, compareBy } = widget;
  const currency = widget.currency;
  const data = buildChartData(deals, widget, dateRef);
  const fmt = (v: number) => fmtMetric(v, metric, currency);
  const showLegend = displayOptions.showLegend ?? false;

  const [drillDown, setDrillDown] = useState<{ title: string; deals: Deal[] } | null>(null);

  function handleBarClick(entry: any) {
    if (!entry?.activePayload?.[0]) return;
    const label = entry.activePayload[0].payload?.label;
    const point = data.find(d => d.label === label);
    if (point?.deals?.length) {
      setDrillDown({ title: `${widget.name} — ${label}`, deals: point.deals });
    }
  }

  function handlePieClick(_: any, index: number) {
    const point = data[index];
    if (point?.deals?.length) {
      setDrillDown({ title: `${widget.name} — ${point.label}`, deals: point.deals });
    }
  }

  function handleScatterClick(entry: any) {
    const name = entry?.name;
    const point = data.find(d => d.label === name);
    if (point?.deals?.length) {
      setDrillDown({ title: `${widget.name} — ${name}`, deals: point.deals });
    }
  }

  const sheet = (
    <DrillDownSheet
      title={drillDown?.title ?? ''}
      deals={drillDown?.deals ?? []}
      open={!!drillDown}
      onClose={() => setDrillDown(null)}
    />
  );

  if (data.length === 0) return (
    <>
      <div className="flex items-center justify-center h-40 text-sm text-muted-foreground">
        Sin datos para el período seleccionado
      </div>
      {sheet}
    </>
  );

  // Multi-series mode (comparative)
  const isMultiSeries = !!(compareBy && data[0]?.series);
  if (isMultiSeries) {
    const seriesKeys = Object.keys(data[0].series!);
    const flatData = data.map(d => ({ label: d.label, ...d.series, _deals: d.deals }));
    const chartHeight = seriesKeys.length > 8 ? 280 : 240;
    const legendStyle = { fontSize: 11, maxHeight: 60, overflowY: 'auto' as const };

    if (chartType === 'line') {
      return (
        <>
          <ResponsiveContainer width="100%" height={chartHeight}>
            <LineChart data={flatData} margin={{ top: 5, right: 10, left: 5, bottom: 5 }} onClick={handleBarClick}>
              <XAxis dataKey="label" tick={{ fontSize: 11 }} />
              <YAxis tick={{ fontSize: 11 }} tickFormatter={fmt} width={60} />
              <Tooltip formatter={(v: number) => fmt(v)} />
              <Legend wrapperStyle={legendStyle} />
              {seriesKeys.map((sk, i) => (
                <Line key={sk} type="monotone" dataKey={sk} stroke={COLORS[i % COLORS.length]}
                  strokeWidth={2} dot={false} cursor="pointer" />
              ))}
            </LineChart>
          </ResponsiveContainer>
          {sheet}
        </>
      );
    }

    // Grouped bar chart
    return (
      <>
        <ResponsiveContainer width="100%" height={chartHeight}>
          <BarChart data={flatData} margin={{ top: 5, right: 10, left: 5, bottom: 5 }} onClick={handleBarClick}>
            <XAxis dataKey="label" tick={{ fontSize: 11 }} />
            <YAxis tick={{ fontSize: 11 }} tickFormatter={fmt} width={60} />
            <Tooltip formatter={(v: number) => fmt(v)} />
            <Legend wrapperStyle={legendStyle} />
            {seriesKeys.map((sk, i) => (
              <Bar key={sk} dataKey={sk} fill={COLORS[i % COLORS.length]} radius={[3, 3, 0, 0]} cursor="pointer" />
            ))}
          </BarChart>
        </ResponsiveContainer>
        {sheet}
      </>
    );
  }

  // Scatter chart
  if (chartType === 'scatter') {
    const { metricY = 'dealCount' } = widget;
    const fmtY = (v: number) => fmtMetric(v, metricY, currency);
    const scatterData = data.map(d => ({ x: d.value, y: d.valueY ?? 0, name: d.label }));
    return (
      <>
        <ResponsiveContainer width="100%" height={260}>
          <ScatterChart margin={{ top: 10, right: 20, left: 5, bottom: 20 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
            <XAxis
              dataKey="x" type="number" tickFormatter={fmt} tick={{ fontSize: 11 }} width={60}
              label={{ value: METRIC_LABELS[metric], position: 'insideBottom', offset: -12, fontSize: 11, fill: 'hsl(var(--muted-foreground))' }}
            />
            <YAxis
              dataKey="y" type="number" tickFormatter={fmtY} tick={{ fontSize: 11 }} width={60}
              label={{ value: METRIC_LABELS[metricY], angle: -90, position: 'insideLeft', offset: 10, fontSize: 11, fill: 'hsl(var(--muted-foreground))' }}
            />
            <ZAxis range={[50, 50]} />
            <Tooltip
              cursor={{ strokeDasharray: '3 3' }}
              content={({ active, payload }) => {
                if (!active || !payload?.length) return null;
                const p = payload[0].payload as { x: number; y: number; name: string };
                return (
                  <div className="bg-card border border-border rounded-lg p-2 text-xs shadow-md space-y-1">
                    <p className="font-semibold text-foreground">{p.name}</p>
                    <p className="text-muted-foreground">{METRIC_LABELS[metric]}: <span className="text-foreground font-medium">{fmt(p.x)}</span></p>
                    <p className="text-muted-foreground">{METRIC_LABELS[metricY]}: <span className="text-foreground font-medium">{fmtY(p.y)}</span></p>
                  </div>
                );
              }}
            />
            <Scatter data={scatterData} fill="hsl(var(--primary))" fillOpacity={0.8} cursor="pointer" onClick={handleScatterClick} />
          </ScatterChart>
        </ResponsiveContainer>
        {sheet}
      </>
    );
  }

  // Single-series mode (existing)
  if (chartType === 'rankingTable') return <>{<RankingTableWidget data={data} metric={metric} currency={currency} />}{sheet}</>;
  if (chartType === 'funnel') return <>{<FunnelWidget data={data} />}{sheet}</>;

  if (chartType === 'pie' || chartType === 'donut') {
    return (
      <>
        <ResponsiveContainer width="100%" height={220}>
          <PieChart>
            <Pie data={data} dataKey="value" nameKey="label" cx="50%" cy="50%"
              innerRadius={chartType === 'donut' ? '45%' : 0} outerRadius="70%"
              cursor="pointer" onClick={handlePieClick}>
              {data.map((_, i) => <Cell key={i} fill={COLORS[i % COLORS.length]} />)}
            </Pie>
            <Tooltip formatter={(v: number) => fmt(v)} />
            {showLegend && <Legend />}
          </PieChart>
        </ResponsiveContainer>
        {sheet}
      </>
    );
  }

  if (chartType === 'line') {
    return (
      <>
        <ResponsiveContainer width="100%" height={220}>
          <LineChart data={data} margin={{ top: 5, right: 10, left: 5, bottom: 5 }} onClick={handleBarClick}>
            <XAxis dataKey="label" tick={{ fontSize: 11 }} />
            <YAxis tick={{ fontSize: 11 }} tickFormatter={fmt} width={60} />
            <Tooltip formatter={fmt} />
            <Line type="monotone" dataKey="value" stroke="hsl(var(--primary))" strokeWidth={2} dot={false} cursor="pointer" />
            {showLegend && <Legend />}
          </LineChart>
        </ResponsiveContainer>
        {sheet}
      </>
    );
  }

  return (
    <>
      <ResponsiveContainer width="100%" height={220}>
        <BarChart data={data} margin={{ top: 5, right: 10, left: 5, bottom: 5 }} onClick={handleBarClick}>
          <XAxis dataKey="label" tick={{ fontSize: 11 }} />
          <YAxis tick={{ fontSize: 11 }} tickFormatter={fmt} width={60} />
          <Tooltip formatter={fmt} />
          <Bar dataKey="value" fill="hsl(var(--primary))" radius={[3, 3, 0, 0]} cursor="pointer" />
          {showLegend && <Legend />}
        </BarChart>
      </ResponsiveContainer>
      {sheet}
    </>
  );
}

src/components/commercial/brief/EntityMe.content:
import { useState, useEffect, useRef } from 'react';
import { GetReferenceOptionsOutputType } from 'zite-endpoints-sdk';
import { getReferenceOptionsCached } from '../../../lib/referenceOptionsCache';
import { Loader2 } from 'lucide-react';
import type { TriggerState, RefInline } from './docTypes';

type Member = GetReferenceOptionsOutputType['members'][0];
type Project = GetReferenceOptionsOutputType['projects'][0];
type EventItem = GetReferenceOptionsOutputType['events'][0];
type GroupItem = GetReferenceOptionsOutputType['groups'][0];
type Item = { kind: 'user' | 'project' | 'event' | 'group'; id: string; label: string; subtitle: string };

const TYPE_META: Record<string, { icon: string; label: string }> = {
  user:    { icon: '👤', label: 'Personas' },
  project: { icon: '📁', label: 'Proyectos' },
  event:   { icon: '📅', label: 'Eventos' },
  group:   { icon: '👥', label: 'Grupos' },
};

const AVATAR_COLORS: Record<string, string> = {
  user:    'bg-chart-1/20 text-chart-1',
  project: 'bg-chart-2/20 text-chart-2',
  event:   'bg-chart-4/20 text-chart-4',
  group:   'bg-chart-5/20 text-chart-5',
};

interface Props {
  trigger: TriggerState | null;
  onSelect: (ref: RefInline) => void;
  onDismiss: () => void;
}

export default function EntityMentionMenu({ trigger, onSelect, onDismiss }: Props) {
  const [members, setMembers] = useState<Member[]>([]);
  const [projects, setProjects] = useState<Project[]>([]);
  const [events, setEvents] = useState<EventItem[]>([]);
  const [groups, setGroups] = useState<GroupItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [activeIdx, setActiveIdx] = useState(0);
  const loaded = useRef(false);
  const onDismissRef = useRef(onDismiss);
  const itemsRef = useRef<Item[]>([]);
  const activeIdxRef = useRef(0);

  useEffect(() => { onDismissRef.current = onDismiss; }, [onDismiss]);

  useEffect(() => {
    if (!trigger || loaded.current) return;
    loaded.current = true;
    setLoading(true);
    getReferenceOptionsCached()
      .then(d => { setMembers(d.members); setProjects(d.projects); setEvents(d.events); setGroups(d.groups); })
      .catch(() => {})
      .finally(() => setLoading(false));
  }, [trigger]);

  useEffect(() => { setActiveIdx(0); }, [trigger?.type, trigger?.query]);

  useEffect(() => {
    if (!trigger) return;
    const handler = (e: KeyboardEvent) => {
      const its = itemsRef.current;
      const ai = activeIdxRef.current;
      if (e.key === 'ArrowDown') { e.preventDefault(); e.stopImmediatePropagation(); setActiveIdx(Math.min(ai + 1, its.length - 1)); }
      else if (e.key === 'ArrowUp') { e.preventDefault(); e.stopImmediatePropagation(); setActiveIdx(Math.max(ai - 1, 0)); }
      else if (e.key === 'Enter') { e.preventDefault(); e.stopImmediatePropagation(); if (its[ai]) onSelect({ type: 'ref', refType: its[ai].kind, refId: its[ai].id, label: its[ai].label }); }
      else if (e.key === 'Escape') { e.preventDefault(); e.stopImmediatePropagation(); onDismissRef.current(); }
    };
    document.addEventListener('keydown', handler, true);
    return () => document.removeEventListener('keydown', handler, true);
  }, [trigger, onSelect]);

  if (!trigger) return null;

  const q = trigger.query.toLowerCase();

  const items: Item[] = (() => {
    switch (trigger.type) {
      case 'user':
        return members
          .filter(m => { const n = `${m.firstName ?? ''} ${m.lastName ?? ''}`.toLowerCase(); return !q || n.includes(q) || (m.email ?? '').toLowerCase().includes(q); })
          .slice(0, 7)
          .map(m => ({ kind: 'user' as const, id: m.id, label: `${m.firstName ?? ''} ${m.lastName ?? ''}`.trim() || m.email || '?', subtitle: m.email ?? '' }));
      case 'project':
        return projects
          .filter(p => !q || p.code.toLowerCase().includes(q) || (p.name ?? '').toLowerCase().includes(q))
          .slice(0, 7)
          .map(p => ({ kind: 'project' as const, id: p.code, label: p.name ?? p.code, subtitle: p.code }));
      case 'event':
        return events
          .filter(e => !q || e.name.toLowerCase().includes(q) || (e.projectCode ?? '').toLowerCase().includes(q))
          .slice(0, 7)
          .map(e => ({ kind: 'event' as const, id: e.id, label: e.name, subtitle: e.date ? new Date(e.date).toLocaleDateString() : (e.projectCode ?? '') }));
      case 'group':
        return groups
          .filter(g => !q || g.name.toLowerCase().includes(q) || (g.projectCode ?? '').toLowerCase().includes(q))
          .slice(0, 7)
          .map(g => ({ kind: 'group' as const, id: g.name, label: g.name, subtitle: g.projectCode ?? '' }));
      default:
        return [];
    }
  })();

  itemsRef.current = items;
  activeIdxRef.current = activeIdx;

  const meta = TYPE_META[trigger.type] ?? TYPE_META.user;
  const avatarColor = AVATAR_COLORS[trigger.type] ?? AVATAR_COLORS.user;

  const top = trigger.rect.bottom + window.scrollY + 6;
  const left = Math.min(trigger.rect.left + window.scrollX, window.innerWidth - 264);

  return (
    <div style={{ top, left, width: 256 }} className="fixed z-[9999] bg-card border border-border rounded-xl shadow-lg overflow-hidden">
      <div className="px-3 py-1.5 border-b border-border/60 flex items-center gap-1.5 text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">
        <span className="text-base leading-none">{meta.icon}</span> {meta.label}
      </div>
      {loading ? (
        <div className="flex items-center justify-center py-5 gap-2 text-xs text-muted-foreground"><Loader2 className="w-3.5 h-3.5 animate-spin" /> Cargando...</div>
      ) : items.length === 0 ? (
        <div className="px-3 py-3 text-xs text-muted-foreground/60 italic">{q ? `Sin resultados para "${q}"` : 'Empieza a escribir...'}</div>
      ) : (
        <div className="max-h-56 overflow-y-auto">
          {items.map((item, idx) => (
            <button key={`${item.kind}-${item.id}`} onMouseDown={e => { e.preventDefault(); onSelect({ type: 'ref', refType: item.kind, refId: item.id, label: item.label }); }}
              className={`w-full flex items-center gap-2.5 px-3 py-2 text-left transition-colors ${idx === activeIdx ? 'bg-primary/10' : 'hover:bg-muted'}`}>
              <div className={`w-7 h-7 rounded-full flex items-center justify-center flex-shrink-0 text-xs font-bold ${avatarColor}`}>
                {item.kind === 'user' ? (item.label[0]?.toUpperCase() ?? '?') : item.kind === 'project' ? '#' : item.kind === 'event' ? '!' : '/'}
              </div>
              <div className="min-w-0 flex-1">
                <div className={`text-sm font-medium truncate ${idx === activeIdx ? 'text-primary' : 'text-foreground'}`}>{item.label}</div>
                <div className="text-xs text-muted-foreground truncate">{item.subtitle}</div>
              </div>
            </button>
          ))}
        </div>
      )}
      <div className="px-3 py-1.5 border-t border-border/40 text-[10px] text-muted-foreground/40 flex items-center gap-2">
        <span>↑↓ navegar</span><span>·</span><span>Enter seleccionar</span><span>·</span><span>Esc cerrar</span>
      </div>
    </div>
  );
}

src/components/commercial-dashboard/Dril.content:
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import { Badge } from '@/components/ui/badge';
import { Deal } from '@/lib/commercial-dashboard/types';
import { useMemo } from 'react';

function fmtCurrency(n: number) {
  return n.toLocaleString('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 0, maximumFractionDigits: 0 });
}

function AmountCell({ deal }: { deal: Deal }) {
  const price = deal.clientPrice ?? 0;
  const isUSD = deal.currency?.startsWith('USD');
  const rate = deal.exchangeRate ?? 20;
  const mxnEquiv = price * rate;

  if (!isUSD) {
    return <span className="tabular-nums">{fmtCurrency(price)}</span>;
  }

  return (
    <TooltipProvider delayDuration={200}>
      <Tooltip>
        <TooltipTrigger asChild>
          <span className="tabular-nums cursor-help inline-flex items-center gap-1.5">
            {fmtCurrency(price)}
            <Badge variant="outline" className="text-[10px] px-1 py-0 font-normal leading-tight">USD 🇺🇸</Badge>
          </span>
        </TooltipTrigger>
        <TooltipContent side="left" className="text-xs">
          <p>≈ {fmtCurrency(mxnEquiv)} MXN</p>
          <p className="text-muted-foreground">TC: {rate.toFixed(4)}{!deal.exchangeRate ? ' (estimado)' : ''}</p>
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}

const PHASE_COLORS: Record<string, string> = {
  Prospecto: 'bg-muted text-muted-foreground',
  'Brief recibido': 'bg-muted text-muted-foreground',
  'Cotización enviada': 'bg-accent text-accent-foreground',
  Negociación: 'bg-accent text-accent-foreground',
  Ganado: 'bg-primary/15 text-primary',
  Perdido: 'bg-destructive/15 text-destructive',
};

interface Props {
  title: string;
  deals: Deal[];
  open: boolean;
  onClose: () => void;
}

export default function DrillDownSheet({ title, deals, open, onClose }: Props) {
  const sorted = useMemo(() => [...deals].sort((a, b) => (b.clientPrice ?? 0) - (a.clientPrice ?? 0)), [deals]);

  const breakdown = useMemo(() => {
    let mxnNative = 0, usdNative = 0, usdConverted = 0;
    for (const d of sorted) {
      const p = d.clientPrice ?? 0;
      if (d.currency?.startsWith('USD')) {
        usdNative += p;
        usdConverted += p * (d.exchangeRate ?? 20);
      } else {
        mxnNative += p;
      }
    }
    return { mxnNative, usdNative, usdConverted, total: mxnNative + usdConverted };
  }, [sorted]);

  const hasUsd = breakdown.usdNative > 0;

  return (
    <Dialog open={open} onOpenChange={v => { if (!v) onClose(); }}>
      <DialogContent className="max-w-3xl max-h-[80vh] overflow-y-auto p-0">
        <DialogHeader className="px-5 pt-5 pb-3 border-b sticky top-0 bg-background z-10">
          <DialogTitle className="text-base">{title}</DialogTitle>
          <p className="text-xs text-muted-foreground">{sorted.length} deal{sorted.length !== 1 ? 's' : ''}</p>
        </DialogHeader>

        <div className="divide-y">
          {sorted.map(d => (
            <div key={d.id} className="flex items-center gap-3 px-5 py-2.5 hover:bg-muted/40 transition-colors">
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium truncate">{d.dealName || 'Sin nombre'}</p>
                <p className="text-xs text-muted-foreground truncate">{d.client || '—'}</p>
              </div>
              <div className="text-right shrink-0">
                <div className="text-sm font-medium">
                  <AmountCell deal={d} />
                </div>
              </div>
              <Badge variant="secondary" className={`shrink-0 text-[10px] ${PHASE_COLORS[d.phase ?? ''] ?? ''}`}>
                {d.phase ?? '—'}
              </Badge>
            </div>
          ))}
          {sorted.length === 0 && (
            <div className="text-center text-sm text-muted-foreground py-12">Sin deals en este segmento</div>
          )}
        </div>

        {sorted.length > 0 && (
          <div className="sticky bottom-0 bg-background border-t px-5 py-3 space-y-1">
            {hasUsd ? (
              <>
                <div className="flex justify-between text-xs text-muted-foreground">
                  <span>MXN nativo</span>
                  <span className="tabular-nums">{fmtCurrency(breakdown.mxnNative)}</span>
                </div>
                <div className="flex justify-between text-xs text-muted-foreground">
                  <span>USD convertido</span>
                  <span className="tabular-nums">≈ {fmtCurrency(breakdown.usdConverted)}</span>
                </div>
                <div className="flex justify-between text-sm font-semibold pt-1 border-t">
                  <span>Total MXN</span>
                  <span className="tabular-nums">{fmtCurrency(breakdown.total)}</span>
                </div>
              </>
            ) : (
              <div className="flex justify-between text-sm font-semibold">
                <span>Total</span>
                <span className="tabular-nums">{fmtCurrency(breakdown.total)}</span>
              </div>
            )}
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

src/components/commercial-dashboard/Char.content:
import { useState, useEffect, useMemo } from 'react';
import { Sheet, SheetContent, SheetHeader, SheetTitle } from '@/components/ui/sheet';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { WidgetConfig, MetricKey, GroupByKey, ChartType, WidgetSize, Deal, DateReference } from '@/lib/commercial-dashboard/types';
import { METRIC_LABELS, GROUPBY_LABELS, CHART_TYPE_LABELS, VALID_GROUPBY_FOR_METRIC, getValidCharts, GROUPBY_CATEGORIES, COMPARE_DIMENSIONS } from '@/lib/commercial-dashboard/constants';
import { getGroupKey } from '@/lib/commercial-dashboard/grouping';
import ChartRenderer from './ChartRenderer';
import { BarChart3, TrendingUp, PieChart, Table2, Filter, Crosshair, CircleDot, type LucideIcon } from 'lucide-react';

const CHART_ICONS: Record<ChartType, LucideIcon> = {
  bar: BarChart3,
  line: TrendingUp,
  pie: PieChart,
  donut: CircleDot,
  rankingTable: Table2,
  funnel: Filter,
  scatter: Crosshair,
};

interface Props {
  open: boolean;
  onClose: () => void;
  initial?: WidgetConfig | null;
  deals: Deal[];
  dateRef: DateReference;
  onSave: (w: WidgetConfig) => void;
}

function genId() { return `widget_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`; }

function getAvailableCompareValues(deals: Deal[], compareBy: GroupByKey, dateRef: DateReference): string[] {
  const seen = new Set<string>();
  for (const d of deals) {
    const v = getGroupKey(d, compareBy, dateRef);
    if (v && !v.startsWith('Sin ') && v !== 'Otro') seen.add(v);
  }
  if (compareBy === 'year') return [...seen].sort().reverse();
  return [...seen].sort();
}

const AUTO_LIMITS = [5, 8, 10, 15, 20];

export default function ChartBuilderModal({ open, onClose, initial, deals, dateRef, onSave }: Props) {
  const [metric, setMetric] = useState<MetricKey>('revenue');
  const [groupBy, setGroupBy] = useState<GroupByKey>('month');
  const [chartType, setChartType] = useState<ChartType>('bar');
  const [name, setName] = useState('');
  const [size, setSize] = useState<WidgetSize>('half');
  const [metricY, setMetricY] = useState<MetricKey>('dealCount');
  const [currency, setCurrency] = useState<'all' | 'MXN' | 'USD'>('all');
  const [compareEnabled, setCompareEnabled] = useState(false);
  const [compareBy, setCompareBy] = useState<GroupByKey>('year');
  const [compareMode, setCompareMode] = useState<'auto' | 'manual'>('auto');
  const [compareValues, setCompareValues] = useState<string[]>([]);
  const [autoLimit, setAutoLimit] = useState(10);

  useEffect(() => {
    if (open) {
      setMetric(initial?.metric ?? 'revenue');
      setGroupBy(initial?.groupBy ?? 'month');
      setChartType(initial?.chartType ?? 'bar');
      setName(initial?.name ?? '');
      setSize(initial?.size ?? 'half');
      setMetricY(initial?.metricY ?? 'dealCount');
      setCurrency(initial?.currency ?? 'all');
      setCompareEnabled(!!initial?.compareBy);
      setCompareBy(initial?.compareBy ?? 'year');
      setCompareMode(initial?.compareMode ?? 'auto');
      setCompareValues(initial?.compareValues ?? []);
      setAutoLimit(initial?.displayOptions?.limit ?? 10);
    }
  }, [open, initial]);

  const validGroupBys = VALID_GROUPBY_FOR_METRIC[metric];
  const validCharts = getValidCharts(metric, groupBy);
  const isScatter = chartType === 'scatter';
  const supportsCompare = (chartType === 'bar' || chartType === 'line') && !isScatter;
  const validCompareDimensions = COMPARE_DIMENSIONS.filter(d => d.key !== groupBy);

  const availableCompareValues = useMemo(
    () => getAvailableCompareValues(deals, compareBy, dateRef),
    [deals, compareBy, dateRef]
  );

  function onMetricChange(m: MetricKey) {
    setMetric(m);
    const vg = VALID_GROUPBY_FOR_METRIC[m];
    const newGb = vg.includes(groupBy) ? groupBy : vg[0];
    setGroupBy(newGb);
    const vc = getValidCharts(m, newGb);
    if (!vc.includes(chartType)) setChartType(vc[0]);
  }

  function onGroupByChange(g: GroupByKey) {
    setGroupBy(g);
    const vc = getValidCharts(metric, g);
    if (!vc.includes(chartType)) setChartType(vc[0]);
    if (g === compareBy) { setCompareEnabled(false); setCompareValues([]); }
  }

  function onCompareByChange(cb: GroupByKey) {
    setCompareBy(cb);
    setCompareValues([]);
  }

  function toggleCompareValue(val: string) {
    setCompareValues(prev =>
      prev.includes(val) ? prev.filter(v => v !== val) : [...prev, val]
    );
  }

  const previewWidget: WidgetConfig = {
    id: 'preview', name, metric, groupBy, chartType, size: 'full', filters: null,
    displayOptions: { limit: compareEnabled && supportsCompare ? autoLimit : 8, sortDirection: 'desc', showLegend: false },
    compareBy: compareEnabled && supportsCompare ? compareBy : undefined,
    compareValues: compareEnabled && supportsCompare && compareMode === 'manual' && compareValues.length > 0 ? compareValues : undefined,
    compareMode: compareEnabled && supportsCompare ? compareMode : undefined,
    metricY: isScatter ? metricY : undefined,
    currency,
  };

  function handleSave() {
    const shouldCompare = compareEnabled && supportsCompare;
    const displayOpts = shouldCompare
      ? { limit: autoLimit, sortDirection: 'desc' as const, showLegend: false }
      : (initial?.displayOptions ?? { limit: 8, sortDirection: 'desc' as const, showLegend: false });

    onSave({
      ...previewWidget,
      id: initial?.id ?? genId(),
      name: name.trim() || (isScatter
        ? `${METRIC_LABELS[metric]} vs ${METRIC_LABELS[metricY]} por ${GROUPBY_LABELS[groupBy]}`
        : `${METRIC_LABELS[metric]} por ${GROUPBY_LABELS[groupBy]}`),
      size,
      displayOptions: displayOpts,
      compareBy: shouldCompare ? compareBy : undefined,
      compareValues: shouldCompare && compareMode === 'manual' && compareValues.length > 0 ? compareValues : undefined,
      compareMode: shouldCompare ? compareMode : undefined,
      metricY: isScatter ? metricY : undefined,
      currency,
    });
    onClose();
  }

  return (
    <Sheet open={open} onOpenChange={v => !v && onClose()}>
      <SheetContent className="w-full sm:max-w-xl overflow-y-auto" side="right">
        <SheetHeader><SheetTitle>{initial ? 'Editar gráfica' : 'Agregar gráfica'}</SheetTitle></SheetHeader>
        <div className="mt-6 space-y-5">

          {/* Sentence builder */}
          <div className="bg-muted/50 rounded-xl p-4 space-y-3">
            <p className="text-xs text-muted-foreground font-medium uppercase tracking-wide">Configurar</p>
            <div className="flex flex-wrap items-center gap-2 text-sm">
              <span className="text-muted-foreground">{isScatter ? 'Eje X' : 'Mostrar'}</span>
              <select value={metric} onChange={e => onMetricChange(e.target.value as MetricKey)}
                className="border rounded-md px-2 py-1 text-sm bg-background font-medium">
                {(Object.keys(METRIC_LABELS) as MetricKey[]).map(m => <option key={m} value={m}>{METRIC_LABELS[m]}</option>)}
              </select>
              {isScatter && (
                <>
                  <span className="text-muted-foreground">Eje Y</span>
                  <select value={metricY} onChange={e => setMetricY(e.target.value as MetricKey)}
                    className="border rounded-md px-2 py-1 text-sm bg-background font-medium">
                    {(Object.keys(METRIC_LABELS) as MetricKey[]).map(m => <option key={m} value={m}>{METRIC_LABELS[m]}</option>)}
                  </select>
                </>
              )}
              <span className="text-muted-foreground">por</span>
              <select value={groupBy} onChange={e => onGroupByChange(e.target.value as GroupByKey)}
                className="border rounded-md px-2 py-1 text-sm bg-background font-medium">
                {GROUPBY_CATEGORIES.map(cat => (
                  <optgroup key={cat.label} label={cat.label}>
                    {cat.keys.filter(k => validGroupBys.includes(k)).map(k => <option key={k} value={k}>{GROUPBY_LABELS[k]}</option>)}
                  </optgroup>
                ))}
              </select>
            </div>

            {/* Currency picker */}
            <div className="space-y-1.5 pt-1">
              <p className="text-xs text-muted-foreground">Moneda</p>
              <div className="flex gap-1.5">
                {([
                  { value: 'all', label: 'Todas (→MXN)' },
                  { value: 'MXN', label: 'Solo MXN' },
                  { value: 'USD', label: 'Solo USD' },
                ] as const).map(opt => (
                  <button
                    key={opt.value}
                    onClick={() => setCurrency(opt.value)}
                    className={`px-3 py-1.5 rounded-lg border text-xs font-medium transition-colors ${
                      currency === opt.value
                        ? 'bg-primary text-primary-foreground border-primary'
                        : 'bg-background border-border hover:bg-muted text-foreground'
                    }`}
                  >
                    {opt.label}
                  </button>
                ))}
              </div>
            </div>

            {/* Chart type picker */}
            <div className="space-y-1.5 pt-1">
              <p className="text-xs text-muted-foreground">Tipo de gráfica</p>
              <div className="flex flex-wrap gap-2">
                {validCharts.map(c => {
                  const Icon = CHART_ICONS[c];
                  const selected = chartType === c;
                  return (
                    <button
                      key={c}
                      onClick={() => setChartType(c)}
                      className={`flex flex-col items-center gap-1 px-3 py-2 rounded-lg border text-xs font-medium transition-colors min-w-[64px] ${
                        selected
                          ? 'bg-primary text-primary-foreground border-primary'
                          : 'bg-background border-border hover:bg-muted text-foreground'
                      }`}
                    >
                      <Icon size={18} />
                      {CHART_TYPE_LABELS[c]}
                    </button>
                  );
                })}
              </div>
            </div>
          </div>

          {/* Compare section */}
          {supportsCompare && (
            <div className="space-y-3">
              <div className="flex items-center gap-3">
                <Switch checked={compareEnabled} onCheckedChange={v => { setCompareEnabled(v); if (!v) setCompareValues([]); }} />
                <Label className="cursor-pointer" onClick={() => setCompareEnabled(e => !e)}>
                  Comparar series
                </Label>
              </div>

              {compareEnabled && (
                <div className="bg-muted/40 border rounded-xl p-3 space-y-3">
                  {/* Dimension selector */}
                  <div className="flex flex-wrap items-center gap-2 text-sm">
                    <span className="text-muted-foreground">Comparar por</span>
                    <select value={compareBy} onChange={e => onCompareByChange(e.target.value as GroupByKey)}
                      className="border rounded-md px-2 py-1 text-sm bg-background font-medium">
                      {validCompareDimensions.map(d => <option key={d.key} value={d.key}>{d.label}</option>)}
                    </select>
                  </div>

                  {/* Auto / Manual toggle */}
                  <div className="flex gap-1 p-0.5 bg-muted rounded-lg w-fit">
                    {(['auto', 'manual'] as const).map(m => (
                      <button key={m} onClick={() => setCompareMode(m)}
                        className={`px-3 py-1 rounded-md text-xs font-medium transition-colors ${compareMode === m ? 'bg-background shadow-sm' : 'text-muted-foreground hover:text-foreground'}`}>
                        {m === 'auto' ? '✦ Automático' : '✎ Manual'}
                      </button>
                    ))}
                  </div>

                  {/* Auto mode: pick top-N limit */}
                  {compareMode === 'auto' && (
                    <div className="space-y-1.5">
                      <p className="text-xs text-muted-foreground">Mostrar top:</p>
                      <div className="flex gap-1.5 flex-wrap">
                        {AUTO_LIMITS.map(n => (
                          <button key={n} onClick={() => setAutoLimit(n)}
                            className={`px-3 py-1 rounded-full text-xs border font-medium transition-colors ${autoLimit === n ? 'bg-primary text-primary-foreground border-primary' : 'hover:bg-muted border-border'}`}>
                            {n}
                          </button>
                        ))}
                      </div>
                      <p className="text-xs text-muted-foreground italic">
                        Seleccionará automáticamente los {autoLimit} {GROUPBY_LABELS[compareBy].toLowerCase()}s con mayor {METRIC_LABELS[metric].toLowerCase()}
                      </p>
                    </div>
                  )}

                  {/* Manual mode: chip picker, no limit */}
                  {compareMode === 'manual' && (
                    <div className="space-y-2">
                      <div className="flex items-center justify-between">
                        <p className="text-xs text-muted-foreground">
                          {compareValues.length > 0
                            ? <span className="text-primary font-medium">{compareValues.length} seleccionado(s)</span>
                            : 'Selecciona los valores a comparar'}
                        </p>
                        <div className="flex gap-2">
                          <button onClick={() => setCompareValues(availableCompareValues)}
                            className="text-xs text-primary hover:underline">Todos</button>
                          {compareValues.length > 0 && (
                            <button onClick={() => setCompareValues([])}
                              className="text-xs text-muted-foreground hover:underline">Limpiar</button>
                          )}
                        </div>
                      </div>
                      {availableCompareValues.length === 0 ? (
                        <p className="text-xs text-muted-foreground italic">Sin valores disponibles</p>
                      ) : (
                        <div className="flex flex-wrap gap-1.5 max-h-40 overflow-y-auto pr-1">
                          {availableCompareValues.map(val => {
                            const selected = compareValues.includes(val);
                            return (
                              <button key={val} onClick={() => toggleCompareValue(val)}
                                className={`px-2.5 py-1 rounded-full text-xs border font-medium transition-colors ${selected ? 'bg-primary text-primary-foreground border-primary' : 'hover:bg-muted border-border'}`}>
                                {val}
                              </button>
                            );
                          })}
                        </div>
                      )}
                    </div>
                  )}
                </div>
              )}
            </div>
          )}

          {/* Preview */}
          <div className="border rounded-xl p-3 bg-card">
            <p className="text-xs text-muted-foreground mb-2">Vista previa</p>
            <ChartRenderer widget={previewWidget} deals={deals.slice(0, 500)} dateRef={dateRef} />
          </div>

          {/* Name */}
          <div className="space-y-1.5">
            <Label>Nombre</Label>
            <Input value={name} onChange={e => setName(e.target.value)} placeholder={`${METRIC_LABELS[metric]} por ${GROUPBY_LABELS[groupBy]}`} />
          </div>

          {/* Size */}
          <div className="space-y-1.5">
            <Label>Tamaño</Label>
            <div className="flex gap-2">
              {(['half', 'full'] as WidgetSize[]).map(s => (
                <button key={s} onClick={() => setSize(s)}
                  className={`flex-1 py-2 rounded-lg border text-sm font-medium transition-colors ${size === s ? 'bg-primary text-primary-foreground border-primary' : 'hover:bg-muted'}`}>
                  {s === 'half' ? '½ Pantalla' : 'Completo'}
                </button>
              ))}
            </div>
          </div>

          <Button className="w-full" onClick={handleSave}>{initial ? 'Guardar cambios' : 'Agregar gráfica'}</Button>
        </div>
      </SheetContent>
    </Sheet>
  );
}

