    expenseDate: z.string().optional(),
    notes: z.string().optional(),
    receipt: z.array(z.object({ url: z.string(), name: z.string() })).optional(),
    pettyCashFundId: z.string().optional(),
    lineItems: z.array(lineItemSchema).optional(),
    deletedLineItemIds: z.array(z.string()).optional(),
  }),
  outputSchema: z.object({ id: z.string(), success: z.boolean() }),
  execute: async ({ input, context }) => {
    const userName = [context.user!.firstName, context.user!.lastName].filter(Boolean).join(' ') || context.user!.email;
    const fundLink = input.pettyCashFundId ? [input.pettyCashFundId] : ([] as string[]);
    const receiptAttachments = input.receipt?.map(r => ({ url: r.url }));

    // Calculate total from line items if provided
    const hasLines = input.lineItems && input.lineItems.length > 0;
    const linesTotal = hasLines
      ? input.lineItems!.reduce((s, l) => s + (l.amount ?? 0), 0)
      : undefined;
    const amount = linesTotal ?? input.amount ?? 0;

    let expenseId: string;

    if (input.id) {
      const existing = await Expenses.findOne({ id: input.id });
      if (!existing) throw new ZiteError({ code: 'NOT_FOUND', message: 'Gasto no encontrado' });

      const isAdmin = ['Admin', 'Admin Financiero', 'Finanzas'].includes(context.user!.role ?? '');
      if (existing.createdBy !== context.user!.email && !isAdmin) {
        throw new ZiteError({ code: 'FORBIDDEN', message: 'Solo el creador puede editar este gasto' });
      }
      if (existing.status !== 'Borrador' && existing.status !== 'Rechazado') {
        throw new ZiteError({ code: 'BAD_REQUEST', message: 'Solo se pueden editar gastos en estado Borrador o Rechazado' });
      }

      await Expenses.update({
        id: input.id,
        record: {
          description: input.description,
          amount,
          category: input.category,
          paymentMethod: input.paymentMethod,
          costCenter: input.costCenter,
          projectCode: input.projectCode,
          currency: input.currency ?? 'MXN',
          expenseDate: input.expenseDate,
          notes: input.notes,
          receipt: receiptAttachments as { url: string }[] | undefined,
          pettyCashFund: fundLink,
        },
      });

      expenseId = input.id;

      await ExpenseAuditLog.create({
        record: {
          timestamp: new Date().toISOString(),
          expense: input.id,
          action: 'Editado',
          userEmail: context.user!.email,
          userName,
          expenseNumber: String(existing.expenseNumber ?? ''),
        },
      });
    } else {
      const created = await Expenses.create({
        record: {
          description: input.description,
          amount,
          category: input.category,
          paymentMethod: input.paymentMethod,
          costCenter: input.costCenter,
          projectCode: input.projectCode,
          currency: input.currency ?? 'MXN',
          expenseDate: input.expenseDate,
          notes: input.notes,
          receipt: receiptAttachments as { url: string }[] | undefined,
          status: 'Borrador',
          createdBy: context.user!.email,
          pettyCashFund: fundLink,
        },
      });

      expenseId = created.id;

      await ExpenseAuditLog.create({
        record: {
          timestamp: new Date().toISOString(),
          expense: created.id,
          action: 'Creado',
          userEmail: context.user!.email,
          userName,
          expenseNumber: String((created as unknown as { expenseNumber?: number }).expenseNumber ?? ''),
        },
      });
    }

    // Handle deletions
    if (input.deletedLineItemIds?.length) {
      await Promise.all(input.deletedLineItemIds.map(id => ExpenseLineItems.delete({ id })));
    }

    // Handle line items creates/updates
    if (input.lineItems && input.lineItems.length > 0) {
      const toCreate = input.lineItems.filter(li => !li.id);
      const toUpdate = input.lineItems.filter(li => !!li.id);

      if (toCreate.length > 0) {
        await ExpenseLineItems.bulkCreate({
          records: toCreate.map(li => ({
            description: li.description,
            expense: expenseId,
            category: li.category,
            amount: li.amount,
            date: li.date,
            receipt: li.receipt?.map(r => ({ url: r.url })) as { url: string }[] | undefined,
            notes: li.notes,
          })),
        });
      }

      for (const li of toUpdate) {
        await ExpenseLineItems.update({
          id: li.id!,
          record: {
            description: li.description,
            category: li.category,
            amount: li.amount,
            date: li.date,
            receipt: li.receipt?.map(r => ({ url: r.url })) as { url: string }[] | undefined,
            notes: li.notes,
          },
        });
      }
    }

    return { id: expenseId, success: true };
  },
});

import { z } from 'zod';
import { createEndpoint, Payments, PurchaseOrders } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Create or update a payment',
  inputSchema: z.object({
    id: z.string().optional(),
    poId: z.string().optional(),
    supplierName: z.string().optional(),
    projectCode: z.string().optional(),
    amount: z.number().optional(),
    currency: z.string().optional(),
    paymentDate: z.string().optional(),
    dueDate: z.string().optional(),
    method: z.string().optional(),
    reference: z.string().optional(),
    status: z.string().optional(),
    notes: z.string().optional(),
    supplierInvoiceNumber: z.string().optional(),
    destinationAccount: z.string().optional(),
    sourceCompany: z.string().optional(),
    sourceBank: z.string().optional(),
    sourceAccount: z.string().optional(),
    attachment: z.array(z.object({ url: z.string() })).optional(),
  }),
  outputSchema: z.object({ success: z.boolean(), id: z.string() }),
  execute: async ({ input }) => {
    const { id, poId, ...rest } = input;

    // If poId provided, enrich from PO
    let supplierName = rest.supplierName;
    let projectCode = rest.projectCode;
    if (poId) {
      const po = await PurchaseOrders.findOne({ id: poId });
      if (!po) throw new Error('ODC no encontrada.');
      if (po.status !== 'Enviada a aprobación' && po.status !== 'Aprobada') {
        throw new Error(`No se puede registrar un pago para una ODC con status "${po.status}". Solo se permiten ODCs Enviadas o Aprobadas.`);
      }
      supplierName = supplierName || po.supplierName;
      projectCode = projectCode || po.projectCode;
      // Auto-fill sourceCompany from PO's billingEntity if not explicitly provided
      if (!rest.sourceCompany && po.billingEntity) {
        rest.sourceCompany = po.billingEntity;
      }
    }

    const record = {
      ...rest,
      poId,
      supplierName,
      projectCode,
      type: 'Pago a proveedor' as const,
      ...(input.attachment !== undefined ? { attachment: input.attachment } : {}),
    };

    // Auto-fill payment date when marking as Realizado
    if (input.status === 'Realizado' && !input.paymentDate) {
      record.paymentDate = new Date().toISOString().split('T')[0];
    }

    if (id) {
      // Prevent changing status if payment is already Realizado or Cancelado
      if (input.status) {
        const existing = await Payments.findOne({ id });
        if (existing && (existing.status === 'Realizado' || existing.status === 'Cancelado')) {
          throw new Error(`No se puede cambiar el status de un pago "${existing.status}".`);
        }
      }
      await Payments.update({ id, record });
      return { success: true, id };
    }

    // Auto-generate payment ID
    const allPayments = await Payments.findAll({ limit: 500 });
    const nextNum = allPayments.records.length + 1;
    const paymentId = `PAG-${String(nextNum).padStart(4, '0')}`;

    // Force Programado status for all new payments
    const created = await Payments.create({ record: { ...record, status: 'Programado', paymentId } });
    return { success: true, id: created.id };
  },
});

import { z } from 'zod';
import { createEndpoint, Projects, Boards, Tasks, CalendarEvents, RecruitmentRows, CellValues } from 'zite-integrations-backend-sdk';
import { ensureCalendarDefaultColumns } from '../serverUtils/calendarDefaults';
import { ensureTimelineDefaultColumns } from '../serverUtils/timelineDefaults';

const sleep = (ms: number) => new Promise(r => setTimeout(r, ms));

async function batchUpdate<T extends { id: string }>(
  records: T[],
  updater: (r: T) => Promise<any>,
  batchSize = 15
) {
  for (let i = 0; i < records.length; i += batchSize) {
    const batch = records.slice(i, i + batchSize);
    await Promise.all(batch.map(updater));
    if (i + batchSize < records.length) await sleep(200);
  }
}

/** Cascade a single oldCode → newCode across all related tables */
async function cascadeCode(oldCode: string, newCode: string) {
  const escaped = oldCode.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  // 1. Tasks
  let offset = 0;
  while (true) {
    const { records, hasMore } = await Tasks.findAll({ filters: { projectCode: oldCode }, limit: 500, offset, fields: ['id'] });
    if (records.length) await batchUpdate(records, r => Tasks.update({ id: r.id, record: { projectCode: newCode } }));
    if (!hasMore) break;
    offset += records.length;
  }

  // 2. Boards
  offset = 0;
  const boardIds: string[] = [];
  while (true) {
    const { records, hasMore } = await Boards.findAll({ filters: { projectCode: oldCode }, limit: 200, offset, fields: ['id'] });
    if (records.length) {
      boardIds.push(...records.map(r => r.id));
      await batchUpdate(records, r => Boards.update({ id: r.id, record: { projectCode: newCode } } as any));
    }
    if (!hasMore) break;
    offset += records.length;
  }

  // 3. CalendarEvents
  offset = 0;
  while (true) {
    const { records, hasMore } = await CalendarEvents.findAll({ filters: { projectCode: oldCode }, limit: 500, offset, fields: ['id'] });
    if (records.length) await batchUpdate(records, r => CalendarEvents.update({ id: r.id, record: { projectCode: newCode } } as any));
    if (!hasMore) break;
    offset += records.length;
  }

  // 4. RecruitmentRows
  offset = 0;
  while (true) {
    const { records, hasMore } = await RecruitmentRows.findAll({ filters: { projectCode: oldCode }, limit: 500, offset, fields: ['id'] });
    if (records.length) await batchUpdate(records, r => RecruitmentRows.update({ id: r.id, record: { projectCode: newCode } } as any));
    if (!hasMore) break;
    offset += records.length;
  }

  // 5. CellValues — boardId embeds the project code (e.g. "pm-OLDCODE-boardname")
  const prefixes = [`pm-${oldCode}-`, `cal-${oldCode}-`, `recruitment-${oldCode}-`];
  for (const prefix of prefixes) {
    offset = 0;
    while (true) {
      const { records, hasMore } = await CellValues.findAll({
        filters: { boardId: { contains: prefix } } as any,
        limit: 500, offset, fields: ['id', 'boardId'],
      });
      if (records.length) {
        await batchUpdate(records, r => {
          const newBoardId = (r.boardId ?? '').replace(
            new RegExp(`(pm|cal|recruitment)-${escaped}-`),
            `$1-${newCode}-`
          );
          return CellValues.update({ id: r.id, record: { boardId: newBoardId } } as any);
        });
      }
      if (!hasMore) break;
      offset += records.length;
    }
  }
}

export default createEndpoint({
  authenticated: true,
  description: 'Create or update a project. If oldProjectCode differs from projectCode, cascades the rename to all related tables. Optionally pass additionalOldCodes to also cascade from other orphaned codes.',
  inputSchema: z.object({
    id: z.string().optional(),
    projectCode: z.string(),
    oldProjectCode: z.string().optional(),
    additionalOldCodes: z.array(z.string()).optional(), // Extra orphaned codes to cascade from
    fullName: z.string().optional(),
    status: z.string().optional(),
    client: z.string().optional(),
    tematica: z.string().optional(),
    startDate: z.string().optional(),
    endDate: z.string().optional(),
    description: z.string().optional(),
    lider: z.string().optional(),
    analistas: z.array(z.string()).optional(),
    moderadores: z.array(z.string()).optional(),
    asistentes: z.array(z.string()).optional(),
    muestra: z.string().optional(),
    muestraImagen: z.string().optional(),
    instruccionesDeAnalisis: z.string().optional(),
  }),
  outputSchema: z.object({ success: z.boolean(), id: z.string(), cascaded: z.boolean().optional() }),
  execute: async ({ input, context }) => {
    const { id, oldProjectCode, projectCode, additionalOldCodes, fullName, status, client, tematica, startDate, endDate, description, lider, analistas, moderadores, asistentes, muestra, muestraImagen, instruccionesDeAnalisis } = input;
    const now = new Date().toISOString();
    const updateFields: Record<string, any> = { projectCode, fullName, status, client, tematica, startDate, endDate, description };
    if (muestra !== undefined) updateFields.muestra = muestra;
    if (muestraImagen !== undefined) updateFields.muestraImagen = muestraImagen;
    if (instruccionesDeAnalisis !== undefined) updateFields.instruccionesDeAnalisis = instruccionesDeAnalisis;
    if (lider !== undefined) updateFields.lider = lider ? lider : null;
    if (analistas !== undefined) updateFields.analistas = analistas;
    if (moderadores !== undefined) updateFields.moderadores = moderadores;
    if (asistentes !== undefined) updateFields.asistentes = asistentes;

    if (id) {
      await Projects.update({ id, record: updateFields });

      // Collect all codes that need cascading
      const codesToCascade: string[] = [];
      if (oldProjectCode && oldProjectCode !== projectCode) {
        codesToCascade.push(oldProjectCode);
      }
      if (additionalOldCodes) {
        for (const c of additionalOldCodes) {
          if (c && c !== projectCode && !codesToCascade.includes(c)) {
            codesToCascade.push(c);
          }
        }
      }

      if (codesToCascade.length > 0) {
        for (const oldCode of codesToCascade) {
          await cascadeCode(oldCode, projectCode);
        }
        return { success: true, id, cascaded: true };
      }

      return { success: true, id };
    }

    // ── Create new project ─────────────────────────────────────────────────────
    const record = await Projects.create({ record: { ...updateFields, createdBy: context.user!.email, createdAt: now } });

    // Auto-create a default calendar board for the new project
    const calendarBoard = await Boards.create({
      record: {
        boardName: 'Calendario',
        projectCode: input.projectCode,
        boardOrder: 0,
        boardType: 'calendar',
      } as any,
    });
    await ensureCalendarDefaultColumns(calendarBoard.id);

    // Auto-create a default Timeline board with 7 default tasks
    const timelineBoard = await Boards.create({
      record: {
        boardName: 'Timeline',
        projectCode: input.projectCode,
        boardOrder: 0,
        boardType: 'pm',
      } as any,
    });
    const timelineBoardId = timelineBoard.id;
    await ensureTimelineDefaultColumns(timelineBoardId);

    const DEFAULT_TASKS = [
      'Go Ahead',
      'Reclutamiento',
      'Envío de guía de tópicos',
      'Aprobación de guía de tópicos',
      'Fieldwork',
      'Análisis',
      'Reporte',
    ];

    await Tasks.bulkCreate({
      records: DEFAULT_TASKS.map((taskName, order) => ({
        taskName,
        projectCode: input.projectCode,
        boardName: 'Timeline',
        boardId: timelineBoardId,
        status: 'Pendiente',
        order,
      })) as any,
    });

    return { success: true, id: record.id };
  },
});

import { z } from 'zod';
import { createEndpoint, Messages, ChatConversations, TaskComments, Users } from 'zite-integrations-backend-sdk';
import { parseMembers } from '../lib/chatJson';
import { publishEvent, safeUserChannel } from '../lib/ably';

const TASK_MENTION_RE = /\[✅\s*([^\]]+)\]\(task:([^)]+)\)/g;

function extractTaskMentions(content: string): { taskName: string; taskId: string }[] {
  const results: { taskName: string; taskId: string }[] = [];
  const re = new RegExp(TASK_MENTION_RE.source, 'g');
  let m;
  while ((m = re.exec(content)) !== null) {
    results.push({ taskName: m[1].trim(), taskId: m[2].trim() });
  }
  return results;
}

export default createEndpoint({
  description: 'Send a message to a channel',
  authenticated: true,
  inputSchema: z.object({
    channel: z.string(),
    content: z.string(),
    parentMessageId: z.string().optional(),
    attachments: z.string().optional(), // JSON array of {url, name, type}
  }),
  outputSchema: z.object({ success: z.boolean(), id: z.string() }),
  execute: async ({ input, context }) => {
    // Check if this channel is a DM/group conversation (not "general" or a project code)
    if (input.channel !== 'general') {
      try {
        const conv = await ChatConversations.findOne({ id: input.channel });
        if (conv) {
          // It's a conversation record — verify the user is a member
          const members: string[] = parseMembers(conv.members);
          if (!members.includes(context.user!.email)) {
            throw new Error('No tienes acceso a esta conversación');
          }
        }
        // If conv is undefined → not found, treat as regular project channel, allow access
      } catch (err) {
        // Re-throw access errors
        if (err instanceof Error && err.message === 'No tienes acceso a esta conversación') {
          throw err;
        }
        // Otherwise: lookup error → treat as regular channel, allow access
      }
    }

    const senderName = [context.user!.firstName, context.user!.lastName].filter(Boolean).join(' ') || context.user!.email;
    const now = new Date().toISOString();

    const record = await Messages.create({
      record: {
        channel: input.channel,
        content: input.content,
        senderName,
        senderEmail: context.user!.email,
        sentAt: now,
        parentMessageId: input.parentMessageId,
        attachments: input.attachments,
      },
    });

    console.log('[sendMessage] message created', { messageId: record.id, channel: input.channel });

    // Side-effect: piggyback presence update — keeps user active without extra endpoint calls
    try {
      await Users.update({
        id: context.user!.id,
        record: {
          lastActiveAt: now,
          activeChannel: input.channel,
        } as Parameters<typeof Users.update>[0]['record'],
      });
    } catch {
      // Silent — never fail sendMessage for presence
    }

    // Update lastMessageAt on DM/group conversations (not general/project channels)
    try {
      if (input.channel !== 'general') {
        const convToUpdate = await ChatConversations.findOne({ id: input.channel });
        if (convToUpdate) {
          await ChatConversations.update({ id: convToUpdate.id, record: { lastMessageAt: now } });
          console.log('[sendMessage][conv-ts updated]', { convId: convToUpdate.id });
        }
      }
    } catch (err) {
      console.error('[sendMessage][update-conv-ts failed]', {
        message: err instanceof Error ? err.message : String(err),
      });
    }

    // Detect task mentions — side effect, never fails the endpoint
    try {
      const directMentions = extractTaskMentions(input.content);

      if (directMentions.length > 0) {
        const directTaskIds = new Set(directMentions.map(m => m.taskId));

        // Create TaskComment for each directly mentioned task
        const directRecords = directMentions.map(({ taskName, taskId }) => ({
          taskId,
          messageId: record.id,
          taskName,
          channel: input.channel,
          senderName,
          senderEmail: context.user!.email,
          content: input.content,
          sentAt: now,
          isThreadReply: false,
        }));
        if (directRecords.length > 0) {
          await TaskComments.bulkCreate({ records: directRecords });
        }

        // If this is a thread reply, also mark the parent's tasks as having a reply
        if (input.parentMessageId) {
          const parentMsg = await Messages.findOne({ id: input.parentMessageId, fields: ['content'] });
          if (parentMsg?.content) {
            const parentMentions = extractTaskMentions(parentMsg.content).filter(m => !directTaskIds.has(m.taskId));
            if (parentMentions.length > 0) {
              const replyRecords = parentMentions.map(({ taskName, taskId }) => ({
                taskId,
                messageId: record.id,
                taskName,
                channel: input.channel,
                senderName,
                senderEmail: context.user!.email,
                content: input.content,
                sentAt: now,
                isThreadReply: true,
              }));
              await TaskComments.bulkCreate({ records: replyRecords });
            }
          }
        }
      } else if (input.parentMessageId) {
        // No direct task mentions — but if replying to a task-mentioning message, mark as reply
        const parentMsg = await Messages.findOne({ id: input.parentMessageId, fields: ['content'] });
        if (parentMsg?.content) {
          const parentMentions = extractTaskMentions(parentMsg.content);
          if (parentMentions.length > 0) {
            const replyRecords = parentMentions.map(({ taskName, taskId }) => ({
              taskId,
              messageId: record.id,
              taskName,
              channel: input.channel,
              senderName,
              senderEmail: context.user!.email,
              content: input.content,
              sentAt: now,
              isThreadReply: true,
            }));
            await TaskComments.bulkCreate({ records: replyRecords });
          }
        }
      }
    } catch (err) {
      console.error('[sendMessage][side-effect failed]', {
        step: 'task-comments',
        messageId: record.id,
        message: err instanceof Error ? err.message : String(err),
      });
    }

    console.log('[sendMessage] publishing ably', { ablyChannel: `chat:${input.channel}`, messageId: record.id });

    try {
      await publishEvent(`chat:${input.channel}`, 'message.created', {
        id: record.id,
        channel: input.channel,
        content: input.content,
        senderName,
        senderEmail: context.user!.email,
        sentAt: now,
        parentMessageId: input.parentMessageId ?? undefined,
        attachments: input.attachments ?? undefined,
        pinned: false,
        reactions: undefined,
      });
    } catch (err) {
      console.error('[sendMessage][ably publish failed]', {
        channel: input.channel,
        messageId: record.id,
        message: err instanceof Error ? err.message : String(err),
      });
    }

    // Side-effect: notify each recipient on their personal Ably channel
    try {
      const senderEmailLower = context.user!.email.toLowerCase();

      // Fetch all users for name lookup and recipient resolution
      const { records: allUsers } = await Users.findAll({
        limit: 500,
        fields: ['email', 'firstName', 'lastName', 'hiddenFromChat'],
      });

      let recipientEmails: string[];
      let resolvedAsConv = false;
      let resolvedConvType: string | null = null;

      if (input.channel === 'general') {
        // General channel: everyone who is not hidden
        recipientEmails = allUsers
          .filter(u => u.email && u.hiddenFromChat !== true)
          .map(u => u.email as string);
      } else {
        // Try to resolve as DM/group conversation
        try {
          const convRecord = await ChatConversations.findOne({ id: input.channel });
          if (convRecord) {
            resolvedAsConv = true;
            resolvedConvType = convRecord.type ?? null;
            recipientEmails = parseMembers(convRecord.members);
          } else {
            recipientEmails = [];
          }
        } catch {
          recipientEmails = [];
        }

        if (!resolvedAsConv) {
          // Project channel: notify all non-hidden users (V1 — no project membership filter)
          recipientEmails = allUsers
            .filter(u => u.email && u.hiddenFromChat !== true)
            .map(u => u.email as string);
        }
      }

      // Exclude sender
      recipientEmails = recipientEmails.filter(e => e && e.toLowerCase() !== senderEmailLower);

      // Build lookup map for mention detection
      const userMap = new Map(allUsers.map(u => [u.email?.toLowerCase() ?? '', u]));
      const contentLower = input.content.toLowerCase();
      let mentionCount = 0;

      // Build a clean content preview (strip markdown, max 80 chars)
      const contentPreview = input.content
        .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1') // links → label
        .replace(/[*_~`#>]/g, '')                 // bold, italic, code, headings, blockquotes
        .replace(/\s+/g, ' ')
        .trim()
        .slice(0, 80) || '📎 Archivo';

      await Promise.allSettled(
        recipientEmails.map(email => {
          const u = userMap.get(email.toLowerCase());
          const fullName = `${u?.firstName ?? ''} ${u?.lastName ?? ''}`.trim().toLowerCase();
          const hasMention = fullName ? contentLower.includes(`@${fullName}`) : false;
          if (hasMention) mentionCount++;

          return publishEvent(safeUserChannel(email), 'notification.new_message', {
            channel: input.channel,
            messageId: record.id,
            senderName,
            senderEmail: context.user!.email,
            hasMention,
            sentAt: now,
            contentPreview,
            isConversation: resolvedAsConv,
            conversationType: resolvedConvType,
          });
        }),
      );

      console.log('[sendMessage][user-notify]', { channel: input.channel, recipients: recipientEmails.length, mentions: mentionCount });
    } catch (err) {
      console.error('[sendMessage][user-notify failed]', {
        message: err instanceof Error ? err.message : String(err),
      });
    }

    console.log('[sendMessage] returning success', { messageId: record.id });

    return { success: true, id: record.id };
  },
});

import { z } from 'zod';
import { createEndpoint, ZiteError, PurchaseOrders, PoAuditLog } from 'zite-integrations-backend-sdk';
import { publishEvent } from '../lib/ably';

function textToHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/(https?:\/\/[^\s<]+)/g, '<a href="$1" style="color:#2563eb;text-decoration:underline">$1</a>')
    .replace(/\n/g, '<br>\n');
}

export default createEndpoint({
  authenticated: true,
  description: 'Send a purchase order to a supplier via Outlook (Microsoft Graph API)',
  inputSchema: z.object({
    poId: z.string(),
    recipientEmail: z.string(),
    subject: z.string(),
    body: z.string(),
  }),
  outputSchema: z.object({ success: z.boolean(), message: z.string() }),
  execute: async ({ input, context }) => {
    const accessToken = process.env.ZITE_OUTLOOK_ACCESS_TOKEN;
    if (!accessToken) {
      throw new ZiteError({
        code: 'BAD_REQUEST',
        message: 'La integración de Outlook no está configurada correctamente.',
      });
    }

    const po = await PurchaseOrders.findOne({ id: input.poId });
    if (!po) throw new ZiteError({ code: 'NOT_FOUND', message: 'OC no encontrada' });

    // Build email attachments from stored pdfBase64 field
    const attachments: unknown[] = [];

    if (po.pdfBase64) {
      console.log('pdfBase64 found on PO, length:', po.pdfBase64.length);
      attachments.push({
        '@odata.type': '#microsoft.graph.fileAttachment',
        name: `OC-${po.poNumber}.pdf`,
        contentType: 'application/pdf',
        contentBytes: po.pdfBase64,
      });
    } else {
      console.log('No pdfBase64 stored on this PO — sending without attachment');
    }

    const sendAsEmail = process.env.ZITE_OUTLOOK_SEND_AS_EMAIL?.trim() || undefined;

    const mailPayload = {
      message: {
        subject: input.subject,
        body: {
          contentType: 'HTML',
          content: textToHtml(input.body),
        },
        toRecipients: [{ emailAddress: { address: input.recipientEmail } }],
        ...(sendAsEmail ? { from: { emailAddress: { address: sendAsEmail } } } : {}),
        ...(attachments.length > 0 ? { attachments } : {}),
      },
      saveToSentItems: true,
    };

    const graphResp = await fetch('https://graph.microsoft.com/v1.0/me/sendMail', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${accessToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(mailPayload),
    });

    if (!graphResp.ok) {
      const errText = await graphResp.text().catch(() => '');
      throw new ZiteError({
        code: 'INTERNAL_ERROR',
        message: `Error al enviar por Outlook (${graphResp.status}): ${errText.slice(0, 300)}`,
      });
    }

    // Update PO record
    await PurchaseOrders.update({
      id: input.poId,
      record: {
        emailSentAt: new Date().toISOString(),
        emailSentTo: input.recipientEmail,
      },
    });

    // Audit log entry
    const userName = [context.user!.firstName, context.user!.lastName].filter(Boolean).join(' ') || context.user!.email;
    await PoAuditLog.create({
      record: {
        timestamp: new Date().toISOString(),
        purchaseOrder: input.poId,
        action: 'Email enviado',
        userEmail: context.user!.email,
        userName,
        poNumber: String(po.poNumber ?? ''),
        comments: `Email enviado a ${input.recipientEmail}`,
      },
    });

    const pdfAttached = attachments.length > 0;
    try { await publishEvent('purchases:global', 'po.changed', { id: input.poId, action: 'email_sent', senderEmail: context.user!.email, timestamp: new Date().toISOString() }); } catch { /* silent */ }
    return {
      success: true,
      message: `OC enviada correctamente a ${input.recipientEmail}${pdfAttached ? ' con PDF adjunto' : ' (sin PDF adjunto — regenera el PDF primero)'}`,
    };
  },
});

