    const raw: unknown[] = Array.isArray(data) ? data : (data.forms ?? []);

    return {
      forms: raw.map((f: any) => ({
        formId: String(f.formId ?? f.id ?? ''),
        name: String(f.name ?? f.title ?? 'Sin nombre'),
        tags: Array.isArray(f.tags) ? f.tags as string[] : [],
      })).filter(f => f.formId && f.tags.includes('form')),
    };
  },
});

import { z } from 'zod';
import { createEndpoint, Projects } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Retrieves the last saved recruitment analysis for a project/board from the database',
  inputSchema: z.object({
    projectCode: z.string(),
    boardName: z.string(),
  }),
  outputSchema: z.object({
    found: z.boolean(),
    analysis: z.any().optional(),
    savedAt: z.string().optional(),
  }),
  execute: async ({ input }) => {
    const { projectCode, boardName } = input;

    const project = await Projects.findOne({
      filters: { projectCode },
      fields: ['id', 'lastAnalysisJson', 'lastAnalysisAt'],
    });

    if (!project?.lastAnalysisJson) {
      return { found: false };
    }

    try {
      const allAnalyses = JSON.parse(project.lastAnalysisJson);
      const analysis = allAnalyses[boardName];
      if (!analysis) return { found: false };
      return {
        found: true,
        analysis,
        savedAt: project.lastAnalysisAt ?? undefined,
      };
    } catch {
      return { found: false };
    }
  },
});

