function fmtDate(d: Date): string {
  const day = String(d.getDate()).padStart(2, '0');
  const mon = d.toLocaleDateString('es', { month: 'short' }).replace('.', '');
  const year = d.getFullYear();
  return `${day}-${mon}-${year}`;
}
