  };

  return (
    <Dialog open={open} onOpenChange={v => { if (!v) onClose(); }}>
      <DialogContent className="sm:max-w-sm">
        <DialogHeader>
          <DialogTitle>{limit ? 'Editar límite de aprobación' : 'Nuevo límite de aprobación'}</DialogTitle>
