});

import { z } from 'zod';
import { createEndpoint, SharedViews } from 'zite-integrations-backend-sdk';
import { randomUUID } from 'crypto';

/**
 * Atomically creates-or-maintains the external shared view linked to an internal view.
 * The external view is only a token stub — filters and column visibility are always
 * read live from the internal view by getSharedViewData, so no filter copying is needed.
 *
 * - If the internal view already has a sharedToken → verify the external view exists
 *   (recreate if it was deleted) and return the same URL.
 * - If not → create a fresh external shared view stub, then save its token back to
 *   the internal view so future calls reuse it.
 */
export default createEndpoint({
  description: 'Create or maintain the external shared view token linked to an internal view (idempotent)',
  authenticated: true,
  inputSchema: z.object({
    internalViewId: z.string(),
    viewName: z.string(),
    boardId: z.string(),
    projectCode: z.string(),
    boardName: z.string(),
  }),
  outputSchema: z.object({
    shareUrl: z.string(),
    sharedToken: z.string(),
    isNew: z.boolean(),
  }),
  execute: async ({ input, context }) => {
    const appUrl = process.env.ZITE_APP_URL ?? '';

    // Load the internal view to check if it already has a linked external view
    const internalView = await SharedViews.findOne({ id: input.internalViewId });
    if (!internalView) throw new Error('Vista interna no encontrada');

    const existingToken = internalView.sharedToken;

    if (existingToken) {
      // ── Verify external view still exists ────────────────────────────
      const externalView = await SharedViews.findOne({ filters: { token: existingToken, type: 'External' } });

      if (externalView) {
        // Update viewName in case it was renamed
        if (externalView.viewName !== `🔗 ${input.viewName}`) {
          await SharedViews.update({
            id: externalView.id,
            record: { viewName: `🔗 ${input.viewName}` },
          });
        }
        return {
          shareUrl: `${appUrl}/shared/${existingToken}`,
          sharedToken: existingToken,
          isNew: false,
        };
      }
      // External view was deleted — fall through to recreate it below
    }

    // ── CREATE new external view stub ─────────────────────────────────────
    const newToken = randomUUID();

    await SharedViews.create({
      record: {
        viewName: `🔗 ${input.viewName}`,
        boardId: input.boardId,
        projectCode: input.projectCode,
        boardName: input.boardName,
        token: newToken,
        createdBy: context.user!.email,
        active: true,
        type: 'External',
      },
    });

    // Save the new token back to the internal view so future calls reuse it
    await SharedViews.update({
      id: input.internalViewId,
      record: { sharedToken: newToken },
    });

    return {
      shareUrl: `${appUrl}/shared/${newToken}`,
      sharedToken: newToken,
      isNew: true,
    };
  },
});

import { z } from 'zod';
import { createEndpoint, Messages } from 'zite-integrations-backend-sdk';
import { publishEvent } from '../lib/ably';

export default createEndpoint({
  description: 'Toggle pin status on a message',
  authenticated: true,
  inputSchema: z.object({ messageId: z.string() }),
  outputSchema: z.object({ success: z.boolean(), pinned: z.boolean() }),
  execute: async ({ input }) => {
    const msg = await Messages.findOne({ id: input.messageId });
    if (!msg) return { success: false, pinned: false };
    const newPinned = !msg.pinned;
    await Messages.update({ id: input.messageId, record: { pinned: newPinned } });

    console.log('[ably][publish message.pinned]', { channel: msg.channel, messageId: input.messageId, pinned: newPinned });
    try {
      await publishEvent(`chat:${msg.channel}`, 'message.pinned', {
        messageId: input.messageId,
        channel: msg.channel,
        pinned: newPinned,
      });
    } catch (err) {
      console.error('[ably][message.pinned failed]', { messageId: input.messageId, message: err instanceof Error ? err.message : String(err) });
    }

    return { success: true, pinned: newPinned };
  },
});

import { z } from 'zod';
import { createEndpoint, SharedViews } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Updates an existing shared view (name, filters, visible columns)',
  inputSchema: z.object({
    id: z.string(),
    viewName: z.string().optional(),
    filtersJson: z.string().optional(),
    visibleColumnsJson: z.string().optional(),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input }) => {
    const record: Record<string, unknown> = {};
    if (input.viewName !== undefined) record.viewName = input.viewName;
    if (input.filtersJson !== undefined) record.filtersJson = input.filtersJson;
    if (input.visibleColumnsJson !== undefined) record.visibleColumnsJson = input.visibleColumnsJson;

    await SharedViews.update({ id: input.id, record });
    return { success: true };
  },
});

import { BarChart3 } from 'lucide-react';
import { Badge } from '@/components/ui/badge';

export interface PollData {
  type: 'poll';
  question: string;
  options: string[];
  votes: Record<string, string[]>;
  creatorName: string;
  creatorEmail: string;
}

export function parsePoll(content?: string | null): PollData | null {
  if (!content) return null;
  try {
    const data = JSON.parse(content);
    if (data?.type === 'poll' && Array.isArray(data.options)) return data as PollData;
    return null;
  } catch {
    return null;
  }
}

interface PollCardProps {
  poll: PollData;
  myEmail: string;
  onVote: (option: string) => void;
  isOwn: boolean;
}

export function PollCard({ poll, myEmail, onVote, isOwn }: PollCardProps) {
  const totalVotes = Object.values(poll.votes).reduce((sum, users) => sum + users.length, 0);

  const myVote = Object.entries(poll.votes).find(([, users]) =>
    users.includes(myEmail)
  )?.[0];

  return (
    <div className={`rounded-2xl overflow-hidden border shadow-sm w-72 ${
      isOwn ? 'border-primary/30 bg-primary/5' : 'border-border bg-card'
    }`}>
      {/* Header */}
      <div className={`flex items-center gap-2 px-3.5 py-2.5 border-b ${
        isOwn ? 'border-primary/20 bg-primary/8' : 'border-border/60 bg-muted/40'
      }`}>
        <BarChart3 className={`w-3.5 h-3.5 flex-shrink-0 ${isOwn ? 'text-primary' : 'text-muted-foreground'}`} />
        <Badge variant="secondary" className="text-[10px] px-1.5 py-0 h-4 font-semibold tracking-wide">
          ENCUESTA
        </Badge>
      </div>

      {/* Question */}
      <div className="px-3.5 pt-3 pb-2">
        <p className="text-sm font-semibold leading-snug text-foreground">{poll.question}</p>
      </div>

      {/* Options */}
      <div className="px-3.5 pb-3 space-y-2">
        {poll.options.map(option => {
          const count = (poll.votes[option] ?? []).length;
          const pct = totalVotes > 0 ? Math.round((count / totalVotes) * 100) : 0;
          const isMyVote = myVote === option;

          return (
            <button
              key={option}
              onClick={() => onVote(option)}
              className={`w-full text-left rounded-xl border transition-all duration-150 overflow-hidden group relative ${
                isMyVote
                  ? 'border-primary/60 bg-primary/8 ring-1 ring-primary/25'
                  : 'border-border hover:border-primary/30 bg-background hover:bg-muted/40'
              }`}
            >
              {/* Progress fill */}
              <div
                className={`absolute inset-0 rounded-xl transition-all duration-500 ${
                  isMyVote ? 'bg-primary/12' : 'bg-muted/60'
                }`}
                style={{ width: `${pct}%` }}
              />
              {/* Content */}
              <div className="relative flex items-center gap-2 px-3 py-2">
                <span className={`text-xs font-medium flex-1 truncate ${
                  isMyVote ? 'text-primary font-semibold' : 'text-foreground'
                }`}>
                  {option}
                </span>
                <span className={`text-[11px] font-bold tabular-nums flex-shrink-0 ${
                  isMyVote ? 'text-primary' : 'text-muted-foreground'
                }`}>
                  {pct > 0 ? `${pct}%` : ''}
                </span>
                {count > 0 && (
                  <span className={`text-[10px] flex-shrink-0 ${
                    isMyVote ? 'text-primary/70' : 'text-muted-foreground/60'
                  }`}>
                    {count}
                  </span>
                )}
                {isMyVote && (
                  <span className="text-primary text-[11px] flex-shrink-0">✓</span>
                )}
              </div>
            </button>
          );
        })}
      </div>

      {/* Footer */}
      <div className={`flex items-center gap-1.5 px-3.5 py-2 border-t text-[11px] text-muted-foreground ${
        isOwn ? 'border-primary/20' : 'border-border/60'
      }`}>
        <span className="font-medium">
          {totalVotes === 0 ? 'Sin votos aún' : `${totalVotes} ${totalVotes === 1 ? 'voto' : 'votos'}`}
        </span>
        <span className="opacity-40">·</span>
        <span className="truncate">por {poll.creatorName || poll.creatorEmail}</span>
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { useAuth } from 'zite-auth-sdk';
import {
  getDashboardData, GetDashboardDataOutputType,
  getRecruitmentDashboard, GetRecruitmentDashboardOutputType,
  getInvoiceWidgetData, GetInvoiceWidgetDataOutputType,
  saveWidgetLayout,
} from 'zite-endpoints-sdk';
import { useProject } from '../context/ProjectContext';
import { Skeleton } from '@/components/ui/skeleton';
import { Button } from '@/components/ui/button';
import { Globe, Settings2, RotateCcw, Check, X } from 'lucide-react';
import { toast } from 'sonner';
import ProjectCards from '../components/dashboard/ProjectCards';
import MyTasks from '../components/dashboard/MyTasks';
import UpcomingEvents from '../components/dashboard/UpcomingEvents';
import RecruitmentDashboard from '../components/dashboard/RecruitmentDashboard';
import InvoiceWidget from '../components/dashboard/InvoiceWidget';
import DraggableWidgetGrid from '../components/dashboard/DraggableWidgetGrid';
import { buildLayout, LayoutItem, WidgetSize } from '../components/dashboard/widgetConfig';

type DashData = GetDashboardDataOutputType;
type RecruitData = GetRecruitmentDashboardOutputType;
type InvoiceData = GetInvoiceWidgetDataOutputType;

// Widgets available in the standard (non-recruitment) dashboard
const NORMAL_WIDGET_IDS = new Set(['my_projects', 'my_tasks', 'upcoming_events', 'received_invoices']);

function getGreeting() {
  const h = new Date().getHours();
  if (h < 12) return 'Buenos días';
  if (h < 19) return 'Buenas tardes';
  return 'Buenas noches';
}

const roleColors: Record<string, string> = {
  Owner:        'bg-primary text-primary-foreground',
  Socio:        'bg-purple-100 text-purple-700',
  Head:         'bg-blue-100 text-blue-700',
  'Líder':      'bg-emerald-100 text-emerald-700',
  Coordinador:  'bg-orange-100 text-orange-700',
  Analista:     'bg-sky-100 text-sky-700',
};

function SectionHeading({ label, accentColor }: { label: string; accentColor?: string }) {
  return (
    <div className="flex items-center gap-2 mb-2">
      {accentColor && <span className={`w-2 h-2 rounded-full flex-shrink-0 ${accentColor}`} />}
      <h2 className="text-xs font-bold uppercase tracking-widest text-muted-foreground">{label}</h2>
    </div>
  );
}

export default function DashboardPage() {
  const { user, isLoading: authLoading } = useAuth();
  const { setSelectedProject } = useProject();
  const [data, setData] = useState<DashData | null>(null);
  const [recruitData, setRecruitData] = useState<RecruitData | null>(null);
  const [invoiceData, setInvoiceData] = useState<InvoiceData | null>(null);
  const [loading, setLoading] = useState(true);
  const [invoiceLoading, setInvoiceLoading] = useState(false);

  const [widgetLayout, setWidgetLayout] = useState<LayoutItem[]>([]);
  const [editing, setEditing] = useState(false);
  const [savedLayoutJson, setSavedLayoutJson] = useState('');
  const [saving, setSaving] = useState(false);
  const [layoutReady, setLayoutReady] = useState(false);

  const isRecruitment = user?.departamento === 'Reclutamiento';
  const dashboardInFlightRef = useRef(false);

  useEffect(() => { setSelectedProject(null); }, []);

  // Initialize layout once when user is available
  useEffect(() => {
    if (authLoading || !user || layoutReady) return;
    const savedJson = (user as any).widgetLayout as string | undefined;
    const initial = buildLayout(user.dashboardWidgets ?? [], savedJson)
      .filter(item => NORMAL_WIDGET_IDS.has(item.id));
    setWidgetLayout(initial);
    setSavedLayoutJson(savedJson ?? '');
    setLayoutReady(true);
  }, [user, authLoading, layoutReady]);

  // Fetch main dashboard data — depend on user.id + isRecruitment (not full user object)
  // to avoid re-triggering when unrelated user fields change (prevents rate-limit errors)
  useEffect(() => {
    if (authLoading || !user?.id) return;
    setLoading(true);
    if (isRecruitment) {
      getRecruitmentDashboard({}).then(setRecruitData).catch(console.error).finally(() => setLoading(false));
    } else {
      if (dashboardInFlightRef.current) {
        console.log('[DashboardPage] getDashboardData skipped: in-flight');
        return;
      }
      dashboardInFlightRef.current = true;
      const fetchWithRetry = async (attempt = 0): Promise<void> => {
        console.log('[DashboardPage] getDashboardData attempt', { attempt });
        try {
          const result = await getDashboardData({});
          setData(result);
        } catch (e: any) {
          const msg = (e?.message ?? '').toLowerCase();
          const isRetryable = msg.includes('too many requests') || msg.includes('bad gateway') || msg.includes('timeout') || msg.includes('worker timeout');
          if (attempt < 4 && isRetryable) {
            const isBadGatewayOrTimeout = msg.includes('bad gateway') || msg.includes('timeout');
            const delayMs = isBadGatewayOrTimeout ? 6000 * (attempt + 1) : 4000 * (attempt + 1);
            console.warn('[DashboardPage] getDashboardData retry', { attempt, delayMs, errorMsg: msg });
            await new Promise(r => setTimeout(r, delayMs));
            return fetchWithRetry(attempt + 1);
          }
          console.error('[DashboardPage] getDashboardData failed after retries', e);
        }
      };
      fetchWithRetry().finally(() => {
        dashboardInFlightRef.current = false;
        setLoading(false);
      });
    }
  }, [user?.id, authLoading, isRecruitment]);

  // Fetch invoice data — delayed 3s so it doesn't burst alongside getDashboardData
  useEffect(() => {
    if (authLoading || !user?.id) return;
    const widgets = user.dashboardWidgets ?? [];
    const showAll = widgets.length === 0;
    if (!showAll && !widgets.includes('Facturas recibidas')) return;
    setInvoiceLoading(true);
    const timer = setTimeout(() => {
      getInvoiceWidgetData({}).then(setInvoiceData).catch(console.error).finally(() => setInvoiceLoading(false));
    }, 3000);
    return () => clearTimeout(timer);
  }, [user?.id, authLoading]);

  const handleStartEdit = () => {
    setSavedLayoutJson(JSON.stringify(widgetLayout));
    setEditing(true);
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      await saveWidgetLayout({ layout: JSON.stringify(widgetLayout) });
      setSavedLayoutJson(JSON.stringify(widgetLayout));
      setEditing(false);
      toast.success('Layout guardado');
    } catch {
      toast.error('Error al guardar');
    } finally {
      setSaving(false);
    }
  };

  const handleCancel = () => {
    const restored = buildLayout(user?.dashboardWidgets ?? [], savedLayoutJson || undefined)
      .filter(item => NORMAL_WIDGET_IDS.has(item.id));
    setWidgetLayout(restored);
    setEditing(false);
  };

  const handleReset = () => {
    setWidgetLayout(
      buildLayout(user?.dashboardWidgets ?? [], undefined)
        .filter(item => NORMAL_WIDGET_IDS.has(item.id))
    );
  };

  const renderWidget = useCallback((id: string, _size: WidgetSize): React.ReactNode => {
    switch (id) {
      case 'my_projects':
        return (
          <div className="space-y-2">
            <SectionHeading label="Mis proyectos" accentColor="bg-[hsl(var(--chart-4))]" />
            {loading ? (
              <div className="flex flex-wrap gap-2">
                {[1,2,3,4,5].map(i => <Skeleton key={i} className="h-7 w-28 rounded-full" />)}
              </div>
            ) : (
              <ProjectCards projects={data?.myProjects ?? []} />
            )}
          </div>
        );
      case 'my_tasks':
        return (
          <div className="space-y-2">
            <SectionHeading label="Mis tareas" accentColor="bg-primary" />
            {loading ? <Skeleton className="h-56 rounded-xl" /> : <MyTasks tasks={data?.myTasks ?? []} />}
          </div>
        );
      case 'upcoming_events':
        return (
          <div className="space-y-2">
            <SectionHeading label="Próximos eventos" accentColor="bg-secondary" />
            {loading ? <Skeleton className="h-56 rounded-xl" /> : <UpcomingEvents events={data?.upcomingEvents ?? []} />}
          </div>
        );
      case 'received_invoices':
        return (
          <div className="space-y-2">
            <SectionHeading label="Facturas recibidas" accentColor="bg-[hsl(var(--chart-5))]" />
            <InvoiceWidget data={invoiceData} loading={invoiceLoading} />
          </div>
        );
      default:
        return null;
    }
  }, [data, loading, invoiceData, invoiceLoading]);

  if (isRecruitment) {
    return (
      <RecruitmentDashboard
        user={{
          firstName: user?.firstName,
          role: user?.role,
          departamento: user?.departamento,
          dashboardWidgets: user?.dashboardWidgets,
          widgetLayout: (user as any).widgetLayout,
        }}
        data={recruitData}
        loading={loading}
        invoiceData={invoiceData}
        invoiceLoading={invoiceLoading}
      />
    );
  }

  const firstName = user?.firstName?.split(' ')[0] || '';

  return (
    <div className="p-6 space-y-6">

      {/* ── Header ── */}
      <div className="flex items-start justify-between gap-3 flex-wrap">
        <div>
          <h1 className="text-2xl font-black">
            {getGreeting()}{firstName ? `, ${firstName}` : ''}
          </h1>
          <p className="text-sm text-muted-foreground mt-0.5">
            {data?.isGlobal ? 'Vista global — todos los proyectos y tareas' : 'Tus proyectos, tareas y actividades'}
          </p>
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          {data?.isGlobal && (
            <span className="flex items-center gap-1.5 text-xs text-muted-foreground bg-muted px-2.5 py-1.5 rounded-full">
              <Globe className="w-3 h-3" /> Vista global
            </span>
          )}
          {user?.role && (
            <span className={`text-xs px-2.5 py-1.5 rounded-full font-semibold ${roleColors[user.role] ?? 'bg-muted text-muted-foreground'}`}>
              {user.role}
            </span>
          )}
          {/* Personalization controls */}
          {!editing ? (
            <button
              onClick={handleStartEdit}
              className="flex items-center gap-1.5 text-xs text-muted-foreground hover:text-foreground bg-muted hover:bg-muted/70 px-2.5 py-1.5 rounded-full transition-colors"
            >
              <Settings2 className="w-3 h-3" />
              Personalizar
            </button>
          ) : (
            <div className="flex items-center gap-1.5">
              <Button variant="ghost" size="sm" className="h-7 text-xs gap-1" onClick={handleReset}>
                <RotateCcw className="w-3 h-3" /> Resetear
              </Button>
              <Button variant="outline" size="sm" className="h-7 text-xs gap-1" onClick={handleCancel}>
                <X className="w-3 h-3" /> Cancelar
              </Button>
              <Button size="sm" className="h-7 text-xs gap-1" onClick={handleSave} disabled={saving}>
                <Check className="w-3 h-3" />
                {saving ? 'Guardando...' : 'Guardar'}
              </Button>
            </div>
          )}
        </div>
      </div>

      {/* Edit mode hint banner */}
      {editing && (
        <div className="flex items-center gap-2 px-4 py-2.5 bg-primary/5 border border-primary/20 rounded-xl text-xs text-primary">
          <Settings2 className="w-3.5 h-3.5 flex-shrink-0" />
          <span>
            Arrastra los widgets para reordenarlos • Usa <strong>Ampliar/Reducir</strong> para cambiar el ancho
          </span>
        </div>
      )}

      {/* Widget grid */}
      {widgetLayout.length > 0 && (
        <DraggableWidgetGrid
          layout={widgetLayout}
          editing={editing}
          onLayoutChange={setWidgetLayout}
          renderWidget={renderWidget}
        />
      )}

    </div>
  );
}

