                  {supplier.address && (
                    <div>
                      <p className="text-xs text-muted-foreground mb-0.5">Dirección</p>
                      <div className="flex items-start gap-1.5">
                        <MapPin className="w-3.5 h-3.5 text-muted-foreground mt-0.5 shrink-0" />
