import { z } from 'zod';
import { createEndpoint, PurchaseOrders } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Get PO IDs that need attention for the current user',
  inputSchema: z.object({}),
  outputSchema: z.object({
    items: z.array(z.object({ id: z.string(), status: z.string() })),
  }),
  execute: async ({ context }) => {
    if (!context?.user) return { items: [] };
    const { user } = context;
    const level = user.purchaseLevel ?? 'Creador';
    const items: { id: string; status: string }[] = [];
    const seenIds = new Set<string>();

    // 1. ODCs pending approval (if user has approval permissions)
    if (level !== 'Creador') {
      const { records: pending } = await PurchaseOrders.findAll({
        filters: { status: 'Enviada a aprobación' } as never,
        fields: ['id', 'status', 'category', 'createdBy'],
        limit: 500,
      });

      for (const po of pending) {
        // Skip own ODCs (you don't approve your own)
        if (po.createdBy === user.email) continue;
        // Área: only see their cost centers
        if (level === 'Aprobador') {
          const costCenters = user.costCenters ?? [];
          if (po.category && !costCenters.includes(po.category)) continue;
        }
        if (!seenIds.has(po.id)) {
          items.push({ id: po.id, status: po.status ?? 'Enviada a aprobación' });
          seenIds.add(po.id);
        }
      }
    }

    // 2. ODCs created by this user that reached Aprobada or Cancelada
    const { records: myChanged } = await PurchaseOrders.findAll({
      filters: { createdBy: user.email, status: { in: ['Aprobada', 'Cancelada'] } } as never,
      fields: ['id', 'status'],
      limit: 500,
    });
    for (const po of myChanged) {
      if (!seenIds.has(po.id)) {
        items.push({ id: po.id, status: po.status ?? '' });
        seenIds.add(po.id);
      }
    }

    return { items };
  },
});

import { z } from 'zod';
import { createEndpoint, RecruitmentRows, Boards } from 'zite-integrations-backend-sdk';

const dedup = <T extends { id: string }>(a: T[], b: T[]): T[] => {
  const seen = new Map<string, T>();
  for (const r of a) seen.set(r.id, r);
  for (const r of b) if (!seen.has(r.id)) seen.set(r.id, r);
  return Array.from(seen.values());
};

const rowSchema = z.object({
  id: z.string(),
  rowName: z.string().optional(),
  projectCode: z.string().optional(),
  boardName: z.string().optional(),
  boardId: z.string().optional(),
  participantName: z.string().optional(),
  email: z.string().optional(),
  phone: z.string().optional(),
  idNumber: z.string().optional(),
  status: z.string().optional(),
  group: z.string().optional(),
  parentRowId: z.string().optional(),
  level: z.number().optional(),
  ndaSent: z.boolean().optional(),
  ndaSentDate: z.string().optional(),
  notes: z.string().optional(),
  sourceForm: z.string().optional(),
  cellData: z.string().optional(),
  rowOrder: z.number().optional(),
});

/** Paginated fetch helper */
async function fetchAllPages(filters: Record<string, unknown>): Promise<any[]> {
  const all: any[] = [];
  let offset = 0;
  while (true) {
    const result = await RecruitmentRows.findAll({ filters, limit: 2000, offset });
    const active = result.records.filter((r: any) => !r.deletedAt);
    all.push(...active);
    if (!result.hasMore || result.records.length === 0) break;
    offset += result.records.length;
  }
  return all;
}

export default createEndpoint({
  authenticated: true,
  description: 'Get recruitment rows for a project, plus all persisted boards (even empty ones)',
  inputSchema: z.object({
    projectCode: z.string().optional(),
    boardName: z.string().optional(),
    boardId: z.string().optional(),
  }),
  outputSchema: z.object({
    rows: z.array(rowSchema),
    boards: z.array(z.string()),
    boardObjects: z.array(z.object({ id: z.string(), name: z.string(), boardType: z.string().optional(), boardOrder: z.number().optional() })),
  }),
  execute: async ({ input }) => {
    const boardFilters: Record<string, unknown> = {};
    if (input.projectCode) boardFilters.projectCode = input.projectCode;

    // Always fetch boards from the Boards table (never from rows)
    const boardsResult = await Boards.findAll({ filters: boardFilters, limit: 200 });
    const boardsFromTable = boardsResult.records
      .filter(b => !b.deletedAt && !!b.boardName && b.boardType !== 'pm' && b.boardType !== 'calendar')
      .sort((a, b) => (a.boardOrder ?? 0) - (b.boardOrder ?? 0))
      .map(b => b.boardName as string);

    const boardObjects = boardsResult.records
      .filter(b => !b.deletedAt && !!b.boardName && b.boardType !== 'pm' && b.boardType !== 'calendar')
      .sort((a, b) => (a.boardOrder ?? 0) - (b.boardOrder ?? 0))
      .map(b => ({ id: b.id, name: b.boardName as string, boardType: b.boardType ?? 'recruitment', boardOrder: b.boardOrder ?? 0 }));

    // ── Dual-read by boardId ──
    if (input.boardId) {
      const q1Filters: Record<string, unknown> = { boardId: input.boardId };
      if (input.projectCode) q1Filters.projectCode = input.projectCode;
      const q1Rows = await fetchAllPages(q1Filters);

      let fallback: any[] = [];
      if (input.projectCode && input.boardName) {
        const q2Rows = await fetchAllPages({ projectCode: input.projectCode, boardName: input.boardName });
        fallback = q2Rows.filter((r: any) => !r.boardId);
      }

      const rows = dedup(q1Rows, fallback);
      return { rows, boards: boardsFromTable, boardObjects };
    }

    // ── Legacy path (unchanged) ──
    // If only board list is needed (no boardName filter), return early without fetching rows
    if (!input.boardName) {
      return { rows: [], boards: boardsFromTable, boardObjects };
    }

    const rowFilters: Record<string, unknown> = {};
    if (input.projectCode) rowFilters.projectCode = input.projectCode;
    if (input.boardName) rowFilters.boardName = input.boardName;

    const allRows = await fetchAllPages(rowFilters);
    return { rows: allRows, boards: boardsFromTable, boardObjects };
  },
});

import { z } from 'zod';
import { createEndpoint, CommercialDashboardViews } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Create or update a commercial dashboard view. If viewId is provided, updates existing; otherwise creates new.',
  inputSchema: z.object({
    viewId: z.string().optional(),
    viewName: z.string(),
    filtersJson: z.string(),
    widgetsJson: z.string(),
    dateReference: z.enum(['proposalDate', 'approvalDate']),
    isDefault: z.boolean().optional(),
    isShared: z.boolean().optional(),
    sortOrder: z.number().optional(),
  }),
  outputSchema: z.object({ dbId: z.string(), viewId: z.string() }),
  execute: async ({ input, context }) => {
    const userId = context.user!.id;

    // Map dateReference to select option value
    const dateRefValue = input.dateReference === 'approvalDate'
      ? 'Fecha de aprobación'
      : 'Fecha de propuesta';

    // If isDefault=true, unmark all other defaults for this user
    if (input.isDefault) {
      const existing = await CommercialDashboardViews.findAll({
        filters: { isDefault: true },
      });
      const otherDefaults = existing.records.filter(v => {
        const ownerArr = Array.isArray(v.owner) ? v.owner : v.owner ? [v.owner] : [];
        return ownerArr.includes(userId);
      });
      for (const v of otherDefaults) {
        await CommercialDashboardViews.update({ id: v.id, record: { isDefault: false } });
      }
    }

    // Upsert by viewId
    if (input.viewId) {
      const existing = await CommercialDashboardViews.findOne({
        filters: { viewId: input.viewId },
      });
      if (existing) {
        await CommercialDashboardViews.update({
          id: existing.id,
          record: {
            viewName: input.viewName,
            filtersJson: input.filtersJson,
            widgetsJson: input.widgetsJson,
            dateReference: dateRefValue,
            isDefault: input.isDefault ?? existing.isDefault ?? false,
            isShared: input.isShared ?? existing.isShared ?? false,
            sortOrder: input.sortOrder ?? existing.sortOrder ?? 0,
          },
        });
        return { dbId: existing.id, viewId: input.viewId };
      }
    }

    // Create new
    const newViewId = input.viewId || `view_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
    const created = await CommercialDashboardViews.create({
      record: {
        viewName: input.viewName,
        viewId: newViewId,
        owner: userId,
        filtersJson: input.filtersJson,
        widgetsJson: input.widgetsJson,
        dateReference: dateRefValue,
        isDefault: input.isDefault ?? false,
        isShared: input.isShared ?? false,
        sortOrder: input.sortOrder ?? 0,
      },
    });

    return { dbId: created.id, viewId: newViewId };
  },
});

import { z } from 'zod';
import { createEndpoint, RecruitmentRows, Projects } from 'zite-integrations-backend-sdk';
import { publishEvent } from '../lib/ably';
import { lookupBoardUUID } from '../serverUtils/resolveBoardId';

// ── Shared helpers ────────────────────────────────────────────────────────────
type RowLike = { id: string; projectCode?: string; boardName?: string; status?: string; group?: string };
type ProjectDates = { startDate?: string; endDate?: string };

const normalize = (s: string) =>
  s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();

/**
 * 🔴 only when: participation criteria met AND other project ended BEFORE current started.
 * Otherwise falls back to 🟡. Levels 3 & 4 unchanged.
 */
const buildParticipationNote = (
  allRows: RowLike[],
  currentId: string,
  currentProjectCode: string,
  currentBoardName: string,
  projectDatesMap: Map<string, ProjectDates> = new Map(),
): string => {
  const others = allRows.filter(r => r.id !== currentId);
  if (others.length === 0) return '';

  const parts: string[] = [];

  const currentDates = projectDatesMap.get(currentProjectCode);
  const currentStart = currentDates?.startDate ? new Date(currentDates.startDate) : null;

  const diffProject = others.filter(r => r.projectCode && r.projectCode !== currentProjectCode);
  const participated = new Map<string, string>();
  const external = new Map<string, string>();

  for (const r of diffProject) {
    if (!r.projectCode) continue;
    const label = r.boardName ? `${r.projectCode} (${r.boardName})` : r.projectCode;
    const meetsParticipation = r.status === 'Asistió' || (!!r.group && r.group.trim() !== '');

    if (meetsParticipation) {
      const otherDates = projectDatesMap.get(r.projectCode);
      const otherEnd   = otherDates?.endDate ? new Date(otherDates.endDate) : null;
      const confirmedBefore = currentStart && otherEnd && otherEnd < currentStart;

      if (confirmedBefore) {
        participated.set(r.projectCode, label);
      } else {
        if (!participated.has(r.projectCode) && !external.has(r.projectCode)) {
          external.set(r.projectCode, label);
        }
      }
    } else if (!participated.has(r.projectCode) && !external.has(r.projectCode)) {
      external.set(r.projectCode, label);
    }
  }

  if (participated.size > 0) parts.push(`🔴 YA PARTICIPÓ: ${[...participated.values()].join(', ')}.`);
  const extLabels = [...external.entries()].filter(([k]) => !participated.has(k)).map(([, v]) => v);
  if (extLabels.length > 0) parts.push(`🟡 DUPLICADO EXTERNO: ${extLabels.join(', ')}.`);

  const sameProjectDiffBoard = others.filter(
    r => r.projectCode === currentProjectCode && r.boardName && r.boardName !== currentBoardName,
  );
  if (sameProjectDiffBoard.length > 0) {
    const boards = [...new Set(sameProjectDiffBoard.map(r => r.boardName).filter(Boolean) as string[])];
    parts.push(`🟠 MISMO PROYECTO: ${boards.join(', ')}.`);
  }

  const internal = others.filter(
    r => r.projectCode === currentProjectCode && r.boardName === currentBoardName,
  );
  if (internal.length > 0) parts.push(`🔵 ×${internal.length + 1} EN ESTE TABLERO`);

  return parts.join(' ');
};

