export default createEndpoint({
  authenticated: true,
  description: 'Create or update a recruitment row. On create, auto-detects duplicates.',
  inputSchema: z.object({
    id: z.string().optional(),
    rowName: z.string().optional(),
    projectCode: z.string().optional(),
    boardId: z.string().optional(),
    boardName: z.string().optional(),
    participantName: z.string().optional(),
    email: z.string().optional(),
    phone: z.string().optional(),
    idNumber: z.string().optional(),
    status: z.string().optional(),
    group: z.string().optional(),
    parentRowId: z.string().optional(),
    level: z.number().optional(),
    ndaSent: z.boolean().optional(),
    ndaSentDate: z.string().optional(),
    notes: z.string().optional(),
    sourceForm: z.string().optional(),
    rowOrder: z.number().optional(),
  }),
  outputSchema: z.object({ success: z.boolean(), id: z.string(), boardId: z.string().optional() }),
  execute: async ({ input, context }) => {
    const { id, ...fields } = input;

    // ── UPDATE path ───────────────────────────────────────────────────────
    if (id) {
      // R2-B: only include boardId in update if explicitly provided — don't overwrite with undefined
      const updateFields = { ...fields };
      if (!input.boardId) delete (updateFields as any).boardId;
      await RecruitmentRows.update({ id, record: updateFields });

      // Publish board.field.updated for real-time sync
      try {
        let projectCode = fields.projectCode;
        let boardName = fields.boardName;
        if (!projectCode || !boardName) {
          const row = await RecruitmentRows.findOne({ id });
          projectCode = projectCode ?? row?.projectCode ?? undefined;
          boardName = boardName ?? row?.boardName ?? undefined;
        }
        if (projectCode && boardName) {
          // R2-B: use input.boardId (UUID) when available, legacy composite as fallback
          const boardId = input.boardId || `recruitment-${projectCode}-${boardName}`;
          const updatedFields = Object.fromEntries(
            Object.entries(fields as Record<string, unknown>).filter(
              ([k, v]) => v !== undefined && k !== 'id' && k !== 'projectCode' && k !== 'boardName'
            )
          );
          if (Object.keys(updatedFields).length > 0) {
            await publishEvent(`board:${projectCode}`, 'board.field.updated', {
              projectCode,
              boardId,
              entityType: 'recruitmentRow',
              fieldType: 'fixed',
              rowId: id,
              fields: updatedFields,
              senderEmail: context.user!.email,
              timestamp: new Date().toISOString(),
            });
          }
        }
      } catch { /* fire and forget */ }

      return { success: true, id, boardId: input.boardId };
    }

    // ── CREATE path — run duplicate detection if we have enough data ──────
    const hasIdentifier = !!(input.email || input.participantName || input.phone);
    const hasProject    = !!input.projectCode;

    // R2-B: use input.boardId directly when provided (UUID from frontend), fallback to lookup
    let boardIdUUID: string | undefined = input.boardId;
    if (!boardIdUUID && input.projectCode && input.boardName) {
      const lookup = await lookupBoardUUID(input.projectCode, input.boardName, 'recruitment');
      if (lookup.found && lookup.uuid) {
        boardIdUUID = lookup.uuid;
      } else {
        console.warn('[saveRecruitmentRow] boardId lookup failed, leaving empty', { projectCode: input.projectCode, boardName: input.boardName, reason: lookup.reason });
      }
    }

    if (!hasIdentifier || !hasProject) {
      const record = await RecruitmentRows.create({ record: { ...fields, boardId: boardIdUUID } });
      return { success: true, id: record.id, boardId: boardIdUUID };
    }

    // 1. Fetch project dates for temporal comparison
    const { records: allProjects } = await Projects.findAll({
      limit: 500,
      fields: ['projectCode', 'startDate', 'endDate'],
    });
    const projectDatesMap = new Map<string, ProjectDates>();
    for (const p of allProjects) {
      if (p.projectCode) projectDatesMap.set(p.projectCode, { startDate: p.startDate, endDate: p.endDate });
    }

    // 2. Fetch all active rows globally for peer matching
    const { records: allRecords } = await RecruitmentRows.findAll({
      limit: 2000,
      fields: ['id', 'email', 'participantName', 'phone', 'projectCode', 'boardName', 'status', 'group', 'notes', 'deletedAt'],
    });
    const active = allRecords.filter(r => !r.deletedAt);

    // 3. Find peers by email / name / phone
    const newEmail = input.email?.toLowerCase().trim() ?? '';
    const newName  = input.participantName ? normalize(input.participantName) : '';
    const newPhone = input.phone ? input.phone.replace(/[\s\-().+]/g, '') : '';

    const peerIds = new Set<string>();
    for (const r of active) {
      if (newEmail && r.email && r.email.toLowerCase().trim() === newEmail) peerIds.add(r.id);
      if (newName.length > 2 && r.participantName && normalize(r.participantName) === newName) peerIds.add(r.id);
      if (newPhone.length >= 7 && r.phone && r.phone.replace(/[\s\-().+]/g, '') === newPhone) peerIds.add(r.id);
    }

    const rowById = new Map(active.map(r => [r.id, r]));
    const peers   = [...peerIds].map(pid => rowById.get(pid)).filter((r): r is typeof active[0] => !!r);

    // 4. Create the record (with boardId dual-write)
    const newRecord = await RecruitmentRows.create({ record: { ...fields, boardId: boardIdUUID } });
    const newId = newRecord.id;

    // 5. Calculate and save note for the new record
    const newRowAsRowLike: RowLike = {
      id: newId,
      projectCode: input.projectCode,
      boardName: input.boardName,
      status: input.status,
      group: input.group,
    };
    const allForNew: RowLike[] = [newRowAsRowLike, ...peers];
    const noteForNew = buildParticipationNote(allForNew, newId, input.projectCode!, input.boardName ?? '', projectDatesMap);

    if (noteForNew) {
      await RecruitmentRows.update({ id: newId, record: { notes: noteForNew } });
    }

    // 6. Backfill notes on existing peer rows
    for (const peer of peers) {
      if (!peer.projectCode) continue;

      const peerPeerIds = new Set<string>([newId]);
      for (const r of active) {
        if (r.id === peer.id) continue;
        if (peer.email && r.email && r.email.toLowerCase().trim() === peer.email.toLowerCase().trim()) peerPeerIds.add(r.id);
        if (peer.participantName) {
          const pn = normalize(peer.participantName);
          if (pn.length > 2 && r.participantName && normalize(r.participantName) === pn) peerPeerIds.add(r.id);
        }
        if (peer.phone) {
          const pp = peer.phone.replace(/[\s\-().+]/g, '');
          if (pp.length >= 7 && r.phone && r.phone.replace(/[\s\-().+]/g, '') === pp) peerPeerIds.add(r.id);
        }
      }

      const allForPeer: RowLike[] = [
        peer,
        newRowAsRowLike,
        ...[...peerPeerIds]
          .filter(pid => pid !== peer.id && pid !== newId)
          .map(pid => rowById.get(pid))
          .filter((r): r is typeof active[0] => !!r),
      ];

      const newPeerNote = buildParticipationNote(allForPeer, peer.id, peer.projectCode, peer.boardName ?? '', projectDatesMap);
      if (newPeerNote !== (peer.notes ?? '')) {
        await RecruitmentRows.update({ id: peer.id, record: { notes: newPeerNote || undefined } });
      }
    }

    return { success: true, id: newId, boardId: boardIdUUID };
  },
});

import { z } from 'zod';
import { createEndpoint, ZiteError, Payments, Suppliers } from 'zite-integrations-backend-sdk';

const fmtCurrency = (amount: number | undefined, currency: string | undefined) => {
  if (amount == null) return '—';
  const sym = currency === 'USD' ? 'USD $' : currency === 'EUR' ? '€' : '$';
  return `${sym}${amount.toLocaleString('es-MX', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
};

const fmtDate = (d: string | undefined) => {
  if (!d) return '—';
  try { return new Date(d).toLocaleDateString('es-MX', { day: '2-digit', month: 'long', year: 'numeric' }); }
  catch { return d; }
};

function buildHtml(payment: {
  paymentId?: number | string;
  supplierName?: string;
  amount?: number;
  currency?: string;
  paymentDate?: string;
  dueDate?: string;
  method?: string;
  reference?: string;
  notes?: string;
}, senderName: string, appUrl: string): string {
  const rows = [
    ['Proveedor',        payment.supplierName ?? '—'],
    ['Monto',            fmtCurrency(payment.amount, payment.currency)],
    ['Fecha de pago',    fmtDate(payment.paymentDate)],
    ['Fecha de vencim.', fmtDate(payment.dueDate)],
    ['Método',           payment.method ?? '—'],
    ['Referencia',       payment.reference ?? '—'],
  ].map(([label, value]) => `
    <tr>
      <td style="padding:8px 12px;font-weight:600;color:#6b7280;white-space:nowrap;border-bottom:1px solid #f3f4f6;">${label}</td>
      <td style="padding:8px 12px;color:#111827;border-bottom:1px solid #f3f4f6;">${value}</td>
    </tr>`).join('');

  const notesBlock = payment.notes ? `
    <div style="margin-top:20px;padding:12px 16px;background:#f9fafb;border-radius:8px;border:1px solid #e5e7eb;">
      <p style="margin:0 0 4px;font-weight:600;font-size:13px;color:#6b7280;">Notas</p>
      <p style="margin:0;font-size:14px;color:#374151;">${payment.notes}</p>
    </div>` : '';

  return `<!DOCTYPE html>
<html lang="es">
<head><meta charset="UTF-8"></head>
<body style="margin:0;padding:0;font-family:Arial,sans-serif;background:#f3f4f6;">
  <table width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6;padding:32px 0;">
    <tr><td align="center">
      <table width="560" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 1px 4px rgba(0,0,0,.08);">
        <!-- Header -->
        <tr>
          <td style="background:#1d4ed8;padding:28px 32px;">
            <h1 style="margin:0;color:#ffffff;font-size:20px;font-weight:700;">Comprobante de pago</h1>
            <p style="margin:6px 0 0;color:#bfdbfe;font-size:14px;">Folio #${payment.paymentId ?? '—'}</p>
          </td>
        </tr>
        <!-- Body -->
        <tr>
          <td style="padding:28px 32px;">
            <p style="margin:0 0 20px;font-size:15px;color:#374151;">
              Estimado proveedor, adjuntamos el comprobante del pago realizado. A continuación los detalles:
            </p>
            <table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #e5e7eb;border-radius:8px;overflow:hidden;font-size:14px;">
              ${rows}
            </table>
            ${notesBlock}
            <div style="margin-top:28px;padding-top:20px;border-top:1px solid #f3f4f6;font-size:13px;color:#9ca3af;">
              Enviado por <strong style="color:#374151;">${senderName}</strong> desde
              <a href="${appUrl}" style="color:#2563eb;text-decoration:none;">Sapience Operations</a>
            </div>
          </td>
        </tr>
      </table>
    </td></tr>
  </table>
</body>
</html>`;
}

export default createEndpoint({
  authenticated: true,
  description: 'Send payment receipt to supplier via Outlook (Microsoft Graph API)',
  inputSchema: z.object({
    paymentId: z.string(),
    newStatus: z.string().optional(),
  }),
  outputSchema: z.object({ success: z.boolean(), message: z.string() }),
  execute: async ({ input, context }) => {
    const accessToken = process.env.ZITE_OUTLOOK_ACCESS_TOKEN;
    if (!accessToken) {
      throw new ZiteError({
        code: 'BAD_REQUEST',
        message: 'La integración de Outlook no está configurada correctamente.',
      });
    }

    // ── Fetch payment ─────────────────────────────────────────────────────
    const payment = await Payments.findOne({ id: input.paymentId });
    if (!payment) throw new ZiteError({ code: 'NOT_FOUND', message: 'Pago no encontrado.' });

    if (!payment.attachment || payment.attachment.length === 0) {
      throw new ZiteError({ code: 'BAD_REQUEST', message: 'Este pago no tiene comprobante adjunto.' });
    }

    // ── Find supplier email ────────────────────────────────────────────────
    let recipientEmail: string | undefined;
    if (payment.supplierName) {
      const supplier = await Suppliers.findOne({ filters: { supplierName: payment.supplierName } });
      recipientEmail = supplier?.email;
    }
    if (!recipientEmail) {
      throw new ZiteError({ code: 'BAD_REQUEST', message: 'El proveedor no tiene email registrado en el catálogo de proveedores.' });
    }

    // ── Build email ───────────────────────────────────────────────────────
    const senderName = [context.user!.firstName, context.user!.lastName].filter(Boolean).join(' ') || context.user!.email;
    const appUrl     = process.env.ZITE_APP_URL ?? '';
    const sendAsEmail = process.env.ZITE_OUTLOOK_SEND_AS_EMAIL?.trim() || undefined;

    const subject = `Comprobante de pago #${payment.paymentId ?? ''} – ${payment.supplierName ?? ''}`;
    const htmlBody = buildHtml(payment as Parameters<typeof buildHtml>[0], senderName, appUrl);

    // ── Download attachment and convert to base64 ─────────────────────────
    const attachments: unknown[] = [];
    for (const att of payment.attachment as Array<{ url: string; filename?: string }>) {
      try {
        const resp = await fetch(att.url);
        if (!resp.ok) continue;
        const buffer = await resp.arrayBuffer();
        const base64 = Buffer.from(buffer).toString('base64');
        const ext    = (att.url.split('?')[0].split('.').pop() ?? 'pdf').toLowerCase();
        const mime   = ext === 'pdf' ? 'application/pdf'
                     : ext === 'png' ? 'image/png'
                     : ext === 'jpg' || ext === 'jpeg' ? 'image/jpeg'
                     : 'application/octet-stream';
        const name   = att.filename ?? `comprobante-${payment.paymentId ?? 'pago'}.${ext}`;
        attachments.push({
          '@odata.type': '#microsoft.graph.fileAttachment',
          name,
          contentType: mime,
          contentBytes: base64,
        });
      } catch {
        // Skip attachment on download error — still send the email
      }
    }

    // ── Send via Microsoft Graph ──────────────────────────────────────────
    const mailPayload = {
      message: {
        subject,
        body: { contentType: 'HTML', content: htmlBody },
        toRecipients: [{ emailAddress: { address: recipientEmail } }],
        ...(sendAsEmail ? { from: { emailAddress: { address: sendAsEmail } } } : {}),
        ...(attachments.length > 0 ? { attachments } : {}),
      },
      saveToSentItems: true,
    };

    const graphResp = await fetch('https://graph.microsoft.com/v1.0/me/sendMail', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${accessToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(mailPayload),
    });

    if (!graphResp.ok) {
      const errText = await graphResp.text().catch(() => '');
      throw new ZiteError({
        code: 'INTERNAL_ERROR',
        message: `Error al enviar por Outlook (${graphResp.status}): ${errText.slice(0, 300)}`,
      });
    }

    // ── Optionally update payment status ──────────────────────────────────
    if (input.newStatus) {
      const autoDate = input.newStatus === 'Realizado' && (!payment.paymentDate || payment.paymentDate === '')
        ? { paymentDate: new Date().toISOString().split('T')[0] }
        : {};
      await Payments.update({
        id: input.paymentId,
        record: { status: input.newStatus, ...autoDate },
      });
    }

    const statusSuffix = input.newStatus ? ` — pago marcado como "${input.newStatus}"` : '';
    const attNote      = attachments.length > 0 ? ` con ${attachments.length} adjunto(s)` : ' (sin adjuntos)';
    return { success: true, message: `Comprobante enviado a ${recipientEmail}${attNote}${statusSuffix}` };
  },
});

import { z } from 'zod';
import { createEndpoint, SharedViews } from 'zite-integrations-backend-sdk';

/**
 * Removes the external shared view linked to an internal view,
 * and clears the sharedToken field on the internal view so a new one can be created later.
 */
export default createEndpoint({
  description: 'Unlinks and deletes the external shared view associated with an internal view',
  authenticated: true,
  inputSchema: z.object({
    internalViewId: z.string(),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input }) => {
    const internalView = await SharedViews.findOne({ id: input.internalViewId });
    if (!internalView) throw new Error('Vista interna no encontrada');

    const existingToken = internalView.sharedToken;

    if (existingToken) {
      // Find and delete the external view stub
      const externalView = await SharedViews.findOne({
        filters: { token: existingToken, type: 'External' },
      });
      if (externalView) {
        await SharedViews.delete({ id: externalView.id });
      }

      // Clear sharedToken from the internal view
      await SharedViews.update({
        id: input.internalViewId,
        record: { sharedToken: '' },
      });
    }

    return { success: true };
  },
});

