  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [groupColIds]);

  const toggleSelect = (id: string) => setSelectedIds(prev => { const n = new Set(prev); n.has(id) ? n.delete(id) : n.add(id); return n; });
