    // ── Guard: deduplicate sentinel columns ──────────────────────────────
    // If multiple __fillout_link__ sentinels exist for the same board, keep the
    // one with the most mappings and silently delete the rest.
    if (cols.length > 1) {
      console.warn(`[syncFilloutResponses] Found ${cols.length} sentinel columns for board ${resolvedBoardId} — merging`);
      // Sort by mapping count descending so cols[0] becomes the richest sentinel
      cols.sort((a, b) => {
        const aLen = (() => { try { return (JSON.parse(a.optionsJson ?? '{}').questionMapping ?? []).length; } catch { return 0; } })();
        const bLen = (() => { try { return (JSON.parse(b.optionsJson ?? '{}').questionMapping ?? []).length; } catch { return 0; } })();
        return bLen - aLen;
      });
      // Delete extras (best-effort, non-blocking)
      for (let si = 1; si < cols.length; si++) {
        try { await BoardColumns.delete({ id: cols[si].id }); } catch { /* ignore */ }
      }
    }

    // ── Guard: deduplicate sentinel columns ──────────────────────────────
    // If multiple __fillout_link__ sentinels exist for the same board, keep the
    // one with the most mappings and silently delete the rest.
    if (cols.length > 1) {
      console.warn(`[syncFilloutResponses] Found ${cols.length} sentinel columns for board ${resolvedBoardId} — merging`);
      // Sort by mapping count descending so cols[0] becomes the richest sentinel
      cols.sort((a, b) => {
        const aLen = (() => { try { return (JSON.parse(a.optionsJson ?? '{}').questionMapping ?? []).length; } catch { return 0; } })();
        const bLen = (() => { try { return (JSON.parse(b.optionsJson ?? '{}').questionMapping ?? []).length; } catch { return 0; } })();
        return bLen - aLen;
      });
      // Delete extras (best-effort, non-blocking)
      for (let si = 1; si < cols.length; si++) {
        try { await BoardColumns.delete({ id: cols[si].id }); } catch { /* ignore */ }
      }
    }

    const linkCol = cols[0];
    if (!linkCol?.optionsJson) return { imported: 0, total: 0 };

    const meta = JSON.parse(linkCol.optionsJson) as {
      formId: string;
      formName: string;
      boardId: string;
      projectCode: string;
      boardName: string;
      questionMapping?: { filloutId: string; columnId: string; questionName: string }[];
    };
    const { formId, formName, projectCode, boardName } = meta;
    let questionMapping = meta.questionMapping ?? [];

    const idToColId = new Map<string, string>();
    for (const entry of questionMapping) {
      idToColId.set(entry.filloutId, entry.columnId);
    }

    // ── 1a. Detect new form questions added after initial link ─────────────
    // Fetch current form schema from Fillout
    const formSchemaRes = await fetch(`https://api.fillout.com/v1/api/forms/${formId}`, {
      headers: { Authorization: `Bearer ${apiKey}` },
    });
    const currentFormQuestions: { id: string; name: string; type: string }[] = [];
    if (formSchemaRes.ok) {
      const formData = await formSchemaRes.json();
      currentFormQuestions.push(...(formData.questions ?? []));
    }

    // ── 1b. Fetch all board columns (for ordering + name dedup + type map) ─
    // Dual-read board columns: UUID first, legacy fallback
    const { records: boardColsUuid } = await BoardColumns.findAll({
      filters: { boardId: resolvedBoardId },
      limit: 500,
      fields: ['id', 'columnName', 'columnType', 'columnOrder'],
    });
    let boardCols = [...boardColsUuid];
    if (legacyBoardId && legacyBoardId !== resolvedBoardId) {
      const { records: boardColsLegacy } = await BoardColumns.findAll({
        filters: { boardId: legacyBoardId },
        limit: 500,
        fields: ['id', 'columnName', 'columnType', 'columnOrder'],
      });
      const seenNames = new Set(boardCols.map(c => c.columnName?.toLowerCase() ?? ''));
      for (const lc of boardColsLegacy) {
        if (!seenNames.has(lc.columnName?.toLowerCase() ?? '')) {
          boardCols.push(lc);
          seenNames.add(lc.columnName?.toLowerCase() ?? '');
        }
      }
    }
    const colIdToType = new Map(boardCols.map(c => [c.id, c.columnType ?? '']));

    // ── 1c. Auto-create columns for new questions not in the mapping ────────
    if (currentFormQuestions.length > 0) {
      const mappedFilloutIds = new Set(questionMapping.map(m => m.filloutId));

      // Build a name→colId lookup for existing board columns
      const colByNorm = new Map<string, string>();
      for (const col of boardCols) {
        if (col.columnName && col.columnType !== '__fillout_link__') {
          colByNorm.set(normalize(col.columnName), col.id);
        }
      }

      const visibleColCount = boardCols.filter(c => c.columnType !== '__fillout_link__').length;

      // Partition new questions into "create" and "map to existing"
      const toCreate: { filloutId: string; name: string; type: string; orderOffset: number }[] = [];
      const toMapExisting: { filloutId: string; columnId: string; questionName: string }[] = [];
      const seenNorms = new Set<string>();

      for (const q of currentFormQuestions) {
        const name = (q.name ?? '').trim();
        if (!name) continue;
        if (mappedFilloutIds.has(q.id)) continue;  // already mapped
        if (matchCore(name)) continue;               // core field — handled separately

        const normName = normalize(name);

        // A column with this name already exists → just add to mapping
        const existingColId = colByNorm.get(normName);
        if (existingColId) {
          toMapExisting.push({ filloutId: q.id, columnId: existingColId, questionName: name });
          continue;
        }

        if (seenNorms.has(normName)) continue; // duplicate question name in form
        seenNorms.add(normName);
        toCreate.push({ filloutId: q.id, name, type: q.type, orderOffset: toCreate.length });
      }

      // Bulk-create new columns (batches of 100)
      const newMappingEntries: { filloutId: string; columnId: string; questionName: string }[] = [
        ...toMapExisting,
      ];

      if (toCreate.length > 0) {
        const BATCH = 100;
        for (let i = 0; i < toCreate.length; i += BATCH) {
          const batch = toCreate.slice(i, i + BATCH);
          const created = await BoardColumns.bulkCreate({
            records: batch.map(c => ({
              columnName: c.name,
              boardId: resolvedBoardId,
              columnType: toColType(c.type),
              columnOrder: visibleColCount + c.orderOffset,
            })),
          });
          for (let j = 0; j < created.records.length; j++) {
            const colId   = created.records[j].id;
            const colType = toColType(batch[j].type);
            newMappingEntries.push({ filloutId: batch[j].filloutId, columnId: colId, questionName: batch[j].name });
            colIdToType.set(colId, colType);
          }
        }
      }

      // Merge new entries into the mapping + update idToColId + persist if anything changed
      if (newMappingEntries.length > 0) {
        for (const e of newMappingEntries) {
          questionMapping.push(e);
          idToColId.set(e.filloutId, e.columnId);
        }
        // Persist updated mapping to the sentinel column
        try {
          await BoardColumns.update({
            id: linkCol.id,
            record: {
              optionsJson: JSON.stringify({ ...meta, questionMapping }),
            },
          });
        } catch { /* non-blocking — mapping will self-heal on next sync */ }
      }
    }

    // ── 1d. Fetch project dates for temporal 🔴 detection ─────────────────
    const { records: allProjects } = await Projects.findAll({
      limit: 500,
      fields: ['projectCode', 'startDate', 'endDate', 'client'],
    });
    const projectDatesMap = new Map<string, ProjectDates>();
    for (const p of allProjects) {
      if (p.projectCode) projectDatesMap.set(p.projectCode, { startDate: p.startDate, endDate: p.endDate });
    }

    // ── 2. Fetch ALL submissions from Fillout (paginated) ─────────────────
    const PAGE_SIZE = 150;
    let offset = 0;
    const submissions: any[] = [];
    while (true) {
      let res: Response | null = null;
      for (let attempt = 0; attempt < 3; attempt++) {
        res = await fetch(`https://api.fillout.com/v1/api/forms/${formId}/submissions?limit=${PAGE_SIZE}&offset=${offset}&status=finished&sort=asc`, {
          headers: { Authorization: `Bearer ${apiKey}` },
        });
        if (res.status === 429) {
          console.warn(`[syncFillout] 429 rate limit at offset ${offset}, attempt ${attempt + 1}/3 — waiting 2s`);
          await sleep(2000);
          continue;
        }
        break;
      }
      if (!res || !res.ok) break;
      const data = await res.json();
      const page: any[] = data.responses ?? data.submissions ?? (Array.isArray(data) ? data : []);
      if (page.length === 0) break;
      submissions.push(...page);
      if (page.length < PAGE_SIZE) break;
      offset += PAGE_SIZE;
      await sleep(1000);
    }

    if (submissions.length === 0) return { imported: 0, total: 0 };

    // ── 3. Get existing rows (single query, build sets for dedup) ─────────
    await sleep(100);
    const { records: existingRows } = await RecruitmentRows.findAll({
      filters: { boardName, projectCode },
      limit: 2000,
      fields: ['email', 'participantName', 'sourceForm'],
    });
    const existingEmails = new Set(existingRows.map(r => r.email?.toLowerCase()).filter(Boolean));
    const existingNames  = new Set(existingRows.map(r => normalize(r.participantName ?? '')).filter(Boolean));
    const importedSubmissionIds = new Set<string>();
    for (const r of existingRows) {
      if (r.sourceForm?.includes('|')) {
        const parts = r.sourceForm.split('|');
        if (parts.length >= 2) importedSubmissionIds.add(parts[parts.length - 1]);
      }
    }

    // ── 4. Process submissions in small batches to stay under rate limit ──
    let imported = 0;
    const BATCH_SIZE = 3;
    const BATCH_DELAY_MS = 600;

    for (let i = 0; i < submissions.length; i += BATCH_SIZE) {
      const batch = submissions.slice(i, i + BATCH_SIZE);

      for (const submission of batch) {
        const questions: any[] = submission.questions ?? submission.answers ?? [];

        const coreFields: Record<string, string> = {};
        const cellsToWrite: { columnId: string; value: string }[] = [];

        for (const q of questions) {
          const name  = (q.name ?? q.label ?? '').trim();
          const value = toText(q.value);

          const coreKey = matchCore(name);
          if (coreKey && value) coreFields[coreKey] = value;

          const colId = idToColId.get(q.id);
          if (colId && value) cellsToWrite.push({ columnId: colId, value });
        }

        if (!coreFields.participantName && !coreFields.email) continue;

        const submissionId = String(submission.submissionId ?? submission.id ?? '');
        const sourceFormValue = submissionId ? `${formName}|${submissionId}` : formName;

        if (submissionId && importedSubmissionIds.has(submissionId)) continue;

        const emailLower = coreFields.email?.toLowerCase() ?? '';
        const normName   = normalize(coreFields.participantName ?? '');
        if (emailLower && existingEmails.has(emailLower)) continue;
        if (!emailLower && normName && existingNames.has(normName)) continue;

        if (emailLower) existingEmails.add(emailLower);
        if (normName)   existingNames.add(normName);
        if (submissionId) importedSubmissionIds.add(submissionId);

        if (submissionId) {
          const { records: existing } = await RecruitmentRows.findAll({
            filters: { sourceForm: sourceFormValue, boardName, projectCode },
            limit: 1,
            fields: ['id'],
          });
          if (existing.length > 0) continue;
        }

        await Participants.bulkCreate({
          records: [{ fullName: coreFields.participantName, email: coreFields.email, phone: coreFields.phone, idNumber: coreFields.idNumber }],
          matchOn: coreFields.email ? ['email'] : undefined,
        });

        const record = await RecruitmentRows.create({
          record: {
            rowName: coreFields.participantName ?? coreFields.email ?? 'Sin nombre',
            projectCode, boardName,
            boardId: resolvedBoardId,
            participantName: coreFields.participantName,
            email: coreFields.email,
            phone: coreFields.phone,
            idNumber: coreFields.idNumber,
            status: 'Pendiente',
            sourceForm: sourceFormValue,
            level: 0,
          },
        });

        if (cellsToWrite.length > 0) {
          const cellRecords = cellsToWrite.map(c => {
            const isFile = colIdToType.get(c.columnId) === 'Archivo';
            return {
              boardId: resolvedBoardId,
              rowId: record.id,
              columnId: c.columnId,
              ...(isFile ? { fileUrl: c.value } : { textValue: c.value }),
            };
          });
          for (let ci = 0; ci < cellRecords.length; ci += 100) {
            await CellValues.bulkCreate({ records: cellRecords.slice(ci, ci + 100) });
          }
          await RecruitmentRows.update({
            id: record.id,
            record: {
              cellData: JSON.stringify(
                Object.fromEntries(cellsToWrite.map(c => {
                  const isFile = colIdToType.get(c.columnId) === 'Archivo';
                  return [c.columnId, isFile ? { fileUrl: c.value } : { textValue: c.value }];
                }))
              ),
            },
          });
        }

        // ── Participation / duplicate detection ────────────────────────────
        try {
          const detectionFields: string[] = ['id', 'participantName', 'email', 'phone', 'projectCode', 'boardName', 'status', 'group', 'deletedAt'];
          const queries: Promise<{ records: any[] }>[] = [];
          if (coreFields.email) {
            queries.push(RecruitmentRows.findAll({ filters: { email: coreFields.email }, limit: 50, fields: detectionFields }));
          }
          if (coreFields.participantName) {
            queries.push(RecruitmentRows.findAll({ filters: { participantName: { contains: coreFields.participantName } }, limit: 50, fields: detectionFields }));
          }
          if (coreFields.phone) {
            queries.push(RecruitmentRows.findAll({ filters: { phone: coreFields.phone }, limit: 50, fields: detectionFields }));
          }
          if (queries.length > 0) {
            const results = await Promise.all(queries);
            const seen = new Set<string>();
            const merged: any[] = [];
            for (const { records } of results) {
              for (const r of records) {
                if (!seen.has(r.id)) { seen.add(r.id); merged.push(r); }
              }
            }
            const activedupes = merged.filter(r => !r.deletedAt);
            const note = buildParticipationNote(activedupes, record.id, projectCode, boardName, projectDatesMap);
            if (note) {
              await RecruitmentRows.update({ id: record.id, record: { notes: note } });
            }
          }
        } catch { /* non-blocking */ }

        imported++;
      }

      if (i + BATCH_SIZE < submissions.length) await sleep(BATCH_DELAY_MS);
    }

    // ── 5. Backfill notes on existing rows that match any newly imported row ──
    if (imported > 0) {
      try {
        const detectionFields: string[] = ['id', 'participantName', 'email', 'phone', 'projectCode', 'boardName', 'status', 'group', 'notes', 'deletedAt'];

        const { records: allProjectRows } = await RecruitmentRows.findAll({
          filters: { projectCode },
          limit: 2000,
          fields: detectionFields,
        });
        const allActive = allProjectRows.filter(r => !r.deletedAt);

        const normalizeLocal = (s: string) =>
          s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();

        const emailMap  = new Map<string, string[]>();
        const nameMap   = new Map<string, string[]>();
        const phoneMap  = new Map<string, string[]>();
        for (const r of allActive) {
          if (r.email) {
            const k = r.email.toLowerCase().trim();
            if (!emailMap.has(k)) emailMap.set(k, []);
            emailMap.get(k)!.push(r.id);
          }
          if (r.participantName) {
            const k = normalizeLocal(r.participantName);
            if (k.length > 2) {
              if (!nameMap.has(k)) nameMap.set(k, []);
              nameMap.get(k)!.push(r.id);
            }
          }
          if (r.phone) {
            const k = r.phone.replace(/[\s\-().+]/g, '');
            if (k.length >= 7) {
              if (!phoneMap.has(k)) phoneMap.set(k, []);
              phoneMap.get(k)!.push(r.id);
            }
          }
        }

        const rowById = new Map(allActive.map(r => [r.id, r]));

        for (const row of allActive) {
          if (!row.projectCode) continue;
          const peerIds = new Set<string>();
          if (row.email) for (const id of emailMap.get(row.email.toLowerCase().trim()) ?? []) peerIds.add(id);
          if (row.participantName) {
            const k = normalizeLocal(row.participantName);
            if (k.length > 2) for (const id of nameMap.get(k) ?? []) peerIds.add(id);
          }
          if (row.phone) {
            const k = row.phone.replace(/[\s\-().+]/g, '');
            if (k.length >= 7) for (const id of phoneMap.get(k) ?? []) peerIds.add(id);
          }
          if (peerIds.size <= 1) continue;

          const peers = [...peerIds]
            .filter(id => id !== row.id)
            .map(id => rowById.get(id))
            .filter((r): r is typeof row => !!r);

          const newNote = buildParticipationNote(
            [row, ...peers],
            row.id,
            row.projectCode,
            row.boardName ?? '',
            projectDatesMap,
          );

          if (newNote !== (row.notes ?? '')) {
            await RecruitmentRows.update({ id: row.id, record: { notes: newNote || undefined } });
            await sleep(50);
          }
        }
      } catch { /* non-blocking */ }
    }

    return { imported, total: submissions.length };
  },
});

import { useState, useRef } from 'react';
import { formatDistanceToNow } from 'date-fns';
import { es } from 'date-fns/locale';
import { X, Trash2 } from 'lucide-react';
import { Dialog, DialogContent } from '@/components/ui/dialog';
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel,
  AlertDialogContent, AlertDialogDescription, AlertDialogFooter,
  AlertDialogHeader, AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { Button } from '@/components/ui/button';
import { saveDocBlock } from 'zite-endpoints-sdk';
import MinutaEditor from './MinutaEditor';

interface Props {
  open: boolean;
  blockId: string;
  initialTitle: string;
  onClose: () => void;
  onTitleChange: (title: string) => void;
  onDelete: () => void;
}

export default function MinutaDialog({ open, blockId, initialTitle, onClose, onTitleChange, onDelete }: Props) {
  const [title, setTitle] = useState(initialTitle);
  const [authorName, setAuthorName] = useState('');
  const [updatedAt, setUpdatedAt] = useState('');
  const [confirmDelete, setConfirmDelete] = useState(false);
  const titleRef = useRef<HTMLInputElement>(null);

  const handleTitleBlur = async () => {
    const trimmed = title.trim() || 'Sin título';
    setTitle(trimmed);
    onTitleChange(trimmed);
    await saveDocBlock({ id: blockId, content: trimmed }).catch(() => {});
  };

  const handleMetaChange = (name: string, at: string) => {
    setAuthorName(name);
    setUpdatedAt(at);
  };

  let relTime = '';
  try {
    if (updatedAt) relTime = formatDistanceToNow(new Date(updatedAt), { addSuffix: true, locale: es });
  } catch { /* skip */ }

  return (
    <>
      <Dialog open={open} onOpenChange={v => { if (!v) onClose(); }}>
        <DialogContent className="max-w-3xl h-[82vh] flex flex-col p-0 gap-0 overflow-hidden">
          {/* Header */}
          <div className="flex-shrink-0 flex items-center gap-3 px-5 py-3 border-b bg-card">
            <input
              ref={titleRef}
              value={title}
              onChange={e => setTitle(e.target.value)}
              onBlur={handleTitleBlur}
              onKeyDown={e => { if (e.key === 'Enter') titleRef.current?.blur(); }}
              className="flex-1 text-base font-semibold bg-transparent border-none outline-none text-foreground placeholder:text-muted-foreground/50 min-w-0"
              placeholder="Sin título"
            />
            <div className="flex items-center gap-1 flex-shrink-0">
              <Button
                variant="ghost"
                size="icon"
                className="h-7 w-7 text-muted-foreground hover:text-destructive"
                onClick={() => setConfirmDelete(true)}
              >
                <Trash2 className="w-3.5 h-3.5" />
              </Button>
              <Button
                variant="ghost"
                size="icon"
                className="h-7 w-7 text-muted-foreground"
                onClick={onClose}
              >
                <X className="w-4 h-4" />
              </Button>
            </div>
          </div>

          {/* Editor */}
          <div className="flex-1 min-h-0 overflow-hidden">
            <MinutaEditor blockId={blockId} onMetaChange={handleMetaChange} />
          </div>

          {/* Footer */}
          {(authorName || relTime) && (
            <div className="flex-shrink-0 px-5 py-2 border-t bg-muted/20 text-xs text-muted-foreground/50">
              {authorName && relTime
                ? `Última edición por ${authorName} · ${relTime}`
                : authorName || relTime}
            </div>
          )}
        </DialogContent>
      </Dialog>

      <AlertDialog open={confirmDelete} onOpenChange={setConfirmDelete}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>¿Eliminar esta minuta?</AlertDialogTitle>
            <AlertDialogDescription>
              Se eliminará permanentemente "{title}". Esta acción no se puede deshacer.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancelar</AlertDialogCancel>
            <AlertDialogAction
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              onClick={() => { setConfirmDelete(false); onDelete(); }}
            >
              Eliminar
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

import { useState, useEffect, useRef, useCallback, createRef } from 'react';
import { useAuth } from 'zite-auth-sdk';
import { useDebouncedCallback } from 'use-debounce';
import { uploadFile } from 'zite-file-upload-sdk';
import { getDocBlock, saveDocBlock } from 'zite-endpoints-sdk';
import { Skeleton } from '@/components/ui/skeleton';
import { Loader2, CheckCircle2 } from 'lucide-react';
import ParagraphEditor, { ParagraphEditorHandle } from './commercial/brief/ParagraphEditor';
import ImageBlockEditor from './commercial/brief/ImageBlockEditor';
import EntityMentionMenu from './commercial/brief/EntityMentionMenu';
import {
  DocumentModel, ContentBlock, ParagraphBlock, HeadingBlock, ListItemBlock, ImageBlock,
  TriggerState, RefInline,
  generateBlockId, makeEmptyDoc, migrateMarkdownToDoc, mergeAdjacentText,
} from './commercial/brief/docTypes';
import { useCollaborativeDocument } from '../hooks/useCollaborativeDocument';

type SaveStatus = 'idle' | 'saving' | 'saved';

interface Props {
  blockId: string;
  onMetaChange?: (authorName: string, updatedAt: string) => void;
}

export default function MinutaEditor({ blockId, onMetaChange }: Props) {
  const { user } = useAuth();
  const [doc, setDoc] = useState<DocumentModel | null>(null);
  const [loading, setLoading] = useState(true);
  const [status, setStatus] = useState<SaveStatus>('idle');
  const [focusBlockId, setFocusBlockId] = useState<string | null>(null);
  const [trigger, setTrigger] = useState<TriggerState | null>(null);
  const [uploading, setUploading] = useState(false);
  const [isDragOver, setIsDragOver] = useState(false);
  const triggerBlockId   = useRef<string | null>(null);
  const focusedBlockRef  = useRef<string | null>(null);
  const docRef           = useRef<DocumentModel | null>(null);
  const opTypeRef        = useRef<'block_update' | 'structure_update'>('block_update');
  const paraRefs         = useRef<Map<string, React.RefObject<ParagraphEditorHandle>>>(new Map());
  const onMetaChangeRef  = useRef(onMetaChange);
  onMetaChangeRef.current = onMetaChange;

  useEffect(() => { docRef.current = doc; }, [doc]);

  const getParaRef = useCallback((id: string) => {
    if (!paraRefs.current.has(id)) paraRefs.current.set(id, createRef<ParagraphEditorHandle>());
    return paraRefs.current.get(id)!;
  }, []);

  // ── Initial load ─────────────────────────────────────────────────────────
  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    const load = async () => {
      try {
        const { block } = await getDocBlock({ id: blockId });
        if (cancelled || !block) return;
        const by = user?.email ?? '';
        if (block.documentJson) {
          try {
            const parsed = JSON.parse(block.documentJson) as DocumentModel;
            setDoc(parsed); docRef.current = parsed;
          } catch {
            const migrated = migrateMarkdownToDoc(block.content ?? '', by);
            setDoc(migrated); docRef.current = migrated;
          }
        } else if (block.content) {
          const migrated = migrateMarkdownToDoc(block.content, by);
          setDoc(migrated); docRef.current = migrated;
        } else {
          const empty = makeEmptyDoc(by);
          setDoc(empty); docRef.current = empty;
        }
        if (block.authorName && block.updatedAt) onMetaChangeRef.current?.(block.authorName, block.updatedAt);
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    load();
    return () => { cancelled = true; };
  }, [blockId, user?.email]);

  // ── Reload from DB (for reconciliation) ──────────────────────────────────
  const reloadDocument = useCallback(async () => {
    try {
      const { block } = await getDocBlock({ id: blockId });
      if (!block) return;
      const by = user?.email ?? '';
      if (block.documentJson) {
        try {
          const parsed = JSON.parse(block.documentJson) as DocumentModel;
          setDoc(parsed); docRef.current = parsed;
        } catch {
          const migrated = migrateMarkdownToDoc(block.content ?? '', by);
          setDoc(migrated); docRef.current = migrated;
        }
      }
      if (block.authorName && block.updatedAt) onMetaChangeRef.current?.(block.authorName, block.updatedAt);
    } catch { /* silent */ }
  }, [blockId, user?.email]);

  // ── Collaboration hook ────────────────────────────────────────────────────
  const collab = useCollaborativeDocument({
    docId: blockId,
    setDocument: setDoc,
    docRef,
    myUser: user ? { id: user.id, email: user.email, firstName: user.firstName, lastName: user.lastName } : undefined,
    onReloadDocument: reloadDocument,
    enabled: !!user,
  });

  // ── Debounced save ────────────────────────────────────────────────────────
  const debouncedSave = useDebouncedCallback(async (jsonStr: string) => {
    setStatus('saving');
    try {
      const result = await saveDocBlock({
        id: blockId,
        documentJson: jsonStr,
        expectedVersion: docRef.current?.version,
        changedBlockId: opTypeRef.current === 'block_update' ? (focusedBlockRef.current ?? undefined) : undefined,
        operationType: opTypeRef.current,
      });

      if (result.conflict) {
        setStatus('idle');
        reloadDocument().catch(() => {});
        return;
      }

      if (result.savedVersion !== undefined) {
        setDoc(prev => prev ? { ...prev, version: result.savedVersion! } : prev);
        if (docRef.current) docRef.current = { ...docRef.current, version: result.savedVersion };
      }

      const name = `${user?.firstName ?? ''} ${user?.lastName ?? ''}`.trim() || user?.email || 'tú';
      onMetaChangeRef.current?.(name, new Date().toISOString());
      setStatus('saved');
    } catch { setStatus('idle'); }
  }, 1500);

  // ── Image helpers ─────────────────────────────────────────────────────────
  const insertImageBlock = useCallback((url: string) => {
    if (!collab.canModifyStructure()) return;
    opTypeRef.current = 'structure_update';
    const imgBlock: ImageBlock  = { id: generateBlockId(), type: 'image', url };
    const newPara: ParagraphBlock = { id: generateBlockId(), type: 'paragraph', content: [] };
    setDoc(prev => {
      if (!prev) return prev;
      const blocks = [...prev.blocks];
      const insertAfterIdx = focusedBlockRef.current
        ? blocks.findIndex(b => b.id === focusedBlockRef.current)
        : blocks.length - 1;
      const idx = insertAfterIdx >= 0 ? insertAfterIdx + 1 : blocks.length;
      blocks.splice(idx, 0, imgBlock, newPara);
      const next = { ...prev, blocks, updatedAt: new Date().toISOString() };
      docRef.current = next;
      debouncedSave(JSON.stringify(next));
      return next;
    });
    setFocusBlockId(newPara.id);
  }, [debouncedSave, collab.canModifyStructure]);

  const handleImageInsert = useCallback(async (file: File) => {
    if (!file.type.startsWith('image/')) return;
    setUploading(true);
    try {
      const { fileUrl } = await uploadFile({ data: file, filename: file.name });
      insertImageBlock(fileUrl);
    } catch { /* silent */ }
    setUploading(false);
  }, [insertImageBlock]);

  const handleDeleteImage = useCallback((id: string) => {
    if (!collab.canModifyStructure()) return;
    opTypeRef.current = 'structure_update';
    setDoc(prev => {
      if (!prev) return prev;
      const next = { ...prev, blocks: prev.blocks.filter(b => b.id !== id), updatedAt: new Date().toISOString() };
      docRef.current = next;
      debouncedSave(JSON.stringify(next));
      return next;
    });
  }, [debouncedSave, collab.canModifyStructure]);

  // ── Block callbacks ───────────────────────────────────────────────────────
  const handleBlockChange = useCallback((updated: ContentBlock) => {
    focusedBlockRef.current = updated.id;
    opTypeRef.current = 'block_update';
    setStatus('idle');
    setDoc(prev => {
      if (!prev) return prev;
      const blocks = prev.blocks.map(b => b.id === updated.id ? updated : b);
      const next = { ...prev, blocks, updatedAt: new Date().toISOString() };
      docRef.current = next;
      debouncedSave(JSON.stringify(next));
      return next;
    });
  }, [debouncedSave]);

  const handleChangeBlockType = useCallback((blockId: string, newType:
    | { type: 'paragraph' }
    | { type: 'heading'; level: 1 | 2 | 3 }
    | { type: 'listItem'; listType: 'bullet' | 'number' }
  ) => {
    focusedBlockRef.current = blockId;
    opTypeRef.current = 'block_update';
    setDoc(prev => {
      if (!prev) return prev;
      const blocks = prev.blocks.map(b => {
        if (b.id !== blockId || b.type === 'image') return b;
        const content = (b as ContentBlock).content;
        if (newType.type === 'paragraph') return { id: b.id, type: 'paragraph', content } as ParagraphBlock;
        if (newType.type === 'heading')   return { id: b.id, type: 'heading',   level: newType.level, content } as HeadingBlock;
        return { id: b.id, type: 'listItem', listType: newType.listType, content } as ListItemBlock;
      });
      const next = { ...prev, blocks, updatedAt: new Date().toISOString() };
      docRef.current = next;
      debouncedSave(JSON.stringify(next));
      return next;
    });
  }, [debouncedSave]);

  const { canModifyStructure } = collab;

  const handleEnter = useCallback((afterId: string) => {
    if (!canModifyStructure()) return;
    opTypeRef.current = 'structure_update';
    const currentBlock = docRef.current?.blocks.find(b => b.id === afterId);

    if (currentBlock?.type === 'listItem') {
      const listBlock = currentBlock as ListItemBlock;
      const contentText = listBlock.content.reduce((s, n) => s + (n.type === 'text' ? n.text : '\u200B'), '').trim();
      if (!contentText) {
        const newPara: ParagraphBlock = { id: afterId, type: 'paragraph', content: [] };
        setDoc(prev => {
          if (!prev) return prev;
          const blocks = prev.blocks.map(b => b.id === afterId ? newPara : b);
          const next = { ...prev, blocks, updatedAt: new Date().toISOString() };
          docRef.current = next;
          debouncedSave(JSON.stringify(next));
          return next;
        });
        return;
      }
      const newId = generateBlockId();
      const newItem: ListItemBlock = { id: newId, type: 'listItem', listType: listBlock.listType, content: [] };
      setDoc(prev => {
        if (!prev) return prev;
        const idx = prev.blocks.findIndex(b => b.id === afterId);
        const blocks = [...prev.blocks];
        blocks.splice(idx + 1, 0, newItem);
        const next = { ...prev, blocks, updatedAt: new Date().toISOString() };
        docRef.current = next;
        debouncedSave(JSON.stringify(next));
        return next;
      });
      setFocusBlockId(newId);
      return;
    }

    const newId = generateBlockId();
    const newBlock: ParagraphBlock = { id: newId, type: 'paragraph', content: [] };
    setDoc(prev => {
      if (!prev) return prev;
      const idx = prev.blocks.findIndex(b => b.id === afterId);
      const blocks = [...prev.blocks];
      blocks.splice(idx + 1, 0, newBlock);
      const next = { ...prev, blocks, updatedAt: new Date().toISOString() };
      docRef.current = next;
      debouncedSave(JSON.stringify(next));
      return next;
    });
    setFocusBlockId(newId);
  }, [debouncedSave, canModifyStructure]);

  const handleBackspace = useCallback((blockId: string) => {
    if (!canModifyStructure()) return;
    opTypeRef.current = 'structure_update';
    const blocks = docRef.current?.blocks;
    if (!blocks || blocks.length <= 1) return;
    const idx = blocks.findIndex(b => b.id === blockId);
    if (idx <= 0) return;
    const prevBlock = blocks[idx - 1];
    const currBlock = blocks[idx];
    if (prevBlock.type === 'image' || currBlock.type === 'image') return;
    const prev = prevBlock as ContentBlock;
    const curr = currBlock as ContentBlock;
    const merged: ContentBlock = { ...prev, content: mergeAdjacentText([...prev.content, ...curr.content]) };
    paraRefs.current.delete(blockId);
    setDoc(d => {
      if (!d) return d;
      const nb = [...d.blocks];
      nb[idx - 1] = merged;
      nb.splice(idx, 1);
      const next = { ...d, blocks: nb, updatedAt: new Date().toISOString() };
      docRef.current = next;
      debouncedSave(JSON.stringify(next));
      return next;
    });
    setFocusBlockId(prevBlock.id);
  }, [debouncedSave, canModifyStructure]);

  const handleTrigger = useCallback((bId: string, state: TriggerState | null) => {
    triggerBlockId.current = state ? bId : null;
    setTrigger(state);
  }, []);

  const handleMentionSelect = useCallback((ref: RefInline) => {
    const bId = triggerBlockId.current;
    if (bId) paraRefs.current.get(bId)?.current?.insertMention(ref);
    setTrigger(null);
    triggerBlockId.current = null;
  }, []);

  const handleDismiss = useCallback(() => {
    setTrigger(null);
    triggerBlockId.current = null;
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragOver(false);
    Array.from(e.dataTransfer.files).filter(f => f.type.startsWith('image/')).forEach(f => handleImageInsert(f));
  }, [handleImageInsert]);

  const handlePaste = useCallback((e: React.ClipboardEvent) => {
    const files = Array.from(e.clipboardData.files).filter(f => f.type.startsWith('image/'));
    if (files.length > 0) { e.preventDefault(); files.forEach(f => handleImageInsert(f)); }
  }, [handleImageInsert]);

  // ── Render ────────────────────────────────────────────────────────────────
  if (loading) {
    return (
      <div className="p-6 space-y-2.5">
        <Skeleton className="h-4 w-full" />
        <Skeleton className="h-4 w-4/5" />
        <Skeleton className="h-4 w-3/4" />
      </div>
    );
  }

  if (!doc) return null;

  return (
    <div className="flex flex-col h-full">
      {/* ── Status bar ── */}
      <div className="flex items-center justify-between px-6 py-1.5 border-b bg-muted/30 flex-shrink-0">
        <span className="text-[10px] text-muted-foreground/40 tracking-wide select-none">
          @ personas · # proyectos · ! eventos · / grupos · arrastra imágenes
        </span>
        <span className="h-4 flex items-center gap-2">
          {uploading && (
            <span className="flex items-center gap-1 text-xs text-muted-foreground">
              <Loader2 className="w-3 h-3 animate-spin" /> Subiendo imagen...
            </span>
          )}
          {!uploading && status === 'saving' && (
            <span className="flex items-center gap-1 text-xs text-muted-foreground">
              <Loader2 className="w-3 h-3 animate-spin" /> Guardando...
            </span>
          )}
          {!uploading && status === 'saved' && (
            <span className="flex items-center gap-1 text-xs text-chart-2 font-medium">
              <CheckCircle2 className="w-3 h-3" /> Guardado
            </span>
          )}
        </span>
      </div>

      {/* ── Collaboration banners ── */}
      {collab.structureLockOwner && (
        <div className="flex items-center gap-2 px-4 py-1.5 bg-primary/8 border-b border-primary/15 text-xs text-primary flex-shrink-0">
          <span>✏️ <strong>{collab.structureLockOwner}</strong> está modificando la estructura del documento</span>
        </div>
      )}


      {/* ── Editor surface ── */}
      <div
        className={`flex-1 overflow-y-auto px-6 py-4 transition-colors ${isDragOver ? 'bg-primary/5 ring-2 ring-inset ring-primary/20' : ''}`}
        onDragOver={e => { e.preventDefault(); setIsDragOver(true); }}
        onDragLeave={() => setIsDragOver(false)}
        onDrop={handleDrop}
        onPaste={handlePaste}
      >
        {doc.blocks.map((block, blockIdx) => {
          if (block.type === 'image') {
            return <ImageBlockEditor key={block.id} block={block} onDelete={handleDeleteImage} />;
          }
          // Compute lock from collab.locks (state, always current in render)
          const lockEntry  = collab.locks[block.id];
          const isLocked   = !!(lockEntry && lockEntry.expiresAt > Date.now());
          const lockedBy   = isLocked ? { userName: lockEntry.userName, userEmail: lockEntry.userEmail } : null;

          let listIndex: number | undefined;
          if (block.type === 'listItem' && block.listType === 'number') {
            let start = blockIdx;
            while (start > 0 && doc.blocks[start - 1].type === 'listItem' && (doc.blocks[start - 1] as ListItemBlock).listType === 'number') {
              start--;
            }
            listIndex = blockIdx - start + 1;
          }

          return (
            <div key={block.id} onFocus={() => { focusedBlockRef.current = block.id; }}>
              <ParagraphEditor
                ref={getParaRef(block.id)}
                block={block}
                onChange={handleBlockChange}
                onEnter={handleEnter}
                onBackspace={handleBackspace}
                onTrigger={state => handleTrigger(block.id, state)}
                onChangeBlockType={handleChangeBlockType}
                listIndex={listIndex}
                autoFocus={focusBlockId === block.id}
                lockedBy={lockedBy}
                isReadOnly={isLocked}
                onFocusBlock={() => collab.acquireBlockLock(block.id)}
                onBlurBlock={() => collab.releaseBlockLock(block.id)}
              />
            </div>
          );
        })}

        {/* Click-to-focus area */}
        <div
          className="min-h-20 cursor-text"
          onClick={() => {
            const blocks = docRef.current?.blocks;
            if (!blocks?.length) return;
            const lastPara = [...blocks].reverse().find(b => b.type !== 'image');
            if (lastPara) paraRefs.current.get(lastPara.id)?.current?.focus();
          }}
        />
        {isDragOver && (
          <div className="pointer-events-none absolute inset-0 flex items-center justify-center">
            <p className="text-sm text-primary font-medium bg-card/90 px-4 py-2 rounded-xl shadow">Suelta para insertar imagen</p>
          </div>
        )}
      </div>

      <EntityMentionMenu trigger={trigger} onSelect={handleMentionSelect} onDismiss={handleDismiss} />
    </div>
  );
}

import { useState, useEffect, useRef } from 'react';
import { Input } from '@/components/ui/input';

interface NumericInputProps {
  value: number;
  onChange: (value: number) => void;
  className?: string;
  placeholder?: string;
  min?: number;
  disabled?: boolean;
  title?: string;
  formatDisplay?: (value: number) => string;
}

export default function NumericInput({
  value,
  onChange,
  className,
  placeholder = '0',
  min,
  disabled,
  title,
  formatDisplay,
}: NumericInputProps) {
  const [internal, setInternal] = useState(
    value === 0 ? '' : formatDisplay ? formatDisplay(value) : String(value)
  );
  const isFocused = useRef(false);

  useEffect(() => {
    if (!isFocused.current) {
      if (formatDisplay && value > 0) {
        setInternal(formatDisplay(value));
      } else {
        setInternal(value === 0 ? '' : String(value));
      }
    }
  }, [value]);

  const handleFocus = () => {
    isFocused.current = true;
    setInternal(value === 0 ? '' : String(value));
  };

  const handleBlur = () => {
    isFocused.current = false;
    const parsed = parseFloat(internal.replace(',', '.'));
    if (internal.trim() === '' || isNaN(parsed)) {
      setInternal('');
      onChange(0);
    } else {
      const clamped = min !== undefined ? Math.max(min, parsed) : parsed;
      setInternal(formatDisplay && clamped > 0 ? formatDisplay(clamped) : String(clamped));
      onChange(clamped);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const raw = e.target.value;
    if (raw === '' || /^-?\d*[.,]?\d*$/.test(raw)) {
      setInternal(raw);
      const parsed = parseFloat(raw.replace(',', '.'));
      if (!isNaN(parsed)) {
        onChange(parsed);
      }
    }
  };

  return (
    <Input
      type="text"
      inputMode="decimal"
      value={internal}
      placeholder={placeholder}
      disabled={disabled}
      title={title}
      className={`placeholder:text-muted-foreground/30 ${className ?? ''}`}
      onChange={handleChange}
      onFocus={handleFocus}
      onBlur={handleBlur}
    />
  );
}

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { ChevronRight, ChevronDown, CornerDownRight, ZoomIn, ZoomOut } from 'lucide-react';
import { useDebouncedCallback } from 'use-debounce';
import { saveCellValue, saveTask } from 'zite-endpoints-sdk';
import { toast } from 'sonner';
import { type Task, type GanttScale, type BoardGanttGroup } from './pmTypes';
import { BOARD_GANTT_STATUS_COLORS } from './pmConstants';
import { fmtDate } from './pmDateUtils';
import { getGroupColor } from '../table/tableUtils';
import { type DynCols } from '../DynamicColumns';
import type { DynColumn } from '../../hooks/useDynamicColumns';

// ── Row height constants ─────────────────────────────────────────────────────
const PARENT_ROW_H = 36;
const CHILD_ROW_H  = 30;
const GROUP_H      = 30;

// ── Color picker ─────────────────────────────────────────────────────────────
function BoardGanttBarColorPicker({ taskId, boardId, colorColId, currentColor, recentColors, onColorChange }: {
  taskId: string; boardId: string; colorColId: string; currentColor: string;
  recentColors: string[]; onColorChange: (taskId: string, color: string) => void;
}) {
  const [open, setOpen] = useState(false);
  const [localHex, setLocalHex] = useState(currentColor || '#6366f1');
  const inputRef = useRef<HTMLInputElement>(null);

  const debouncedSave = useDebouncedCallback(async (hex: string) => {
    onColorChange(taskId, hex);
    try { await saveCellValue({ boardId, rowId: taskId, columnId: colorColId, textValue: hex }); } catch { /* best-effort */ }
  }, 400);

  const applyColor = async (hex: string) => {
    setLocalHex(hex); onColorChange(taskId, hex); setOpen(false);
    try { await saveCellValue({ boardId, rowId: taskId, columnId: colorColId, textValue: hex }); } catch { /* best-effort */ }
  };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <button className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" onClick={e => { e.stopPropagation(); setOpen(true); }} title="Cambiar color" />
      </PopoverTrigger>
      <PopoverContent className="p-0 w-52" align="center" onClick={e => e.stopPropagation()}>
        <div className="p-2 border-b border-border"><p className="text-xs font-medium text-muted-foreground px-1">Color de la barra</p></div>
        <div className="p-3 space-y-3">
          {recentColors.length > 0 && (
            <div>
              <p className="text-[10px] text-muted-foreground mb-1.5">Recientes</p>
              <div className="flex flex-wrap gap-1.5">
                {recentColors.map(hex => (
                  <button key={hex} title={hex} onClick={() => applyColor(hex)}
                    className={`w-5 h-5 rounded-full border transition-all hover:scale-110 ${currentColor === hex ? 'ring-2 ring-offset-1 ring-foreground scale-110' : 'border-border/50'}`}
                    style={{ backgroundColor: hex }} />
                ))}
              </div>
            </div>
          )}
          <div>
            <input ref={inputRef} type="color" className="sr-only" value={localHex}
              onChange={e => { setLocalHex(e.target.value); debouncedSave(e.target.value); }} />
            <button onClick={() => inputRef.current?.click()}
              className="w-full flex items-center gap-2.5 px-2 py-1.5 rounded-md border border-border/50 hover:bg-muted transition-colors text-left">
              <div className="w-5 h-5 rounded-full border border-border/50 flex-shrink-0" style={{ backgroundColor: localHex }} />
              <span className="text-xs text-foreground">Elegir color personalizado</span>
            </button>
          </div>
        </div>
        {currentColor && (
          <div className="px-3 pb-3">
            <button className="w-full text-xs text-muted-foreground hover:text-destructive text-center py-1 rounded hover:bg-muted/50 transition-colors"
              onClick={async () => { onColorChange(taskId, ''); setOpen(false); try { await saveCellValue({ boardId, rowId: taskId, columnId: colorColId, textValue: '' }); } catch { /**/ } }}>
              Quitar color
            </button>
          </div>
        )}
      </PopoverContent>
    </Popover>
  );
}

// ── Row types ─────────────────────────────────────────────────────────────────
type GanttRow =
  | { kind: 'group-header'; group: BoardGanttGroup; groupColor: string }
  | { kind: 'task';         task: Task;              groupColor: string }
  | { kind: 'child';        task: Task;              groupColor: string };

const rowH   = (r: GanttRow) => r.kind === 'group-header' ? GROUP_H : r.kind === 'child' ? CHILD_ROW_H : PARENT_ROW_H;
const rowKey = (r: GanttRow) => r.kind === 'group-header' ? `g:${r.group.id}` : `t:${r.task.id}`;

// ── Main component ────────────────────────────────────────────────────────────
export function GanttView({ tasks, dynCols, childDynCols, groupDynCols, boardId }: {
  tasks: Task[]; dynCols: DynCols; childDynCols: DynCols; groupDynCols: DynCols; boardId: string;
}) {
  const [scale, setScale]               = useState<GanttScale>('weeks');
  const [colorMode, setColorMode]       = useState<'status' | 'color'>('status');
  const [localColors, setLocalColors]   = useState<Map<string, string>>(new Map());
  const [localDates, setLocalDates]     = useState<Map<string, { start: string; end: string }>>(new Map());
  const [collapsedGroups, setCollapsedGroups] = useState<Set<string>>(new Set());
  const [hoveredKey, setHoveredKey]     = useState<string | null>(null);

  const hasScrolledRef = useRef(false);
  const scrollRef      = useRef<HTMLDivElement>(null);
  const dragRef        = useRef<{
    taskId: string; edge: 'left' | 'right'; origStart: string; origEnd: string;
    startX: number; curStart: string; curEnd: string;
  } | null>(null);
  const ppdRef        = useRef(4);
  const padMinRef     = useRef(new Date());
  const saveResizeRef = useRef<((id: string, s: string, e: string) => Promise<void>) | null>(null);
  const [dragPreview, setDragPreview] = useState<{
    taskId: string; bLeft: number; bWidth: number; label: string; mouseX: number; mouseY: number;
  } | null>(null);

  // Mouse events for drag-resize
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      const drag = dragRef.current;
      if (!drag) return;
      const deltaDays = Math.round((e.clientX - drag.startX) / ppdRef.current);
      let newStart = drag.origStart, newEnd = drag.origEnd;
      if (drag.edge === 'left') {
        const d = new Date(drag.origStart + 'T00:00:00'); d.setDate(d.getDate() + deltaDays);
        if (d < new Date(drag.origEnd + 'T00:00:00')) newStart = d.toISOString().split('T')[0];
      } else {
        const d = new Date(drag.origEnd + 'T00:00:00'); d.setDate(d.getDate() + deltaDays);
        if (d > new Date(drag.origStart + 'T00:00:00')) newEnd = d.toISOString().split('T')[0];
      }
      drag.curStart = newStart; drag.curEnd = newEnd;
      const bLeft  = Math.max(0, (new Date(newStart + 'T00:00:00').getTime() - padMinRef.current.getTime()) / 86400000 * ppdRef.current);
      const bWidth = Math.max(((new Date(newEnd + 'T00:00:00').getTime() - new Date(newStart + 'T00:00:00').getTime()) / 86400000 + 1) * ppdRef.current, 4);
      setDragPreview({ taskId: drag.taskId, bLeft, bWidth, label: drag.edge === 'left' ? fmtDate(new Date(newStart + 'T00:00:00')) : fmtDate(new Date(newEnd + 'T00:00:00')), mouseX: e.clientX, mouseY: e.clientY });
    };
    const handleMouseUp = () => {
      const drag = dragRef.current;
      if (!drag) return;
      dragRef.current = null;
      document.body.style.cursor = '';
      setDragPreview(null);
      if (drag.curStart !== drag.origStart || drag.curEnd !== drag.origEnd)
        saveResizeRef.current?.(drag.taskId, drag.curStart, drag.curEnd);
    };
    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
    return () => { document.removeEventListener('mousemove', handleMouseMove); document.removeEventListener('mouseup', handleMouseUp); };
  }, []);

  // ── Helpers ──────────────────────────────────────────────────────────────
  const findCol = (name: string) =>
    (dynCols.columns.find(c => c.columnName === name) ?? childDynCols.columns.find(c => c.columnName === name)) as DynColumn | undefined;
  const startCol  = findCol('Inicio');
  const endCol    = findCol('Fin');
  const statusCol = findCol('Estado');
  const colorCol  = dynCols.columns.find(c => c.columnName?.toLowerCase() === 'color');

  const getDateVal = (id: string, col?: DynColumn) =>
    col ? ((dynCols.getCellVal(id, col.id) ?? childDynCols.getCellVal(id, col.id))?.dateValue?.split('T')[0] ?? '') : '';

  const getStatus = (t: Task) => {
    if (statusCol) {
      const c = dynCols.getCellVal(t.id, statusCol.id) ?? childDynCols.getCellVal(t.id, statusCol.id);
      if (c?.textValue) return c.textValue;
    }
    return t.status ?? 'Pendiente';
  };

  const tStart = (t: Task) => localDates.get(t.id)?.start || getDateVal(t.id, startCol) || t.startDate?.split('T')[0] || '';
  const tEnd   = (t: Task) => localDates.get(t.id)?.end   || getDateVal(t.id, endCol)   || t.endDate?.split('T')[0]   || '';

  const getTaskBarColor = (t: Task, fallback: string) => {
    if (colorMode === 'color') {
      const lc = localColors.get(t.id);
      if (lc !== undefined) return lc || fallback;
      const stored = colorCol ? (dynCols.getCellVal(t.id, colorCol.id)?.textValue ?? '') : '';
      return stored || fallback;
    }
    return BOARD_GANTT_STATUS_COLORS[getStatus(t)] ?? fallback;
  };

  const groups        = groupDynCols.columns;
  const getTaskGroupId = (taskId: string) =>
    groups.find(g => groupDynCols.getCellVal(taskId, g.id)?.textValue === '1')?.id ?? null;

  const topLevelWithDates = tasks.filter(t => !t.parentTaskId && tStart(t) && tEnd(t));

  // eslint-disable-next-line react-hooks/exhaustive-deps
  const recentColors = useMemo(() => {
    if (!colorCol) return [];
    const seen = new Set<string>(); const result: string[] = [];
    for (const t of tasks.filter(t => !t.parentTaskId)) {
      const hex = dynCols.getCellVal(t.id, colorCol.id)?.textValue;
      if (hex && !seen.has(hex)) { seen.add(hex); result.push(hex); }
      if (result.length >= 10) break;
    }
    return result;
  }, [tasks, colorCol, dynCols.getCellVal]);

  if (topLevelWithDates.length === 0) return (
    <div className="text-center text-muted-foreground py-16">No hay tareas con fechas de inicio y fin para el Gantt.</div>
  );

  // ── Date math ─────────────────────────────────────────────────────────────
  const allDates  = topLevelWithDates.flatMap(t => [new Date(tStart(t)), new Date(tEnd(t))]);
  const minD      = new Date(Math.min(...allDates.map(d => d.getTime())));
  const maxD      = new Date(Math.max(...allDates.map(d => d.getTime())));
  const padMin    = new Date(minD.getFullYear(), 0, 1);
  const padMax    = new Date(maxD.getFullYear(), 11, 31);
  const totalDays = Math.max(Math.ceil((padMax.getTime() - padMin.getTime()) / 86400000), 1);
  const pxPerDay  = scale === 'days' ? 40 : scale === 'weeks' ? 12 : 4;
  const totalWidth = totalDays * pxPerDay;
  ppdRef.current    = pxPerDay;
  padMinRef.current = padMin;

  const getLeft = (d: string) => Math.max(0, (new Date(d).getTime() - padMin.getTime()) / 86400000 * pxPerDay);
  const getBarW = (s: string, e: string) => Math.max(((new Date(e).getTime() - new Date(s).getTime()) / 86400000 + 1) * pxPerDay, 4);

  // ── Day columns & grid lines ───────────────────────────────────────────────
  const DAY_LABELS = ['D', 'L', 'M', 'X', 'J', 'V', 'S'];
  const dayCols = Array.from({ length: totalDays }, (_, i) => {
    const d = new Date(padMin); d.setDate(d.getDate() + i); d.setHours(0, 0, 0, 0);
    const dow = d.getDay();
    return { idx: i, left: i * pxPerDay, dow, isWeekend: dow === 0 || dow === 6, label: DAY_LABELS[dow], dayNum: d.getDate() };
  });
  const weekendCols = dayCols.filter(d => d.isWeekend);

  const gridLines: { label: string; left: number; isMajor: boolean }[] = [];
  {
    const cur = new Date(padMin);
    if (scale === 'days') {
      cur.setHours(0, 0, 0, 0);
      while (cur <= padMax) {
        const isMonday = cur.getDay() === 1, isFirst = cur.getDate() === 1;
        gridLines.push({ label: isFirst ? cur.toLocaleDateString('es', { day: 'numeric', month: 'short' }) : cur.getDate().toString(), left: (cur.getTime() - padMin.getTime()) / 86400000 * pxPerDay, isMajor: isMonday || isFirst });
        cur.setDate(cur.getDate() + 1);
      }
    } else if (scale === 'weeks') {
      cur.setHours(0, 0, 0, 0);
      while (cur.getDay() !== 1) cur.setDate(cur.getDate() + 1);
      while (cur <= padMax) {
        gridLines.push({ label: cur.toLocaleDateString('es', { day: 'numeric', month: 'short' }), left: (cur.getTime() - padMin.getTime()) / 86400000 * pxPerDay, isMajor: cur.getDate() <= 7 });
        cur.setDate(cur.getDate() + 7);
      }
    } else {
      const mCur = new Date(padMin.getFullYear(), padMin.getMonth(), 1);
      while (mCur <= padMax) {
        gridLines.push({ label: mCur.toLocaleDateString('es', { month: 'short', year: '2-digit' }), left: (mCur.getTime() - padMin.getTime()) / 86400000 * pxPerDay, isMajor: true });
        mCur.setMonth(mCur.getMonth() + 1);
      }
    }
  }

  const todayD    = new Date(); todayD.setHours(0, 0, 0, 0);
  const todayLeft = (todayD.getTime() - padMin.getTime()) / 86400000 * pxPerDay;
  const showToday = todayLeft > 0 && todayLeft < totalWidth;

  // ── Build groups ──────────────────────────────────────────────────────────
  const byGroup = new Map<string, Task[]>();
  byGroup.set('__none__', []);
  for (const g of groups) byGroup.set(g.id, []);
  for (const t of topLevelWithDates) {
    const gid = getTaskGroupId(t.id) ?? '__none__';
    (byGroup.get(gid) ?? byGroup.get('__none__')!).push(t);
  }
  const ganttGroups: BoardGanttGroup[] = [];
  const noneTs = byGroup.get('__none__') ?? [];
  if (noneTs.length > 0) ganttGroups.push({ id: '__none__', name: 'Sin grupo', tasks: noneTs });
  for (const g of groups) {
    const ts = byGroup.get(g.id) ?? [];
    if (ts.length > 0) ganttGroups.push({ id: g.id, name: g.columnName ?? 'Grupo', colorId: g.columnType, tasks: ts });
  }

  // ── Build flat rows array ─────────────────────────────────────────────────
  const flatRows: GanttRow[] = [];
  for (const group of ganttGroups) {
    const groupColor = getGroupColor(group.colorId);
    flatRows.push({ kind: 'group-header', group, groupColor });
    if (!collapsedGroups.has(group.id)) {
      for (const task of group.tasks) {
        flatRows.push({ kind: 'task', task, groupColor });
        tasks.filter(t => t.parentTaskId === task.id && tStart(t) && tEnd(t))
          .forEach(child => flatRows.push({ kind: 'child', task: child, groupColor }));
      }
    }
  }

  // ── Save resize ───────────────────────────────────────────────────────────
  saveResizeRef.current = async (taskId: string, newStart: string, newEnd: string) => {
    const isChild = !!tasks.find(t => t.id === taskId)?.parentTaskId;
    if (startCol && endCol) {
      const effectiveBoardId = isChild ? `${boardId}::children` : boardId;
      (isChild ? childDynCols : dynCols).setCellVal(taskId, startCol.id, { dateValue: newStart + 'T00:00:00' });
      (isChild ? childDynCols : dynCols).setCellVal(taskId, endCol.id,   { dateValue: newEnd   + 'T00:00:00' });
      try {
        await Promise.all([
          saveCellValue({ boardId: effectiveBoardId, rowId: taskId, columnId: startCol.id, dateValue: newStart + 'T00:00:00' }),
          saveCellValue({ boardId: effectiveBoardId, rowId: taskId, columnId: endCol.id,   dateValue: newEnd   + 'T00:00:00' }),
        ]);
        toast.success('Fechas actualizadas');
      } catch { toast.error('Error al guardar fechas'); }
    } else {
      setLocalDates(prev => new Map(prev).set(taskId, { start: newStart, end: newEnd }));
      try {
        await saveTask({ id: taskId, startDate: newStart, endDate: newEnd });
        toast.success('Fechas actualizadas');
      } catch {
        setLocalDates(prev => { const n = new Map(prev); n.delete(taskId); return n; });
        toast.error('Error al guardar fechas');
      }
    }
  };

  const startResize = (e: React.MouseEvent, task: Task, edge: 'left' | 'right') => {
    e.preventDefault(); e.stopPropagation();
    const s = tStart(task), en = tEnd(task);
    if (!s || !en) return;
    dragRef.current = { taskId: task.id, edge, origStart: s, origEnd: en, startX: e.clientX, curStart: s, curEnd: en };
    document.body.style.cursor = 'col-resize';
  };

  const toggleGroup = (id: string) => setCollapsedGroups(p => { const n = new Set(p); n.has(id) ? n.delete(id) : n.add(id); return n; });

  // Auto-scroll to today on first render
  if (!hasScrolledRef.current && scrollRef.current && showToday) {
    hasScrolledRef.current = true;
    requestAnimationFrame(() => scrollRef.current?.scrollTo({ left: Math.max(0, todayLeft - 400) }));
  }

  const headerH = scale !== 'months' ? 48 : 32;

  // ── Shared sub-components (rendered inside each timeline row) ─────────────
  const WeekendShading = () => <>{weekendCols.map(d => (
    <div key={d.idx} className="absolute top-0 bottom-0 pointer-events-none" style={{ left: d.left, width: pxPerDay, background: 'repeating-linear-gradient(135deg, transparent, transparent 3px, hsl(var(--muted)/0.3) 3px, hsl(var(--muted)/0.3) 5px), hsl(var(--muted)/0.7)' }} />
  ))}</>;

  const GridLinesComp = () => <>{gridLines.map((g, i) => (
    <div key={i} className={`absolute top-0 bottom-0 ${g.isMajor ? 'border-l border-border/30' : 'border-l border-border/10'}`} style={{ left: g.left }} />
  ))}</>;

  // ── LEFT column render ────────────────────────────────────────────────────
  const renderLeft = (row: GanttRow) => {
    const h = rowH(row), k = rowKey(row), isHov = hoveredKey === k;

    if (row.kind === 'group-header') {
      const collapsed = collapsedGroups.has(row.group.id);
      return (
        <div key={`l-${k}`}
          style={{ height: h, borderLeft: `3px solid ${row.groupColor}`, background: `color-mix(in srgb, ${row.groupColor} 10%, hsl(var(--card)))` }}
          className="flex items-center gap-2 px-3 border-b border-border/30 cursor-pointer select-none overflow-hidden"
          onClick={() => toggleGroup(row.group.id)}
          onMouseEnter={() => setHoveredKey(k)} onMouseLeave={() => setHoveredKey(null)}>
          {collapsed ? <ChevronRight className="w-3.5 h-3.5 text-muted-foreground flex-shrink-0" /> : <ChevronDown className="w-3.5 h-3.5 text-muted-foreground flex-shrink-0" />}
          <div className="w-2 h-2 rounded-full flex-shrink-0" style={{ background: row.groupColor }} />
          <span className="text-xs font-semibold truncate flex-1" style={{ color: row.groupColor }}>{row.group.name}</span>
          <span className="text-[10px] text-muted-foreground/60 flex-shrink-0">({row.group.tasks.length})</span>
        </div>
      );
    }

    const isChild = row.kind === 'child';
    return (
      <div key={`l-${k}`}
        style={{ height: h, ...(!isChild ? { borderLeft: `3px solid ${row.groupColor}` } : {}) }}
        className={`flex items-center border-b overflow-hidden ${isChild ? 'border-border/10' : 'border-border/20'} ${isHov ? 'bg-muted/20' : 'bg-card'}`}
        onMouseEnter={() => setHoveredKey(k)} onMouseLeave={() => setHoveredKey(null)}>
        {isChild ? (
          <div className="flex items-center gap-1 w-full overflow-hidden" style={{ paddingLeft: 20, paddingRight: 12 }}>
            <CornerDownRight className="w-3 h-3 text-muted-foreground/30 flex-shrink-0" />
            <span className="truncate text-xs text-muted-foreground">{row.task.taskName}</span>
          </div>
        ) : (
          <div className="flex items-center w-full overflow-hidden px-3">
            <span className="truncate text-sm font-medium">{row.task.taskName}</span>
          </div>
        )}
      </div>
    );
  };

  // ── TIMELINE rows render ──────────────────────────────────────────────────
  const renderTimeline = (row: GanttRow) => {
    const h = rowH(row), k = rowKey(row), isHov = hoveredKey === k;

    if (row.kind === 'group-header') {
      return (
        <div key={`tl-${k}`}
          style={{ height: h, position: 'relative', background: `color-mix(in srgb, ${row.groupColor} 5%, transparent)` }}
          className="border-b border-border/30 cursor-pointer"
          onClick={() => toggleGroup(row.group.id)}
          onMouseEnter={() => setHoveredKey(k)} onMouseLeave={() => setHoveredKey(null)}>
          <WeekendShading /><GridLinesComp />
        </div>
      );
    }

    const task = row.task, isChild = row.kind === 'child';
    const s = tStart(task), e = tEnd(task);
    const barColor      = getTaskBarColor(task, row.groupColor);
    const isDragging    = dragPreview?.taskId === task.id;
    const finalLeft     = isDragging ? dragPreview!.bLeft  : (s ? getLeft(s) : 0);
    const finalWidth    = isDragging ? dragPreview!.bWidth : (s && e ? getBarW(s, e) : 0);
    const currentColor  = localColors.has(task.id) ? (localColors.get(task.id) ?? '') : (colorCol ? (dynCols.getCellVal(task.id, colorCol.id)?.textValue ?? '') : '');

    return (
      <div key={`tl-${k}`}
        style={{ height: h, position: 'relative' }}
        className={`border-b ${isChild ? 'border-border/10' : 'border-border/20'} ${isHov ? 'bg-muted/20' : ''}`}
        onMouseEnter={() => setHoveredKey(k)} onMouseLeave={() => setHoveredKey(null)}>
        <WeekendShading />
        <GridLinesComp />
        {s && e && (
          <div className={`absolute ${isChild ? 'top-1 h-5 rounded shadow-sm' : 'top-1.5 h-6 rounded-md shadow-sm'}`}
            style={{ left: finalLeft, width: finalWidth, backgroundColor: barColor, border: `${isChild ? 1 : 1.5}px solid ${barColor}`, userSelect: 'none' }}>
            {/* Left resize */}
            <div className="absolute left-0 top-0 bottom-0 w-3 z-20 cursor-col-resize flex items-center justify-center rounded-l-sm hover:bg-white/20 transition-colors"
              onMouseDown={ev => startResize(ev, task, 'left')}>
              <div className={`w-px ${isChild ? 'h-2.5' : 'h-3'} bg-white/60 rounded-full`} />
            </div>
            {/* Label */}
            <div className="absolute inset-0 flex items-center overflow-hidden pl-3 pr-3 pointer-events-none">
              {!isChild && <div className="w-1.5 h-1.5 rounded-full flex-shrink-0 mr-1" style={{ background: BOARD_GANTT_STATUS_COLORS[getStatus(task)] ?? '#94a3b8' }} />}
              {finalWidth > (isChild ? 60 : 72) && (
                <span className={`text-[10px] text-white truncate leading-none drop-shadow-sm ${!isChild ? 'font-semibold' : ''}`}>{task.taskName}</span>
              )}
            </div>
            {/* Color picker */}
            {colorMode === 'color' && colorCol && !isChild && (
              <BoardGanttBarColorPicker taskId={task.id} boardId={boardId} colorColId={colorCol.id} currentColor={currentColor} recentColors={recentColors} onColorChange={(id, c) => setLocalColors(p => new Map(p).set(id, c))} />
            )}
            {/* Right resize */}
            <div className="absolute right-0 top-0 bottom-0 w-3 z-20 cursor-col-resize flex items-center justify-center rounded-r-sm hover:bg-white/20 transition-colors"
              onMouseDown={ev => startResize(ev, task, 'right')}>
              <div className={`w-px ${isChild ? 'h-2.5' : 'h-3'} bg-white/60 rounded-full`} />
            </div>
          </div>
        )}
        {showToday && <div className="absolute top-0 bottom-0 w-0.5 bg-destructive/60 z-10 pointer-events-none" style={{ left: todayLeft }} />}
      </div>
    );
  };

  // ── RIGHT column render ───────────────────────────────────────────────────
  const renderRight = (row: GanttRow) => {
    const h = rowH(row), k = rowKey(row), isHov = hoveredKey === k;

    if (row.kind === 'group-header') {
      return (
        <div key={`r-${k}`}
          style={{ height: h, background: `color-mix(in srgb, ${row.groupColor} 10%, hsl(var(--card)))` }}
          className="border-b border-border/30" />
      );
    }

    if (row.kind === 'task') {
      const status = getStatus(row.task), color = BOARD_GANTT_STATUS_COLORS[status] ?? '#94a3b8';
      return (
        <div key={`r-${k}`}
          style={{ height: h }}
          className={`flex items-center px-2 border-b border-border/20 ${isHov ? 'bg-muted/20' : 'bg-card'}`}
          onMouseEnter={() => setHoveredKey(k)} onMouseLeave={() => setHoveredKey(null)}>
          <span className="text-xs px-1.5 py-0.5 rounded whitespace-nowrap" style={{ backgroundColor: color + '20', color }}>{status}</span>
        </div>
      );
    }

    // child
    return (
      <div key={`r-${k}`}
        style={{ height: h }}
        className={`border-b border-border/10 ${isHov ? 'bg-muted/10' : 'bg-card'}`}
        onMouseEnter={() => setHoveredKey(k)} onMouseLeave={() => setHoveredKey(null)} />
    );
  };

  // ── JSX ───────────────────────────────────────────────────────────────────
  return (
    <div className="space-y-3">
      {/* Toolbar */}
      <div className="flex items-center justify-between gap-3 flex-wrap">
        <div className="flex items-center gap-2 flex-wrap">
          <span className="text-xs text-muted-foreground font-medium">Escala:</span>
          <div className="flex items-center bg-muted/50 rounded-lg p-0.5 border border-border/40">
            {([{ key: 'days', label: 'Días' }, { key: 'weeks', label: 'Semanas' }, { key: 'months', label: 'Meses' }] as const).map(opt => (
              <button key={opt.key} onClick={() => setScale(opt.key)}
                className={`px-3 py-1 text-xs rounded-md transition-all ${scale === opt.key ? 'bg-primary text-primary-foreground font-semibold shadow-sm' : 'text-muted-foreground hover:text-foreground hover:bg-muted'}`}>
                {opt.label}
              </button>
            ))}
          </div>
          <div className="flex items-center gap-1">
            <button onClick={() => setScale(s => s === 'months' ? 'weeks' : 'days')} className="p-1.5 rounded-md hover:bg-muted text-muted-foreground transition-colors" title="Acercar"><ZoomIn className="w-4 h-4" /></button>
            <button onClick={() => setScale(s => s === 'days' ? 'weeks' : 'months')} className="p-1.5 rounded-md hover:bg-muted text-muted-foreground transition-colors" title="Alejar"><ZoomOut className="w-4 h-4" /></button>
          </div>
          {showToday && (
            <button onClick={() => scrollRef.current?.scrollTo({ left: Math.max(0, todayLeft - 300), behavior: 'smooth' })} className="text-xs text-muted-foreground hover:text-foreground px-2 py-1 rounded-md hover:bg-muted transition-colors">
              📍 Hoy
            </button>
          )}
        </div>
        <div className="flex items-center gap-2">
          <div className="flex items-center bg-muted rounded-lg p-0.5 gap-0.5">
            <button className={`px-2.5 py-1 rounded-md text-xs font-medium transition-colors ${colorMode === 'status' ? 'bg-card text-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'}`} onClick={() => setColorMode('status')}>Estado</button>
            <button className={`px-2.5 py-1 rounded-md text-xs font-medium transition-colors ${colorMode === 'color'  ? 'bg-card text-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'}`} onClick={() => setColorMode('color')}>Color</button>
          </div>
          {colorMode === 'color' && colorCol && <span className="text-xs text-muted-foreground italic">Click en barra para cambiar color</span>}
          {colorMode === 'status' && (
            <div className="hidden sm:flex items-center gap-3">
              {Object.entries(BOARD_GANTT_STATUS_COLORS).map(([s, c]) => (
                <div key={s} className="flex items-center gap-1">
                  <div className="w-2 h-2 rounded-full" style={{ background: c }} />
                  <span className="text-[10px] text-muted-foreground">{s}</span>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Board — 3 separate zones, only the middle scrolls horizontally */}
      <div className="border rounded-xl overflow-hidden bg-card">
        <div className="flex">

          {/* ── LEFT: task names — never moves horizontally ── */}
          <div className="w-52 flex-shrink-0 bg-card border-r border-border" style={{ zIndex: 30 }}>
            <div style={{ height: headerH }} className="flex items-center px-3 border-b border-border bg-muted/50 text-xs font-semibold">
              Tarea
            </div>
            {flatRows.map(renderLeft)}
          </div>

          {/* ── MIDDLE: timeline — only this section scrolls horizontally ── */}
          <div ref={scrollRef} className="flex-1 overflow-x-auto">
            <div style={{ width: totalWidth }}>
              {/* Timeline header */}
              <div style={{ height: headerH, position: 'relative' }} className="border-b border-border bg-muted/50">
                <WeekendShading />
                {gridLines.map((g, i) => (
                  <span key={i}
                    className={`absolute text-xs whitespace-nowrap ${scale !== 'months' ? 'top-1' : 'top-1/2 -translate-y-1/2'} ${g.isMajor ? 'text-foreground/70 font-medium' : 'text-muted-foreground/50'}`}
                    style={{ left: g.left + 4 }}>
                    {g.label}
                  </span>
                ))}
                {scale !== 'months' && dayCols.map(d => (
                  <div key={d.idx} className="absolute bottom-0 flex flex-col items-center justify-center overflow-hidden"
                    style={{ left: d.left, width: pxPerDay, height: scale === 'days' ? 22 : 14 }}>
                    {scale === 'days' ? (
                      <>
                        <span className={`text-[9px] font-medium leading-none ${d.isWeekend ? 'text-destructive/60' : 'text-muted-foreground/50'}`}>{d.label}</span>
                        <span className={`text-[9px] leading-none mt-0.5 ${d.isWeekend ? 'text-destructive/60' : 'text-muted-foreground/50'}`}>{d.dayNum}</span>
                      </>
                    ) : (
                      <span className={`text-[8px] leading-none ${d.isWeekend ? 'text-destructive/60' : 'text-muted-foreground/50'}`}>{d.label}</span>
                    )}
                  </div>
                ))}
              </div>
              {/* Timeline rows */}
              {flatRows.map(renderTimeline)}
            </div>
          </div>

          {/* ── RIGHT: status badges — never moves horizontally ── */}
          <div className="w-24 flex-shrink-0 bg-card border-l border-border" style={{ zIndex: 30 }}>
            <div style={{ height: headerH }} className="flex items-center px-2 border-b border-border bg-muted/50 text-xs font-semibold">
              Estado
            </div>
            {flatRows.map(renderRight)}
          </div>

        </div>
      </div>

      {/* Drag preview tooltip */}
      {dragPreview && (
        <div className="fixed z-[300] bg-foreground text-background text-xs font-semibold px-2.5 py-1 rounded-lg shadow-xl pointer-events-none"
          style={{ left: dragPreview.mouseX + 14, top: dragPreview.mouseY - 10 }}>
          {dragPreview.label}
        </div>
      )}
    </div>
  );
}

import { useEffect, useRef, useCallback, useState } from 'react';
import { getAblyToken } from 'zite-endpoints-sdk';

export type DocChannelStatus = 'connecting' | 'connected' | 'error' | 'disabled';

interface UseDocumentChannelOptions {
  docId: string | null;
  myUserId: string;
  onBlockLock?: (data: any) => void;
  onBlockUnlock?: (data: any) => void;
  onBlockLockHeartbeat?: (data: any) => void;
  onBlockUpdate?: (data: any) => void;
  onStructureChanged?: (data: any) => void;
  onReload?: (data: any) => void;
  enabled?: boolean;
}

export function useDocumentChannel({
  docId,
  myUserId,
  onBlockLock,
  onBlockUnlock,
  onBlockLockHeartbeat,
  onBlockUpdate,
  onStructureChanged,
  onReload,
  enabled = true,
}: UseDocumentChannelOptions): { status: DocChannelStatus } {
  const [status, setStatus] = useState<DocChannelStatus>('disabled');
  const eventSourceRef  = useRef<EventSource | null>(null);
  const tokenRef        = useRef<{ token: string; expires: number } | null>(null);
  const retryTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Stable callback refs
  const cbRef = useRef({ onBlockLock, onBlockUnlock, onBlockLockHeartbeat, onBlockUpdate, onStructureChanged, onReload, myUserId });
  cbRef.current = { onBlockLock, onBlockUnlock, onBlockLockHeartbeat, onBlockUpdate, onStructureChanged, onReload, myUserId };

  const cleanup = useCallback(() => {
    if (eventSourceRef.current) {
      eventSourceRef.current.close();
      eventSourceRef.current = null;
    }
    if (retryTimeoutRef.current) {
      clearTimeout(retryTimeoutRef.current);
      retryTimeoutRef.current = null;
    }
  }, []);

  useEffect(() => {
    if (!enabled || !docId) {
      cleanup();
      setStatus('disabled');
      return;
    }

    let cancelled = false;
    const ablyChannel = `doc:${docId}`;

    const connect = async () => {
      setStatus('connecting');

      const now = Math.floor(Date.now() / 1000);
      if (!tokenRef.current || tokenRef.current.expires - now < 300) {
        try {
          const res = await getAblyToken({ channels: [ablyChannel] });
          if (res.token && res.expires) {
            tokenRef.current = { token: res.token, expires: res.expires };
          } else {
            setStatus('error');
            if (!cancelled) retryTimeoutRef.current = setTimeout(connect, 10000);
            return;
          }
        } catch {
          setStatus('error');
          if (!cancelled) retryTimeoutRef.current = setTimeout(connect, 10000);
          return;
        }
      }

      if (cancelled) return;

      const sseUrl = `https://realtime.ably.io/sse?channels=${encodeURIComponent(ablyChannel)}&accessToken=${encodeURIComponent(tokenRef.current!.token)}&v=1.2`;
      const es = new EventSource(sseUrl);
      eventSourceRef.current = es;

      es.onopen = () => {
        if (!cancelled) setStatus('connected');
      };

      es.onmessage = (event) => {
        try {
          const parsed = JSON.parse(event.data);
          const data = typeof parsed.data === 'string' ? JSON.parse(parsed.data) : parsed.data;
          if (!data) return;

          // Ignore own events
          if (data.userId === cbRef.current.myUserId) return;

          switch (parsed.name) {
            case 'block.lock':            cbRef.current.onBlockLock?.(data); break;
            case 'block.unlock':          cbRef.current.onBlockUnlock?.(data); break;
            case 'block.lock_heartbeat':  cbRef.current.onBlockLockHeartbeat?.(data); break;
            case 'block.update':          cbRef.current.onBlockUpdate?.(data); break;
            case 'doc.structure_changed': cbRef.current.onStructureChanged?.(data); break;
            case 'doc.reload':            cbRef.current.onReload?.(data); break;
          }
        } catch { /* ignore malformed */ }
      };

      es.onerror = () => {
        if (!cancelled) {
          setStatus('error');
          es.close();
          eventSourceRef.current = null;
          tokenRef.current = null;
          retryTimeoutRef.current = setTimeout(connect, 3000);
        }
      };
    };

    connect();

    return () => {
      cancelled = true;
      cleanup();
      setStatus('disabled');
    };
  }, [docId, enabled, cleanup]);

  return { status };
}

import { useEffect, useRef, useCallback, useState } from 'react';
import { updatePresence, getPresence, publishPresenceEvent } from 'zite-endpoints-sdk';
import { getCachedAblyToken, invalidateAblyToken } from '../lib/ablyTokenCache';

export type PresenceMember = {
  email: string;
  name?: string;
  profilePhoto?: string;
  pageName?: string;
};

type UseProjectPresenceOptions = {
  projectCode: string | null;
  pageName: string;
  enabled: boolean;
  user?: {
    email?: string;
    firstName?: string;
    lastName?: string;
    profilePhoto?: string;
  };
};

export function useProjectPresence({
  projectCode,
  pageName,
  enabled,
  user,
}: UseProjectPresenceOptions) {
  const [members, setMembers] = useState<PresenceMember[]>([]);

  const lastPublishRef    = useRef<number>(0);
  const eventSourceRef    = useRef<EventSource | null>(null);
  const tokenRef          = useRef<{ token: string; expires: number } | null>(null);
  const retryTimeoutRef   = useRef<ReturnType<typeof setTimeout> | null>(null);
  const heartbeatRef      = useRef<ReturnType<typeof setInterval> | null>(null);
  const pollRef           = useRef<ReturnType<typeof setInterval> | null>(null);
  // Cache name+photo from real-time events so polls can enrich presence
  const profileCacheRef   = useRef<Map<string, { name?: string; profilePhoto?: string }>>(new Map());

  const myEmail      = user?.email;
  const name         = user ? (`${user.firstName ?? ''} ${user.lastName ?? ''}`.trim() || user.email) : undefined;
  const profilePhoto = user?.profilePhoto;

  const sseCleanup = useCallback(() => {
    eventSourceRef.current?.close();
    eventSourceRef.current = null;
    if (retryTimeoutRef.current) { clearTimeout(retryTimeoutRef.current); retryTimeoutRef.current = null; }
  }, []);

  useEffect(() => {
    if (!enabled || !projectCode || !myEmail) {
      sseCleanup();
      setMembers([]);
      return;
    }

    const activeChannel = `project:${projectCode}:${pageName}`;
    const ablyChannel   = `board:${projectCode}`;
    let cancelled = false;

    // ── Publish own presence (updatePresence + publishPresenceEvent) ──────────
    const publishPresence = async () => {
      const now = Date.now();
      const isFirst = lastPublishRef.current === 0;
      if (!isFirst && now - lastPublishRef.current < 60000) return;

      try { await updatePresence({ activeChannel }); } catch { /* silent */ }
      try {
        await publishPresenceEvent({
          projectCode,
          pageName,
          activeChannel,
          name: name || undefined,
          profilePhoto: profilePhoto || undefined,
        });
        lastPublishRef.current = Date.now();
      } catch (err) {
        console.warn('[presence] publishPresenceEvent failed (rate limit?)', err);
      }
    };

    // ── Fetch full presence snapshot from DB and merge with profile cache ─────
    const fetchAndSetPresence = async () => {
      try {
        const data = await getPresence({});
        const prefix   = `project:${projectCode}:`;
        const filtered = data.users.filter(u => u.email !== myEmail && u.activeChannel?.startsWith(prefix));
        setMembers(filtered.map(u => {
          const cached   = profileCacheRef.current.get(u.email);
          const pg       = (u.activeChannel ?? '').slice(prefix.length);
          // Prefer SSE cache (most recent), fall back to DB fields from poll
          const fullName = cached?.name
            ?? ([u.firstName, u.lastName].filter(Boolean).join(' ').trim() || undefined);
          const photo    = cached?.profilePhoto ?? u.profilePhoto ?? undefined;
          return { email: u.email, name: fullName, profilePhoto: photo, pageName: pg };
        }));
      } catch { /* silent */ }
    };

    // ── SSE connection — shares Ably token with useRealtimeBoardEvents ────────
    // Both hooks connect to the same board:{projectCode} channel. Using the
    // shared token cache ensures only one getAblyToken request fires even if
    // both hooks connect simultaneously.
    const connect = async () => {
      const now = Math.floor(Date.now() / 1000);
      if (!tokenRef.current || tokenRef.current.expires - now < 300) {
        const tokenResult = await getCachedAblyToken(ablyChannel);
        if (tokenResult) {
          tokenRef.current = tokenResult;
        } else {
          if (!cancelled) retryTimeoutRef.current = setTimeout(connect, 10000);
          return;
        }
      }
      if (cancelled) return;

      const sseUrl = `https://realtime.ably.io/sse?channels=${encodeURIComponent(ablyChannel)}&accessToken=${encodeURIComponent(tokenRef.current!.token)}&v=1.2`;
      const es = new EventSource(sseUrl);
      eventSourceRef.current = es;

      es.onmessage = (event) => {
        try {
          const parsed = JSON.parse(event.data);
          if (parsed.name !== 'user.presence') return;

          const data: {
            email: string;
            name?: string;
            profilePhoto?: string;
            pageName?: string;
            projectCode?: string;
            activeChannel?: string;
          } = typeof parsed.data === 'string' ? JSON.parse(parsed.data) : parsed.data;

          if (!data.email || data.email === myEmail) return;
          if (data.projectCode !== projectCode) return;

          // Cache profile info for future poll merges
          profileCacheRef.current.set(data.email, { name: data.name, profilePhoto: data.profilePhoto });

          setMembers(prev => {
            const others = prev.filter(m => m.email !== data.email);
            return [...others, {
              email: data.email,
              name: data.name,
              profilePhoto: data.profilePhoto,
              pageName: data.pageName,
            }];
          });
        } catch { /* ignore malformed events */ }
      };

      es.onerror = () => {
        if (!cancelled) {
          es.close();
          eventSourceRef.current = null;
          // Invalidate shared cache so next connect fetches a fresh token
          invalidateAblyToken(ablyChannel);
          tokenRef.current = null;
          retryTimeoutRef.current = setTimeout(connect, 3000);
        }
      };
    };

    // Initial publish + fetch, then connect SSE
    publishPresence();
    fetchAndSetPresence();
    connect();

    // Heartbeat every 120s to keep presence alive
    heartbeatRef.current = setInterval(() => { if (document.visibilityState === 'visible') publishPresence(); }, 300000);

    // Full state poll every 3 min as fallback (SSE handles real-time updates)
    pollRef.current = setInterval(() => { if (document.visibilityState === 'visible') fetchAndSetPresence(); }, 600000);

    return () => {
      cancelled = true;
      sseCleanup();
      if (heartbeatRef.current) { clearInterval(heartbeatRef.current); heartbeatRef.current = null; }
      if (pollRef.current)      { clearInterval(pollRef.current);      pollRef.current = null; }
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projectCode, pageName, enabled, myEmail, name, profilePhoto]);

  return { members, count: members.length };
}

import { useEffect, useRef, useCallback, useState } from 'react';
import { getAblyToken } from 'zite-endpoints-sdk';

type RealtimeMessage = {
  id: string;
  channel?: string;
  content?: string;
  senderName?: string;
  senderEmail?: string;
  sentAt?: string;
  parentMessageId?: string;
  reactions?: string;
  pinned?: boolean;
  attachments?: string;
};

type ReactionPayload = { messageId: string; channel: string; reactions: string };
type PinnedPayload   = { messageId: string; channel: string; pinned: boolean };
type PollPayload     = { messageId: string; channel: string; content: string };
export type TypingPayload = { channel: string; userEmail: string; userName: string; sentAt: string };

type UseRealtimeChannelOptions = {
  channel: string;
  onMessageCreated?: (msg: RealtimeMessage) => void;
  onReactionUpdated?: (payload: ReactionPayload) => void;
  onMessagePinned?:   (payload: PinnedPayload)   => void;
  onPollUpdated?:     (payload: PollPayload)      => void;
  onTyping?:          (payload: TypingPayload)    => void;
  enabled?: boolean;
};

export type RealtimeStatus = 'connecting' | 'connected' | 'error' | 'disabled';

export function useRealtimeChannel({
  channel,
  onMessageCreated,
  onReactionUpdated,
  onMessagePinned,
  onPollUpdated,
  onTyping,
  enabled = true,
}: UseRealtimeChannelOptions): { status: RealtimeStatus } {
  const callbackRef  = useRef(onMessageCreated);
  const reactionRef  = useRef(onReactionUpdated);
  const pinnedRef    = useRef(onMessagePinned);
  const pollRef      = useRef(onPollUpdated);
  const typingRef    = useRef(onTyping);

  callbackRef.current  = onMessageCreated;
  reactionRef.current  = onReactionUpdated;
  pinnedRef.current    = onMessagePinned;
  pollRef.current      = onPollUpdated;
  typingRef.current    = onTyping;

  const [status, setStatus] = useState<RealtimeStatus>('disabled');
  const eventSourceRef   = useRef<EventSource | null>(null);
  const tokenRef         = useRef<{ token: string; expires: number } | null>(null);
  const retryTimeoutRef  = useRef<ReturnType<typeof setTimeout> | null>(null);

  const cleanup = useCallback(() => {
    if (eventSourceRef.current) {
      eventSourceRef.current.close();
      eventSourceRef.current = null;
    }
    if (retryTimeoutRef.current) {
      clearTimeout(retryTimeoutRef.current);
      retryTimeoutRef.current = null;
    }
  }, []);

  useEffect(() => {
    if (!enabled || !channel) {
      cleanup();
      setStatus('disabled');
      return;
    }

    let cancelled = false;

    const connect = async () => {
      setStatus('connecting');
      console.log('[ably][sse connecting]', { channel, ablyChannel: `chat:${channel}` });

      // Get or refresh token
      const now = Math.floor(Date.now() / 1000);
      if (!tokenRef.current || tokenRef.current.expires - now < 300) {
        try {
          const ablyChannel = `chat:${channel}`;
          const res = await getAblyToken({ channels: [ablyChannel] });
          if (res.token && res.expires) {
            tokenRef.current = { token: res.token, expires: res.expires };
            console.log('[ably][token ok]', { channel, expiresIn: res.expires - now });
          } else {
            console.warn('[ably][token failed]', { channel, error: res.error ?? 'no token returned' });
            setStatus('error');
            if (!cancelled) {
              retryTimeoutRef.current = setTimeout(connect, 10000);
            }
            return;
          }
        } catch (err) {
          console.warn('[ably][token error]', { channel, error: (err as Error).message });
          setStatus('error');
          if (!cancelled) {
            retryTimeoutRef.current = setTimeout(connect, 10000);
          }
          return;
        }
      }

      if (cancelled) return;

      const ablyChannel = `chat:${channel}`;
      const sseUrl = `https://realtime.ably.io/sse?channels=${encodeURIComponent(ablyChannel)}&accessToken=${encodeURIComponent(tokenRef.current!.token)}&v=1.2`;

      const es = new EventSource(sseUrl);
      eventSourceRef.current = es;

      es.onopen = () => {
        if (!cancelled) {
          setStatus('connected');
          console.log('[ably][sse connected] ✓', { channel, ablyChannel });
        }
      };

      es.onmessage = (event) => {
        console.log('[ably][raw event]', { channel, data: event.data?.slice?.(0, 300) });
        try {
          const parsed = JSON.parse(event.data);

          if (parsed.name === 'message.created' && parsed.data) {
            const msg: RealtimeMessage = typeof parsed.data === 'string' ? JSON.parse(parsed.data) : parsed.data;
            console.log('[ably][event received]', { name: parsed.name, id: msg.id, channel: msg.channel });
            callbackRef.current?.(msg);
          }

          if (parsed.name === 'reaction.updated' && parsed.data) {
            const payload: ReactionPayload = typeof parsed.data === 'string' ? JSON.parse(parsed.data) : parsed.data;
            console.log('[ably][received reaction.updated]', payload);
            reactionRef.current?.(payload);
          }

          if (parsed.name === 'message.pinned' && parsed.data) {
            const payload: PinnedPayload = typeof parsed.data === 'string' ? JSON.parse(parsed.data) : parsed.data;
            console.log('[ably][received message.pinned]', payload);
            pinnedRef.current?.(payload);
          }

          if (parsed.name === 'poll.updated' && parsed.data) {
            const payload: PollPayload = typeof parsed.data === 'string' ? JSON.parse(parsed.data) : parsed.data;
            console.log('[ably][received poll.updated]', payload);
            pollRef.current?.(payload);
          }

          if (parsed.name === 'typing' && parsed.data) {
            const payload: TypingPayload = typeof parsed.data === 'string' ? JSON.parse(parsed.data) : parsed.data;
            typingRef.current?.(payload);
          }
        } catch {
          // Ignore malformed events
        }
      };

      es.onerror = () => {
        console.warn('[ably][sse error]', { channel, ablyChannel, readyState: es.readyState });
        if (!cancelled) {
          setStatus('error');
          es.close();
          eventSourceRef.current = null;
          tokenRef.current = null; // Force re-fetch
          retryTimeoutRef.current = setTimeout(connect, 3000);
        }
      };
    };

    connect();

    // Refresh token before expiry (every 50 minutes)
    const tokenRefreshInterval = setInterval(() => {
      if (!cancelled && tokenRef.current) {
        const now = Math.floor(Date.now() / 1000);
        if (tokenRef.current.expires - now < 600) {
          cleanup();
          tokenRef.current = null;
          connect();
        }
      }
    }, 50 * 60 * 1000);

    return () => {
      cancelled = true;
      clearInterval(tokenRefreshInterval);
      cleanup();
      setStatus('disabled');
      console.log('[ably][sse disconnected]', { channel });
    };
  }, [channel, enabled, cleanup]);

  return { status };
}

import { z } from 'zod';
import { createEndpoint, Deals } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Backfill exchange rates for USD deals missing exchangeRate',
  inputSchema: z.object({}),
  outputSchema: z.object({
    updated: z.number(),
    skipped: z.number(),
    rates: z.array(z.object({ date: z.string(), rate: z.number(), dealCount: z.number() })),
  }),
  execute: async () => {
    // Fetch all USD deals without exchangeRate
    const { records: allUsd } = await Deals.findAll({
      filters: { currency: { contains: 'USD' } },
      limit: 2000,
    });
    const missing = allUsd.filter(d => !d.exchangeRate);
    if (missing.length === 0) return { updated: 0, skipped: 0, rates: [] };

    // Group by date
    const byDate = new Map<string, typeof missing>();
    for (const deal of missing) {
      const date = deal.approvalDate || new Date().toISOString().slice(0, 10);
      const arr = byDate.get(date) || [];
      arr.push(deal);
      byDate.set(date, arr);
    }

    // Fetch rates per unique date
    const rateCache = new Map<string, number>();
    for (const date of byDate.keys()) {
      let rate: number | null = null;
      try {
        const res = await fetch(`https://cdn.jsdelivr.net/npm/@fawazahmed0/currency-api@${date}/v1/currencies/usd.json`);
        if (res.ok) {
          const json = await res.json() as { usd?: { mxn?: number } };
          if (json.usd?.mxn) rate = json.usd.mxn;
        }
      } catch {}
      if (!rate) {
        try {
          const res = await fetch('https://cdn.jsdelivr.net/npm/@fawazahmed0/currency-api@latest/v1/currencies/usd.json');
          if (res.ok) {
            const json = await res.json() as { usd?: { mxn?: number } };
            if (json.usd?.mxn) rate = json.usd.mxn;
          }
        } catch {}
      }
      if (rate) rateCache.set(date, rate);
    }

    let updated = 0;
    let skipped = 0;
    const ratesOut: { date: string; rate: number; dealCount: number }[] = [];

    for (const [date, deals] of byDate.entries()) {
      const rate = rateCache.get(date);
      if (!rate) { skipped += deals.length; continue; }
      ratesOut.push({ date, rate, dealCount: deals.length });
      for (const deal of deals) {
        await Deals.update({ id: deal.id, record: { exchangeRate: rate } });
        updated++;
      }
    }

    return { updated, skipped, rates: ratesOut };
  },
});

import { z } from 'zod';
import { createEndpoint, CellValues } from 'zite-integrations-backend-sdk';

const sleep = (ms: number) => new Promise(r => setTimeout(r, ms));

/**
 * Repairs CellValues whose boardId embeds an old project code.
 * Runs in pages of 200, up to maxPages iterations per prefix, so it won't timeout.
 * Call repeatedly until done = true.
 */
export default createEndpoint({
  authenticated: true,
  description: 'Repair orphaned CellValues boardIds for a given old→new project code mapping. Returns { done, fixedThisRun, totalFixed } — call repeatedly until done=true.',
  inputSchema: z.object({
    oldCode: z.string(),
    newCode: z.string(),
    maxPages: z.number().optional(), // pages of 200 per call, default 10
  }),
  outputSchema: z.object({
    done: z.boolean(),
    fixedThisRun: z.number(),
    remainingEstimate: z.number(),
  }),
  execute: async ({ input }) => {
    const { oldCode, newCode, maxPages = 10 } = input;
    const escaped = oldCode.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const prefixes = [`pm-${oldCode}-`, `cal-${oldCode}-`, `recruitment-${oldCode}-`];
    const pageSize = 200;
    let fixedThisRun = 0;
    let remainingEstimate = 0;
    let allDone = true;

    for (const prefix of prefixes) {
      let pages = 0;
      while (pages < maxPages) {
        const { records, hasMore } = await CellValues.findAll({
          filters: { boardId: { contains: prefix } } as any,
          limit: pageSize, offset: 0, // Always offset 0 — we update them so next call gets fresh ones
          fields: ['id', 'boardId'],
        });

        if (records.length === 0) break;

        // Update in chunks of 15
        for (let i = 0; i < records.length; i += 15) {
          const chunk = records.slice(i, i + 15);
          await Promise.all(chunk.map(r => {
            const newBoardId = (r.boardId ?? '').replace(
              new RegExp(`(pm|cal|recruitment)-${escaped}-`),
              `$1-${newCode}-`
            );
            return CellValues.update({ id: r.id, record: { boardId: newBoardId } } as any);
          }));
          await sleep(150);
        }

        fixedThisRun += records.length;
        pages++;

        if (!hasMore) break;

        // If still more after maxPages, mark as not done
        if (pages >= maxPages && hasMore) {
          allDone = false;
          remainingEstimate += 999; // estimate
        }

        await sleep(200);
      }
    }

    return { done: allDone, fixedThisRun, remainingEstimate };
  },
});

import { z } from 'zod';
import { createEndpoint, Suppliers } from 'zite-integrations-backend-sdk';

function randomAlphanumeric(length: number): string {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789';
  let result = '';
  for (let i = 0; i < length; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
}

function generateUUID(): string {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

export default createEndpoint({
  description: 'Generate or regenerate portal access token and password for a supplier',
  authenticated: true,
  inputSchema: z.object({ supplierId: z.string() }),
  outputSchema: z.object({
    token: z.string(),
    password: z.string(),
    portalUrl: z.string(),
  }),
  execute: async ({ input }) => {
    const token = generateUUID();
    const password = randomAlphanumeric(8);
    const appUrl = process.env.ZITE_APP_URL ?? '';

    await Suppliers.update({
      id: input.supplierId,
      record: { accessToken: token, portalPassword: password },
    });

    return {
      token,
      password,
      portalUrl: `${appUrl}/portal/${token}`,
    };
  },
});

import { z } from 'zod';
import { createEndpoint, RecruitmentRows } from 'zite-integrations-backend-sdk';

const participantSchema = z.object({
  id: z.string(),
  rowName: z.string().optional(),
  participantName: z.string().optional(),
  email: z.string().optional(),
  phone: z.string().optional(),
  status: z.string().optional(),
  cellData: z.string().optional(),
  rowOrder: z.number().optional(),
});

export default createEndpoint({
  authenticated: true,
  description: 'Get participants belonging to a specific recruitment group (groupColumnId) within a board',
  inputSchema: z.object({
    projectCode: z.string(),
    boardName: z.string(),
    groupColumnId: z.string(),
  }),
  outputSchema: z.object({
    participants: z.array(participantSchema),
  }),
  execute: async ({ input }) => {
    const { projectCode, boardName, groupColumnId } = input;

    const allRows: z.infer<typeof participantSchema>[] = [];
    let offset = 0;

    while (true) {
      const { records, hasMore } = await RecruitmentRows.findAll({
        filters: { projectCode, boardName, group: groupColumnId },
        limit: 500,
        offset,
      });

      const active = records.filter(r => !r.deletedAt);
      allRows.push(
        ...active.map(r => ({
          id: r.id,
          rowName: r.rowName,
          participantName: r.participantName,
          email: r.email,
          phone: r.phone,
          status: r.status,
          cellData: r.cellData,
          rowOrder: r.rowOrder,
        }))
      );

      if (!hasMore || records.length === 0) break;
      offset += records.length;
    }

    // Sort by rowOrder
    allRows.sort((a, b) => (a.rowOrder ?? 0) - (b.rowOrder ?? 0));

    return { participants: allRows };
  },
});

