                  {po.invoiceStatus && (
                    <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-semibold border ${INV_STATUS_STYLES[po.invoiceStatus] ?? 'bg-muted text-muted-foreground border-border'}`}>
