import React from 'react';
import { Users, Pencil, ChevronUp, ChevronDown } from 'lucide-react';

interface TeamUser {
  id: string;
  firstName?: string;
  lastName?: string;
  email?: string;
}

interface SavedTeam {
  lider: string[];
  analistas: string[];
  moderadores: string[];
  asistentes: string[];
}

interface TeamSectionProps {
  teamUsers: TeamUser[];
  savedTeam: SavedTeam;
  expanded: boolean;
  setExpanded: (v: boolean | ((prev: boolean) => boolean)) => void;
  onEditOpen: () => void;
}

function getUserName(users: TeamUser[], id: string): string {
  const u = users.find(x => x.id === id);
  if (!u) return id;
  return [u.firstName, u.lastName].filter(Boolean).join(' ') || u.email || id;
}

export function TeamSection({ teamUsers, savedTeam, expanded, setExpanded, onEditOpen }: TeamSectionProps) {
  const allIds = [...savedTeam.lider, ...savedTeam.analistas, ...savedTeam.moderadores, ...savedTeam.asistentes];
  const hasTeam = allIds.length > 0;

  const roles = [
    { label: 'Líder',       ids: savedTeam.lider,       color: 'bg-primary/10 text-primary' },
    { label: 'Analistas',   ids: savedTeam.analistas,   color: 'bg-chart-2/10 text-chart-2' },
    { label: 'Moderadores', ids: savedTeam.moderadores, color: 'bg-chart-3/10 text-chart-3' },
    { label: 'Asistentes',  ids: savedTeam.asistentes,  color: 'bg-muted text-muted-foreground' },
  ].filter(r => r.ids.length > 0);

  return (
    <>
      {/* Header buttons */}
      <div className="ml-auto flex items-center gap-1">
        <button
          onClick={() => setExpanded(v => !v)}
          className="flex items-center gap-1.5 text-xs text-muted-foreground hover:text-foreground px-2 py-1 rounded-md hover:bg-muted transition-colors"
        >
          <Users className="w-3.5 h-3.5" />
          {hasTeam ? (
            <span className="hidden sm:inline">{allIds.length} miembro{allIds.length !== 1 ? 's' : ''}</span>
          ) : (
            <span className="hidden sm:inline">Asignar equipo</span>
          )}
          {expanded ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
        </button>
        <button
          onClick={onEditOpen}
          className="p-1.5 rounded-md text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
          title="Editar equipo"
        >
          <Pencil className="w-3.5 h-3.5" />
        </button>
      </div>

      {/* Expandable strip */}
      {expanded && (
        <div className="px-4 py-2 border-b border-border/40 bg-muted/30 flex flex-wrap gap-4 flex-shrink-0">
          {roles.length === 0 ? (
            <p className="text-xs text-muted-foreground italic">Sin equipo asignado.</p>
          ) : roles.map(role => (
            <div key={role.label} className="flex items-center gap-2">
              <span className="text-[11px] font-semibold text-muted-foreground">{role.label}:</span>
              <div className="flex flex-wrap gap-1">
                {role.ids.map(id => (
                  <span key={id} className={`text-[11px] font-medium px-2 py-0.5 rounded-full ${role.color}`}>
                    {getUserName(teamUsers, id)}
                  </span>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </>
  );
}

import { useState, useRef, useCallback, useEffect } from 'react';
import { useAuth } from 'zite-auth-sdk';
import {
  migrateCellValuesToUUID, MigrateCellValuesToUUIDOutputType,
  getProjects, GetProjectsOutputType,
  saveMigrationLog, getMigrationLogs, GetMigrationLogsOutputType,
} from 'zite-endpoints-sdk';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { Badge } from '@/components/ui/badge';
import { Skeleton } from '@/components/ui/skeleton';
import { Play, Square, CheckCircle2, AlertTriangle, Loader2, History, RefreshCw } from 'lucide-react';

type LogEntry = {
  ts: string;
  boardId: string | null;
  migrated: number;
  failed: number;
  skipped: number;
  done: boolean;
  allDone: boolean;
  timedOut: boolean;
  elapsed: number;
  error?: string;
};

type HistoryLog = GetMigrationLogsOutputType['logs'][0];

// ── History Table ──────────────────────────────────────────────────────────────
function MigrationHistory({ projects }: { projects: GetProjectsOutputType['projects'] }) {
  const [logs, setLogs] = useState<HistoryLog[]>([]);
  const [loading, setLoading] = useState(true);
  const [filterProject, setFilterProject] = useState('');

  const load = useCallback((pc?: string) => {
    setLoading(true);
    getMigrationLogs({ projectCode: pc || undefined })
      .then(d => setLogs(d.logs))
      .catch(() => {})
      .finally(() => setLoading(false));
  }, []);

  useEffect(() => { load(); }, [load]);

  const handleFilterChange = (v: string) => {
    const val = v === '__all__' ? '' : v;
    setFilterProject(val);
    load(val);
  };

  const statusBadge = (status?: string) => {
    if (!status) return null;
    const s = status.toLowerCase();
    if (s === 'completed') return <Badge className="bg-primary/10 text-primary border-primary/20 text-[10px] px-1.5 py-0">Completed</Badge>;
    if (s === 'partial') return <Badge className="bg-accent/50 text-foreground border-border text-[10px] px-1.5 py-0">Partial</Badge>;
    return <Badge variant="destructive" className="text-[10px] px-1.5 py-0">Error</Badge>;
  };

  const fmtDate = (iso?: string) => {
    if (!iso) return '—';
    return new Date(iso).toLocaleString('es-MX', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' });
  };

  const fmtBoard = (bid?: string) => {
    if (!bid) return '—';
    const parts = bid.split('-');
    return parts[parts.length - 1]?.slice(0, 20) || bid.slice(0, 12);
  };

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <CardTitle className="text-lg flex items-center gap-2">
            <History className="h-4 w-4 text-primary" />
            Historial de migraciones
          </CardTitle>
          <div className="flex items-center gap-2">
            <Select value={filterProject || '__all__'} onValueChange={handleFilterChange}>
              <SelectTrigger className="h-8 w-48 text-xs">
                <SelectValue placeholder="Todos los proyectos" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="__all__">Todos los proyectos</SelectItem>
                {[...projects]
                  .filter(p => p.projectCode)
                  .sort((a, b) => (a.projectCode ?? '').localeCompare(b.projectCode ?? ''))
                  .map(p => (
                    <SelectItem key={p.id} value={p.projectCode!} className="text-xs">
                      {p.projectCode}
                    </SelectItem>
                  ))}
              </SelectContent>
            </Select>
            <Button size="icon" variant="ghost" className="h-8 w-8" onClick={() => load(filterProject)} disabled={loading}>
              <RefreshCw className={`h-3.5 w-3.5 ${loading ? 'animate-spin' : ''}`} />
            </Button>
          </div>
        </div>
      </CardHeader>
      <CardContent>
        {loading ? (
          <div className="space-y-2">
            {[1, 2, 3].map(i => <Skeleton key={i} className="h-8 w-full" />)}
          </div>
        ) : logs.length === 0 ? (
          <p className="text-sm text-muted-foreground text-center py-6">Sin registros de migración.</p>
        ) : (
          <div className="rounded-lg border border-border overflow-hidden">
            <table className="w-full text-xs">
              <thead className="bg-muted/50 border-b border-border">
                <tr>
                  <th className="text-left px-3 py-2 font-semibold text-muted-foreground">Fecha</th>
                  <th className="text-left px-3 py-2 font-semibold text-muted-foreground">Proyecto</th>
                  <th className="text-left px-3 py-2 font-semibold text-muted-foreground">Board</th>
                  <th className="text-right px-3 py-2 font-semibold text-muted-foreground">Migradas</th>
                  <th className="text-right px-3 py-2 font-semibold text-muted-foreground">Fallidas</th>
                  <th className="text-center px-3 py-2 font-semibold text-muted-foreground">Status</th>
                  <th className="text-right px-3 py-2 font-semibold text-muted-foreground">Duración</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border/50">
                {logs.map(log => (
                  <tr key={log.id} className="hover:bg-muted/20 transition-colors">
                    <td className="px-3 py-2 text-muted-foreground whitespace-nowrap">{fmtDate(log.createdAt)}</td>
                    <td className="px-3 py-2 font-medium text-foreground">{log.projectCode || '—'}</td>
                    <td className="px-3 py-2 text-muted-foreground font-mono truncate max-w-[120px]" title={log.boardId}>{fmtBoard(log.boardId)}</td>
                    <td className="px-3 py-2 text-right font-bold tabular-nums text-foreground">{(log.migrated ?? 0).toLocaleString()}</td>
                    <td className={`px-3 py-2 text-right font-bold tabular-nums ${(log.failed ?? 0) > 0 ? 'text-destructive' : 'text-muted-foreground'}`}>{log.failed ?? 0}</td>
                    <td className="px-3 py-2 text-center">{statusBadge(log.status)}</td>
                    <td className="px-3 py-2 text-right text-muted-foreground tabular-nums">{(log.durationSeconds ?? 0).toFixed(1)}s</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

// ── Main Page ──────────────────────────────────────────────────────────────────
export default function MigrationRunnerPage() {
  const { user, isLoading, loginWithRedirect } = useAuth();
  const [projectCode, setProjectCode] = useState('');
  const [projects, setProjects] = useState<GetProjectsOutputType['projects']>([]);
  const [loadingProjects, setLoadingProjects] = useState(true);
  const [dryRun, setDryRun] = useState(true);
  const [running, setRunning] = useState(false);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [totalMigrated, setTotalMigrated] = useState(0);
  const [totalFailed, setTotalFailed] = useState(0);
  const [totalSkipped, setTotalSkipped] = useState(0);
  const [currentBoard, setCurrentBoard] = useState<string | null>(null);
  const stopRef = useRef(false);
  const [delayMs, setDelayMs] = useState(5000);
  const [allDone, setAllDone] = useState(false);
  const historyKeyRef = useRef(0);

  useEffect(() => {
    getProjects({}).then(d => setProjects(d.projects)).catch(() => {}).finally(() => setLoadingProjects(false));
  }, []);

  const addLog = useCallback((entry: LogEntry) => {
    setLogs(prev => [entry, ...prev].slice(0, 200));
  }, []);

  const persistLog = useCallback(async (
    pc: string, boardId: string | null, migrated: number, failed: number, skipped: number,
    status: 'completed' | 'partial' | 'error', elapsed: number,
  ) => {
    try {
      await saveMigrationLog({ projectCode: pc, boardId: boardId ?? undefined, migrated, failed, skipped, status, durationSeconds: elapsed });
    } catch { /* non-critical */ }
  }, []);

  const runMigration = useCallback(async () => {
    setRunning(true);
    setAllDone(false);
    stopRef.current = false;

    let nextOffset: number | null = 0;
    let activeBoardId: string | undefined = undefined;

    while (!stopRef.current) {
      try {
        const result: MigrateCellValuesToUUIDOutputType = await migrateCellValuesToUUID({
          projectCode,
          dryRun,
          boardId: activeBoardId,
          offset: nextOffset ?? 0,
        });

        setTotalMigrated(prev => prev + result.migrated);
        setTotalFailed(prev => prev + result.failed);
        setTotalSkipped(prev => prev + result.skipped);
        setCurrentBoard(result.boardId);

        addLog({
          ts: new Date().toLocaleTimeString(),
          boardId: result.boardId,
          migrated: result.migrated,
          failed: result.failed,
          skipped: result.skipped,
          done: result.done,
          allDone: result.allDone,
          timedOut: result.timedOut,
          elapsed: result.elapsed,
        });

        // Persist log for non-dry-run chunks with actual work
        if (!dryRun && (result.migrated > 0 || result.failed > 0)) {
          const chunkStatus = result.failed > 0 ? 'error' : result.allDone ? 'completed' : result.done ? 'completed' : 'partial';
          persistLog(projectCode, result.boardId, result.migrated, result.failed, result.skipped, chunkStatus, result.elapsed);
        }

        if (result.allDone) {
          addLog({
            ts: new Date().toLocaleTimeString(),
            boardId: null, migrated: 0, failed: 0, skipped: 0,
            done: true, allDone: true, timedOut: false, elapsed: 0,
          });
          // Persist final "completed" entry
          if (!dryRun) {
            persistLog(projectCode, null, 0, 0, 0, 'completed', 0);
          }
          setAllDone(true);
          historyKeyRef.current++;
          break;
        }

        if (result.done) {
          activeBoardId = undefined;
          nextOffset = 0;
        } else {
          activeBoardId = result.boardId ?? undefined;
          nextOffset = result.nextOffset;
        }

        const waitMs = (result.failed > 0 || result.timedOut) ? delayMs * 2 : delayMs;
        await new Promise(r => setTimeout(r, waitMs));
      } catch (err: any) {
        addLog({
          ts: new Date().toLocaleTimeString(),
          boardId: activeBoardId ?? null,
          migrated: 0, failed: 0, skipped: 0,
          done: false, allDone: false, timedOut: false, elapsed: 0,
          error: err?.message || 'Unknown error',
        });
        if (!dryRun) {
          persistLog(projectCode, activeBoardId ?? null, 0, 0, 0, 'error', 0);
        }
        await new Promise(r => setTimeout(r, 15000));
      }
    }

    setRunning(false);
  }, [projectCode, dryRun, delayMs, addLog, persistLog]);

  const stopMigration = useCallback(() => {
    stopRef.current = true;
  }, []);

  if (isLoading) return null;
  if (!user) {
    loginWithRedirect();
    return null;
  }

  return (
    <div className="min-h-screen bg-background p-6">
      <div className="max-w-3xl mx-auto space-y-6">
        <h1 className="text-2xl font-bold text-foreground">UUID Migration Runner</h1>
        <p className="text-sm text-muted-foreground">
          Migra CellValues de legacy boardId a UUID, de forma automática y resumable.
        </p>

        <Card>
          <CardHeader>
            <CardTitle className="text-lg">Configuración</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Project Code</Label>
                <Select value={projectCode} onValueChange={setProjectCode} disabled={running}>
                  <SelectTrigger>
                    <SelectValue placeholder="Seleccionar proyecto..." />
                  </SelectTrigger>
                  <SelectContent>
                    {loadingProjects ? (
                      <SelectItem value="__loading__" disabled>Cargando proyectos...</SelectItem>
                    ) : (
                      [...projects]
                        .filter(p => p.projectCode)
                        .sort((a, b) => (a.projectCode ?? '').localeCompare(b.projectCode ?? ''))
                        .map(p => (
                          <SelectItem key={p.id} value={p.projectCode!}>
                            {p.projectCode} — {p.fullName || 'Sin nombre'}
                          </SelectItem>
                        ))
                    )}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label>Delay entre llamadas (ms)</Label>
                <Input
                  type="number"
                  value={delayMs}
                  onChange={e => setDelayMs(Number(e.target.value))}
                  disabled={running}
                />
              </div>
            </div>
            <div className="flex items-center gap-3">
              <Switch
                checked={dryRun}
                onCheckedChange={setDryRun}
                disabled={running}
              />
              <Label>Dry Run (solo reportar, no modificar)</Label>
              {dryRun && <Badge variant="secondary">Modo seguro</Badge>}
              {!dryRun && <Badge variant="destructive">Escritura real</Badge>}
            </div>

            <div className="flex gap-3 items-center">
              {!running ? (
                <Button disabled={!projectCode} onClick={() => { setAllDone(false); setTotalMigrated(0); setTotalFailed(0); setTotalSkipped(0); setLogs([]); runMigration(); }} className="gap-2">
                  <Play className="h-4 w-4" />
                  {dryRun ? 'Iniciar Dry Run' : 'Iniciar Migración'}
                </Button>
              ) : (
                <Button onClick={stopMigration} variant="destructive" className="gap-2">
                  <Square className="h-4 w-4" />
                  Detener
                </Button>
              )}
              {allDone && !running && (
                <Badge className="bg-green-600 text-white gap-1 py-1 px-3">
                  <CheckCircle2 className="h-3.5 w-3.5" />
                  Migración completada
                </Badge>
              )}
            </div>
          </CardContent>
        </Card>

        {/* Status */}
        <Card>
          <CardHeader>
            <CardTitle className="text-lg flex items-center gap-2">
              Estado
              {running && <Loader2 className="h-4 w-4 animate-spin text-primary" />}
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-5 gap-4 text-center">
              <div>
                <p className="text-2xl font-bold text-foreground">{totalMigrated}</p>
                <p className="text-xs text-muted-foreground">Migradas</p>
              </div>
              <div>
                <p className={`text-2xl font-bold ${totalFailed > 0 ? 'text-destructive' : 'text-foreground'}`}>{totalFailed}</p>
                <p className="text-xs text-muted-foreground">Failed</p>
              </div>
              <div>
                <p className="text-2xl font-bold text-foreground">{totalSkipped}</p>
                <p className="text-xs text-muted-foreground">Skipped</p>
              </div>
              <div>
                <p className="text-2xl font-bold text-foreground">{logs.length}</p>
                <p className="text-xs text-muted-foreground">Chunks</p>
              </div>
              <div>
                <p className="text-sm font-mono text-foreground truncate">
                  {currentBoard?.split('-').slice(-1)[0] || '—'}
                </p>
                <p className="text-xs text-muted-foreground">Board</p>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Completion Banner */}
        {allDone && !running && (
          <Card className="border-green-500/50 bg-green-500/5">
            <CardContent className="pt-6">
              <div className="flex items-center gap-3 mb-3">
                <CheckCircle2 className="h-6 w-6 text-green-600" />
                <h3 className="text-lg font-semibold text-foreground">
                  ¡Migración completada exitosamente!
                </h3>
              </div>
              <p className="text-sm text-muted-foreground mb-4">
                Todos los CellValues del proyecto <strong>{projectCode}</strong> fueron procesados.
              </p>
              <div className="grid grid-cols-3 gap-4 text-center">
                <div className="bg-background rounded-lg p-3 border">
                  <p className="text-xl font-bold text-foreground">{totalMigrated}</p>
                  <p className="text-xs text-muted-foreground">Migradas</p>
                </div>
                <div className="bg-background rounded-lg p-3 border">
                  <p className="text-xl font-bold text-foreground">{totalSkipped}</p>
                  <p className="text-xs text-muted-foreground">Ya estaban en UUID</p>
                </div>
                <div className="bg-background rounded-lg p-3 border">
                  <p className={`text-xl font-bold ${totalFailed > 0 ? 'text-destructive' : 'text-foreground'}`}>{totalFailed}</p>
                  <p className="text-xs text-muted-foreground">Fallidas</p>
                </div>
              </div>
            </CardContent>
          </Card>
        )}

        {/* Log */}
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">Log</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="max-h-96 overflow-y-auto space-y-1 font-mono text-xs">
              {logs.length === 0 && (
                <p className="text-muted-foreground">Sin actividad aún.</p>
              )}
              {logs.map((log, i) => (
                <div
                  key={i}
                  className={`flex items-start gap-2 py-1 px-2 rounded ${
                    log.error || log.failed > 0
                      ? 'bg-destructive/10 text-destructive'
                      : log.allDone
                        ? 'bg-green-500/10 text-green-700'
                        : 'bg-muted/50 text-foreground'
                  }`}
                >
                  {log.error || log.failed > 0 ? (
                    <AlertTriangle className="h-3 w-3 mt-0.5 shrink-0" />
                  ) : log.allDone ? (
                    <CheckCircle2 className="h-3 w-3 mt-0.5 shrink-0" />
                  ) : null}
                  <span className="text-muted-foreground">{log.ts}</span>
                  {log.error ? (
                    <span>Error: {log.error}</span>
                  ) : log.allDone && log.migrated === 0 ? (
                    <span className="font-bold">✅ ALL DONE — migración completa</span>
                  ) : (
                    <span>
                      {log.boardId?.split('-').slice(-1)[0] || '?'}: +{log.migrated}
                      {log.failed > 0 ? ` ❌${log.failed}failed` : ''}
                      {log.skipped > 0 ? ` ⏭${log.skipped}skip` : ''}
                      {' '}{log.timedOut ? '⏱️timeout' : log.done ? '✅done' : ''}
                      {' '}({log.elapsed.toFixed(1)}s)
                    </span>
                  )}
                </div>
              ))}
            </div>
          </CardContent>
        </Card>

        {/* Migration History */}
        <MigrationHistory key={historyKeyRef.current} projects={projects} />
      </div>
    </div>
  );
}

import { Boards, type BoardsRecordType } from 'zite-integrations-backend-sdk';

// ── Types ────────────────────────────────────────────────────────────────────

type BoardSuffix = '::groups' | '::children' | '';

export type ResolvedBoard = {
  /** UUID real (o legacy si no se pudo resolver) + suffix si aplica */
  boardId: string;
  /** UUID real (o legacy) sin suffix */
  baseBoardId: string;
  /** Compuesto legacy con suffix (ej: pm-PJT-001-Timeline::groups) */
  legacyCompositeId: string;
  /** Compuesto legacy sin suffix */
  legacyBaseId: string;
  /** Nombre del board */
  boardName: string;
  /** Código del proyecto */
  projectCode: string;
  /** Tipo del board: pm, calendar, recruitment, etc. */
  boardType: string;
  /** Sufijo extraído: ::groups, ::children, o vacío */
  suffix: BoardSuffix;
  /** true si el input era un compuesto legacy (no UUID) */
  isLegacy: boolean;
  /** true si fallbackToLegacy se usó y no se encontró Board activo */
  unresolvedLegacy?: boolean;
  /**
   * true si es un board virtual events-.
   * events- NO existe en la tabla Boards, no se migra a UUID,
   * y se conserva como legacy permanentemente.
   */
  isVirtualEventsBoard?: boolean;
  /** El registro Board real. null para events- virtuales o legacy sin resolver */
  board: BoardsRecordType | null;
};

export type ResolveBoardIdOptions = {
  /** El boardId o key compuesto a resolver */
  boardIdOrKey: string;
  /** ProjectCode — ayuda a parsear compuestos sin ambigüedad */
  projectCode?: string;
  /** BoardName — para búsqueda directa si ya se conoce */
  boardName?: string;
  /**
   * Si true, cuando no encuentre un Board activo retorna el legacy id
   * en vez de lanzar error. Útil para endpoints de lectura durante la transición.
   * Default: false (estricto).
   */
  fallbackToLegacy?: boolean;
};

// ── Constants ────────────────────────────────────────────────────────────────

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/** Ordered longest-prefix-first so recruitment- is tested before a hypothetical "re-" prefix */
const KNOWN_PREFIXES = [
  { prefix: 'recruitment-', boardType: 'recruitment' },
  { prefix: 'cal-',         boardType: 'calendar' },
  { prefix: 'events-',      boardType: 'events' },
  { prefix: 'pm-',          boardType: 'pm' },
] as const;

const SUFFIXES: BoardSuffix[] = ['::groups', '::children'];

const DEBUG = typeof process !== 'undefined'
  && process.env?.DEBUG_BOARD_RESOLUTION === 'true';

// ── Internal helpers ─────────────────────────────────────────────────────────

function extractSuffix(input: string): { base: string; suffix: BoardSuffix } {
  for (const s of SUFFIXES) {
    if (input.endsWith(s)) {
      return { base: input.slice(0, -s.length), suffix: s };
    }
  }
  return { base: input, suffix: '' };
}

function detectPrefix(base: string): { prefix: string; boardType: string; rest: string } | null {
  for (const p of KNOWN_PREFIXES) {
    if (base.startsWith(p.prefix)) {
      return { prefix: p.prefix, boardType: p.boardType, rest: base.slice(p.prefix.length) };
    }
  }
  return null;
}

/**
 * Extrae boardName del "rest" (lo que queda después del prefix) cuando
 * se conoce el projectCode. No usa split por guiones — quita el projectCode
 * del inicio y lo que sobra es el boardName.
 *
 * Ej: rest = "PJT-001-Timeline CDMX - Ola 1", projectCode = "PJT-001"
 *   → boardName = "Timeline CDMX - Ola 1"
 *
 * Ej: rest = "PJT-001" (sin boardName), projectCode = "PJT-001"
 *   → boardName = ""
 */
function extractBoardName(rest: string, projectCode: string): string {
  if (rest === projectCode) return '';
  const expectedPrefix = `${projectCode}-`;
  if (rest.startsWith(expectedPrefix)) {
    return rest.slice(expectedPrefix.length);
  }
  return rest;
}

/**
 * Construye el legacy composite boardId.
 * `prefixType` es el tipo lógico derivado del PREFIJO del input (pm, calendar,
 * recruitment), NO del boardType almacenado en el registro Board (que puede
 * estar vacío en boards legacy).
 */
function buildLegacyComposite(prefixType: string, projectCode: string, boardName: string): string {
  const prefix = prefixType === 'calendar' ? 'cal-'
    : prefixType === 'recruitment' ? 'recruitment-'
    : prefixType === 'events' ? 'events-'
    : 'pm-';
  return boardName ? `${prefix}${projectCode}-${boardName}` : `${prefix}${projectCode}`;
}

/**
 * Dado un array de Boards activos, elige el mejor match según boardType.
 * Prioridad:
 *   1. boardType coincide exactamente con el prefixType detectado
 *   2. boardType está vacío (legacy — acepta cualquier prefijo)
 *   3. primer registro activo disponible (último fallback)
 */
function pickBestBoard(
  activeRecords: BoardsRecordType[],
  prefixType: string,
): BoardsRecordType | undefined {
  if (activeRecords.length === 0) return undefined;
  if (activeRecords.length === 1) return activeRecords[0];

  // Map prefix type to the DB boardType value used for exact match
  const dbTypeForPrefix: Record<string, string> = {
    pm: 'pm',
    calendar: 'calendar',
    recruitment: 'recruitment',
  };
  const exactType = dbTypeForPrefix[prefixType];

  // 1. Exact boardType match
  if (exactType) {
    const exact = activeRecords.find(b => b.boardType === exactType);
    if (exact) return exact;
  }

  // 2. Empty boardType fallback (legacy boards)
  const emptyType = activeRecords.find(b => !b.boardType || b.boardType === '');
  if (emptyType) return emptyType;

  // 3. Last resort
  return activeRecords[0];
}

function makeUnresolvedResult(
  boardIdOrKey: string, base: string, suffix: BoardSuffix,
  boardName: string, projectCode: string, boardType: string,
): ResolvedBoard {
  return {
    boardId: boardIdOrKey,
    baseBoardId: base,
    legacyCompositeId: boardIdOrKey,
    legacyBaseId: base,
    boardName,
    projectCode,
    boardType,
    suffix,
    isLegacy: true,
    unresolvedLegacy: true,
    board: null,
  };
}

// ── LookupBoardUUID ──────────────────────────────────────────────────────────
//
// Use when the endpoint already knows projectCode + boardName + boardType.
// Never throws — returns { found: false, reason } when no active board matches.

export type LookupResult = {
  /** UUID del board activo, presente solo si found === true */
  uuid?: string;
  /** Legacy composite ID (ej: recruitment-PJT-001-Filtro) */
  legacyId: string;
  /** true si se encontró un Board activo que matchea */
  found: boolean;
  /** El registro Board completo, presente solo si found === true */
  board?: BoardsRecordType;
  /** Razón legible cuando found === false */
  reason?: string;
};

export async function lookupBoardUUID(
  projectCode: string,
  boardName: string,
  boardType: string,
): Promise<LookupResult> {
  const legacyId = buildLegacyComposite(boardType, projectCode, boardName);

  try {
    const filters: Record<string, string> = { projectCode };
    if (boardName) filters.boardName = boardName;

    const { records } = await Boards.findAll({ filters: filters as any, limit: 10 });
    const activeRecords = records.filter(b => !b.deletedAt);

    if (activeRecords.length === 0) {
      if (DEBUG) console.log('[lookupBoardUUID] No active board found', { projectCode, boardName, boardType });
      return { legacyId, found: false, reason: `No active board for projectCode="${projectCode}", boardName="${boardName}", boardType="${boardType}"` };
    }

    const best = pickBestBoard(activeRecords, boardType);
    if (!best) {
      return { legacyId, found: false, reason: `pickBestBoard returned undefined for ${activeRecords.length} candidates` };
    }

    if (DEBUG) console.log('[lookupBoardUUID] resolved', { projectCode, boardName, boardType, uuid: best.id });

    return { uuid: best.id, legacyId, found: true, board: best };
  } catch (err) {
    // Never throw — surface the error as a reason
    if (DEBUG) console.log('[lookupBoardUUID] error (returning found:false)', String(err));
    return { legacyId, found: false, reason: `Lookup error: ${String(err)}` };
  }
}

// ── Main function ────────────────────────────────────────────────────────────

export async function resolveBoardId(opts: ResolveBoardIdOptions): Promise<ResolvedBoard> {
  const { boardIdOrKey, projectCode, boardName: explicitBoardName, fallbackToLegacy = false } = opts;

  // 1. Extract suffix (::groups, ::children)
  const { base, suffix } = extractSuffix(boardIdOrKey);

  // 2. Is it a UUID?
  const isUuid = UUID_RE.test(base);

  // ── UUID path ──────────────────────────────────────────────────────────────
  if (isUuid) {
    const board = await Boards.findOne({ id: base });

    if (!board || board.deletedAt) {
      if (fallbackToLegacy) {
        if (DEBUG) console.log('[resolveBoardId] UUID not found, fallback', { base, suffix });
        return makeUnresolvedResult(boardIdOrKey, base, suffix, explicitBoardName ?? '', projectCode ?? '', '');
      }
      throw new Error(`Board not found or deleted: ${base}`);
    }

    const bName = board.boardName ?? '';
    const pCode = board.projectCode ?? '';
    const bType = board.boardType ?? 'pm';
    const legacyBase = buildLegacyComposite(bType, pCode, bName);

    if (DEBUG) console.log('[resolveBoardId] resolved UUID', { base, bName, pCode, bType, suffix });

    return {
      boardId: suffix ? `${board.id}${suffix}` : board.id,
      baseBoardId: board.id,
      legacyCompositeId: suffix ? `${legacyBase}${suffix}` : legacyBase,
      legacyBaseId: legacyBase,
      boardName: bName,
      projectCode: pCode,
      boardType: bType,
      suffix,
      isLegacy: false,
      board,
    };
  }

  // ── Legacy composite path ──────────────────────────────────────────────────

  const detected = detectPrefix(base);

  // 3. Handle events- virtual boards.
  //    ┌─────────────────────────────────────────────────────────────────────┐
  //    │ events- is a VIRTUAL prefix. There is NO record in the Boards      │
  //    │ table for events boards. This prefix is NOT migrated to UUID and   │
  //    │ is kept as legacy permanently. The boardId for events is always    │
  //    │ `events-{projectCode}` (no boardName segment).                    │
  //    └─────────────────────────────────────────────────────────────────────┘
  if (detected?.boardType === 'events') {
    const pCode = projectCode ?? detected.rest;
    const legacyBase = `events-${pCode}`;

    if (DEBUG) console.log('[resolveBoardId] virtual events board (permanent legacy)', { pCode, suffix });

    return {
      boardId: suffix ? `${legacyBase}${suffix}` : legacyBase,
      baseBoardId: legacyBase,
      legacyCompositeId: suffix ? `${legacyBase}${suffix}` : legacyBase,
      legacyBaseId: legacyBase,
      boardName: '',
      projectCode: pCode,
      boardType: 'events',
      suffix,
      isLegacy: true,
      isVirtualEventsBoard: true,
      board: null,
    };
  }

  // 4. Parse composite — extract boardName and projectCode
  let resolvedBoardName = explicitBoardName ?? '';
  let resolvedProjectCode = projectCode ?? '';
  const resolvedPrefixType = detected?.boardType ?? 'pm';

  if (detected && projectCode) {
    // We have the prefix and the projectCode — safe extraction
    resolvedBoardName = explicitBoardName ?? extractBoardName(detected.rest, projectCode);
    resolvedProjectCode = projectCode;
  } else if (detected && !projectCode) {
    // No projectCode provided — must search Boards table to disambiguate.
    //
    // IMPORTANT: Use `resolvedPrefixType` (derived from the INPUT string's prefix)
    // to build the comparison composite, NOT `b.boardType` from the DB record.
    // Reason: ~27% of boards have empty boardType. If the input is
    // `cal-PJT-001-Timeline` and the Board has boardType='', using b.boardType
    // would generate `pm-PJT-001-Timeline` which would never match the input.
    const { records } = await Boards.findAll({ limit: 500 });
    const activeBoards = records.filter(b => !b.deletedAt);

    const match = activeBoards.find(b => {
      const composite = buildLegacyComposite(
        resolvedPrefixType, // ← always use the prefix from the input, not b.boardType
        b.projectCode ?? '',
        b.boardName ?? '',
      );
      return composite === base;
    });

    if (match) {
      resolvedBoardName = match.boardName ?? '';
      resolvedProjectCode = match.projectCode ?? '';
    } else if (!fallbackToLegacy) {
      throw new Error(`Board not found for legacy composite: ${base}`);
    } else {
      if (DEBUG) console.log('[resolveBoardId] unresolved legacy (no projectCode)', { base, suffix });
      return makeUnresolvedResult(boardIdOrKey, base, suffix, '', '', resolvedPrefixType);
    }
  }

  // 5. Look up the active Board by boardName + projectCode.
  //    When multiple active Boards match (same name, same project), use
  //    pickBestBoard to prefer the one whose boardType matches the detected prefix.
  if (resolvedBoardName || resolvedProjectCode) {
    const filters: Record<string, string> = {};
    if (resolvedBoardName) filters.boardName = resolvedBoardName;
    if (resolvedProjectCode) filters.projectCode = resolvedProjectCode;

    const { records } = await Boards.findAll({ filters: filters as any, limit: 10 });
    const activeRecords = records.filter(b => !b.deletedAt);

    const activeBoard = pickBestBoard(activeRecords, resolvedPrefixType);

    if (activeBoard) {
      // Use the prefix type for legacy composite (not the possibly-empty db boardType)
      const legacyBase = buildLegacyComposite(
        resolvedPrefixType,
        activeBoard.projectCode ?? '',
        activeBoard.boardName ?? '',
      );

      if (DEBUG) console.log('[resolveBoardId] resolved legacy → UUID', {
        legacy: base, uuid: activeBoard.id, suffix,
        dbBoardType: activeBoard.boardType, prefixType: resolvedPrefixType,
      });

      return {
        boardId: suffix ? `${activeBoard.id}${suffix}` : activeBoard.id,
        baseBoardId: activeBoard.id,
        legacyCompositeId: suffix ? `${legacyBase}${suffix}` : legacyBase,
        legacyBaseId: legacyBase,
        boardName: activeBoard.boardName ?? '',
        projectCode: activeBoard.projectCode ?? '',
        boardType: activeBoard.boardType || resolvedPrefixType,
        suffix,
        isLegacy: true,
        board: activeBoard,
      };
    }
  }

  // 6. No active Board found
  if (fallbackToLegacy) {
    if (DEBUG) console.log('[resolveBoardId] unresolved legacy fallback', { base, suffix });
    return makeUnresolvedResult(boardIdOrKey, base, suffix, resolvedBoardName, resolvedProjectCode, resolvedPrefixType);
  }

  throw new Error(`Board not found: ${base} (boardName=${resolvedBoardName}, projectCode=${resolvedProjectCode})`);
}

import { z } from 'zod';
import { createEndpoint, BoardColumns, RecruitmentRows } from 'zite-integrations-backend-sdk';

const normalize = (str: string) =>
  str.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();

export default createEndpoint({
  authenticated: true,
  description: 'Counts how many new Fillout submissions are available for a board without importing anything.',
  inputSchema: z.object({ boardId: z.string() }),
  outputSchema: z.object({ total: z.number(), newCount: z.number() }),
  execute: async ({ input }) => {
    const apiKey = process.env.ZITE_FILLOUT_API_KEY ?? '';
    if (!apiKey) throw new Error('Fillout API key not configured');

    const { records: cols } = await BoardColumns.findAll({
      filters: { boardId: input.boardId, columnType: '__fillout_link__' },
      limit: 5,
    });
    const linkCol = cols[0];
    if (!linkCol?.optionsJson) return { total: 0, newCount: 0 };

    const meta = JSON.parse(linkCol.optionsJson) as {
      formId: string;
      projectCode: string;
      boardName: string;
      lastSyncedAt?: string;
    };
    const { formId, projectCode, boardName } = meta;

    // Compute afterDate with 5-min overlap window
    let afterDate: string | undefined;
    if (meta.lastSyncedAt) {
      const cursor = new Date(meta.lastSyncedAt);
      cursor.setMinutes(cursor.getMinutes() - 5);
      afterDate = cursor.toISOString();
    }

    // Fetch submissions from Fillout (paginated)
    const PAGE_SIZE = 50;
    const submissions: any[] = [];
    let offset = 0;
    while (true) {
      const params = new URLSearchParams({
        limit: String(PAGE_SIZE),
        offset: String(offset),
        sort: 'asc',
        status: 'finished',
      });
      if (afterDate) params.set('afterDate', afterDate);

      const res = await fetch(`https://api.fillout.com/v1/api/forms/${formId}/submissions?${params}`, {
        headers: { Authorization: `Bearer ${apiKey}` },
      });
      if (res.status === 429 || !res.ok) break;

      const data = await res.json();
      const page: any[] = data.responses ?? data.submissions ?? (Array.isArray(data) ? data : []);
      if (page.length === 0) break;
      submissions.push(...page);
      if (page.length < PAGE_SIZE) break;
      offset += PAGE_SIZE;
    }

    if (submissions.length === 0) return { total: 0, newCount: 0 };

    // Build set of already-imported submissionIds (same dedup logic as checkNewSubmissions)
    const { records: existingRows } = await RecruitmentRows.findAll({
      filters: { boardName, projectCode },
      limit: 2000,
      fields: ['email', 'participantName', 'sourceForm'],
    });

    const importedSubmissionIds = new Set<string>();

    for (const r of existingRows) {
      if (r.sourceForm && r.sourceForm.includes('|')) {
        const parts = r.sourceForm.split('|');
        if (parts.length >= 2) importedSubmissionIds.add(parts[parts.length - 1]);
      }
    }

    // Count truly new submissions
    const newSubmissions = submissions.filter(s => {
      const sid = s.submissionId ?? s.id;
      return sid ? !importedSubmissionIds.has(String(sid)) : true;
    });

    return { total: submissions.length, newCount: newSubmissions.length };
  },
});

import { z } from 'zod';
import { createEndpoint, Boards, BoardColumns, Tasks, CellValues } from 'zite-integrations-backend-sdk';

/**
 * Standard PM timeline tasks with assigned colors from GROUP_COLORS palette.
 * Colors chosen to best match the target palette:
 *   #00B32D (verde)  → green-3
 *   #9E9E9E (gris)   → orange-1 (no gray exists; neutral warm tone)
 *   #FFBB00 (amarillo) → yellow-3
 *   #3D74BD (azul)   → blue-3
 *   #DB0000 (rojo)   → red-3
 */
const TEMPLATE_TASKS = [
  { name: 'Go Ahead',                      order: 0, color: 'green-3'  },
  { name: 'Reclutamiento',                 order: 1, color: 'orange-1' },
  { name: 'Envío de guía de tópicos',      order: 2, color: 'yellow-3' },
  { name: 'Aprobación de guía de tópicos', order: 3, color: 'yellow-3' },
  { name: 'Fieldwork',                     order: 4, color: 'blue-3'   },
  { name: 'Análisis',                      order: 5, color: 'orange-1' },
  { name: 'Reporte',                       order: 6, color: 'red-3'    },
];

const columnSchema = z.object({
  id: z.string(),
  boardId: z.string().optional().nullable(),
  columnName: z.string().optional().nullable(),
  columnType: z.string().optional().nullable(),
  optionsJson: z.string().optional().nullable(),
  columnOrder: z.number().optional().nullable(),
});

const cellValueSchema = z.object({
  id: z.string(),
  boardId: z.string().optional().nullable(),
  rowId: z.string().optional().nullable(),
  columnId: z.string().optional().nullable(),
  textValue: z.string().optional().nullable(),
  numberValue: z.number().optional().nullable(),
  dateValue: z.string().optional().nullable(),
  booleanValue: z.boolean().optional().nullable(),
  fileUrl: z.string().optional().nullable(),
});

export default createEndpoint({
  description: 'Creates a new PM timeline board with default columns and 7 standard tasks with colors, all in a single call',
  inputSchema: z.object({
    projectCode: z.string(),
    boardName: z.string(),
    boardOrder: z.number(),
    boardType: z.string(),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    /** Legacy composite ID — used by the frontend for cache keys and display */
    boardId: z.string(),
    /** Same as boardId — the legacy composite (pm-{projectCode}-{boardName}) */
    legacyBoardId: z.string(),
    /** The real UUID of the Boards record — used for DB writes going forward */
    uuidBoardId: z.string(),
    /** Alias for uuidBoardId — canonical ID to use in future migrations */
    canonicalBoardId: z.string(),
    tasks: z.array(z.object({ id: z.string(), name: z.string(), order: z.number() })),
    columns: z.array(columnSchema),
    cellValues: z.array(cellValueSchema),
  }),
  execute: async ({ input }) => {
    // ── 1. Derive both IDs up front ──────────────────────────────────────────
    const legacyBoardId = `pm-${input.projectCode}-${input.boardName}`;

    // ── 2. Create the Board record and capture the real UUID ─────────────────
    const createdBoard = await Boards.create({
      record: {
        boardName: input.boardName,
        projectCode: input.projectCode,
        boardOrder: input.boardOrder,
        boardType: input.boardType,
      },
    });

    const uuidBoardId = createdBoard.id;

    // ── 3. Create the 3 default columns — written under the UUID ─────────────
    const statusOptions = JSON.stringify([
      { label: 'Pendiente',   color: 'gray'  },
      { label: 'En progreso', color: 'blue'  },
      { label: 'Completada',  color: 'green' },
      { label: 'Bloqueada',   color: 'red'   },
    ]);

    const columnsResult = await BoardColumns.bulkCreate({
      records: [
        { boardId: uuidBoardId, columnName: 'Estado',      columnType: 'Status', columnOrder: 500,  optionsJson: statusOptions },
        { boardId: uuidBoardId, columnName: 'Responsable', columnType: 'Persona', columnOrder: 1000 },
        { boardId: uuidBoardId, columnName: 'Color',       columnType: 'Color',   columnOrder: 1500 },
      ],
    });

    // Return columns with boardId = legacyBoardId so preSeedBoardCache receives
    // data consistent with the legacy cache key used by the frontend.
    const columns = columnsResult.records.map(r => ({
      id: r.id,
      boardId: legacyBoardId,           // ← defensive: always legacy in response
      columnName: r.fields.columnName ?? null,
      columnType: r.fields.columnType ?? null,
      optionsJson: r.fields.optionsJson ?? null,
      columnOrder: r.fields.columnOrder ?? null,
    }));

    const colorColumn = columns.find(c => c.columnType === 'Color');

    // ── 4. Create the 7 standard tasks ───────────────────────────────────────
    const tasksResult = await Tasks.bulkCreate({
      records: TEMPLATE_TASKS.map(t => ({
        taskName: t.name,
        projectCode: input.projectCode,
        boardName: input.boardName,
        boardId: uuidBoardId,
        order: t.order,
        status: 'Pendiente',
        parentTaskId: '',
      })),
    });

    const tasks = tasksResult.records.map((r, i) => ({
      id: r.id,
      name: TEMPLATE_TASKS[i].name,
      order: TEMPLATE_TASKS[i].order,
    }));

    // ── 5. Create color CellValues — written under the UUID ──────────────────
    type CellValueItem = {
      id: string;
      boardId?: string | null;
      rowId?: string | null;
      columnId?: string | null;
      textValue?: string | null;
      numberValue?: number | null;
      dateValue?: string | null;
      booleanValue?: boolean | null;
      fileUrl?: string | null;
    };

    let cellValues: CellValueItem[] = [];
    if (colorColumn) {
      const cellValuesResult = await CellValues.bulkCreate({
        records: tasks.map((task, i) => ({
          boardId: uuidBoardId,          // ← written to DB under UUID
          rowId: task.id,
          columnId: colorColumn.id,
          textValue: TEMPLATE_TASKS[i].color,
        })),
      });

      // Return cellValues with boardId = legacyBoardId for the same reason as
      // columns above — consistency with the legacy cache key in preSeedBoardCache.
      cellValues = cellValuesResult.records.map(r => ({
        id: r.id,
        boardId: legacyBoardId,          // ← defensive: always legacy in response
        rowId: r.fields.rowId ?? null,
        columnId: r.fields.columnId ?? null,
        textValue: r.fields.textValue ?? null,
        numberValue: r.fields.numberValue ?? null,
        dateValue: r.fields.dateValue ?? null,
        booleanValue: r.fields.booleanValue ?? null,
        fileUrl: r.fields.fileUrl ?? null,
      }));
    }

    return {
      success: true,
      boardId: legacyBoardId,           // compat: frontend uses this for cache key
      legacyBoardId,                    // explicit alias
      uuidBoardId,                      // real DB UUID — for debugging / future use
      canonicalBoardId: uuidBoardId,    // canonical alias
      tasks,
      columns,
      cellValues,
    };
  },
});

import { z } from 'zod';
import { createEndpoint, RecruitmentRows, Projects } from 'zite-integrations-backend-sdk';
import {
  buildIdentityClusters, resolveSignals, DuplicateSignalEnum,
  Signal, IdentityRow,
} from '../lib/duplicateIdentity';

const normClient = (s?: string) => (s ?? '').toLowerCase().trim();

const RowBadgeSchema = z.object({
  signals:              z.array(DuplicateSignalEnum),
  primaryBadge:         DuplicateSignalEnum.nullable(),
  secondaryBadges:      z.array(DuplicateSignalEnum),
  sameBoardCount:       z.number(),
  hasHighRisk:          z.boolean(),
  hasInternalDuplicate: z.boolean(),
});

export default createEndpoint({
  authenticated: true,
  description: 'Batch compute duplicate/participation badges for all rows in a board — single source of truth for row icons',
  inputSchema: z.object({
    projectCode: z.string(),
    boardName:   z.string(),
  }),
  outputSchema: z.object({
    badges: z.record(z.string(), RowBadgeSchema),
  }),
  execute: async ({ input }) => {
    const { projectCode, boardName } = input;

    // ── 0. Project metadata ──────────────────────────────────────────────────
    const { records: allProjects } = await Projects.findAll({
      limit: 500,
      fields: ['projectCode', 'startDate', 'client'],
    });
    const projectMap = new Map<string, { startDate?: string; client?: string }>();
    for (const p of allProjects) {
      if (p.projectCode) projectMap.set(p.projectCode, { startDate: p.startDate, client: p.client });
    }

    const currentProjData = projectMap.get(projectCode);
    const referenceDate   = currentProjData?.startDate ? new Date(currentProjData.startDate) : new Date();
    const sixMonthsAgo   = new Date(referenceDate);
    sixMonthsAgo.setMonth(sixMonthsAgo.getMonth() - 6);
    const currentClientNorm = normClient(currentProjData?.client);

    // ── 1. Fetch ALL active rows (paginated) ─────────────────────────────────
    const allRows: IdentityRow[] = [];
    let offset = 0;
    let hasMore = true;
    while (hasMore) {
      const batch = await RecruitmentRows.findAll({
        limit: 2000,
        offset,
        fields: ['id', 'projectCode', 'boardName', 'email', 'participantName', 'phone', 'status', 'group', 'deletedAt'],
      });
      allRows.push(...batch.records);
      hasMore = batch.hasMore;
      offset += batch.records.length;
    }
    const activeRows = allRows.filter(r => !r.deletedAt);

    // ── 2. Rows for the target board ─────────────────────────────────────────
    const boardRows = activeRows.filter(
      r => r.projectCode === projectCode && r.boardName === boardName,
    );
    if (boardRows.length === 0) return { badges: {} };

    // ── 3. Build identity clusters (union-find with full transitive closure) ─
    const clusters = buildIdentityClusters(activeRows);

    // Build rowId → clusterId lookup
    const rowToCluster = new Map<string, string>();
    for (const [cid, cluster] of clusters) {
      for (const rid of cluster.rowIds) rowToCluster.set(rid, cid);
    }

    const rowById = new Map(activeRows.map(r => [r.id, r]));

    // ── 4. Compute signals per cluster (cached) ─────────────────────────────
    type ClusterResult = { signalSet: Set<Signal>; sameBoardCount: number };
    const clusterCache = new Map<string, ClusterResult>();

    const badges: Record<string, z.infer<typeof RowBadgeSchema>> = {};

    for (const boardRow of boardRows) {
      const clusterId = rowToCluster.get(boardRow.id);
      if (!clusterId) continue;

      if (clusterCache.has(clusterId)) {
        const cached = clusterCache.get(clusterId)!;
        const { signals, primaryBadge, secondaryBadges } = resolveSignals(cached.signalSet);
        badges[boardRow.id] = {
          signals, primaryBadge, secondaryBadges,
          sameBoardCount:       cached.sameBoardCount,
          hasHighRisk:          primaryBadge === 'same_client' || primaryBadge === 'recent',
          hasInternalDuplicate: cached.sameBoardCount > 1,
        };
        continue;
      }

      const cluster = clusters.get(clusterId)!;
      const peerRows = cluster.rowIds
        .map(id => rowById.get(id))
        .filter((r): r is IdentityRow => !!r);

      // sameBoardCount: how many rows from this cluster are in the target board
      const sameBoardCount = peerRows.filter(
        r => r.projectCode === projectCode && r.boardName === boardName,
      ).length;

      // Cross-project signals
      const signalSet = new Set<Signal>();
      for (const peer of peerRows) {
        if (!peer.projectCode) continue;

        const isSameBoard = peer.projectCode === projectCode && peer.boardName === boardName;
        if (isSameBoard) continue;

        const isSameProject = peer.projectCode === projectCode;
        if (isSameProject) continue;

        const peerProjData  = projectMap.get(peer.projectCode);
        const peerStartDate = peerProjData?.startDate ? new Date(peerProjData.startDate) : null;
        if (peerStartDate && peerStartDate > referenceDate) continue;

        const rawParticipated = peer.status === 'Asistió' || (!!peer.group && String(peer.group).trim() !== '');
        const isSameClient = !!currentClientNorm && !!peerProjData?.client && normClient(peerProjData.client) === currentClientNorm;
        const isRecent = !peerStartDate || peerStartDate > sixMonthsAgo;

        if (rawParticipated && isSameClient) {
          signalSet.add('same_client');
        } else if (rawParticipated && isRecent) {
          signalSet.add('recent');
        } else if (rawParticipated && !isRecent) {
          signalSet.add('old');
        } else if (!rawParticipated) {
          signalSet.add('registered_only');
        }
      }

      if (sameBoardCount > 1) signalSet.add('same_board_duplicate');

      clusterCache.set(clusterId, { signalSet, sameBoardCount });

      const { signals, primaryBadge, secondaryBadges } = resolveSignals(signalSet);
      badges[boardRow.id] = {
        signals, primaryBadge, secondaryBadges,
        sameBoardCount,
        hasHighRisk:          primaryBadge === 'same_client' || primaryBadge === 'recent',
        hasInternalDuplicate: sameBoardCount > 1,
      };
    }

    return { badges };
  },
});

import { z } from 'zod';
import { createEndpoint, Boards, BoardColumns } from 'zite-integrations-backend-sdk';

function mapColType(type: string | null | undefined): string {
  switch (type) {
    case 'Status':        return 'status';
    case 'Fecha':         return 'date';
    case 'Datetime':      return 'datetime';
    case 'Persona':       return 'people';
    case 'Color':         return 'color_picker';
    case 'Texto':         return 'text';
    case 'Número':        return 'numbers';
    case 'Número entero': return 'numbers';
    case 'Select':        return 'dropdown';
    default:              return (type ?? 'text').toLowerCase();
  }
}

// Saved format in excelColumnsJson: { order: string[], selected: string[] }
// Backwards-compat: if it's a plain string[] (old format), treat all as selected with original order
type SavedConfig = { order: string[]; selected: string[] };

export default createEndpoint({
  authenticated: true,
  description: 'Gets the available columns (in saved order) and previously saved selection for calendar Excel export',
  inputSchema: z.object({
    projectCode: z.string().optional(),
    calendarName: z.string().optional(),
    boardId: z.string().optional(),
  }),
  outputSchema: z.object({
    columns: z.array(z.object({
      id:    z.string(),
      title: z.string(),
      type:  z.string(),
    })),
    selectedIds: z.array(z.string()),
    nextVersion: z.number(),
  }),
  execute: async ({ input }) => {
    let resolvedBoardId: string;
    let boardResult: any = null;

    if (input.boardId) {
      // ── UUID-first: use boardId directly, skip ALL legacy resolution ──
      resolvedBoardId = input.boardId;
      boardResult = await Boards.findOne({ id: input.boardId });
    } else {
      // ── Legacy path: require projectCode + calendarName ──
      if (!input.projectCode || !input.calendarName) {
        throw new Error('Either boardId or both projectCode and calendarName are required.');
      }

      // Ambiguity detection
      const boardsResult = await Boards.findAll({
        filters: { boardName: input.calendarName, projectCode: input.projectCode, boardType: 'calendar' } as any,
        limit: 10,
      });
      const activeBoards = boardsResult.records.filter(b => !b.deletedAt);
      if (activeBoards.length > 1) {
        throw new Error(`Ambiguity: ${activeBoards.length} calendars named "${input.calendarName}" for project ${input.projectCode}. Pass boardId to disambiguate.`);
      }
      if (activeBoards.length === 1) {
        resolvedBoardId = activeBoards[0].id;
        boardResult = activeBoards[0];
      } else {
        // Last resort legacy composite
        resolvedBoardId = `cal-${input.projectCode}-${input.calendarName}`;
        boardResult = null;
      }
    }

    // ── Fetch columns using resolved UUID ──
    const colRes = await BoardColumns.findAll({ filters: { boardId: resolvedBoardId } as any, limit: 200 });
    let activeCols = colRes.records.filter(c => !c.deletedAt);

    // ── Auto-create default columns if board has none ─────────────────────────
    if (activeCols.length === 0) {
      const defaultCols = [
        { columnName: 'Fecha y hora',          columnType: 'Datetime', optionsJson: undefined },
        { columnName: 'Duración (hrs)',         columnType: 'Número',   optionsJson: undefined },
        { columnName: 'Dinámica',               columnType: 'Texto',    optionsJson: undefined },
        { columnName: 'Perfil',                 columnType: 'Texto',    optionsJson: undefined },
        { columnName: 'Descripción',            columnType: 'Texto',    optionsJson: undefined },
        { columnName: 'Detalles adicionales',   columnType: 'Texto',    optionsJson: undefined },
        { columnName: 'Detalles adicionales 2', columnType: 'Texto',    optionsJson: undefined },
        { columnName: 'Status',                 columnType: 'Select',   optionsJson: JSON.stringify(['Por realizar', 'Realizada', 'Cancelada', 'Reprogramada', 'Caída', 'Reposición']) },
        { columnName: 'Ubicación Interna',      columnType: 'Select',   optionsJson: JSON.stringify(['Online', 'Sala 5-A', 'Sala 5-B', 'Sala 5-C', 'Sala 6-A', 'Sala 6-B', 'Sala 6-D', 'Sala 6-F', 'Sala 6-G', 'Sala 6-H', 'Otro']) },
        { columnName: 'Dirección',              columnType: 'Texto',    optionsJson: undefined },
        { columnName: 'Link',                   columnType: 'Texto',    optionsJson: undefined },
      ];
      await BoardColumns.bulkCreate({
        records: defaultCols.map((col, i) => ({
          boardId: resolvedBoardId,
          columnName: col.columnName,
          columnType: col.columnType,
          optionsJson: col.optionsJson,
          columnOrder: i,
        })),
      });
      const freshRes = await BoardColumns.findAll({ filters: { boardId: resolvedBoardId } as any, limit: 200 });
      activeCols = freshRes.records.filter(c => !c.deletedAt);
    }

    // Exclude "Ubicación Interna" — internal field, never exported to Excel
    activeCols = activeCols.filter(c => c.columnName !== 'Ubicación Interna' && c.columnName !== 'Ubicación (interna)');

    // Dedup by name (last wins)
    const deduped = new Map<string, typeof activeCols[0]>();
    for (const col of activeCols) {
      deduped.set((col.columnName ?? col.id).toLowerCase().trim(), col);
    }

    // Expand Datetime columns into two separate (Fecha) and (Hora) columns
    const allColumns: { id: string; title: string; type: string }[] = [];
    for (const col of Array.from(deduped.values())) {
      const type  = mapColType(col.columnType);
      const title = col.columnName ?? col.id;
      if (type === 'datetime') {
        allColumns.push({ id: `${col.id}__fecha`, title: 'Fecha', type: 'date' });
        allColumns.push({ id: `${col.id}__hora`,  title: 'Hora',  type: 'time' });
      } else {
        allColumns.push({ id: col.id, title, type });
      }
    }
    const allIds       = new Set(allColumns.map(c => c.id));
    const colById      = new Map(allColumns.map(c => [c.id, c]));

    // Parse saved config (supports both old string[] and new {order,selected} formats)
    let savedOrder:    string[] | null = null;
    let savedSelected: string[] | null = null;

    if (boardResult?.excelColumnsJson) {
      try {
        const parsed = JSON.parse(boardResult.excelColumnsJson);
        if (Array.isArray(parsed)) {
          savedSelected = (parsed as string[]).filter(id => allIds.has(id));
        } else if (parsed && Array.isArray(parsed.order) && Array.isArray(parsed.selected)) {
          const cfg = parsed as SavedConfig;
          savedOrder    = cfg.order.filter(id => allIds.has(id));
          savedSelected = cfg.selected.filter(id => allIds.has(id));
        }
      } catch { /* bad JSON — use defaults */ }
    }

    // Apply saved order: sorted columns first, then any new columns not in saved order
    let orderedColumns = allColumns;
    if (savedOrder && savedOrder.length > 0) {
      const inOrder    = savedOrder.map(id => colById.get(id)!).filter(Boolean);
      const remainder  = allColumns.filter(c => !savedOrder!.includes(c.id));
      orderedColumns   = [...inOrder, ...remainder];
    }

    // Selected IDs (default = all)
    const selectedIds = savedSelected && savedSelected.length > 0
      ? savedSelected
      : orderedColumns.map(c => c.id);

    const nextVersion = (boardResult?.calendarVersion ?? 0) + 1;

    return { columns: orderedColumns, selectedIds, nextVersion };
  },
});

import { z } from 'zod';
import { createEndpoint, Projects, Tasks, CalendarEvents, Users, PurchaseOrders, Messages, CellValues, BoardColumns, RecruitmentRows, Boards } from 'zite-integrations-backend-sdk';

const memberSchema = z.object({
  id: z.string(),
  name: z.string(),
  initials: z.string(),
  role: z.string(),
});

const projectSchema = z.object({
  id: z.string(),
  projectCode: z.string().optional(),
  fullName: z.string().optional(),
  status: z.string().optional(),
  client: z.string().optional(),
  startDate: z.string().optional(),
  endDate: z.string().optional(),
  team: z.array(memberSchema),
  myRole: z.string().optional(),
});

const taskSchema = z.object({
  id: z.string(),
  taskName: z.string().optional(),
  projectCode: z.string().optional(),
  status: z.string().optional(),
  assignedTo: z.string().optional(),
  endDate: z.string().optional(),
  boardName: z.string().optional(),
  statusOptions: z.array(z.string()).optional(),
});

const eventSchema = z.object({
  id: z.string(),
  eventName: z.string().optional(),
  projectCode: z.string().optional(),
  eventDate: z.string().optional(),
  location: z.string().optional(),
  calendarName: z.string().optional(),
  durationHours: z.number().optional(),
  assignedToMe: z.boolean().optional(),
});

const poCountsSchema = z.object({
  borrador: z.number(),
  enviadaAprobacion: z.number(),
  aprobada: z.number(),
  devuelta: z.number(),
  cancelada: z.number(),
  total: z.number(),
});

const mentionSchema = z.object({
  id: z.string(),
  channel: z.string().optional(),
  senderName: z.string().optional(),
  senderEmail: z.string().optional(),
  content: z.string().optional(),
  sentAt: z.string().optional(),
});

const toIds = (v: string[] | string | undefined): string[] => {
  if (!v) return [];
  return Array.isArray(v) ? v : [v];
};

const mkInitials = (u: { firstName?: string; lastName?: string; email?: string }) =>
  ((u.firstName?.[0] ?? '') + (u.lastName?.[0] ?? '')).toUpperCase() || (u.email?.[0]?.toUpperCase() ?? '?');

export default createEndpoint({
  authenticated: true,
  description: 'Get recruitment-specific dashboard data',
  inputSchema: z.object({}),
  outputSchema: z.object({
    isGlobal: z.boolean(),
    poCounts: poCountsSchema,
    recentMentions: z.array(mentionSchema),
    myProjects: z.array(projectSchema),
    myTasks: z.array(taskSchema),
    upcomingEvents: z.array(eventSchema),
  }),
  execute: async ({ context }) => {
    const user = context.user!;
    const isGlobal = ['Owner', 'Socio'].includes(user.role ?? '');
    const firstName = user.firstName ?? '';
    const lastName = user.lastName ?? '';
    const fullName = [firstName, lastName].filter(Boolean).join(' ');

    // Build mention search string
    const mentionSearch = firstName ? `@${firstName}` : `@${user.email}`;

    const now = new Date();
    const in14 = new Date(now.getTime() + 14 * 24 * 60 * 60 * 1000);

    // Parallel phase 1: POs, messages, projects, users
    const [{ records: recruitPOs }, { records: rawMentions }, { records: allProjects }, { records: allUsers }] = await Promise.all([
      PurchaseOrders.findAll({
        filters: { category: 'Reclutamiento e Incentivos' },
        limit: 2000,
        fields: ['status', 'category'],
      }),
      Messages.findAll({
        filters: { content: { contains: mentionSearch } },
        limit: 100,
        fields: ['id', 'channel', 'senderName', 'senderEmail', 'content', 'sentAt'],
      }),
      Projects.findAll({
        limit: 500,
        fields: ['projectCode', 'fullName', 'status', 'client', 'startDate', 'endDate', 'lider', 'analistas', 'moderadores', 'asistentes'],
      }),
      Users.findAll({ limit: 200, fields: ['firstName', 'lastName', 'email'] }),
    ]);

    // PO counts grouped by status
    const poStatusMap: Record<string, number> = {};
    for (const po of recruitPOs) {
      const s = po.status ?? 'Sin estado';
      poStatusMap[s] = (poStatusMap[s] ?? 0) + 1;
    }
    const poCounts = {
      borrador: poStatusMap['Borrador'] ?? 0,
      enviadaAprobacion: poStatusMap['Enviada a aprobación'] ?? 0,
      aprobada: poStatusMap['Aprobada'] ?? 0,
      devuelta: poStatusMap['Devuelta'] ?? 0,
      cancelada: poStatusMap['Cancelada'] ?? 0,
      total: recruitPOs.length,
    };

    // Filter and sort mentions, truncate content
    const mentionPattern = fullName ? `@${fullName}` : mentionSearch;
    const recentMentions = rawMentions
      .filter(m => {
        const c = m.content ?? '';
        return c.includes(mentionPattern) || c.includes(mentionSearch);
      })
      .sort((a, b) => {
        if (!a.sentAt && !b.sentAt) return 0;
        if (!a.sentAt) return 1;
        if (!b.sentAt) return -1;
        return a.sentAt > b.sentAt ? -1 : 1;
      })
      .slice(0, 10)
      .map(m => ({
        id: m.id,
        channel: m.channel,
        senderName: m.senderName,
        senderEmail: m.senderEmail,
        content: m.content ? m.content.slice(0, 120) + (m.content.length > 120 ? '…' : '') : undefined,
        sentAt: m.sentAt,
      }));

    // Projects
    const userMap = new Map(allUsers.map(u => [u.id, u]));
    const myProjects = isGlobal
      ? allProjects
      : allProjects.filter(p => {
          const members = [
            ...toIds(p.lider),
            ...toIds(p.analistas),
            ...toIds(p.moderadores),
            ...toIds(p.asistentes),
          ];
          return members.includes(user.id);
        });

    const projectsWithTeam = myProjects.map(p => {
      const team: { id: string; name: string; initials: string; role: string }[] = [];
      const addMembers = (ids: string[], role: string) => {
        for (const id of ids) {
          const u = userMap.get(id);
          if (u) team.push({ id, name: [u.firstName, u.lastName].filter(Boolean).join(' ') || u.email || '', initials: mkInitials(u), role });
        }
      };
      addMembers(toIds(p.lider), 'Líder');
      addMembers(toIds(p.analistas), 'Analista');
      addMembers(toIds(p.moderadores), 'Moderador');
      addMembers(toIds(p.asistentes), 'Asistente');

      let myRole: string | undefined;
      if (!isGlobal) {
        if (toIds(p.lider).includes(user.id)) myRole = 'Líder';
        else if (toIds(p.analistas).includes(user.id)) myRole = 'Analista';
        else if (toIds(p.moderadores).includes(user.id)) myRole = 'Moderador';
        else if (toIds(p.asistentes).includes(user.id)) myRole = 'Asistente';
      }

      return { id: p.id, projectCode: p.projectCode, fullName: p.fullName, status: p.status, client: p.client, startDate: p.startDate?.split('T')[0], endDate: p.endDate?.split('T')[0], team, myRole };
    });

    const myCodes = new Set(myProjects.map(p => p.projectCode).filter(Boolean) as string[]);

    // Phase 2: tasks, events, dynamic cells
    const [{ records: allTasks }, { records: allEvents }, { records: assignedCells }] = await Promise.all([
      Tasks.findAll({ limit: 1000, fields: ['taskName', 'projectCode', 'status', 'assignedTo', 'endDate', 'boardName', 'parentTaskId', 'boardId'] }),
      CalendarEvents.findAll({ limit: 500, fields: ['eventName', 'projectCode', 'eventDate', 'location', 'calendarName', 'durationHours'] }),
      CellValues.findAll({ filters: { textValue: user.id }, limit: 2000, fields: ['rowId', 'boardId'] }),
    ]);

    // UUID-native: batch-lookup unique boardIds against the Boards table to classify
    // by boardType instead of relying on legacy 'pm-' / 'cal-' prefixes.
    const uniqueBoardIds = [...new Set(assignedCells.map(c => c.boardId).filter(Boolean) as string[])];
    const boardTypeMap = new Map<string, string>();
    if (uniqueBoardIds.length > 0) {
      for (let i = 0; i < uniqueBoardIds.length; i += 100) {
        const batch = uniqueBoardIds.slice(i, i + 100);
        const { records: boardRecords } = await Boards.findAll({
          filters: { id: { in: batch } } as any,
          limit: 100,
          fields: ['boardType'],
        });
        for (const br of boardRecords) {
          if (br.boardType) boardTypeMap.set(br.id, br.boardType);
        }
      }
    }
    const classifyBoardId = (bid: string): 'pm' | 'calendar' | 'unknown' => {
      const bt = boardTypeMap.get(bid);
      if (bt === 'pm') return 'pm';
      if (bt === 'calendar') return 'calendar';
      if (bid.startsWith('pm-')) return 'pm';
      if (bid.startsWith('cal-')) return 'calendar';
      return 'unknown';
    };

    const dynamicAssignedTaskIds = new Set<string>();
    const dynamicAssignedEventIds = new Set<string>();
    for (const cell of assignedCells) {
      const cls = classifyBoardId(cell.boardId ?? '');
      if (cls === 'calendar' && cell.rowId) dynamicAssignedEventIds.add(cell.rowId);
      if (cls === 'pm' && cell.rowId) dynamicAssignedTaskIds.add(cell.rowId);
    }

    const projectTasks = allTasks.filter(t =>
      !t.parentTaskId &&
      (isGlobal || myCodes.has(t.projectCode ?? '') || dynamicAssignedTaskIds.has(t.id))
    );

    // Phase 3: dynamic status options for task boards
    const taskBoardIdMap = new Map<string, string>();
    for (const t of projectTasks) {
      if (!t.projectCode) continue;
      // Prefer UUID boardId if available
      if ((t as any).boardId && boardTypeMap.has((t as any).boardId)) {
        taskBoardIdMap.set(t.id, (t as any).boardId);
      } else {
        taskBoardIdMap.set(t.id, t.boardName ? `pm-${t.projectCode}-${t.boardName}` : `pm-${t.projectCode}`);
      }
    }
    for (const cell of assignedCells.filter(c => classifyBoardId(c.boardId ?? '') === 'pm')) {
      if (cell.rowId && cell.boardId) taskBoardIdMap.set(cell.rowId, cell.boardId);
    }

    // Include both UUID and legacy PM board IDs
    const allPmBoardIds = [...new Set([...taskBoardIdMap.values()].filter(b => {
      if (boardTypeMap.get(b) === 'pm') return true;
      return b.startsWith('pm-') && b !== 'pm-';
    }))];
    const statusOptionsByBoard = new Map<string, string[]>();

    if (allPmBoardIds.length > 0) {
      const boardColResults = await Promise.all(
        allPmBoardIds.map(boardId =>
          BoardColumns.findAll({ filters: { boardId } as any, limit: 200, fields: ['columnName', 'columnType', 'boardId', 'optionsJson', 'deletedAt'] }).then(r => r.records)
        )
      );
      for (let i = 0; i < allPmBoardIds.length; i++) {
        const boardId = allPmBoardIds[i];
        const estadoCol = boardColResults[i].find(c => !c.deletedAt && (c.columnName ?? '').toLowerCase() === 'estado');
        if (estadoCol) {
          try {
            const raw = JSON.parse((estadoCol as any).optionsJson ?? '[]');
            const labels: string[] = raw.map((o: unknown) => typeof o === 'string' ? o : ((o as Record<string, string>).value ?? (o as Record<string, string>).label ?? '')).filter(Boolean);
            if (labels.length > 0) statusOptionsByBoard.set(boardId, labels);
          } catch { /* ignore */ }
        }
      }
    }

    const myTasks = projectTasks
      .filter(t => {
        if (dynamicAssignedTaskIds.has(t.id)) return true;
        if (!t.assignedTo) return false;
        const a = t.assignedTo.toLowerCase();
        if (firstName && a.includes(firstName.toLowerCase())) return true;
        if (lastName && a.includes(lastName.toLowerCase())) return true;
        return false;
      })
      .sort((a, b) => {
        if (!a.endDate && !b.endDate) return 0;
        if (!a.endDate) return 1;
        if (!b.endDate) return -1;
        return a.endDate < b.endDate ? -1 : 1;
      })
      .map(t => ({
        id: t.id,
        taskName: t.taskName,
        projectCode: t.projectCode,
        status: t.status,
        assignedTo: t.assignedTo,
        endDate: t.endDate?.split('T')[0],
        boardName: t.boardName,
        statusOptions: statusOptionsByBoard.get(taskBoardIdMap.get(t.id) ?? '') ?? [],
      }));

    const upcomingEvents = allEvents
      .filter(ev => {
        if (!ev.eventDate) return false;
        const d = new Date(ev.eventDate);
        if (d < now || d > in14) return false;
        return isGlobal || myCodes.has(ev.projectCode ?? '') || dynamicAssignedEventIds.has(ev.id);
      })
      .sort((a, b) => (a.eventDate ?? '') < (b.eventDate ?? '') ? -1 : 1)
      .slice(0, 20)
      .map(ev => ({
        id: ev.id,
        eventName: ev.eventName,
        projectCode: ev.projectCode,
        eventDate: ev.eventDate,
        location: ev.location,
        calendarName: ev.calendarName,
        durationHours: ev.durationHours,
        assignedToMe: dynamicAssignedEventIds.has(ev.id),
      }));

    return { isGlobal, poCounts, recentMentions, myProjects: projectsWithTeam, myTasks, upcomingEvents };
  },
});

import { z } from 'zod';
import { createEndpoint, Boards, CellValues } from 'zite-integrations-backend-sdk';

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const TIME_BUDGET_MS = 90_000;
const BATCH_SIZE = 20;
const BATCH_DELAY_MS = 500;
const RETRY_DELAY_MS = 2000;

function buildLegacyVariants(boardType: string, projectCode: string, boardName: string): string[] {
  const prefix = boardType === 'calendar' ? 'cal-'
    : boardType === 'recruitment' ? 'recruitment-'
    : boardType === 'events' ? 'events-'
    : 'pm-';
  const base = boardName ? `${prefix}${projectCode}-${boardName}` : `${prefix}${projectCode}`;
  return [base, `${base}::groups`, `${base}::children`];
}

function isLegacyBoardId(id: string): boolean {
  const base = id.replace(/::groups$|::children$/, '');
  return !UUID_RE.test(base);
}

const delay = (ms: number) => new Promise(r => setTimeout(r, ms));

export default createEndpoint({
  authenticated: true,
  description: 'Migrate CellValues boardId from legacy to UUID for a project — resumable, chunked, idempotent',
  inputSchema: z.object({
    projectCode: z.string(),
    boardId: z.string().optional(),
    offset: z.number().optional(),
    limit: z.number().optional(),
    dryRun: z.boolean(),
  }),
  outputSchema: z.object({
    projectCode: z.string(),
    boardId: z.string().nullable(),
    targetUUID: z.string().nullable(),
    migrated: z.number(),
    skipped: z.number(),
    failed: z.number(),
    offset: z.number(),
    nextOffset: z.number().nullable(),
    remaining: z.number().nullable(),
    done: z.boolean(),
    allDone: z.boolean(),
    dryRun: z.boolean(),
    elapsed: z.number(),
    timedOut: z.boolean(),
  }),
  execute: async ({ input }) => {
    const startTime = Date.now();
    const { projectCode, dryRun } = input;
    const limit = input.limit ?? 2000;
    const inputOffset = input.offset ?? 0;

    // 1. Load boards and build legacy→UUID map
    const { records: boards } = await Boards.findAll({ filters: { projectCode }, limit: 200 });
    const activeBoards = boards.filter(b => !b.deletedAt);

    const legacyToUUID: Record<string, string> = {};
    for (const board of activeBoards) {
      const bType = board.boardType || 'pm';
      const bName = board.boardName ?? '';
      const variants = buildLegacyVariants(bType, projectCode, bName);
      legacyToUUID[variants[0]] = board.id;
      legacyToUUID[variants[1]] = `${board.id}::groups`;
      legacyToUUID[variants[2]] = `${board.id}::children`;
    }

    // 2. Determine which boardId to process
    let targetBoardId = input.boardId ?? null;

    if (!targetBoardId) {
      for (const legacyId of Object.keys(legacyToUUID)) {
        const { records } = await CellValues.findAll({
          filters: { boardId: legacyId },
          limit: 1,
          fields: ['id'],
        });
        if (records.length > 0) {
          targetBoardId = legacyId;
          break;
        }
      }
    }

    // No legacy boardId found → all done
    if (!targetBoardId) {
      return {
        projectCode,
        boardId: null,
        targetUUID: null,
        migrated: 0,
        skipped: 0,
        failed: 0,
        offset: 0,
        nextOffset: null,
        remaining: null,
        done: true,
        allDone: true,
        dryRun,
        elapsed: (Date.now() - startTime) / 1000,
        timedOut: false,
      };
    }

    const targetUUID = legacyToUUID[targetBoardId] ?? null;

    // 3. Fetch CellValues
    // Live mode: offset=0 because migrated records leave the filter
    // Dry run: use input offset to paginate without re-counting
    const fetchOffset = dryRun ? inputOffset : 0;
    const { records: cells, hasMore } = await CellValues.findAll({
      filters: { boardId: targetBoardId },
      offset: fetchOffset,
      limit,
      fields: ['id', 'boardId'],
    });

    let migrated = 0;
    let skipped = 0;
    let failed = 0;
    let timedOut = false;
    let cellsProcessed = 0;
    let stoppedEarly = false;

    // 4. Process in batches of BATCH_SIZE with Promise.allSettled
    for (let i = 0; i < cells.length; i += BATCH_SIZE) {
      // Time budget check
      if (Date.now() - startTime > TIME_BUDGET_MS) {
        timedOut = true;
        break;
      }

      const batch = cells.slice(i, i + BATCH_SIZE);
      const toUpdate: { id: string; newBoardId: string }[] = [];

      for (const cell of batch) {
        const bid = cell.boardId ?? '';
        if (!isLegacyBoardId(bid)) {
          skipped++;
          continue;
        }
        if (targetUUID) {
          toUpdate.push({ id: cell.id, newBoardId: targetUUID });
        } else {
          failed++;
        }
      }

      cellsProcessed += batch.length;

      if (toUpdate.length === 0) continue;

      if (!dryRun) {
        // Execute updates in parallel with allSettled
        const results = await Promise.allSettled(
          toUpdate.map(u =>
            CellValues.update({ id: u.id, record: { boardId: u.newBoardId } })
          )
        );

        let fulfilled = results.filter(r => r.status === 'fulfilled').length;
        const failedItems = toUpdate.filter((_, idx) => results[idx].status === 'rejected');

        // Retry failed items once after waiting
        if (failedItems.length > 0) {
          await delay(RETRY_DELAY_MS);

          const retryResults = await Promise.allSettled(
            failedItems.map(u =>
              CellValues.update({ id: u.id, record: { boardId: u.newBoardId } })
            )
          );

          const retryFulfilled = retryResults.filter(r => r.status === 'fulfilled').length;
          const retryFailed = retryResults.filter(r => r.status === 'rejected').length;

          fulfilled += retryFulfilled;

          if (retryFailed > 0) {
            // Same records failed twice — stop and report
            migrated += fulfilled;
            failed += retryFailed;
            stoppedEarly = true;
            break;
          }
        }

        // Verify one cell from the batch actually changed
        const verifyCell = await CellValues.findOne({
          id: toUpdate[0].id,
          fields: ['boardId'],
        });

        if (!verifyCell || isLegacyBoardId(verifyCell.boardId ?? '')) {
          // Verification failed — updates didn't stick
          failed += fulfilled;
          stoppedEarly = true;
          break;
        }

        // All good — count as migrated
        migrated += fulfilled;
      } else {
        // Dry run — just count
        migrated += toUpdate.length;
      }

      // Delay between batches (skip on last batch)
      if (i + BATCH_SIZE < cells.length) {
        await delay(BATCH_DELAY_MS);
      }
    }

    // 5. Determine done / nextOffset
    const processedAll = cellsProcessed >= cells.length;
    const done = !hasMore && processedAll && !timedOut && !stoppedEarly;

    let nextOffset: number | null = null;
    if (!done) {
      if (dryRun) {
        // In dry run, advance by what we processed
        nextOffset = fetchOffset + cellsProcessed;
      } else {
        // In live mode, offset stays 0 (records leave filter)
        nextOffset = 0;
      }
    }

    let remaining: number | null = null;
    if (!done) {
      const unprocessed = cells.length - cellsProcessed;
      remaining = unprocessed + (hasMore ? 1 : 0); // +1 signals "more pages exist"
      if (remaining < 0) remaining = null;
    }

    // 6. Check allDone — are there other legacy boardIds with cells?
    let allDone = done;
    if (done) {
      for (const legacyId of Object.keys(legacyToUUID)) {
        if (legacyId === targetBoardId) continue;
        const { records } = await CellValues.findAll({
          filters: { boardId: legacyId },
          limit: 1,
          fields: ['id'],
        });
        if (records.length > 0) {
          allDone = false;
          break;
        }
      }
    }

    return {
      projectCode,
      boardId: targetBoardId,
      targetUUID,
      migrated,
      skipped,
      failed,
      offset: fetchOffset,
      nextOffset,
      remaining,
      done,
      allDone,
      dryRun,
      elapsed: (Date.now() - startTime) / 1000,
      timedOut,
    };
  },
});

import { useState } from 'react';
import { ParseOdcCsvOutputType } from 'zite-endpoints-sdk';
import { Button } from '@/components/ui/button';
import { FolderPlus, Building2, ChevronDown, ChevronRight, CheckCircle2, MinusCircle } from 'lucide-react';
import SearchableSelect, { SelectOption } from './SearchableSelect';

type Preview = ParseOdcCsvOutputType;

interface Props {
  preview: Preview;
  projectMappings: Record<string, string>;
  supplierMappings: Record<string, string>;
  onProjectMap: (code: string, decision: string) => void;
  onSupplierMap: (key: string, decision: string) => void;
}

export default function OdcMappingPanel({ preview, projectMappings, supplierMappings, onProjectMap, onSupplierMap }: Props) {
  const [showProjects, setShowProjects] = useState(true);
  const [showSuppliers, setShowSuppliers] = useState(true);

  const hasIssues = preview.projectsToCreate.length > 0 || preview.suppliersNotFound.length > 0;
  if (!hasIssues) return null;

  const projectOptions: SelectOption[] = [
    { value: 'create', label: '➕ Crear proyecto nuevo' },
    { value: 'skip', label: '⏭️ Dejar sin vincular', sub: 'Se importa la ODC sin proyecto' },
    ...preview.existingProjects.map(p => ({
      value: p.code,
      label: p.code,
      sub: p.fullName || undefined,
    })),
  ];

  const supplierOptions: SelectOption[] = [
    { value: 'raw', label: '📝 Guardar nombre del CSV' },
    { value: 'create', label: '➕ Crear proveedor nuevo en BD' },
    ...preview.existingSuppliers.map(s => ({
      value: s.name,
      label: s.name,
      sub: s.rfc ? `RFC: ${s.rfc}` : undefined,
    })),
  ];

  const projectDecisionLabel = (decision: string) => {
    if (!decision || decision === 'create') return '➕ Crear proyecto nuevo';
    return decision;
  };

  const supplierDecisionLabel = (decision: string) => {
    if (!decision || decision === 'raw') return '📝 Guardar nombre del CSV';
    if (decision === 'create') return '➕ Crear proveedor nuevo en BD';
    return decision;
  };

  return (
    <div className="space-y-3">
      {/* Projects */}
      {preview.projectsToCreate.length > 0 && (
        <div className="rounded-xl border border-amber-200 bg-amber-50/50 p-4 space-y-3">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <FolderPlus className="w-4 h-4 text-amber-600" />
              <p className="text-sm font-medium text-amber-800">
                {preview.projectsToCreate.length} proyectos no encontrados en BD
              </p>
            </div>
            <Button size="sm" variant="ghost" className="text-amber-700 text-xs h-7 gap-1" onClick={() => setShowProjects(p => !p)}>
              {showProjects ? <ChevronDown className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />}
              {showProjects ? 'Colapsar' : 'Resolver'}
            </Button>
          </div>
          {showProjects && (
            <div className="space-y-2">
              <p className="text-xs text-amber-700">
                Para cada proyecto del CSV, elige si crearlo nuevo o vincularlo a uno existente:
              </p>
              {preview.projectsToCreate.map(code => {
                const decision = projectMappings[code] ?? 'create';
                const isLinkedToExisting = decision !== 'create' && decision !== 'skip';
                const isSkip = decision === 'skip';
                return (
                  <div key={code} className="flex items-center gap-3 bg-white/60 rounded-lg px-3 py-2 border border-amber-100">
                    <div className="flex-1 min-w-0">
                      <p className="text-xs font-semibold text-foreground truncate">{code}</p>
                    </div>
                    {isLinkedToExisting && <CheckCircle2 className="w-3.5 h-3.5 text-primary shrink-0" />}
                    {isSkip && <MinusCircle className="w-3.5 h-3.5 text-muted-foreground shrink-0" />}
                    <SearchableSelect
                      value={decision}
                      onChange={v => onProjectMap(code, v)}
                      options={projectOptions}
                      placeholder="Elegir acción…"
                    />
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {/* Suppliers */}
      {preview.suppliersNotFound.length > 0 && (
        <div className="rounded-xl border border-orange-200 bg-orange-50/40 p-4 space-y-3">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Building2 className="w-4 h-4 text-orange-600" />
              <p className="text-sm font-medium text-orange-800">
                {preview.suppliersNotFound.length} proveedores sin match por RFC/email/nombre
              </p>
            </div>
            <Button size="sm" variant="ghost" className="text-orange-700 text-xs h-7 gap-1" onClick={() => setShowSuppliers(p => !p)}>
              {showSuppliers ? <ChevronDown className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />}
              {showSuppliers ? 'Colapsar' : 'Resolver'}
            </Button>
          </div>
          {showSuppliers && (
            <div className="space-y-2">
              <p className="text-xs text-orange-700">
                Para cada proveedor, elige si guardar el nombre tal como viene, crear en BD, o vincularlo a uno existente:
              </p>
              {preview.suppliersNotFound.map((s, i) => {
                const key = s.rfc || s.name || `row-${i}`;
                const decision = supplierMappings[key] ?? (s.suggestedMatch ?? 'raw');
                const isLinked = decision !== 'raw' && decision !== 'create';
                const isCreating = decision === 'create';
                const hasSuggestion = !!s.suggestedMatch && (s.suggestedScore ?? 0) > 0.4;
                const isUsingSuggestion = hasSuggestion && decision === s.suggestedMatch;
                return (
                  <div key={key} className="flex items-start gap-3 bg-white/60 rounded-lg px-3 py-2 border border-orange-100">
                    <div className="flex-1 min-w-0">
                      <p className="text-xs font-semibold text-foreground truncate">{s.name || '—'}</p>
                      <div className="flex items-center gap-1.5 mt-0.5 flex-wrap">
                        <p className="text-[10px] text-muted-foreground">
                          {s.rfc ? `RFC: ${s.rfc}` : 'Sin RFC'} · {s.odcCount} ODC{s.odcCount !== 1 ? 's' : ''}
                        </p>
                        {hasSuggestion && isUsingSuggestion && (
                          <span className="text-[10px] px-1.5 py-0.5 rounded bg-primary/10 text-primary font-medium border border-primary/20">
                            ✨ sugerido {s.suggestedScore ? `${Math.round(s.suggestedScore * 100)}%` : ''}
                          </span>
                        )}
                        {hasSuggestion && !isUsingSuggestion && decision === 'raw' && (
                          <span className="text-[10px] px-1.5 py-0.5 rounded bg-muted text-muted-foreground border border-border">
                            posible: {s.suggestedMatch}
                          </span>
                        )}
                      </div>
                    </div>
                    {(isLinked || isCreating) && (
                      <CheckCircle2 className={`w-3.5 h-3.5 shrink-0 mt-0.5 ${isCreating ? 'text-amber-500' : 'text-primary'}`} />
                    )}
                    <SearchableSelect
                      value={decision}
                      onChange={v => onSupplierMap(key, v)}
                      options={supplierOptions}
                      placeholder="Elegir acción…"
                    />
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Loader2, CheckCircle2, AlertCircle } from 'lucide-react';
import { Progress } from '@/components/ui/progress';
import { subscribeToPendingSaves, getPendingSaveState } from '../hooks/useDynamicColumns';

export default function PendingSavesBar() {
  const [state, setState] = useState(getPendingSaveState());

  useEffect(() => {
    const unsub = subscribeToPendingSaves(() => {
      setState(getPendingSaveState());
    });
    return unsub;
  }, []);

  const { pending, completed, failed, total } = state;
  const isActive = total > 0;
  const isDone   = isActive && pending === 0;
  const progress = total > 0 ? Math.round(((completed + failed) / total) * 100) : 0;

  return (
    <AnimatePresence>
      {isActive && (
        <motion.div
          key="pending-saves-bar"
          initial={{ y: 60, opacity: 0 }}
          animate={{ y: 0,  opacity: 1 }}
          exit={{ y: 60, opacity: 0 }}
          transition={{ type: 'spring', stiffness: 380, damping: 32 }}
          className="fixed bottom-4 left-1/2 -translate-x-1/2 z-50 pointer-events-none"
        >
          <div className="bg-card border border-border shadow-lg rounded-xl px-4 py-2.5 flex items-center gap-3 min-w-[280px] max-w-sm">
            {/* Icon */}
            {!isDone ? (
              <Loader2 className="w-4 h-4 text-primary animate-spin flex-shrink-0" />
            ) : failed > 0 ? (
              <AlertCircle className="w-4 h-4 text-destructive flex-shrink-0" />
            ) : (
              <CheckCircle2 className="w-4 h-4 text-chart-2 flex-shrink-0" />
            )}

            {/* Text + bar */}
            <div className="flex-1 min-w-0">
              {!isDone ? (
                <>
                  <p className="text-xs font-medium text-foreground leading-tight">
                    Guardando cambios&hellip;&nbsp;
                    <span className="text-muted-foreground font-normal">
                      {completed + failed} de {total}
                    </span>
                  </p>
                  <Progress value={progress} className="h-1 mt-1.5" />
                </>
              ) : failed > 0 ? (
                <p className="text-xs font-medium text-destructive leading-tight">
                  {failed} cambio{failed !== 1 ? 's' : ''} no se pudi{failed !== 1 ? 'eron' : 'o'} guardar
                </p>
              ) : (
                <p className="text-xs font-medium text-chart-2 leading-tight">
                  Todos los cambios guardados ✓
                </p>
              )}
            </div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

import React, { useRef, useState } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Plus, Trash2, Copy, X } from 'lucide-react';
import type { BoardObj } from './pmTypes';

interface BoardBadge {
  version?: number;
  url?: string;
  status?: string;
}

interface BoardTabsBarProps {
  boards: string[];
  boardObjects?: BoardObj[];
  activeBoard: string;
  onActiveBoardChange: (board: string) => void;
  adding: boolean;
  setAdding: (v: boolean) => void;
  newBoardName: string;
  setNewBoardName: (v: string) => void;
  onAddBoard: () => void;
  onDuplicateBoard: (boardName: string) => void;
  onDeleteBoard: (boardIdOrName: string) => void;
  onReorder: (fromIdx: number, toIdx: number) => void;
  onRenameBoard?: (keyOrOldName: string, newName: string) => void;
  addLabel: string;
  inputPlaceholder: string;
  getBadge?: (keyOrName: string) => BoardBadge | undefined;
}

export function BoardTabsBar({
  boards,
  boardObjects,
  activeBoard,
  onActiveBoardChange,
  adding,
  setAdding,
  newBoardName,
  setNewBoardName,
  onAddBoard,
  onDuplicateBoard,
  onDeleteBoard,
  onReorder,
  onRenameBoard,
  addLabel,
  inputPlaceholder,
  getBadge,
}: BoardTabsBarProps) {
  const dragIdxRef = useRef<number>(-1);
  const [dragOverIdx, setDragOverIdx] = useState<number>(-1);
  // editingBoard stores the item key (UUID when boardObjects present, name otherwise)
  const [editingBoard, setEditingBoard] = useState<string | null>(null);
  const [editingValue, setEditingValue] = useState('');

  // Unified items array: key for identity, label for display
  const items = boardObjects
    ? boardObjects.map(b => ({ key: b.id, label: b.name }))
    : boards.map(b => ({ key: b, label: b }));

  const displayItems = items;

  const startEdit = (key: string, label: string) => {
    setEditingBoard(key);
    setEditingValue(label);
  };

  const commitEdit = (key: string, originalLabel: string) => {
    const trimmed = editingValue.trim();
    setEditingBoard(null);
    if (trimmed && trimmed !== originalLabel) {
      onRenameBoard?.(key, trimmed);
    }
  };

  const cancelEdit = () => {
    setEditingBoard(null);
    setEditingValue('');
  };

  return (
    <div className="flex items-center gap-0.5 px-4 pt-3 border-b border-border bg-card overflow-x-auto flex-shrink-0 min-w-0 scrollbar-thin">
      {displayItems.map((item, idx) => {
        const isDropTarget = dragOverIdx === idx && dragIdxRef.current !== idx;
        const badge = getBadge?.(item.key);
        const isEditing = editingBoard === item.key;
        return (
          <div
            key={item.key}
            draggable={!isEditing}
            onDragStart={e => { dragIdxRef.current = idx; e.dataTransfer.effectAllowed = 'move'; }}
            onDragOver={e => { e.preventDefault(); setDragOverIdx(idx); }}
            onDragLeave={() => setDragOverIdx(-1)}
            onDrop={e => { e.preventDefault(); onReorder(dragIdxRef.current, idx); setDragOverIdx(-1); }}
            onDragEnd={() => { dragIdxRef.current = -1; setDragOverIdx(-1); }}
            className={`group/tab flex-shrink-0 flex items-center border-b-2 transition-colors whitespace-nowrap ${isEditing ? 'cursor-text' : 'cursor-grab active:cursor-grabbing'} relative ${
              activeBoard === item.key ? 'border-primary' : 'border-transparent'
            } ${isDropTarget ? 'border-l-2 border-l-primary' : ''}`}
          >
            {isEditing ? (
              <Input
                className="h-7 w-32 text-sm px-2 my-1 mx-1"
                value={editingValue}
                onChange={e => setEditingValue(e.target.value)}
                onKeyDown={e => {
                  if (e.key === 'Enter') { e.preventDefault(); commitEdit(item.key, item.label); }
                  if (e.key === 'Escape') { e.preventDefault(); cancelEdit(); }
                }}
                onBlur={() => commitEdit(item.key, item.label)}
                autoFocus
                onClick={e => e.stopPropagation()}
              />
            ) : (
              <button
                onClick={() => onActiveBoardChange(item.key)}
                onDoubleClick={e => { e.preventDefault(); if (onRenameBoard) startEdit(item.key, item.label); }}
                className={`px-3 py-2 text-sm font-medium transition-colors flex items-center gap-1.5 ${
                  activeBoard === item.key ? 'text-primary' : 'text-muted-foreground hover:text-foreground'
                }`}
                title={`${item.label} · ${item.key.slice(0, 6)}${onRenameBoard ? ' · Doble clic para renombrar' : ''}`}
              >
                {item.label}
                {badge?.version && (
                  <a
                    href={badge.url ?? '#'}
                    target="_blank"
                    rel="noopener noreferrer"
                    onClick={e => { e.stopPropagation(); if (!badge.url) e.preventDefault(); }}
                    title={badge.url ? 'Abrir archivo Excel' : `V${badge.version}`}
                    className="inline-flex items-center gap-0.5 text-[10px] font-semibold px-1.5 py-0.5 rounded-full bg-emerald-100 text-emerald-700 hover:bg-emerald-200 transition-colors"
                  >
                    V{badge.version} ✓
                  </a>
                )}
              </button>
            )}
            {!isEditing && (
              <>
                <button
                  onClick={e => { e.stopPropagation(); onDuplicateBoard(item.label); }}
                  className="opacity-0 group-hover/tab:opacity-100 transition-opacity p-0.5 rounded text-muted-foreground/40 hover:text-primary hover:bg-primary/10"
                  title={`Duplicar "${item.label}"`}
                >
                  <Copy className="w-3 h-3" />
                </button>
                <button
                  onClick={e => { e.stopPropagation(); onDeleteBoard(item.key); }}
                  className="opacity-0 group-hover/tab:opacity-100 transition-opacity p-0.5 mr-1 rounded text-muted-foreground/40 hover:text-destructive hover:bg-destructive/10"
                  title={`Eliminar "${item.label}"`}
                >
                  <Trash2 className="w-3 h-3" />
                </button>
              </>
            )}
          </div>
        );
      })}

      {adding ? (
        <div className="flex items-center gap-1 px-2 py-1 flex-shrink-0">
          <Input
            className="h-7 w-36 text-xs"
            placeholder={inputPlaceholder}
            value={newBoardName}
            onChange={e => setNewBoardName(e.target.value)}
            onKeyDown={e => {
              if (e.key === 'Enter') onAddBoard();
              if (e.key === 'Escape') setAdding(false);
            }}
            autoFocus
          />
          <Button size="sm" className="h-7 text-xs px-2" onClick={onAddBoard}>OK</Button>
          <Button size="sm" variant="ghost" className="h-7 w-7 p-0" onClick={() => setAdding(false)}>
            <X className="w-3 h-3" />
          </Button>
        </div>
      ) : (
        <button
          onClick={() => setAdding(true)}
          className="px-3 py-2 text-xs text-muted-foreground hover:text-foreground flex items-center gap-1 flex-shrink-0 whitespace-nowrap transition-colors"
        >
          <Plus className="w-3 h-3" /> {addLabel}
        </button>
      )}
    </div>
  );
}

import { useState, useMemo } from 'react';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Calendar } from '@/components/ui/calendar';
import { CalendarDays } from 'lucide-react';
import { format, isSameMonth, isSameYear } from 'date-fns';
import { es } from 'date-fns/locale/es';
import { fmt, toISO, normalizeRange } from './pmDateUtils';

export function TimelineCell({ taskId, startDate, endDate, onSave }: {
  taskId: string;
  startDate: string;
  endDate: string;
  onSave: (taskId: string, start: string, end: string) => void;
}) {
  const [open, setOpen]           = useState(false);
  const [anchorDate, setAnchorDate] = useState<Date | undefined>(undefined);
  const [hoverDate,  setHoverDate]  = useState<Date | undefined>(undefined);

  const startParsed = useMemo(() => startDate ? (() => { const d = new Date(startDate + 'T00:00:00'); return isNaN(d.getTime()) ? undefined : d; })() : undefined, [startDate]);
  const endParsed   = useMemo(() => endDate   ? (() => { const d = new Date(endDate   + 'T00:00:00'); return isNaN(d.getTime()) ? undefined : d; })() : undefined, [endDate]);

  const committedRange = useMemo(() => {
    if (startParsed && endParsed) return normalizeRange(startParsed, endParsed);
    if (startParsed) return { from: startParsed, to: startParsed };
    return undefined;
  }, [startParsed, endParsed]);

  const previewRange = useMemo(() => {
    if (!anchorDate) return undefined;
    return normalizeRange(anchorDate, hoverDate ?? anchorDate);
  }, [anchorDate, hoverDate]);

  const defaultMonth = startParsed ?? endParsed ?? new Date();

  // Compact label
  const label = (() => {
    if (!startParsed && !endParsed) return null;
    if (startParsed && endParsed) {
      const year = endParsed.getFullYear();
      if (isSameMonth(startParsed, endParsed) && isSameYear(startParsed, endParsed)) {
        return `${startParsed.getDate()} → ${endParsed.getDate()} ${format(endParsed, 'MMM yyyy', { locale: es }).replace(/\.$/, '')}`;
      }
      if (isSameYear(startParsed, endParsed)) {
        return `${fmt(startParsed)} → ${fmt(endParsed)} ${year}`;
      }
      return `${fmt(startParsed)} ${startParsed.getFullYear()} → ${fmt(endParsed)} ${year}`;
    }
    if (startParsed) return `${fmt(startParsed)} →`;
    return `→ ${fmt(endParsed!)}`;
  })();

  const hasRange = !!(startParsed && endParsed);

  const handleDayClick = (day: Date) => {
    const clicked = new Date(day); clicked.setHours(0, 0, 0, 0);

    if (!anchorDate) {
      // First click — set anchor, keep popover open for second click
      setAnchorDate(clicked);
      setHoverDate(clicked);
      return;
    }

    // Second click — finalize range, save, close
    const range = normalizeRange(anchorDate, clicked);
    onSave(taskId, toISO(range.from), toISO(range.to));
    setAnchorDate(undefined);
    setHoverDate(undefined);
    setOpen(false);
  };

  const handleOpenChange = (next: boolean) => {
    setOpen(next);
    if (!next) {
      setAnchorDate(undefined);
      setHoverDate(undefined);
    }
  };

  // Build modifiers for visual feedback
  const visibleRange = previewRange ?? committedRange;
  const modifiers: Record<string, Date | { from: Date; to: Date } | undefined> = {};
  const modifiersClassNames: Record<string, string> = {};

  if (visibleRange) {
    if (anchorDate) {
      // In-progress selection: show preview range
      modifiers.previewInner = { from: visibleRange.from, to: visibleRange.to };
      modifiers.previewStart = visibleRange.from;
      modifiers.previewEnd   = visibleRange.to;
      modifiersClassNames.previewInner = 'bg-accent/50 text-foreground !rounded-none';
      modifiersClassNames.previewStart = '!bg-primary !text-primary-foreground !rounded-l-md !rounded-r-none';
      modifiersClassNames.previewEnd   = '!bg-primary !text-primary-foreground !rounded-r-md !rounded-l-none';
    } else {
      // Committed (saved) range
      modifiers.committed      = { from: visibleRange.from, to: visibleRange.to };
      modifiers.committedStart = visibleRange.from;
      modifiers.committedEnd   = visibleRange.to;
      modifiersClassNames.committed      = 'bg-primary/15 text-foreground !rounded-none';
      modifiersClassNames.committedStart = '!bg-primary !text-primary-foreground !rounded-l-md !rounded-r-none';
      modifiersClassNames.committedEnd   = '!bg-primary !text-primary-foreground !rounded-r-md !rounded-l-none';
    }
  }

  return (
    <Popover open={open} onOpenChange={handleOpenChange} modal>
      <PopoverTrigger asChild>
        <button
          className={`group/tc flex items-center gap-1.5 w-full h-full px-2.5 py-1 text-left transition-colors hover:bg-primary/10 ${hasRange ? 'bg-primary/5' : ''}`}
          style={{ minHeight: 28 }}
        >
          {label ? (
            <span className="text-[11px] font-medium text-foreground tabular-nums leading-none">{label}</span>
          ) : (
            <span className="flex items-center gap-1 text-xs text-muted-foreground/30">
              <span>—</span>
              <CalendarDays className="w-3 h-3 opacity-0 group-hover/tc:opacity-100 transition-opacity" />
            </span>
          )}
        </button>
      </PopoverTrigger>
      <PopoverContent
        className="w-auto p-0"
        align="start"
        sideOffset={4}
        onOpenAutoFocus={e => e.preventDefault()}
      >
        {anchorDate && (
          <div className="px-3 pt-2.5 pb-0 text-xs text-muted-foreground">
            Ahora selecciona la fecha de fin…
          </div>
        )}
        <Calendar
          mode="default"
          defaultMonth={defaultMonth}
          numberOfMonths={2}
          locale={es}
          onDayClick={handleDayClick}
          onDayMouseEnter={(day) => {
            if (!anchorDate) return;
            const d = new Date(day); d.setHours(0, 0, 0, 0);
            setHoverDate(d);
          }}
          onDayMouseLeave={() => {
            if (anchorDate) setHoverDate(anchorDate);
          }}
          modifiers={modifiers as Parameters<typeof Calendar>[0]['modifiers']}
          modifiersClassNames={modifiersClassNames}
        />
        {(startDate || endDate) && (
          <div className="px-3 pb-2.5 border-t border-border/30 pt-2">
            <button
              className="text-xs text-muted-foreground hover:text-destructive transition-colors"
              onClick={() => { onSave(taskId, '', ''); setAnchorDate(undefined); setHoverDate(undefined); setOpen(false); }}
            >
              Limpiar fechas
            </button>
          </div>
        )}
      </PopoverContent>
    </Popover>
  );
}

