      taxId: z.string().optional(),
    })),
    unregistered: z.array(z.object({
      name: z.string(),
      poCount: z.number(),
      suggestedMatch: z.object({
        name: z.string(),
        score: z.number(),
      }).optional(),
    })),
    supplierDuplicates: z.array(z.object({
      normalizedName: z.string(),
      suppliers: z.array(z.object({
        id: z.string(),
        name: z.string(),
        taxId: z.string().optional(),
        poCount: z.number(),
      })),
    })),
    totalGroups: z.number(),
    totalVariants: z.number(),
    totalUnregistered: z.number(),
    totalSupplierDuplicates: z.number(),
  }),
  execute: async () => {
    const [{ records: pos }, { records: suppliers }] = await Promise.all([
      PurchaseOrders.findAll({ fields: ['supplierName'], limit: 2000 }),
      Suppliers.findAll({ fields: ['supplierName', 'taxId'], limit: 2000 }),
    ]);

    // DB supplier index for fuzzy matching on unregistered
    const dbSupplierNames = new Set(
      suppliers.map(s => s.supplierName?.trim() ?? '').filter(Boolean)
    );
    const dbIndex: { originalName: string; tokens: Set<string> }[] = [];
    for (const s of suppliers) {
      if (!s.supplierName) continue;
      const norm = normalizeName(s.supplierName);
      if (norm.length < 2) continue;
      dbIndex.push({ originalName: s.supplierName, tokens: tokenize(norm) });
    }

    // Count POs per exact supplier name
    const poCountByName: Record<string, number> = {};
    for (const po of pos) {
      const name = po.supplierName?.trim();
      if (!name) continue;
      poCountByName[name] = (poCountByName[name] || 0) + 1;
    }

    // ── PO variant groups ──────────────────────────────────────────────────────
    const poGroups: Record<string, string[]> = {};
    for (const name of Object.keys(poCountByName)) {
      const key = normalizeName(name);
      if (!key || key.length < 2) continue;
      if (!poGroups[key]) poGroups[key] = [];
      poGroups[key].push(name);
    }

    // Second pass: fuzzy-merge singleton PO groups into multi-variant groups
    fuzzyMergeGroups(poGroups, 0.6, 2);

    const duplicateGroups = Object.entries(poGroups)
      .filter(([, variants]) => variants.length >= 2)
      .map(([normalizedName, variants]) => ({
        normalizedName,
        variants: variants
          .map(name => ({
            name,
            poCount: poCountByName[name] ?? 0,
            inDb: dbSupplierNames.has(name),
          }))
          .sort((a, b) => b.poCount - a.poCount),
      }))
      .sort((a, b) =>
        b.variants.reduce((s, v) => s + v.poCount, 0) -
        a.variants.reduce((s, v) => s + v.poCount, 0)
      );

    // ── Unregistered suppliers ─────────────────────────────────────────────────
    const unregistered = Object.entries(poCountByName)
      .filter(([name]) => name.length > 0 && !dbSupplierNames.has(name))
      .map(([name, poCount]) => {
        const normTokens = tokenize(normalizeName(name));
        let bestMatch: { name: string; score: number } | undefined;
        if (normTokens.size >= 1) {
          for (const entry of dbIndex) {
            const score = jaccardScore(normTokens, entry.tokens);
            const sharedCount = [...normTokens].filter(t => entry.tokens.has(t)).length;
            if (score >= 0.5 && sharedCount >= 2) {
              if (!bestMatch || score > bestMatch.score) {
                bestMatch = { name: entry.originalName, score };
              }
            }
          }
        }
        return { name, poCount, suggestedMatch: bestMatch };
      })
      .sort((a, b) => {
        if (!!a.suggestedMatch !== !!b.suggestedMatch) return a.suggestedMatch ? -1 : 1;
        return b.poCount - a.poCount;
      });

    // ── Supplier table duplicates ──────────────────────────────────────────────
    type SupplierItem = { id: string; supplierName: string; taxId?: string };
    const supplierGroups: Record<string, SupplierItem[]> = {};
    for (const s of suppliers) {
      if (!s.supplierName) continue;
      const norm = normalizeName(s.supplierName);
      if (!norm || norm.length < 2) continue;
      if (!supplierGroups[norm]) supplierGroups[norm] = [];
      supplierGroups[norm].push({ id: s.id, supplierName: s.supplierName, taxId: s.taxId || undefined });
    }

    // Second pass: fuzzy-merge singleton supplier groups
    fuzzyMergeGroups(supplierGroups, 0.6, 2);

    const supplierDuplicates = Object.entries(supplierGroups)
      .filter(([, arr]) => arr.length >= 2)
      .map(([normalizedName, arr]) => ({
        normalizedName,
        suppliers: arr
          .map(s => ({
            id: s.id,
            name: s.supplierName,
            taxId: s.taxId,
            poCount: poCountByName[s.supplierName] ?? 0,
          }))
          .sort((a, b) => b.poCount - a.poCount),
      }))
      .sort((a, b) => b.suppliers.length - a.suppliers.length);

    return {
      groups: duplicateGroups,
      existingSuppliers: suppliers
        .map(s => ({ name: s.supplierName ?? '', taxId: s.taxId || undefined }))
        .filter(s => s.name.length > 0),
      unregistered,
      supplierDuplicates,
      totalGroups: duplicateGroups.length,
      totalVariants: duplicateGroups.reduce((sum, g) => sum + g.variants.length - 1, 0),
      totalUnregistered: unregistered.length,
      totalSupplierDuplicates: supplierDuplicates.length,
    };
  },
});

import { z } from 'zod';
import { createEndpoint, RecruitmentRows, Projects } from 'zite-integrations-backend-sdk';
import {
  buildIdentityClusters, findClusterForRow, aggregateClusterReasons,
  resolveSignals, DuplicateSignalEnum, Signal, IdentityRow,
} from '../lib/duplicateIdentity';

const normalizeClient = (s?: string) => (s ?? '').toLowerCase().trim();

const STATUS_PRIORITY = ['Asistió', 'Confirmado', 'Contactado', 'Pendiente', 'Descartado', 'No show'];

// ── History entry shape ─────────────────────────────────────────────────────
const HistoryEntrySchema = z.object({
  rowId:            z.string().optional(),
  projectCode:      z.string(),
  boardName:        z.string().optional(),
  group:            z.string().optional(),
  status:           z.string().optional(),
  sourceForm:       z.string().optional(),
  participated:     z.boolean(),
  sameProject:      z.boolean(),
  sameBoard:        z.boolean(),
  isCurrentRow:     z.boolean(),
  clientName:       z.string().optional(),
  projectStartDate: z.string().optional(),
  sameClient:       z.boolean(),
  isRecent:         z.boolean(),
  warningLevel:     z.enum(['same_client', 'recent', 'old', 'same_board']).nullable(),
});

type EntryShape = z.infer<typeof HistoryEntrySchema>;

const ResultSchema = z.object({
  id:                   z.string(),
  fullName:             z.string().optional(),
  email:                z.string().optional(),
  phone:                z.string().optional(),
  matchedBy:            z.array(z.string()),
  signals:              z.array(DuplicateSignalEnum),
  primaryBadge:         DuplicateSignalEnum.nullable(),
  secondaryBadges:      z.array(DuplicateSignalEnum),
  sameBoardCount:       z.number(),
  hasHighRisk:          z.boolean(),
  hasInternalDuplicate: z.boolean(),
  identityClusterId:    z.string(),
  identityMatchReasons: z.array(z.enum(['email', 'name', 'phone'])),
  history:              z.array(HistoryEntrySchema),
});

// ── Shared: build history + signals from a set of rows ──────────────────────
function buildPersonResult(
  personRows: IdentityRow[],
  opts: {
    projectCode?: string;
    boardName?: string;
    rowId?: string;
    currentClientNorm: string;
    referenceDate: Date;
    sixMonthsAgo: Date;
    projectMap: Map<string, { client?: string; startDate?: string }>;
    clusterId: string;
    clusterReasons: ('email' | 'name' | 'phone')[];
    matchedBy: string[];
  },
) {
  const { projectCode, boardName, rowId, currentClientNorm, referenceDate, sixMonthsAgo, projectMap } = opts;

  let fullName: string | undefined;
  let email: string | undefined;
  let phone: string | undefined;
  for (const r of personRows) {
    if (!fullName && r.participantName) fullName = r.participantName;
    if (!email    && r.email)           email    = r.email;
    if (!phone    && r.phone)           phone    = r.phone;
  }

  const sameBoardEntries: EntryShape[] = [];
  const crossBoardMap = new Map<string, EntryShape>();

  for (const row of personRows) {
    if (!row.projectCode) continue;

    const rawParticipated = row.status === 'Asistió' || (!!row.group && String(row.group).trim() !== '');
    const sameProject     = !!projectCode && row.projectCode === projectCode;
    const sameBoard       = sameProject && !!boardName && row.boardName === boardName;
    const isCurrentRow    = !!rowId && row.id === rowId;

    const projData         = projectMap.get(row.projectCode) ?? {};
    const clientName       = projData.client;
    const projectStartDate = projData.startDate;

    const otherStartDate  = projectStartDate ? new Date(projectStartDate) : null;
    const isFutureProject = !sameProject && !sameBoard && !!otherStartDate && otherStartDate > referenceDate;
    const isRecent        = !projectStartDate || new Date(projectStartDate) > sixMonthsAgo;

    const sameClient = !isFutureProject && !sameBoard && !sameProject && !!currentClientNorm &&
      !!clientName && normalizeClient(clientName) === currentClientNorm;

    let participated: boolean;
    let warningLevel: EntryShape['warningLevel'];

    if (isFutureProject) {
      participated = false; warningLevel = null;
    } else if (sameBoard) {
      participated = false; warningLevel = 'same_board';
    } else if (sameClient && rawParticipated) {
      participated = true; warningLevel = 'same_client';
    } else if (!sameProject && rawParticipated && isRecent) {
      participated = true; warningLevel = 'recent';
    } else if (!sameProject && rawParticipated && !isRecent) {
      participated = false; warningLevel = 'old';
    } else {
      participated = false; warningLevel = null;
    }

    const entry: EntryShape = {
      rowId: row.id, projectCode: row.projectCode, boardName: row.boardName,
      group: row.group, status: row.status, sourceForm: row.sourceForm,
      participated, sameProject, sameBoard, isCurrentRow,
      clientName, projectStartDate, sameClient, isRecent, warningLevel,
    };

    if (sameBoard) {
      sameBoardEntries.push(entry);
    } else {
      const boardKey = `${row.projectCode}||${row.boardName ?? ''}`;
      const existing = crossBoardMap.get(boardKey);
      if (!existing) {
        crossBoardMap.set(boardKey, entry);
      } else {
        const curIdx  = STATUS_PRIORITY.indexOf(row.status ?? '');
        const prevIdx = STATUS_PRIORITY.indexOf(existing.status ?? '');
        const betterStatus = (curIdx !== -1 && (prevIdx === -1 || curIdx < prevIdx)) ? row.status : existing.status;
        const levelRank = (l: EntryShape['warningLevel']) =>
          l === 'same_client' ? 4 : l === 'recent' ? 3 : l === 'old' ? 2 : l === 'same_board' ? 1 : 0;
        const worstWarning = levelRank(entry.warningLevel) >= levelRank(existing.warningLevel)
          ? entry.warningLevel : existing.warningLevel;
        const finalParticipated = worstWarning === 'same_client' || worstWarning === 'recent';
        crossBoardMap.set(boardKey, {
          ...existing,
          status: betterStatus,
          group: existing.group || row.group,
          sourceForm: existing.sourceForm || row.sourceForm,
          participated: finalParticipated,
          warningLevel: worstWarning,
          sameClient: existing.sameClient || entry.sameClient,
        });
      }
    }
  }

  sameBoardEntries.sort((a, b) => {
    if (a.isCurrentRow && !b.isCurrentRow) return -1;
    if (!a.isCurrentRow && b.isCurrentRow) return 1;
    return STATUS_PRIORITY.indexOf(a.status ?? '') - STATUS_PRIORITY.indexOf(b.status ?? '');
  });

  const history: EntryShape[] = [...sameBoardEntries, ...[...crossBoardMap.values()]];

  const sameBoardCount = sameBoardEntries.length;
  const signalSet = new Set<Signal>();

  for (const entry of crossBoardMap.values()) {
    if (entry.sameProject) continue;
    if (entry.projectStartDate && new Date(entry.projectStartDate) > referenceDate) continue;

    if (entry.warningLevel === 'same_client')  signalSet.add('same_client');
    else if (entry.warningLevel === 'recent')  signalSet.add('recent');
    else if (entry.warningLevel === 'old')     signalSet.add('old');
    else if (entry.warningLevel === null)      signalSet.add('registered_only');
  }

  if (sameBoardCount > 1) signalSet.add('same_board_duplicate');

  const { signals, primaryBadge, secondaryBadges } = resolveSignals(signalSet);

  return {
    id:                   opts.clusterId,
    fullName,
    email,
    phone,
    matchedBy:            opts.matchedBy,
    signals,
    primaryBadge,
    secondaryBadges,
    sameBoardCount,
    hasHighRisk:          primaryBadge === 'same_client' || primaryBadge === 'recent',
    hasInternalDuplicate: sameBoardCount > 1,
    identityClusterId:    opts.clusterId,
    identityMatchReasons: opts.clusterReasons,
    history,
  };
}

// ── Helper: load all active rows paginated ──────────────────────────────────
async function loadAllActiveRows(): Promise<IdentityRow[]> {
  const allRows: IdentityRow[] = [];
  let offset = 0;
  let hasMore = true;
  while (hasMore) {
    const batch = await RecruitmentRows.findAll({
      limit: 2000,
      offset,
      fields: ['id', 'participantName', 'email', 'phone', 'projectCode', 'boardName', 'status', 'group', 'sourceForm', 'deletedAt'],
    });
    allRows.push(...batch.records);
    hasMore = batch.hasMore;
    offset += batch.records.length;
  }
  return allRows.filter(r => !r.deletedAt);
}

// ── Helper: load project metadata ───────────────────────────────────────────
async function loadProjectMap(projectCodes: string[]): Promise<Map<string, { client?: string; startDate?: string }>> {
  const projectMap = new Map<string, { client?: string; startDate?: string }>();
  if (projectCodes.length === 0) return projectMap;
  const { records } = await Projects.findAll({
    filters: { projectCode: { in: [...new Set(projectCodes)] } },
    fields: ['projectCode', 'client', 'startDate'],
    limit: 500,
  });
  for (const p of records) {
    if (p.projectCode) projectMap.set(p.projectCode, { client: p.client, startDate: p.startDate });
  }
  return projectMap;
}

// ── Endpoint ────────────────────────────────────────────────────────────────

export default createEndpoint({
  authenticated: true,
  description: 'Search participant history — seed mode (canonical, complete) or query mode (exploratory)',
  inputSchema: z.object({
    seedRowId:     z.string().optional(),
    query:         z.string().optional(),
    projectCode:   z.string().optional(),
    boardName:     z.string().optional(),
    rowId:         z.string().optional(),
    currentClient: z.string().optional(),
  }),
  outputSchema: z.object({
    results: z.array(ResultSchema),
  }),

  execute: async ({ input }) => {
    const isSeedMode = !!input.seedRowId;

    // ═══════════════════════════════════════════════════════════════════════
    // SEED MODE — canonical, complete identity resolution
    // ═══════════════════════════════════════════════════════════════════════
    if (isSeedMode) {
      const activeRows = await loadAllActiveRows();
      if (activeRows.length === 0) return { results: [] };

      const clusters = buildIdentityClusters(activeRows);
      const match = findClusterForRow(clusters, input.seedRowId!);
      if (!match) return { results: [] };

      const { clusterId, cluster } = match;
      const rowById = new Map(activeRows.map(r => [r.id, r]));
      const personRows = cluster.rowIds.map(id => rowById.get(id)).filter((r): r is IdentityRow => !!r);

      const clusterProjectCodes = personRows.map(r => r.projectCode).filter(Boolean) as string[];
      if (input.projectCode) clusterProjectCodes.push(input.projectCode);
      const projectMap = await loadProjectMap(clusterProjectCodes);

      const currentProjectStartDate = input.projectCode ? projectMap.get(input.projectCode)?.startDate : undefined;
      const referenceDate = currentProjectStartDate ? new Date(currentProjectStartDate) : new Date();
      const sixMonthsAgo = new Date(referenceDate);
      sixMonthsAgo.setMonth(sixMonthsAgo.getMonth() - 6);
      const currentClientNorm = normalizeClient(input.currentClient);

      const clusterReasons = aggregateClusterReasons(cluster);

      const result = buildPersonResult(personRows, {
        projectCode:     input.projectCode,
        boardName:       input.boardName,
        rowId:           input.rowId ?? input.seedRowId,
        currentClientNorm,
        referenceDate,
        sixMonthsAgo,
        projectMap,
        clusterId,
        clusterReasons,
        matchedBy: clusterReasons,
      });

      return { results: [result] };
    }

    // ═══════════════════════════════════════════════════════════════════════
    // QUERY MODE — exploratory search
    // ═══════════════════════════════════════════════════════════════════════
    const q = (input.query ?? '').trim();
    if (q.length < 2) return { results: [] };

    const searchFields = ['id', 'participantName', 'email', 'phone', 'projectCode', 'boardName', 'status', 'group', 'sourceForm', 'deletedAt'];

    const [byName, byEmail, byPhone] = await Promise.all([
      RecruitmentRows.findAll({ filters: { participantName: { contains: q } }, limit: 200, fields: searchFields }),
      RecruitmentRows.findAll({ filters: { email:           { contains: q } }, limit: 200, fields: searchFields }),
      RecruitmentRows.findAll({ filters: { phone:           { contains: q } }, limit: 200, fields: searchFields }),
    ]);

    const matchedByEmailIds = new Set(byEmail.records.map(r => r.id));
    const matchedByNameIds  = new Set(byName.records.map(r => r.id));
    const matchedByPhoneIds = new Set(byPhone.records.map(r => r.id));

    const seen = new Set<string>();
    const allRows: IdentityRow[] = [];
    for (const r of [...byEmail.records, ...byName.records, ...byPhone.records]) {
      if (!seen.has(r.id)) { seen.add(r.id); allRows.push(r); }
    }
    const activeRows = allRows.filter(r => !r.deletedAt);
    if (activeRows.length === 0) return { results: [] };

    const clusters = buildIdentityClusters(activeRows);

    const rowProjectCodes = activeRows.map(r => r.projectCode).filter(Boolean) as string[];
    if (input.projectCode) rowProjectCodes.push(input.projectCode);
    const projectMap = await loadProjectMap(rowProjectCodes);

    const currentProjectStartDate = input.projectCode ? projectMap.get(input.projectCode)?.startDate : undefined;
    const referenceDate = currentProjectStartDate ? new Date(currentProjectStartDate) : new Date();
    const sixMonthsAgo = new Date(referenceDate);
    sixMonthsAgo.setMonth(sixMonthsAgo.getMonth() - 6);
    const currentClientNorm = normalizeClient(input.currentClient);

    const rowById = new Map(activeRows.map(r => [r.id, r]));

    const results = [...clusters.entries()].slice(0, 10).map(([clusterId, cluster]) => {
      const personRows = cluster.rowIds.map(id => rowById.get(id)).filter((r): r is IdentityRow => !!r);
      if (personRows.length === 0) return null;

      const queryMatchedBy = new Set<string>();
      for (const rid of cluster.rowIds) {
        if (matchedByEmailIds.has(rid)) queryMatchedBy.add('email');
        if (matchedByNameIds.has(rid))  queryMatchedBy.add('name');
        if (matchedByPhoneIds.has(rid)) queryMatchedBy.add('phone');
      }

      const clusterReasons = aggregateClusterReasons(cluster);

      return buildPersonResult(personRows, {
        projectCode:     input.projectCode,
        boardName:       input.boardName,
        rowId:           input.rowId,
        currentClientNorm,
        referenceDate,
        sixMonthsAgo,
        projectMap,
        clusterId,
        clusterReasons,
        matchedBy: [...queryMatchedBy],
      });
    }).filter((r): r is NonNullable<typeof r> => r !== null);

    results.sort((a, b) => b.history.length - a.history.length);

    return { results };
  },
});

import { useState, useRef, useCallback, useEffect } from 'react';
import { Slider } from '@/components/ui/slider';
import { Button } from '@/components/ui/button';
import { ImageIcon, Upload, X, ZoomIn } from 'lucide-react';

interface AvatarCropEditorProps {
  currentPhotoUrl?: string;
  onSave: (file: File) => Promise<void>;
}

const DISPLAY = 200;
const CANVAS  = 400;

export default function AvatarCropEditor({ currentPhotoUrl, onSave }: AvatarCropEditorProps) {
  const [imageSrc, setImageSrc] = useState<string | null>(null);
  const [imgEl,    setImgEl]    = useState<HTMLImageElement | null>(null);
  const [zoom,     setZoom]     = useState(1);
  const [offset,   setOffset]   = useState({ x: 0, y: 0 });
  const [dragging, setDragging] = useState(false);
  const [isDragOver, setIsDragOver] = useState(false);
  const [saving,   setSaving]   = useState(false);
  const [currentImgError, setCurrentImgError] = useState(false);

  const dragStart  = useRef<{ mx: number; my: number; ox: number; oy: number } | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const loadFile = (file: File) => {
    if (!file.type.startsWith('image/')) return;
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      setImgEl(img);
      setImageSrc(url);
      setZoom(1);
      setOffset({ x: 0, y: 0 });
    };
    img.src = url;
  };

  // ── Drag & drop handlers ─────────────────────────────────────────────────
  const handleDragOver = (e: React.DragEvent) => { e.preventDefault(); setIsDragOver(true); };
  const handleDragLeave = () => setIsDragOver(false);
  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragOver(false);
    const file = e.dataTransfer.files[0];
    if (file) loadFile(file);
  };

  const handleFileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) loadFile(file);
    e.target.value = '';
  };

  // ── Pan handlers (mouse) ─────────────────────────────────────────────────
  const onMouseDown = (e: React.MouseEvent) => {
    e.preventDefault();
    dragStart.current = { mx: e.clientX, my: e.clientY, ox: offset.x, oy: offset.y };
    setDragging(true);
  };

  const onMouseMove = useCallback((e: MouseEvent) => {
    if (!dragStart.current) return;
    setOffset({
      x: dragStart.current.ox + e.clientX - dragStart.current.mx,
      y: dragStart.current.oy + e.clientY - dragStart.current.my,
    });
  }, []);

  const onMouseUp = useCallback(() => {
    dragStart.current = null;
    setDragging(false);
  }, []);

  useEffect(() => {
    if (dragging) {
      window.addEventListener('mousemove', onMouseMove);
      window.addEventListener('mouseup', onMouseUp);
    }
    return () => {
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('mouseup', onMouseUp);
    };
  }, [dragging, onMouseMove, onMouseUp]);

  // ── Pan handlers (touch) ─────────────────────────────────────────────────
  const onTouchStart = (e: React.TouchEvent) => {
    const t = e.touches[0];
    dragStart.current = { mx: t.clientX, my: t.clientY, ox: offset.x, oy: offset.y };
  };
  const onTouchMove = (e: React.TouchEvent) => {
    if (!dragStart.current) return;
    const t = e.touches[0];
    setOffset({
      x: dragStart.current.ox + t.clientX - dragStart.current.mx,
      y: dragStart.current.oy + t.clientY - dragStart.current.my,
    });
  };
  const onTouchEnd = () => { dragStart.current = null; };

  // ── Export ───────────────────────────────────────────────────────────────
  const handleSave = async () => {
    if (!imgEl || saving) return;
    setSaving(true);
    try {
      const baseScale = Math.max(DISPLAY / imgEl.naturalWidth, DISPLAY / imgEl.naturalHeight);
      const totalScale = baseScale * zoom;
      const scale2x = CANVAS / DISPLAY;
      const drawW = imgEl.naturalWidth  * totalScale * scale2x;
      const drawH = imgEl.naturalHeight * totalScale * scale2x;
      const drawX = CANVAS / 2 - drawW / 2 + offset.x * scale2x;
      const drawY = CANVAS / 2 - drawH / 2 + offset.y * scale2x;

      const canvas = document.createElement('canvas');
      canvas.width  = CANVAS;
      canvas.height = CANVAS;
      const ctx = canvas.getContext('2d')!;

      // circular clip
      ctx.beginPath();
      ctx.arc(CANVAS / 2, CANVAS / 2, CANVAS / 2, 0, Math.PI * 2);
      ctx.clip();

      ctx.drawImage(imgEl, drawX, drawY, drawW, drawH);

      const blob = await new Promise<Blob>((resolve, reject) => {
        canvas.toBlob(b => b ? resolve(b) : reject(new Error('Canvas export failed')), 'image/jpeg', 0.9);
      });

      const file = new File([blob], 'avatar.jpg', { type: 'image/jpeg' });
      await onSave(file);
    } catch { /* errors surfaced by onSave */ }
    setSaving(false);
  };

  const reset = () => {
    setImageSrc(null);
    setImgEl(null);
    setZoom(1);
    setOffset({ x: 0, y: 0 });
  };

  // ── Drop zone ────────────────────────────────────────────────────────────
  if (!imageSrc || !imgEl) {
    return (
      <div className="flex flex-col gap-3">
        <input ref={fileInputRef} type="file" accept="image/*" className="hidden" onChange={handleFileInput} />

        <div
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onDrop={handleDrop}
          onClick={() => fileInputRef.current?.click()}
          className={`relative flex flex-col items-center justify-center gap-2.5 rounded-xl border-2 border-dashed transition-all cursor-pointer py-6 px-4 select-none ${
            isDragOver
              ? 'border-primary bg-primary/8 scale-[1.01]'
              : 'border-border hover:border-primary/50 hover:bg-muted/40'
          }`}
        >
          {/* Current photo preview or icon */}
          {currentPhotoUrl && !currentImgError ? (
            <img
              src={currentPhotoUrl}
              alt="current"
              className="w-14 h-14 rounded-full object-cover ring-2 ring-border opacity-70 mb-0.5"
              onError={() => setCurrentImgError(true)}
            />
          ) : (
            <div className="w-14 h-14 rounded-full bg-muted flex items-center justify-center mb-0.5">
              <ImageIcon className="w-6 h-6 text-muted-foreground" />
            </div>
          )}

          <div className="text-center space-y-0.5">
            <p className="text-xs font-semibold text-foreground">
              {isDragOver ? 'Suelta para cargar' : 'Arrastra una foto aquí'}
            </p>
            <p className="text-[11px] text-muted-foreground">o haz clic para seleccionar</p>
          </div>

          <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-md border border-border bg-background text-xs text-muted-foreground mt-0.5">
            <Upload className="w-3 h-3" />
            Seleccionar imagen
          </div>

          <p className="text-[10px] text-muted-foreground/50">JPG, PNG, WEBP — máx. 10 MB</p>
        </div>
      </div>
    );
  }

  // ── Editor ───────────────────────────────────────────────────────────────
  const baseScale = Math.max(DISPLAY / imgEl.naturalWidth, DISPLAY / imgEl.naturalHeight);
  const totalScale = baseScale * zoom;
  const imgW = imgEl.naturalWidth  * totalScale;
  const imgH = imgEl.naturalHeight * totalScale;

  return (
    <div className="flex flex-col items-center gap-4">
      {/* Circular preview */}
      <div
        className="relative flex-shrink-0 overflow-hidden rounded-full ring-2 ring-border shadow-inner"
        style={{
          width: DISPLAY,
          height: DISPLAY,
          cursor: dragging ? 'grabbing' : 'grab',
          background: 'hsl(var(--muted))',
        }}
        onMouseDown={onMouseDown}
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={onTouchEnd}
      >
        <img
          src={imageSrc}
          alt="crop preview"
          draggable={false}
          style={{
            position: 'absolute',
            width: imgW,
            height: imgH,
            left: DISPLAY / 2 - imgW / 2 + offset.x,
            top:  DISPLAY / 2 - imgH / 2 + offset.y,
            userSelect: 'none',
            pointerEvents: 'none',
          }}
        />
        {/* Hint overlay */}
        <div className="absolute inset-0 rounded-full ring-1 ring-inset ring-border/40 pointer-events-none" />
      </div>

      <p className="text-[11px] text-muted-foreground -mt-1">
        Arrastra para reposicionar
      </p>

      {/* Zoom slider */}
      <div className="w-full space-y-2">
        <div className="flex items-center gap-2">
          <ZoomIn className="w-3.5 h-3.5 text-muted-foreground flex-shrink-0" />
          <Slider
            min={1} max={3} step={0.05}
            value={[zoom]}
            onValueChange={([v]) => setZoom(v)}
            className="flex-1"
          />
          <span className="text-[11px] font-mono text-muted-foreground w-8 text-right flex-shrink-0">
            {zoom.toFixed(1)}×
          </span>
        </div>
      </div>

      {/* Actions */}
      <div className="flex gap-2 w-full">
        <Button
          variant="ghost" size="sm" className="flex-1 gap-1.5"
          onClick={reset} disabled={saving}
        >
          <X className="w-3.5 h-3.5" />
          Cancelar
        </Button>
        <Button
          size="sm" className="flex-1 gap-1.5"
          onClick={handleSave} disabled={saving}
        >
          {saving ? (
            <>
              <span className="w-3 h-3 rounded-full border-2 border-primary-foreground/30 border-t-primary-foreground animate-spin flex-shrink-0" />
              Subiendo...
            </>
          ) : (
            'Guardar foto'
          )}
        </Button>
      </div>
    </div>
  );
}

import React, { useEffect, useState, useRef, forwardRef, useImperativeHandle, Fragment, useCallback, memo } from 'react';
import { createPortal } from 'react-dom';
import {
  Plus, MoreHorizontal, Pencil, RefreshCw, Trash2, Check, X,
  Bookmark, Save, Share2, Copy, ExternalLink, Link2, Unlink, GripVertical,
} from 'lucide-react';
import {
  getInternalViews, saveInternalView, deleteInternalView, syncExternalView, unlinkExternalView,
  reorderInternalViews,
  GetInternalViewsOutputType,
} from 'zite-endpoints-sdk';
import {
  DropdownMenu, DropdownMenuContent, DropdownMenuItem,
  DropdownMenuSeparator, DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { toast } from 'sonner';

type InternalView = GetInternalViewsOutputType['views'][0];

// Module-level cache: persist views across board switches and tab changes.
// Same pattern as colCache in useDynamicColumns — survives re-renders entirely.
const internalViewsCache = new Map<string, InternalView[]>();
const inFlightViews      = new Map<string, Promise<GetInternalViewsOutputType>>();

export interface InternalViewsBarHandle {
  notifyViewSaved: (viewId: string, filtersJson: string) => void;
}

interface Props {
  boardId: string;
  projectCode: string;
  boardName: string;
  activeViewId: string | null;
  onViewSelected: (view: InternalView | null) => void;
  currentFiltersJson: string;
  hasUnsavedChanges: boolean;
  onViewUpdated?: (view: InternalView) => void;
}

const EDGE_THRESHOLD = 120;
const MAX_SCROLL_SPEED = 15;
const MIN_DRAG_PX = 5;

export const InternalViewsBar = memo(forwardRef<InternalViewsBarHandle, Props>(function InternalViewsBar({
  boardId, projectCode, boardName,
  activeViewId, onViewSelected, currentFiltersJson,
  hasUnsavedChanges, onViewUpdated,
}: Props, ref) {
  const [views, setViews] = useState<InternalView[]>([]);
  const [loading, setLoading] = useState(false);

  // Inline new view input
  const [showNewInput, setShowNewInput] = useState(false);
  const [newName, setNewName] = useState('');
  const [saving, setSaving] = useState(false);
  const newInputRef = useRef<HTMLInputElement>(null);

  // Rename inline
  const [renamingId, setRenamingId] = useState<string | null>(null);
  const [renameVal, setRenameVal] = useState('');
  const renameInputRef = useRef<HTMLInputElement>(null);

  // Delete / share state
  const [deletingView, setDeletingView] = useState<InternalView | null>(null);
  const [syncingViewId, setSyncingViewId] = useState<string | null>(null);
  const [unlinkingViewId, setUnlinkingViewId] = useState<string | null>(null);
  const [shareDialogOpen, setShareDialogOpen] = useState(false);
  const [shareDialogUrl, setShareDialogUrl] = useState<string | null>(null);
  const [shareDialogIsNew, setShareDialogIsNew] = useState(false);
  const [copied, setCopied] = useState(false);

  // ── Drag state (for rendering) ─────────────────────────────────────────
  const [dragId, setDragId] = useState<string | null>(null);
  const [insertIndex, setInsertIndex] = useState(-1);
  const [ghostData, setGhostData] = useState<{ label: string; initX: number; initY: number } | null>(null);

  // ── Drag refs (stable, no re-render) ──────────────────────────────────
  const dragIdRef        = useRef<string | null>(null);
  const dragActiveRef    = useRef(false);          // true as soon as drag starts
  const thresholdMetRef  = useRef(false);          // true after 5px movement
  const startXRef        = useRef(0);
  const lastClientXRef   = useRef(0);
  const insertIndexRef   = useRef(-1);
  const scrollContainerRef = useRef<HTMLElement | null>(null);
  const scrollRafRef     = useRef<number | null>(null);
  const scrollSpeedRef   = useRef(0);
  const scrollDirRef     = useRef(0);
  const ghostRef         = useRef<HTMLDivElement | null>(null);
  const tabRefs          = useRef<Map<string, HTMLElement>>(new Map());
  const viewsRef         = useRef<InternalView[]>([]);
  viewsRef.current = views;

  useImperativeHandle(ref, () => ({
    notifyViewSaved: (viewId: string, filtersJson: string) => {
      setViews(prev => { const next = prev.map(v => v.id === viewId ? { ...v, filtersJson } : v); internalViewsCache.set(boardId, next); return next; });
    },
  }), []);

  const load = async () => {
    if (!boardId) return;

    // ── Instant cache hit: show stored views immediately, refresh silently ─
    if (internalViewsCache.has(boardId)) {
      setViews(internalViewsCache.get(boardId)!);
      const bid = boardId;
      getInternalViews({ boardId: bid })
        .then(res => { internalViewsCache.set(bid, res.views); setViews(res.views); })
        .catch(() => {});
      return;
    }

    // ── Dedup: if another caller already fetched this boardId, await it ───
    if (inFlightViews.has(boardId)) {
      try {
        const res = await inFlightViews.get(boardId)!;
        internalViewsCache.set(boardId, res.views);
        setViews(res.views);
      } catch { /* silent */ }
      return;
    }

    // ── First fetch: show spinner, populate cache, clear in-flight entry ─
    setLoading(true);
    const bid = boardId;
    const promise = getInternalViews({ boardId: bid });
    inFlightViews.set(bid, promise);
    try {
      const res = await promise;
      internalViewsCache.set(bid, res.views);
      setViews(res.views);
    } catch { /* silent */ } finally {
      inFlightViews.delete(bid);
      setLoading(false);
    }
  };

  useEffect(() => { setViews([]); load(); }, [boardId]); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => { if (showNewInput) setTimeout(() => newInputRef.current?.focus(), 50); }, [showNewInput]);
  useEffect(() => { if (renamingId) setTimeout(() => renameInputRef.current?.focus(), 50); }, [renamingId]);

  // ── Drag: compute insert index from cursor X ───────────────────────────
  function calcInsertIndex(clientX: number): number {
    const vs = viewsRef.current;
    for (let i = 0; i < vs.length; i++) {
      const el = tabRefs.current.get(vs[i].id);
      if (!el) continue;
      const r = el.getBoundingClientRect();
      if (clientX < r.left + r.width / 2) return i;
    }
    return vs.length;
  }

  // ── Drag: stop & cleanup ───────────────────────────────────────────────
  const stopDrag = useCallback(() => {
    dragActiveRef.current = false;
    thresholdMetRef.current = false;
    if (scrollRafRef.current !== null) {
      cancelAnimationFrame(scrollRafRef.current);
      scrollRafRef.current = null;
    }
    scrollSpeedRef.current = 0;
    scrollDirRef.current = 0;
    document.body.style.cursor = '';
  }, []);

  // ── Drag: RAF auto-scroll loop ─────────────────────────────────────────
  const startScrollLoop = useCallback(() => {
    if (scrollRafRef.current !== null) return;
    const tick = () => {
      if (!dragActiveRef.current) { scrollRafRef.current = null; return; }
      const container = scrollContainerRef.current;
      if (!container) { scrollRafRef.current = requestAnimationFrame(tick); return; }

      const rect = container.getBoundingClientRect();
      const x = lastClientXRef.current;
      const maxScroll = Math.max(0, container.scrollWidth - container.clientWidth);
      let targetDir = 0, targetSpeed = 0;

      if (x < rect.left + EDGE_THRESHOLD && container.scrollLeft > 0) {
        targetDir = -1;
        targetSpeed = Math.max(3, Math.round(((rect.left + EDGE_THRESHOLD - x) / EDGE_THRESHOLD) * MAX_SCROLL_SPEED));
      } else if (x > rect.right - EDGE_THRESHOLD && container.scrollLeft < maxScroll) {
        targetDir = 1;
        targetSpeed = Math.max(3, Math.round(((x - (rect.right - EDGE_THRESHOLD)) / EDGE_THRESHOLD) * MAX_SCROLL_SPEED));
      }

      if (targetDir !== 0) {
        scrollDirRef.current = targetDir;
        scrollSpeedRef.current += (targetSpeed - scrollSpeedRef.current) * 0.28;
      } else {
        scrollSpeedRef.current *= 0.72;
        if (scrollSpeedRef.current < 0.5) { scrollSpeedRef.current = 0; scrollDirRef.current = 0; }
      }

      if (scrollDirRef.current !== 0 && scrollSpeedRef.current > 0.5) {
        container.scrollLeft = Math.max(0, Math.min(maxScroll,
          container.scrollLeft + scrollDirRef.current * scrollSpeedRef.current));
      }
      scrollRafRef.current = requestAnimationFrame(tick);
    };
    scrollRafRef.current = requestAnimationFrame(tick);
  }, []);

  // ── Drag: stable listener wrappers ─────────────────────────────────────
  const pointerMoveHandlerRef = useRef<(e: PointerEvent) => void>(() => {});
  const pointerUpHandlerRef   = useRef<(e: PointerEvent) => void>(() => {});
  const stablePointerMove = useCallback((e: PointerEvent) => { pointerMoveHandlerRef.current(e); }, []);
  const stablePointerUp   = useCallback((e: PointerEvent) => { pointerUpHandlerRef.current(e); }, []);

  // ── Drag: pointer move ─────────────────────────────────────────────────
  const handlePointerMove = useCallback((e: PointerEvent) => {
    if (!dragActiveRef.current) return;
    lastClientXRef.current = e.clientX;

    // Move ghost imperatively (no re-render)
    if (ghostRef.current) {
      ghostRef.current.style.left = `${e.clientX + 12}px`;
      ghostRef.current.style.top  = `${e.clientY - 16}px`;
    }

    // Gate: only compute insertion after threshold
    if (!thresholdMetRef.current) {
      if (Math.abs(e.clientX - startXRef.current) < MIN_DRAG_PX) return;
      thresholdMetRef.current = true;
      document.body.style.cursor = 'grabbing';
    }

    const newIdx = calcInsertIndex(e.clientX);
    if (newIdx !== insertIndexRef.current) {
      insertIndexRef.current = newIdx;
      setInsertIndex(newIdx);
    }
  }, []);

  // ── Drag: pointer up ───────────────────────────────────────────────────
  const handlePointerUp = useCallback(() => {
    window.removeEventListener('pointermove', stablePointerMove);
    window.removeEventListener('pointerup',   stablePointerUp);
    const did          = dragIdRef.current;
    const idx          = insertIndexRef.current;
    const wasActive    = thresholdMetRef.current;
    stopDrag();
    dragIdRef.current      = null;
    insertIndexRef.current = -1;
    setDragId(null);
    setInsertIndex(-1);
    setGhostData(null);
    if (did && wasActive && idx >= 0) handleReorder(did, idx);
  }, [stablePointerMove, stablePointerUp, stopDrag]); // eslint-disable-line react-hooks/exhaustive-deps

  pointerMoveHandlerRef.current = handlePointerMove;
  pointerUpHandlerRef.current   = handlePointerUp;

  // ── Drag: start ────────────────────────────────────────────────────────
  function startDrag(e: React.PointerEvent, viewId: string) {
    e.preventDefault();
    dragIdRef.current      = viewId;
    dragActiveRef.current  = true;
    thresholdMetRef.current = false;
    startXRef.current      = e.clientX;
    lastClientXRef.current = e.clientX;
    insertIndexRef.current = viewsRef.current.findIndex(v => v.id === viewId);

    setDragId(viewId);

    const view = viewsRef.current.find(v => v.id === viewId);
    setGhostData({ label: view?.viewName ?? '', initX: e.clientX + 12, initY: e.clientY - 16 });

    // Find horizontal scroll container
    let el: HTMLElement | null = e.currentTarget as HTMLElement;
    while (el) {
      const ox = window.getComputedStyle(el).overflowX;
      if (el.scrollWidth > el.clientWidth && (ox === 'auto' || ox === 'scroll')) {
        scrollContainerRef.current = el;
        break;
      }
      el = el.parentElement;
    }

    window.addEventListener('pointermove', stablePointerMove);
    window.addEventListener('pointerup',   stablePointerUp);
    startScrollLoop();
  }

  // ── Drag: reorder ──────────────────────────────────────────────────────
  function handleReorder(draggingId: string, insertIdx: number) {
    const vs = viewsRef.current;
    const dragIdx = vs.findIndex(v => v.id === draggingId);
    if (dragIdx === -1 || dragIdx === insertIdx || dragIdx + 1 === insertIdx) return;

    const draggingView = vs[dragIdx];
    const without = vs.filter(v => v.id !== draggingId);
    const adjusted = dragIdx < insertIdx ? insertIdx - 1 : insertIdx;
    const newViews = [...without.slice(0, adjusted), draggingView, ...without.slice(adjusted)];

    setViews(newViews);
    internalViewsCache.set(boardId, newViews);
    reorderInternalViews({
      viewOrders: newViews.map((v, i) => ({ id: v.id, order: i })),
    }).catch(() => toast.error('Error al guardar el orden'));
  }

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      stopDrag();
      window.removeEventListener('pointermove', stablePointerMove);
      window.removeEventListener('pointerup',   stablePointerUp);
    };
  }, [stablePointerMove, stablePointerUp, stopDrag]);

  // ── View handlers ──────────────────────────────────────────────────────

  const handleSaveNew = async () => {
    const name = newName.trim();
    if (!name) return;
    setSaving(true);
    const emptyFiltersJson = JSON.stringify({ filterRules: [], filterMode: 'and', columnFilters: {}, hiddenColumns: [], sortColumn: null, sortDirection: 'asc' });
    try {
      const res = await saveInternalView({ viewName: name, boardId, projectCode, boardName, filtersJson: emptyFiltersJson });
      const newView: InternalView = { id: res.id, viewName: res.viewName, filtersJson: emptyFiltersJson };
      setViews(prev => { const next = [...prev, newView]; internalViewsCache.set(boardId, next); return next; });
      setNewName(''); setShowNewInput(false);
      onViewSelected(newView);
      toast.success(`Vista "${name}" guardada`);
    } catch { toast.error('Error al guardar la vista'); }
    setSaving(false);
  };

  const handleUpdateFilters = async (view: InternalView) => {
    try {
      await saveInternalView({ id: view.id, viewName: view.viewName, boardId, projectCode, boardName, filtersJson: currentFiltersJson });
      const updatedView = { ...view, filtersJson: currentFiltersJson };
      setViews(prev => { const next = prev.map(v => v.id === view.id ? updatedView : v); internalViewsCache.set(boardId, next); return next; });
      onViewUpdated?.(updatedView);
      toast.success('Vista guardada');
    } catch { toast.error('Error al actualizar la vista'); }
  };

  const handleRename = async (view: InternalView) => {
    const name = renameVal.trim();
    if (!name || name === view.viewName) { setRenamingId(null); return; }
    try {
      await saveInternalView({ id: view.id, viewName: name, boardId, projectCode, boardName, filtersJson: view.filtersJson });
      setViews(prev => { const next = prev.map(v => v.id === view.id ? { ...v, viewName: name } : v); internalViewsCache.set(boardId, next); return next; });
      if (activeViewId === view.id) onViewSelected({ ...view, viewName: name });
      toast.success('Vista renombrada');
    } catch { toast.error('Error al renombrar'); }
    setRenamingId(null);
  };

  const handleDelete = async () => {
    if (!deletingView) return;
    try {
      await deleteInternalView({ id: deletingView.id });
      setViews(prev => { const next = prev.filter(v => v.id !== deletingView.id); internalViewsCache.set(boardId, next); return next; });
      if (activeViewId === deletingView.id) onViewSelected(null);
      toast.success('Vista eliminada');
    } catch { toast.error('Error al eliminar la vista'); }
    setDeletingView(null);
  };

  const handleSyncExternal = async (view: InternalView) => {
    setSyncingViewId(view.id);
    try {
      const res = await syncExternalView({ internalViewId: view.id, viewName: view.viewName, boardId, projectCode, boardName });
      setViews(prev => { const next = prev.map(v => v.id === view.id ? { ...v, sharedToken: res.sharedToken, sharedUrl: res.shareUrl } : v); internalViewsCache.set(boardId, next); return next; });
      setShareDialogUrl(res.shareUrl); setShareDialogIsNew(res.isNew); setShareDialogOpen(true); setCopied(false);
      await navigator.clipboard.writeText(res.shareUrl);
      setCopied(true); setTimeout(() => setCopied(false), 2000);
      toast.success(res.isNew ? 'Vista externa creada — link copiado' : 'Vista externa actualizada — link copiado');
    } catch { toast.error('Error al sincronizar la vista externa'); }
    setSyncingViewId(null);
  };

  const handleUnlinkExternal = async (view: InternalView) => {
    setUnlinkingViewId(view.id);
    try {
      await unlinkExternalView({ internalViewId: view.id });
      setViews(prev => { const next = prev.map(v => v.id === view.id ? { ...v, sharedToken: undefined, sharedUrl: undefined } : v); internalViewsCache.set(boardId, next); return next; });
      toast.success('Link externo desactivado');
    } catch { toast.error('Error al desactivar el link externo'); }
    setUnlinkingViewId(null);
  };

  const handleQuickCopy = async (view: InternalView) => {
    if (!view.sharedUrl) return;
    await navigator.clipboard.writeText(view.sharedUrl);
    toast.success('Link copiado al portapapeles');
  };

  const handleCopyDialogUrl = async () => {
    if (!shareDialogUrl) return;
    await navigator.clipboard.writeText(shareDialogUrl);
    setCopied(true); setTimeout(() => setCopied(false), 2000);
  };

  if (!boardId) return null;

  const tabCls = (isActive: boolean) =>
    `flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-md transition-all whitespace-nowrap border ${
      isActive
        ? 'bg-primary text-primary-foreground border-primary shadow-sm'
        : 'bg-card text-muted-foreground border-border/50 hover:text-foreground hover:border-border hover:bg-muted/50'
    }`;

  return (
    <>
      <div className="flex items-center gap-1.5 px-6 py-2 bg-muted/20 border-b border-border/40 overflow-x-auto flex-shrink-0">

        {/* "Todos" tab */}
        <button className={tabCls(activeViewId === null)} onClick={() => onViewSelected(null)}>
          Todos
        </button>

        {/* View tabs */}
        {views.map((view, i) => (
          <Fragment key={view.id}>
            {/* Insertion indicator before this tab */}
            {dragId && insertIndex === i && (
              <div className="relative flex-shrink-0 mx-0.5 flex flex-col items-center" style={{ zIndex: 50 }}>
                <div className="w-0 h-0" style={{
                  borderLeft: '5px solid transparent',
                  borderRight: '5px solid transparent',
                  borderTop: '6px solid hsl(var(--primary))',
                }} />
                <div
                  className="w-[3px] h-5 bg-primary rounded-full"
                  style={{ boxShadow: '0 0 8px 3px hsl(var(--primary)/0.5)' }}
                />
              </div>
            )}

            <div className="flex items-center flex-shrink-0">
              {renamingId === view.id ? (
                <div className="flex items-center gap-1 px-2 py-1 rounded-md border border-primary bg-card">
                  <input
                    ref={renameInputRef}
                    value={renameVal}
                    onChange={e => setRenameVal(e.target.value)}
                    onKeyDown={e => {
                      if (e.key === 'Enter') handleRename(view);
                      if (e.key === 'Escape') setRenamingId(null);
                    }}
                    className="text-xs bg-transparent outline-none w-28 text-foreground"
                  />
                  <button onClick={() => handleRename(view)} className="text-primary hover:opacity-70">
                    <Check className="w-3 h-3" />
                  </button>
                  <button onClick={() => setRenamingId(null)} className="text-muted-foreground hover:opacity-70">
                    <X className="w-3 h-3" />
                  </button>
                </div>
              ) : (
                <div
                  ref={el => { if (el) tabRefs.current.set(view.id, el); else tabRefs.current.delete(view.id); }}
                  className={`flex items-center gap-0 group/tab rounded-md overflow-hidden border transition-all select-none ${
                    activeViewId === view.id
                      ? 'bg-primary text-primary-foreground border-primary shadow-sm'
                      : 'bg-card text-muted-foreground border-border/50 hover:border-border hover:bg-muted/50'
                  } ${dragId === view.id ? 'opacity-30' : ''}`}
                >
                  {/* Grip handle */}
                  <button
