    if (!date) return;
    setDateOpen(false);
    const newEndDate = format(date, 'yyyy-MM-dd');
    setSavingDate(true);
    try {
      await updateDashboardTask({ taskId: task.id, newEndDate });
      onUpdate(task.id, { endDate: newEndDate });
    } catch { /* ignore */ } finally {
      setSavingDate(false);
