                  <div className="flex-1 min-w-0">
                    <div className="text-sm font-medium truncate group-hover:text-primary transition-colors">
                      {t.taskName}
                    </div>
                    {t.projectCode && (
                      <div className="text-xs text-muted-foreground">{t.projectCode}</div>
                    )}
