import { useState, useEffect, useMemo } from 'react';
import { useAuth } from 'zite-auth-sdk';
import { getDeals, getCommercialViews, saveCommercialView, backfillExchangeRates, GetDealsOutputType, GetCommercialViewsOutputType } from 'zite-endpoints-sdk';
import { BarChart2, Printer, RefreshCcw } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Skeleton } from '@/components/ui/skeleton';
import { toast } from 'sonner';
import { DashboardFilters, DateReference, WidgetConfig, SavedView } from '@/lib/commercial-dashboard/types';
import { DEFAULT_FILTERS, DEFAULT_DATE_REFERENCE, DEFAULT_WIDGETS } from '@/lib/commercial-dashboard/constants';
import { applyFilters } from '@/lib/commercial-dashboard/filters';
import KpiCardsRow from '@/components/commercial-dashboard/KpiCardsRow';
import CommercialDashboardFilters from '@/components/commercial-dashboard/CommercialDashboardFilters';
import DashboardWidgetGrid from '@/components/commercial-dashboard/DashboardWidgetGrid';
import SavedViewsDropdown from '@/components/commercial-dashboard/SavedViewsDropdown';

type Deal = GetDealsOutputType['deals'][0];
type ViewOut = GetCommercialViewsOutputType['views'][0];

function toSavedView(v: ViewOut): SavedView {
  return { dbId: v.dbId, viewId: v.viewId, viewName: v.viewName, isDefault: v.isDefault, isShared: v.isShared, filtersJson: v.filtersJson, widgetsJson: v.widgetsJson, dateReference: v.dateReference as DateReference, sortOrder: v.sortOrder };
}

function parseWidgets(json: string): WidgetConfig[] {
  try { const p = JSON.parse(json); if (Array.isArray(p)) return p; } catch {}
  return DEFAULT_WIDGETS;
}

function parseFilters(json: string): DashboardFilters {
  try { const p = JSON.parse(json); if (p && typeof p === 'object') return { ...DEFAULT_FILTERS, ...p }; } catch {}
  return DEFAULT_FILTERS;
}

export default function CommercialDashboardPage() {
  const { user, isLoading: authLoading, loginWithRedirect } = useAuth();
  const [deals, setDeals] = useState<Deal[]>([]);
  const [views, setViews] = useState<SavedView[]>([]);
  const [loading, setLoading] = useState(true);
  const [backfilling, setBackfilling] = useState(false);
  const [activeViewId, setActiveViewId] = useState<string | null>(null);
  const [filters, setFilters] = useState<DashboardFilters>(DEFAULT_FILTERS);
  const [dateRef, setDateRef] = useState<DateReference>(DEFAULT_DATE_REFERENCE);
  const [widgets, setWidgets] = useState<WidgetConfig[]>(DEFAULT_WIDGETS);

  useEffect(() => {
    if (!authLoading && !user) loginWithRedirect({ redirectUrl: window.location.href });
    if (!authLoading && user) loadData();
  }, [authLoading, user]);

  async function runBackfill(silent = false) {
    setBackfilling(true);
    try {
      const res = await backfillExchangeRates({});
      if (res.updated > 0) {
        const refreshed = await getDeals({});
        setDeals(refreshed.deals);
        if (!silent) toast.success(`✓ Tipos de cambio actualizados (${res.updated} deals)`);
      } else if (!silent) {
        toast.info('Todos los deals ya tienen tipo de cambio');
      }
    } catch {
      if (!silent) toast.error('Error al actualizar tipos de cambio');
    } finally {
      setBackfilling(false);
    }
  }

  async function loadData() {
    setLoading(true);
    try {
      const [d, v] = await Promise.all([getDeals({}), getCommercialViews({})]);
      setDeals(d.deals);
      const parsed = v.views.map(toSavedView);
      setViews(parsed);
      const def = parsed.find(x => x.isDefault) ?? parsed[0] ?? null;
      if (def) applyView(def);

      // Auto-backfill if there are USD deals missing exchangeRate
      const hasMissing = d.deals.some(deal => deal.currency?.includes('USD') && !deal.exchangeRate);
      if (hasMissing) {
        // Run silently in background
        setTimeout(() => runBackfill(true), 100);
      }
    } catch { toast.error('Error al cargar el dashboard'); }
    finally { setLoading(false); }
  }

  async function saveCurrentView() {
    const activeView = views.find(v => v.viewId === activeViewId);
    if (!activeView) { toast.info('Selecciona una vista para guardar'); return; }
    try {
      await saveCommercialView({
        viewId: activeView.viewId,
        viewName: activeView.viewName,
        filtersJson: JSON.stringify(filters),
        widgetsJson: JSON.stringify(widgets),
        dateReference: dateRef,
        isDefault: activeView.isDefault,
        isShared: activeView.isShared,
        sortOrder: activeView.sortOrder,
      });
      setViews(vs => vs.map(v => v.viewId === activeView.viewId
        ? { ...v, filtersJson: JSON.stringify(filters), widgetsJson: JSON.stringify(widgets), dateReference: dateRef }
        : v
      ));
      toast.success('Vista guardada');
    } catch { toast.error('Error al guardar la vista'); }
  }

  function applyView(v: SavedView) {
    setActiveViewId(v.viewId);
    setFilters(parseFilters(v.filtersJson));
    setDateRef(v.dateReference);
    setWidgets(parseWidgets(v.widgetsJson));
  }

  const filteredDeals = useMemo(() => applyFilters(deals, filters, dateRef), [deals, filters, dateRef]);

  if (authLoading || (loading && !deals.length)) {
    return (
      <div className="p-6 space-y-5">
        <Skeleton className="h-8 w-64" />
        <div className="grid grid-cols-2 sm:grid-cols-5 gap-3">{Array.from({ length: 5 }).map((_, i) => <Skeleton key={i} className="h-24 rounded-xl" />)}</div>
        <div className="grid grid-cols-2 gap-4">{Array.from({ length: 4 }).map((_, i) => <Skeleton key={i} className="h-64 rounded-xl" />)}</div>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-5 print:p-3">
      <div className="flex items-start justify-between gap-4 flex-wrap">
        <div>
          <h2 className="text-lg font-bold flex items-center gap-2">
            <BarChart2 className="w-5 h-5 text-primary" /> Dashboard Comercial
          </h2>
          <p className="text-sm text-muted-foreground">
            {filteredDeals.length} de {deals.length} deals · {filteredDeals.filter(d => d.phase === 'Ganado').length} ganados
          </p>
        </div>
        <div className="flex items-center gap-2 flex-wrap print:hidden">
          <SavedViewsDropdown
            views={views} activeViewId={activeViewId}
            currentFiltersJson={JSON.stringify(filters)}
            currentWidgetsJson={JSON.stringify(widgets)}
            currentDateRef={dateRef}
            onSelectView={applyView}
            onViewsChange={setViews}
          />
          <Button variant="ghost" size="sm" className="gap-1.5" disabled={backfilling} onClick={() => runBackfill(false)}>
            <RefreshCcw className={`w-4 h-4 ${backfilling ? 'animate-spin' : ''}`} /> Actualizar TC
          </Button>
          <Button variant="ghost" size="sm" className="gap-1.5" onClick={() => window.print()}>
            <Printer className="w-4 h-4" /> Imprimir
          </Button>
        </div>
      </div>

      <div className="print:hidden">
        <CommercialDashboardFilters filters={filters} dateRef={dateRef} deals={deals} onFiltersChange={setFilters} onDateRefChange={setDateRef} />
      </div>

      <KpiCardsRow allDeals={deals} filters={filters} dateRef={dateRef} />

      <DashboardWidgetGrid widgets={widgets} deals={filteredDeals} dateRef={dateRef} onWidgetsChange={setWidgets} onSaveRequested={saveCurrentView} />
    </div>
  );
}

import { z } from 'zod';
import { createEndpoint, Cotizaciones, Deals } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Approve all included cotizaciones for a deal and update its quoted cost',
  inputSchema: z.object({ dealId: z.string() }),
  outputSchema: z.object({ success: z.boolean(), approvedCount: z.number(), totalCost: z.number() }),
  execute: async ({ input }) => {
    const result = await Cotizaciones.findAll({
      filters: { deal: { contains: input.dealId } },
    });

    const included = result.records.filter(c => {
      const ids = Array.isArray(c.deal) ? c.deal : c.deal ? [c.deal] : [];
      return ids.includes(input.dealId) && c.included === true;
    });

    await Promise.all(included.map(c =>
      Cotizaciones.update({ id: c.id, record: { status: 'Aprobada' } })
    ));

    const totalCost = included.reduce((sum, c) => sum + (c.clientPrice ?? c.totalCost ?? 0), 0);

    await Deals.update({
      id: input.dealId,
      record: { quotedCost: totalCost, phase: 'Ganado' },
    });

    return { success: true, approvedCount: included.length, totalCost };
  },
});

import { z } from 'zod';
import { createEndpoint, Projects, Deals, Cotizaciones, CotizacionLineItems, PurchaseOrders, PurchaseOrdersRecordType, CotizacionLineItemsRecordType, CotizacionesRecordType } from 'zite-integrations-backend-sdk';

const RUBROS = ['Reclutamiento e incentivos', 'Moderación', 'Management', 'Logística y operación', 'Back office'] as const;

const RUBRO_TO_OC: Record<string, string> = {
  'Reclutamiento e incentivos': 'Reclutamiento e Incentivos',
  'Moderación': 'Moderaciones',
  'Management': 'Management',
  'Logística y operación': 'Logística',
  'Back office': 'Otros',
};

const rubroRow = z.object({
  rubro: z.string(),
  cotizado: z.number(),
  costoConMarkup: z.number(),
  precioCliente: z.number(),
  gastado: z.number(),
  markUpInicial: z.number(),
  markUpFinal: z.number(),
  diferenciaTotalMxn: z.number(),
  revenueInicial: z.number().nullable(),
  revenueFinal: z.number().nullable(),
});

const totalsSchema = z.object({
  cotizado: z.number(),
  costoConMarkup: z.number(),
  precioCliente: z.number(),
  gastado: z.number(),
  markUpInicial: z.number(),
  markUpFinal: z.number(),
  diferenciaTotalMxn: z.number(),
  revenueInicial: z.number().nullable(),
  revenueFinal: z.number().nullable(),
});

const projectAnalysisSchema = z.object({
  project: z.object({
    id: z.string(),
    projectCode: z.string().optional(),
    fullName: z.string().optional(),
    status: z.string().optional(),
    dealId: z.string().optional(),
  }),
  deal: z.object({
    id: z.string(),
    dealName: z.string(),
    clientPrice: z.number().nullable(),
    currency: z.string().optional(),
  }).nullable(),
  byRubro: z.array(rubroRow),
  totals: totalsSchema,
});

function makeTotals(cotizado: number, costoConMarkup: number, precioCliente: number, gastado: number) {
  const markUpInicial = costoConMarkup - cotizado;
  const markUpFinal = precioCliente - gastado;
  const diferenciaTotalMxn = markUpFinal - markUpInicial;
  return {
    cotizado, costoConMarkup, precioCliente, gastado,
    markUpInicial, markUpFinal, diferenciaTotalMxn,
    revenueInicial: precioCliente > 0 ? (markUpInicial / precioCliente) * 100 : null,
    revenueFinal: precioCliente > 0 ? (markUpFinal / precioCliente) * 100 : null,
  };
}

/** Fetch ALL PurchaseOrders using pagination (2000 per page) */
async function fetchAllPOs(): Promise<PurchaseOrdersRecordType[]> {
  const all: PurchaseOrdersRecordType[] = [];
  let offset = 0;
  while (true) {
    const result = await PurchaseOrders.findAll({ limit: 2000, offset });
    all.push(...result.records);
    if (!result.hasMore || result.records.length === 0) break;
    offset += result.records.length;
  }
  return all;
}

/** Fetch ALL Cotizaciones using pagination (2000 per page) */
async function fetchAllCotizaciones(): Promise<CotizacionesRecordType[]> {
  const all: CotizacionesRecordType[] = [];
  let offset = 0;
  while (true) {
    const result = await Cotizaciones.findAll({ limit: 2000, offset });
    all.push(...result.records);
    if (!result.hasMore || result.records.length === 0) break;
    offset += result.records.length;
  }
  return all;
}

/** Fetch line items by IDs using findAll with id filter (avoids per-record findOne calls) */
async function fetchLineItemsByIds(ids: string[]): Promise<CotizacionLineItemsRecordType[]> {
  if (ids.length === 0) return [];
  const results: CotizacionLineItemsRecordType[] = [];
  const BATCH = 100;
  for (let i = 0; i < ids.length; i += BATCH) {
    const batch = ids.slice(i, i + BATCH);
    const { records } = await CotizacionLineItems.findAll({
      filters: { id: { in: batch } },
      limit: BATCH,
    });
    results.push(...records);
  }
  return results;
}

export default createEndpoint({
  authenticated: true,
  description: 'Batch P&L analysis for multiple projects — optimized with single bulk fetches',
  inputSchema: z.object({
    projectIds: z.array(z.string()).optional(),
  }),
  outputSchema: z.object({
    projects: z.array(projectAnalysisSchema),
    grandTotals: totalsSchema,
    dealsList: z.array(z.object({ id: z.string(), dealName: z.string(), clientPrice: z.number().nullable() })),
  }),
  execute: async ({ input }) => {
    const [{ records: allProjects }, allPos, { records: allDeals }, allCotizaciones] = await Promise.all([
      Projects.findAll({ limit: 500 }),
      fetchAllPOs(),
      Deals.findAll({ limit: 500 }),
      fetchAllCotizaciones(),
    ]);

    const projectsToAnalyze = input.projectIds && input.projectIds.length > 0
      ? allProjects.filter(p => input.projectIds!.includes(p.id))
      : allProjects;

    const EXCLUDED = new Set(['Borrador', 'Cancelada']);

    // Gastado by projectCode → ocCategory → amount
    const gastadoMap: Record<string, Record<string, number>> = {};
    for (const po of allPos) {
      if (EXCLUDED.has(po.status ?? '') || !po.projectCode) continue;
      const cat = po.category ?? 'Otros';
      if (!gastadoMap[po.projectCode]) gastadoMap[po.projectCode] = {};
      gastadoMap[po.projectCode][cat] = (gastadoMap[po.projectCode][cat] ?? 0) + (po.totalAmount ?? 0);
    }

    const dealsById: Record<string, typeof allDeals[0]> = {};
    for (const d of allDeals) dealsById[d.id] = d;

    const cotizByDeal: Record<string, typeof allCotizaciones> = {};
    for (const c of allCotizaciones) {
      const dealId = Array.isArray(c.deal) ? c.deal[0] : c.deal;
      if (dealId) { (cotizByDeal[dealId] ??= []).push(c); }
    }
    for (const d of allDeals) {
      const cotizIds = Array.isArray(d.cotizaciones)
        ? d.cotizaciones
        : d.cotizaciones ? [d.cotizaciones] : [];
      for (const cid of cotizIds) {
        const cot = allCotizaciones.find(c => c.id === cid);
        if (cot && !(cotizByDeal[d.id] ?? []).some(c => c.id === cid)) {
          (cotizByDeal[d.id] ??= []).push(cot);
        }
      }
    }

    const relevantDealIds = new Set<string>();
    for (const project of projectsToAnalyze) {
      const dealId = Array.isArray(project.dealVinculado) ? project.dealVinculado[0] : project.dealVinculado;
      if (dealId) relevantDealIds.add(dealId);
    }

    const liIdSet = new Set<string>();
    const relevantCotizIds = new Set<string>();
    for (const dealId of relevantDealIds) {
      for (const cot of (cotizByDeal[dealId] ?? []).filter(c => c.included !== false)) {
        relevantCotizIds.add(cot.id);
        const liIds = Array.isArray(cot.cotizacionLineItems)
          ? cot.cotizacionLineItems
          : cot.cotizacionLineItems ? [cot.cotizacionLineItems] : [];
        for (const id of liIds) liIdSet.add(id as string);
      }
    }

    const allLineItems = await fetchLineItemsByIds(Array.from(liIdSet));

    const lineItemById: Record<string, CotizacionLineItemsRecordType> = {};
    for (const li of allLineItems) lineItemById[li.id] = li;

    const lisByCotiz: Record<string, CotizacionLineItemsRecordType[]> = {};
    for (const cotId of relevantCotizIds) {
      const cot = allCotizaciones.find(c => c.id === cotId);
      if (!cot) continue;
      const liIds = Array.isArray(cot.cotizacionLineItems)
        ? cot.cotizacionLineItems
        : cot.cotizacionLineItems ? [cot.cotizacionLineItems] : [];
      lisByCotiz[cotId] = (liIds as string[]).map(id => lineItemById[id]).filter(Boolean);
    }

    const projectAnalyses = projectsToAnalyze.map(project => {
      const dealId = Array.isArray(project.dealVinculado) ? project.dealVinculado[0] : project.dealVinculado ?? undefined;
      const gastadoByCat = project.projectCode ? (gastadoMap[project.projectCode] ?? {}) : {};

      // rubroAgg: cotizado = base cost, costoConMarkup = finalPrice (with markup)
      const rubroAgg: Record<string, { cotizado: number; costoConMarkup: number }> = {};
      let deal: { id: string; dealName: string; clientPrice: number | null; currency?: string } | null = null;

      if (dealId) {
        const dr = dealsById[dealId];
        if (dr) deal = { id: dr.id, dealName: dr.dealName ?? '', clientPrice: dr.clientPrice ?? null, currency: dr.currency };

        for (const cot of (cotizByDeal[dealId] ?? []).filter(c => c.included !== false)) {
          for (const li of lisByCotiz[cot.id] ?? []) {
            const rubro = li.rubro ?? 'Back office';
            rubroAgg[rubro] ??= { cotizado: 0, costoConMarkup: 0 };
            rubroAgg[rubro].cotizado += (li.unitCost ?? 0) * (li.cantidad ?? 1) * (li.componentes ?? 1);
            rubroAgg[rubro].costoConMarkup += li.finalPrice ?? 0;
          }
        }
      }

      // The real client price comes from the deal
      const dealClientPrice = deal?.clientPrice ?? 0;

      // Total costoConMarkup across all rubros (used for proportional distribution of precioCliente)
      const totalMarkup = Object.values(rubroAgg).reduce((s, r) => s + r.costoConMarkup, 0);

      const hasLineItems = dealId
        ? (cotizByDeal[dealId] ?? []).filter(c => c.included !== false).some(c => (lisByCotiz[c.id] ?? []).length > 0)
        : false;

      // Fallback: no line items — distribute clientPrice proportionally if cotizado data exists
      if (!hasLineItems && dealClientPrice > 0) {
        const totCotizado = Object.values(rubroAgg).reduce((s, r) => s + r.cotizado, 0);
        if (totCotizado > 0) {
          for (const rubro of RUBROS) {
            const cotRubro = rubroAgg[rubro]?.cotizado ?? 0;
            if (cotRubro > 0) {
              rubroAgg[rubro] ??= { cotizado: 0, costoConMarkup: 0 };
              rubroAgg[rubro].costoConMarkup = (cotRubro / totCotizado) * dealClientPrice;
            }
          }
        } else {
          rubroAgg['Reclutamiento e incentivos'] ??= { cotizado: 0, costoConMarkup: 0 };
          rubroAgg['Reclutamiento e incentivos'].costoConMarkup = dealClientPrice;
        }
      }

      const byRubro = RUBROS.map(rubro => {
        const cotizado = rubroAgg[rubro]?.cotizado ?? 0;
        const costoConMarkup = rubroAgg[rubro]?.costoConMarkup ?? 0;
        const gastado = gastadoByCat[RUBRO_TO_OC[rubro]] ?? 0;

        // Distribute dealClientPrice proportionally by costoConMarkup weight
        const precioCliente = totalMarkup > 0
          ? (costoConMarkup / totalMarkup) * dealClientPrice
          : 0;

        const markUpInicial = costoConMarkup - cotizado;
        const markUpFinal = precioCliente - gastado;
        const diferenciaTotalMxn = markUpFinal - markUpInicial;
        return {
          rubro, cotizado, costoConMarkup, precioCliente, gastado,
          markUpInicial, markUpFinal, diferenciaTotalMxn,
          revenueInicial: precioCliente > 0 ? (markUpInicial / precioCliente) * 100 : null,
          revenueFinal: precioCliente > 0 ? (markUpFinal / precioCliente) * 100 : null,
        };
      });

      const totCot = byRubro.reduce((s, r) => s + r.cotizado, 0);
      const totMarkup = byRubro.reduce((s, r) => s + r.costoConMarkup, 0);
      const totGas = byRubro.reduce((s, r) => s + r.gastado, 0);

      return {
        project: { id: project.id, projectCode: project.projectCode, fullName: project.fullName, status: project.status, dealId },
        deal,
        byRubro,
        totals: makeTotals(totCot, totMarkup, dealClientPrice, totGas),
      };
    });

    const grandCot = projectAnalyses.reduce((s, p) => s + p.totals.cotizado, 0);
    const grandMarkup = projectAnalyses.reduce((s, p) => s + p.totals.costoConMarkup, 0);
    const grandPC = projectAnalyses.reduce((s, p) => s + p.totals.precioCliente, 0);
    const grandGas = projectAnalyses.reduce((s, p) => s + p.totals.gastado, 0);

    return {
      projects: projectAnalyses,
      grandTotals: makeTotals(grandCot, grandMarkup, grandPC, grandGas),
      dealsList: allDeals.map(d => ({ id: d.id, dealName: d.dealName ?? '', clientPrice: d.clientPrice ?? null })),
    };
  },
});

import React, { useState } from 'react';
import { SlidersHorizontal, Plus, X, Type, Hash, Calendar, ListFilter, Save } from 'lucide-react';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Checkbox } from '@/components/ui/checkbox';
import { ScrollArea } from '@/components/ui/scroll-area';

// ── Types ─────────────────────────────────────────────────────────────────────
export type FilterColumnType = 'text' | 'number' | 'date' | 'select';

export type FilterColumn = {
  key: string;
  label: string;
  type?: FilterColumnType;
  options?: string[];
};

export type FilterRule = {
  id: string;
  column: string;
  operator: string;
  value: string;
  value2?: string;
  selectedValues?: string[];
};

// ── Operators per type ────────────────────────────────────────────────────────
export const OPS: Record<FilterColumnType, { value: string; label: string }[]> = {
  text: [
    { value: 'contiene',    label: 'contiene' },
    { value: 'no_contiene', label: 'no contiene' },
    { value: 'igual_a',     label: 'es igual a' },
    { value: 'no_igual_a',  label: 'no es igual a' },
    { value: 'empieza_con', label: 'empieza con' },
    { value: 'termina_con', label: 'termina con' },
    { value: 'vacio',       label: 'está vacío' },
    { value: 'no_vacio',    label: 'no está vacío' },
  ],
  number: [
    { value: 'igual_a',     label: 'es igual a' },
    { value: 'no_igual_a',  label: 'no es igual a' },
    { value: 'mayor_que',   label: 'mayor que' },
    { value: 'menor_que',   label: 'menor que' },
    { value: 'mayor_igual', label: 'mayor o igual a' },
    { value: 'menor_igual', label: 'menor o igual a' },
    { value: 'entre',       label: 'entre' },
    { value: 'vacio',       label: 'está vacío' },
    { value: 'no_vacio',    label: 'no está vacío' },
  ],
  date: [
    { value: 'fecha_es',    label: 'es' },
    { value: 'antes_de',    label: 'es antes de' },
    { value: 'despues_de',  label: 'es después de' },
    { value: 'entre',       label: 'entre' },
    { value: 'esta_semana', label: 'esta semana' },
    { value: 'este_mes',    label: 'este mes' },
    { value: 'vacio',       label: 'está vacío' },
    { value: 'no_vacio',    label: 'no está vacío' },
  ],
  select: [
    { value: 'es',            label: 'es' },
    { value: 'no_es',         label: 'no es' },
    { value: 'es_alguno',     label: 'es alguno de' },
    { value: 'no_es_ninguno', label: 'no es ninguno de' },
    { value: 'vacio',         label: 'está vacío' },
    { value: 'no_vacio',      label: 'no está vacío' },
  ],
};

export const TYPE_ICONS: Record<FilterColumnType, React.ElementType> = {
  text: Type, number: Hash, date: Calendar, select: ListFilter,
};

export const NO_INPUT_OPS = new Set(['vacio', 'no_vacio', 'esta_semana', 'este_mes']);
const TEXT_FREE_OPS    = new Set(['contiene', 'no_contiene']);
const TEXT_SUGGEST_OPS = new Set(['igual_a', 'empieza_con', 'termina_con']);

// ── TextMultiCombobox ─────────────────────────────────────────────────────────
function TextMultiCombobox({ selected, onChange, suggestions }: {
  selected: string[];
  onChange: (vals: string[]) => void;
  suggestions: string[];
}) {
  const [search, setSearch] = useState('');

  const filtered = search.trim()
    ? suggestions.filter(s => s.toLowerCase().includes(search.toLowerCase()))
    : suggestions;

  const toggle = (opt: string, checked: boolean) =>
    onChange(checked ? [...selected, opt] : selected.filter(v => v !== opt));

  return (
    <div className="space-y-1.5">
      {/* Selected badges */}
      {selected.length > 0 && (
        <div className="flex flex-wrap gap-1">
          {selected.map(v => (
            <span
              key={v}
              className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-medium bg-primary text-primary-foreground"
            >
              {v}
              <button
                type="button"
                onClick={() => toggle(v, false)}
                className="hover:opacity-70 transition-opacity leading-none"
              >
                <X className="w-2.5 h-2.5" />
              </button>
            </span>
          ))}
        </div>
      )}

      {/* Search input */}
      <Input
        placeholder="Buscar valores..."
        className="h-8 text-xs"
        value={search}
        onChange={e => setSearch(e.target.value)}
      />

      {/* Checkbox list */}
      <div className="max-h-36 overflow-y-auto rounded-lg border border-border bg-card shadow-sm">
        {filtered.length === 0 ? (
          <p className="text-xs text-muted-foreground text-center py-3 italic">Sin resultados</p>
        ) : (
          filtered.map(opt => (
            <label
              key={opt}
              className="flex items-center gap-2 px-2.5 py-1.5 text-xs hover:bg-accent cursor-pointer transition-colors"
            >
              <Checkbox
                checked={selected.includes(opt)}
                onCheckedChange={ch => toggle(opt, !!ch)}
                className="h-3.5 w-3.5 flex-shrink-0"
              />
              <span className="truncate text-card-foreground font-medium">{opt}</span>
            </label>
          ))
        )}
      </div>
    </div>
  );
}

// ── TextFreeInput — free-text tag input for "contiene" / "no_contiene" ────────
function TextFreeInput({ selected, onChange }: {
  selected: string[];
  onChange: (vals: string[]) => void;
}) {
  const [input, setInput] = useState('');

  const addTag = (raw: string) => {
    const trimmed = raw.trim();
    if (trimmed && !selected.includes(trimmed)) {
      onChange([...selected, trimmed]);
    }
    setInput('');
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') { e.preventDefault(); addTag(input); }
    if (e.key === 'Backspace' && !input && selected.length > 0) {
      onChange(selected.slice(0, -1));
    }
  };

  const remove = (val: string) => onChange(selected.filter(v => v !== val));

  return (
    <div className="space-y-1.5">
      {selected.length > 0 && (
        <div className="flex flex-wrap gap-1">
          {selected.map(v => (
            <span
              key={v}
              className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-medium bg-primary text-primary-foreground"
            >
              {v}
              <button type="button" onClick={() => remove(v)} className="hover:opacity-70 transition-opacity leading-none">
                <X className="w-2.5 h-2.5" />
              </button>
            </span>
          ))}
        </div>
      )}
      <Input
        placeholder={selected.length === 0 ? 'Escribe una palabra y presiona Enter…' : 'Agregar otra palabra…'}
        className="h-8 text-xs"
        value={input}
        onChange={e => setInput(e.target.value)}
        onKeyDown={handleKeyDown}
      />
      <p className="text-[10px] text-muted-foreground leading-none">
        Presiona <kbd className="font-mono bg-muted px-1 rounded">Enter</kbd> para agregar · Backspace para borrar
      </p>
    </div>
  );
}

// ── FilterRuleRow (exported for reuse) ────────────────────────────────────────
export function FilterRuleRow({ rule, idx, columns, colUniqueValues, filterMode, onUpdate, onRemove }: {
  rule: FilterRule;
  idx: number;
  columns: FilterColumn[];
  colUniqueValues: (key: string) => string[];
  filterMode: 'and' | 'or';
  onUpdate: (patch: Partial<FilterRule>) => void;
  onRemove: () => void;
}) {
  const col = columns.find(c => c.key === rule.column);
  const colType: FilterColumnType = col?.type ?? 'text';
  const operators = OPS[colType];
  const rawOptions = col?.options?.length ? col.options : colUniqueValues(rule.column);
  const selectOptions = rawOptions.filter(Boolean);

  const handleColumnChange = (newKey: string) => {
    const newCol = columns.find(c => c.key === newKey);
    const newType: FilterColumnType = newCol?.type ?? 'text';
    onUpdate({ column: newKey, operator: OPS[newType][0].value, value: '', value2: '', selectedValues: [] });
  };

  const handleOperatorChange = (op: string) => {
    onUpdate({ operator: op, value: '', value2: '', selectedValues: [] });
  };

  const toggleVal = (opt: string, checked: boolean) => {
    const prev = rule.selectedValues ?? [];
    onUpdate({ selectedValues: checked ? [...prev, opt] : prev.filter(v => v !== opt) });
  };

  const noInput        = NO_INPUT_OPS.has(rule.operator);
  const isBetween      = rule.operator === 'entre';
  const isSelectSingle = colType === 'select' && ['es', 'no_es'].includes(rule.operator);
  const isSelectMulti  = colType === 'select' && ['es_alguno', 'no_es_ninguno'].includes(rule.operator);
  const isTextFree     = colType === 'text' && TEXT_FREE_OPS.has(rule.operator);
  const isTextSuggest  = colType === 'text' && TEXT_SUGGEST_OPS.has(rule.operator);
  const TypeIcon       = TYPE_ICONS[colType];
  const connectorLabel = idx === 0 ? 'DONDE' : filterMode === 'and' ? 'Y DONDE' : 'O DONDE';

  return (
    <div className="p-3 bg-card border border-border rounded-xl shadow-sm text-foreground">
      <div className="flex items-center justify-between mb-2.5">
        <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider">{connectorLabel}</span>
        <button onClick={onRemove} className="text-muted-foreground hover:text-destructive transition-colors rounded p-0.5">
          <X className="w-3.5 h-3.5" />
        </button>
      </div>

      <div className="space-y-1.5">
        {/* Column */}
        <Select value={rule.column} onValueChange={handleColumnChange}>
          <SelectTrigger className="h-8 text-xs">
            <div className="flex items-center gap-1.5 min-w-0 overflow-hidden">
              <TypeIcon className="w-3 h-3 text-muted-foreground flex-shrink-0" />
              <SelectValue placeholder="Elegir columna..." />
            </div>
          </SelectTrigger>
          <SelectContent>
            {columns.map(c => {
              const Icon = TYPE_ICONS[c.type ?? 'text'];
              return (
                <SelectItem key={c.key} value={c.key}>
                  <div className="flex items-center gap-1.5">
                    <Icon className="w-3 h-3 text-muted-foreground" />
                    {c.label}
                  </div>
                </SelectItem>
              );
            })}
          </SelectContent>
        </Select>

        {/* Operator */}
        <Select value={rule.operator} onValueChange={handleOperatorChange}>
          <SelectTrigger className="h-8 text-xs"><SelectValue /></SelectTrigger>
          <SelectContent>
            {operators.map(op => <SelectItem key={op.value} value={op.value}>{op.label}</SelectItem>)}
          </SelectContent>
        </Select>

        {/* Value input */}
        {!noInput && (
          isSelectSingle ? (
            <Select value={rule.value} onValueChange={v => onUpdate({ value: v })}>
              <SelectTrigger className="h-8 text-xs"><SelectValue placeholder="Elegir valor..." /></SelectTrigger>
              <SelectContent>
                {selectOptions.map(opt => <SelectItem key={opt} value={opt}>{opt}</SelectItem>)}
              </SelectContent>
            </Select>
          ) : isSelectMulti ? (
            <div className="max-h-52 overflow-y-auto border border-border rounded-lg p-1 bg-background">
              {selectOptions.length === 0
                ? <p className="text-xs text-muted-foreground text-center py-2 italic">Sin valores disponibles</p>
                : selectOptions.map(opt => (
                  <label key={opt} className="flex items-center gap-2 px-1.5 py-1 text-xs hover:bg-muted rounded cursor-pointer">
                    <Checkbox
                      checked={(rule.selectedValues ?? []).includes(opt)}
                      onCheckedChange={ch => toggleVal(opt, !!ch)}
                      className="h-3.5 w-3.5"
                    />
                    <span className="truncate">{opt}</span>
                  </label>
                ))
              }
            </div>
          ) : isTextFree ? (
            <TextFreeInput
              selected={rule.selectedValues ?? []}
              onChange={vals => onUpdate({ selectedValues: vals, value: vals[0] ?? '' })}
            />
          ) : isTextSuggest ? (
            <TextMultiCombobox
              selected={rule.selectedValues ?? []}
              onChange={vals => onUpdate({ selectedValues: vals, value: vals[0] ?? '' })}
              suggestions={selectOptions}
            />
          ) : colType === 'number' ? (
            isBetween ? (
              <div className="flex gap-1">
                <Input type="number" placeholder="Mín" className="h-8 text-xs" value={rule.value} onChange={e => onUpdate({ value: e.target.value })} />
                <Input type="number" placeholder="Máx" className="h-8 text-xs" value={rule.value2 ?? ''} onChange={e => onUpdate({ value2: e.target.value })} />
              </div>
            ) : (
              <Input type="number" placeholder="Valor..." className="h-8 text-xs" value={rule.value} onChange={e => onUpdate({ value: e.target.value })} />
            )
          ) : colType === 'date' ? (
            isBetween ? (
              <div className="flex gap-1">
                <Input type="date" className="h-8 text-xs" value={rule.value} onChange={e => onUpdate({ value: e.target.value })} />
                <Input type="date" className="h-8 text-xs" value={rule.value2 ?? ''} onChange={e => onUpdate({ value2: e.target.value })} />
              </div>
            ) : (
              <Input type="date" className="h-8 text-xs" value={rule.value} onChange={e => onUpdate({ value: e.target.value })} />
            )
          ) : (
            <Input placeholder="Valor..." className="h-8 text-xs" value={rule.value} onChange={e => onUpdate({ value: e.target.value })} />
          )
        )}
      </div>
    </div>
  );
}

// ── Shared popover style helpers ──────────────────────────────────────────────
const popoverBg  = 'hsl(var(--filter-popover-bg))';
const popoverFg  = 'hsl(var(--filter-popover-fg))';
const popoverBorder = 'hsl(var(--filter-popover-border))';
const popoverMuted  = 'hsl(var(--filter-popover-muted))';

// ── AdvancedFilterSheet — Popover flotante ────────────────────────────────────
interface Props {
  columns: FilterColumn[];
  rules: FilterRule[];
  onRulesChange: (rules: FilterRule[]) => void;
  filterMode: 'and' | 'or';
  onFilterModeChange: (mode: 'and' | 'or') => void;
  colUniqueValues: (key: string) => string[];
  activeFilterCount?: number;
  activeViewName?: string;
  onSaveToView?: () => void;
  columnFilters?: Record<string, Set<string>>;
  onClearColumnFilter?: (columnKey: string) => void;
  onClearAll?: () => void;
}

export function AdvancedFilterSheet({
  columns, rules, onRulesChange, filterMode, onFilterModeChange, colUniqueValues, activeFilterCount = 0,
  activeViewName, onSaveToView, columnFilters = {}, onClearColumnFilter, onClearAll,
}: Props) {
  const [open, setOpen] = useState(false);

  const addRule = () => {
    const first = columns[0];
    const t: FilterColumnType = first?.type ?? 'text';
    onRulesChange([...rules, {
      id: `r_${Date.now()}`,
      column: first?.key ?? '',
      operator: OPS[t][0].value,
      value: '',
      selectedValues: [],
    }]);
  };

  const update = (id: string, patch: Partial<FilterRule>) =>
    onRulesChange(rules.map(r => r.id === id ? { ...r, ...patch } : r));
  const remove = (id: string) => onRulesChange(rules.filter(r => r.id !== id));

  return (
    <>
      <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          size="sm"
          variant={rules.length > 0 ? 'default' : 'outline'}
          className="gap-1.5 h-8"
        >
          <SlidersHorizontal className="w-3.5 h-3.5" />
          Filtros
          {activeFilterCount > 0 && (
            <Badge variant="secondary" className="text-[10px] h-4 px-1.5 ml-0.5 bg-background/30 text-inherit">
              {activeFilterCount}
            </Badge>
          )}
        </Button>
      </PopoverTrigger>

      <PopoverContent
        className="w-[420px] p-0 flex flex-col shadow-2xl"
        align="start"
        side="bottom"
        sideOffset={6}
        style={{
          maxHeight: '520px',
          backgroundColor: popoverBg,
          color: popoverFg,
          borderColor: popoverBorder,
        }}
      >
        {/* Header */}
        <div
          className="px-4 py-3 border-b flex items-center justify-between flex-shrink-0"
          style={{ borderColor: popoverBorder }}
        >
          <div className="flex items-center gap-2">
            <SlidersHorizontal className="w-4 h-4" style={{ color: popoverMuted }} />
            <span className="text-sm font-semibold" style={{ color: popoverFg }}>Filtros avanzados</span>
            {rules.length > 0 && (
              <Badge variant="secondary" className="text-xs ml-1 bg-white/10 text-white border-white/20">
                {rules.length}
              </Badge>
            )}
          </div>
          <button
            onClick={() => setOpen(false)}
            className="transition-colors p-0.5 rounded hover:bg-white/10"
            style={{ color: popoverMuted }}
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* AND / OR toggle */}
        {rules.length >= 2 && (
          <div
            className="px-4 py-2 border-b flex items-center gap-2 flex-wrap flex-shrink-0"
            style={{ borderColor: popoverBorder }}
          >
            <span className="text-xs" style={{ color: popoverMuted }}>Mostrar registros que cumplan</span>
            <div className="flex items-center rounded-lg p-0.5 gap-0.5" style={{ backgroundColor: 'hsl(220 50% 10%)' }}>
              <button
                onClick={() => onFilterModeChange('and')}
                className="px-2.5 py-1 text-xs rounded-md transition-all"
                style={filterMode === 'and'
                  ? { backgroundColor: 'hsl(220 50% 28%)', color: popoverFg, fontWeight: 600 }
                  : { color: popoverMuted }}
              >
                todas
              </button>
              <button
                onClick={() => onFilterModeChange('or')}
                className="px-2.5 py-1 text-xs rounded-md transition-all"
                style={filterMode === 'or'
                  ? { backgroundColor: 'hsl(220 50% 28%)', color: popoverFg, fontWeight: 600 }
                  : { color: popoverMuted }}
              >
                cualquiera
              </button>
            </div>
            <span className="text-xs" style={{ color: popoverMuted }}>de las condiciones</span>
          </div>
        )}

        {/* Rules */}
        <div className="flex-1 overflow-y-auto px-4 py-3 space-y-3">
          {/* Column filters section */}
          {Object.entries(columnFilters).filter(([, vals]) => vals.size > 0).length > 0 && (
            <div>
              <p className="text-[10px] font-bold uppercase tracking-wider mb-2" style={{ color: popoverMuted }}>
                Filtros de columna
              </p>
              <div className="space-y-1.5">
                {Object.entries(columnFilters)
                  .filter(([, vals]) => vals.size > 0)
                  .map(([colKey, vals]) => {
                    const colLabel = columns.find(c => c.key === colKey)?.label ?? colKey;
                    return (
                      <div
                        key={colKey}
                        className="flex items-start gap-2 p-2.5 rounded-lg border"
                        style={{ backgroundColor: 'hsl(220 50% 14%)', borderColor: popoverBorder }}
                      >
                        <div className="flex-1 min-w-0">
                          <p className="text-[10px] font-semibold mb-1.5" style={{ color: popoverMuted }}>
                            {colLabel}
                          </p>
                          <div className="flex flex-wrap gap-1">
                            {[...vals].map(v => (
                              <span
                                key={v}
                                className="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-medium"
                                style={{ backgroundColor: 'hsl(220 50% 28%)', color: popoverFg }}
                              >
                                {v || '(vacío)'}
                              </span>
                            ))}
                          </div>
                        </div>
                        {onClearColumnFilter && (
                          <button
                            onClick={() => onClearColumnFilter(colKey)}
                            className="flex-shrink-0 mt-0.5 rounded p-0.5 hover:bg-white/10 transition-colors"
                            style={{ color: popoverMuted }}
                            title="Quitar filtro"
                          >
                            <X className="w-3.5 h-3.5" />
                          </button>
                        )}
                      </div>
                    );
                  })}
              </div>
            </div>
          )}

          {/* Advanced filter rules */}
          {rules.length === 0 && Object.values(columnFilters).every(s => s.size === 0) ? (
            <div className="flex flex-col items-center justify-center py-10 text-center">
              <SlidersHorizontal className="w-9 h-9 mb-3" style={{ color: `${popoverMuted}55` }} />
              <p className="text-sm font-semibold mb-1" style={{ color: popoverFg }}>Sin filtros activos</p>
              <p className="text-xs" style={{ color: popoverMuted }}>
                Agrega condiciones para filtrar registros de forma precisa
              </p>
            </div>
          ) : rules.length > 0 ? (
            <div className="space-y-3">
              {rules.map((rule, idx) => (
                <FilterRuleRow
                  key={rule.id}
                  rule={rule}
                  idx={idx}
                  columns={columns}
                  colUniqueValues={colUniqueValues}
                  filterMode={filterMode}
                  onUpdate={patch => update(rule.id, patch)}
                  onRemove={() => remove(rule.id)}
                />
              ))}
            </div>
          ) : null}
        </div>

        {/* Footer */}
        <div
          className="px-4 py-3 border-t space-y-2 flex-shrink-0"
          style={{ borderColor: popoverBorder }}
        >
          {onSaveToView && (
            <button
              onClick={onSaveToView}
              className="w-full flex items-center justify-center gap-1.5 h-8 text-xs font-semibold rounded-lg transition-all hover:opacity-90 active:scale-[0.98]"
              style={{ backgroundColor: 'hsl(220 50% 32%)', color: popoverFg, border: '1px solid hsl(220 50% 45%)' }}
            >
              <Save className="w-3 h-3 flex-shrink-0" />
              <span className="truncate">Guardar en vista «{activeViewName}»</span>
            </button>
          )}
          <button
            onClick={addRule}
            className="w-full flex items-center justify-center gap-1.5 h-8 text-sm rounded-lg border transition-colors hover:bg-white/10"
            style={{ borderColor: popoverBorder, color: popoverFg }}
          >
            <Plus className="w-3.5 h-3.5" /> Agregar condición
          </button>
          {activeFilterCount > 0 && (
            <button
              onClick={() => { if (onClearAll) { onClearAll(); setOpen(false); } else { onRulesChange([]); } }}
              className="w-full flex items-center justify-center h-8 text-xs rounded-lg transition-colors hover:bg-red-500/20"
              style={{ color: popoverMuted }}
            >
              Limpiar todos los filtros
            </button>
          )}
        </div>
      </PopoverContent>
      </Popover>
      {activeFilterCount > 0 && onClearAll && (
        <button
          onClick={onClearAll}
          className="flex items-center gap-1.5 px-2.5 py-1 bg-primary/10 text-primary text-xs rounded-lg font-medium border border-primary/20 hover:bg-destructive/10 hover:text-destructive hover:border-destructive/20 transition-colors whitespace-nowrap"
          title="Limpiar todos los filtros"
        >
          <span>{activeFilterCount} filtro{activeFilterCount !== 1 ? 's' : ''} activo{activeFilterCount !== 1 ? 's' : ''}</span>
          <X className="w-3 h-3" />
        </button>
      )}
    </>
  );
}

import { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import { Skeleton } from '@/components/ui/skeleton';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Loader2, CalendarDays, CheckSquare, Square, ChevronUp, ChevronDown } from 'lucide-react';
import { toast } from 'sonner';
import { getCalendarExcelColumns, sendCalendarToWebhook, GetCalendarExcelColumnsOutputType } from 'zite-endpoints-sdk';

type Column = GetCalendarExcelColumnsOutputType['columns'][0];

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  projectCode: string;
  calendarName: string;
  boardId?: string;
  projectFullName?: string;
  projectTematica?: string;
  onSuccess: (result: { status?: string; fileUrl?: string; eventCount: number; version?: string }) => void;
}

const COL_TYPE_LABELS: Record<string, string> = {
  datetime:     '📅 Fecha',
  date:         '📅 Fecha',
  time:         '🕐 Hora',
  numbers:      '🔢 Número',
  number:       '🔢 Número',
  text:         '📝 Texto',
  status:       '🏷️ Status',
  dropdown:     '▾ Select',
  people:       '👤 Persona',
  color_picker: '🎨 Color',
};

function colTypeLabel(type: string) {
  return COL_TYPE_LABELS[type] ?? type;
}

function buildFileName(fullName: string, tematica: string, docName: string, version: string): string {
  const parts = [fullName, tematica, docName].filter(Boolean);
  return `${parts.join(' - ')} - V${version || '?'}`;
}

export function CalendarExcelDialog({ open, onOpenChange, projectCode, calendarName, boardId, projectFullName = '', projectTematica = '', onSuccess }: Props) {
  const [loadingCols, setLoadingCols] = useState(false);
  const [columns, setColumns]         = useState<Column[]>([]);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [sending, setSending]         = useState(false);
  const [nextVersion, setNextVersion] = useState<number | null>(null);
  const [versionInput, setVersionInput] = useState('');

  useEffect(() => {
    if (!open || !projectCode || (!calendarName && !boardId)) return;
    setLoadingCols(true);
    getCalendarExcelColumns({ projectCode, calendarName, ...(boardId ? { boardId } : {}) })
      .then(res => {
        setColumns(res.columns);
        setSelectedIds(new Set(res.selectedIds));
        setNextVersion(res.nextVersion);
        setVersionInput(String(res.nextVersion));
      })
      .catch(() => toast.error('Error al cargar las columnas'))
      .finally(() => setLoadingCols(false));
  }, [open, projectCode, calendarName]);

  // ── Selection ──────────────────────────────────────────────────────────
  const toggleAll = () => {
    if (selectedIds.size === columns.length) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(columns.map(c => c.id)));
    }
  };

  const toggle = (id: string) => {
    setSelectedIds(prev => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  };

  // ── Reorder ────────────────────────────────────────────────────────────
  const moveUp = (index: number) => {
    if (index === 0) return;
    setColumns(prev => {
      const next = [...prev];
      [next[index - 1], next[index]] = [next[index], next[index - 1]];
      return next;
    });
  };

  const moveDown = (index: number) => {
    if (index === columns.length - 1) return;
    setColumns(prev => {
      const next = [...prev];
      [next[index], next[index + 1]] = [next[index + 1], next[index]];
      return next;
    });
  };

  // ── Send ───────────────────────────────────────────────────────────────
  const handleSend = async () => {
    if (selectedIds.size === 0) {
      toast.error('Selecciona al menos una columna');
      return;
    }
    setSending(true);
    try {
      const res = await sendCalendarToWebhook({
        projectCode,
        calendarName,
        ...(boardId ? { boardId } : {}),
        columnOrder:       columns.map(c => c.id),
        selectedColumnIds: [...selectedIds],
        overrideVersion:   versionInput.trim() || undefined,
      });
      if (res.calendarStatus === 'Listo') {
        toast.success(`✅ Calendario V${res.version} listo — ${res.eventCount} evento${res.eventCount !== 1 ? 's' : ''}`);
        onSuccess({ status: res.calendarStatus, fileUrl: res.fileUrl, eventCount: res.eventCount, version: res.version });
        onOpenChange(false);
      } else {
        toast.error('n8n procesó el calendario pero reportó un error.');
        onSuccess({ status: res.calendarStatus, eventCount: res.eventCount, version: res.version });
        onOpenChange(false);
      }
    } catch {
      toast.error('Error al enviar el calendario');
    } finally {
      setSending(false);
    }
  };

  const allSelected  = columns.length > 0 && selectedIds.size === columns.length;
  const someSelected = selectedIds.size > 0 && selectedIds.size < columns.length;
  const previewName  = buildFileName(projectFullName, projectTematica, calendarName, versionInput || String(nextVersion ?? '?'));

  return (
    <Dialog open={open} onOpenChange={v => { if (!sending) onOpenChange(v); }}>
      <DialogContent className="sm:max-w-sm">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-base">
            <CalendarDays className="w-4 h-4 text-primary" />
            Crear calendario Excel
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-3">
          {/* File preview */}
          <div className="rounded-lg bg-muted px-3 py-2.5 space-y-1">
            <p className="text-[10px] font-semibold uppercase tracking-wide text-muted-foreground">
              Vista previa del nombre
            </p>
            <p className="text-[13px] font-mono text-foreground break-all leading-snug">
              📄 {previewName}
            </p>
          </div>

          {/* Version input */}
          <div className="space-y-1">
            <Label className="text-xs">Versión</Label>
            <Input
              value={versionInput}
              onChange={e => setVersionInput(e.target.value)}
              placeholder={String(nextVersion ?? 1)}
              className="h-8 text-sm"
            />
          </div>

          <p className="text-xs text-muted-foreground">
            Selecciona y ordena las columnas. Usa ▲▼ para cambiar el orden en el Excel.
          </p>

          {loadingCols ? (
            <div className="space-y-2">
              {[...Array(6)].map((_, i) => <Skeleton key={i} className="h-9 w-full" />)}
            </div>
          ) : (
            <div className="border border-border rounded-lg overflow-hidden">
              {/* Select all header */}
              <button
                className="w-full flex items-center gap-3 px-3 py-2 bg-muted/50 hover:bg-muted transition-colors border-b border-border text-left"
                onClick={toggleAll}
              >
                {allSelected
                  ? <CheckSquare className="w-4 h-4 text-primary flex-shrink-0" />
                  : someSelected
                    ? <div className="w-4 h-4 rounded border-2 border-primary bg-primary/20 flex-shrink-0" />
                    : <Square className="w-4 h-4 text-muted-foreground flex-shrink-0" />}
                <span className="text-xs font-semibold text-foreground">
                  {allSelected ? 'Deseleccionar todo' : 'Seleccionar todo'}
                </span>
                <span className="ml-auto text-xs text-muted-foreground">
                  {selectedIds.size}/{columns.length}
                </span>
              </button>

              {/* Column list */}
              <div className="max-h-64 overflow-y-auto divide-y divide-border/50">
                {columns.map((col, index) => (
                  <div
                    key={col.id}
                    className="flex items-center gap-2 px-2 py-2 hover:bg-muted/30 transition-colors"
                  >
                    {/* Order buttons */}
                    <div className="flex flex-col flex-shrink-0">
                      <button
                        onClick={() => moveUp(index)}
                        disabled={index === 0}
                        className="p-0.5 rounded text-muted-foreground/50 hover:text-foreground hover:bg-muted disabled:opacity-20 disabled:cursor-not-allowed transition-colors"
                      >
                        <ChevronUp className="w-3 h-3" />
                      </button>
                      <button
                        onClick={() => moveDown(index)}
                        disabled={index === columns.length - 1}
                        className="p-0.5 rounded text-muted-foreground/50 hover:text-foreground hover:bg-muted disabled:opacity-20 disabled:cursor-not-allowed transition-colors"
                      >
                        <ChevronDown className="w-3 h-3" />
                      </button>
                    </div>

                    {/* Order number */}
                    <span className="text-[10px] text-muted-foreground/50 tabular-nums w-4 text-right flex-shrink-0">
                      {index + 1}
                    </span>

                    {/* Checkbox + label */}
                    <label className="flex items-center gap-2 flex-1 min-w-0 cursor-pointer">
                      <Checkbox
                        checked={selectedIds.has(col.id)}
                        onCheckedChange={() => toggle(col.id)}
                        className="h-3.5 w-3.5 flex-shrink-0"
                      />
                      <span className={`text-sm flex-1 truncate ${selectedIds.has(col.id) ? 'text-foreground' : 'text-muted-foreground'}`}>
                        {col.title}
                      </span>
                    </label>

                    {/* Type badge */}
                    <span className="text-[10px] text-muted-foreground/50 flex-shrink-0">
                      {colTypeLabel(col.type)}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        <DialogFooter className="gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => onOpenChange(false)}
            disabled={sending}
          >
            Cancelar
          </Button>
          <Button
            size="sm"
            onClick={handleSend}
            disabled={sending || loadingCols || selectedIds.size === 0}
            className="gap-1.5"
          >
            {sending
              ? <><Loader2 className="w-3.5 h-3.5 animate-spin" /> Procesando...</>
              : <><CalendarDays className="w-3.5 h-3.5" /> Generar Excel V{versionInput || nextVersion}</>}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useMemo, useEffect } from 'react';
import { Filter } from 'lucide-react';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';


interface ColumnFilterPopoverProps {
  allValues: string[];
  activeValues: Set<string>;
  onApply: (values: Set<string>) => void;
}

export function ColumnFilterPopover({ allValues, activeValues, onApply }: ColumnFilterPopoverProps) {
  const [open, setOpen] = useState(false);
  const [pending, setPending] = useState<Set<string>>(new Set());
  const [search, setSearch] = useState('');

  // Sync pending with activeValues when popover opens
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { if (open) { setPending(new Set(activeValues)); setSearch(''); } }, [open]);

  const displayed = useMemo(() =>
    search ? allValues.filter(v => v.toLowerCase().includes(search.toLowerCase())) : allValues,
    [allValues, search]
  );

  const allDisplayedSelected = displayed.length > 0 && displayed.every(v => pending.has(v));
  const isActive = activeValues.size > 0;

  const toggle = (v: string) => {
    const next = new Set(pending);
    next.has(v) ? next.delete(v) : next.add(v);
    setPending(next);
  };

  const toggleAll = () => {
    const next = new Set(pending);
    if (allDisplayedSelected) displayed.forEach(v => next.delete(v));
    else displayed.forEach(v => next.add(v));
    setPending(next);
  };

  const apply = () => { onApply(new Set(pending)); setOpen(false); };
  const clear = () => { onApply(new Set()); setOpen(false); };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <button
          className="relative ml-1 p-0.5 rounded hover:bg-muted/80 transition-colors flex-shrink-0 align-middle"
          onClick={e => e.stopPropagation()}
          title="Filtrar columna"
        >
          <Filter className={`w-3 h-3 ${isActive ? 'text-primary' : 'text-muted-foreground/40 hover:text-muted-foreground'}`} />
          {isActive && (
            <span className="absolute -top-0.5 -right-0.5 w-1.5 h-1.5 rounded-full bg-primary pointer-events-none" />
          )}
        </button>
      </PopoverTrigger>
      <PopoverContent className="w-52 p-2 z-50" side="bottom" align="start">
        <Input
          className="h-7 text-xs mb-2"
          placeholder="Buscar valor..."
          value={search}
          onChange={e => setSearch(e.target.value)}
        />
        <div className="flex items-center justify-between mb-1.5 px-0.5">
          <button onClick={toggleAll} className="text-xs text-primary hover:underline font-medium">
            {allDisplayedSelected ? 'Limpiar selección' : 'Seleccionar todos'}
          </button>
          {pending.size > 0 && (
            <span className="text-xs text-muted-foreground">{pending.size} sel.</span>
          )}
        </div>
        <div className="max-h-44 overflow-y-auto">
          <div className="space-y-0.5 pr-1">
            {displayed.length === 0 ? (
              <p className="text-xs text-muted-foreground text-center py-3 italic">
                {allValues.length === 0 ? 'Sin valores en esta columna' : 'Sin coincidencias'}
              </p>
            ) : displayed.map(v => (
              <label
                key={v}
                className="flex items-center gap-2 cursor-pointer hover:bg-muted px-1.5 py-1 rounded text-xs font-normal"
              >
                <Checkbox
                  checked={pending.has(v)}
                  onCheckedChange={() => toggle(v)}
                  className="h-3.5 w-3.5 flex-shrink-0"
                />
                <span className="truncate">{v || '(vacío)'}</span>
              </label>
            ))}
          </div>
        </div>
        <div className="flex gap-1.5 mt-2 pt-2 border-t border-border">
          <Button size="sm" className="flex-1 h-7 text-xs" onClick={apply}>Aplicar</Button>
          {(pending.size > 0 || activeValues.size > 0) && (
            <Button size="sm" variant="ghost" className="h-7 text-xs px-2" onClick={clear}>Limpiar</Button>
          )}
        </div>
      </PopoverContent>
    </Popover>
  );
}

