export function EventDetailDialog({
  open, onOpenChange,
  editingEvent,
  calBoardId,
  presetLocs = PRESET_LOCS,
  calDynCols,
  recGroups, recGroupsLoading,
  linkingGroup, setLinkingGroup,
  outlookSyncing,
  htmlPreviewOpen, setHtmlPreviewOpen,
  onOutlookSync,
  onRecGroupsRefresh,
  onInviteStatusChanged,
  onSaved,
