import { Deal, DashboardFilters, DateReference, DashboardPeriod, KpiCompareMode } from './types';

export function getPeriodRange(period: DashboardPeriod): { startDate: string | null; endDate: string | null } {
  if (period.mode === 'all') return { startDate: null, endDate: null };
  if (period.mode === 'custom') {
    return { startDate: period.startDate ?? null, endDate: period.endDate ?? null };
  }

  const year = period.year ?? new Date().getFullYear();

  if (period.mode === 'year') {
    return { startDate: `${year}-01-01`, endDate: `${year}-12-31` };
  }
  if (period.mode === 'quarter' && period.quarter) {
    const starts = ['01', '04', '07', '10'];
    const ends = ['03-31', '06-30', '09-30', '12-31'];
    return {
      startDate: `${year}-${starts[period.quarter - 1]}-01`,
      endDate: `${year}-${ends[period.quarter - 1]}`,
    };
  }
  if (period.mode === 'month' && period.month) {
    const m = String(period.month).padStart(2, '0');
    const lastDay = new Date(year, period.month, 0).getDate();
    return {
      startDate: `${year}-${m}-01`,
      endDate: `${year}-${m}-${String(lastDay).padStart(2, '0')}`,
    };
  }
  return { startDate: null, endDate: null };
}

export function getPreviousPeriod(period: DashboardPeriod, compareMode: KpiCompareMode = 'previous'): DashboardPeriod | null {
  if (compareMode === 'none') return null;
  if (period.mode === 'all' || period.mode === 'custom') return null;
  const year = period.year ?? new Date().getFullYear();

  if (compareMode === 'yoy') {
    if (period.mode === 'year') return { mode: 'year', year: year - 1 };
    if (period.mode === 'quarter' && period.quarter) {
      return { mode: 'quarter', year: year - 1, quarter: period.quarter };
    }
    if (period.mode === 'month' && period.month) {
      return { mode: 'month', year: year - 1, month: period.month };
    }
    return null;
  }

  // compareMode === 'previous'
  if (period.mode === 'year') return { mode: 'year', year: year - 1 };
  if (period.mode === 'quarter' && period.quarter) {
    return period.quarter === 1
      ? { mode: 'quarter', year: year - 1, quarter: 4 }
      : { mode: 'quarter', year, quarter: period.quarter - 1 };
  }
  if (period.mode === 'month' && period.month) {
    return period.month === 1
      ? { mode: 'month', year: year - 1, month: 12 }
      : { mode: 'month', year, month: period.month - 1 };
  }
  return null;
}

export function applyFilters(deals: Deal[], filters: DashboardFilters, dateRef: DateReference): Deal[] {
  const { startDate, endDate } = getPeriodRange(filters.period);

  return deals.filter(d => {
    if (startDate || endDate) {
      const dateStr = dateRef === 'approvalDate' ? d.approvalDate : d.proposalDate;
      if (!dateStr) return false;
      if (startDate && dateStr < startDate) return false;
      if (endDate && dateStr > endDate) return false;
    }
    if (filters.clients.length > 0 && !filters.clients.includes(d.client ?? '')) return false;
    if (filters.projectTypes.length > 0 && !filters.projectTypes.includes(d.projectType ?? '')) return false;
    if (filters.currencies.length > 0 && !filters.currencies.includes(d.currency ?? '')) return false;
    if (filters.phases.length > 0 && !filters.phases.includes(d.phase ?? '')) return false;
    if (filters.owners.length > 0) {
      const ownerArr = Array.isArray(d.owner) ? d.owner : d.owner ? [d.owner] : [];
      if (!filters.owners.some(o => ownerArr.includes(o))) return false;
    }
    if (filters.empresaOperadora.length > 0) {
      const emp = d.empresaOperadora ?? '';
      if (!filters.empresaOperadora.includes(emp)) return false;
    }
    return true;
  });
}

import { Deal, MetricKey } from './types';
import { DashboardPeriod } from './types';
import { getPreviousPeriod } from './filters';

function toMXN(deal: Deal): { revenue: number; cost: number } {
  const isMXN = deal.currency?.startsWith('MXN');
  const rate = isMXN ? 1 : (deal.exchangeRate ?? 20);
  return {
    revenue: (deal.clientPrice ?? 0) * rate,
    cost: (deal.quotedCost ?? 0) * rate,
  };
}

export function calcCurrencyBreakdown(deals: Deal[]) {
  let mxnNative = 0;
  let usdNative = 0;
  let usdConvertedToMxn = 0;
  let missingRates = 0;
  let usdDealCount = 0;

  for (const d of deals) {
    const price = d.clientPrice ?? 0;
    const isMXN = d.currency?.startsWith('MXN');
    if (isMXN || !d.currency) {
      mxnNative += price;
    } else {
      usdDealCount++;
      usdNative += price;
      if (!d.exchangeRate) missingRates++;
      usdConvertedToMxn += price * (d.exchangeRate ?? 20);
    }
  }

  return {
    mxnNative,
    usdNative,
    usdConvertedToMxn,
    avgRate: usdNative > 0 ? usdConvertedToMxn / usdNative : 0,
    totalMxn: mxnNative + usdConvertedToMxn,
    usdDealCount,
    missingRates,
  };
}

export function calcRevenue(deals: Deal[]): number {
  return deals.reduce((s, d) => s + toMXN(d).revenue, 0);
}

export function calcCost(deals: Deal[]): number {
  return deals.reduce((s, d) => s + toMXN(d).cost, 0);
}

export function calcMargin(deals: Deal[]): number {
  return calcRevenue(deals) - calcCost(deals);
}

export function calcAvgTicket(deals: Deal[]): number {
  const withPrice = deals.filter(d => (d.clientPrice ?? 0) > 0);
  if (withPrice.length === 0) return 0;
  return calcRevenue(withPrice) / withPrice.length;
}

export function calcConversionRate(deals: Deal[]): number {
  const base = deals.filter(d =>
    ['Cotización enviada', 'Negociación', 'Ganado', 'Perdido'].includes(d.phase ?? '')
  );
  if (base.length === 0) return 0;
  return base.filter(d => d.phase === 'Ganado').length / base.length;
}

export function calcMetric(deals: Deal[], metric: MetricKey): number {
  switch (metric) {
    case 'revenue': return calcRevenue(deals);
    case 'cost': return calcCost(deals);
    case 'margin': return calcMargin(deals);
    case 'avgTicket': return calcAvgTicket(deals);
    case 'dealCount': return deals.length;
    case 'conversionRate': return calcConversionRate(deals);
    default: return 0;
  }
}

/** Filter deals by a widget-level currency preference */
export function filterDealsByCurrency(deals: Deal[], currency?: 'all' | 'MXN' | 'USD'): Deal[] {
  if (!currency || currency === 'all') return deals;
  return deals.filter(d => d.currency?.startsWith(currency));
}

/**
 * Calculate a metric with optional currency filtering.
 * - 'all' / undefined: uses toMXN() conversion (existing behavior)
 * - 'MXN' or 'USD': uses clientPrice / quotedCost directly, no conversion
 * Note: deals should already be pre-filtered by filterDealsByCurrency before calling this.
 */
export function calcMetricInCurrency(deals: Deal[], metric: MetricKey, currency?: 'all' | 'MXN' | 'USD'): number {
  if (!currency || currency === 'all') return calcMetric(deals, metric);
  // Specific currency — use raw amounts without exchange-rate conversion
  switch (metric) {
    case 'revenue': return deals.reduce((s, d) => s + (d.clientPrice ?? 0), 0);
    case 'cost': return deals.reduce((s, d) => s + (d.quotedCost ?? 0), 0);
    case 'margin': return deals.reduce((s, d) => s + (d.clientPrice ?? 0) - (d.quotedCost ?? 0), 0);
    case 'avgTicket': {
      const w = deals.filter(d => (d.clientPrice ?? 0) > 0);
      return w.length === 0 ? 0 : w.reduce((s, d) => s + (d.clientPrice ?? 0), 0) / w.length;
    }
    case 'dealCount': return deals.length;
    case 'conversionRate': return calcConversionRate(deals);
    default: return 0;
  }
}

export function calcKpi(
  current: Deal[],
  previous: Deal[] | null,
  metric: MetricKey
): { current: number; previous: number | null; changePct: number | null } {
  const cur = calcMetric(current, metric);
  const prev = previous !== null ? calcMetric(previous, metric) : null;
  const changePct =
    prev !== null && prev !== 0 ? ((cur - prev) / Math.abs(prev)) * 100 : null;
  return { current: cur, previous: prev, changePct };
}

export function hasPreviousPeriod(period: DashboardPeriod): boolean {
  return getPreviousPeriod(period) !== null;
}

import { z } from 'zod';
import { createEndpoint } from 'zite-integrations-backend-sdk';
import { publishEvent } from '../lib/ably';

export default createEndpoint({
  authenticated: true,
  description: 'Publish recruitment rows change event via Ably so other open screens refresh their row list',
  inputSchema: z.object({
    projectCode: z.string(),
    boardId: z.string().optional(),
    rowId: z.string().optional(),
    changeType: z.enum(['created', 'updated', 'deleted']).optional(),
    entityType: z.enum(['task', 'event', 'recruitment']).optional(),
    groupId: z.string().optional(),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    if (input.projectCode) {
      try {
        await publishEvent(`board:${input.projectCode}`, 'recruitment.rows.changed', {
          projectCode: input.projectCode,
          boardId: input.boardId ?? '',
          rowId: input.rowId ?? '',
          changeType: input.changeType ?? 'created',
          entityType: input.entityType ?? '',
          groupId: input.groupId ?? '',
          senderEmail: context?.user?.email ?? '',
          timestamp: new Date().toISOString(),
        });
      } catch (err) {
        console.error('[ably] recruitment.rows.changed publish failed:', err);
      }
    }
    return { success: true };
  },
});

