import { useState, useEffect } from 'react';
import { format } from 'date-fns';
import { es } from 'date-fns/locale';
import { CalendarDays, ChevronRight, Unlink, Loader2, MapPin, X } from 'lucide-react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { getTasks } from 'zite-endpoints-sdk';
import type { GetTasksOutputType } from 'zite-endpoints-sdk';

type CalEvent = GetTasksOutputType['calendarEvents'][0];
type BoardObj = { id: string; name: string };

interface Props {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  projectCode: string;
  currentLink?: { calBoardId: string; eventId: string };
  onLink: (calBoardId: string, eventId: string) => Promise<void>;
  onUnlink: () => Promise<void>;
  calBoardObjects?: BoardObj[];
}

function formatEventDate(iso?: string) {
  if (!iso) return '';
  try {
    return format(new Date(iso), "EEE d MMM · h:mm a", { locale: es });
  } catch { return iso; }
}

export function LinkEventDialog({ open, onOpenChange, projectCode, currentLink, onLink, onUnlink, calBoardObjects: externalObjs }: Props) {
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [calBoardObjs, setCalBoardObjs] = useState<BoardObj[]>([]);
  const [allEvents, setAllEvents] = useState<CalEvent[]>([]);
  const [selectedBoardId, setSelectedBoardId] = useState<string | null>(null);
  const [selectedEventId, setSelectedEventId] = useState<string | null>(null);
  const [currentEventInfo, setCurrentEventInfo] = useState<CalEvent | null>(null);

  useEffect(() => {
    if (!open || !projectCode) return;
    setLoading(true);
    setSelectedBoardId(null);
    setSelectedEventId(null);
    getTasks({ projectCode })
      .then(data => {
        const objs: BoardObj[] = externalObjs ?? ((data as any).calendarBoardObjects ?? []);
        setCalBoardObjs(objs);
        setAllEvents(data.calendarEvents);
        if (currentLink) {
          const ev = data.calendarEvents.find(e => e.id === currentLink.eventId);
          setCurrentEventInfo(ev ?? null);
        }
      })
      .finally(() => setLoading(false));
  }, [open, projectCode]);

  // Derive the selected board's name for legacy event matching
  const selectedBoardObj = calBoardObjs.find(b => b.id === selectedBoardId);

  const eventsForBoard = selectedBoardId
    ? allEvents.filter(e => {
        // UUID-first: if event has boardId, match by UUID; else fallback by calendarName
        if ((e as any).boardId) return (e as any).boardId === selectedBoardId;
        return e.calendarName === selectedBoardObj?.name;
      })
    : [];

  const selectedEvent = eventsForBoard.find(e => e.id === selectedEventId);

  const handleLink = async () => {
    if (!selectedBoardId || !selectedEventId) return;
    setSaving(true);
    try {
      // Pass UUID directly — no legacy composite construction
      await onLink(selectedBoardId, selectedEventId);
      onOpenChange(false);
    } finally {
      setSaving(false);
    }
  };

  const handleUnlink = async () => {
    setSaving(true);
    try {
      await onUnlink();
      onOpenChange(false);
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-sm" aria-describedby={undefined}>
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-base">
            <CalendarDays className="w-4 h-4 text-primary flex-shrink-0" />
            {currentLink ? 'Evento vinculado' : 'Vincular a evento de calendario'}
          </DialogTitle>
        </DialogHeader>

        {loading ? (
          <div className="flex items-center justify-center py-8 text-muted-foreground gap-2">
            <Loader2 className="w-4 h-4 animate-spin" />
            <span className="text-sm">Cargando calendarios...</span>
          </div>
        ) : currentLink ? (
          /* ── Already linked: show info + unlink ── */
          <div className="space-y-4">
            <div className="rounded-lg border border-primary/30 bg-primary/5 px-4 py-3 space-y-1.5">
              <p className="text-sm font-semibold text-foreground">
                {currentEventInfo?.eventName ?? 'Evento'}
              </p>
              {currentEventInfo?.eventDate && (
                <p className="text-xs text-muted-foreground flex items-center gap-1.5">
                  <CalendarDays className="w-3 h-3 flex-shrink-0" />
                  {formatEventDate(currentEventInfo.eventDate)}
                  {currentEventInfo.durationHours != null && ` · ${currentEventInfo.durationHours} hrs`}
                </p>
              )}
              {currentEventInfo?.location && (
                <p className="text-xs text-muted-foreground flex items-center gap-1.5">
                  <MapPin className="w-3 h-3 flex-shrink-0" />
                  {currentEventInfo.location}
                </p>
              )}
            </div>
            <div className="flex gap-2">
              <Button
                variant="outline"
                size="sm"
                className="flex-1 gap-1.5 text-destructive border-destructive/30 hover:bg-destructive/10"
                onClick={handleUnlink}
                disabled={saving}
              >
                {saving ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Unlink className="w-3.5 h-3.5" />}
                Desvincular
              </Button>
              <Button variant="outline" size="sm" className="flex-1" onClick={() => onOpenChange(false)}>
                <X className="w-3.5 h-3.5 mr-1.5" /> Cerrar
              </Button>
            </div>
          </div>
        ) : !selectedBoardId ? (
          /* ── Step 1: Pick calendar ── */
          <div className="space-y-2">
            <p className="text-xs text-muted-foreground mb-1">Selecciona un calendario del proyecto:</p>
            {calBoardObjs.length === 0 ? (
              <p className="text-sm text-muted-foreground text-center py-6">No hay calendarios en este proyecto.</p>
            ) : (
              <div className="space-y-1">
                {calBoardObjs.map(board => (
                  <button
                    key={board.id}
                    onClick={() => setSelectedBoardId(board.id)}
                    className="w-full flex items-center justify-between px-3 py-2.5 rounded-lg border border-border/50 hover:border-primary/40 hover:bg-primary/5 transition-all text-left group"
                  >
                    <div className="flex items-center gap-2.5">
                      <CalendarDays className="w-3.5 h-3.5 text-muted-foreground group-hover:text-primary transition-colors" />
                      <span className="text-sm font-medium">{board.name}</span>
                    </div>
                    <ChevronRight className="w-3.5 h-3.5 text-muted-foreground/40 group-hover:text-primary/60 transition-colors" />
                  </button>
                ))}
              </div>
            )}
          </div>
        ) : (
          /* ── Step 2: Pick event ── */
          <div className="space-y-3">
            <div className="flex items-center gap-2">
              <button
                onClick={() => { setSelectedBoardId(null); setSelectedEventId(null); }}
                className="text-xs text-primary hover:underline flex items-center gap-1"
              >
                ← Calendarios
              </button>
              <span className="text-xs text-muted-foreground">/</span>
              <span className="text-xs font-medium truncate">{selectedBoardObj?.name}</span>
            </div>

            {eventsForBoard.length === 0 ? (
              <p className="text-sm text-muted-foreground text-center py-6">Sin eventos en este calendario.</p>
            ) : (
              <div className="max-h-64 overflow-y-auto">
                <div className="space-y-1 pr-1">
                  {[...eventsForBoard]
                    .sort((a, b) => (a.eventDate ?? '') < (b.eventDate ?? '') ? -1 : 1)
                    .map(ev => {
                      const isSelected = selectedEventId === ev.id;
                      return (
                        <button
                          key={ev.id}
                          onClick={() => setSelectedEventId(ev.id)}
                          className={`w-full text-left px-3 py-2.5 rounded-lg border transition-all ${isSelected ? 'border-primary bg-primary/10' : 'border-border/40 hover:border-primary/30 hover:bg-muted/40'}`}
                        >
                          <p className={`text-sm font-medium truncate ${isSelected ? 'text-primary' : 'text-foreground'}`}>
                            {ev.eventName ?? 'Sin nombre'}
                          </p>
                          <div className="flex items-center gap-3 mt-0.5">
                            {ev.eventDate && (
                              <span className="text-xs text-muted-foreground">
                                {formatEventDate(ev.eventDate)}
                                {ev.durationHours != null && ` · ${ev.durationHours} hrs`}
                              </span>
                            )}
                          </div>
                          {ev.location && (
                            <p className="text-[10px] text-muted-foreground/60 mt-0.5 flex items-center gap-1">
                              <MapPin className="w-2.5 h-2.5 flex-shrink-0" />
                              {ev.location}
                            </p>
                          )}
                        </button>
                      );
                    })}
                </div>
              </div>
            )}

            <div className="flex gap-2 pt-1 border-t border-border/30">
              <Button variant="outline" size="sm" className="flex-1" onClick={() => { setSelectedBoardId(null); setSelectedEventId(null); }}>
                Atrás
              </Button>
              <Button
                size="sm"
                className="flex-1 gap-1.5"
                disabled={!selectedEventId || saving}
                onClick={handleLink}
              >
                {saving ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <CalendarDays className="w-3.5 h-3.5" />}
                Vincular
              </Button>
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

import { Deal, GroupByKey, DateReference } from './types';
import { PHASE_ORDER } from './constants';

const MONTH_NAMES = ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'];

function getDateKey(d: Deal, dateRef: DateReference, groupBy: 'month' | 'quarter' | 'year'): string {
  const dateStr = dateRef === 'approvalDate' ? d.approvalDate : d.proposalDate;
  if (!dateStr) return 'Sin fecha';
  const [y, m] = dateStr.split('-').map(Number);
  if (groupBy === 'year') return `${y}`;
  if (groupBy === 'quarter') return `Q${Math.ceil(m / 3)} ${y}`;
  return `${MONTH_NAMES[m - 1]} ${y}`;
}

function getDateSortKey(d: Deal, dateRef: DateReference): string {
  return (dateRef === 'approvalDate' ? d.approvalDate : d.proposalDate) ?? '0000-00';
}

export function getGroupKey(d: Deal, groupBy: GroupByKey, dateRef: DateReference): string {
  switch (groupBy) {
    case 'month':
    case 'quarter':
    case 'year':
      return getDateKey(d, dateRef, groupBy);
    case 'client': return d.client ?? 'Sin cliente';
    case 'projectType': return d.projectType ?? 'Sin tipo';
    case 'tematica': return d.tematica ?? 'Sin temática';
    case 'owner': {
      const arr = Array.isArray(d.owner) ? d.owner : d.owner ? [d.owner] : [];
      return arr[0] ?? 'Sin owner';
    }
    case 'empresaOperadora': return d.empresaOperadora ?? 'Sin empresa';
    case 'phase': return d.phase ?? 'Sin fase';
    default: return 'Otro';
  }
}

/** Returns just the time unit label without the year (e.g. "Ene" instead of "Ene 2024"). Used for year-comparison charts. */
export function getGroupKeyStripped(d: Deal, groupBy: GroupByKey, dateRef: DateReference): string {
  if (groupBy === 'month' || groupBy === 'quarter') {
    const dateStr = dateRef === 'approvalDate' ? d.approvalDate : d.proposalDate;
    if (!dateStr) return 'Sin fecha';
    const [, m] = dateStr.split('-').map(Number);
    if (groupBy === 'month') return MONTH_NAMES[m - 1];
    return `Q${Math.ceil(m / 3)}`;
  }
  return getGroupKey(d, groupBy, dateRef);
}

export function groupDeals(deals: Deal[], groupBy: GroupByKey, dateRef: DateReference): Map<string, Deal[]> {
  const map = new Map<string, Deal[]>();
  for (const d of deals) {
    const key = getGroupKey(d, groupBy, dateRef);
    if (!map.has(key)) map.set(key, []);
    map.get(key)!.push(d);
  }

  // Sort phase by canonical order
  if (groupBy === 'phase') {
    const sorted = new Map<string, Deal[]>();
    for (const p of PHASE_ORDER) {
      if (map.has(p)) sorted.set(p, map.get(p)!);
    }
    for (const [k, v] of map) {
      if (!sorted.has(k)) sorted.set(k, v);
    }
    return sorted;
  }

  // Sort time-based chronologically using a representative deal's date
  if (['month', 'quarter', 'year'].includes(groupBy)) {
    const keyToSortVal = new Map<string, string>();
    for (const d of deals) {
      const key = getGroupKey(d, groupBy, dateRef);
      if (!keyToSortVal.has(key)) {
        keyToSortVal.set(key, getDateSortKey(d, dateRef));
      }
    }
    const entries = [...map.entries()].sort((a, b) =>
      (keyToSortVal.get(a[0]) ?? '').localeCompare(keyToSortVal.get(b[0]) ?? '')
    );
    return new Map(entries);
  }

  return map;
}

export function fillTimeSeries(
  data: Map<string, Deal[]>,
  groupBy: 'month' | 'quarter' | 'year',
  deals: Deal[],
  dateRef: DateReference
): Map<string, Deal[]> {
  const dates = deals
    .map(d => (dateRef === 'approvalDate' ? d.approvalDate : d.proposalDate))
    .filter((s): s is string => !!s)
    .sort();
  if (dates.length === 0) return data;

  const [minY, minM] = dates[0].split('-').map(Number);
  const [maxY, maxM] = dates[dates.length - 1].split('-').map(Number);
  const filled = new Map<string, Deal[]>();

  if (groupBy === 'year') {
    for (let y = minY; y <= maxY; y++) {
      const k = `${y}`;
      filled.set(k, data.get(k) ?? []);
    }
  } else if (groupBy === 'quarter') {
    let y = minY, q = Math.ceil(minM / 3);
    const ey = maxY, eq = Math.ceil(maxM / 3);
    while (y < ey || (y === ey && q <= eq)) {
      const k = `Q${q} ${y}`;
      filled.set(k, data.get(k) ?? []);
      if (++q > 4) { q = 1; y++; }
    }
  } else {
    let y = minY, m = minM - 1; // convert to 0-based month index
    const ey = maxY, em = maxM - 1;
    while (y < ey || (y === ey && m <= em)) {
      const k = `${MONTH_NAMES[m]} ${y}`;
      filled.set(k, data.get(k) ?? []);
      if (++m > 11) { m = 0; y++; }
    }
  }
  return filled;
}

import { useState } from 'react';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import type { PresenceMember } from '../hooks/useProjectPresence';

const PAGE_LABELS: Record<string, string> = {
  pm:          'Actividades',
  recruitment: 'Reclutamiento',
};

function getInitials(email: string, name?: string): string {
  if (name) {
    const parts = name.trim().split(/\s+/);
    if (parts.length >= 2) return `${parts[0][0]}${parts[1][0]}`.toUpperCase();
    if (parts[0].length > 0) return parts[0].slice(0, 2).toUpperCase();
  }
  return email.slice(0, 2).toUpperCase();
}

function getPageLabel(pageName?: string): string {
  if (!pageName) return '';
  return PAGE_LABELS[pageName] ?? pageName;
}

// Deterministic background color from email hash
const COLORS = [
  'bg-blue-500', 'bg-violet-500', 'bg-emerald-500', 'bg-orange-500',
  'bg-pink-500', 'bg-teal-500', 'bg-indigo-500', 'bg-rose-500',
];
function avatarBg(email: string): string {
  let h = 0;
  for (let i = 0; i < email.length; i++) h = email.charCodeAt(i) + ((h << 5) - h);
  return COLORS[Math.abs(h) % COLORS.length];
}

const MAX_VISIBLE = 4;

interface ProjectPresenceAvatarsProps {
  members: PresenceMember[];
}

function PresenceAvatar({ m, i }: { m: PresenceMember; i: number }) {
  const [imgError, setImgError] = useState(false);

  return (
    <div
      className={`relative w-7 h-7 rounded-full flex items-center justify-center text-[10px] font-bold text-white flex-shrink-0 border-2 border-background cursor-default select-none ${i > 0 ? '-ml-2' : ''} ${avatarBg(m.email)}`}
      style={{ zIndex: MAX_VISIBLE - i }}
    >
      {/* Initials always shown as fallback base */}
      {getInitials(m.email, m.name)}

      {/* Photo overlay — hides itself on error */}
      {m.profilePhoto && !imgError && (
        <img
          src={m.profilePhoto}
          alt={m.name || m.email}
          className="absolute inset-0 w-full h-full rounded-full object-cover"
          onError={() => setImgError(true)}
        />
      )}
    </div>
  );
}

export function ProjectPresenceAvatars({ members }: ProjectPresenceAvatarsProps) {
  if (!members || members.length === 0) return null;

  const visible  = members.slice(0, MAX_VISIBLE);
  const overflow = members.length - MAX_VISIBLE;

  return (
    <TooltipProvider>
      <div className="flex items-center flex-shrink-0">
        {visible.map((m, i) => (
          <Tooltip key={m.email}>
            <TooltipTrigger asChild>
              <span>
                <PresenceAvatar m={m} i={i} />
              </span>
            </TooltipTrigger>
            <TooltipContent side="bottom" className="text-xs py-1.5 px-2.5">
              <div className="font-semibold">{m.name || m.email}</div>
              {m.pageName && (
                <div className="text-muted-foreground text-[11px] mt-0.5">{getPageLabel(m.pageName)}</div>
              )}
            </TooltipContent>
          </Tooltip>
        ))}

        {overflow > 0 && (
          <div
            className="relative -ml-2 w-7 h-7 rounded-full flex items-center justify-center text-[10px] font-semibold bg-muted text-muted-foreground border-2 border-background flex-shrink-0"
            style={{ zIndex: 0 }}
          >
            +{overflow}
          </div>
        )}
      </div>
    </TooltipProvider>
  );
}

