  analysis: ProjectAnalysis;
  dealsList: DealItem[];
  isExpanded: boolean;
  onToggle: () => void;
  onDealUpdated: (projectId: string, deal: DealItem | null) => void;
  onRefreshAnalysis: () => void;
}

