            <TooltipProvider delayDuration={300}>
              <Tooltip>
                <TooltipTrigger asChild>
                  <button className="relative p-1 rounded hover:bg-background/80 text-muted-foreground hover:text-foreground transition-colors" onClick={onSendTimeline}>
                    <BarChart2 className="w-3.5 h-3.5" />
                    <span className="absolute -top-0.5 -right-0.5 w-2 h-2 rounded-full bg-red-500" />
                  </button>
                </TooltipTrigger>
                <TooltipContent side="top" className="text-xs">Error al generar — click para reintentar</TooltipContent>
              </Tooltip>
            </TooltipProvider>
          ) : (
            <TooltipProvider delayDuration={300}>
              <Tooltip>
                <TooltipTrigger asChild>
                  <button className="p-1 rounded hover:bg-background/80 text-muted-foreground hover:text-foreground transition-colors" onClick={onSendTimeline}>
                    <BarChart2 className="w-3.5 h-3.5" />
                  </button>
                </TooltipTrigger>
                <TooltipContent side="top" className="text-xs">Crear / actualizar timeline</TooltipContent>
              </Tooltip>
            </TooltipProvider>
          )}
        </div>
      )}

      {/* ── 3-dot action menu ── */}
      {!isNone && (
        <div className="opacity-0 group-hover/gh:opacity-100 transition-opacity flex-shrink-0" onClick={e => e.stopPropagation()}>
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <button className="p-1 rounded hover:bg-background/80 text-muted-foreground hover:text-foreground">
                <MoreHorizontal className="w-3.5 h-3.5" />
              </button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-52 p-1.5">
              {/* Color picker */}
              <div className="px-2 pb-2 pt-1">
                <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider mb-1.5">Color del grupo</p>
                <ColorSwatches currentId={colorId} onPick={id => groupDynCols.updateColumn(groupId, { columnType: id })} />
              </div>

              {/* Nombre público — solo en tablero de reclutamiento */}
              {showPublicName && (
                <>
                  <div className="my-1 border-t border-border/40" />
                  <div className="px-2 py-2">
                    <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider mb-1.5">Nombre público</p>
                    <input
                      type="text"
                      value={pubName}
                      onChange={e => setPubName(e.target.value)}
                      onBlur={() => savePublicName(pubName)}
                      onKeyDown={e => { e.stopPropagation(); if (e.key === 'Enter') (e.target as HTMLInputElement).blur(); }}
                      onClick={e => e.stopPropagation()}
                      placeholder="Ej: Grupo 1 - Jue 23 mayo"
                      className="w-full text-xs bg-muted/50 border border-border/50 rounded-md px-2 py-1.5 outline-none focus:ring-1 focus:ring-primary/40 placeholder:text-muted-foreground/40"
                    />
                    <p className="text-[9px] text-muted-foreground/50 mt-1 leading-tight">
                      Nombre visible para reclutadores externos (oculta el perfil)
                    </p>
                  </div>
                </>
              )}

              {/* Vincular / desvincular evento */}
              {(onLinkEvent || onUnlinkEvent) && (
                <>
                  <div className="my-1 border-t border-border/40" />
                  {linkedCalEvent?.eventId ? (
                    <DropdownMenuItem className="text-xs gap-2 cursor-pointer" onClick={() => setLinkDialogOpen(true)}>
                      <Unlink className="w-3.5 h-3.5 text-muted-foreground" /> Desvincular evento 📅
                    </DropdownMenuItem>
                  ) : (
                    <>
                      <DropdownMenuItem className="text-xs gap-2 cursor-pointer" onClick={() => setLinkDialogOpen(true)}>
                        <CalendarDays className="w-3.5 h-3.5 text-muted-foreground" /> Vincular a evento 📅
                      </DropdownMenuItem>
                      {onCreateEventForGroup && (
                        <DropdownMenuItem className="text-xs gap-2 cursor-pointer" onClick={() => onCreateEventForGroup()}>
                          <Plus className="w-3.5 h-3.5 text-muted-foreground" /> Crear evento nuevo 📅
                        </DropdownMenuItem>
                      )}
                    </>
                  )}
                </>
              )}

              <div className="my-1 border-t border-border/40" />
              <DropdownMenuItem className="text-xs gap-2 cursor-pointer" onClick={() => { setEditVal(name); setRenaming(true); }}>
                <Pencil className="w-3.5 h-3.5" /> Renombrar
              </DropdownMenuItem>
              {onDuplicateGroup && (
                <DropdownMenuItem className="text-xs gap-2 cursor-pointer" onClick={onDuplicateGroup}>
                  <Copy className="w-3.5 h-3.5" /> Duplicar grupo
                </DropdownMenuItem>
              )}
              <DropdownMenuItem
                className="text-xs gap-2 cursor-pointer text-destructive focus:text-destructive"
                onClick={async () => { try { await groupDynCols.removeColumn(groupId); onGroupStructureChanged?.(); } catch { /* keep existing behavior */ } }}
              >
                <Trash2 className="w-3.5 h-3.5" /> Eliminar grupo
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      )}
    </div>
  );

  // ── Table mode: renders as <tr><td colSpan> with sticky top:33px ─────────
  if (colSpan !== undefined) {
    return (
      <>
        <tr
          onDragOver={e => { e.preventDefault(); e.stopPropagation(); onDragOver?.(e, groupId); }}
          onDrop={e => { e.preventDefault(); e.stopPropagation(); onDrop?.(e, groupId); }}
        >
          <td
            colSpan={colSpan}
            className={`group/gh p-0 transition-all duration-150${isDragOver ? ' ring-2 ring-inset ring-primary' : ''}`}
            style={{
              position: 'sticky',
              top: 33,
              zIndex: 20,
              background: isDragOver ? `color-mix(in srgb, hsl(var(--primary)) 10%, ${pastelBg})` : pastelBg,
              borderLeft: isDragOver ? `4px solid hsl(var(--primary))` : `4px solid ${color}`,
              borderBottom: '1px solid hsl(var(--border) / 0.2)',
              boxShadow: isDragOver ? 'inset 0 0 0 1px hsl(var(--primary) / 0.4)' : undefined,
            }}
          >
            <div style={{ position: 'sticky', left: 0, width: 'fit-content', maxWidth: '100vw' }}>
              {inner}
            </div>
          </td>
        </tr>
        {linkDialog}
      </>
    );
  }

  // ── Legacy mode: renders as a sticky <div> (CSS Grid / PMPage) ───────────
  return (
    <>
      <div
        className={`sticky top-[33px] z-20 border-b border-border/20 group/gh${isDragOver ? ' ring-2 ring-inset ring-primary' : ''}`}
        style={{ borderLeft: `4px solid ${color}`, background: pastelBg }}
        onDragOver={e => { e.preventDefault(); onDragOver?.(e, groupId); }}
        onDrop={e => { e.preventDefault(); onDrop?.(e, groupId); }}
      >
        {inner}
      </div>
      {linkDialog}
    </>
  );
}

import { useState, useEffect, useRef } from 'react';
import { GetDealsOutputType, saveDeal, deleteDeal, getUsers, GetUsersOutputType, saveProject, approveSelectedCotizaciones } from 'zite-endpoints-sdk';
import ApprovalReviewDialog from './ApprovalReviewDialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { Trash2, FolderPlus, CheckCircle2 } from 'lucide-react';
import { toast } from 'sonner';
import { PHASES, CURRENCIES, getCurrencySymbol, fmtMoneyFull } from './dealUtils';
import NumericInput from '@/components/NumericInput';

type Deal = GetDealsOutputType['deals'][0];
type UserItem = GetUsersOutputType['users'][0];
const PHASE_KEYS = PHASES.map(p => p.key);

interface Props {
  deal: Deal;
  onSaved: (updated: Deal) => void;
  onDeleted: () => void;
  existingClients?: string[];
}

const APPROVE_PHASES = ['Cotización enviada', 'Negociación'];

export default function DealGeneralTab({ deal, onSaved, onDeleted, existingClients = [] }: Props) {
  const [form, setForm] = useState({
    dealName: deal.dealName ?? '', phase: deal.phase ?? 'Prospecto',
    client: deal.client ?? '', projectType: deal.projectType ?? '',
    tematica: deal.tematica ?? '', proposalDate: (deal.proposalDate ?? '').slice(0, 10),
    approvalDate: (deal.approvalDate ?? '').slice(0, 10), currency: deal.currency ?? 'MXN 🇲🇽',
    clientPrice: deal.clientPrice?.toString() ?? '', taxesPct: deal.taxesPct?.toString() ?? '',
    retencionesPct: deal.retencionesPct?.toString() ?? '',
    notes: deal.notes ?? '',
  });
  const [owner, setOwner] = useState((Array.isArray(deal.owner) ? deal.owner[0] : deal.owner) ?? '');
  const [users, setUsers] = useState<UserItem[]>([]);
  const [saving, setSaving] = useState(false);
  const [confirmDel, setConfirmDel] = useState(false);
  const [creatingProject, setCreatingProject] = useState(false);
  const [pendingApprove, setPendingApprove] = useState<{ dealId: string; updated: Deal } | null>(null);
  const [approving, setApproving] = useState(false);
  const [approvalReviewOpen, setApprovalReviewOpen] = useState(false);
  const [clientFocused, setClientFocused] = useState(false);
  const clientBlurTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const dealAny = deal as any;
  const hasLinkedProject = Array.isArray(dealAny.projects)
    ? (dealAny.projects as string[]).length > 0
    : !!dealAny.projects;

  const handleCreateProject = async () => {
    setCreatingProject(true);
    try {
      const code = form.dealName || 'Proyecto ' + Date.now().toString().slice(-4);
      await saveProject({
        projectCode: code,
        fullName: form.dealName || undefined,
        client: form.client || undefined,
        tematica: form.tematica || undefined,
        status: 'Activo',
      });
      toast.success(`Proyecto "${code}" creado exitosamente`);
    } catch { toast.error('Error al crear el proyecto'); }
    setCreatingProject(false);
  };

  const handleApprovalSuccess = (res: { projectCode: string; projectId: string; quotedCost: number; notificationsSent: number }) => {
    const today = new Date().toISOString().split('T')[0];
    const updated: Deal = { ...deal, phase: 'Ganado', approvalDate: today, quotedCost: res.quotedCost };
    (updated as any).projects = [res.projectId];
    setForm(f => ({ ...f, phase: 'Ganado', approvalDate: today }));
    onSaved(updated);
  };

  // Sync form when deal prop changes from outside
  useEffect(() => {
    setForm(f => ({
      ...f,
      clientPrice: deal.clientPrice?.toString() ?? f.clientPrice,
      retencionesPct: deal.retencionesPct?.toString() ?? f.retencionesPct,
      proposalDate: deal.proposalDate ? deal.proposalDate.slice(0, 10) : f.proposalDate,
      approvalDate: deal.approvalDate ? deal.approvalDate.slice(0, 10) : f.approvalDate,
    }));
  }, [deal.clientPrice, deal.retencionesPct, deal.proposalDate, deal.approvalDate]);

  useEffect(() => {
    getUsers({}).then(d => setUsers(d.users));
  }, []);

  const sf = (k: keyof typeof form) => (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) =>
    setForm(f => ({ ...f, [k]: e.target.value }));

  const handleSave = async () => {
    setSaving(true);
    try {
      const result = await saveDeal({
        id: deal.id || undefined, dealName: form.dealName || undefined,
        phase: form.phase, client: form.client || undefined,
        projectType: form.projectType || undefined, tematica: form.tematica || undefined,
        owner: owner ? [owner] : undefined, proposalDate: form.proposalDate || undefined,
        approvalDate: form.approvalDate || undefined, currency: form.currency,
        clientPrice: form.clientPrice ? Number(form.clientPrice) : undefined,
        taxesPct: form.taxesPct ? Number(form.taxesPct) : undefined,
        retencionesPct: form.retencionesPct ? Number(form.retencionesPct) : undefined,
        quotedCost: deal.quotedCost ?? undefined,
        notes: form.notes || undefined,
      });
      const updated: Deal = {
        id: result.id, ...form, owner: owner ? [owner] : undefined,
        clientPrice: form.clientPrice ? Number(form.clientPrice) : undefined,
        taxesPct: form.taxesPct ? Number(form.taxesPct) : undefined,
        retencionesPct: form.retencionesPct ? Number(form.retencionesPct) : undefined,
        quotedCost: deal.quotedCost ?? undefined,
      };
      toast.success('Deal guardado');
      onSaved(updated);
      if (form.phase === 'Ganado' && result.id) {
        setPendingApprove({ dealId: result.id, updated });
      }
    } catch { toast.error('Error al guardar'); }
    setSaving(false);
  };

  const handleDelete = async () => {
    await deleteDeal({ id: deal.id });
    toast.success('Deal eliminado');
    onDeleted();
  };

  const userName = (u: UserItem) => [u.firstName, u.lastName].filter(Boolean).join(' ') || u.email || u.id;

  const clientPrice = form.clientPrice ? Number(form.clientPrice) : 0;
  const taxesPct = form.taxesPct ? Number(form.taxesPct) : 0;
  const retencionesPct = form.retencionesPct ? Number(form.retencionesPct) : 0;
  const impuestos = clientPrice * taxesPct / 100;
  const retenciones = clientPrice * retencionesPct / 100;
  const totalACobrar = clientPrice + impuestos - retenciones;
  const sym = getCurrencySymbol(form.currency);

  const clientSuggestions = clientFocused && form.client.length > 0
    ? existingClients.filter(c => c.toLowerCase().includes(form.client.toLowerCase()) && c !== form.client)
    : [];

  const canApprove = deal.id && APPROVE_PHASES.includes(form.phase);

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-2 gap-3">
        <div className="col-span-2 space-y-1"><Label>Nombre del deal *</Label>
          <Input value={form.dealName} onChange={sf('dealName')} placeholder="Ej: Proyecto Banco Nacional Q1" />
        </div>
        <div className="space-y-1"><Label>Fase</Label>
          <Select value={form.phase} onValueChange={v => setForm(f => ({ ...f, phase: v }))}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>{PHASE_KEYS.map(p => <SelectItem key={p} value={p}>{p}</SelectItem>)}</SelectContent>
          </Select>
        </div>
        <div className="space-y-1 relative"><Label>Cliente</Label>
          <Input
            value={form.client}
            onChange={sf('client')}
            onFocus={() => {
              if (clientBlurTimer.current) clearTimeout(clientBlurTimer.current);
              setClientFocused(true);
            }}
            onBlur={() => {
              clientBlurTimer.current = setTimeout(() => setClientFocused(false), 150);
            }}
            placeholder="Nombre del cliente..."
          />
          {clientSuggestions.length > 0 && (
            <div className="absolute z-50 mt-1 w-full bg-popover border border-border rounded-lg shadow-lg max-h-40 overflow-y-auto">
              {clientSuggestions.map(c => (
                <button
                  key={c}
                  type="button"
                  className="w-full text-left px-3 py-2 text-sm hover:bg-accent hover:text-accent-foreground transition-colors first:rounded-t-lg last:rounded-b-lg"
                  onMouseDown={e => e.preventDefault()}
                  onClick={() => {
                    setForm(f => ({ ...f, client: c }));
                    setClientFocused(false);
                  }}
                >
                  {c}
                </button>
              ))}
            </div>
          )}
        </div>
        <div className="space-y-1"><Label>Tipo de proyecto</Label>
          <Input value={form.projectType} onChange={sf('projectType')} placeholder="Cualitativo, Cuantitativo..." />
        </div>
        <div className="space-y-1"><Label>Temática</Label>
          <Input value={form.tematica} onChange={sf('tematica')} placeholder="Ej: Banca digital" />
        </div>
        <div className="space-y-1"><Label>Responsable</Label>
          <Select value={owner || '__none__'} onValueChange={v => setOwner(v === '__none__' ? '' : v)}>
            <SelectTrigger><SelectValue placeholder="Seleccionar..." /></SelectTrigger>
            <SelectContent>{users.map(u => <SelectItem key={u.id} value={u.id}>{userName(u)}</SelectItem>)}</SelectContent>
          </Select>
        </div>
        <div className="space-y-1"><Label>Moneda</Label>
          <Select value={form.currency} onValueChange={v => setForm(f => ({ ...f, currency: v }))}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>{CURRENCIES.map(c => <SelectItem key={c.value} value={c.value}>{c.label}</SelectItem>)}</SelectContent>
          </Select>
        </div>
        <div className="space-y-1"><Label>Precio a cliente</Label>
          <NumericInput
            value={clientPrice}
            onChange={v => setForm(f => ({ ...f, clientPrice: v ? String(v) : '' }))}
            min={0}
            formatDisplay={(v) => fmtMoneyFull(v, sym)}
          />
        </div>
        <div className="space-y-1"><Label>Impuestos (%)</Label>
          <NumericInput
            value={taxesPct}
            onChange={v => setForm(f => ({ ...f, taxesPct: v ? String(v) : '' }))}
            min={0}
            placeholder="16"
          />
        </div>
        <div className="space-y-1"><Label>Retenciones (%)</Label>
          <NumericInput
            value={retencionesPct}
            onChange={v => setForm(f => ({ ...f, retencionesPct: v ? String(v) : '' }))}
            min={0}
            placeholder="0"
          />
        </div>
        <div className="space-y-1"><Label>Fecha envío propuesta</Label>
          <Input type="date" value={form.proposalDate} onChange={sf('proposalDate')} />
        </div>
        <div className="space-y-1"><Label>Fecha aprobación</Label>
          <Input type="date" value={form.approvalDate} onChange={sf('approvalDate')} />
        </div>
      </div>

      {/* Financial summary */}
      {clientPrice > 0 && (
        <div className="bg-muted/20 border rounded-lg p-3 space-y-1.5 text-sm">
          <div className="flex justify-between text-muted-foreground">
            <span>Precio a cliente</span>
            <span>{fmtMoneyFull(clientPrice, sym)}</span>
          </div>
          {taxesPct > 0 && (
            <div className="flex justify-between text-muted-foreground">
              <span>+ Impuestos ({taxesPct}%)</span>
              <span>{fmtMoneyFull(impuestos, sym)}</span>
            </div>
          )}
          {retencionesPct > 0 && (
            <div className="flex justify-between text-muted-foreground">
              <span>− Retenciones ({retencionesPct}%)</span>
              <span>−{fmtMoneyFull(retenciones, sym)}</span>
            </div>
          )}
          <div className="flex justify-between font-bold text-primary border-t pt-1.5 mt-1">
            <span>= Total a cobrar</span>
            <span>{fmtMoneyFull(totalACobrar, sym)}</span>
          </div>
        </div>
      )}

      <div className="space-y-1"><Label>Notas</Label>
        <Textarea rows={2} value={form.notes} onChange={sf('notes')} />
      </div>

      {/* ── Approve Deal banner (for Cotización enviada / Negociación) ── */}
      {canApprove && (
        <div className="border rounded-xl p-4 bg-primary/5 border-primary/20">
          <div className="flex items-center justify-between gap-3">
            <div className="min-w-0">
              <p className="text-sm font-semibold text-primary flex items-center gap-1.5">
                <CheckCircle2 className="w-4 h-4 flex-shrink-0" />
                Listo para aprobar
              </p>
              <p className="text-xs text-muted-foreground mt-0.5">
                Crea el proyecto, aprueba cotizaciones y notifica a los responsables de cada rubro
              </p>
            </div>
            <Button
              size="sm"
              onClick={() => setApprovalReviewOpen(true)}
              className="gap-1.5 flex-shrink-0"
            >
              <CheckCircle2 className="w-4 h-4" />
              Aprobar Deal
            </Button>
          </div>
        </div>
      )}

      {/* ── Fallback: "Crear Proyecto" when already Ganado but no project linked ── */}
      {form.phase === 'Ganado' && deal.id && !hasLinkedProject && (
        <div className="border rounded-xl p-3 bg-muted/20 border-border flex items-center justify-between">
          <div>
            <p className="text-sm font-semibold text-foreground flex items-center gap-1.5">
              <FolderPlus className="w-4 h-4" /> Deal ganado
            </p>
            <p className="text-xs text-muted-foreground mt-0.5">
              Crea el proyecto con los datos de este deal
            </p>
          </div>
          <Button size="sm" variant="outline" onClick={handleCreateProject} disabled={creatingProject} className="gap-1.5 flex-shrink-0">
            <FolderPlus className="w-4 h-4" />
            {creatingProject ? 'Creando...' : 'Crear Proyecto'}
          </Button>
        </div>
      )}

      <div className="flex items-center justify-between pt-1">
        {deal.id && (
          <Button variant="ghost" size="sm" className="text-destructive hover:text-destructive gap-1" onClick={() => setConfirmDel(true)}>
            <Trash2 className="w-3.5 h-3.5" /> Eliminar
          </Button>
        )}
        <Button onClick={handleSave} disabled={saving} className="ml-auto">{saving ? 'Guardando...' : 'Guardar'}</Button>
      </div>

      {/* ── Aprobar Deal — review dialog ── */}
      <ApprovalReviewDialog
        open={approvalReviewOpen}
        onClose={() => setApprovalReviewOpen(false)}
        deal={deal}
        onApproved={handleApprovalSuccess}
      />

      {/* Approve included cotizaciones dialog (triggered when manually setting phase to Ganado) */}
      <AlertDialog open={!!pendingApprove} onOpenChange={o => !o && setPendingApprove(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>¿Aprobar cotizaciones incluidas?</AlertDialogTitle>
            <AlertDialogDescription>
              Las cotizaciones marcadas como "Incluida" se marcarán como <strong>Aprobadas</strong> y el costo cotizado del deal se actualizará automáticamente.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel onClick={() => setPendingApprove(null)}>No por ahora</AlertDialogCancel>
            <AlertDialogAction
              disabled={approving}
              onClick={async () => {
                if (!pendingApprove) return;
                setApproving(true);
                try {
                  const res = await approveSelectedCotizaciones({ dealId: pendingApprove.dealId });
                  toast.success(`${res.approvedCount} cotización${res.approvedCount !== 1 ? 'es' : ''} aprobada${res.approvedCount !== 1 ? 's' : ''}`);
                  onSaved({ ...pendingApprove.updated, quotedCost: res.totalCost });
                } catch { toast.error('Error al aprobar cotizaciones'); }
                setApproving(false);
                setPendingApprove(null);
              }}
            >
              {approving ? 'Aprobando...' : 'Sí, aprobar'}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      <AlertDialog open={confirmDel} onOpenChange={setConfirmDel}>
        <AlertDialogContent>
          <AlertDialogHeader><AlertDialogTitle>¿Eliminar deal?</AlertDialogTitle>
            <AlertDialogDescription>Esta acción no se puede deshacer.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancelar</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-destructive text-destructive-foreground">Eliminar</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useState, useEffect, useRef, useCallback } from 'react';
import { uploadFile } from 'zite-file-upload-sdk';
import {
  saveExpense, getExpenseLineItems, submitExpense, approveExpense,
  GetExpensesOutputType, GetPettyCashFundsOutputType,
} from 'zite-endpoints-sdk';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Plus, Trash2, Paperclip, CheckCircle2, Loader2, FileSpreadsheet, Send, CheckCheck } from 'lucide-react';
import { toast } from 'sonner';
import { useProject } from '../../context/ProjectContext';
import SearchableSelect from '@/components/SearchableSelect';
import { COST_CENTERS } from '../../lib/constants';
import { fmtCurrency } from '../../lib/format';
import ExcelImportExpenseDialog from './ExcelImportExpenseDialog';

type Expense = GetExpensesOutputType['expenses'][0];
type Fund = GetPettyCashFundsOutputType['funds'][0];

const CATEGORIES = ['Viáticos', 'Transporte', 'Alimentación', 'Hospedaje', 'Compras menores', 'Papelería', 'Materiales', 'Otros'];
const PAYMENT_METHODS = ['Caja chica', 'Tarjeta corporativa', 'Reembolso empleado'];


const STATUS_STYLES: Record<string, string> = {
  'Borrador':               'bg-muted text-muted-foreground border-transparent',
  'Enviado a aprobación':   'border-amber-300 bg-amber-50 text-amber-800',
  'Aprobado':               'border-emerald-300 bg-emerald-50 text-emerald-800',
  'Rechazado':              'border-rose-300 bg-rose-50 text-rose-800',
};

export interface LineItem {
  id?: string;
  description: string;
  category: string;
  amount: number;
  date: string;
  receipt: { url: string }[];
  notes: string;
}

function newLine(defaultDate = ''): LineItem {
  return { description: '', category: '', amount: 0, date: defaultDate, receipt: [], notes: '' };
}

const fmtNum = (n: number) => n.toLocaleString('es-MX', { minimumFractionDigits: 2, maximumFractionDigits: 2 });


interface Props {
  open: boolean;
  onClose: () => void;
  expense: Expense | null;
  funds: Fund[];
  onSaved: () => void;
  canApprove: boolean;
  userEmail: string;
  isFinanceRole: boolean;
}

type HeaderState = {
  description: string; costCenter: string; projectCode: string;
  currency: string; paymentMethod: string; pettyCashFundId: string; notes: string;
};

const EMPTY_HEADER: HeaderState = {
  description: '', costCenter: '', projectCode: '', currency: 'MXN',
  paymentMethod: '', pettyCashFundId: '', notes: '',
};

export default function ExpenseFormSheet({
  open, onClose, expense, funds, onSaved,
  canApprove, userEmail, isFinanceRole,
}: Props) {
  const { projects } = useProject();
  const [header, setHeader] = useState<HeaderState>(EMPTY_HEADER);
  const [lines, setLines] = useState<LineItem[]>([newLine()]);
  const [deletedIds, setDeletedIds] = useState<string[]>([]);
  const [saving, setSaving] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [approving, setApproving] = useState(false);
  const [loadingLines, setLoadingLines] = useState(false);
  const [uploadingIdx, setUploadingIdx] = useState<number | null>(null);
  const [excelImportOpen, setExcelImportOpen] = useState(false);

  // Tracks the saved expense ID and live status after creation/edit
  const [savedExpenseId, setSavedExpenseId] = useState<string | null>(null);
  const [savedStatus, setSavedStatus] = useState<string>('Borrador');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const pendingUploadIdx = useRef<number | null>(null);

  const today = new Date().toISOString().split('T')[0];

  useEffect(() => {
    if (!open) return;
    setDeletedIds([]);

    if (expense) {
      setSavedExpenseId(expense.id);
      setSavedStatus(expense.status ?? 'Borrador');
      setHeader({
        description: expense.description ?? '',
        costCenter: expense.costCenter ?? '',
        projectCode: expense.projectCode ?? '',
        currency: expense.currency ?? 'MXN',
        paymentMethod: expense.paymentMethod ?? '',
        pettyCashFundId: expense.pettyCashFundId ?? '',
        notes: expense.notes ?? '',
      });
      setLoadingLines(true);
      getExpenseLineItems({ expenseId: expense.id })
        .then(({ lineItems }) => {
          if (lineItems.length > 0) {
            setLines(lineItems.map(li => ({
              id: li.id,
              description: li.description ?? '',
              category: li.category ?? '',
              amount: li.amount ?? 0,
              date: li.date ?? today,
              receipt: li.receipt ?? [],
              notes: li.notes ?? '',
            })));
          } else {
            setLines([{
              id: undefined,
              description: expense.description ?? '',
              category: expense.category ?? '',
              amount: expense.amount ?? 0,
              date: expense.expenseDate ?? today,
              receipt: expense.receipt ?? [],
              notes: '',
            }]);
          }
        })
        .catch(() => setLines([newLine(today)]))
        .finally(() => setLoadingLines(false));
    } else {
      setSavedExpenseId(null);
      setSavedStatus('Borrador');
      setHeader(EMPTY_HEADER);
      setLines([newLine(today)]);
    }
  }, [open, expense?.id]);

  const setH = (k: keyof HeaderState, v: string) => setHeader(p => ({ ...p, [k]: v }));
  const updateLine = (i: number, patch: Partial<LineItem>) =>
    setLines(prev => prev.map((l, idx) => idx === i ? { ...l, ...patch } : l));
  const removeLine = (i: number) => {
    const line = lines[i];
    if (line.id) setDeletedIds(d => [...d, line.id!]);
    setLines(prev => prev.filter((_, idx) => idx !== i));
  };
  const triggerUpload = (i: number) => {
    pendingUploadIdx.current = i;
    fileInputRef.current?.click();
  };
  const handleFileChange = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    const idx = pendingUploadIdx.current;
    e.target.value = '';
    if (!file || idx === null) return;
    setUploadingIdx(idx);
    try {
      const { fileUrl } = await uploadFile({ data: file, filename: file.name });
      updateLine(idx, { receipt: [{ url: fileUrl }] });
    } catch {
      toast.error('Error al subir comprobante');
    }
    setUploadingIdx(null);
    pendingUploadIdx.current = null;
  }, []);

  const total = lines.reduce((s, l) => s + (l.amount || 0), 0);

  const handleSave = async () => {
    if (!header.description.trim() || !header.paymentMethod || !header.costCenter) {
      toast.error('Completa descripción, método de pago y centro de costos');
      return;
    }
    const validLines = lines.filter(l => l.description.trim() || l.amount > 0);
    if (validLines.length === 0) {
      toast.error('Agrega al menos una línea de gasto');
      return;
    }
    setSaving(true);
    try {
      const result = await saveExpense({
        id: savedExpenseId ?? undefined,
        description: header.description.trim(),
        paymentMethod: header.paymentMethod,
        costCenter: header.costCenter,
        projectCode: header.projectCode || undefined,
        currency: header.currency,
        notes: header.notes || undefined,
        pettyCashFundId: (header.paymentMethod === 'Caja chica' && header.pettyCashFundId) ? header.pettyCashFundId : undefined,
        lineItems: validLines.map(l => ({
          id: l.id,
          description: l.description,
          category: l.category,
          amount: l.amount,
          date: l.date || undefined,
          receipt: l.receipt.map(r => ({ url: r.url, name: r.url.split('/').pop() ?? 'comprobante' })),
          notes: l.notes || undefined,
        })),
        deletedLineItemIds: deletedIds,
      });
      // Stay open — set ID and transition to action footer
      setSavedExpenseId(result.id);
      setSavedStatus(prev => prev === 'Rechazado' ? 'Borrador' : prev); // reset if was rejected
      toast.success(savedExpenseId ? 'Cambios guardados' : 'Borrador creado');
      onSaved(); // refresh list in background, but don't close
    } catch (e: unknown) {
      toast.error((e as { message?: string })?.message ?? 'Error al guardar');
    }
    setSaving(false);
  };

  const handleSubmit = async () => {
    if (!savedExpenseId) return;
    setSubmitting(true);
    try {
      await submitExpense({ id: savedExpenseId });
      setSavedStatus('Enviado a aprobación');
      toast.success('Gasto enviado a aprobación');
      onSaved();
    } catch (e: unknown) {
      toast.error((e as { message?: string })?.message ?? 'Error al enviar');
    }
    setSubmitting(false);
  };

  const handleApprove = async () => {
    if (!savedExpenseId) return;
    setApproving(true);
    try {
      await approveExpense({ id: savedExpenseId });
      setSavedStatus('Aprobado');
      toast.success('Gasto aprobado');
      onSaved();
    } catch (e: unknown) {
      toast.error((e as { message?: string })?.message ?? 'Error al aprobar');
    }
    setApproving(false);
  };

  const handleClose = () => { onSaved(); onClose(); };

  // Determine if editing is allowed
  const canEdit = !savedExpenseId
    || savedStatus === 'Borrador'
    || savedStatus === 'Rechazado';

  // Build footer
  const isNew = !savedExpenseId;
  const isOwner = !expense?.createdBy || expense.createdBy === userEmail;

  return (
    <Dialog open={open} onOpenChange={v => { if (!v) handleClose(); }}>
      <DialogContent className="max-w-4xl max-h-[90vh] flex flex-col p-0 gap-0">
        <DialogHeader className="px-6 pt-5 pb-4 border-b border-border flex-shrink-0">
          <div className="flex items-center gap-3">
            <DialogTitle className="text-base">
              {expense ? 'Editar gasto' : savedExpenseId ? 'Gasto creado' : 'Nuevo gasto'}
            </DialogTitle>
            {savedExpenseId && savedStatus && (
              <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium border ${STATUS_STYLES[savedStatus] ?? 'bg-muted text-muted-foreground border-transparent'}`}>
                {savedStatus}
              </span>
            )}
          </div>
        </DialogHeader>

        <ScrollArea className="flex-1 min-h-0">
          <div className="px-6 py-5 space-y-5">

            {/* Header fields */}
            <div className="grid grid-cols-2 gap-3">
              <div className="col-span-2 space-y-1.5">
                <Label className="text-xs font-medium">Título del gasto *</Label>
                <Input value={header.description} onChange={e => setH('description', e.target.value)}
                  placeholder='Ej: "Viaje a EEUU — Proyecto Kraft"'
                  className="h-9 text-sm" autoFocus disabled={!canEdit} />
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs font-medium">Método de pago *</Label>
                <Select value={header.paymentMethod} onValueChange={v => setH('paymentMethod', v)} disabled={!canEdit}>
                  <SelectTrigger className="h-9 text-sm"><SelectValue placeholder="Seleccionar..." /></SelectTrigger>
                  <SelectContent>{PAYMENT_METHODS.map(m => <SelectItem key={m} value={m}>{m}</SelectItem>)}</SelectContent>
                </Select>
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs font-medium">Centro de costos *</Label>
                <Select value={header.costCenter} onValueChange={v => setH('costCenter', v)} disabled={!canEdit}>
                  <SelectTrigger className="h-9 text-sm"><SelectValue placeholder="Seleccionar..." /></SelectTrigger>
                  <SelectContent>{COST_CENTERS.map(c => <SelectItem key={c} value={c}>{c}</SelectItem>)}</SelectContent>
                </Select>
              </div>
              {header.paymentMethod === 'Caja chica' && (
                <div className="space-y-1.5">
                  <Label className="text-xs font-medium">Fondo de caja chica</Label>
                  <Select value={header.pettyCashFundId} onValueChange={v => setH('pettyCashFundId', v)} disabled={!canEdit}>
                    <SelectTrigger className="h-9 text-sm"><SelectValue placeholder="Seleccionar fondo..." /></SelectTrigger>
                    <SelectContent>
                      {funds.map(f => <SelectItem key={f.id} value={f.id}>{f.fundName} — {fmtCurrency(f.currentBalance ?? undefined)}</SelectItem>)}
                    </SelectContent>
                  </Select>
                </div>
              )}
              <div className="space-y-1.5">
                <Label className="text-xs font-medium">Proyecto</Label>
                <SearchableSelect
                  value={header.projectCode || '__none__'}
                  onChange={v => setH('projectCode', v === '__none__' ? '' : v)}
                  options={[{ value: '__none__', label: 'Sin proyecto' }, ...projects.map(p => ({ value: p.projectCode ?? '', label: p.projectCode ?? '', sub: p.fullName ?? '' }))]}
                  placeholder="Sin proyecto"
                  className="w-full h-9 text-sm"
                />

              </div>
              <div className="space-y-1.5">
                <Label className="text-xs font-medium">Moneda</Label>
                <Select value={header.currency} onValueChange={v => setH('currency', v)} disabled={!canEdit}>
                  <SelectTrigger className="h-9 text-sm"><SelectValue /></SelectTrigger>
                  <SelectContent><SelectItem value="MXN">MXN</SelectItem><SelectItem value="USD">USD</SelectItem></SelectContent>
                </Select>
              </div>
              <div className="col-span-2 space-y-1.5">
                <Label className="text-xs font-medium">Notas</Label>
                <Textarea value={header.notes} onChange={e => setH('notes', e.target.value)}
                  placeholder="Contexto adicional..." className="text-sm resize-none min-h-[56px]"
                  disabled={!canEdit} />
              </div>
            </div>

            {/* Line items */}
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <Label className="text-xs font-medium">Partidas del gasto</Label>
                {canEdit && (
                  <div className="flex items-center gap-2">
                    <Button variant="ghost" size="sm" className="h-7 text-xs gap-1 text-muted-foreground hover:text-primary"
                      onClick={() => setExcelImportOpen(true)}>
                      <FileSpreadsheet className="w-3 h-3" /> Importar Excel
                    </Button>
                    <Button variant="ghost" size="sm" className="h-7 text-xs gap-1 text-primary"
                      onClick={() => setLines(p => [...p, newLine(today)])}>
                      <Plus className="w-3 h-3" /> Agregar línea
                    </Button>
                  </div>
                )}
              </div>

              {loadingLines ? (
                <div className="h-20 flex items-center justify-center text-sm text-muted-foreground">
                  <Loader2 className="w-4 h-4 animate-spin mr-2" /> Cargando partidas...
                </div>
              ) : (
                <div className="border border-border rounded-lg overflow-hidden">
                  <table className="w-full text-xs">
                    <thead className="bg-muted/50 border-b border-border">
                      <tr>
                        <th className="text-left px-3 py-2 font-medium text-muted-foreground">Descripción</th>
                        <th className="text-left px-3 py-2 font-medium text-muted-foreground w-36">Categoría</th>
                        <th className="text-left px-3 py-2 font-medium text-muted-foreground w-32">Fecha</th>
                        <th className="text-right px-3 py-2 font-medium text-muted-foreground w-28">Monto</th>
                        <th className="text-center px-3 py-2 font-medium text-muted-foreground w-20">Comprobante</th>
                        {canEdit && <th className="w-8" />}
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-border">
                      {lines.map((line, i) => (
                        <LineRow
                          key={i}
                          line={line}
                          uploading={uploadingIdx === i}
                          onChange={patch => updateLine(i, patch)}
                          onRemove={() => removeLine(i)}
                          onUpload={() => triggerUpload(i)}
                          canRemove={lines.length > 1}
                          readOnly={!canEdit}
                        />
                      ))}
                    </tbody>
                    <tfoot className="bg-muted/30 border-t border-border">
                      <tr>
                        <td colSpan={3} className="px-3 py-2 text-right text-xs font-semibold text-muted-foreground">
                          Total {header.currency}
                        </td>
                        <td className="px-3 py-2 text-right text-sm font-bold">{fmtNum(total)}</td>
                        <td colSpan={canEdit ? 2 : 1} />
                      </tr>
                    </tfoot>
                  </table>
                </div>
              )}
            </div>
          </div>
        </ScrollArea>

        {/* ── Footer ── */}
        <div className="px-6 py-4 border-t border-border flex-shrink-0 flex items-center gap-2">
          {/* Left: status info after save */}
          <div className="flex-1">
            {savedExpenseId && savedStatus === 'Borrador' && (
              <p className="text-xs text-muted-foreground">Guardado como borrador. ¿Listo para enviarlo?</p>
            )}
            {savedExpenseId && savedStatus === 'Enviado a aprobación' && !canApprove && (
              <p className="text-xs text-muted-foreground">En espera de aprobación.</p>
            )}
            {savedExpenseId && savedStatus === 'Aprobado' && (
              <p className="text-xs text-emerald-600 font-medium flex items-center gap-1">
                <CheckCheck className="w-3.5 h-3.5" /> Gasto aprobado.
              </p>
            )}
          </div>

          {/* Right: action buttons */}
          <div className="flex items-center gap-2">
            {/* CASE 1: New, not yet saved */}
            {isNew && (
              <>
                <Button variant="ghost" size="sm" onClick={handleClose} disabled={saving}>Cancelar</Button>
                <Button size="sm" onClick={handleSave} disabled={saving || loadingLines} className="min-w-[130px]">
                  {saving
                    ? <><Loader2 className="w-3.5 h-3.5 animate-spin mr-1.5" />Guardando...</>
                    : 'Crear borrador'}
                </Button>
              </>
            )}

            {/* CASE 2: Existing expense — Borrador or Rechazado (editable) */}
            {savedExpenseId && (savedStatus === 'Borrador' || savedStatus === 'Rechazado') && (
              <>
                <Button variant="ghost" size="sm" onClick={handleClose} disabled={saving || submitting || approving}>
                  Cerrar
                </Button>
                <Button variant="outline" size="sm" onClick={handleSave} disabled={saving || loadingLines} className="min-w-[130px]">
                  {saving
                    ? <><Loader2 className="w-3.5 h-3.5 animate-spin mr-1.5" />Guardando...</>
                    : 'Guardar cambios'}
                </Button>
                {(isOwner || isFinanceRole) && (
                  <Button size="sm" onClick={handleSubmit} disabled={submitting || saving} className="gap-1.5">
                    {submitting
                      ? <><Loader2 className="w-3.5 h-3.5 animate-spin" />Enviando...</>
                      : <><Send className="w-3.5 h-3.5" />Enviar a aprobación</>}
                  </Button>
                )}
                {canApprove && (
                  <Button size="sm" onClick={handleApprove} disabled={approving || saving}
                    className="gap-1.5 bg-emerald-600 hover:bg-emerald-700 text-white">
                    {approving
                      ? <><Loader2 className="w-3.5 h-3.5 animate-spin" />Aprobando...</>
                      : <><CheckCheck className="w-3.5 h-3.5" />Aprobar</>}
                  </Button>
                )}
              </>
            )}

            {/* CASE 3: Enviado a aprobación */}
            {savedExpenseId && savedStatus === 'Enviado a aprobación' && (
              <>
                <Button variant="ghost" size="sm" onClick={handleClose} disabled={approving}>Cerrar</Button>
                {canApprove && (
                  <Button size="sm" onClick={handleApprove} disabled={approving}
                    className="gap-1.5 bg-emerald-600 hover:bg-emerald-700 text-white">
                    {approving
                      ? <><Loader2 className="w-3.5 h-3.5 animate-spin" />Aprobando...</>
                      : <><CheckCheck className="w-3.5 h-3.5" />Aprobar</>}
                  </Button>
                )}
              </>
            )}

            {/* CASE 4: Aprobado or terminal state */}
            {savedExpenseId && (savedStatus === 'Aprobado') && (
              <Button size="sm" onClick={handleClose}>Cerrar</Button>
            )}
          </div>
        </div>

        <input ref={fileInputRef} type="file" className="hidden" accept="image/*,.pdf,.xlsx,.xls"
          onChange={handleFileChange} />
      </DialogContent>

      <ExcelImportExpenseDialog
        open={excelImportOpen}
        onClose={() => setExcelImportOpen(false)}
        defaultDate={today}
        onImport={imported => {
          setLines(prev => {
            const isEmpty = prev.length === 1 && !prev[0].description && prev[0].amount === 0;
            return isEmpty ? imported : [...prev, ...imported];
          });
        }}
      />
    </Dialog>
  );
}

// ── LineRow sub-component ─────────────────────────────────────────────────────
interface LineRowProps {
  line: LineItem;
  uploading: boolean;
  onChange: (patch: Partial<LineItem>) => void;
  onRemove: () => void;
  onUpload: () => void;
  canRemove: boolean;
  readOnly: boolean;
}

function LineRow({ line, uploading, onChange, onRemove, onUpload, canRemove, readOnly }: LineRowProps) {
  const hasReceipt = line.receipt.length > 0;
  const receiptUrl = line.receipt[0]?.url;
  const isImg = receiptUrl ? /\.(png|jpg|jpeg|gif|webp)$/i.test(receiptUrl) : false;
  const [isDragging, setIsDragging] = useState(false);

  const handleDrop = async (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (readOnly) return;
    const file = e.dataTransfer.files?.[0];
    if (!file) return;
    try {
      const { fileUrl } = await uploadFile({ data: file, filename: file.name });
      onChange({ receipt: [{ url: fileUrl }] });
    } catch {
      toast.error('Error al subir comprobante');
    }
  };

  return (
    <tr className="hover:bg-muted/20 transition-colors">
      <td className="px-2 py-1.5">
        <Input className="h-7 text-xs border-0 focus-visible:ring-0 bg-transparent min-w-[140px]"
          value={line.description} onChange={e => onChange({ description: e.target.value })}
          placeholder="Descripción..." disabled={readOnly} />
      </td>
      <td className="px-2 py-1.5">
        <select
          value={line.category}
          onChange={e => onChange({ category: e.target.value })}
          disabled={readOnly}
          className="w-full h-7 text-xs bg-transparent border-0 focus:outline-none focus:ring-0 text-foreground disabled:opacity-50"
        >
          <option value="">Categoría...</option>
          {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
        </select>
      </td>
      <td className="px-2 py-1.5">
        <Input type="date" className="h-7 text-xs border-0 focus-visible:ring-0 bg-transparent w-28"
          value={line.date} onChange={e => onChange({ date: e.target.value })} disabled={readOnly} />
      </td>
      <td className="px-2 py-1.5">
        <Input type="number" min="0" step="0.01"
          className="h-7 text-xs border-0 focus-visible:ring-0 bg-transparent text-right w-24"
          value={line.amount === 0 ? '' : line.amount}
          placeholder="0.00"
          onChange={e => onChange({ amount: e.target.value === '' ? 0 : Number(e.target.value) })}
          disabled={readOnly} />
      </td>
      <td
        className={`px-2 py-1.5 text-center rounded transition-colors ${isDragging && !readOnly ? 'bg-primary/10 outline outline-2 outline-primary outline-offset-[-2px]' : ''}`}
        onDragOver={e => { e.preventDefault(); if (!readOnly) setIsDragging(true); }}
        onDragEnter={e => { e.preventDefault(); if (!readOnly) setIsDragging(true); }}
        onDragLeave={e => { e.preventDefault(); setIsDragging(false); }}
        onDrop={handleDrop}
      >
        {uploading ? (
          <Loader2 className="w-4 h-4 animate-spin text-muted-foreground mx-auto" />
        ) : hasReceipt ? (
          <div className="flex items-center justify-center gap-1">
            <a href={receiptUrl} target="_blank" rel="noopener noreferrer" title="Ver comprobante">
              {isImg
                ? <img src={receiptUrl} alt="comp" className="w-6 h-6 rounded object-cover border border-border" />
                : <Paperclip className="w-4 h-4 text-primary" />
              }
            </a>
            <CheckCircle2 className="w-3 h-3 text-emerald-500 flex-shrink-0" />
          </div>
        ) : !readOnly ? (
          <button onClick={onUpload}
            className="flex items-center justify-center mx-auto w-7 h-7 rounded hover:bg-muted transition-colors text-muted-foreground hover:text-foreground">
            <Paperclip className="w-3.5 h-3.5" />
          </button>
        ) : null}
      </td>
      {!readOnly && (
        <td className="px-1 py-1.5 text-center">
          <button onClick={onRemove} disabled={!canRemove}
            className="flex items-center justify-center w-6 h-6 rounded hover:bg-destructive/10 text-muted-foreground hover:text-destructive disabled:opacity-20 transition-colors mx-auto">
            <Trash2 className="w-3 h-3" />
          </button>
        </td>
      )}
    </tr>
  );
}

import { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Accordion } from '@/components/ui/accordion';
import { Badge } from '@/components/ui/badge';
import { Pencil } from 'lucide-react';
import { getCotizacionLineItems, GetCotizacionesOutputType, saveCotizacion, saveQuotationLineItems } from 'zite-endpoints-sdk';
import { toast } from 'sonner';
import { RUBROS, COTIZ_STATUSES, COTIZ_CURRENCIES, getCurrencySymbol, fmtMoneyFull } from './dealUtils';
import CotizacionRubroSection, { type LineItemLocal, calcFinal, calcBase } from './CotizacionRubroSection';

type Cotizacion = GetCotizacionesOutputType['cotizaciones'][0];

interface Props {
  cotizacion: Cotizacion | null;
  dealId: string;
  isOpen: boolean;
  viewOnly?: boolean;
  onClose: () => void;
  onSaved: () => void;
}

type RubroMap = Record<string, LineItemLocal[]>;

export default function CotizacionModal({ cotizacion, dealId, isOpen, viewOnly = false, onClose, onSaved }: Props) {
  const [form, setForm] = useState({ cotizacionName: '', status: 'Borrador', currency: 'MXN', notes: '' });
  const [rubroItems, setRubroItems] = useState<RubroMap>({});
  const [saving, setSaving] = useState(false);
  const [isViewMode, setIsViewMode] = useState(viewOnly);

  // Reset view mode when modal opens
  useEffect(() => {
    if (isOpen) setIsViewMode(viewOnly);
  }, [isOpen, viewOnly]);

  useEffect(() => {
    if (!isOpen) return;
    if (cotizacion) {
      setForm({
        cotizacionName: cotizacion.cotizacionName ?? '',
        status: cotizacion.status ?? 'Borrador',
        currency: cotizacion.currency ?? 'MXN',
        notes: cotizacion.notes ?? '',
      });
      getCotizacionLineItems({ cotizacionId: cotizacion.id }).then(data => {
        const grouped: RubroMap = {};
        data.lineItems.forEach(li => {
          const r = li.rubro ?? RUBROS[0];
          if (!grouped[r]) grouped[r] = [];
          grouped[r].push({
            localId: li.id, subRubro: li.subRubro ?? '', cantidad: li.cantidad ?? 0,
            componentes: li.componentes ?? 0, unitCost: li.unitCost ?? 0,
            hasMarkup: li.hasMarkup ?? false, markupPct: li.markupPct ?? 0,
          });
        });
        setRubroItems(grouped);
      });
    } else {
      setForm({ cotizacionName: '', status: 'Borrador', currency: 'MXN', notes: '' });
      const mk = (subRubro: string, hasMarkup: boolean, markupPct: number): LineItemLocal => ({
        localId: Math.random().toString(36).slice(2), subRubro, cantidad: 0, componentes: 0, unitCost: 0, hasMarkup, markupPct,
      });
      setRubroItems({
        'Reclutamiento e incentivos': [mk('Reclutamiento', true, 50), mk('Incentivos', true, 50)],
        'Moderación': [mk('Moderación', true, 50)],
        'Management': [mk('Management Cuali', true, 50)],
        'Logística y operación': [mk('Renta de cámaras', false, 0), mk('Traducción', false, 0), mk('Viáticos', false, 0), mk('Transporte', false, 0)],
        'Back office': [mk('Seguimiento', true, 50)],
      });
    }
  }, [isOpen, cotizacion]);

  const allItems = Object.entries(rubroItems).flatMap(([rubro, items]) =>
    items.map(item => ({ ...item, rubro, finalPrice: calcFinal(item) }))
  );
  const totalCost = allItems.reduce((s, i) => s + calcBase(i), 0);
  const totalWithMarkup = allItems.reduce((s, i) => s + i.finalPrice, 0);
  const sym = getCurrencySymbol(form.currency);

  // In view mode, only show rubros that have items with actual data
  const visibleRubros = isViewMode
    ? RUBROS.filter(r => (rubroItems[r] ?? []).some(i => i.cantidad > 0 || i.unitCost > 0))
    : RUBROS;

  const handleSave = async () => {
    setSaving(true);
    try {
      const result = await saveCotizacion({
        id: cotizacion?.id,
        cotizacionName: form.cotizacionName || undefined,
        deal: cotizacion?.id ? undefined : [dealId],
        status: form.status,
        currency: form.currency,
        notes: form.notes || undefined,
      });
      const cotizId = cotizacion?.id ?? result.id;
      await saveQuotationLineItems({
        cotizacionId: cotizId,
        lineItems: allItems.map(({ localId: _lid, ...rest }) => rest),
        totalCost: totalWithMarkup,
      });
      toast.success('Cotización guardada');
      onSaved();
      onClose();
    } catch { toast.error('Error al guardar cotización'); }
    setSaving(false);
  };

  return (
    <Dialog open={isOpen} onOpenChange={o => !o && onClose()}>
      <DialogContent className="max-w-4xl max-h-[90vh] flex flex-col gap-0 p-0">
        <DialogHeader className="px-6 py-4 border-b flex-shrink-0">
          <div className="flex items-center gap-3">
            <DialogTitle>
              {isViewMode
                ? (form.cotizacionName || 'Sin nombre')
                : (cotizacion ? 'Editar cotización' : 'Nueva cotización')}
            </DialogTitle>
            {isViewMode && (
              <Badge variant="outline" className="text-xs font-normal">
                {form.status}
              </Badge>
            )}
          </div>
        </DialogHeader>

        <div className="overflow-y-auto flex-1 px-6 py-4 space-y-4">
          {isViewMode ? (
            /* View mode header */
            <div className="flex items-center gap-4 text-sm text-muted-foreground">
              <span>Moneda: <strong className="text-foreground">{form.currency}</strong></span>
              {form.notes && (
                <span className="flex-1 truncate">Notas: <em>{form.notes}</em></span>
              )}
            </div>
          ) : (
            /* Edit mode header fields */
            <div className="grid grid-cols-3 gap-3">
              <div className="space-y-1"><Label>Nombre</Label>
                <Input value={form.cotizacionName} onChange={e => setForm(f => ({ ...f, cotizacionName: e.target.value }))} placeholder="Cotización v1" />
              </div>
              <div className="space-y-1"><Label>Status</Label>
                <Select value={form.status} onValueChange={v => setForm(f => ({ ...f, status: v }))}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>{COTIZ_STATUSES.map(s => <SelectItem key={s} value={s}>{s}</SelectItem>)}</SelectContent>
                </Select>
              </div>
              <div className="space-y-1"><Label>Moneda</Label>
                <Select value={form.currency} onValueChange={v => setForm(f => ({ ...f, currency: v }))}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>{COTIZ_CURRENCIES.map(c => <SelectItem key={c.value} value={c.value}>{c.label}</SelectItem>)}</SelectContent>
                </Select>
              </div>
            </div>
          )}

          {/* Rubros */}
          {visibleRubros.length > 0 ? (
            <Accordion type="multiple" defaultValue={[...visibleRubros]} className="space-y-0">
              {visibleRubros.map(rubro => (
                <CotizacionRubroSection
                  key={rubro}
                  rubro={rubro}
                  items={rubroItems[rubro] ?? []}
                  currencySymbol={sym}
                  readOnly={isViewMode}
                  onUpdate={items => setRubroItems(prev => ({ ...prev, [rubro]: items }))}
                />
              ))}
            </Accordion>
          ) : isViewMode ? (
            <p className="text-sm text-muted-foreground text-center py-6">Sin rubros con datos.</p>
          ) : null}

          {/* Totals & notes */}
          <div className="border rounded-lg p-4 space-y-3 bg-muted/20">
            <div className="flex items-center justify-between text-sm text-muted-foreground">
              <span>Costo base</span>
              <span className="tabular-nums">{fmtMoneyFull(totalCost, sym)}</span>
            </div>
            <div className="flex items-center justify-between border-t pt-2">
              <span className="text-sm font-semibold">Precio con markup</span>
              <span className="text-lg font-bold">{fmtMoneyFull(totalWithMarkup, sym)}</span>
            </div>
            {!isViewMode && (
              <div className="space-y-1"><Label>Notas</Label>
                <Textarea rows={2} value={form.notes} onChange={e => setForm(f => ({ ...f, notes: e.target.value }))} />
              </div>
            )}
            {isViewMode && form.notes && (
              <div className="text-sm text-muted-foreground border-t pt-2">
                <span className="font-medium text-foreground">Notas:</span> {form.notes}
              </div>
            )}
          </div>
        </div>

        <DialogFooter className="px-6 py-4 border-t flex-shrink-0">
          {isViewMode ? (
            <>
              <Button variant="outline" onClick={onClose}>Cerrar</Button>
              <Button onClick={() => setIsViewMode(false)} className="gap-1.5">
                <Pencil className="w-4 h-4" /> Editar
              </Button>
            </>
          ) : (
            <>
              <Button variant="outline" onClick={onClose}>Cancelar</Button>
              <Button onClick={handleSave} disabled={saving}>{saving ? 'Guardando...' : 'Guardar cotización'}</Button>
            </>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect } from 'react';
import { getCotizaciones, GetCotizacionesOutputType, deleteCotizacion, saveCotizacion, saveDeal, duplicateCotizacion } from 'zite-endpoints-sdk';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { Plus, Pencil, Trash2, CheckCircle2, Copy, Loader2 } from 'lucide-react';
import { Skeleton } from '@/components/ui/skeleton';
import { toast } from 'sonner';
import { COTIZ_STATUS_COLORS, getCurrencySymbol, fmtMoney, fmtMoneyFull } from './dealUtils';
import CotizacionModal from './CotizacionModal';
import NumericInput from '@/components/NumericInput';

type Cotizacion = GetCotizacionesOutputType['cotizaciones'][0];

interface Props {
  dealId: string;
  dealCurrency?: string;
  dealClientPrice?: number;
  dealQuotedCost?: number;
  dealTaxesPct?: number;
  dealRetencionesPct?: number;
  onDealFieldUpdated: (fields: { clientPrice?: number; quotedCost?: number }) => void;
}

export default function CotizacionesTab({ dealId, dealCurrency, dealClientPrice, dealQuotedCost: _dqc, dealTaxesPct, dealRetencionesPct, onDealFieldUpdated }: Props) {
  const [cotizaciones, setCotizaciones] = useState<Cotizacion[]>([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editing, setEditing] = useState<Cotizacion | null>(null);
  const [viewOnly, setViewOnly] = useState(false);
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [duplicatingId, setDuplicatingId] = useState<string | null>(null);

  const load = async () => {
    setLoading(true);
    try { const d = await getCotizaciones({ dealId }); setCotizaciones(d.cotizaciones); }
    finally { setLoading(false); }
  };

  useEffect(() => { load(); }, [dealId]);

  const calcAndSaveQuotedCost = (list: Cotizacion[]) => {
    const total = list.filter(c => c.included).reduce((s, c) => s + (c.clientPrice ?? c.totalCost ?? 0), 0);
    onDealFieldUpdated({ quotedCost: total });
    saveDeal({ id: dealId, quotedCost: total }).catch(() => {});
  };

  const handleApprove = async (c: Cotizacion) => {
    await saveCotizacion({ id: c.id, status: 'Aprobada' });
    toast.success('Cotización marcada como aprobada');
    load();
  };

  const handleToggleIncluded = (c: Cotizacion, value: boolean) => {
    const updated = cotizaciones.map(x => x.id === c.id ? { ...x, included: value } : x);
    setCotizaciones(updated);
    calcAndSaveQuotedCost(updated);
    saveCotizacion({ id: c.id, included: value }).catch(() => toast.error('Error al actualizar'));
  };

  const handleDuplicate = async (id: string) => {
    setDuplicatingId(id);
    try {
      const result = await duplicateCotizacion({ cotizacionId: id });
      toast.success(`Cotización duplicada · ${result.lineItemsCopied} partida${result.lineItemsCopied !== 1 ? 's' : ''} copiada${result.lineItemsCopied !== 1 ? 's' : ''}`);
      const d = await getCotizaciones({ dealId });
      setCotizaciones(d.cotizaciones);
      calcAndSaveQuotedCost(d.cotizaciones);
    } catch {
      toast.error('Error al duplicar la cotización');
    } finally {
      setDuplicatingId(null);
    }
  };

  const handleDelete = async () => {
    if (!deletingId) return;
    await deleteCotizacion({ id: deletingId });
    toast.success('Cotización eliminada');
    setDeletingId(null);
    const d = await getCotizaciones({ dealId });
    setCotizaciones(d.cotizaciones);
    calcAndSaveQuotedCost(d.cotizaciones);
  };

  const handleClientPriceChange = (val: number) => {
    onDealFieldUpdated({ clientPrice: val });
    saveDeal({ id: dealId, clientPrice: val }).catch(() => {});
  };

  const openView = (c: Cotizacion) => { setEditing(c); setViewOnly(true); setShowModal(true); };
  const openEdit = (c: Cotizacion) => { setEditing(c); setViewOnly(false); setShowModal(true); };
  const openNew = () => { setEditing(null); setViewOnly(false); setShowModal(true); };

  if (loading) return <Skeleton className="h-40 w-full" />;

  const included = cotizaciones.filter(c => c.included);
  const includedTotal = included.reduce((s, c) => s + (c.totalCost ?? 0), 0);
  const includedClientTotal = included.reduce((s, c) => s + (c.clientPrice ?? 0), 0);
  const defaultSym = getCurrencySymbol(dealCurrency);
  const cp = dealClientPrice ?? 0;
  const impuestos = cp * (dealTaxesPct ?? 0) / 100;
  const retenciones = cp * (dealRetencionesPct ?? 0) / 100;
  const totalACobrar = cp + impuestos - retenciones;

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <span className="text-sm text-muted-foreground">
          {cotizaciones.length} cotizacion{cotizaciones.length !== 1 ? 'es' : ''}
          {included.length > 0 && ` · ${included.length} incluida${included.length !== 1 ? 's' : ''}`}
        </span>
        <Button size="sm" onClick={openNew} className="gap-1.5"><Plus className="w-4 h-4" /> Nueva cotización</Button>
      </div>

      {/* Totals + Precio a cliente */}
      <div className="border rounded-xl px-4 py-3 bg-primary/5 border-primary/20 space-y-3">
        <div className="flex items-center justify-between">
          <span className="text-sm font-medium text-muted-foreground">
            Costo total incluido ({included.length} cotizacion{included.length !== 1 ? 'es' : ''})
          </span>
          <span className="text-base font-bold" style={{ color: 'hsl(var(--primary))' }}>
            {fmtMoneyFull(includedTotal, defaultSym)}
          </span>
        </div>
        {includedClientTotal > 0 && (
          <div className="flex items-center justify-between">
            <span className="text-sm font-medium text-muted-foreground">
              Costo con mark up
            </span>
            <span className="text-base font-bold text-foreground">
              {fmtMoneyFull(includedClientTotal, defaultSym)}
            </span>
          </div>
        )}
        <div className="border-t pt-3 flex items-center gap-3">
          <Label className="text-sm font-semibold whitespace-nowrap">Precio a cliente</Label>
          <div className="flex items-center gap-1.5 flex-1">
            <span className="text-sm text-muted-foreground">{defaultSym}</span>
            <NumericInput
              value={dealClientPrice ?? 0}
              onChange={handleClientPriceChange}
              min={0}
              className="flex-1"
              formatDisplay={(v) => fmtMoneyFull(v, defaultSym)}
            />
            <span className="text-xs text-muted-foreground">{dealCurrency?.split(' ')[0] ?? ''}</span>
          </div>
        </div>
        {cp > 0 && (
          <div className="border-t pt-3 space-y-1 text-sm">
            {(dealTaxesPct ?? 0) > 0 && (
              <div className="flex justify-between text-muted-foreground">
                <span>+ Impuestos ({dealTaxesPct}%)</span>
                <span>{fmtMoneyFull(impuestos, defaultSym)}</span>
              </div>
            )}
            {(dealRetencionesPct ?? 0) > 0 && (
              <div className="flex justify-between text-muted-foreground">
                <span>− Retenciones ({dealRetencionesPct}%)</span>
                <span>−{fmtMoneyFull(retenciones, defaultSym)}</span>
              </div>
            )}
            {((dealTaxesPct ?? 0) > 0 || (dealRetencionesPct ?? 0) > 0) && (
              <div className="flex justify-between font-bold text-primary border-t pt-1">
                <span>= Total a cobrar</span>
                <span>{fmtMoneyFull(totalACobrar, defaultSym)}</span>
              </div>
            )}
          </div>
        )}
      </div>

      <div className="space-y-2">
        {cotizaciones.map(c => {
          const color = COTIZ_STATUS_COLORS[c.status ?? ''] ?? 'hsl(var(--muted-foreground))';
          const sym = getCurrencySymbol(c.currency ?? dealCurrency);
          const isApproved = c.status === 'Aprobada';
          const isIncluded = c.included ?? false;
          return (
            <div
              key={c.id}
              className={`border rounded-xl p-4 transition-colors cursor-pointer ${
                isIncluded && isApproved ? 'bg-emerald-50 border-emerald-400 dark:bg-emerald-950/30 dark:border-emerald-700 hover:brightness-95' :
                isIncluded ? 'bg-emerald-50/60 border-emerald-200 dark:bg-emerald-950/20 dark:border-emerald-800 hover:brightness-95' :
                isApproved ? 'bg-primary/5 border-primary/30 hover:bg-primary/10' :
                'bg-card hover:bg-muted/20'
              }`}
              onClick={() => openView(c)}
            >
              <div className="flex items-start justify-between gap-2">
                <div className="min-w-0 flex-1">
                  <div className="flex items-center gap-2 flex-wrap">
                    {isApproved && <CheckCircle2 className="w-4 h-4 flex-shrink-0" style={{ color: 'hsl(var(--chart-2))' }} />}
                    <span className="font-semibold text-sm">{c.cotizacionName || 'Sin nombre'}</span>
                    <span className="px-2 py-0.5 rounded-full text-xs font-medium" style={{ backgroundColor: color + '22', color }}>
                      {c.status}
                    </span>
                  </div>
                  <div className="mt-1 text-xs text-muted-foreground flex items-center gap-3 flex-wrap">
                    {c.totalCost != null && <span>Costo: <strong>{fmtMoney(c.totalCost, sym)}</strong></span>}
                    {c.clientPrice != null && <span>Con markup: <strong>{fmtMoney(c.clientPrice, sym)}</strong></span>}
                    {c.currency && <span className="text-muted-foreground/60">{c.currency}</span>}
                  </div>
                </div>

                <div className="flex items-center gap-2 flex-shrink-0" onClick={e => e.stopPropagation()}>
                  <div className="flex items-center gap-1.5 mr-1">
                    <span className="text-xs text-muted-foreground">Incluida</span>
                    <Switch
                      checked={isIncluded}
                      onCheckedChange={v => handleToggleIncluded(c, v)}
                    />
                  </div>
                  {!isApproved && (
                    <Button size="sm" variant="outline" className="h-7 text-xs gap-1" onClick={() => handleApprove(c)}>
                      <CheckCircle2 className="w-3 h-3" /> Aprobar
                    </Button>
                  )}
                  <Button size="icon" variant="ghost" className="h-7 w-7" onClick={() => openEdit(c)}>
                    <Pencil className="w-3 h-3" />
                  </Button>
                  <Button size="icon" variant="ghost" className="h-7 w-7" disabled={duplicatingId === c.id} onClick={e => { e.stopPropagation(); handleDuplicate(c.id); }}>
                    {duplicatingId === c.id ? <Loader2 className="w-3 h-3 animate-spin" /> : <Copy className="w-3 h-3" />}
                  </Button>
                  <Button size="icon" variant="ghost" className="h-7 w-7 text-destructive" onClick={() => setDeletingId(c.id)}>
                    <Trash2 className="w-3 h-3" />
                  </Button>
                </div>
              </div>
            </div>
          );
        })}
        {cotizaciones.length === 0 && (
          <div className="text-center py-12 text-muted-foreground text-sm border-2 border-dashed rounded-xl">
            Sin cotizaciones. Crea la primera.
          </div>
        )}
      </div>

      <CotizacionModal
        cotizacion={editing}
        dealId={dealId}
        isOpen={showModal}
        viewOnly={viewOnly}
        onClose={() => { setShowModal(false); setEditing(null); }}
        onSaved={async () => {
          setShowModal(false);
          setEditing(null);
          const d = await getCotizaciones({ dealId });
          setCotizaciones(d.cotizaciones);
          calcAndSaveQuotedCost(d.cotizaciones);
        }}
      />

      <AlertDialog open={!!deletingId} onOpenChange={o => !o && setDeletingId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader><AlertDialogTitle>¿Eliminar cotización?</AlertDialogTitle>
            <AlertDialogDescription>Esta acción no se puede deshacer.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancelar</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-destructive text-destructive-foreground">Eliminar</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Button } from '@/components/ui/button';
import { GetDealsOutputType } from 'zite-endpoints-sdk';
import { PHASE_COLOR_MAP } from './dealUtils';
import DealGeneralTab from './DealGeneralTab';
import CotizacionesTab from './CotizacionesTab';
import DocumentosTab from './DocumentosTab';
import ResumenTab from './ResumenTab';
import BriefEditor from './BriefEditor';
import ApprovalReviewDialog from './ApprovalReviewDialog';

type Deal = GetDealsOutputType['deals'][0];

const APPROVE_PHASES = ['Cotización enviada', 'Negociación'];

interface Props {
  deal: Deal;
  isOpen: boolean;
  onClose: () => void;
  onDealUpdated: (deal: Deal) => void;
  onDeleted: () => void;
  existingClients?: string[];
}

export default function DealDetailSheet({ deal, isOpen, onClose, onDealUpdated, onDeleted, existingClients }: Props) {
  const [localDeal, setLocalDeal] = useState<Deal>(deal);
  const [approvalReviewOpen, setApprovalReviewOpen] = useState(false);
  const isNew = !deal.id;
  const phaseColor = PHASE_COLOR_MAP[localDeal.phase ?? ''] ?? 'hsl(var(--muted-foreground))';
  const canApprove = !!localDeal.id && APPROVE_PHASES.includes(localDeal.phase ?? '');

  // Sync when parent deal changes (e.g. new deal opened)
  useEffect(() => { setLocalDeal(deal); }, [deal]);

  const handleDealSaved = (updated: Deal) => {
    setLocalDeal(updated);
    onDealUpdated(updated);
  };

  const handleDealFieldUpdated = (fields: { clientPrice?: number; quotedCost?: number; retencionesPct?: number }) => {
    setLocalDeal(prev => ({ ...prev, ...fields }));
    onDealUpdated({ ...localDeal, ...fields });
  };

  const handleApprovalSuccess = (res: { projectCode: string; projectId: string; quotedCost: number; notificationsSent: number }) => {
    const today = new Date().toISOString().split('T')[0];
    const updated: Deal = { ...localDeal, phase: 'Ganado', approvalDate: today, quotedCost: res.quotedCost };
    (updated as any).projects = [res.projectId];
    setLocalDeal(updated);
    onDealUpdated(updated);
    setApprovalReviewOpen(false);
  };

  return (
    <>
      <Dialog open={isOpen} onOpenChange={o => !o && onClose()}>
        <DialogContent className="max-w-4xl h-[85vh] flex flex-col gap-0 p-0 overflow-hidden">
          {/* Header */}
          <DialogHeader className="px-6 py-4 border-b flex-shrink-0">
            <div className="flex items-start justify-between gap-3">
              <div className="flex items-start gap-3 min-w-0">
                {!isNew && (
                  <div className="w-1 self-stretch rounded-full flex-shrink-0 mt-0.5" style={{ backgroundColor: phaseColor }} />
                )}
                <div className="min-w-0">
                  <DialogTitle className="text-base leading-tight">
                    {isNew ? 'Nuevo Deal' : (localDeal.dealName || 'Deal sin nombre')}
                  </DialogTitle>
                  {!isNew && localDeal.client && (
                    <p className="text-sm text-muted-foreground mt-0.5">{localDeal.client}</p>
                  )}
                </div>
              </div>

            </div>
          </DialogHeader>

          {isNew ? (
            <div className="flex-1 min-h-0 overflow-y-auto px-6 py-4">
              <DealGeneralTab deal={localDeal} onSaved={handleDealSaved} onDeleted={onDeleted} existingClients={existingClients} />
            </div>
          ) : (
            <Tabs defaultValue="general" className="flex-1 min-h-0 flex flex-col overflow-hidden">
              <TabsList className="mx-6 mt-3 mb-0 flex-shrink-0 grid grid-cols-5">
                <TabsTrigger value="general">General</TabsTrigger>
                <TabsTrigger value="cotizaciones">Cotizaciones</TabsTrigger>
                <TabsTrigger value="documentos">Documentos</TabsTrigger>
                <TabsTrigger value="brief">Brief</TabsTrigger>
                <TabsTrigger value="resumen">Resumen</TabsTrigger>
              </TabsList>
              <div className="flex-1 min-h-0 overflow-y-auto px-6 py-4">
                <TabsContent value="general" className="mt-0 data-[state=inactive]:hidden" forceMount>
                  <DealGeneralTab deal={localDeal} onSaved={handleDealSaved} onDeleted={onDeleted} existingClients={existingClients} />
                </TabsContent>
                <TabsContent value="cotizaciones" className="mt-0 data-[state=inactive]:hidden" forceMount>
                  <CotizacionesTab
                    dealId={localDeal.id}
                    dealCurrency={localDeal.currency}
                    dealClientPrice={localDeal.clientPrice}
                    dealQuotedCost={localDeal.quotedCost}
                    dealTaxesPct={localDeal.taxesPct}
                    dealRetencionesPct={localDeal.retencionesPct}
                    onDealFieldUpdated={handleDealFieldUpdated}
                  />
                </TabsContent>
                <TabsContent value="documentos" className="mt-0 data-[state=inactive]:hidden" forceMount>
                  <DocumentosTab dealId={localDeal.id} />
                </TabsContent>
                <TabsContent value="brief" className="mt-0 data-[state=inactive]:hidden" forceMount>
                  <BriefEditor dealId={localDeal.id} />
                </TabsContent>
                <TabsContent value="resumen" className="mt-0 data-[state=inactive]:hidden" forceMount>
                  <ResumenTab deal={localDeal} />
                </TabsContent>
              </div>
            </Tabs>
          )}
        </DialogContent>
      </Dialog>

      <ApprovalReviewDialog
        open={approvalReviewOpen}
        onClose={() => setApprovalReviewOpen(false)}
        deal={localDeal}
        onApproved={handleApprovalSuccess}
      />
    </>
  );
}

import { useState, useEffect, useCallback } from 'react';
import {
  getExpenseAuditLog, getExpenseComments, addExpenseComment,
  approveExpense, rejectExpense, submitExpense, deleteExpense,
  getExpenseLineItems,
  GetExpensesOutputType, GetExpenseAuditLogOutputType, GetExpenseCommentsOutputType,
  GetExpenseLineItemsOutputType,
} from 'zite-endpoints-sdk';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Skeleton } from '@/components/ui/skeleton';
import { CheckCircle2, XCircle, Send, Edit2, Trash2, Paperclip, History, MessageSquare, ListOrdered } from 'lucide-react';
import { toast } from 'sonner';

type Expense = GetExpensesOutputType['expenses'][0];
type AuditEntry = GetExpenseAuditLogOutputType['entries'][0];
type ExpComment = GetExpenseCommentsOutputType['comments'][0];
type LineItem = GetExpenseLineItemsOutputType['lineItems'][0];

const STATUS_STYLES: Record<string, string> = {
  'Borrador': 'bg-muted text-muted-foreground',
  'Enviado a aprobación': 'border border-amber-300 bg-amber-50 text-amber-800',
  'Aprobado': 'border border-emerald-300 bg-emerald-50 text-emerald-800',
  'Rechazado': 'border border-rose-300 bg-rose-50 text-rose-800',
};

const ACTION_STYLES: Record<string, string> = {
  'Creado': 'bg-emerald-100 text-emerald-700',
  'Editado': 'bg-sky-100 text-sky-700',
  'Enviado a aprobación': 'bg-blue-100 text-blue-700',
  'Aprobado': 'bg-emerald-100 text-emerald-700',
  'Rechazado': 'bg-rose-100 text-rose-700',
  'Eliminado': 'bg-muted text-muted-foreground',
};

function fmt(amount: number | null | undefined, currency = 'MXN') {
  if (amount == null) return '—';
  return new Intl.NumberFormat('es-MX', { style: 'currency', currency, minimumFractionDigits: 0, maximumFractionDigits: 2 }).format(amount);
}

function fmtDate(d: string | null | undefined) {
  if (!d) return '—';
  const [y, m, day] = d.split('T')[0].split('-');
  return new Date(Number(y), Number(m) - 1, Number(day)).toLocaleDateString('es-MX', { day: '2-digit', month: 'short', year: 'numeric' });
}

function fmtDateTime(d: string | null | undefined) {
  if (!d) return '—';
  return new Date(d).toLocaleDateString('es-MX', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });
}

function InfoRow({ label, value }: { label: string; value?: string | null }) {
  return (
    <div className="space-y-0.5">
      <p className="text-[11px] text-muted-foreground uppercase tracking-wide font-medium">{label}</p>
      <p className="text-sm font-medium">{value || '—'}</p>
    </div>
  );
}

// ── Flow Stepper ──────────────────────────────────────────────────────────────
const STEPS = [{ label: 'Creado' }, { label: 'Env. aprob.' }, { label: 'Aprobado' }];

function FlowStepper({ status }: { status: string | null | undefined }) {
  if (!status || status === 'Borrador') return null;
  const isRejected = status === 'Rechazado';
  const stepIdx = (status === 'Aprobado' || isRejected) ? 2 : status === 'Enviado a aprobación' ? 1 : 0;

  return (
    <div className="flex items-start w-full">
      {STEPS.map((step, i) => {
        const isDone = i < stepIdx || (i === stepIdx && status === 'Aprobado');
        const isActive = i === stepIdx && !isDone;
        const isRejectedStep = isActive && isRejected;
        const isLast = i === STEPS.length - 1;
        return (
          <div key={step.label} className="flex items-start flex-1 min-w-0">
            <div className="flex flex-col items-center flex-shrink-0">
              <div className={`w-7 h-7 rounded-full flex items-center justify-center border-2 text-[11px] font-bold ${
                isRejectedStep ? 'bg-destructive border-destructive text-destructive-foreground' :
                isDone ? 'bg-primary border-primary text-primary-foreground' :
                isActive ? 'bg-background border-primary text-primary' :
                'bg-background border-muted-foreground/25 text-muted-foreground/50'
              }`}>
                {isDone ? '✓' : isRejectedStep ? '✕' : i + 1}
              </div>
              <span className={`text-[10px] mt-1 font-medium text-center leading-tight px-0.5 ${
                isRejectedStep ? 'text-destructive font-semibold' :
                isDone ? 'text-primary' :
                isActive ? 'text-foreground font-semibold' : 'text-muted-foreground/60'
              }`}>
                {isRejectedStep ? 'Rechazado' : step.label}
              </span>
            </div>
            {!isLast && (
              <div className={`flex-1 h-0.5 mt-3.5 mx-1 rounded-full ${i < stepIdx ? 'bg-primary' : 'bg-muted-foreground/15'}`} />
            )}
          </div>
        );
      })}
    </div>
  );
}

// ── Props ─────────────────────────────────────────────────────────────────────
interface Props {
  expense: Expense | null;
  open: boolean;
  onClose: () => void;
  canApprove: boolean;
  userEmail: string;
  isFinanceRole: boolean;
  onEdit: (expense: Expense) => void;
  onUpdate: (id: string, changes: Partial<Expense>) => void;
  onRefreshList: () => void;
}

export default function ExpenseDetailDialog({ expense, open, onClose, canApprove, userEmail, isFinanceRole, onEdit, onUpdate, onRefreshList }: Props) {
  const [auditLog, setAuditLog] = useState<AuditEntry[]>([]);
  const [comments, setComments] = useState<ExpComment[]>([]);
  const [lineItems, setLineItems] = useState<LineItem[]>([]);
  const [auditLoading, setAuditLoading] = useState(false);
  const [commentsLoading, setCommentsLoading] = useState(false);
  const [newComment, setNewComment] = useState('');
  const [sendingComment, setSendingComment] = useState(false);
  const [approving, setApproving] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [rejectOpen, setRejectOpen] = useState(false);
  const [rejectionReason, setRejectionReason] = useState('');
  const [rejecting, setRejecting] = useState(false);
  const [deleteOpen, setDeleteOpen] = useState(false);
  const [deleting, setDeleting] = useState(false);

  const loadData = useCallback(async (expenseId: string) => {
    setAuditLoading(true);
    setCommentsLoading(true);
    const [auditRes, commentsRes, linesRes] = await Promise.allSettled([
      getExpenseAuditLog({ expenseId }),
      getExpenseComments({ expenseId }),
      getExpenseLineItems({ expenseId }),
    ]);
    if (auditRes.status === 'fulfilled') setAuditLog(auditRes.value.entries);
    if (commentsRes.status === 'fulfilled') setComments(commentsRes.value.comments);
    if (linesRes.status === 'fulfilled') setLineItems(linesRes.value.lineItems);
    setAuditLoading(false);
    setCommentsLoading(false);
  }, []);

  useEffect(() => {
    if (!open || !expense) return;
    setAuditLog([]); setComments([]); setLineItems([]); setNewComment('');
    loadData(expense.id);
  }, [open, expense?.id, loadData]);

  if (!expense) return null;

  const status = expense.status ?? 'Borrador';
  const isCreator = expense.createdBy === userEmail;
  const canEdit = (status === 'Borrador' || status === 'Rechazado') && (isCreator || isFinanceRole);
  const canSubmit = (status === 'Borrador' || status === 'Rechazado') && isCreator;
  const canApproveThis = canApprove && status === 'Enviado a aprobación';
  const canReject = canApprove && status === 'Enviado a aprobación';
  const canDelete = (status === 'Borrador' || status === 'Rechazado') && (isCreator || isFinanceRole);
  const receipts = expense.receipt ?? [];

  const handleApprove = async () => {
    setApproving(true);
    try {
      await approveExpense({ id: expense.id });
      toast.success('Gasto aprobado');
      onUpdate(expense.id, { status: 'Aprobado', approvedBy: userEmail });
      onRefreshList();
      await loadData(expense.id);
    } catch (e: unknown) { toast.error((e as { message?: string })?.message ?? 'Error al aprobar'); }
    setApproving(false);
  };

  const handleSubmit = async () => {
    setSubmitting(true);
    try {
      await submitExpense({ id: expense.id });
      toast.success('Enviado a aprobación');
      onUpdate(expense.id, { status: 'Enviado a aprobación' });
      onRefreshList();
      await loadData(expense.id);
    } catch (e: unknown) { toast.error((e as { message?: string })?.message ?? 'Error al enviar'); }
    setSubmitting(false);
  };

  const handleReject = async () => {
    if (!rejectionReason.trim()) return;
    setRejecting(true);
    try {
      await rejectExpense({ id: expense.id, rejectionReason: rejectionReason.trim() });
      toast.success('Gasto rechazado');
      onUpdate(expense.id, { status: 'Rechazado', rejectionReason: rejectionReason.trim() });
      onRefreshList();
      setRejectOpen(false); setRejectionReason('');
      await loadData(expense.id);
    } catch (e: unknown) { toast.error((e as { message?: string })?.message ?? 'Error al rechazar'); }
    setRejecting(false);
  };

  const handleDelete = async () => {
    setDeleting(true);
    try {
      await deleteExpense({ id: expense.id });
      toast.success('Gasto eliminado');
      onRefreshList(); onClose();
    } catch (e: unknown) { toast.error((e as { message?: string })?.message ?? 'Error al eliminar'); }
    setDeleting(false);
  };

  const handleAddComment = async () => {
    if (!newComment.trim()) return;
    setSendingComment(true);
    try {
      await addExpenseComment({ expenseId: expense.id, comment: newComment.trim() });
      setNewComment('');
      await loadData(expense.id);
    } catch (e: unknown) { toast.error((e as { message?: string })?.message ?? 'Error al enviar'); }
    setSendingComment(false);
  };

  return (
    <>
      <Dialog open={open} onOpenChange={v => { if (!v) onClose(); }}>
        <DialogContent className="max-w-3xl max-h-[85vh] flex flex-col gap-0 p-0 overflow-hidden">
          {/* Header */}
          <DialogHeader className="px-6 py-4 border-b flex-shrink-0">
            <div className="flex items-start justify-between gap-4">
              <div className="min-w-0">
                <p className="text-xs text-muted-foreground font-mono mb-0.5">Gasto #{expense.expenseNumber ?? '—'}</p>
                <DialogTitle className="text-base leading-tight line-clamp-2">{expense.description ?? 'Sin descripción'}</DialogTitle>
                {expense.projectCode && <p className="text-xs text-muted-foreground mt-0.5">{expense.projectCode}</p>}
              </div>
              <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-xs font-semibold flex-shrink-0 mt-0.5 ${STATUS_STYLES[status] ?? 'bg-muted text-muted-foreground'}`}>
                {status}
              </span>
            </div>
            <div className="mt-4"><FlowStepper status={status} /></div>
          </DialogHeader>

          {/* Body */}
          <div className="flex-1 overflow-y-auto px-6 py-5 space-y-6">
            {/* Rejection banner */}
            {status === 'Rechazado' && expense.rejectionReason && (
              <div className="flex items-start gap-2.5 px-4 py-3 rounded-lg bg-destructive/5 border border-destructive/20 border-l-4 border-l-destructive">
                <XCircle className="w-4 h-4 text-destructive flex-shrink-0 mt-0.5" />
                <div>
                  <p className="text-sm font-semibold text-destructive">Gasto rechazado — requiere corrección</p>
                  <p className="text-xs text-muted-foreground mt-0.5 leading-relaxed">{expense.rejectionReason}</p>
                </div>
              </div>
            )}

            {/* Info grid */}
            <div className="grid grid-cols-3 gap-x-6 gap-y-4">
              <InfoRow label="Total" value={fmt(expense.amount, expense.currency ?? 'MXN')} />
              <InfoRow label="Moneda" value={expense.currency} />
              <InfoRow label="Método de pago" value={expense.paymentMethod} />
              <InfoRow label="Centro de costos" value={expense.costCenter} />
              <InfoRow label="Proyecto" value={expense.projectCode} />
              <InfoRow label="Creado por" value={expense.createdBy?.split('@')[0]} />
              <InfoRow label="Aprobado por" value={expense.approvedBy?.split('@')[0]} />
              {lineItems.length === 0 && expense.category && (
                <InfoRow label="Categoría" value={expense.category} />
              )}
              {lineItems.length === 0 && expense.expenseDate && (
                <InfoRow label="Fecha del gasto" value={fmtDate(expense.expenseDate)} />
              )}
            </div>

            {/* Notes */}
            {expense.notes && (
              <div className="space-y-1">
                <p className="text-[11px] text-muted-foreground uppercase tracking-wide font-medium">Notas</p>
                <p className="text-sm bg-muted/30 rounded-lg px-3 py-2 leading-relaxed">{expense.notes}</p>
              </div>
            )}

            {/* Line items detail (new) */}
            {lineItems.length > 0 ? (
              <div className="space-y-2">
                <p className="text-[11px] text-muted-foreground uppercase tracking-wide font-medium flex items-center gap-1.5">
                  <ListOrdered className="w-3.5 h-3.5" /> Partidas del gasto ({lineItems.length})
                </p>
                <div className="border border-border rounded-lg overflow-hidden">
                  <table className="w-full text-xs">
                    <thead className="bg-muted/50 border-b border-border">
                      <tr>
                        <th className="text-left px-3 py-2 font-medium text-muted-foreground">Descripción</th>
                        <th className="text-left px-3 py-2 font-medium text-muted-foreground hidden sm:table-cell">Categoría</th>
                        <th className="text-left px-3 py-2 font-medium text-muted-foreground hidden sm:table-cell">Fecha</th>
                        <th className="text-right px-3 py-2 font-medium text-muted-foreground">Monto</th>
                        <th className="text-center px-3 py-2 font-medium text-muted-foreground w-16">Comp.</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-border">
                      {lineItems.map((li, i) => {
                        const r = li.receipt?.[0];
                        const isImg = r ? /\.(png|jpg|jpeg|gif|webp)$/i.test(r.url) : false;
                        return (
                          <tr key={li.id ?? i} className="hover:bg-muted/20">
                            <td className="px-3 py-2 font-medium">{li.description || '—'}</td>
                            <td className="px-3 py-2 text-muted-foreground hidden sm:table-cell">{li.category || '—'}</td>
                            <td className="px-3 py-2 text-muted-foreground hidden sm:table-cell">{fmtDate(li.date)}</td>
                            <td className="px-3 py-2 text-right font-semibold">{fmt(li.amount, expense.currency ?? 'MXN')}</td>
                            <td className="px-3 py-2 text-center">
                              {r ? (
                                <a href={r.url} target="_blank" rel="noopener noreferrer" title="Ver comprobante">
                                  {isImg
                                    ? <img src={r.url} alt="comp" className="w-7 h-7 rounded object-cover border border-border mx-auto hover:opacity-80" />
                                    : <Paperclip className="w-4 h-4 text-primary mx-auto" />
                                  }
                                </a>
                              ) : <span className="text-muted-foreground/40">—</span>}
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                    <tfoot className="bg-muted/30 border-t border-border">
                      <tr>
                        <td colSpan={3} className="px-3 py-2 text-right text-xs font-semibold text-muted-foreground hidden sm:table-cell">Total</td>
                        <td colSpan={1} className="px-3 py-2 text-right text-xs font-semibold text-muted-foreground sm:hidden">Total</td>
                        <td className="px-3 py-2 text-right font-bold text-sm">{fmt(expense.amount, expense.currency ?? 'MXN')}</td>
                        <td />
                      </tr>
                    </tfoot>
                  </table>
                </div>
              </div>
            ) : (
              /* Legacy: show single receipt if no line items */
              <div className="space-y-2">
                <p className="text-[11px] text-muted-foreground uppercase tracking-wide font-medium flex items-center gap-1.5">
                  <Paperclip className="w-3.5 h-3.5" /> Evidencias / Comprobantes
                </p>
                {receipts.length === 0 ? (
                  <p className="text-sm text-muted-foreground italic">Sin comprobantes adjuntos</p>
                ) : (
                  <div className="flex flex-wrap gap-3">
                    {receipts.map((r, i) => {
                      const isImg = /\.(png|jpg|jpeg|gif|webp)$/i.test(r.url);
                      return isImg ? (
                        <a key={i} href={r.url} target="_blank" rel="noopener noreferrer" className="group block">
                          <img src={r.url} alt="evidencia" className="w-24 h-24 rounded-xl object-cover border border-border group-hover:opacity-80 transition-opacity shadow-sm" />
                        </a>
                      ) : (
                        <a key={i} href={r.url} target="_blank" rel="noopener noreferrer"
                          className="flex items-center gap-2 px-3 py-2.5 border border-border rounded-xl bg-muted text-sm hover:bg-muted/80 transition-colors">
                          <Paperclip className="w-4 h-4 flex-shrink-0 text-muted-foreground" />
                          <span className="truncate max-w-[150px]">{r.url.split('/').pop()}</span>
                        </a>
                      );
                    })}
                  </div>
                )}
              </div>
            )}

            {/* Comments */}
            <div className="space-y-3">
              <div className="flex items-center gap-2">
                <MessageSquare className="w-3.5 h-3.5 text-muted-foreground" />
                <p className="text-[11px] text-muted-foreground uppercase tracking-wide font-medium">Comentarios</p>
              </div>
              {commentsLoading ? (
                <div className="space-y-2">{[1, 2].map(i => <Skeleton key={i} className="h-12 w-full" />)}</div>
              ) : (
                <div className="space-y-3">
                  {comments.length === 0 && (
                    <p className="text-sm text-muted-foreground italic">Sin comentarios aún. Agrega uno abajo.</p>
                  )}
                  {comments.map((c, i) => (
                    <div key={c.id ?? i} className="flex gap-2.5">
                      <div className="w-7 h-7 rounded-full bg-primary/10 flex items-center justify-center flex-shrink-0 text-xs font-bold text-primary">
                        {(c.authorName || c.authorEmail || '?')[0].toUpperCase()}
                      </div>
                      <div className="flex-1 bg-muted/30 rounded-xl px-3 py-2">
                        <div className="flex items-center gap-2 mb-0.5">
                          <span className="text-xs font-semibold">{c.authorName || c.authorEmail?.split('@')[0] || '—'}</span>
                          <span className="text-[11px] text-muted-foreground">{fmtDateTime(c.createdAt)}</span>
                        </div>
                        <p className="text-sm leading-relaxed">{c.comment}</p>
                      </div>
                    </div>
                  ))}
                  <div className="flex gap-2 pt-1">
                    <Textarea
                      value={newComment}
                      onChange={e => setNewComment(e.target.value)}
                      placeholder="Escribe un comentario... (Ctrl+Enter para enviar)"
                      className="text-sm min-h-[60px] resize-none flex-1"
                      onKeyDown={e => { if (e.key === 'Enter' && e.ctrlKey) handleAddComment(); }}
                    />
                    <Button size="sm" className="self-end flex-shrink-0 gap-1.5" onClick={handleAddComment}
                      disabled={sendingComment || !newComment.trim()}>
                      <Send className="w-3.5 h-3.5" />
                      {sendingComment ? '...' : 'Enviar'}
                    </Button>
                  </div>
                </div>
              )}
            </div>

            {/* Audit Log */}
            <div className="space-y-3">
              <div className="flex items-center gap-2">
                <History className="w-3.5 h-3.5 text-muted-foreground" />
                <p className="text-[11px] text-muted-foreground uppercase tracking-wide font-medium">Historial de cambios</p>
              </div>
              {auditLoading ? (
                <div className="space-y-2">{[1, 2, 3].map(i => <Skeleton key={i} className="h-10 w-full" />)}</div>
              ) : auditLog.length === 0 ? (
                <p className="text-sm text-muted-foreground italic">Sin historial disponible</p>
              ) : (
                <div className="relative pl-1">
                  <div className="absolute left-3 top-2 bottom-2 w-px bg-border" />
                  <div className="space-y-4">
                    {auditLog.map((entry, i) => (
                      <div key={entry.id ?? i} className="flex gap-3">
                        <div className={`w-6 h-6 rounded-full flex items-center justify-center flex-shrink-0 z-10 text-[10px] font-bold mt-0.5 ${ACTION_STYLES[entry.action ?? ''] ?? 'bg-muted text-muted-foreground'}`}>
                          {(entry.action ?? '?')[0]}
                        </div>
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 flex-wrap">
                            <span className={`text-[11px] font-semibold px-1.5 py-0.5 rounded ${ACTION_STYLES[entry.action ?? ''] ?? 'bg-muted text-muted-foreground'}`}>
                              {entry.action}
                            </span>
                            <span className="text-xs text-muted-foreground font-medium">{entry.userName || entry.userEmail?.split('@')[0]}</span>
                            <span className="text-xs text-muted-foreground">· {fmtDateTime(entry.timestamp)}</span>
                          </div>
                          {entry.comments && (
                            <p className="text-xs text-muted-foreground mt-1 bg-muted/30 rounded px-2 py-1.5 leading-relaxed">{entry.comments}</p>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Footer actions */}
          <div className="px-6 py-4 border-t flex-shrink-0 flex items-center gap-2 flex-wrap">
            {canEdit && (
              <Button variant="outline" size="sm" className="gap-1.5" onClick={() => { onClose(); onEdit(expense); }}>
                <Edit2 className="w-3.5 h-3.5" /> Editar
              </Button>
            )}
            {canDelete && (
              <Button variant="outline" size="sm" className="gap-1.5 text-destructive border-destructive/30 hover:bg-destructive/10" onClick={() => setDeleteOpen(true)}>
                <Trash2 className="w-3.5 h-3.5" /> Eliminar
              </Button>
            )}
            {canSubmit && (
              <Button variant="outline" size="sm" className="gap-1.5 text-sky-600 border-sky-200 hover:bg-sky-50" onClick={handleSubmit} disabled={submitting}>
                <Send className="w-3.5 h-3.5" />
                {submitting ? 'Enviando...' : 'Enviar a aprobación'}
              </Button>
            )}
            {canApproveThis && (
              <Button variant="outline" size="sm" className="gap-1.5 text-emerald-600 border-emerald-200 hover:bg-emerald-50" onClick={handleApprove} disabled={approving}>
                <CheckCircle2 className="w-3.5 h-3.5" />
                {approving ? 'Aprobando...' : 'Aprobar'}
              </Button>
            )}
            {canReject && (
              <Button variant="outline" size="sm" className="gap-1.5 text-destructive border-destructive/30 hover:bg-destructive/10" onClick={() => setRejectOpen(true)}>
                <XCircle className="w-3.5 h-3.5" /> Rechazar
              </Button>
            )}
          </div>
        </DialogContent>
      </Dialog>

      {/* Reject sub-dialog */}
      <Dialog open={rejectOpen} onOpenChange={v => { if (!v) { setRejectOpen(false); setRejectionReason(''); } }}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 text-destructive">
              <XCircle className="w-4 h-4" /> Rechazar gasto
            </DialogTitle>
          </DialogHeader>
          <div className="py-2 space-y-3">
            <p className="text-sm text-muted-foreground">
              El gasto quedará como <strong>Rechazado</strong>. El creador podrá editarlo y reenviarlo a aprobación.
            </p>
            <div className="space-y-1.5">
              <Label className="text-xs">Motivo del rechazo *</Label>
              <Textarea rows={3} className="resize-none text-sm" placeholder="Explica el motivo para que el creador pueda corregirlo..."
                value={rejectionReason} onChange={e => setRejectionReason(e.target.value)} autoFocus />
            </div>
          </div>
          <div className="flex justify-end gap-2 pt-1">
            <Button variant="ghost" size="sm" onClick={() => { setRejectOpen(false); setRejectionReason(''); }} disabled={rejecting}>Cancelar</Button>
            <Button variant="destructive" size="sm" onClick={handleReject} disabled={rejecting || !rejectionReason.trim()}>
              {rejecting ? 'Rechazando...' : 'Rechazar gasto'}
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* Delete confirm */}
      <AlertDialog open={deleteOpen} onOpenChange={v => { if (!v) setDeleteOpen(false); }}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>¿Eliminar este gasto?</AlertDialogTitle>
            <AlertDialogDescription>
              Se eliminará permanentemente <strong>"{expense.description}"</strong>. Esta acción no se puede deshacer.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleting}>Cancelar</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} disabled={deleting} className="bg-destructive hover:bg-destructive/90">
              {deleting ? 'Eliminando...' : 'Eliminar'}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

import { useState, useRef } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Separator } from '@/components/ui/separator';
import { Progress } from '@/components/ui/progress';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { toast } from 'sonner';
import { fmtCurrency } from '../../lib/format';
import { sendPaymentReceipt, savePayment, GetPaymentsOutputType } from 'zite-endpoints-sdk';
import { uploadFile } from 'zite-file-upload-sdk';
import {
  CreditCard, Paperclip, FileText, Landmark, Receipt,
  Pencil, Trash2, Send, AlertCircle, Upload, Building2, X, CheckCircle, XCircle,
} from 'lucide-react';

type Payment = GetPaymentsOutputType['payments'][0];


function fmtDate(d?: string) {
  if (!d) return '—';
  return new Date(d.split('T')[0] + 'T12:00:00').toLocaleDateString('es-MX', { day: '2-digit', month: 'short', year: 'numeric' });
}

function StatusBadge({ status }: { status?: string }) {
  const styles: Record<string, string> = {
    'Programado': 'bg-yellow-100 text-yellow-700 border-yellow-200',
    'Realizado': 'bg-green-100 text-green-700 border-green-200',
    'Cancelado': 'bg-red-100 text-red-700 border-red-200',
  };
  return (
    <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-semibold border ${styles[status ?? ''] ?? 'bg-muted text-muted-foreground border-border'}`}>
      {status || '—'}
    </span>
  );
}

interface Props {
  payment: Payment | null;
  open: boolean;
  onOpenChange: (v: boolean) => void;
  onEdit: () => void;
  onDelete: () => void;
  onAttachmentUploaded?: (attachment: { url: string }[]) => void;
  onPaymentUpdated?: (updates: { status?: string; paymentDate?: string }) => void;
}

export function PaymentDetailDialog({ payment, open, onOpenChange, onEdit, onDelete, onAttachmentUploaded, onPaymentUpdated }: Props) {
  const [sending, setSending] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [dragging, setDragging] = useState(false);
  const [registering, setRegistering] = useState(false);
  const [cancelling, setCancelling] = useState(false);
  const [cancelConfirmOpen, setCancelConfirmOpen] = useState(false);
  const [localAttachment, setLocalAttachment] = useState<{ url: string }[] | null>(null);
  const [localStatus, setLocalStatus] = useState<string | null>(null);
  const [localPaymentDate, setLocalPaymentDate] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const currentAttachment = localAttachment ?? (payment?.attachment ?? []);
  const hasAttachment = currentAttachment.length > 0;
  const displayStatus = localStatus ?? payment?.status;
  const displayPaymentDate = localPaymentDate ?? payment?.paymentDate;

  if (!payment) return null;

  const isProgramado = displayStatus === 'Programado';
  const paidPct = payment.poTotalAmount ? Math.min(100, ((payment.amount ?? 0) / payment.poTotalAmount) * 100) : 0;
  const isOverdue = (() => {
    if (!payment.dueDate || !isProgramado) return false;
    const due = new Date(payment.dueDate.split('T')[0] + 'T12:00:00');
    due.setHours(0, 0, 0, 0);
    const today = new Date(); today.setHours(0, 0, 0, 0);
    return due < today;
  })();

  const handleUploadFile = async (file: File) => {
    setUploading(true);
    try {
      const { fileUrl } = await uploadFile({ data: file, filename: file.name });
      const newAttachment = [...currentAttachment, { url: fileUrl }];
      await savePayment({ id: payment.id, attachment: newAttachment });
      setLocalAttachment(newAttachment);
      onAttachmentUploaded?.(newAttachment);
      toast.success('Comprobante subido correctamente');
    } catch {
      toast.error('Error al subir el comprobante');
    }
    setUploading(false);
  };

  const handleRemoveAttachment = async (idx: number) => {
    const newAttachment = currentAttachment.filter((_, i) => i !== idx);
    try {
      await savePayment({ id: payment.id, attachment: newAttachment });
      setLocalAttachment(newAttachment);
      onAttachmentUploaded?.(newAttachment);
      toast.success('Comprobante eliminado');
    } catch {
      toast.error('Error al eliminar el comprobante');
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragging(false);
    const file = e.dataTransfer.files?.[0];
    if (file) handleUploadFile(file);
  };

  const handleRegisterPayment = async () => {
    if (!hasAttachment) {
      toast.error('Sube un comprobante antes de registrar el pago');
      return;
    }
    setRegistering(true);
    try {
      const today = new Date().toISOString().split('T')[0];
      await savePayment({ id: payment.id, status: 'Realizado', paymentDate: today });
      setLocalStatus('Realizado');
      setLocalPaymentDate(today);
      onPaymentUpdated?.({ status: 'Realizado', paymentDate: today });
      toast.success('Pago registrado como realizado');
    } catch {
      toast.error('Error al registrar el pago');
    }
    setRegistering(false);
  };

  const handleCancelPayment = async () => {
    setCancelConfirmOpen(false);
    setCancelling(true);
    try {
      await savePayment({ id: payment.id, status: 'Cancelado' });
      setLocalStatus('Cancelado');
      onPaymentUpdated?.({ status: 'Cancelado' });
      toast.success('Pago cancelado');
    } catch {
      toast.error('Error al cancelar el pago');
    }
    setCancelling(false);
  };

  const handleSendReceipt = async () => {
    setSending(true);
    try {
      const result = await sendPaymentReceipt({ paymentId: payment.id });
      toast.success(result.message);
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : 'Error al enviar comprobante';
      toast.error(msg);
    }
    setSending(false);
  };

  return (
    <>
      <Dialog open={open} onOpenChange={(v) => { if (!v) { setLocalAttachment(null); setLocalStatus(null); setLocalPaymentDate(null); } onOpenChange(v); }}>
        <DialogContent className="sm:max-w-2xl max-h-[90vh] flex flex-col p-0 gap-0">
          <DialogHeader className="px-6 pt-6 pb-4 border-b shrink-0">
            <div className="flex items-start gap-3">
              <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center shrink-0">
                <CreditCard className="w-5 h-5 text-primary" />
              </div>
              <div className="min-w-0 flex-1">
                <div className="flex items-center gap-2 flex-wrap">
                  <DialogTitle className="text-base font-bold">{String(payment.paymentId ?? '—')}</DialogTitle>
                  <StatusBadge status={displayStatus} />
                  {payment.currency && (
                    <span className="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-semibold border bg-blue-100 text-blue-700 border-blue-200">{payment.currency}</span>
                  )}
                </div>
                <p className="text-sm text-muted-foreground mt-0.5">{payment.supplierName ?? '—'}</p>
              </div>
            </div>
          </DialogHeader>

          <div className="flex-1 overflow-y-auto px-6 py-5 space-y-5">
            {/* Payment data */}
            <div>
              <p className="text-[11px] text-muted-foreground uppercase tracking-wider font-semibold mb-3 flex items-center gap-1.5">
                <Receipt className="w-3.5 h-3.5" /> Datos del pago
              </p>
              <div className="grid grid-cols-2 gap-x-6 gap-y-3">
                <div>
                  <p className="text-xs text-muted-foreground mb-0.5">Monto</p>
                  <p className="text-xl font-black text-primary">{fmtCurrency(payment.amount, payment.currency)}</p>
                </div>
                <div>
                  <p className="text-xs text-muted-foreground mb-0.5">Método</p>
                  <p className="text-sm font-medium">{payment.method || 'Transferencia'}</p>
                </div>
                <div>
                  <p className="text-xs text-muted-foreground mb-0.5">Fecha comprometida</p>
                  <div className="flex items-center gap-2">
                    <p className={`text-sm font-medium ${isOverdue ? 'text-destructive' : ''}`}>{fmtDate(payment.dueDate)}</p>
                    {isOverdue && <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-destructive/10 text-destructive border border-destructive/20 leading-none flex items-center gap-1"><AlertCircle className="w-2.5 h-2.5" />Vencido</span>}
                  </div>
                </div>
                <div>
                  <p className="text-xs text-muted-foreground mb-0.5">Fecha de pago real</p>
                  <p className="text-sm font-medium">{fmtDate(displayPaymentDate)}</p>
                </div>
                <div>
                  <p className="text-xs text-muted-foreground mb-0.5">Referencia</p>
                  <p className="text-sm font-medium font-mono">{payment.reference ?? '—'}</p>
                </div>
                <div>
                  <p className="text-xs text-muted-foreground mb-0.5"># Factura proveedor</p>
                  <p className="text-sm font-medium">{payment.supplierInvoiceNumber ?? '—'}</p>
                </div>
                <div>
                  <p className="text-xs text-muted-foreground mb-0.5">ODC vinculada</p>
                  <p className="text-sm font-medium font-mono">{payment.poNumber ? `ODC-${payment.poNumber}` : '—'}</p>
                </div>
                <div>
                  <p className="text-xs text-muted-foreground mb-0.5">Proyecto</p>
                  <p className="text-sm font-medium">{payment.projectCode ?? '—'}</p>
                </div>
                {payment.supplierEmail && (
                  <div>
                    <p className="text-xs text-muted-foreground mb-0.5">Email proveedor</p>
                    <p className="text-sm font-medium">{payment.supplierEmail}</p>
                  </div>
                )}
              </div>
            </div>

            {/* PO */}
            {payment.poId && (
              <>
                <Separator />
                <div>
                  <p className="text-[11px] text-muted-foreground uppercase tracking-wider font-semibold mb-3 flex items-center gap-1.5">
                    <FileText className="w-3.5 h-3.5" /> ODC vinculada
                  </p>
                  <div className="bg-muted/40 rounded-xl p-4 space-y-3">
                    <div className="flex items-center justify-between">
                      <span className="text-sm font-bold">ODC-{payment.poNumber}</span>
                      <span className="text-xs text-muted-foreground">{fmtCurrency(payment.poTotalAmount, payment.currency)}</span>
                    </div>
                    <div className="space-y-1">
                      <div className="flex justify-between text-xs text-muted-foreground">
                        <span>Saldo pendiente</span>
                        <span className="font-semibold text-foreground">{fmtCurrency(payment.poPendingAmount, payment.currency)}</span>
                      </div>
                      <Progress value={100 - paidPct} className="h-1.5" />
                    </div>
                  </div>
                </div>
              </>
            )}

            {/* Bank / Source info */}
            <Separator />
            <div>
              <p className="text-[11px] text-muted-foreground uppercase tracking-wider font-semibold mb-3 flex items-center gap-1.5">
                <Landmark className="w-3.5 h-3.5" /> Datos bancarios
              </p>
              <div className="grid grid-cols-2 gap-x-6 gap-y-3">
                {(payment.sourceCompany || payment.sourceBank || payment.sourceAccount) && (
                  <>
                    <div className="col-span-2">
                      <p className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider mb-2 flex items-center gap-1.5">
                        <Building2 className="w-3 h-3" /> Origen del pago
                      </p>
                    </div>
                    {payment.sourceCompany && (
                      <div>
                        <p className="text-xs text-muted-foreground mb-0.5">Empresa pagadora</p>
                        <p className="text-sm font-medium">{payment.sourceCompany}</p>
                      </div>
                    )}
                    {payment.sourceBank && (
                      <div>
                        <p className="text-xs text-muted-foreground mb-0.5">Banco origen</p>
                        <p className="text-sm font-medium">{payment.sourceBank}</p>
                      </div>
                    )}
                    {payment.sourceAccount && (
                      <div className="col-span-2">
                        <p className="text-xs text-muted-foreground mb-0.5">Cuenta origen</p>
                        <p className="text-sm font-medium font-mono">{payment.sourceAccount}</p>
                      </div>
                    )}
                    <div className="col-span-2 border-t border-border/50 pt-3 mt-1" />
                  </>
                )}
                <div className="col-span-2">
                  <p className="text-xs text-muted-foreground mb-0.5">Cuenta destino</p>
                  <p className="text-sm font-medium font-mono">{payment.destinationAccount ?? '—'}</p>
                </div>
              </div>
            </div>

            {/* Attachment / Upload */}
            <Separator />
            <div>
              <p className="text-[11px] text-muted-foreground uppercase tracking-wider font-semibold mb-3 flex items-center gap-1.5">
                <Paperclip className="w-3.5 h-3.5" /> Comprobante de pago
              </p>

              {isProgramado && !hasAttachment && (
                <div className="flex items-center gap-2 mb-3 px-3 py-2 rounded-lg bg-yellow-50 border border-yellow-200 text-yellow-700">
                  <AlertCircle className="w-3.5 h-3.5 shrink-0" />
                  <p className="text-xs font-medium">Sube un comprobante antes de registrar el pago</p>
                </div>
              )}

              {hasAttachment && (
                <div className="flex flex-wrap gap-2 mb-3">
                  {currentAttachment.map((a, i) => (
                    <div key={i} className="group flex items-center gap-1 pl-3 pr-1.5 py-1.5 rounded-lg bg-primary/10 text-primary text-sm font-medium">
                      <a href={a.url} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1.5 hover:underline">
                        <Paperclip className="w-3.5 h-3.5" />
                        Ver comprobante{currentAttachment.length > 1 ? ` ${i + 1}` : ''}
                      </a>
                      <button
                        onClick={() => handleRemoveAttachment(i)}
                        className="ml-1 p-0.5 rounded opacity-50 hover:opacity-100 hover:text-destructive transition-all"
                        title="Eliminar"
                      >
                        <X className="w-3 h-3" />
                      </button>
                    </div>
                  ))}
                </div>
              )}

              <div
                className={`relative border-2 border-dashed rounded-xl p-5 text-center transition-colors cursor-pointer ${dragging ? 'border-primary bg-primary/5' : 'border-border hover:border-primary/50 hover:bg-muted/30'} ${uploading ? 'pointer-events-none opacity-60' : ''}`}
                onDragOver={e => { e.preventDefault(); setDragging(true); }}
                onDragLeave={() => setDragging(false)}
                onDrop={handleDrop}
                onClick={() => fileInputRef.current?.click()}
              >
                <input
                  ref={fileInputRef}
                  type="file"
                  accept="image/*,application/pdf"
                  className="hidden"
                  onChange={e => { const f = e.target.files?.[0]; if (f) handleUploadFile(f); e.target.value = ''; }}
                />
                {uploading ? (
                  <div className="flex flex-col items-center gap-2">
                    <span className="animate-spin w-6 h-6 border-2 border-primary border-t-transparent rounded-full" />
                    <p className="text-sm text-muted-foreground">Subiendo comprobante…</p>
                  </div>
                ) : (
                  <div className="flex flex-col items-center gap-2">
                    <div className="w-10 h-10 rounded-xl bg-muted flex items-center justify-center">
                      <Upload className="w-5 h-5 text-muted-foreground" />
                    </div>
                    <p className="text-sm font-medium text-foreground">
                      {hasAttachment ? 'Agregar otro comprobante' : 'Subir comprobante'}
                    </p>
                    <p className="text-xs text-muted-foreground">Arrastra un archivo aquí o haz clic para buscar</p>
                    <p className="text-[10px] text-muted-foreground/60">PDF, JPG, PNG · Máx. 10 MB</p>
                  </div>
