import { useState, useEffect, useRef } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Skeleton } from '@/components/ui/skeleton';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { Paperclip, Upload, Trash2, Loader2, Download } from 'lucide-react';
import { getPoAttachments, savePoAttachment, deletePoAttachment, GetPoAttachmentsOutputType } from 'zite-endpoints-sdk';
import { uploadFile } from 'zite-file-upload-sdk';
import { toast } from 'sonner';

type Attachment = GetPoAttachmentsOutputType['attachments'][0];

function getFileEmoji(name: string) {
  const ext = name.split('.').pop()?.toLowerCase() ?? '';
  if (ext === 'pdf') return '📄';
  if (['jpg', 'jpeg', 'png', 'gif', 'webp', 'svg', 'heic'].includes(ext)) return '🖼️';
  if (['xls', 'xlsx', 'csv'].includes(ext)) return '📊';
  if (['doc', 'docx'].includes(ext)) return '📝';
  if (['zip', 'rar', '7z'].includes(ext)) return '🗜️';
  if (['mp4', 'mov', 'avi'].includes(ext)) return '🎥';
  return '📎';
}

function fmtDT(d?: string) {
  if (!d) return '—';
  return new Date(d).toLocaleDateString('es-MX', {
    day: '2-digit', month: 'short', year: 'numeric',
    hour: '2-digit', minute: '2-digit',
  });
}

interface Props {
  poId: string;
  status: string;
  userEmail: string;
  canUpload: boolean;
  isHighLevel: boolean;
  open: boolean;
}

export default function PoAttachmentsSection({ poId, status, userEmail, canUpload, isHighLevel, open }: Props) {
  const [attachments, setAttachments] = useState<Attachment[]>([]);
  const [loading, setLoading] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [desc, setDesc] = useState('');
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [confirmDelete, setConfirmDelete] = useState<Attachment | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!open || !poId) return;
    setLoading(true);
    getPoAttachments({ poId })
      .then(d => setAttachments(d.attachments))
      .catch(() => setAttachments([]))
      .finally(() => setLoading(false));
  }, [open, poId]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 25 * 1024 * 1024) {
      toast.error('El archivo no puede superar 25 MB');
      return;
    }
    setUploading(true);
    try {
      const { fileUrl } = await uploadFile({ data: file, filename: file.name });
      const result = await savePoAttachment({
        poId,
        fileUrl,
        fileName: file.name,
        description: desc.trim() || undefined,
      });
      setAttachments(prev => [...prev, result.attachment]);
      setDesc('');
      toast.success('Evidencia subida correctamente');
    } catch (e: unknown) {
      toast.error((e as Error).message ?? 'Error al subir el archivo');
    }
    setUploading(false);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleDelete = async () => {
    if (!confirmDelete) return;
    setDeletingId(confirmDelete.id);
    try {
      await deletePoAttachment({ id: confirmDelete.id });
      setAttachments(prev => prev.filter(a => a.id !== confirmDelete.id));
      toast.success('Evidencia eliminada');
    } catch (e: unknown) {
      toast.error((e as Error).message ?? 'Error al eliminar');
    }
    setDeletingId(null);
    setConfirmDelete(null);
  };

  const showUpload = canUpload && status !== 'Cancelada';

  return (
    <div className="space-y-3">
      {/* Header */}
      <div className="flex items-center justify-between gap-3 flex-wrap">
        <div className="flex items-center gap-2">
          <Paperclip className="w-3.5 h-3.5 text-muted-foreground" />
          <p className="text-[11px] text-muted-foreground uppercase tracking-wide font-medium">
            Evidencias y adjuntos
            {attachments.length > 0 && (
              <span className="ml-1.5 inline-flex items-center justify-center w-4 h-4 rounded-full bg-muted text-foreground text-[10px] font-bold">
                {attachments.length}
              </span>
            )}
          </p>
        </div>

        {showUpload && (
          <div className="flex items-center gap-2">
            <Input
              placeholder="Descripción (opcional)"
              value={desc}
              onChange={e => setDesc(e.target.value)}
              className="h-7 text-xs w-40"
              disabled={uploading}
            />
            <Button
              size="sm"
              variant="outline"
              className="h-7 text-xs gap-1.5 flex-shrink-0"
              disabled={uploading}
              onClick={() => fileInputRef.current?.click()}
            >
              {uploading
                ? <Loader2 className="w-3 h-3 animate-spin" />
                : <Upload className="w-3 h-3" />}
              {uploading ? 'Subiendo...' : 'Subir archivo'}
            </Button>
            <input
              ref={fileInputRef}
              type="file"
              className="hidden"
              onChange={handleFileChange}
            />
          </div>
        )}
      </div>

      {/* List */}
      {loading ? (
        <div className="space-y-2">
          {[1, 2].map(i => <Skeleton key={i} className="h-12 w-full rounded-lg" />)}
        </div>
      ) : attachments.length === 0 ? (
        <div className="flex items-center gap-2 py-4 text-sm text-muted-foreground italic">
          <Paperclip className="w-4 h-4 opacity-40" />
          Sin evidencias adjuntas
        </div>
      ) : (
        <div className="border border-border rounded-lg divide-y divide-border overflow-hidden">
          {attachments.map(att => {
            const canDel = att.uploadedByEmail === userEmail || isHighLevel;
            return (
              <div key={att.id} className="flex items-center gap-3 px-3 py-2.5 hover:bg-muted/20 group transition-colors">
                <span className="text-lg flex-shrink-0 leading-none">{getFileEmoji(att.name)}</span>
                <div className="flex-1 min-w-0">
                  <a
                    href={att.fileUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="text-sm font-medium text-primary hover:underline truncate block leading-tight"
                  >
                    {att.name}
                  </a>
                  <p className="text-xs text-muted-foreground mt-0.5 truncate">
                    {att.description && <span className="text-foreground/70 mr-1.5">{att.description} ·</span>}
                    <span>{att.uploadedByName || att.uploadedByEmail?.split('@')[0]}</span>
                    <span className="mx-1">·</span>
                    <span>{fmtDT(att.uploadedAt)}</span>
                  </p>
                </div>
                <div className="flex items-center gap-0.5 flex-shrink-0 opacity-0 group-hover:opacity-100 transition-opacity">
                  <a href={att.fileUrl} target="_blank" rel="noopener noreferrer" download={att.name}>
                    <Button size="icon" variant="ghost" className="h-7 w-7" title="Descargar">
                      <Download className="w-3.5 h-3.5" />
                    </Button>
                  </a>
                  {canDel && (
                    <Button
                      size="icon"
                      variant="ghost"
                      className="h-7 w-7 text-destructive hover:text-destructive hover:bg-destructive/10"
                      disabled={deletingId === att.id}
                      onClick={() => setConfirmDelete(att)}
                      title="Eliminar"
                    >
                      {deletingId === att.id
                        ? <Loader2 className="w-3.5 h-3.5 animate-spin" />
                        : <Trash2 className="w-3.5 h-3.5" />}
                    </Button>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Delete confirmation */}
      <AlertDialog open={!!confirmDelete} onOpenChange={o => { if (!o) setConfirmDelete(null); }}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>¿Eliminar evidencia?</AlertDialogTitle>
            <AlertDialogDescription>
              Se eliminará <strong>{confirmDelete?.name}</strong> permanentemente. Esta acción no se puede deshacer.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancelar</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              Eliminar
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useState, useEffect } from 'react';
import {
  getApprovalPreview, approveDeal,
  GetApprovalPreviewOutputType, GetDealsOutputType,
} from 'zite-endpoints-sdk';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from '@/components/ui/accordion';
import { Skeleton } from '@/components/ui/skeleton';
import { Badge } from '@/components/ui/badge';

import { CheckCircle2, Loader2, User } from 'lucide-react';
import { toast } from 'sonner';

type Deal = GetDealsOutputType['deals'][0];
type RubroData = GetApprovalPreviewOutputType['rubros'][0];

interface ApprovalResult {
  projectCode?: string;
  projectId?: string;
  quotedCost: number;
  notificationsSent: number;
}

interface Props {
  open: boolean;
  onClose: () => void;
  deal: Deal;
  onApproved: (result: ApprovalResult) => void;
}

function fmtAmt(amount: number, currency: string) {
  const sym = currency === 'USD' ? 'USD ' : currency === 'EUR' ? 'EUR ' : '$';
  return `${sym}${amount.toLocaleString('es-MX', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

function RubroAccordionItem({
  rubro, currency, selected, onToggleItem, onToggleAll,
}: {
  rubro: RubroData;
  currency: string;
  selected: Set<string>;
  onToggleItem: (id: string) => void;
  onToggleAll: (allSelected: boolean) => void;
}) {
  const allIds = rubro.lineItems.map(li => li.id);
  const allSelected = allIds.length > 0 && allIds.every(id => selected.has(id));
  const someSelected = allIds.some(id => selected.has(id));
  const subtotal = rubro.lineItems.filter(li => selected.has(li.id)).reduce((s, li) => s + li.total, 0);

  return (
    <AccordionItem value={rubro.rubroName} className="border rounded-lg mb-2 overflow-hidden">
      <AccordionTrigger className="px-4 py-3 hover:no-underline hover:bg-muted/30 transition-colors">
        <div className="flex items-center gap-3 w-full pr-2 min-w-0">
          <div
            className="flex-shrink-0"
            onClick={e => { e.stopPropagation(); onToggleAll(allSelected); }}
          >
            <Checkbox
              checked={allSelected ? true : someSelected ? 'indeterminate' : false}
              onCheckedChange={() => onToggleAll(allSelected)}
            />
          </div>
          <span className="font-semibold text-sm truncate">{rubro.rubroName}</span>
          <div className="flex items-center gap-1 flex-wrap flex-shrink-0">
            {rubro.users.length > 0 ? rubro.users.map(u => (
              <Badge key={u.id} variant="secondary" className="text-[10px] gap-1 py-0 px-1.5">
                <User className="w-2.5 h-2.5" />{u.name}
              </Badge>
            )) : (
              <span className="text-[10px] text-muted-foreground italic">Sin responsable</span>
            )}
          </div>
          <span className="ml-auto text-xs font-semibold tabular-nums flex-shrink-0 text-primary">
            {fmtAmt(subtotal, currency)}
          </span>
        </div>
      </AccordionTrigger>
      <AccordionContent className="px-4 pb-3 pt-0">
        <div className="space-y-0.5">
          <div className="grid grid-cols-[20px_1fr_44px_44px_90px_90px] gap-2 text-[10px] font-semibold text-muted-foreground uppercase tracking-wide pb-1.5 pt-1 border-b border-border px-1">
            <span />
            <span>Sub-rubro</span>
            <span className="text-right">UDC</span>
            <span className="text-right">Comp.</span>
            <span className="text-right">P. unit.</span>
            <span className="text-right">Total</span>
          </div>
          {(() => {
            // Group line items by cotizacionName
            const groups = new Map<string, typeof rubro.lineItems>();
            for (const li of rubro.lineItems) {
              const key = li.cotizacionName || '—';
              if (!groups.has(key)) groups.set(key, []);
              groups.get(key)!.push(li);
            }
            const showSubheaders = groups.size > 1;
            return [...groups.entries()].map(([cotName, items]) => (
              <div key={cotName}>
                {showSubheaders && (
                  <div className="text-[10px] font-semibold text-muted-foreground bg-muted/40 px-2 py-1 mt-2 mb-0.5 rounded">
                    {cotName}
                  </div>
                )}
                {items.map(li => {
                  const isChecked = selected.has(li.id);
                  return (
                    <div
                      key={li.id}
                      onClick={() => onToggleItem(li.id)}
                      className={`grid grid-cols-[20px_1fr_44px_44px_90px_90px] gap-2 items-center py-1.5 px-1 rounded-md cursor-pointer transition-colors select-none ${
                        isChecked ? 'hover:bg-muted/40' : 'opacity-40 hover:opacity-60'
                      }`}
                    >
                      <Checkbox
                        checked={isChecked}
                        onClick={e => e.stopPropagation()}
                        onCheckedChange={() => onToggleItem(li.id)}
                      />
                      <span className="text-sm truncate">{li.subRubro || '—'}</span>
                      <span className="text-xs text-right tabular-nums text-muted-foreground">{li.cantidad}</span>
                      <span className="text-xs text-right tabular-nums text-muted-foreground">{li.componentes}</span>
                      <span className="text-xs text-right tabular-nums text-muted-foreground">{fmtAmt(li.unitCost, currency)}</span>
                      <span className={`text-xs text-right tabular-nums font-medium ${isChecked ? 'text-foreground' : 'text-muted-foreground'}`}>
                        {fmtAmt(li.total, currency)}
                      </span>
                    </div>
                  );
                })}
              </div>
            ));
          })()}
        </div>
      </AccordionContent>
    </AccordionItem>
  );
}

export default function ApprovalReviewDialog({ open, onClose, deal, onApproved }: Props) {
  const [loading, setLoading] = useState(false);
  const [approving, setApproving] = useState(false);
  const [rubros, setRubros] = useState<RubroData[]>([]);
  const [currency, setCurrency] = useState('MXN');
  const [selected, setSelected] = useState<Map<string, Set<string>>>(new Map());
  const [createProject, setCreateProject] = useState(true);

  useEffect(() => {
    if (!open || !deal.id) return;
    setLoading(true);
    getApprovalPreview({ dealId: deal.id })
      .then(data => {
        setRubros(data.rubros);
        setCurrency(data.currency);
        const init = new Map<string, Set<string>>();
        for (const r of data.rubros) init.set(r.rubroName, new Set(r.lineItems.map(li => li.id)));
        setSelected(init);
      })
      .catch(() => toast.error('Error al cargar líneas de cotización'))
      .finally(() => setLoading(false));
  }, [open, deal.id]);

  const toggleItem = (rubroName: string, id: string) => {
    setSelected(prev => {
      const next = new Map(prev);
      const s = new Set(next.get(rubroName) ?? []);
      s.has(id) ? s.delete(id) : s.add(id);
      next.set(rubroName, s);
      return next;
    });
  };

  const toggleAll = (rubroName: string, allIds: string[], wasAllSelected: boolean) => {
    setSelected(prev => {
      const next = new Map(prev);
      next.set(rubroName, wasAllSelected ? new Set() : new Set(allIds));
      return next;
    });
  };

  const handleApprove = async () => {
    if (!deal.id) return;
    setApproving(true);
    try {
      const selectedLineItems = rubros.map(r => ({
        rubroName: r.rubroName,
        lineItemIds: [...(selected.get(r.rubroName) ?? new Set<string>())],
      }));
      const res = await approveDeal({ dealId: deal.id, createProject, selectedLineItems });
      const notifMsg = res.notificationsSent > 0
        ? ` · ${res.notificationsSent} notificación${res.notificationsSent !== 1 ? 'es' : ''} enviada${res.notificationsSent !== 1 ? 's' : ''}`
        : '';
      const successMsg = createProject
        ? `✓ Deal aprobado — Proyecto ${res.projectCode} creado${notifMsg}`
        : `✓ Deal aprobado`;
      toast.success(successMsg);
      onApproved({ projectCode: res.projectCode, projectId: res.projectId, quotedCost: res.quotedCost, notificationsSent: res.notificationsSent });
      onClose();
    } catch (e: unknown) {
      toast.error((e as { message?: string })?.message ?? 'Error al aprobar el deal');
    }
    setApproving(false);
  };

  const grandTotal = rubros.reduce((sum, r) => {
    const sel = selected.get(r.rubroName) ?? new Set<string>();
    return sum + r.lineItems.filter(li => sel.has(li.id)).reduce((s, li) => s + li.total, 0);
  }, 0);

  const totalItems = rubros.reduce((s, r) => s + r.lineItems.length, 0);
  const selectedCount = rubros.reduce((s, r) => s + (selected.get(r.rubroName)?.size ?? 0), 0);

  return (
    <Dialog open={open} onOpenChange={v => { if (!v && !approving) onClose(); }}>
      <DialogContent className="sm:max-w-2xl max-h-[90vh] flex flex-col p-0 gap-0 overflow-hidden">
        <DialogHeader className="px-6 py-4 border-b flex-shrink-0">
          <DialogTitle className="flex items-center gap-2 text-base">
            <CheckCircle2 className="w-4 h-4 text-primary" />
            Aprobar deal: {deal.dealName || 'Sin nombre'}
          </DialogTitle>
          <p className="text-xs text-muted-foreground mt-1">
            Selecciona qué líneas de cotización se enviarán a cada responsable. Solo las marcadas aparecerán en los mensajes y en el presupuesto.
          </p>
        </DialogHeader>

        <div className="flex-1 min-h-0 overflow-y-auto">
          <div className="px-6 py-4 space-y-2">
            {loading ? (
              <div className="space-y-3">
                {[1, 2, 3].map(i => <Skeleton key={i} className="h-14 w-full rounded-lg" />)}
              </div>
            ) : rubros.length === 0 ? (
              <div className="py-12 text-center space-y-2">
                <p className="text-sm font-medium text-muted-foreground">Sin líneas de cotización</p>
                <p className="text-xs text-muted-foreground">No hay cotizaciones incluidas con líneas de presupuesto en este deal.</p>
                <p className="text-xs text-muted-foreground">Aún puedes aprobar — se creará el proyecto y el proceso de cobranza.</p>
              </div>
            ) : (
              <Accordion type="multiple" defaultValue={rubros.map(r => r.rubroName)}>
                {rubros.map(rubro => (
                  <RubroAccordionItem
                    key={rubro.rubroName}
                    rubro={rubro}
                    currency={currency}
                    selected={selected.get(rubro.rubroName) ?? new Set()}
                    onToggleItem={id => toggleItem(rubro.rubroName, id)}
                    onToggleAll={wasAll => toggleAll(rubro.rubroName, rubro.lineItems.map(li => li.id), wasAll)}
                  />
                ))}
              </Accordion>
            )}
          </div>
        </div>

        {/* Footer */}
        <div className="px-6 py-4 border-t flex-shrink-0 bg-muted/20 space-y-3">
          <div className="flex items-start gap-2">
            <Checkbox
              id="create-project-checkbox"
              checked={createProject}
              onCheckedChange={v => setCreateProject(v === true)}
              className="mt-0.5"
            />
            <div>
              <label htmlFor="create-project-checkbox" className="text-sm font-medium cursor-pointer">
                Crear proyecto automáticamente
              </label>
              <p className="text-xs text-muted-foreground">
                {createProject
                  ? 'Se creará un proyecto con tableros y tareas por defecto'
                  : 'Solo se aprobará el deal, sin crear proyecto ni proceso de cobranza'}
              </p>
            </div>
          </div>
          <div className="flex items-center justify-between gap-4">
            <div className="min-w-0">
              {totalItems > 0 && (
                <p className="text-xs text-muted-foreground">
                  <span className="font-semibold text-foreground">{selectedCount}</span> de {totalItems} líneas seleccionadas
                </p>
              )}
              <p className="text-sm font-bold text-foreground">
                Total: {fmtAmt(grandTotal, currency)}
              </p>
            </div>
            <div className="flex gap-2 flex-shrink-0">
              <Button variant="ghost" onClick={onClose} disabled={approving}>Cancelar</Button>
              <Button onClick={handleApprove} disabled={approving || loading} className="gap-1.5">
                {approving
                  ? <><Loader2 className="w-4 h-4 animate-spin" /> Aprobando...</>
                  : <><CheckCircle2 className="w-4 h-4" /> {createProject ? 'Aprobar y notificar' : 'Aprobar'}</>
                }
              </Button>
            </div>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect, useRef, useCallback, createRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'sonner';
import { useDebouncedCallback } from 'use-debounce';
import { useAuth } from 'zite-auth-sdk';
import { uploadFile } from 'zite-file-upload-sdk';
import { getDocBlocks, saveDocBlock } from 'zite-endpoints-sdk';
import { Skeleton } from '@/components/ui/skeleton';
import { Loader2, CheckCircle2 } from 'lucide-react';
import { formatDistanceToNow } from 'date-fns';
import { es } from 'date-fns/locale';
import ParagraphEditor, { ParagraphEditorHandle } from './ParagraphEditor';
import ImageBlockEditor from './ImageBlockEditor';
import EntityMentionMenu from './EntityMentionMenu';
import {
  DocumentModel, ContentBlock, ParagraphBlock, HeadingBlock, ListItemBlock, ImageBlock,
  TriggerState, RefInline, EntityType,
  generateBlockId, makeEmptyDoc, migrateMarkdownToDoc, mergeAdjacentText,
} from './docTypes';
import { useCollaborativeDocument } from '../../../hooks/useCollaborativeDocument';

type SaveStatus = 'idle' | 'saving' | 'saved';

export default function DocumentCanvas({ dealId }: { dealId: string }) {
  const { user } = useAuth();
  const navigate  = useNavigate();
  const [doc, setDoc] = useState<DocumentModel | null>(null);
  const [blockDbId, setBlockDbId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [status, setStatus] = useState<SaveStatus>('idle');
  const [lastEditedBy, setLastEditedBy] = useState<string | undefined>();
  const [lastEditedAt, setLastEditedAt] = useState<string | undefined>();
  const [focusBlockId, setFocusBlockId] = useState<string | null>(null);
  const [trigger, setTrigger] = useState<TriggerState | null>(null);
  const [uploading, setUploading] = useState(false);
  const [isDragOver, setIsDragOver] = useState(false);
  const triggerBlockId  = useRef<string | null>(null);
  const focusedBlockRef = useRef<string | null>(null);
  const docRef          = useRef<DocumentModel | null>(null);
  const blockDbIdRef    = useRef<string | null>(null);
  const opTypeRef       = useRef<'block_update' | 'structure_update'>('block_update');
  const paraRefs        = useRef<Map<string, React.RefObject<ParagraphEditorHandle>>>(new Map());

  useEffect(() => { docRef.current = doc; }, [doc]);
  useEffect(() => { blockDbIdRef.current = blockDbId; }, [blockDbId]);

  const getParaRef = useCallback((id: string) => {
    if (!paraRefs.current.has(id)) paraRefs.current.set(id, createRef<ParagraphEditorHandle>());
    return paraRefs.current.get(id)!;
  }, []);

  // ── Initial load ─────────────────────────────────────────────────────────
  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      try {
        const data = await getDocBlocks({ dealId });
        if (cancelled) return;
        const block = data.blocks.find(b => b.blockType === 'Texto') ?? data.blocks[0];
        const by = user?.email ?? '';
        if (block) {
          setBlockDbId(block.id);
          blockDbIdRef.current = block.id;
          setLastEditedBy(block.authorName);
          setLastEditedAt(block.updatedAt ?? block.createdAt);
          if (block.documentJson) {
            try {
              const parsed = JSON.parse(block.documentJson) as DocumentModel;
              setDoc(parsed); docRef.current = parsed;
            } catch {
              const migrated = migrateMarkdownToDoc(block.content ?? '', by);
              setDoc(migrated); docRef.current = migrated;
            }
          } else if (block.content) {
            const migrated = migrateMarkdownToDoc(block.content, by);
            setDoc(migrated); docRef.current = migrated;
            await saveDocBlock({ id: block.id, documentJson: JSON.stringify(migrated) });
          } else {
            const empty = makeEmptyDoc(by);
            setDoc(empty); docRef.current = empty;
          }
        } else {
          const empty = makeEmptyDoc(by);
          const created = await saveDocBlock({ dealId, blockType: 'Texto', sortOrder: 0, content: '', documentJson: JSON.stringify(empty) });
          if (!cancelled) {
            setBlockDbId(created.id); blockDbIdRef.current = created.id;
            setDoc(empty); docRef.current = empty;
          }
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    load();
    return () => { cancelled = true; };
  }, [dealId, user?.email]);

  // ── Reload from DB (reconciliation) ──────────────────────────────────────
  const reloadDocument = useCallback(async () => {
    try {
      const data = await getDocBlocks({ dealId });
      const block = data.blocks.find(b => b.blockType === 'Texto') ?? data.blocks[0];
      if (!block?.documentJson) return;
      const parsed = JSON.parse(block.documentJson) as DocumentModel;
      setDoc(parsed);
      docRef.current = parsed;
      if (block.authorName) setLastEditedBy(block.authorName);
      if (block.updatedAt ?? block.createdAt) setLastEditedAt(block.updatedAt ?? block.createdAt);
    } catch { /* silent */ }
  }, [dealId]);

  // ── Collaboration hook ────────────────────────────────────────────────────
  const collab = useCollaborativeDocument({
    docId: blockDbId,
    setDocument: setDoc,
    docRef,
    myUser: user ? { id: user.id, email: user.email, firstName: user.firstName, lastName: user.lastName } : undefined,
    onReloadDocument: reloadDocument,
    enabled: !!blockDbId && !!user,
  });

  // ── Debounced save ────────────────────────────────────────────────────────
  const debouncedSave = useDebouncedCallback(async (jsonStr: string) => {
    const id = blockDbIdRef.current;
    if (!id) return;
    setStatus('saving');
    try {
      const result = await saveDocBlock({
        id,
        documentJson: jsonStr,
        expectedVersion: docRef.current?.version,
        changedBlockId: opTypeRef.current === 'block_update' ? (focusedBlockRef.current ?? undefined) : undefined,
        operationType: opTypeRef.current,
      });

      if (result.conflict) {
        setStatus('idle');
        reloadDocument().catch(() => {});
        return;
      }

      if (result.savedVersion !== undefined) {
        setDoc(prev => prev ? { ...prev, version: result.savedVersion! } : prev);
        if (docRef.current) docRef.current = { ...docRef.current, version: result.savedVersion };
      }

      const name = `${user?.firstName ?? ''} ${user?.lastName ?? ''}`.trim() || user?.email || 'tú';
      setLastEditedBy(name);
      setLastEditedAt(new Date().toISOString());
      setStatus('saved');
    } catch { setStatus('idle'); }
  }, 1500);

  // ── Image helpers ─────────────────────────────────────────────────────────
  const insertImageBlock = useCallback((url: string) => {
    if (!collab.canModifyStructure()) return;
    opTypeRef.current = 'structure_update';
    const imgBlock: ImageBlock    = { id: generateBlockId(), type: 'image', url };
    const newPara: ParagraphBlock = { id: generateBlockId(), type: 'paragraph', content: [] };
    setDoc(prev => {
      if (!prev) return prev;
      const blocks = [...prev.blocks];
      const insertAfterIdx = focusedBlockRef.current
        ? blocks.findIndex(b => b.id === focusedBlockRef.current)
        : blocks.length - 1;
      const idx = insertAfterIdx >= 0 ? insertAfterIdx + 1 : blocks.length;
      blocks.splice(idx, 0, imgBlock, newPara);
      const next = { ...prev, blocks, updatedAt: new Date().toISOString() };
      docRef.current = next;
      debouncedSave(JSON.stringify(next));
      return next;
    });
    setFocusBlockId(newPara.id);
  }, [debouncedSave, collab.canModifyStructure]);

  const handleImageInsert = useCallback(async (file: File) => {
    if (!file.type.startsWith('image/')) return;
    setUploading(true);
    try {
      const { fileUrl } = await uploadFile({ data: file, filename: file.name });
      insertImageBlock(fileUrl);
    } catch { /* silent */ }
    setUploading(false);
  }, [insertImageBlock]);

  const handleDeleteImage = useCallback((id: string) => {
    if (!collab.canModifyStructure()) return;
    opTypeRef.current = 'structure_update';
    setDoc(prev => {
      if (!prev) return prev;
      const next = { ...prev, blocks: prev.blocks.filter(b => b.id !== id), updatedAt: new Date().toISOString() };
      docRef.current = next;
      debouncedSave(JSON.stringify(next));
      return next;
    });
  }, [debouncedSave, collab.canModifyStructure]);

  // ── Block callbacks ───────────────────────────────────────────────────────
  const handleBlockChange = useCallback((updated: ContentBlock) => {
    focusedBlockRef.current = updated.id;
    opTypeRef.current = 'block_update';
    setStatus('idle');
    setDoc(prev => {
      if (!prev) return prev;
      const blocks = prev.blocks.map(b => b.id === updated.id ? updated : b);
      const next = { ...prev, blocks, updatedAt: new Date().toISOString() };
      docRef.current = next;
      debouncedSave(JSON.stringify(next));
      return next;
    });
  }, [debouncedSave]);

  const handleChangeBlockType = useCallback((blockId: string, newType:
    | { type: 'paragraph' }
    | { type: 'heading'; level: 1 | 2 | 3 }
    | { type: 'listItem'; listType: 'bullet' | 'number' }
  ) => {
    focusedBlockRef.current = blockId;
    opTypeRef.current = 'block_update';
    setDoc(prev => {
      if (!prev) return prev;
      const blocks = prev.blocks.map(b => {
        if (b.id !== blockId || b.type === 'image') return b;
        const content = (b as ContentBlock).content;
        if (newType.type === 'paragraph') return { id: b.id, type: 'paragraph', content } as ParagraphBlock;
        if (newType.type === 'heading')   return { id: b.id, type: 'heading',   level: newType.level, content } as HeadingBlock;
        return { id: b.id, type: 'listItem', listType: newType.listType, content } as ListItemBlock;
      });
      const next = { ...prev, blocks, updatedAt: new Date().toISOString() };
      docRef.current = next;
      debouncedSave(JSON.stringify(next));
      return next;
    });
  }, [debouncedSave]);

  const { canModifyStructure } = collab;

  const handleEnter = useCallback((afterId: string) => {
    if (!canModifyStructure()) return;
    opTypeRef.current = 'structure_update';
    const currentBlock = docRef.current?.blocks.find(b => b.id === afterId);

    if (currentBlock?.type === 'listItem') {
      const listBlock = currentBlock as ListItemBlock;
      const contentText = listBlock.content.reduce((s, n) => s + (n.type === 'text' ? n.text : '\u200B'), '').trim();
      if (!contentText) {
        const newPara: ParagraphBlock = { id: afterId, type: 'paragraph', content: [] };
        setDoc(prev => {
          if (!prev) return prev;
          const blocks = prev.blocks.map(b => b.id === afterId ? newPara : b);
          const next = { ...prev, blocks, updatedAt: new Date().toISOString() };
          docRef.current = next;
          debouncedSave(JSON.stringify(next));
          return next;
        });
        return;
      }
      const newId = generateBlockId();
      const newItem: ListItemBlock = { id: newId, type: 'listItem', listType: listBlock.listType, content: [] };
      setDoc(prev => {
        if (!prev) return prev;
        const idx = prev.blocks.findIndex(b => b.id === afterId);
        const blocks = [...prev.blocks];
        blocks.splice(idx + 1, 0, newItem);
        const next = { ...prev, blocks, updatedAt: new Date().toISOString() };
        docRef.current = next;
        debouncedSave(JSON.stringify(next));
        return next;
      });
      setFocusBlockId(newId);
      return;
    }

    const newId = generateBlockId();
    const newBlock: ParagraphBlock = { id: newId, type: 'paragraph', content: [] };
    setDoc(prev => {
      if (!prev) return prev;
      const idx = prev.blocks.findIndex(b => b.id === afterId);
      const blocks = [...prev.blocks];
      blocks.splice(idx + 1, 0, newBlock);
      const next = { ...prev, blocks, updatedAt: new Date().toISOString() };
      docRef.current = next;
      debouncedSave(JSON.stringify(next));
      return next;
    });
    setFocusBlockId(newId);
  }, [debouncedSave, canModifyStructure]);

  const handleBackspace = useCallback((blockId: string) => {
    if (!canModifyStructure()) return;
    opTypeRef.current = 'structure_update';
    const blocks = docRef.current?.blocks;
    if (!blocks || blocks.length <= 1) return;
    const idx = blocks.findIndex(b => b.id === blockId);
    if (idx <= 0) return;
    const prevBlock = blocks[idx - 1];
    const currBlock = blocks[idx];
    if (prevBlock.type === 'image' || currBlock.type === 'image') return;
    const prev = prevBlock as ContentBlock;
    const curr = currBlock as ContentBlock;
    const merged: ContentBlock = { ...prev, content: mergeAdjacentText([...prev.content, ...curr.content]) };
    paraRefs.current.delete(blockId);
    setDoc(d => {
      if (!d) return d;
      const nb = [...d.blocks];
      nb[idx - 1] = merged;
      nb.splice(idx, 1);
      const next = { ...d, blocks: nb, updatedAt: new Date().toISOString() };
      docRef.current = next;
      debouncedSave(JSON.stringify(next));
      return next;
    });
    setFocusBlockId(prevBlock.id);
  }, [debouncedSave, canModifyStructure]);

  const handleTrigger = useCallback((bId: string, state: TriggerState | null) => {
    triggerBlockId.current = state ? bId : null;
    setTrigger(state);
  }, []);

  const handleMentionSelect = useCallback((ref: RefInline) => {
    const bId = triggerBlockId.current;
    if (bId) paraRefs.current.get(bId)?.current?.insertMention(ref);
    setTrigger(null);
    triggerBlockId.current = null;
  }, []);

  const handleDismiss = useCallback(() => {
    setTrigger(null);
    triggerBlockId.current = null;
  }, []);

  const handleChipClick = useCallback((refType: EntityType, _refId: string, label: string) => {
    if (refType === 'project')      navigate('/operacion/proyectos');
    else if (refType === 'user')    toast.info(`@${label}`, { description: 'Persona mencionada en este documento' });
    else if (refType === 'event')   toast.info(`!${label}`, { description: 'Evento mencionado en este documento' });
    else if (refType === 'group')   toast.info(`/${label}`, { description: 'Grupo mencionado en este documento' });
  }, [navigate]);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragOver(false);
    Array.from(e.dataTransfer.files).filter(f => f.type.startsWith('image/')).forEach(f => handleImageInsert(f));
  }, [handleImageInsert]);

  const handlePaste = useCallback((e: React.ClipboardEvent) => {
    const files = Array.from(e.clipboardData.files).filter(f => f.type.startsWith('image/'));
    if (files.length > 0) { e.preventDefault(); files.forEach(f => handleImageInsert(f)); }
  }, [handleImageInsert]);

  // ── Render ────────────────────────────────────────────────────────────────
  let relTime = '';
  try { if (lastEditedAt) relTime = formatDistanceToNow(new Date(lastEditedAt), { addSuffix: true, locale: es }); } catch { /* skip */ }

  if (loading) {
    return (
      <div className="p-6 space-y-2.5">
        <Skeleton className="h-4 w-full" />
        <Skeleton className="h-4 w-4/5" />
        <Skeleton className="h-4 w-3/4" />
      </div>
    );
  }

  if (!doc) return null;

  return (
    <div className="flex flex-col h-full px-6 py-4 gap-3">
      {/* Status bar */}
      <div className="flex items-center justify-between h-5 flex-shrink-0">
        <span className="text-[10px] text-muted-foreground/35 tracking-wide select-none">
          @ personas &nbsp;·&nbsp; # proyectos &nbsp;·&nbsp; ! eventos &nbsp;·&nbsp; / grupos &nbsp;·&nbsp; arrastra imágenes
        </span>
        <span className="flex items-center gap-2">
          {uploading && <span className="flex items-center gap-1.5 text-xs text-muted-foreground"><Loader2 className="w-3 h-3 animate-spin" />Subiendo...</span>}
          {!uploading && status === 'saving' && <span className="flex items-center gap-1.5 text-xs text-muted-foreground"><Loader2 className="w-3 h-3 animate-spin" />Guardando...</span>}
          {!uploading && status === 'saved'  && <span className="flex items-center gap-1.5 text-xs text-chart-2 font-medium"><CheckCircle2 className="w-3 h-3" />Guardado</span>}
          {!uploading && status === 'idle' && lastEditedBy && relTime && (
            <span className="text-xs text-muted-foreground/50">
              Editado por <span className="font-medium text-muted-foreground/70">{lastEditedBy}</span> · {relTime}
            </span>
          )}
        </span>
      </div>

      {/* Collaboration banners */}
      {collab.structureLockOwner && (
        <div className="flex items-center gap-2 px-3 py-1.5 bg-primary/8 border border-primary/15 rounded-lg text-xs text-primary flex-shrink-0">
          <span>✏️ <strong>{collab.structureLockOwner}</strong> está modificando la estructura del documento</span>
        </div>
      )}


      {/* Document surface */}
      <div
        className={`flex-1 overflow-y-auto relative transition-colors ${isDragOver ? 'bg-primary/5 ring-2 ring-inset ring-primary/20' : ''}`}
        onDragOver={e => { e.preventDefault(); setIsDragOver(true); }}
        onDragLeave={() => setIsDragOver(false)}
        onDrop={handleDrop}
        onPaste={handlePaste}
      >
        {doc.blocks.map((block, blockIdx) => {
          if (block.type === 'image') {
            return <ImageBlockEditor key={block.id} block={block} onDelete={handleDeleteImage} />;
          }
          const lockEntry = collab.locks[block.id];
          const isLocked  = !!(lockEntry && lockEntry.expiresAt > Date.now());
          const lockedBy  = isLocked ? { userName: lockEntry.userName, userEmail: lockEntry.userEmail } : null;

          let listIndex: number | undefined;
          if (block.type === 'listItem' && block.listType === 'number') {
            let start = blockIdx;
            while (start > 0 && doc.blocks[start - 1].type === 'listItem' && (doc.blocks[start - 1] as ListItemBlock).listType === 'number') {
              start--;
            }
            listIndex = blockIdx - start + 1;
          }

          return (
            <div key={block.id} onFocus={() => { focusedBlockRef.current = block.id; }}>
              <ParagraphEditor
                ref={getParaRef(block.id)}
                block={block}
                onChange={handleBlockChange}
                onEnter={handleEnter}
                onBackspace={handleBackspace}
                onTrigger={state => handleTrigger(block.id, state)}
                onChipClick={handleChipClick}
                onChangeBlockType={handleChangeBlockType}
                listIndex={listIndex}
                autoFocus={focusBlockId === block.id}
                lockedBy={lockedBy}
                isReadOnly={isLocked}
                onFocusBlock={() => collab.acquireBlockLock(block.id)}
                onBlurBlock={() => collab.releaseBlockLock(block.id)}
              />
            </div>
          );
        })}

        <div
          className="min-h-16 cursor-text"
          onClick={() => {
            const blocks = docRef.current?.blocks;
            if (!blocks?.length) return;
            const lastContent = [...blocks].reverse().find(b => b.type !== 'image');
            if (lastContent) paraRefs.current.get(lastContent.id)?.current?.focus();
          }}
        />
        {isDragOver && (
          <div className="pointer-events-none absolute inset-0 flex items-center justify-center">
            <p className="text-sm text-primary font-medium bg-card/90 px-4 py-2 rounded-xl shadow">Suelta para insertar imagen</p>
          </div>
        )}
      </div>

      <EntityMentionMenu trigger={trigger} onSelect={handleMentionSelect} onDismiss={handleDismiss} />
    </div>
  );
}

import type { Inline, EntityType } from './docTypes';

interface Props {
  content: Inline[];
  onClickRef?: (refType: EntityType, refId: string) => void;
  className?: string;
}

function renderNode(node: Inline, i: number, onClickRef?: (refType: EntityType, refId: string) => void): React.ReactNode {
  if (node.type === 'ref') {
    const isUser = node.refType === 'user';
    return (
      <span
        key={i}
        contentEditable={false}
        onClick={() => onClickRef?.(node.refType, node.refId)}
        className={`inline-flex items-center px-1.5 py-px rounded text-xs font-medium mx-0.5 cursor-pointer select-none align-baseline whitespace-nowrap border ${
          isUser
            ? 'bg-chart-1/10 text-chart-1 border-chart-1/25'
            : 'bg-chart-2/10 text-chart-2 border-chart-2/25'
        }`}
      >
        {isUser ? '@' : '#'}{node.label}
      </span>
    );
  }
  // TextInline — apply marks
  const marks = node.marks ?? [];
  let content: React.ReactNode = node.text;
  if (marks.includes('code'))   content = <code key="code" className="font-mono text-[0.9em] bg-muted px-1 rounded">{content}</code>;
  if (marks.includes('strike')) content = <s key="s">{content}</s>;
  if (marks.includes('italic')) content = <em key="em">{content}</em>;
  if (marks.includes('bold'))   content = <strong key="strong">{content}</strong>;
  return <span key={i}>{content}</span>;
}

export default function InlineRenderer({ content, onClickRef, className }: Props) {
  if (!content.length) return <span className={className} />;
  return (
    <span className={className}>
      {content.map((node, i) => renderNode(node, i, onClickRef))}
    </span>
  );
}

import { useRef, useEffect, forwardRef, useImperativeHandle } from 'react';

export interface TriggerState {
  type: 'user' | 'project';
  query: string;
  rect: DOMRect;
}

export interface MentionWrapperRef {
  insert: (token: string) => void;
}

interface Props {
  children: React.ReactNode;
  onTrigger: (state: TriggerState | null) => void;
}

const MentionWrapper = forwardRef<MentionWrapperRef, Props>(
  function MentionWrapper({ children, onTrigger }, ref) {
    const wrapperRef = useRef<HTMLDivElement>(null);
    const savedRangeRef = useRef<Range | null>(null);
    const onTriggerRef = useRef(onTrigger);

    // Keep ref up to date without re-running effect
    useEffect(() => { onTriggerRef.current = onTrigger; }, [onTrigger]);

    useEffect(() => {
      const wrapper = wrapperRef.current;
      if (!wrapper) return;

      // Input bubbles up from contenteditable naturally
      const handleInput = (e: Event) => {
        const target = e.target as HTMLElement;
        if (!target.isContentEditable) return;

        const sel = window.getSelection();
        if (!sel?.rangeCount) { onTriggerRef.current(null); return; }

        const range = sel.getRangeAt(0);
        const node = range.startContainer;
        if (node.nodeType !== Node.TEXT_NODE) { onTriggerRef.current(null); return; }

        const textBefore = (node.textContent ?? '').slice(0, range.startOffset);
        const match = textBefore.match(/[@#](\w*)$/);

        if (!match) { onTriggerRef.current(null); savedRangeRef.current = null; return; }

        const type = match[0][0] === '@' ? 'user' : 'project';
        const query = match[1];

        // Save range for later insertion
        savedRangeRef.current = range.cloneRange();

        // Get pixel coords of the caret
        const caretRange = range.cloneRange();
        caretRange.collapse(true);
        const rect = caretRange.getBoundingClientRect();

        onTriggerRef.current({ type, query, rect });
      };

      const handleKeyDown = (e: KeyboardEvent) => {
        const target = e.target as HTMLElement;
        if (!target.isContentEditable) return;
        if (e.key === 'Escape' && savedRangeRef.current) {
          onTriggerRef.current(null);
          savedRangeRef.current = null;
        }
      };

      wrapper.addEventListener('input', handleInput);
      wrapper.addEventListener('keydown', handleKeyDown);
      return () => {
        wrapper.removeEventListener('input', handleInput);
        wrapper.removeEventListener('keydown', handleKeyDown);
      };
    }, []);

    useImperativeHandle(ref, () => ({
      insert: (token: string) => {
        const savedRange = savedRangeRef.current;
        if (!savedRange) return;

        const node = savedRange.startContainer;
        if (node.nodeType !== Node.TEXT_NODE) return;

        const textBefore = (node.textContent ?? '').slice(0, savedRange.startOffset);
        const match = textBefore.match(/[@#](\w*)$/);
        if (!match) return;

        const triggerStart = savedRange.startOffset - match[0].length;

        // Focus the contenteditable inside
        const editable = wrapperRef.current?.querySelector(
          '[contenteditable="true"]'
        ) as HTMLElement | null;
        editable?.focus();

        // Select the trigger + query text, then replace via execCommand
        const sel = window.getSelection();
        if (!sel) return;

        const replaceRange = document.createRange();
        replaceRange.setStart(node, triggerStart);
        replaceRange.setEnd(node, savedRange.startOffset);
        sel.removeAllRanges();
        sel.addRange(replaceRange);

        document.execCommand('insertText', false, token + ' ');

        onTriggerRef.current(null);
        savedRangeRef.current = null;
      },
    }));

    return (
      <div ref={wrapperRef} className="contents">
        {children}
      </div>
    );
  }
);

export default MentionWrapper;

import { useMemo } from 'react';
import { Deal, MetricKey, DashboardFilters, DateReference } from '@/lib/commercial-dashboard/types';
import { calcKpi, calcCurrencyBreakdown } from '@/lib/commercial-dashboard/metrics';
import { applyFilters, getPreviousPeriod } from '@/lib/commercial-dashboard/filters';
import { TrendingUp, TrendingDown, Minus } from 'lucide-react';
import { fmtMetric } from './RankingTableWidget';

const KPI_DEFS: { metric: MetricKey; label: string; chartVar: string; wonOnly?: boolean }[] = [
  { metric: 'revenue', label: 'Revenue', chartVar: '--chart-1' },
  { metric: 'dealCount', label: 'Deals ganados', chartVar: '--chart-2', wonOnly: true },
  { metric: 'avgTicket', label: 'Ticket promedio', chartVar: '--chart-3' },
  { metric: 'conversionRate', label: 'Conversión', chartVar: '--chart-4' },
  { metric: 'margin', label: 'Margen bruto', chartVar: '--chart-5' },
];

function fmtCompact(n: number): string {
  if (n >= 1_000_000) return `$${(n / 1_000_000).toFixed(1)}M`;
  if (n >= 1_000) return `$${(n / 1_000).toFixed(0)}K`;
  return `$${n.toFixed(0)}`;
}

interface Props {
  allDeals: Deal[];
  filters: DashboardFilters;
  dateRef: DateReference;
}

export default function KpiCardsRow({ allDeals, filters, dateRef }: Props) {
  const compareMode = filters.compareMode ?? 'previous';
  const current = useMemo(() => applyFilters(allDeals, filters, dateRef), [allDeals, filters, dateRef]);
  const prevPeriod = getPreviousPeriod(filters.period, compareMode);
  const previous = useMemo(
    () => prevPeriod ? applyFilters(allDeals, { ...filters, period: prevPeriod }, dateRef) : null,
    [allDeals, filters, dateRef, prevPeriod]
  );

  const currentWon = current.filter(d => d.phase === 'Ganado');
  const previousWon = previous ? previous.filter(d => d.phase === 'Ganado') : null;

  const breakdown = useMemo(() => calcCurrencyBreakdown(currentWon), [currentWon]);

  return (
    <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-3">
      {KPI_DEFS.map(({ metric, label, chartVar, wonOnly }) => {
        const cur = wonOnly ? currentWon : current;
        const prev = wonOnly ? previousWon : previous;
        const { current: val, changePct } = calcKpi(cur, prev, metric);
        const up = (changePct ?? 0) >= 0;

        return (
          <div key={metric} className="bg-card border rounded-xl p-4 space-y-1">
            <div className="text-xs text-muted-foreground">{label}</div>
            <div className="text-2xl font-bold" style={{ color: `hsl(var(${chartVar}))` }}>
              {fmtMetric(val, metric)}
            </div>
            {changePct !== null ? (
              <div className={`flex items-center gap-1 text-xs font-medium ${up ? 'text-green-600 dark:text-green-400' : 'text-destructive'}`}>
                {up ? <TrendingUp className="w-3 h-3" /> : <TrendingDown className="w-3 h-3" />}
                {up ? '+' : ''}{changePct.toFixed(1)}% {compareMode === 'yoy' ? 'YoY' : 'vs anterior'}
              </div>
            ) : (
              <div className="flex items-center gap-1 text-xs text-muted-foreground">
                <Minus className="w-3 h-3" /> Sin comparación
              </div>
            )}
            {metric === 'revenue' && breakdown.usdDealCount > 0 && (
              <div className="pt-0.5 space-y-0.5">
                <div className="text-[11px] text-muted-foreground leading-tight">
                  MXN {fmtCompact(breakdown.mxnNative)} + USD {fmtCompact(breakdown.usdNative)} (≈{fmtCompact(breakdown.usdConvertedToMxn)} MXN)
                </div>
                {breakdown.missingRates > 0 && (
                  <div className="text-[11px] text-yellow-600 dark:text-yellow-400 leading-tight">
                    ⚠ {breakdown.missingRates} sin TC
                  </div>
                )}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

import { useRef, useEffect, useImperativeHandle, forwardRef, useState } from 'react';
import type {
  ContentBlock, HeadingBlock, ListItemBlock, Inline, EntityType, RefInline, TriggerState, Mark,
} from './docTypes';
import { mergeAdjacentText } from './docTypes';

export interface ParagraphEditorHandle {
  focus: () => void;
  insertMention: (ref: RefInline) => void;
}

type BlockTypeChange =
  | { type: 'paragraph' }
  | { type: 'heading'; level: 1 | 2 | 3 }
  | { type: 'listItem'; listType: 'bullet' | 'number' };

interface Props {
  block: ContentBlock;
  onChange: (block: ContentBlock) => void;
  onEnter: (afterBlockId: string) => void;
  onBackspace: (blockId: string) => void;
  onTrigger: (state: TriggerState | null) => void;
  onChipClick?: (refType: EntityType, refId: string, label: string) => void;
  onChangeBlockType?: (blockId: string, newType: BlockTypeChange) => void;
  listIndex?: number;
  autoFocus?: boolean;
  // Collaboration
  lockedBy?: { userName: string; userEmail: string } | null;
  isReadOnly?: boolean;
  onFocusBlock?: () => void;
  onBlurBlock?: () => void;
}

// ── Styles ──────────────────────────────────────────────────────────────────

let chipStylesInjected = false;
function injectChipStyles() {
  if (chipStylesInjected || document.getElementById('doc-chip-styles')) return;
  chipStylesInjected = true;
  const s = document.createElement('style');
  s.id = 'doc-chip-styles';
  s.textContent = [
    '.mention-chip{display:inline-flex;align-items:center;padding:1px 7px;border-radius:4px;font-size:.85em;font-weight:500;cursor:pointer;user-select:none;vertical-align:baseline;margin:0 1px;white-space:nowrap}',
    '.mention-chip-user{background:hsl(var(--chart-1)/.12);color:hsl(var(--chart-1));border:1px solid hsl(var(--chart-1)/.25)}',
    '.mention-chip-project{background:hsl(var(--chart-2)/.12);color:hsl(var(--chart-2));border:1px solid hsl(var(--chart-2)/.25)}',
    '.mention-chip-event{background:hsl(var(--chart-4)/.12);color:hsl(var(--chart-4));border:1px solid hsl(var(--chart-4)/.25)}',
    '.mention-chip-group{background:hsl(var(--chart-5)/.12);color:hsl(var(--chart-5));border:1px solid hsl(var(--chart-5)/.25)}',
    '[data-para]:empty::before{content:attr(data-ph);color:hsl(var(--muted-foreground)/.4);pointer-events:none}',
  ].join('');
  document.head.appendChild(s);
}

// ── HTML helpers ─────────────────────────────────────────────────────────────

function esc(t: string) {
  return t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const PREFIXES: Record<EntityType, string> = { user: '@', project: '#', event: '!', group: '/' };

function toHTML(content: Inline[]): string {
  return content.map(n => {
    if (n.type === 'ref') {
      return `<span contenteditable="false" data-mention-type="${n.refType}" data-mention-id="${esc(n.refId)}" data-mention-label="${esc(n.label)}" class="mention-chip mention-chip-${n.refType}">${PREFIXES[n.refType] ?? ''}${esc(n.label)}</span>`;
    }
    let html = esc(n.text);
    const marks = n.marks ?? [];
    if (marks.includes('code'))   html = `<code>${html}</code>`;
    if (marks.includes('strike')) html = `<s>${html}</s>`;
    if (marks.includes('italic')) html = `<em>${html}</em>`;
    if (marks.includes('bold'))   html = `<strong>${html}</strong>`;
    return html;
  }).join('');
}

function fromDOMRecursive(node: Node, inherited: Mark[]): Inline[] {
  if (node.nodeType === Node.TEXT_NODE) {
    const text = node.textContent ?? '';
    if (!text) return [];
    const marks = [...inherited].sort() as Mark[];
    return [{ type: 'text', text, ...(marks.length > 0 ? { marks } : {}) }];
  }
  if (!(node instanceof HTMLElement)) return [];
  if (node.dataset.mentionType) {
    return [{ type: 'ref', refType: node.dataset.mentionType as EntityType, refId: node.dataset.mentionId ?? '', label: node.dataset.mentionLabel ?? '' }];
  }
  if (node.tagName === 'BR') {
    const marks = [...inherited].sort() as Mark[];
    return [{ type: 'text', text: '\n', ...(marks.length > 0 ? { marks } : {}) }];
  }
  const marks = [...inherited];
  const tag   = node.tagName.toLowerCase();
  if ((tag === 'strong' || tag === 'b')                  && !marks.includes('bold'))   marks.push('bold');
  if ((tag === 'em'     || tag === 'i')                  && !marks.includes('italic')) marks.push('italic');
  if ((tag === 's' || tag === 'strike' || tag === 'del') && !marks.includes('strike')) marks.push('strike');
  if (tag === 'code'                                     && !marks.includes('code'))   marks.push('code');
  const result: Inline[] = [];
  node.childNodes.forEach(child => result.push(...fromDOMRecursive(child, marks)));
  return result;
}

function fromDOM(el: HTMLElement): Inline[] {
  const result: Inline[] = [];
  el.childNodes.forEach(n => result.push(...fromDOMRecursive(n, [])));
  return mergeAdjacentText(result);
}

function focusAtEnd(el: HTMLElement) {
  el.focus();
  const r = document.createRange();
  r.selectNodeContents(el);
  r.collapse(false);
  window.getSelection()?.removeAllRanges();
  window.getSelection()?.addRange(r);
}

function getContentClass(block: ContentBlock): string {
  const base = 'outline-none py-0.5 break-words w-full';
  if (block.type === 'heading') {
    if (block.level === 1) return `${base} text-2xl font-bold leading-tight`;
    if (block.level === 2) return `${base} text-xl font-bold leading-snug`;
    return `${base} text-lg font-semibold leading-snug`;
  }
  return `${base} text-sm text-foreground leading-relaxed min-h-[1.5em]`;
}

function getPlaceholder(block: ContentBlock): string {
  if (block.type === 'heading')  return `Encabezado ${block.level}`;
  if (block.type === 'listItem') return 'Elemento de lista';
  return 'Escribe aquí...';
}

const TRIGGER_RE = /[@#!/](\w*)$/;
const TRIGGER_CHAR_TO_TYPE: Record<string, TriggerState['type']> = {
  '@': 'user', '#': 'project', '!': 'event', '/': 'group',
};

// ── Toolbar ──────────────────────────────────────────────────────────────────

function TBtn({ children, title, active, onMouseDown, className }: {
  children: React.ReactNode; title: string; active?: boolean;
  onMouseDown: () => void; className?: string;
}) {
  return (
    <button
      type="button"
      title={title}
      onMouseDown={e => { e.preventDefault(); onMouseDown(); }}
      className={`h-5 min-w-[1.25rem] px-1 rounded text-[11px] font-medium flex items-center justify-center transition-colors
        ${active ? 'bg-primary/15 text-primary' : 'text-muted-foreground hover:bg-muted hover:text-foreground'}
        ${className ?? ''}`}
    >
      {children}
    </button>
  );
}

function FormatToolbar({ block, onApplyMark, onChangeType }: {
  block: ContentBlock;
  onApplyMark: (cmd: string) => void;
  onChangeType: (t: BlockTypeChange) => void;
}) {
  const isH    = (l: 1 | 2 | 3) => block.type === 'heading'  && (block as HeadingBlock).level === l;
  const isList = (lt: 'bullet' | 'number') => block.type === 'listItem' && (block as ListItemBlock).listType === lt;
  return (
    <div
      className="absolute top-0 left-0 z-10 flex items-center gap-px h-6 px-1 bg-card border border-border/60 rounded-lg shadow-md"
      onMouseDown={e => e.preventDefault()}
    >
      <TBtn title="Negrita (Ctrl+B)"       onMouseDown={() => onApplyMark('bold')}          className="font-bold">B</TBtn>
      <TBtn title="Cursiva (Ctrl+I)"       onMouseDown={() => onApplyMark('italic')}        className="italic">I</TBtn>
      <TBtn title="Tachado (Ctrl+Shift+X)" onMouseDown={() => onApplyMark('strikeThrough')} className="line-through">S</TBtn>
      <div className="w-px h-3.5 bg-border mx-0.5" />
      <TBtn title="Párrafo"      active={block.type === 'paragraph'} onMouseDown={() => onChangeType({ type: 'paragraph' })}>P</TBtn>
      <TBtn title="Encabezado 1" active={isH(1)} onMouseDown={() => onChangeType({ type: 'heading', level: 1 })}>H1</TBtn>
      <TBtn title="Encabezado 2" active={isH(2)} onMouseDown={() => onChangeType({ type: 'heading', level: 2 })}>H2</TBtn>
      <TBtn title="Encabezado 3" active={isH(3)} onMouseDown={() => onChangeType({ type: 'heading', level: 3 })}>H3</TBtn>
      <div className="w-px h-3.5 bg-border mx-0.5" />
      <TBtn title="Lista"          active={isList('bullet')} onMouseDown={() => onChangeType({ type: 'listItem', listType: 'bullet' })}>•</TBtn>
      <TBtn title="Lista numerada" active={isList('number')} onMouseDown={() => onChangeType({ type: 'listItem', listType: 'number' })}>1.</TBtn>
    </div>
  );
}

// ── ParagraphEditor ───────────────────────────────────────────────────────────

const ParagraphEditor = forwardRef<ParagraphEditorHandle, Props>(
  function ParagraphEditor({
    block, onChange, onEnter, onBackspace, onTrigger, onChipClick, onChangeBlockType,
    listIndex, autoFocus,
    lockedBy, isReadOnly = false, onFocusBlock, onBlurBlock,
  }, ref) {
    const divRef   = useRef<HTMLDivElement>(null);
    const hasFocus = useRef(false);
    const [focused, setFocused] = useState(false);
    const cb = useRef({ onChange, onTrigger, onEnter, onBackspace, onChipClick, onChangeBlockType, block });
    cb.current = { onChange, onTrigger, onEnter, onBackspace, onChipClick, onChangeBlockType, block };

    useEffect(() => { injectChipStyles(); }, []);

    useEffect(() => {
      if (!hasFocus.current && divRef.current) {
        divRef.current.innerHTML = toHTML(block.content);
      }
    }, [block]);

    useEffect(() => {
      if (autoFocus && divRef.current) focusAtEnd(divRef.current);
    }, [autoFocus]);

    useImperativeHandle(ref, () => ({
      focus: () => { if (divRef.current) focusAtEnd(divRef.current); },
      insertMention: (mRef: RefInline) => {
        const el = divRef.current;
        if (!el) return;
        const sel = window.getSelection();
        if (!sel?.rangeCount) return;
        const range = sel.getRangeAt(0);
        const node  = range.startContainer;
        if (node.nodeType !== Node.TEXT_NODE) return;
        const before = (node.textContent ?? '').slice(0, range.startOffset);
        const match  = before.match(TRIGGER_RE);
        if (!match) return;

        const prefix = PREFIXES[mRef.refType] ?? '';
        const span   = document.createElement('span');
        span.setAttribute('contenteditable', 'false');
        span.setAttribute('data-mention-type',  mRef.refType);
        span.setAttribute('data-mention-id',    mRef.refId);
        span.setAttribute('data-mention-label', mRef.label);
        span.className   = `mention-chip mention-chip-${mRef.refType}`;
        span.textContent = prefix + mRef.label;
        const space = document.createTextNode('\u00A0');

        const rng = document.createRange();
        rng.setStart(node, range.startOffset - match[0].length);
        rng.setEnd(node, range.startOffset);
        rng.deleteContents();
        const frag = document.createDocumentFragment();
        frag.appendChild(span);
        frag.appendChild(space);
        rng.insertNode(frag);

        const nr = document.createRange();
        nr.setStartAfter(space);
        nr.collapse(true);
        sel.removeAllRanges();
        sel.addRange(nr);

        cb.current.onChange({ ...cb.current.block, content: fromDOM(el) } as ContentBlock);
        cb.current.onTrigger(null);
      },
    }), []);

    const syncFromDOM = () => {
      const el = divRef.current;
      if (!el) return;
      cb.current.onChange({ ...cb.current.block, content: fromDOM(el) } as ContentBlock);
    };

    const applyMark = (command: string) => {
      document.execCommand(command, false);
      syncFromDOM();
    };

    const changeType = (newType: BlockTypeChange) => {
      syncFromDOM();
      cb.current.onChangeBlockType?.(cb.current.block.id, newType);
    };

    const handleInput = () => {
      syncFromDOM();
      const sel = window.getSelection();
      if (!sel?.rangeCount) { cb.current.onTrigger(null); return; }
      const range = sel.getRangeAt(0);
      const node  = range.startContainer;
      if (node.nodeType !== Node.TEXT_NODE) { cb.current.onTrigger(null); return; }
      const before = (node.textContent ?? '').slice(0, range.startOffset);
      const match  = before.match(TRIGGER_RE);
      if (!match) { cb.current.onTrigger(null); return; }
      const type = TRIGGER_CHAR_TO_TYPE[match[0][0]];
      if (!type) { cb.current.onTrigger(null); return; }
      const caretRng = range.cloneRange();
      caretRng.collapse(true);
      cb.current.onTrigger({ type, query: match[1], rect: caretRng.getBoundingClientRect() });
    };

    const handleClick = (e: React.MouseEvent) => {
      const chip = (e.target as HTMLElement).closest('.mention-chip') as HTMLElement | null;
      if (!chip) return;
      const refType = chip.dataset.mentionType as EntityType | undefined;
      if (refType) cb.current.onChipClick?.(refType, chip.dataset.mentionId ?? '', chip.dataset.mentionLabel ?? '');
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
      const meta = e.ctrlKey || e.metaKey;
      if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        e.stopPropagation();
        syncFromDOM();
        cb.current.onEnter(cb.current.block.id);
      } else if (e.key === 'Backspace') {
        const el = divRef.current;
        if (el && (el.textContent ?? '').length === 0) {
          e.preventDefault();
          cb.current.onBackspace(cb.current.block.id);
        }
      } else if (meta && !e.shiftKey && e.key === 'b') {
        e.preventDefault(); e.stopPropagation(); applyMark('bold');
      } else if (meta && !e.shiftKey && e.key === 'i') {
        e.preventDefault(); e.stopPropagation(); applyMark('italic');
      } else if (meta && e.shiftKey && (e.key === 'x' || e.key === 'X')) {
        e.preventDefault(); e.stopPropagation(); applyMark('strikeThrough');
      }
    };

    const handlePaste = (e: React.ClipboardEvent) => {
      const files = Array.from(e.clipboardData.files).filter(f => f.type.startsWith('image/'));
      if (files.length > 0) return;
      const text = e.clipboardData.getData('text/plain');
      if (text) {
        e.preventDefault();
        document.execCommand('insertText', false, text);
        syncFromDOM();
      }
    };

    const isListItem = block.type === 'listItem';
    const listType   = isListItem ? (block as ListItemBlock).listType : null;

    const editDiv = (
      <div
        ref={divRef}
        contentEditable={!isReadOnly}
        suppressContentEditableWarning
        data-para
        data-ph={getPlaceholder(block)}
        onFocus={() => {
          hasFocus.current = true;
          setFocused(true);
          onFocusBlock?.();
        }}
        onBlur={() => {
          hasFocus.current = false;
          setFocused(false);
          onBlurBlock?.();
        }}
        onInput={handleInput}
        onKeyDown={handleKeyDown}
        onClick={handleClick}
        onPaste={handlePaste}
        className={`${getContentClass(block)} ${isReadOnly ? 'cursor-not-allowed opacity-70' : ''}`}
      />
    );

    return (
      <div className={`relative ${focused && !isReadOnly ? 'pt-7' : ''} ${lockedBy ? 'border-l-2 border-chart-1 pl-2' : ''}`}>
        {/* Lock badge — shown when another user is editing */}
        {lockedBy && (
          <span className="text-[10px] text-chart-1 font-medium mb-0.5 flex items-center gap-1 select-none">
            <span>✏️</span> {lockedBy.userName} está editando
          </span>
        )}
        {/* Format toolbar — only when focused and not read-only */}
        {focused && !isReadOnly && (
          <FormatToolbar block={block} onApplyMark={applyMark} onChangeType={changeType} />
        )}
        {isListItem ? (
          <div className="flex items-start gap-2">
            <span className="text-sm text-muted-foreground leading-relaxed mt-0.5 select-none w-5 text-right flex-shrink-0">
              {listType === 'bullet' ? '•' : `${listIndex ?? 1}.`}
            </span>
            <div className="flex-1 min-w-0">{editDiv}</div>
